      const u = new Uri('download:' + (i.getStringExtra(Intent.EXTRA_TITLE) || 'file')); u.name = i.getStringExtra(Intent.EXTRA_TITLE) || 'file'; u.mime = i.type;
      const data = new Intent(); data.data = u;
      setTimeout(() => from.onActivityResult(req, RESULT_OK, data), 0);
      return;
