/** Relative times ("5 minutes ago"). */
const DateUtils = {
  MINUTE_IN_MILLIS: 60000, HOUR_IN_MILLIS: 3600000, DAY_IN_MILLIS: 86400000, WEEK_IN_MILLIS: 604800000, FORMAT_ABBREV_RELATIVE: 0x40000,
  getRelativeTimeSpanString(t, now, min) {
    now = now || Date.now(); const d = now - t; const a = Math.abs(d);
    const f = (n, u) => n + ' ' + u + (n === 1 ? '' : 's') + (d >= 0 ? ' ago' : '');
    if (a < 60000) return 'Just now';
    if (a < 3600000) return f(Math.floor(a / 60000), 'minute');
    if (a < 86400000) return f(Math.floor(a / 3600000), 'hour');
    if (a < 7 * 86400000) return f(Math.floor(a / 86400000), 'day');
    return LocalDate.ofEpochDay(Math.floor((t + 19800000) / 86400000)).format(DateTimeFormatter.ofPattern('d MMM yyyy'));
  },
  isToday(t) { return LocalDate.ofEpochDay(Math.floor((t + 19800000) / 86400000)).equals(LocalDate.now()); }
};

