/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Dates are stored as ISO yyyy-MM-dd strings and shown as dd-MM-yyyy. */
class Dates {
  /** Index 1..7 is Monday..Sunday, matching DayOfWeek.getValue(); 0 means every day. */
  static DAYS = ["Every day", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

  static NICE = DateTimeFormatter.ofPattern("dd-MM-yyyy", Locale.ENGLISH);
  static LONG = DateTimeFormatter.ofPattern("EEEE, dd MMM yyyy", Locale.ENGLISH);
  static SHORT = DateTimeFormatter.ofPattern("dd MMM", Locale.ENGLISH);
  static MONTH = DateTimeFormatter.ofPattern("MMMM yyyy", Locale.ENGLISH);
  static HM = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);

  static today() { return LocalDate.now(); }

  static todayIso() { return LocalDate.now().toString(); }

  static now() { return LocalTime.now().format(Dates.HM); }

  /** Admission day and PG call duty change over at 7:30 AM. */
  static CHANGEOVER = LocalTime.of(7, 30);
  /** Tests pin the clock here; null means the phone's time. */
  static fixedTime = null;

  static time() { return Dates.fixedTime != null ? Dates.fixedTime : LocalTime.now(); }

  /**
   * The admission day (or call duty day) running now: Monday's M1 admission day runs from 7:30 AM Monday
   * to 7:30 AM Tuesday, so before 7:30 AM it is still yesterday's.
   */
  static admitDay() { return Dates.time().isBefore(Dates.CHANGEOVER) ? Dates.today().minusDays(1) : Dates.today(); }

  static parse(s) {
    try { return LocalDate.parse(s); } catch (e) { return null; }
  }

  /** nice(String iso) or nice(LocalDate d). */
  static nice(x) {
    if (x instanceof LocalDate) return x.format(Dates.NICE);
    const d = Dates.parse(x);
    return d == null ? Ui.nz(x) : d.format(Dates.NICE);
  }

  static longFmt(d) { return d.format(Dates.LONG); }

  static shortFmt(d) { return d.format(Dates.SHORT); }

  static month(d) { return d.format(Dates.MONTH); }

  static dow(d) { return d.getDayOfWeek().getValue(); }

  static weekStart(d) {
    return d.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));
  }

  static monthStart(d) { return d.withDayOfMonth(1); }

  static saturdayAnchor(anchor) {
    if (anchor == null) anchor = LocalDate.of(2026, 1, 3);
    return anchor.with(TemporalAdjusters.nextOrSame(DayOfWeek.SATURDAY));
  }

  /** Journal club runs on alternate Saturdays counted from the anchor Saturday in settings. */
  static isJournalClubDay(d, anchor) {
    if (d.getDayOfWeek() !== DayOfWeek.SATURDAY) return false;
    return ChronoUnit.DAYS.between(Dates.saturdayAnchor(anchor), d) % 14 === 0;
  }

  static nextJournalClub(from, anchor) {
    const s = from.with(TemporalAdjusters.nextOrSame(DayOfWeek.SATURDAY));
    return Dates.isJournalClubDay(s, anchor) ? s : s.plusWeeks(1);
  }

  static weekday(weekStart, day) {
    return weekStart.with(TemporalAdjusters.nextOrSame(day));
  }
}
;
