  static WARD_UNITS = ["M1", "M2", "M3", "M4", "M5", "M6", "M7"];
  /** Wards that admit every day and hold patients for a parent unit. */
  static SPECIAL = [Db.TAEI, Db.TRIAGE, Db.STEPDOWN, Db.IMCU, Db.FEVER, Db.CCB, Db.IDW, Db.GERI, Db.RHEUM];
  /** The special wards as an SQL list, for location IN … */
  static SPECIAL_SQL = "('TAEI','TRIAGE','STEPDOWN','IMCU','FEVER','CCB','IDW','GERI','RHEUM')";
  /** Every ward at TVMCH run by the department. */
