'use strict';
/** Frosted-glass look: 3D glass icon tiles, the soft colour backdrop behind every screen, and glassy cards. */
class Glass {
  /** Two bright tones from one colour: a lighter, warmer top and a deeper, richer bottom. Greys stay grey. */
  static vivid(color) {
    const hsv = [0, 0, 0];
    Color.colorToHSV(color, hsv);
    if (hsv[1] < 0.18) return [Ui.mix(color, Color.WHITE, 0.25), Ui.mix(color, Color.BLACK, 0.2), Ui.mix(color, Color.BLACK, 0.45)];
    const top = [(hsv[0] + 345) % 360, Math.min(1, hsv[1] * 0.78 + 0.12), 1];
    const bot = [(hsv[0] + 22) % 360, Math.min(1, hsv[1] * 0.9 + 0.15), Math.max(0.62, hsv[2] * 0.92)];
    const base = [bot[0], Math.min(1, bot[1] + 0.05), bot[2] * 0.62];
    return [Color.HSVToColor(top), Color.HSVToColor(bot), Color.HSVToColor(base)];
  }

  /** Frosted white panel with a bright hairline rim. */
  static panel(c, radiusDp) {
    const g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, [0xF7FFFFFF, 0xE8FFFFFF]);
    g.setCornerRadius(Ui.dp(c, radiusDp));
    g.setStroke(Math.max(1, Ui.dp(c, 1)), 0xFFFFFFFF);
    return g;
  }

  /** A coloured gradient with a frosted sheen across the top and a light rim, for hero cards and ward headers. */
  static hero(c, colors, radiusDp) {
    const base = new GradientDrawable(GradientDrawable.Orientation.TL_BR, colors);
    base.setCornerRadius(Ui.dp(c, radiusDp));
    const sheen = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, [0x38FFFFFF, 0x0AFFFFFF, 0x00FFFFFF]);
    sheen.setCornerRadius(Ui.dp(c, radiusDp));
    const rim = new GradientDrawable();
    rim.setColor(0x00000000);
    rim.setCornerRadius(Ui.dp(c, radiusDp));
    rim.setStroke(Math.max(1, Ui.dp(c, 1)), 0x59FFFFFF);
    return new LayerDrawable([base, sheen, rim]);
  }

  /** Light frosted chip on a coloured background (stat strips, date badge). */
  static frost(c, radiusDp) {
    const g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, [0x40FFFFFF, 0x1FFFFFFF]);
    g.setCornerRadius(Ui.dp(c, radiusDp));
    g.setStroke(Math.max(1, Ui.dp(c, 1)), 0x4DFFFFFF);
    return g;
  }

  /** A soft round glow of one colour (behind the chosen tab's gem). */
  static halo(color) {
    return new (class extends Drawable {
      constructor() { super(); this.p = new Paint(Paint.ANTI_ALIAS_FLAG); }
      draw(cv) {
        const b = this.getBounds();
        const rr = Math.min(b.width(), b.height()) / 2;
        this.p.setShader(new RadialGradient(b.exactCenterX(), b.exactCenterY(), rr,
          [Ui.alpha(Ui.mix(color, Color.WHITE, 0.25), 0xCC), Ui.alpha(color, 0x55), color & 0x00FFFFFF], [0, 0.55, 1], Shader.TileMode.CLAMP));
        cv.drawCircle(b.exactCenterX(), b.exactCenterY(), rr, this.p);
      }
      setAlpha(a) {}
      setColorFilter(cf) {}
      getOpacity() { return PixelFormat.TRANSLUCENT; }
    })();
  }

  /** A clear glass capsule behind the open tab. */
  static lens(c) {
    const g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, [0x8CFFFFFF, 0x40FFFFFF, 0x73FFFFFF]);
    g.setCornerRadius(Ui.dp(c, 24));
    g.setStroke(Math.max(1, Ui.dp(c, 1)), 0x5938BDF8);
    return g;
  }

  /** Pink of the crystal glass heart: light, middle and deep. */
  static HEART = [0xFFFF8FB6, 0xFFEC4F87, 0xFFC0245E];

  /** Tints the elevation shadow so glass panels cast a soft, cool shadow instead of a grey one. */
  static softShadow(v, color) {
    if (Build.VERSION.SDK_INT >= 28) {
      v.setOutlineAmbientShadowColor(color);
      v.setOutlineSpotShadowColor(color);
    }
  }
}

/** A glyph drawable (R.drawable.ic_*) copied and tinted one colour. */
function glassTint(g, color) {
  const d = g.getConstantState().newDrawable().mutate();
  d.setColorFilter(new PorterDuffColorFilter(color, PorterDuff.Mode.SRC_IN));
  return d;
}

/** A raised, glossy 3D glass tile in bright two-tone colour, with the glyph embossed in white on top. */
Glass.Icon = class extends Drawable {
  constructor(c, color, glyphRes) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    /** Draw a framed border (white inner ring, deep coloured outer line) around the tile. */
    this.border = false;
    this.tones = Glass.vivid(color);
    this.density = c.getResources().getDisplayMetrics().density;
    const g = !glyphRes ? null : c.getResources().getDrawable(glyphRes, null);
    if (g != null) {
      this.glyph = g.getConstantState().newDrawable().mutate();
      this.glyph.setColorFilter(new PorterDuffColorFilter(Color.WHITE, PorterDuff.Mode.SRC_IN));
      this.glyphShadow = g.getConstantState().newDrawable().mutate();
      this.glyphShadow.setColorFilter(new PorterDuffColorFilter(Ui.alpha(this.tones[2], 0x99), PorterDuff.Mode.SRC_IN));
    } else {
      this.glyph = this.glyphShadow = null;
    }
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, tones = this.tones;
    const d = this.density;
    const lift = Math.max(2.5 * d, b.height() * 0.06);     // thickness of the raised edge
    const drop = lift + 3 * d;                              // room for the shadow
    const r = new RectF(b.left + 2 * d, b.top + d, b.right - 2 * d, b.bottom - drop);
    const rad = r.width() * 0.3;
    p.setStyle(Paint.Style.FILL);

    // soft coloured shadow on the surface below
    p.setShader(null);
    for (let i = 5; i >= 1; i--) {
      p.setColor(Ui.alpha(tones[1], 0x0C + (5 - i) * 0x07));
      const s = new RectF(r.left + i * 0.5 * d, r.top + lift + i * d, r.right - i * 0.5 * d, r.bottom + lift + i * 0.8 * d);
      cv.drawRoundRect(s, rad, rad, p);
    }
    // raised side (the extruded edge that makes it look like a thick glass block)
    p.setColor(0xFF000000);
    p.setShader(new LinearGradient(0, r.top + lift, 0, r.bottom + lift, [tones[2], Ui.mix(tones[2], Color.BLACK, 0.25)], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(new RectF(r.left, r.top + lift, r.right, r.bottom + lift), rad, rad, p);

    // face: bright two-tone gradient
    p.setShader(new LinearGradient(r.left, r.top, r.left + r.width() * 0.65, r.bottom,
      [tones[0], tones[1]], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);

    cv.save();
    this.clip.reset();
    this.clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(this.clip);
    // inner glow from the bottom, like light passing through glass
    p.setShader(new RadialGradient(r.centerX(), r.bottom + r.height() * 0.15, r.width() * 0.7,
      [Ui.alpha(Ui.mix(tones[0], Color.WHITE, 0.3), 0x8C), 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(r, p);
    // curved gloss across the top half
    const gloss = new RectF(r.left - r.width() * 0.35, r.top - r.height() * 0.62, r.right + r.width() * 0.35, r.top + r.height() * 0.5);
    p.setShader(new LinearGradient(0, r.top, 0, gloss.bottom, [0xB3FFFFFF, 0x33FFFFFF, 0x0DFFFFFF], [0, 0.7, 1], Shader.TileMode.CLAMP));
    cv.drawOval(gloss, p);
    // sparkle, top left
    const gx = r.left + r.width() * 0.24, gy = r.top + r.height() * 0.16, gr = r.width() * 0.2;
    p.setShader(new RadialGradient(gx, gy, gr, [0xCCFFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawCircle(gx, gy, gr, p);
    // darker rim at the bottom inside the face
    p.setShader(new LinearGradient(0, r.bottom - r.height() * 0.22, 0, r.bottom, [0x00000000, 0x2E000000], null, Shader.TileMode.CLAMP));
    cv.drawRect(r.left, r.bottom - r.height() * 0.22, r.right, r.bottom, p);
    cv.restore();

    // bright glass rim
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1.3 * d);
    p.setShader(new LinearGradient(0, r.top, 0, r.bottom, [0xF2FFFFFF, 0x33FFFFFF, 0x80FFFFFF], [0, 0.55, 1], Shader.TileMode.CLAMP));
    cv.drawRoundRect(new RectF(r.left + 0.65 * d, r.top + 0.65 * d, r.right - 0.65 * d, r.bottom - 0.65 * d), rad, rad, p);
    if (this.border) {
      p.setShader(null);
      p.setStrokeWidth(1.3 * d);
      p.setColor(Ui.mix(tones[1], Color.BLACK, 0.12));
      cv.drawRoundRect(new RectF(r.left - 0.8 * d, r.top - 0.8 * d, r.right + 0.8 * d, r.bottom + lift + 0.8 * d), rad, rad, p);
      p.setStrokeWidth(1.8 * d);
      p.setColor(0xF2FFFFFF);
      cv.drawRoundRect(new RectF(r.left + 1.6 * d, r.top + 1.6 * d, r.right - 1.6 * d, r.bottom - 1.6 * d), rad * 0.85, rad * 0.85, p);
    }
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);

    // embossed white glyph with a coloured drop shadow
    if (this.glyph != null) {
      const gs = toInt(r.width() * 0.52);
      const gl = toInt(r.centerX() - gs / 2), gt = toInt(r.centerY() - gs / 2);
      const off = Math.max(1, toInt(1.6 * d));
      this.glyphShadow.setBounds(gl, gt + off, gl + gs, gt + gs + off);
      this.glyphShadow.draw(cv);
      this.glyph.setBounds(gl, gt, gl + gs, gt + gs);
      this.glyph.draw(cv);
    }
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** The calm wallpaper behind every screen: soft colour glows on a pale base, like a blurred photo behind frosted glass. */
Glass.Backdrop = class extends Drawable {
  constructor() { super(); this.p = new Paint(Paint.ANTI_ALIAS_FLAG); }

  draw(cv) {
    const b = this.getBounds();
    const w = b.width(), h = b.height();
    this.p.setShader(new LinearGradient(0, 0, 0, h, [0xFFF1F3FD, 0xFFF6F4FB, 0xFFF0F7FA], null, Shader.TileMode.CLAMP));
    cv.drawRect(b, this.p);
    this.glow(cv, w * 0.05, h * 0.10, w * 0.75, 0x3D60A5FA);
    this.glow(cv, w * 0.98, h * 0.22, w * 0.65, 0x3338BDF8);
    this.glow(cv, w * 0.10, h * 0.62, w * 0.70, 0x26FBBF24);
    this.glow(cv, w * 0.95, h * 0.88, w * 0.80, 0x2E2DD4BF);
    this.p.setShader(null);
  }

  glow(cv, x, y, r, c) {
    this.p.setShader(new RadialGradient(x, y, r, [c, c & 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawCircle(x, y, r, this.p);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.OPAQUE; }
};

/** The bottom tab bar: clear, very light water glass with ripples, caustic light and a pastel tint under each tab. */
Glass.TabBar = class extends Drawable {
  constructor(c, colors, active) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    this.wave = new Path();
    this.colors = colors;
    this.active = active;
    this.density = c.getResources().getDisplayMetrics().density;
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, colors = this.colors;
    const d = this.density;
    const r = new RectF(b.left + d, b.top + d, b.right - d, b.bottom - d);
    const rad = Math.min(r.height() / 2, 30 * d);
    p.setStyle(Paint.Style.FILL);
    // clear water: almost white with a hint of aqua, a touch deeper at the bottom
    p.setShader(new LinearGradient(0, r.top, 0, r.bottom, [0xF2FFFFFF, 0xE6F2FBFF, 0xE0E3F5FB], [0, 0.55, 1], Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);
    cv.save();
    this.clip.reset();
    this.clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(this.clip);
    // a faint pastel of each tab's colour in the water under it, the chosen one a little stronger
    const n = colors == null ? 0 : colors.length;
    for (let i = 0; i < n; i++) {
      const x = r.left + r.width() * (i + 0.5) / n;
      const on = i === this.active;
      const rr = r.width() / n * (on ? 0.95 : 0.6);
      const c = Ui.alpha(colors[i], on ? 0x33 : 0x14);
      p.setShader(new RadialGradient(x, r.bottom, rr, [c, c & 0x00FFFFFF], null, Shader.TileMode.CLAMP));
      cv.drawCircle(x, r.bottom, rr, p);
    }
    p.setShader(null);
    // ripples: soft wavy lines of light and shade drifting across, like the surface of water
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeCap(Paint.Cap.ROUND);
    const waves = [[0.16, 0.9, 0.0, 2.2], [0.36, 1.3, 1.7, 1.4], [0.94, 1.1, 3.1, 1.6]];
    const waveColors = [0xD9FFFFFF, 0x2E0EA5E9, 0x29FFFFFF];
    for (let wi = 0; wi < waves.length; wi++) {
      const w = waves[wi];
      const y0 = r.top + r.height() * w[0], amp = r.height() * 0.05, k = Math.PI * 2 * w[1] / r.width();
      this.wave.reset();
      for (let x = r.left; x <= r.right; x += 4 * d) {
        const y = y0 + amp * Math.sin(k * (x - r.left) + w[2]);
        if (x === r.left) this.wave.moveTo(x, y); else this.wave.lineTo(x, y);
      }
      p.setColor(waveColors[wi]);
      p.setStrokeWidth(w[3] * d);
      cv.drawPath(this.wave, p);
    }
    p.setStyle(Paint.Style.FILL);
    // caustic sparkles where light focuses in the water
    const spots = [[0.12, 0.70, 10], [0.37, 0.22, 7], [0.63, 0.80, 9], [0.86, 0.30, 8], [0.50, 0.50, 12]];
    for (const s0 of spots) {
      const x = r.left + r.width() * s0[0], y = r.top + r.height() * s0[1], rr = s0[2] * d;
      p.setShader(new RadialGradient(x, y, rr, [0x99FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
      cv.drawCircle(x, y, rr, p);
    }
    // glassy shine across the top
    p.setShader(new LinearGradient(0, r.top, 0, r.top + r.height() * 0.45, [0xE6FFFFFF, 0x40FFFFFF, 0x00FFFFFF], [0, 0.5, 1], Shader.TileMode.CLAMP));
    cv.drawRect(r.left, r.top, r.right, r.top + r.height() * 0.45, p);
    cv.restore();
    // pure glass edge: a crisp white rim inside a fine aqua line
    p.setStyle(Paint.Style.STROKE);
    p.setShader(null);
    p.setStrokeWidth(1.2 * d);
    p.setColor(0x6638BDF8);
    cv.drawRoundRect(r, rad, rad, p);
    p.setStrokeWidth(1.6 * d);
    p.setShader(new LinearGradient(0, r.top, 0, r.bottom, [0xFFFFFFFF, 0x99FFFFFF, 0xE6FFFFFF], [0, 0.6, 1], Shader.TileMode.CLAMP));
    cv.drawRoundRect(new RectF(r.left + 1.6 * d, r.top + 1.6 * d, r.right - 1.6 * d, r.bottom - 1.6 * d), rad - 1.6 * d, rad - 1.6 * d, p);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** A colourless 3D glass tile, like clear glass etched with the glyph (in the style of the newest iPhone icons). */
Glass.ClearIcon = class extends Drawable {
  constructor(c, glyphRes, on) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    this.density = c.getResources().getDisplayMetrics().density;
    this.on = on;
    const g = c.getResources().getDrawable(glyphRes, null);
    this.glyph = Glass.ClearIcon.tint(g, on ? 0xFF0F2A4A : 0xFF475569);
    this.light = Glass.ClearIcon.tint(g, 0xE6FFFFFF);
    this.shade = Glass.ClearIcon.tint(g, 0x40000000);
  }

  static tint(g, color) {
    return glassTint(g, color);
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, on = this.on, clip = this.clip;
    const d = this.density;
    const r = new RectF(b.left + 2 * d, b.top + 2 * d, b.right - 2 * d, b.bottom - 3 * d);
    const rad = r.width() * 0.32;
    p.setStyle(Paint.Style.FILL);
    // a faint contact shadow just below the glass (kept outside it, so the glass stays clear)
    cv.save();
    clip.reset();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipOutPath(clip);
    for (let i = 3; i >= 1; i--) {
      p.setColor(0x0F0F172A);
      cv.drawRoundRect(new RectF(r.left + i * d, r.top + (i + 1) * d, r.right - i * d, r.bottom + i * d), rad, rad, p);
    }
    cv.restore();
    // clear body: nearly transparent, a little brighter at the top
    p.setShader(new LinearGradient(0, r.top, 0, r.bottom, [on ? 0x8CFFFFFF : 0x66FFFFFF, on ? 0x40FFFFFF : 0x26FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);
    cv.save();
    clip.reset();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    // light bending through the thick glass: bright lower edge, soft inner shade under the top rim
    p.setShader(new LinearGradient(0, r.bottom - r.height() * 0.3, 0, r.bottom, [0x00FFFFFF, 0x99FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(r.left, r.bottom - r.height() * 0.3, r.right, r.bottom, p);
    // curved specular sheen across the top
    const gloss = new RectF(r.left - r.width() * 0.2, r.top - r.height() * 0.55, r.right + r.width() * 0.2, r.top + r.height() * 0.42);
    p.setShader(new LinearGradient(0, r.top, 0, gloss.bottom, [0xB3FFFFFF, 0x26FFFFFF, 0x00FFFFFF], [0, 0.7, 1], Shader.TileMode.CLAMP));
    cv.drawOval(gloss, p);
    cv.restore();
    // glass edges: a fine dark outline for depth, then a bright rim that catches light top-left and bottom-right
    p.setShader(null);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1 * d);
    p.setColor(on ? 0x4D0F2A4A : 0x2E0F172A);
    cv.drawRoundRect(r, rad, rad, p);
    p.setStrokeWidth(1.5 * d);
    p.setShader(new LinearGradient(r.left, r.top, r.right, r.bottom, [0xFFFFFFFF, 0x33FFFFFF, 0xE6FFFFFF], [0, 0.5, 1], Shader.TileMode.CLAMP));
    cv.drawRoundRect(new RectF(r.left + 1.4 * d, r.top + 1.4 * d, r.right - 1.4 * d, r.bottom - 1.4 * d), rad - 1.4 * d, rad - 1.4 * d, p);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    // the glyph, etched into the glass: soft shadow below, white light above, then the glyph itself
    const gs = toInt(r.width() * 0.5);
    const gl = toInt(r.centerX() - gs / 2), gt = toInt(r.centerY() - gs / 2);
    const o = Math.max(1, toInt(1.2 * d));
    this.shade.setBounds(gl, gt + o, gl + gs, gt + gs + o);
    this.shade.draw(cv);
    this.light.setBounds(gl, gt - o, gl + gs, gt + gs - o);
    this.light.draw(cv);
    this.glyph.setBounds(gl, gt, gl + gs, gt + gs);
    this.glyph.draw(cv);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** A see-through glass tile (square, slightly rounded corners): clear in the middle, bright towards the rim, with a white symbol (like a lock-screen keypad). */
Glass.Bubble = class extends Drawable {
  constructor(c, glyphRes, on) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    this.density = c.getResources().getDisplayMetrics().density;
    this.on = on;
    const g = c.getResources().getDrawable(glyphRes, null);
    this.glyph = g.getConstantState().newDrawable().mutate();
    this.glyph.setColorFilter(new PorterDuffColorFilter(Color.WHITE, PorterDuff.Mode.SRC_IN));
    this.shadow = g.getConstantState().newDrawable().mutate();
    this.shadow.setColorFilter(new PorterDuffColorFilter(0x590F172A, PorterDuff.Mode.SRC_IN));
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, on = this.on, clip = this.clip;
    const d = this.density;
    const cx = b.exactCenterX(), cy = b.exactCenterY();
    const rr = Math.min(b.width(), b.height()) / 2 - 1.5 * d;
    const r = new RectF(cx - rr, cy - rr, cx + rr, cy + rr);
    const rad = rr * 0.5;   // a square with slightly rounded corners
    p.setStyle(Paint.Style.FILL);
    // the body: clear in the centre, frosted white towards the edge, as in a block of glass
    p.setShader(null);
    p.setColor(on ? 0x40FFFFFF : 0x14FFFFFF);
    cv.drawRoundRect(r, rad, rad, p);
    cv.save();
    clip.reset();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    p.setStyle(Paint.Style.STROKE);
    const edge = on ? [0x8CFFFFFF, 0x66FFFFFF, 0x4DFFFFFF, 0x33FFFFFF, 0x1FFFFFFF, 0x0FFFFFFF] : [0x73FFFFFF, 0x52FFFFFF, 0x38FFFFFF, 0x24FFFFFF, 0x14FFFFFF, 0x08FFFFFF];
    for (let k = 0; k < edge.length; k++) {
      const inn = (k + 0.5) * 1.3 * d;
      p.setStrokeWidth(1.5 * d);
      p.setColor(edge[k]);
      cv.drawRoundRect(new RectF(r.left + inn, r.top + inn, r.right - inn, r.bottom - inn), Math.max(0, rad - inn), Math.max(0, rad - inn), p);
    }
    p.setStyle(Paint.Style.FILL);
    // light caught on the upper left and lower right
    p.setShader(new RadialGradient(cx - rr * 0.5, cy - rr * 0.55, rr * 0.8, [0x66FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(r, p);
    p.setShader(new RadialGradient(cx + rr * 0.55, cy + rr * 0.6, rr * 0.55, [0x40FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(r, p);
    cv.restore();
    // crisp glass rim
    p.setShader(null);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1.3 * d);
    p.setShader(new LinearGradient(r.left, r.top, r.right, r.bottom, [0xFFFFFFFF, 0x99FFFFFF, 0xF2FFFFFF], null, Shader.TileMode.CLAMP));
    const h = 0.6 * d;
    cv.drawRoundRect(new RectF(r.left + h, r.top + h, r.right - h, r.bottom - h), rad - h, rad - h, p);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    // white symbol with a soft shade so it reads on any colour
    const gs = toInt(rr * 1.0);
    const gl = toInt(cx - gs / 2), gt = toInt(cy - gs / 2);
    const o = Math.max(1, toInt(1.2 * d));
    this.shadow.setBounds(gl, gt + o, gl + gs, gt + gs + o);
    this.shadow.draw(cv);
    this.glyph.setBounds(gl, gt, gl + gs, gt + gs);
    this.glyph.draw(cv);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/**
 * A crystal-clear glass icon in the tile's own colour: deep colour like tinted water, a glossy reflection,
 * a bold border with a white crystal edge, a white symbol and tiny glitter stars.
 */
Glass.Gem = class extends Drawable {
  /** Where the little stars sit (x, y as a share of the icon) and how big each is. */
  static STARS = [[0.2, 0.19, 1.0], [0.79, 0.24, 0.75], [0.64, 0.11, 0.5], [0.85, 0.7, 0.6],
    [0.17, 0.74, 0.55], [0.42, 0.86, 0.4], [0.33, 0.3, 0.35]];

  constructor(c, glyphRes, color) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.path = new Path();
    this.density = c.getResources().getDisplayMetrics().density;
    this.color = color;
    const g = c.getResources().getDrawable(glyphRes, null);
    this.glyph = g.getConstantState().newDrawable().mutate();
    this.glyph.setColorFilter(new PorterDuffColorFilter(Color.WHITE, PorterDuff.Mode.SRC_IN));
    this.shade = g.getConstantState().newDrawable().mutate();
    this.shade.setColorFilter(new PorterDuffColorFilter(Ui.alpha(Ui.mix(color, Color.BLACK, 0.55), 0x99), PorterDuff.Mode.SRC_IN));
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, color = this.color, path = this.path;
    const d = this.density;
    const cx = b.exactCenterX(), cy = b.exactCenterY();
    const rr = Math.min(b.width(), b.height()) / 2 - 2.5 * d;
    const rad = rr * 0.5;
    const r = new RectF(cx - rr, cy - rr - d, cx + rr, cy + rr - d);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    // soft coloured shadow and the block's thickness underneath
    for (let k = 3; k >= 1; k--) {
      p.setColor(Ui.alpha(Ui.mix(color, Color.BLACK, 0.35), 0x14 * (4 - k)));
      const o = k * d;
      cv.drawRoundRect(new RectF(r.left + o * 0.4, r.top + o * 1.8, r.right - o * 0.4, r.bottom + o * 1.8), rad, rad, p);
    }
    p.setColor(Ui.mix(color, Color.BLACK, 0.3));
    cv.drawRoundRect(new RectF(r.left, r.top + 2.2 * d, r.right, r.bottom + 2.2 * d), rad, rad, p);
    // the colour seen through clear glass: bright and deep, like coloured water
    p.setShader(new LinearGradient(0, r.top, 0, r.bottom, [Ui.mix(color, Color.WHITE, 0.3), color, Ui.mix(color, Color.BLACK, 0.2)],
      null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);
    cv.save();
    path.reset();
    path.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(path);
    // light gathered at the bottom, as in a drop of water
    p.setShader(new RadialGradient(cx, r.bottom, rr * 1.1, [0x66FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(r, p);
    // the glossy reflection over the top half
    const gloss = new RectF(r.left + 2.2 * d, r.top + 2 * d, r.right - 2.2 * d, cy - rr * 0.02);
    p.setShader(new LinearGradient(0, gloss.top, 0, gloss.bottom, [0xD9FFFFFF, 0x40FFFFFF, 0x0DFFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(gloss, rad * 0.85, rad * 0.85, p);
    // a small bright glint on the lower right
    p.setShader(null);
    p.setColor(0x8CFFFFFF);
    cv.drawOval(new RectF(cx + rr * 0.42, cy + rr * 0.5, cx + rr * 0.72, cy + rr * 0.66), p);
    cv.restore();
    // a bold border: the colour deepened on the outside, a white crystal edge inside it
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(2.2 * d);
    p.setColor(Ui.mix(color, Color.BLACK, 0.35));
    cv.drawRoundRect(r, rad, rad, p);
    p.setStrokeWidth(1.5 * d);
    const h = 1.9 * d;
    p.setShader(new LinearGradient(r.left, r.top, r.right, r.bottom, [0xFFFFFFFF, 0x99FFFFFF, 0xE6FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(new RectF(r.left + h, r.top + h, r.right - h, r.bottom - h), rad - h, rad - h, p);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    // the white symbol, with a shade of the colour under it
    const gs = toInt(rr * 1.05);
    const gl = toInt(cx - gs / 2), gt = toInt(cy - gs / 2 - d);
    const o = Math.max(1, toInt(1.2 * d));
    this.shade.setBounds(gl, gt + o, gl + gs, gt + gs + o);
    this.shade.draw(cv);
    this.glyph.setBounds(gl, gt, gl + gs, gt + gs);
    this.glyph.draw(cv);
    // tiny twinkling stars of glitter
    for (const s of Glass.Gem.STARS) this.star(cv, r.left + r.width() * s[0], r.top + r.height() * s[1], (1.2 + 2.4 * s[2]) * d);
  }

  /** A four-pointed sparkle with a soft glow. */
  star(cv, x, y, size) {
    const p = this.p, path = this.path;
    p.setShader(new RadialGradient(x, y, size * 1.3, [0x99FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawCircle(x, y, size * 1.3, p);
    p.setShader(null);
    p.setColor(Color.WHITE);
    const w = size * 0.22;
    path.reset();
    path.moveTo(x, y - size);
    path.quadTo(x + w, y - w, x + size, y);
    path.quadTo(x + w, y + w, x, y + size);
    path.quadTo(x - w, y + w, x - size, y);
    path.quadTo(x - w, y - w, x, y - size);
    path.close();
    cv.drawPath(path, p);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/**
 * A crystal glass app icon: a rounded square of milky tinted glass with a thick rainbow-edged rim, and the symbol
 * itself moulded in clear coloured glass with an iridescent outline, a glossy top and a soft shadow.
 */
Glass.Crystal = class extends Drawable {
  static RAINBOW = [0xFFFF9EC7, 0xFFFFE08A, 0xFF9EF5C8, 0xFF8ADCFF, 0xFFC9A8FF, 0xFFFF9EC7];

  /** Crystal(c, glyphRes, color), or Crystal(c, color): just the glass square with its rainbow rim, for content laid on top (the ward census tiles). */
  constructor(c, glyphRes, color) {
    super();
    if (arguments.length === 2) { color = glyphRes; glyphRes = 0; }
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.rim = null; this.body = null; this.gloss = null; this.shadow = null; this.frame = null;
    this.size = -1;
    this.density = c.getResources().getDisplayMetrics().density;
    this.color = color;
    this.glyph = !glyphRes ? null : c.getResources().getDrawable(glyphRes, null).getConstantState().newDrawable().mutate();
  }

  /** The symbol drawn as a mask (scaled about its centre) and filled with a shader. */
  fill(gs, scale, shader, solid) {
    const b = Bitmap.createBitmap(gs, gs, Bitmap.Config.ARGB_8888);
    const c = new Canvas(b);
    const inn = toInt(gs * (1 - scale) / 2);
    this.glyph.setColorFilter(new PorterDuffColorFilter(Color.WHITE, PorterDuff.Mode.SRC_IN));
    this.glyph.setBounds(inn, inn, gs - inn, gs - inn);
    this.glyph.draw(c);
    const f = new Paint(Paint.ANTI_ALIAS_FLAG);
    f.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_IN));
    if (shader != null) f.setShader(shader);
    else f.setColor(solid);
    c.drawRect(0, 0, gs, gs, f);
    return b;
  }

  build(gs) {
    const color = this.color;
    this.size = gs;
    this.rim = this.fill(gs, 1, new SweepGradient(gs / 2, gs / 2, Glass.Crystal.RAINBOW, null), 0);
    this.body = this.fill(gs, 0.84, new LinearGradient(0, 0, gs * 0.6, gs, [Ui.mix(color, Color.WHITE, 0.7), Ui.mix(color, Color.WHITE, 0.3),
      Ui.mix(color, Color.WHITE, 0.05)], null, Shader.TileMode.CLAMP), 0);
    this.gloss = this.fill(gs, 0.84, new LinearGradient(0, gs * 0.12, 0, gs * 0.58, [0xE6FFFFFF, 0x55FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP), 0);
    this.shadow = this.fill(gs, 1, null, Ui.alpha(Ui.mix(color, Color.BLACK, 0.45), 0x55));
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, color = this.color;
    const d = this.density;
    const cx = b.exactCenterX(), cy = b.exactCenterY();
    const half = Math.min(b.width(), b.height()) / 2 - 2 * d;
    const rad = half * 0.5;
    const r = new RectF(cx - half, cy - half - d, cx + half, cy + half - d);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    // soft shadow under the glass
    for (let k = 3; k >= 1; k--) {
      p.setColor(Ui.alpha(Ui.mix(color, Color.BLACK, 0.4), 0x0E * (4 - k)));
      const o = k * d;
      cv.drawRoundRect(new RectF(r.left + o * 0.5, r.top + o * 1.6, r.right - o * 0.5, r.bottom + o * 1.6), rad, rad, p);
    }
    // milky glass tinted with the colour, deepening towards the bottom
    p.setColor(Ui.mix(color, Color.WHITE, 0.82));
    cv.drawRoundRect(r, rad, rad, p);
    cv.save();
    const clip = new Path();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    const bands = 24;
    for (let i = 0; i < bands; i++) {
      p.setColor(Ui.alpha(color, 0x04));
      cv.drawRect(r.left, r.top + r.height() * (0.35 + 0.65 * i / bands), r.right, r.bottom, p);
    }
    // light falling on the upper glass
    for (let i = 0; i < bands; i++) {
      p.setColor(0x07FFFFFF);
      cv.drawRect(r.left, r.top, r.right, r.top + r.height() * 0.55 * (1 - i / bands), p);
    }
    cv.restore();
    // the thick glass rim: rainbow refraction round the edge, a white inner edge, a deeper line outside
    const rw = 3.4 * d;
    if (this.frame == null || this.frame.getWidth() !== toInt(Math.ceil(r.width())) || this.frame.getHeight() !== toInt(Math.ceil(r.height()))) {
      const fw = toInt(Math.ceil(r.width())), fh = toInt(Math.ceil(r.height()));
      this.frame = Bitmap.createBitmap(fw, fh, Bitmap.Config.ARGB_8888);
      const fc = new Canvas(this.frame);
      const fp = new Paint(Paint.ANTI_ALIAS_FLAG);
      fp.setStyle(Paint.Style.STROKE);
      fp.setStrokeWidth(rw);
      fp.setColor(Color.WHITE);
      fc.drawRoundRect(new RectF(rw / 2, rw / 2, fw - rw / 2, fh - rw / 2), rad - rw / 2, rad - rw / 2, fp);
      const fill = new Paint(Paint.ANTI_ALIAS_FLAG);
      fill.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_IN));
      fill.setShader(new SweepGradient(fw / 2, fh / 2, Glass.Crystal.RAINBOW, null));
      fc.drawRect(0, 0, fw, fh, fill);
    }
    p.setAlpha(0xFF);
    cv.drawBitmap(this.frame, r.left, r.top, p);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1.1 * d);
    p.setColor(0xCCFFFFFF);
    const e = rw + 0.4 * d;
    const re = new RectF(r.left + e, r.top + e, r.right - e, r.bottom - e);
    cv.drawRoundRect(re, rad - e, rad - e, p);
    p.setStrokeWidth(0.9 * d);
    p.setColor(Ui.alpha(Ui.mix(color, Color.BLACK, 0.3), 0x66));
    cv.drawRoundRect(r, rad, rad, p);
    // a bright curved highlight along the top-left corner of the rim
    p.setStrokeWidth(1.6 * d);
    p.setColor(0xF2FFFFFF);
    p.setStrokeCap(Paint.Cap.ROUND);
    const c2 = (rad - e) * 2;
    cv.drawArc(new RectF(re.left, re.top, re.left + c2, re.top + c2), 195, 60, false, p);
    p.setStrokeCap(Paint.Cap.BUTT);
    p.setStyle(Paint.Style.FILL);
    if (this.glyph == null) return;
    // the symbol in clear coloured glass: iridescent outline, see-through body, glossy top
    const gs = toInt(half * 1.42);
    if (gs !== this.size) this.build(gs);
    const gl = cx - gs / 2, gt = cy - gs / 2 - d;
    p.setAlpha(0xFF);
    cv.drawBitmap(this.shadow, gl + 0.6 * d, gt + 2 * d, p);
    cv.drawBitmap(this.rim, gl, gt, p);
    p.setAlpha(0xC4);
    cv.drawBitmap(this.body, gl, gt, p);
    p.setAlpha(0xFF);
    cv.drawBitmap(this.gloss, gl, gt - 0.5 * d, p);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/**
 * Text moulded in clear coloured liquid glass, like the crystal heart icon: a light-to-deep fill, an iridescent
 * rainbow outline, a glossy upper half and a soft coloured shadow. Shrinks to fit its width.
 */
Glass.LiquidText = class extends View {
  static RAINBOW = [0xFFFF9EC7, 0xFFFFE08A, 0xFF9EF5C8, 0xFF8ADCFF, 0xFFC9A8FF, 0xFFFF9EC7];

  constructor(c, text, sizeSp, tone) {
    super(c);
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.text = text;
    this.size = sizeSp * c.getResources().getDisplayMetrics().scaledDensity;
    this.tone = tone;
    this.p.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
    this.p.setTextAlign(Paint.Align.CENTER);
    this.setContentDescription(text);
  }

  onMeasure(ws, hs) {
    this.p.setTextSize(this.size);
    const w = this.p.measureText(this.text) + this.size * 0.3;
    this.setMeasuredDimension(View.resolveSize(toInt(w), ws), View.resolveSize(toInt(this.size * 1.25), hs));
  }

  /** The text drawn as a white mask, then filled with a shader (shaders on text do not render everywhere). */
  layer(cv, cx, base, stroke, width, shader, solid) {
    const p = this.p;
    const b = Bitmap.createBitmap(this.getWidth(), this.getHeight(), Bitmap.Config.ARGB_8888);
    const c = new Canvas(b);
    p.setShader(null);
    p.setColor(Color.WHITE);
    p.setStyle(stroke ? Paint.Style.STROKE : Paint.Style.FILL);
    p.setStrokeWidth(width);
    p.setStrokeJoin(Paint.Join.ROUND);
    c.drawText(this.text, cx, base, p);
    const f = new Paint(Paint.ANTI_ALIAS_FLAG);
    f.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_IN));
    if (shader != null) f.setShader(shader); else f.setColor(solid);
    c.drawRect(0, 0, this.getWidth(), this.getHeight(), f);
    cv.drawBitmap(b, 0, 0, null);
    b.recycle();
  }

  onDraw(cv) {
    if (this.getWidth() <= 0 || this.getHeight() <= 0) return;
    const p = this.p, text = this.text, tone = this.tone;
    const d = this.getContext().getResources().getDisplayMetrics().density;
    let ts = this.size;
    p.setTextSize(ts);
    const fit = this.getWidth() - 10 * d;
    if (p.measureText(text) > fit) ts = ts * fit / p.measureText(text);
    p.setTextSize(ts);
    const cx = this.getWidth() / 2;
    const base = this.getHeight() / 2 - (p.descent() + p.ascent()) / 2;
    const tb = new Rect();
    p.getTextBounds(text, 0, text.length, tb);
    const top = base + tb.top, bot = base + tb.bottom;
    // soft coloured shadow under the glass
    cv.save();
    cv.translate(0.6 * d, 2.2 * d);
    this.layer(cv, cx, base, false, 0, null, Ui.alpha(tone[2], 0x4D));
    cv.restore();
    // the iridescent rim of the glass
    this.layer(cv, cx, base, true, Math.max(1.4 * d, ts * 0.07), new SweepGradient(cx, (top + bot) / 2, Glass.LiquidText.RAINBOW, null), 0);
    // the clear coloured body, light at the top and deep at the bottom
    this.layer(cv, cx, base, false, 0, new LinearGradient(0, top, 0, bot, [tone[0], tone[1], tone[2]], null, Shader.TileMode.CLAMP), 0);
    // a thin white inner edge and the glossy upper half
    this.layer(cv, cx, base, true, 0.8 * d, null, 0x59FFFFFF);
    this.layer(cv, cx, base, false, 0, new LinearGradient(0, top, 0, top + (bot - top) * 0.5, [0xA6FFFFFF, 0x26FFFFFF, 0x00FFFFFF],
      [0, 0.55, 1], Shader.TileMode.CLAMP), 0);
  }
};

/**
 * A square that keeps its height equal to its width.
 * (Java overrides onMeasure(ws, ws); in the browser the same is done with CSS aspect-ratio, so no onMeasure here.)
 */
Glass.Square = class extends LinearLayout {
  constructor(c) {
    super(c);
    this.setOrientation(LinearLayout.VERTICAL);
    this.el.style.aspectRatio = '1 / 1';
  }
};

/**
 * A raised block of tinted glass for a tile: the tile's soft colour, a frosted inner edge, light across the top,
 * a crisp white rim and a deeper coloured lip underneath for thickness.
 */
Glass.Block = class extends Drawable {
  constructor(c, color, radiusDp, depthDp) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    this.density = c.getResources().getDisplayMetrics().density;
    this.color = color;
    this.radius = radiusDp * this.density;
    this.depth = depthDp * this.density;
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, color = this.color, radius = this.radius, depth = this.depth, clip = this.clip;
    const d = this.density;
    const face = new RectF(b.left, b.top, b.right, b.bottom - depth);
    // the lip: the same glass seen from the side, a deeper shade of the colour
    p.setStyle(Paint.Style.FILL);
    p.setShader(new LinearGradient(0, b.top, 0, b.bottom, [Ui.mix(color, Color.WHITE, 0.45), Ui.mix(color, Color.WHITE, 0.25)],
      null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(new RectF(b.left, b.top + depth, b.right, b.bottom), radius, radius, p);
    // the face: the soft tint as before, a little clearer at the top
    p.setShader(new LinearGradient(0, face.top, 0, face.bottom, [Ui.mix(color, Color.WHITE, 0.92), Ui.mix(color, Color.WHITE, 0.74)],
      null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(face, radius, radius, p);
    cv.save();
    clip.reset();
    clip.addRoundRect(face, radius, radius, Path.Direction.CW);
    cv.clipPath(clip);
    // frosted inner edge, as in a slab of glass
    p.setShader(null);
    p.setStyle(Paint.Style.STROKE);
    const edge = [0x99FFFFFF, 0x66FFFFFF, 0x40FFFFFF, 0x24FFFFFF, 0x10FFFFFF];
    for (let k = 0; k < edge.length; k++) {
      const inn = (k + 0.5) * 1.4 * d;
      p.setStrokeWidth(1.6 * d);
      p.setColor(edge[k]);
      cv.drawRoundRect(new RectF(face.left + inn, face.top + inn, face.right - inn, face.bottom - inn), Math.max(0, radius - inn), Math.max(0, radius - inn), p);
    }
    p.setStyle(Paint.Style.FILL);
    // light across the upper half and a glint on the upper left
    p.setShader(new LinearGradient(0, face.top, 0, face.top + face.height() * 0.55, [0x8CFFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(face.left, face.top, face.right, face.top + face.height() * 0.55, p);
    const gr = Math.min(face.width(), face.height()) * 0.9;
    p.setShader(new RadialGradient(face.left + gr * 0.25, face.top + gr * 0.12, gr * 0.6, [0x73FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(face, p);
    // a faint colour glow on the lower right, light passing through the tint
    p.setShader(new RadialGradient(face.right - gr * 0.2, face.bottom, gr * 0.7, [Ui.alpha(color, 0x2E), 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(face, p);
    cv.restore();
    // crisp rim: bright white at the top left, the tile's colour at the bottom right
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1.3 * d);
    p.setShader(new LinearGradient(face.left, face.top, face.right, face.bottom,
      [0xFFFFFFFF, 0xCCFFFFFF, Ui.mix(color, Color.WHITE, 0.4)], null, Shader.TileMode.CLAMP));
    const h = 0.65 * d;
    cv.drawRoundRect(new RectF(face.left + h, face.top + h, face.right - h, face.bottom - h), radius - h, radius - h, p);
    // and a clear coloured outline so the block's edge stands out
    p.setShader(null);
    p.setStrokeWidth(1.4 * d);
    p.setColor(Ui.alpha(Ui.mix(color, Color.WHITE, 0.2), 0xB3));
    cv.drawRoundRect(new RectF(b.left + 0.7 * d, b.top + 0.7 * d, b.right - 0.7 * d, b.bottom - 0.7 * d), radius, radius, p);
    p.setStyle(Paint.Style.FILL);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** A soft blurred wallpaper of warm peach and sky blue, for glass bubbles to show through. */
Glass.Wallpaper = class extends Drawable {
  constructor(c) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    this.density = c.getResources().getDisplayMetrics().density;
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, clip = this.clip;
    const d = this.density;
    const r = new RectF(b.left + d, b.top + d, b.right - d, b.bottom - d);
    const rad = Math.min(r.height() / 2, 30 * d);
    cv.save();
    clip.reset();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    p.setStyle(Paint.Style.FILL);
    p.setShader(new LinearGradient(r.left, r.top, r.right, r.bottom, [0xFFFFB866, 0xFFF59A3A, 0xFF2D8CF0], [0, 0.5, 1], Shader.TileMode.CLAMP));
    cv.drawRect(r, p);
    this.blob(cv, r.left + r.width() * 0.66, r.top - r.height() * 0.05, r.height() * 1.3, 0xF21A73E8);
    this.blob(cv, r.left + r.width() * 0.42, r.bottom + r.height() * 0.2, r.height() * 0.9, 0xB3B9D7F5);
    this.blob(cv, r.left + r.width() * 0.08, r.top, r.height() * 1.0, 0xCCFFC27A);
    this.blob(cv, r.left + r.width() * 0.97, r.bottom, r.height() * 0.9, 0xCCF59A3A);
    // glassy shine across the top
    p.setShader(new LinearGradient(0, r.top, 0, r.top + r.height() * 0.5, [0x66FFFFFF, 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawRect(r.left, r.top, r.right, r.top + r.height() * 0.5, p);
    cv.restore();
    p.setShader(null);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1.4 * d);
    p.setColor(0xCCFFFFFF);
    cv.drawRoundRect(new RectF(r.left + 0.7 * d, r.top + 0.7 * d, r.right - 0.7 * d, r.bottom - 0.7 * d), rad, rad, p);
    p.setStyle(Paint.Style.FILL);
  }

  blob(cv, x, y, r, c) {
    this.p.setShader(new RadialGradient(x, y, r, [c, c & 0x00FFFFFF], null, Shader.TileMode.CLAMP));
    cv.drawCircle(x, y, r, this.p);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};
