'use strict';
/** Builds labelled input fields and reads their values back by key. */
class Form {
  // interface OnChange { void changed(String value); }  — callers pass { changed: (value) => … }

  static TEXT = InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_WORDS;
  static PLAIN = InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES;
  static NUMBER = InputType.TYPE_CLASS_NUMBER;
  static DECIMAL = InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_FLAG_DECIMAL;
  static PHONE = InputType.TYPE_CLASS_PHONE;

  constructor(c) {
    this.c = c;
    this.view = Ui.v(c);
    /** The headings added so far (10.34: the admission form's section cards take their place). */
    this.headings = [];
    this.fields = new JMap();
    this.boxes = new JMap();
    /** Field labels in the order shown, and the allowed values of choice fields (for the Copilot, 8.90). */
    this.labels = new LinkedHashMap();
    this.options = new JMap();
    /** Where new fields go: the form itself, or a row of two while a row is open. */
    this.row = null;
    /** Ticks in a row of colour bands; consecutive ticks share one wrapping row. */
    this.tickFlow = null;
    this.ticks = 0;
  }

  box(key, label) {
    const c = this.c;
    const b = Ui.v(c);
    b.setPadding(0, Ui.dp(c, 10), 0, 0);
    if (label != null) b.addView(Ui.tv(c, label, 13, Ui.MUTED, true));
    if (this.row != null) {
      const p = Ui.weight(1);
      if (this.row.getChildCount() > 0) p.leftMargin = Ui.dp(c, 12);
      this.row.addView(b, p);
    } else {
      this.view.addView(b, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    }
    this.boxes.put(key, b);
    if (label != null || !this.labels.containsKey(key)) this.labels.put(key, Ui.nz(label));
    return b;
  }

  heading(s) {
    const t = Ui.tv(this.c, s, 16, Ui.PRIMARY, true);
    t.setPadding(0, Ui.dp(this.c, 18), 0, 0);
    this.view.addView(t);
    this.headings.add(t);
  }

  /** Fields added until endRow() sit side by side. */
  beginRow() {
    this.row = Ui.h(this.c);
    this.row.setBaselineAligned(false);
    this.view.addView(this.row, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
  }

  endRow() {
    // a lone field keeps half the width
    if (this.row != null && this.row.getChildCount() === 1) {
      const p = Ui.weight(1);
      p.leftMargin = Ui.dp(this.c, 12);
      this.row.addView(new View(this.c), p);
    }
    this.row = null;
  }

  /**
   * A row of tappable options (Yes / No, Regular / Irregular). Tapping the chosen one again clears it.
   * Values are the options themselves; "" means not recorded.
   * segment(key, label, options, selected[, normal[, onChange]]): "normal" is the reassuring answer (shown green),
   * any other answer shows red; onChange is told each time the answer changes (and once when the form is built).
   */
  segment(key, label, options, selected, normal, onChange) {
    return this.bands(key, label, options, options, selected, normal == null ? null : normal, onChange == null ? null : onChange);
  }

  /** Labels that only mean "nothing chosen": such an option is not shown as a band. */
  static blankLabel(l) {
    const x = l.trim();
    return x.isEmpty() || x === "–" || x === "-" || x.equalsIgnoreCase("Not recorded") || x.equalsIgnoreCase("Not set");
  }

  /**
   * Single choice as colour bands with the words on them. Short pairs (Yes / No) share the row equally;
   * longer lists wrap. Each option has its own colour, or green / red when a normal answer is given.
   */
  bands(key, label, labels, values, selected, normal, onChange) {
    const c = this.c;
    const b = this.box(key, label);
    this.options.put(key, values);
    let clearable = false;
    let n = 0, len = 0;
    for (let i = 0; i < values.length; i++) {
      if (values[i].isEmpty() && Form.blankLabel(labels[i])) {
        clearable = true;
        continue;
      }
      n++;
      len = Math.max(len, labels[i].length);
    }
    const even = n <= 2 && len <= 14 || n === 3 && len <= 9;
    const group = even ? Ui.h(c) : new Bands.Flow(c);
    const current = [Ui.nz(selected)];
    group.setTag(current[0]);
    const canClear = clearable;
    let k = 0;
    for (let i = 0; i < values.length; i++) {
      if (values[i].isEmpty() && Form.blankLabel(labels[i])) continue;
      const v = values[i];
      const t = new TextView(c);
      t.setText(labels[i]);
      Bands.padBand(c, t);
      t.setTag(v);
      t.setTag(R.id.tag_state, normal == null ? Bands.color(k) : normal === v ? Ui.GREEN : 0xFFDC2626);
      k++;
      if (even) {
        // equal shares of the row: shrink the letters rather than cut them off
        t.setGravity(Gravity.CENTER);
        t.setMaxLines(1);
        t.setPadding(Ui.dp(c, 4), Ui.dp(c, 8), Ui.dp(c, 4), Ui.dp(c, 8));
        t.setAutoSizeTextTypeUniformWithConfiguration(10, 14, 1, TypedValue.COMPLEX_UNIT_SP);
      }
      t.setOnClickListener({
        onClick: (x) => {
          const now = v === group.getTag() && canClear ? "" : v;
          this.paintBands(group, now);
          if (onChange != null) onChange.changed(now);
        }
      });
      if (even) {
        const p = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1);
        if (group.getChildCount() > 0) p.leftMargin = Ui.dp(c, 8);
        group.addView(t, p);
      } else {
        group.addView(t);
      }
    }
    const p = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    p.topMargin = Ui.dp(c, 6);
    b.addView(group, p);
    this.paintBands(group, current[0]);
    this.fields.put(key, group);
    if (onChange != null) {
      // like a drop-down, report the starting value once the whole form is built
      group.post({ run: () => { onChange.changed(Ui.nz(group.getTag())); } });
    }
    return group;
  }

  paintBands(group, value) {
    group.setTag(value);
    for (let i = 0; i < group.getChildCount(); i++) {
      const t = group.getChildAt(i);
      Bands.paint(this.c, t, t.getTag(R.id.tag_state), t.getTag() === value);
    }
  }

  text(key, label, value, type) {
    const b = this.box(key, label);
    const e = new EditText(this.c);
    e.setInputType(type);
    e.setText(Ui.nz(value));
    e.setTextSize(16);
    e.setTextColor(Ui.TEXT);
    b.addView(e);
    this.fields.put(key, e);
    return e;
  }

  multi(key, label, value) {
    const e = this.text(key, label, value, Form.PLAIN | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
    e.setMinLines(2);
    e.setSingleLine(false);
    return e;
  }

  suggest(key, label, value, options) {
    const b = this.box(key, label);
    const e = new AutoCompleteTextView(this.c);
    e.setInputType(Form.TEXT);
    e.setThreshold(1);
    e.setText(Ui.nz(value));
    e.setTextSize(16);
    e.setAdapter(new ArrayAdapter(this.c, ANDROID_R.layout.simple_dropdown_item_1line, options));
    b.addView(e);
    this.fields.put(key, e);
    return e;
  }

  pickerField(key, label) {
    const c = this.c;
    const b = this.box(key, label);
    const t = Ui.tv(c, "", 16, Ui.TEXT, false);
    t.setBackground(Ui.outline(c, Ui.CARD, Ui.LINE, 8));
    t.setPadding(Ui.dp(c, 12), Ui.dp(c, 10), Ui.dp(c, 12), Ui.dp(c, 10));
    const p = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    p.topMargin = Ui.dp(c, 4);
    b.addView(t, p);
    this.fields.put(key, t);
    Ui.ripple(t, Ui.alpha(Ui.PRIMARY, 0x22));
    return t;
  }

  date(key, label, iso) {
    const t = this.pickerField(key, label);
    Form.setDate(t, iso == null || iso.isEmpty() ? Dates.todayIso() : iso);
    t.setOnClickListener({
      onClick: (v) => {
        let d = Dates.parse(t.getTag());
        if (d == null) d = Dates.today();
        new DatePickerDialog(this.c, {
          onDateSet: (p, y, m, day) => {
            Form.setDate(t, LocalDate.of(y, m + 1, day).toString());
          }
        }, d.getYear(), d.getMonthValue() - 1, d.getDayOfMonth()).show();
      }
    });
    return t;
  }

  /** A date that may be left empty; long-press clears it. */
  optionalDate(key, label, iso) {
    const t = this.pickerField(key, label);
    Form.setDate(t, Ui.nz(iso));
    t.setOnClickListener({
      onClick: (v) => {
        let d = Dates.parse(t.getTag());
        if (d == null) d = Dates.today();
        new DatePickerDialog(this.c, {
          onDateSet: (p, y, m, day) => {
            Form.setDate(t, LocalDate.of(y, m + 1, day).toString());
          }
        }, d.getYear(), d.getMonthValue() - 1, d.getDayOfMonth()).show();
      }
    });
    t.setOnLongClickListener({
      onLongClick: (v) => { Form.setDate(t, ""); return true; }
    });
    return t;
  }

  set(key, value) {
    const v = this.fields.get(key);
    if (v instanceof CompoundButton) {
      v.setChecked("1" === value || "true" === value);
      return;
    }
    if (v instanceof NumberPicker) {
      const np = v;
      const shown = np.getDisplayedValues();
      for (let i = 1; i < shown.length; i++) if (shown[i].jsplit(" ")[0] === Ui.nz(value)) { np.setValue(i); np.setTag(Ui.nz(value)); return; }
      np.setValue(0);
      np.setTag("");
    } else if (v instanceof ViewGroup && !(v instanceof Spinner) && typeof v.getTag() === 'string') this.paintBands(v, Ui.nz(value));
    else if (v instanceof EditText) v.setText(value);
    else if (v instanceof Spinner) {
      const vals = v.getTag();
      for (let i = 0; i < vals.length; i++) if (vals[i] === value) v.setSelection(i);
    } else if (v instanceof TextView && typeof v.getTag() === 'string' && Dates.parse(value) != null) Form.setDate(v, value);
    else if (v instanceof TextView && typeof v.getTag() === 'string' && Ui.nz(value).matches("\\d{2}:\\d{2}")) {
      v.setTag(value);
      v.setText(value);
    }
  }

  static setDate(t, iso) {
    t.setTag(iso);
    const d = Dates.parse(iso);
    t.setText(d == null ? (iso.isEmpty() ? "Not set (tap to choose)" : iso) : Dates.longFmt(d));
  }

  time(key, label, hhmm) {
    const t = this.pickerField(key, label);
    t.setTag(Ui.nz(hhmm));
    t.setText(hhmm == null || hhmm.isEmpty() ? "Tap to set time" : hhmm);
    t.setOnClickListener({
      onClick: (v) => {
        const cur = t.getTag();
        let h = 9, m = 0;
        if (cur != null && cur.length === 5) {
          h = Ui.toInt(cur.substring(0, 2), 9);
          m = Ui.toInt(cur.substring(3), 0);
        }
        new TimePickerDialog(this.c, {
          onTimeSet: (p, hour, minute) => {
            const s = jfmt("%02d:%02d", hour, minute);
            t.setTag(s);
            t.setText(s);
          }
        }, h, m, true).show();
      }
    });
    return t;
  }

  /** Long lists stay a drop-down (inside a soft band); shorter ones become colour bands. */
  choice(key, label, labels, values, selected, onChange) {
    const c = this.c;
    let len = 0;
    for (const l of labels) len = Math.max(len, l.length);
    if (values.length <= 14 && len <= 30) return this.bands(key, label, labels, values, selected, null, onChange == null ? null : onChange);
    const b = this.box(key, label);
    this.options.put(key, values);
    const s = new Spinner(c);
    const a = new ArrayAdapter(c, ANDROID_R.layout.simple_spinner_item, labels);
    a.setDropDownViewResource(ANDROID_R.layout.simple_spinner_dropdown_item);
    s.setAdapter(a);
    s.setTag(values);
    for (let i = 0; i < values.length; i++) if (values[i] === selected) s.setSelection(i);
    if (onChange != null) {
      s.setOnItemSelectedListener({
        onItemSelected: (p, v, pos, id) => { onChange.changed(values[pos]); },
        onNothingSelected: (p) => {}
      });
    }
    s.setBackground(Bands.soft(c, Ui.PRIMARY));
    s.setPadding(Ui.dp(c, 6), Ui.dp(c, 2), Ui.dp(c, 6), Ui.dp(c, 2));
    const p = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    p.topMargin = Ui.dp(c, 6);
    b.addView(s, p);
    this.fields.put(key, s);
    return s;
  }

  /**
   * A rolling number wheel from min to max (e.g. years 1 to 50), with a blank "–" above min for not recorded.
   * The value is the number as text, or "" when blank.
   */
  wheel(key, label, min, max, selected, unit, onChange) {
    const c = this.c;
    const b = this.box(key, label);
    const np = new NumberPicker(c);
    const shown = new Array(max - min + 2).fill(null);
    shown[0] = "–";
    for (let i = min; i <= max; i++) shown[i - min + 1] = i + (unit == null ? "" : " " + unit);
    np.setMinValue(0);
    np.setMaxValue(shown.length - 1);
    np.setDisplayedValues(shown);
    np.setWrapSelectorWheel(false);
    np.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);
    const lo = min;
    const sel = Ui.toInt(selected, 0);
    np.setValue(sel >= min && sel <= max ? sel - min + 1 : 0);
    np.setTag(np.getValue() === 0 ? "" : String(np.getValue() - 1 + lo));
    np.setOnValueChangedListener({
      onValueChange: (p, old, now) => {
        p.setTag(now === 0 ? "" : String(now - 1 + lo));
        if (onChange != null) onChange.changed(p.getTag());
      }
    });
    const p = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, Ui.dp(c, 130));
    p.topMargin = Ui.dp(c, 4);
    b.addView(np, p);
    this.fields.put(key, np);
    return np;
  }

  check(key, label, on) {
    const c = this.c;
    const parent = this.row != null ? this.row : this.view;
    if (this.tickFlow == null || parent.getChildCount() === 0 || parent.getChildAt(parent.getChildCount() - 1) !== this.tickFlow.getParent()) {
      const b = this.box(key, null);
      this.tickFlow = new Bands.Flow(c);
      this.tickFlow.setPadding(0, Ui.dp(c, 4), 0, 0);
      b.addView(this.tickFlow, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    } else {
      this.boxes.put(key, this.tickFlow.getParent());
    }
    this.labels.put(key, Ui.nz(label));
    this.options.put(key, ["0", "1"]);
    const cb = new Bands.Band(c, label, Bands.color(this.ticks++));
    cb.setChecked(on);
    this.tickFlow.addView(cb);
    this.fields.put(key, cb);
    return cb;
  }

  show(key, visible) {
    const f = this.fields.get(key);
    if (f instanceof Bands.Band) {
      f.setVisibility(visible ? View.VISIBLE : View.GONE);
      return;
    }
    const b = this.boxes.get(key);
    if (b != null) b.setVisibility(visible ? View.VISIBLE : View.GONE);
  }

  /** The input view of a field (null when there is none). */
  fieldOf(key) {
    const f = this.fields.get(key);
    return f == null ? null : f;
  }

  /** The labelled box that holds a field (null when there is none). */
  boxOf(key) {
    const b = this.boxes.get(key);
    return b == null ? null : b;
  }

  has(key) {
    return this.fields.containsKey(key);
  }

  /** True when the field and its box are on screen (not hidden by show(key, false)). */
  shown(key) {
    const f = this.fields.get(key);
    const b = f instanceof Bands.Band ? f : this.boxes.get(key);
    for (let v = b; v != null && v !== this.view; v = v.getParent() instanceof View ? v.getParent() : null)
      if (v.getVisibility() !== View.VISIBLE) return false;
    return true;
  }

  labelOf(key) {
    return Ui.nz(this.labels.get(key));
  }

  /** One line per shown field: key | label | value | allowed values (empty for free text). */
  describe() {
    const sb = new StringBuilder();
    for (const e of this.labels.entrySet()) {
      const k = e.getKey();
      if (!this.fields.containsKey(k) || !this.shown(k)) continue;
      const v = this.fields.get(k);
      let kind = "";
      if (v instanceof EditText) {
        const t = v.getInputType() & InputType.TYPE_MASK_CLASS;
        kind = t === InputType.TYPE_CLASS_NUMBER ? "number" : t === InputType.TYPE_CLASS_PHONE ? "phone" : "text";
      } else if (v instanceof NumberPicker) kind = "number";
      else if (!(v instanceof ViewGroup) && v instanceof TextView && !(v instanceof CheckBox)) kind = "date or HH:MM";
      const o = this.options.get(k);
      sb.append(k).append(" | ").append(e.getValue()).append(" | ").append(this.get(k)).append(" | ");
      if (o != null) {
        const ob = new StringBuilder();
        for (const x of o) if (!x.isEmpty()) ob.append(ob.length() === 0 ? "" : " / ").append(x);
        sb.append("one of: ").append(ob);
      } else sb.append(kind);
      sb.append('\n');
    }
    return sb.toString();
  }

  get(key) {
    const v = this.fields.get(key);
    if (v instanceof CheckBox) return v.isChecked() ? "1" : "0";
    // (a NumberPicker is a ViewGroup on the phone; in the browser runtime it is a plain View)
    if ((v instanceof ViewGroup || v instanceof NumberPicker) && !(v instanceof Spinner)) return Ui.nz(v.getTag());
    if (v instanceof EditText) return v.getText().toString().trim();
    if (v instanceof Spinner) {
      const s = v;
      const vals = s.getTag();
      const pos = s.getSelectedItemPosition();
      return pos < 0 ? "" : vals[pos];
    }
    if (v instanceof TextView) return Ui.nz(v.getTag());
    return "";
  }

  getInt(key, def) {
    return Ui.toInt(this.get(key), def);
  }

  /** Shows an error on a text field and returns false so callers can bail out. */
  require(key, message) {
    if (!this.get(key).isEmpty()) return true;
    const v = this.fields.get(key);
    if (v instanceof EditText) {
      v.setError(message);
      v.requestFocus();
    } else {
      Ui.toast(this.c, message);
    }
    return false;
  }
}
;
