/* ---- app/Store.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Faculty photos and documents on disk, the faculty PIN, and handing files to other apps. */
class Store {
  // ---------- importing files ----------

  static safeName(s) {
    const n = s.replaceAllRx("[^A-Za-z0-9]+", "_").replaceAllRx("^_+|_+$", "");
    return n.isEmpty() ? "file" : n;
  }

  static displayName(c, uri) {
    let cur = null;
    try {
      cur = c.getContentResolver().query(uri, [OpenableColumns.DISPLAY_NAME], null, null, null);
      if (cur != null && cur.moveToFirst() && !cur.isNull(0)) return cur.getString(0);
    } catch (ignored) {
    } finally {
      if (cur != null) cur.close();
    }
    const last = uri.getLastPathSegment();
    return last == null ? "" : last;
  }

  static extOf(name) {
    const dot = name.lastIndexOf('.');
    return dot < 0 ? "" : name.substring(dot + 1).toLowerCase();
  }

  /**
   * Copies a picked file into filesDir/{dir}/{base}_{time}.{ext} and returns the relative path.
   * Photos and scans are re-saved as JPEG no larger than 2400 px to keep the phone and backups small;
   * PDFs and other files are copied unchanged.
   */
  static importUri(c, uri, dir, base) {
    const mime = Ui.nz(c.getContentResolver().getType(uri));
    const name = Store.displayName(c, uri);
    let ext = Store.extOf(name);
    if (ext.isEmpty()) ext = mime.equals("application/pdf") ? "pdf" : mime.startsWith("image/") ? "jpg" : "bin";
    const stem = dir + "/" + Store.safeName(base) + "_" + System.currentTimeMillis();
    if (mime.startsWith("image/") || ext.equals("jpg") || ext.equals("jpeg") || ext.equals("png") || ext.equals("webp") || ext.equals("heic")) {
      const bm = Store.decode(c, uri, 2400);
      if (bm != null) {
        const rel = stem + ".jpg";
        Store.writeJpeg(bm, Db.get(c).file(rel), 88);
        return rel;
      }
    }
    const rel = stem + "." + ext;
    const out = Db.get(c).file(rel);
    out.getParentFile().mkdirs();
    const inp = c.getContentResolver().openInputStream(uri);
    if (inp == null) throw new IOException("Cannot read file");
    try {
      Store.copy(inp, new FileOutputStream(out));
    } finally {
      inp.close();
    }
    return rel;
  }

  static copy(inp, out) {
    try {
      const buf = new Uint8Array(16384);
      let n;
      while ((n = inp.read(buf)) > 0) out.write(buf, 0, n);
    } finally {
      out.close();
    }
  }

  static decode(c, uri, maxPx) {
    try {
      const o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      let inp = c.getContentResolver().openInputStream(uri);
      BitmapFactory.decodeStream(inp, null, o);
      inp.close();
      if (o.outWidth <= 0) return null;
      o.inSampleSize = Store.sample(o, maxPx);
      o.inJustDecodeBounds = false;
      inp = c.getContentResolver().openInputStream(uri);
      const bm = BitmapFactory.decodeStream(inp, null, o);
      inp.close();
      return bm == null ? null : Store.fit(bm, maxPx);
    } catch (e) {
      return null;
    }
  }

  static sample(o, maxPx) {
    let s = 1;
    while (idiv(Math.max(o.outWidth, o.outHeight), s * 2) >= maxPx) s *= 2;
    return s;
  }

  static fit(bm, maxPx) {
    const w = bm.getWidth(), h = bm.getHeight(), m = Math.max(w, h);
    if (m <= maxPx) return bm;
    const k = maxPx / m;
    return Bitmap.createScaledBitmap(bm, Math.round(w * k), Math.round(h * k), true);
  }

  static writeJpeg(bm, f, quality) {
    f.getParentFile().mkdirs();
    const out = new FileOutputStream(f);
    try {
      bm.compress(Bitmap.CompressFormat.JPEG, quality, out);
    } finally {
      out.close();
    }
    // the picture is in memory now: later synchronous decodes of this file see it
    if (bm.canvas) { Bitmaps.decoded.set(VFS.norm(f.rel()), bm); VFS.setMeta(f.rel(), { w: bm.w, h: bm.h }); }
  }

  /** Saves a picked picture as a JPEG at filesDir/{rel}, at most maxPx on its long side (10.11, the album). Null if it is not a picture. */
  static saveImage(c, src, rel, maxPx) {
    const bm = Store.decode(c, src, maxPx);
    if (bm == null) return null;
    Store.writeJpeg(bm, Db.get(c).file(rel), 86);
    return rel;
  }

  /** Re-saves a camera capture in place, scaled to at most maxPx. Returns false if it is not an image. */
  static shrink(f, maxPx) {
    try {
      const o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      BitmapFactory.decodeFile(f.getAbsolutePath(), o);
      if (o.outWidth <= 0) return false;
      o.inSampleSize = Store.sample(o, maxPx);
      o.inJustDecodeBounds = false;
      const bm = BitmapFactory.decodeFile(f.getAbsolutePath(), o);
      if (bm == null) return false;
      Store.writeJpeg(Store.fit(bm, maxPx), f, 88);
      return true;
    } catch (e) {
      return false;
    }
  }

  /** Saves a square, centre-cropped profile photo from a picked or captured image (under people/, which every member can see: 9.00). */
  static savePhoto(c, src, srcFile, staffId) {
    let bm;
    if (src != null) bm = Store.decode(c, src, 1400);
    else {
      const o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      BitmapFactory.decodeFile(srcFile.getAbsolutePath(), o);
      o.inSampleSize = Store.sample(o, 1400);
      o.inJustDecodeBounds = false;
      bm = BitmapFactory.decodeFile(srcFile.getAbsolutePath(), o);
    }
    if (bm == null) throw new IOException("Not an image");
    const s = Math.min(bm.getWidth(), bm.getHeight());
    const k = Math.min(1, 640 / s);
    // Java: createBitmap(bm, x, y, s, s, scale matrix k, true)
    let sq = Bitmap.createBitmap(bm, idiv(bm.getWidth() - s, 2), idiv(bm.getHeight() - s, 2), s, s);
    if (k < 1) sq = Bitmap.createScaledBitmap(sq, Math.round(s * k), Math.round(s * k), true);
    const rel = "people/" + staffId + "_photo_" + System.currentTimeMillis() + ".jpg";
    Store.writeJpeg(sq, Db.get(c).file(rel), 90);
    return rel;
  }

  static sizeLabel(bytes) {
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return Math.round(bytes / 1024.0) + " KB";
    return jfmt("%.1f MB", bytes / (1024.0 * 1024.0));
  }

  static kindLabel(rel) {
    const e = Store.extOf(rel);
    if (e.equals("pdf")) return "PDF";
    if (e.equals("jpg") || e.equals("jpeg") || e.equals("png") || e.equals("webp")) return "Image";
    return e.toUpperCase();
  }

  static isImage(rel) {
    return DocProvider.mimeOf(rel).startsWith("image/");
  }

  // ---------- handing files to other apps ----------

  static share(a, rel, subject) {
    const u = DocProvider.uri(rel);
    const i = new Intent(Intent.ACTION_SEND);
    i.setType(DocProvider.mimeOf(rel));
    i.putExtra(Intent.EXTRA_STREAM, u);
    i.putExtra(Intent.EXTRA_SUBJECT, subject);
    i.setClipData(ClipData.newRawUri(subject, u));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    const go = () => a.startActivity(Intent.createChooser(i, "Share " + subject));
    // Web: the file's bytes must be in memory before the browser's share sheet opens
    if (VFS.readSync(rel) == null && VFS.exists(rel)) VFS.read(rel).then(go, go); else go();
  }

  static openWith(a, rel) {
    const u = DocProvider.uri(rel);
    const i = new Intent(Intent.ACTION_VIEW);
    i.setDataAndType(u, DocProvider.mimeOf(rel));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    try {
      a.startActivity(i);
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(a, "No app on this phone can open this file");
    }
  }

  /** Starts the camera, writing the picture to filesDir/{rel}. Returns false if there is no camera app. */
  static capture(a, rel, req) {
    const u = DocProvider.uri(rel);
    const i = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
    i.putExtra(MediaStore.EXTRA_OUTPUT, u);
    i.setClipData(ClipData.newRawUri("capture", u));
    i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION | Intent.FLAG_GRANT_READ_URI_PERMISSION);
    try {
      Db.get(a).file(rel).getParentFile().mkdirs();
      a.startActivityForResult(i, req);
      return true;
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(a, "No camera app found");
      return false;
    }
  }

  static pick(a, mimes, req) {
    const i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
    i.addCategory(Intent.CATEGORY_OPENABLE);
    i.setType(mimes.length == 1 ? mimes[0] : "*/*");
    if (mimes.length > 1) i.putExtra(Intent.EXTRA_MIME_TYPES, mimes);
    try {
      a.startActivityForResult(i, req);
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(a, "No file picker found");
    }
  }

  // ---------- faculty PIN ----------

  static unlockedAt = 0;
  static UNLOCK_MS = 5 * 60 * 1000;

  static hash(pin) {
    const md = MessageDigest.getInstance("SHA-256");
    const d = md.digest(jbytes("tvmchmed-faculty:" + pin));
    const sb = new StringBuilder();
    for (const b of d) sb.append(jfmt("%02x", b & 0xFF));
    return sb.toString();
  }

  static hasPin(db) {
    return !db.setting("faculty_pin", "").isEmpty();
  }

  /** True while the faculty section needs the PIN. Each unlocked screen keeps it open a few minutes longer. */
  static locked(db) {
    if (!Store.hasPin(db)) return false;
    const now = System.currentTimeMillis();
    if (Store.unlockedAt > 0 && now - Store.unlockedAt < Store.UNLOCK_MS) {
      Store.unlockedAt = now;
      return false;
    }
    return true;
  }

  static unlock(db, pin) {
    if (!Store.hash(pin).equals(db.setting("faculty_pin", ""))) return false;
    Store.unlockedAt = System.currentTimeMillis();
    return true;
  }

  static lock() {
    Store.unlockedAt = 0;
  }

  static setPin(db, pin) {
    db.setSetting("faculty_pin", pin == null ? "" : Store.hash(pin));
    Store.unlockedAt = pin == null ? 0 : System.currentTimeMillis();
  }

  // ---------- faces ----------

  static initials(name) {
    const n = name.replaceAllRx("(?i)^(prof\\.?|dr\\.?|\\s)+", "").replaceAllRx("(?i)\\b(dr|prof)\\.?\\s*", "").trim();
    const sb = new StringBuilder();
    for (const w of n.jsplit("[\\s.]+")) {
      if (!w.isEmpty() && Character.isLetter(w.charAt(0))) sb.append(Character.toUpperCase(w.charAt(0)));
      if (sb.length() == 2) break;
    }
    return sb.length() == 0 ? "?" : sb.toString();
  }

  /** Round profile photo, or coloured initials when there is no photo. */
  static avatar(c, s, sizeDp, color) {
    const px = Ui.dp(c, sizeDp);
    const photo = s.get("photo");
    const bm = photo == null || photo.isEmpty() ? null : Ui.loadScaled(Db.get(c).file(photo), px * 2);
    let v;
    if (bm != null) {
      const iv = new ImageView(c);
      iv.setImageBitmap(Store.circle(bm, px));
      v = iv;
    } else {
      const t = Ui.tv(c, Store.initials(Ui.nz(s.get("name"))), sizeDp * 0.36, Color.WHITE, true);
      t.setGravity(Gravity.CENTER);
      v = t;
    }
    v.setBackground(Ui.gradient(c, [color, Ui.mix(color, 0xFF000000, 0.3)], sizeDp / 2));
    v.setOutlineProvider({
      getOutline: (view, o) => { o.setOval(0, 0, view.getWidth(), view.getHeight()); }
    });
    v.setClipToOutline(true);
    v.setLayoutParams(Ui.lp(px, px));
    return v;
  }

  /** Centre-crops a bitmap into a round one, so photos look right on every launcher and Android version. */
  static circle(src, px) {
    return Bitmaps.circle(src, px);
  }

  static roleColor(role) {
    if ("Professor".equals(role)) return Ui.PRIMARY;
    if ("Associate Professor".equals(role)) return Ui.PURPLE;
    return Ui.TEAL;
  }

  static exists(c, rel) {
    return rel != null && !rel.isEmpty() && Db.get(c).file(rel).exists();
  }

  static size(c, rel) {
    return rel == null || rel.isEmpty() ? 0 : Db.get(c).file(rel).length();
  }
}
;
