/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * App lock for a lost or borrowed phone: once signed in, the app opens only with this phone's PIN (or fingerprint).
 * It locks when the app starts and after a few minutes away. The PIN never leaves the phone; only a salted PBKDF2 hash
 * is kept in prefs "lock". Five wrong PINs sign the phone out (email + password needed again).
 * Web: browsers give pages no fingerprint check, so only the PIN is offered.
 */
class Lock {
  static MAX_TRIES = 5;
  static MIN_LEN = 4; static MAX_LEN = 8;
  static AFTER_MINUTES = [1, 3, 5, 15];

  /** Tests turn the lock on without a real sign-in. */
  static always = false;
  /** True from a correct PIN until the app is away longer than the lock time (or the process restarts). */
  static unlocked = false;
  /** True while no screen of the app is showing; hiddenAt = elapsedRealtime when the last one went away. */
  static away = false;
  static hiddenAt = 0;

  static prefs(c) {
    return c.getSharedPreferences("lock", Context.MODE_PRIVATE);
  }

  /** The lock applies once this phone is signed in and sharing records. */
  static applies(c) {
    return Lock.always || (Cloud.requireLogin && Cloud.active(c));
  }

  static hasPin(c) {
    return !Lock.prefs(c).getString("hash", "").isEmpty();
  }

  static afterMinutes(c) {
    return Lock.prefs(c).getInt("after", 3);
  }

  static setAfterMinutes(c, m) {
    Lock.prefs(c).edit().putInt("after", m).apply();
  }

  /** Whether the lock screen must come up before this screen shows. */
  static needed(c) {
    if (!Lock.applies(c)) return false;
    if (!Lock.hasPin(c) || !Lock.unlocked) return true;
    return Lock.away && SystemClock.elapsedRealtime() - Lock.hiddenAt >= Lock.afterMinutes(c) * 60000;
  }

  /** A screen went to the background. */
  static hidden() {
    if (Lock.unlocked) { Lock.away = true; Lock.hiddenAt = SystemClock.elapsedRealtime(); }
  }

  /** A screen is showing while unlocked: the time away starts again. */
  static shown() {
    Lock.away = false;
  }

  static open(c) {
    c.startActivity(new Intent(c, LockActivity).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | 0x10000 /* FLAG_ACTIVITY_NO_ANIMATION */));
  }

  static validPin(pin) {
    return pin != null && pin.length >= Lock.MIN_LEN && pin.length <= Lock.MAX_LEN && pin.matches("[0-9]+");
  }

  static setPin(c, pin) {
    const salt = new Uint8Array(16);
    new SecureRandom().nextBytes(salt);
    const s = Base64.encodeToString(salt, Base64.NO_WRAP);
    Lock.prefs(c).edit().putString("salt", s).putString("hash", Lock.hash(pin, salt)).putInt("fails", 0).apply();
  }

  /** Checks a PIN; a wrong one counts towards the sign-out. */
  static check(c, pin) {
    const p = Lock.prefs(c);
    const salt = Base64.decode(p.getString("salt", ""), Base64.NO_WRAP);
    const ok = Lock.hasPin(c) && MessageDigest.isEqual(jbytes(Lock.hash(pin, salt)), jbytes(p.getString("hash", "")));
    p.edit().putInt("fails", ok ? 0 : p.getInt("fails", 0) + 1).apply();
    return ok;
  }

  static triesLeft(c) {
    return Math.max(0, Lock.MAX_TRIES - Lock.prefs(c).getInt("fails", 0));
  }

  /** Forgets the PIN and fingerprint choice (sign out, forgot PIN, too many tries). The lock time is kept. */
  static clear(c) {
    Lock.prefs(c).edit().remove("salt").remove("hash").remove("fails").remove("bio").apply();
    Lock.unlocked = false;
    Lock.away = false;
  }

  static unlock() {
    Lock.unlocked = true;
    Lock.away = false;
  }

  /** PBKDF2WithHmacSHA256, 20000 rounds, 256 bits (the PIN's digits as UTF-8, as Java's chars for ASCII digits). */
  static hash(pin, salt) {
    const h = pbkdf2Sha256(jbytes(pin), salt, 20000, 32);
    return Base64.encodeToString(h, Base64.NO_WRAP);
  }

  // ---------- fingerprint ----------

  /** Tests pretend the phone has an enrolled fingerprint. */
  static bioForTests = null;

  /** Whether this phone has a fingerprint (or face) set up that the app can ask for. Never in a browser. */
  static bioAvailable(c) {
    if (Lock.bioForTests != null) return Lock.bioForTests;
    if (Build.VERSION.SDK_INT < 28) return false;
    return BiometricManager.canAuthenticate() == BiometricManager.BIOMETRIC_SUCCESS;
  }

  static bio(c) {
    return Lock.prefs(c).getBoolean("bio", false) && Lock.bioAvailable(c);
  }

  static setBio(c, on) {
    Lock.prefs(c).edit().putBoolean("bio", on).apply();
  }
}
;
/* ---- app/E2e.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * End-to-end encryption and the 7:30 AM wipe for the Duty team chat.
 *
 * Each phone makes its own key pair; only the public half is shared (table chat_keys). A message is locked on the
 * sender's phone with a fresh key, and that key is locked again for every phone of the day's team, so the server
 * only ever holds scrambled text and files. Messages, read receipts and files vanish when the DAP's duty ends.
 *
 * Web: the crypto runs on WebCrypto (ECDH P-256 keys as X.509 "spki" / PKCS#8, AES-GCM with a 12-byte IV and the
 * 128-bit tag after the cipher text), byte for byte as on the phones, so phones and the website read each other's
 * messages. Every function that does crypto returns a Promise (seal, open, sealFile, openFile, ensureKey, purgeServer).
 */
class E2e {
  static DUTY_DIR = "chat/duty/";
  static LOCKED = "🔒 This message can't be opened on this phone (it was sent before this phone's secure key reached the sender).";
  static PREFS = "e2e";

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences(E2e.PREFS, Context.MODE_PRIVATE);
  }

  static b64(b) {
    return Base64.encodeToString(b, Base64.NO_WRAP);
  }

  static unb64(s) {
    return Base64.decode(s, Base64.NO_WRAP);
  }

  static random(n) {
    const b = new Uint8Array(n);
    crypto.getRandomValues(b);
    return b;
  }

  // ---------- keys ----------

  static async newPair() {
    return crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  }

  /** The X.509 (spki) encoding, as Java's getEncoded() of an EC public key. */
  static async encPub(kp) {
    return new Uint8Array(await crypto.subtle.exportKey("spki", kp.publicKey));
  }

  /** The PKCS#8 encoding, as Java's getEncoded() of an EC private key. */
  static async encPriv(kp) {
    return new Uint8Array(await crypto.subtle.exportKey("pkcs8", kp.privateKey));
  }

  static async pub(s) {
    return crypto.subtle.importKey("spki", E2e.unb64(s), { name: "ECDH", namedCurve: "P-256" }, true, []);
  }

  static async priv(s) {
    return crypto.subtle.importKey("pkcs8", E2e.unb64(s), { name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);
  }

  /** Makes this phone's key pair once and shares the public half (again if the person was linked to another staff entry). */
  static async ensureKey(c, db) {
    const me = Chat.me(c);
    // wait for the first download, so a key this phone already shared is found rather than made again
    if (me <= 0 || db.meta("last_seq", 0) == 0) return false;
    const p = E2e.prefs(c);
    try {
      if (p.getString("pub", "").isEmpty()) {
        const kp = await E2e.newPair();
        p.edit().putString("pub", E2e.b64(await E2e.encPub(kp))).putString("priv", E2e.b64(await E2e.encPriv(kp))).remove("row").apply();
      }
    } catch (e) {
      return false;
    }
    const pub = p.getString("pub", "");
    let row = p.getLong("row", -1);
    let r = row > 0 ? db.row("SELECT * FROM chat_keys WHERE id=?", String(row)) : null;
    if (r == null) {
      const same = db.row("SELECT id FROM chat_keys WHERE pub=? LIMIT 1", pub);
      if (same != null) {
        row = Long.parseLong(same.get("id"));
        r = db.row("SELECT * FROM chat_keys WHERE id=?", String(row));
        p.edit().putLong("row", row).apply();
      }
    }
    const cv = new ContentValues();
    cv.put("staff_id", me);
    cv.put("pub", pub);
    cv.put("time", Chat.now());
    if (r == null) p.edit().putLong("row", db.insert("chat_keys", cv)).apply();
    else if (!String(me).equals(r.get("staff_id"))) db.update("chat_keys", cv, row);
    else return false;
    return true;
  }

  /** How many of these people have at least one phone that can open locked messages. */
  static ready(db, ids) {
    let n = 0;
    for (const id of ids) if (db.num("SELECT COUNT(*) FROM chat_keys WHERE staff_id=?", String(id)) > 0) n++;
    return n;
  }

  /** ECDH shared secret (the x coordinate, as Java's KeyAgreement), then SHA-256("TVMCH duty chat v1" + secret). */
  static async wrapKey(mine, theirs) {
    const secret = new Uint8Array(await crypto.subtle.deriveBits({ name: "ECDH", public: theirs }, mine, 256));
    const d = MessageDigest.getInstance("SHA-256");
    d.update(jbytes("TVMCH duty chat v1"));
    return d.digest(secret);
  }

  /** AES/GCM/NoPadding with a 128-bit tag appended to the cipher text (Java's layout). Throws GeneralSecurityException. */
  static async gcm(lock, key, iv, data) {
    try {
      const k = await crypto.subtle.importKey("raw", key, { name: "AES-GCM" }, false, [lock ? "encrypt" : "decrypt"]);
      const alg = { name: "AES-GCM", iv: iv, tagLength: 128 };
      return new Uint8Array(lock ? await crypto.subtle.encrypt(alg, k, data) : await crypto.subtle.decrypt(alg, k, data));
    } catch (e) {
      throw new GeneralSecurityException(e && e.message ? e.message : String(e));
    }
  }

  // ---------- messages ----------

  static isDutyRow(t, data) {
    return t.equals("chat_messages") && String(Chat.DUTY).equals(data.optString("chat_id"));
  }

  /** PG Connect messages (7.79): locked the same way, for the postgraduates' and the admin's phones only. */
  static isWardRow(t) {
    return t.equals(PgConnect.TABLE);
  }

  /** Rows that travel locked: the Duty team chat and PG Connect. */
  static isSealed(t, data) {
    return E2e.isDutyRow(t, data) || E2e.isWardRow(t);
  }

  /** Before upload: replaces the text and file name with a locked envelope only the day's team can open. */
  static async seal(c, db, data) {
    if ("1".equals(data.optString("deleted"))) return;
    const rel = data.isNull("file") ? "" : data.optString("file", "");
    const inner = new JSONObject()
      .put("text", data.isNull("text") ? "" : data.optString("text", ""))
      .put("file_name", data.isNull("file_name") ? "" : data.optString("file_name", ""));
    if (data.has("patient")) inner.put("patient", data.isNull("patient") ? "" : data.optString("patient", ""));
    if (!rel.isEmpty()) inner.put("fk", E2e.fileKey(c, rel, true));
    const k = E2e.random(32), iv = E2e.random(12);
    const eph = await E2e.newPair();
    const keys = new JSONObject();
    // PG Connect: only the postgraduates and the admin, worked out at each upload so new PGs get resent messages
    const members = data.has("from_ward") ? PgConnect.audience(db) : data.isNull("members") ? "" : data.optString("members", "");
    for (const r of db.rows("SELECT id, staff_id, pub FROM chat_keys")) {
      if (!"*".equals(members) && !members.contains("," + r.get("staff_id") + ",")) continue;
      try {
        const iv2 = E2e.random(12);
        const w = await E2e.gcm(true, await E2e.wrapKey(eph.privateKey, await E2e.pub(r.get("pub"))), iv2, k);
        keys.put(r.get("id"), E2e.b64(iv2) + "." + E2e.b64(w));
      } catch (ignored) {
        // a damaged key: that phone can't read this message
      }
    }
    const env = new JSONObject().put("v", 1).put("e", E2e.b64(await E2e.encPub(eph))).put("iv", E2e.b64(iv))
      .put("ct", E2e.b64(await E2e.gcm(true, k, iv, jbytes(inner.toString())))).put("k", keys);
    data.put("text", "");
    data.put("file_name", "");
    if (data.has("patient")) data.put("patient", "");
    data.put("enc", env.toString());
  }

  /** After download: opens a locked envelope with this phone's key, or leaves a note that it can't. */
  static async open(c, data) {
    const enc = data.isNull("enc") ? "" : data.optString("enc", "");
    if (enc.isEmpty()) return;
    try {
      const env = new JSONObject(enc);
      const p = E2e.prefs(c);
      const w = env.getJSONObject("k").optString(String(p.getLong("row", -1)), "");
      if (w.isEmpty() || p.getString("priv", "").isEmpty()) throw new Error("no key");
      const parts = w.jsplit("\\.");
      const k = await E2e.gcm(false, await E2e.wrapKey(await E2e.priv(p.getString("priv", "")), await E2e.pub(env.getString("e"))), E2e.unb64(parts[0]), E2e.unb64(parts[1]));
      const inner = new JSONObject(jstr(await E2e.gcm(false, k, E2e.unb64(env.getString("iv")), E2e.unb64(env.getString("ct")))));
      data.put("text", inner.optString("text", ""));
      data.put("file_name", inner.optString("file_name", ""));
      if (inner.has("patient")) data.put("patient", inner.optString("patient", ""));
      const rel = data.isNull("file") ? "" : data.optString("file", "");
      if (!rel.isEmpty() && inner.has("fk")) p.edit().putString("fk_" + rel, inner.getString("fk")).apply();
    } catch (e) {
      try {
        data.put("text", E2e.LOCKED);
        if (data.has("patient")) data.put("patient", "");
        data.put("file", "");
        data.put("file_name", "");
      } catch (ignored) {}
    }
    data.remove("enc");
  }

  /**
   * A team member's phone shared its key after some messages were sent: send this phone's messages of the current
   * duty again, locked for every key now known, so latecomers can read them. Returns true if any were queued.
   */
  static reseal(c, db) {
    const me = Chat.me(c);
    if (me <= 0) return false;
    const p = E2e.prefs(c);
    const seen = p.getString("keys_seen", ",");
    const all = new StringBuilder(",");
    let fresh = false;
    for (const r of db.rows("SELECT id FROM chat_keys ORDER BY id")) {
      all.append(r.get("id")).append(',');
      if (!seen.contains("," + r.get("id") + ",")) fresh = true;
    }
    p.edit().putString("keys_seen", all.toString()).apply();
    if (!fresh) return false;
    const mine = db.rows("SELECT id FROM chat_messages WHERE chat_id=? AND sender_id=? AND time>=? AND deleted=''",
      String(Chat.DUTY), String(me), E2e.dutyStart());
    for (const m of mine)
      db.getWritableDatabase().execSQL("INSERT OR REPLACE INTO outbox(tbl, pk) VALUES ('chat_messages', ?)", [m.get("id")]);
    // PG Connect: this phone's messages of the last week, so a new phone can read the recent conversation
    const ward = db.rows("SELECT id FROM " + PgConnect.TABLE + " WHERE sender_id=? AND time>=? AND IFNULL(deleted,'')=''",
      String(me), Chat.stamp(LocalDateTime.now().minusDays(7)));
    for (const m of ward)
      db.getWritableDatabase().execSQL("INSERT OR REPLACE INTO outbox(tbl, pk) VALUES ('" + PgConnect.TABLE + "', ?)", [m.get("id")]);
    return !mine.isEmpty() || !ward.isEmpty();
  }

  // ---------- files ----------

  static fileKey(c, rel, create) {
    const p = E2e.prefs(c);
    let k = p.getString("fk_" + rel, "");
    if (k.isEmpty() && create) {
      k = E2e.b64(E2e.random(32));
      p.edit().putString("fk_" + rel, k).apply();
    }
    return k;
  }

  /** Locks a Duty team file before upload. */
  static async sealFile(c, rel, plain) {
    if (!rel.startsWith(E2e.DUTY_DIR)) return plain;
    const iv = E2e.random(12);
    const ct = await E2e.gcm(true, E2e.unb64(E2e.fileKey(c, rel, true)), iv, plain);
    const out = new Uint8Array(12 + ct.length);
    out.set(iv, 0);
    out.set(ct, 12);
    return out;
  }

  /** Opens a downloaded Duty team file (files from before encryption have no key and are kept as they are). */
  static async openFile(c, rel, body) {
    if (!rel.startsWith(E2e.DUTY_DIR)) return body;
    const k = E2e.fileKey(c, rel, false);
    if (k.isEmpty() || body.length < 28) return body;
    const iv = body.slice(0, 12);
    const ct = body.slice(12);
    return E2e.gcm(false, E2e.unb64(k), iv, ct);
  }

  // ---------- the 7:30 AM wipe ----------

  /** When the current DAP duty began (7:30 AM today, or yesterday before 7:30 AM), as a chat time. */
  static dutyStart() {
    return Chat.stamp(E2e.dutyStartTime());
  }

  /** By the phone's real clock, like the message times (not the test clock of Dates). */
  static dutyStartTime() {
    const now = LocalDateTime.now();
    return LocalDateTime.of(now.toLocalTime().isBefore(Dates.CHANGEOVER) ? now.toLocalDate().minusDays(1) : now.toLocalDate(), Dates.CHANGEOVER);
  }

  /** Removes the earlier duty's messages, read receipts and files from this phone. Returns how many messages went. */
  static purgeLocal(c) {
    const db = Db.get(c);
    const start = E2e.dutyStart(), id = String(Chat.DUTY);
    const old = db.rows("SELECT id, file FROM chat_messages WHERE chat_id=? AND time<?", id, start);
    const reads = db.rows("SELECT id FROM chat_reads WHERE chat_id=? AND time<?", id, start);
    if (old.isEmpty() && reads.isEmpty()) return 0;
    const w = db.getWritableDatabase();
    w.beginTransaction();
    try {
      w.execSQL("INSERT INTO sync_mute VALUES (1)");
      for (const m of old) {
        w.delete("chat_messages", "id=?", [m.get("id")]);
        w.delete("outbox", "tbl='chat_messages' AND pk=?", [m.get("id")]);
      }
      for (const r of reads) {
        w.delete("chat_reads", "id=?", [r.get("id")]);
        w.delete("outbox", "tbl='chat_reads' AND pk=?", [r.get("id")]);
      }
      w.execSQL("DELETE FROM sync_mute");
      w.setTransactionSuccessful();
    } finally {
      w.endTransaction();
    }
    const e = E2e.prefs(c).edit();
    for (const m of old) {
      const rel = Ui.nz(m.get("file"));
      if (rel.isEmpty()) continue;
      db.file(rel).delete();
      w.delete("files_up", "rel=?", [rel]);
      e.remove("fk_" + rel);
    }
    e.apply();
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm != null) nm.cancel(7100);
    return old.size();
  }

  /** Once per duty: asks the server to drop the earlier duty's messages and deletes their stored files. */
  static async purgeServer(c) {
    const start = E2e.dutyStart();
    const p = E2e.prefs(c);
    if (start.equals(p.getString("server_purged", ""))) return;
    let ok = true;
    try {
      await Cloud.jsonA(c, "POST", "/rest/v1/rpc/purge_duty", new JSONObject());
    } catch (e) {
      ok = false; // the server set-up has not been re-run yet; the server still hides old messages from phones
    }
    try {
      const cut = E2e.dutyStartTime().atZone(ZoneId.systemDefault()).toInstant();
      const items = new JSONArray((await Cloud.jsonA(c, "POST", "/storage/v1/object/list/files",
        new JSONObject().put("prefix", "chat/duty/").put("limit", 1000).put("offset", 0))).text());
      const gone = [];
      for (let i = 0; i < items.length(); i++) {
        const o = items.getJSONObject(i);
        const name = o.optString("name", ""), at = o.optString("created_at", "");
        if (name.isEmpty() || at.isEmpty() || o.isNull("id")) continue;
        let made;
        try {
          made = OffsetDateTime.parse(at).toInstant();
        } catch (x) {
          made = Instant.parse(at);
        }
        if (made.isBefore(cut)) gone.add("chat/duty/" + name);
      }
      for (const rel of gone)
        if (Sync.safeRel(rel)) await Cloud.httpA(c, "DELETE", "/storage/v1/object/files/" + Uri.encode(rel, "/"), null, null, await Cloud.tokenA(c));
    } catch (e) {
      ok = false;
    }
    if (ok) p.edit().putString("server_purged", start).apply();
  }
}
;
