'use strict';
/**
 * Phone alerts while the app is closed. Android wakes this job about every 15 minutes when there is internet:
 * it syncs, then shows notifications for new chat messages, HOD urgent messages, the morning handover and
 * anything waiting for this person (approvals, leave letters, logbook entries to sign).
 * Web: a page cannot be woken while it is closed, so schedule() runs the same work every 15 minutes while the page is open.
 */
class Background extends JobService {
  static JOB = 7300;
  static CHANNEL = "alerts";
  static PERIOD_MS = 15 * 60 * 1000;
  static N_ALERT = 7200; static N_WAITING = 7201; static N_HANDOVER = 7202; static N_UPDATE = 7203; static N_PGC = 7204; static N_EWS = 7205; static N_WATCH = 7206; static N_BRIEF = 7207; static N_RESULTS = 7209; static N_CONDUCT = 7210; static N_MEMO = 7211; static N_SIGNOFF = 7212; static N_CRIT = 7213; static N_OUTBREAK = 7214; static N_HARRISON = 7215; static N_ESCALATE = 7216; static N_BEDS = 7217; static N_DAPREPORT = 7218; static N_ISSUE = 7219; static N_KUDOS = 7220; static N_MONTH = 7221; static N_DUEL = 7222; static N_CODE = 7224; static N_TEACH = 7225; static N_RARE = 7226; static N_NMC = 7227;
  /** Web: the repeating timer, started once. */
  static timer = null;

  /** Starts the repeating job once; safe to call often. */
  static schedule(c) {
    const app = c.getApplicationContext();
    if (!Cloud.active(app)) {
      if (Background.timer != null) { clearInterval(Background.timer); Background.timer = null; }
      return;
    }
    if (Background.timer != null) return;
    Background.timer = setInterval(() => { Background.work(app); }, Background.PERIOD_MS);
  }

  onStartJob(params) {
    const c = this.getApplicationContext();
    Background.work(c).then(() => this.jobFinished(params, false));
    return true;
  }

  /** The job's work (sync, then notifications), callable without JobParameters. Returns a Promise. */
  static async work(c) {
    try {
      if (Cloud.active(c)) {
        const changed = await Sync.run(c);
        if (changed) Reminders.schedule(c);
        if (changed) Protocols.schedule(c);
        if (changed) Countdown.schedule(c);
        Chat.notifyNew(c);
        Background.check(c);
        try {
          Updates.autoFetch(c, Db.get(c));
        } catch (ignored) {
          // tried again next time; the home page still offers the update
        }
      }
    } catch (ignored) {
      // no internet or the server is busy: try again next time
    }
  }

  onStopJob(params) {
    return true;
  }

  // ---------- what to tell the person ----------

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences("bg_alerts", Context.MODE_PRIVATE);
  }

  /** After a sync: new HOD urgent messages, the morning handover, and things waiting for this person. */
  static check(c) {
    if (!Cloud.active(c)) return;
    const db = Db.get(c);
    const p = Background.prefs(c);
    const e = p.edit();

    // HOD urgent messages: each new one once
    const seen = p.getString("alert_seen", "");
    let max = seen;
    let newest = null;
    for (const a of Alerts.active(db)) {
      const t = Ui.nz(a.get("posted_at"));
      if (t.compareTo(max) > 0) max = t;
      if (!seen.isEmpty() && t.compareTo(seen) > 0 && (newest == null || t.compareTo(newest.get("posted_at")) > 0)) newest = a;
    }
    e.putString("alert_seen", max.isEmpty() ? Alerts.now() : max);
    if (newest != null) Background.show(c, Background.N_ALERT, "🚨 HOD urgent message", Ui.nz(newest.get("message")), Ui.RED, MainActivity);

    // 10.20: NMC biometric attendance reminder for faculty, check-in and check-out, once a day each
    try {
      const nmc = NmcAttendance.remind(c, db, p, e);
      if (!nmc.isEmpty()) Background.show(c, Background.N_NMC, "🖐 NMC attendance: " + NmcAttendance.label(nmc), "Tap to open the NMC app and mark your " + NmcAttendance.label(nmc), NmcAttendance.COLOR, NmcAttendanceActivity);
    } catch (ex) {
      // the reminder is optional
    }

    // PG Connect: never the message itself on the lock screen, it is end-to-end encrypted
    const pgSeen = p.getString("pgc_seen", "");
    if (pgSeen.isEmpty()) e.putString("pgc_seen", Chat.now());
    else if (PgConnect.canUse(c, db)) {
      const n = PgConnect.newSince(c, db, pgSeen);
      e.putString("pgc_seen", Chat.now());
      if (n > 0) Background.show(c, Background.N_PGC, "💬 New message in PG Connect", n == 1 ? "1 new message for your ward" : n + " new messages for your ward", PgConnect.GREEN, PgConnectActivity);
    }

    // memos (9.00): a new memo for this person, or an explanation on one they issued (never the content on the lock screen)
    if (Memo.on(db)) {
      const me = Memo.me(c);
      if (!me.isEmpty()) {
        const mw = Memo.waitingForMe(c, db), md = Memo.toDecide(c, db);
        const was = p.getString("memo_seen", "");
        if (!was.isEmpty()) {
          const w = was.jsplit(":");
          if (mw > Ui.toInt(w[0], 0)) Background.show(c, Background.N_MEMO, "📩 Memo", "You have received a memo. Open the app to give your explanation.", Memo.COLOR, MemoActivity);
          else if (md > (w.length > 1 ? Ui.toInt(w[1], 0) : 0)) Background.show(c, Background.N_MEMO, "📩 Memo", "An explanation has come in on a memo you issued.", Memo.COLOR, MemoActivity);
        }
        e.putString("memo_seen", mw + ":" + md);
      }
    }

    // sign-off queue (9.30): a new document waiting for this faculty member, or one sent back to this PG (no names on the lock screen)
    if (!SignOff.me(c).isEmpty()) {
      const sw = SignOff.faculty(c) ? SignOff.countForMe(c, db) : 0, sb = SignOff.returnedToMe(c, db);
      const was = p.getString("signoff_seen", "");
      if (!was.isEmpty()) {
        const w = was.jsplit(":");
        if (sw > Ui.toInt(w[0], 0)) Background.show(c, Background.N_SIGNOFF, "✍ Sign-off", sw === 1 ? "A document is waiting for your sign-off." : sw + " documents are waiting for your sign-off.", SignOff.COLOR, SignOffActivity);
        else if (sb > (w.length > 1 ? Ui.toInt(w[1], 0) : 0)) Background.show(c, Background.N_SIGNOFF, "↩ Sign-off", "A document you sent was sent back for correction.", SignOff.COLOR, SignOffActivity);
      }
      e.putString("signoff_seen", sw + ":" + sb);
    }

    // Harrison's topic of the day (9.80): once a day, when the day's deck is out at 7 AM
    try {
      const h = Harrison.today(db);
      if (h != null && !Ui.nz(h.get("day")).equals(p.getString("harrison_told", ""))) {
        e.putString("harrison_told", Ui.nz(h.get("day")));
        Background.show(c, Background.N_HARRISON, "📘 Harrison's topic of the day", Ui.nz(h.get("topic")), Harrison.COLOR, HarrisonActivity);
      }
    } catch (ignored) {
      // the reminder is optional
    }

    // outbreak early warning (9.60): a new or bigger cluster of cases from one place, for faculty (no names)
    try {
      if (Outbreak.alerted(c)) {
        const ob = Outbreak.fresh(c, db, "bg");
        if (!ob.isEmpty()) {
          Background.show(c, Background.N_OUTBREAK, "🦠 Possible outbreak", ob.size() === 1 ? Outbreak.line(ob.get(0)) : ob.size() + " clusters of cases from one place this week",
            Outbreak.COLOR, OutbreakActivity);
          Outbreak.mark(c, ob, "bg");
        }
      }
    } catch (ignored) {
      // the alert is optional
    }

    // critical lab values (9.50): a new one for this person's unit (no names or values on the lock screen)
    try {
      const esc = new Set();
      if (DapDuty.iAmDap(c, db)) for (const a of DapDuty.overdue(db)) esc.add(a.get("id"));
      const open = new TreeSet();
      for (const a of CriticalLabs.openForMe(c, db)) if (!esc.has(a.get("id"))) open.add(a.get("id"));
      const prev = p.getString("crit_open", "");
      let fresh = 0;
      for (const id of open) if (!(("," + prev + ",").contains("," + id + ","))) fresh++;
      e.putString("crit_open", TextUtils.join(",", [...open]));
      if (fresh > 0 && p.contains("crit_open")) Background.show(c, Background.N_CRIT, "🚨 Critical lab value", fresh === 1 ? "A critical result in your unit needs acknowledgement" : fresh + " critical results in your unit need acknowledgement", CriticalLabs.COLOR, CriticalLabsActivity);
    } catch (ignored) {
      // the alert is optional
    }

    // 9.97: DAP duty. Alerts nobody acknowledged in 15 minutes, wards that just became full, and the report after 7:30 AM
    try {
      if (DapDuty.iAmDap(c, db)) {
        const esc = [];
        for (const a of DapDuty.overdue(db)) esc.push(a.get("id"));
        const prev = p.getString("esc_open", "");
        let fresh = 0;
        for (const id of esc) if (!(("," + prev + ",").includes("," + id + ","))) fresh++;
        e.putString("esc_open", esc.join(","));
        if (fresh > 0) Background.show(c, Background.N_ESCALATE, "⏫ Not acknowledged in 15 min", fresh === 1 ? "An alert in a ward needs the DAP" : fresh + " alerts in the wards need the DAP", Ui.RED, DapActivity);
        const full = DapDuty.full(db).map((w) => w.code);
        const prevF = p.getString("beds_full", "");
        const nowFull = [];
        for (const w of full) if (!(("," + prevF + ",").includes("," + w + ","))) nowFull.push(Db.shortName(w));
        e.putString("beds_full", full.join(","));
        if (nowFull.length > 0 && p.contains("beds_full_seen")) Background.show(c, Background.N_BEDS, "🛏 Ward full", nowFull.join(", ") + (nowFull.length === 1 ? " is" : " are") + " full. Tap to see where a patient can go.", DapDuty.COLOR, DapActivity);
        e.putBoolean("beds_full_seen", true);
      }
      const ended = Dates.admitDay().minusDays(1);
      if (ended.toString() !== p.getString("dap_report_day", "") && (Cloud.isOwner(c) || DapDuty.isMe(c, db, DapDuty.dapOf(db, ended)))) {
        e.putString("dap_report_day", ended.toString());
        if (p.contains("dap_report_seen")) Background.show(c, Background.N_DAPREPORT, "📋 DAP report ready", "Last night's report is made from the records. Check, add issues and send.",
            DapDuty.COLOR, new Intent(c, DapReportActivity).putExtra("day", ended.toString()));
        e.putBoolean("dap_report_seen", true);
      }
    } catch (ignored) {
      // the alert is optional
    }

    // 9.98: a new incident, complaint or shortage, for the HOD's office (no details on the lock screen)
    try {
      if (Cloud.isAdmin(c)) {
        const open = db.rows("SELECT id FROM issues WHERE status='Open'").map((r) => r.get("id"));
        const prev = p.getString("issues_open", "");
        let fresh = 0;
        for (const id of open) if (!(("," + prev + ",").includes("," + id + ","))) fresh++;
        e.putString("issues_open", open.join(","));
        if (fresh > 0 && p.contains("issues_open")) Background.show(c, Background.N_ISSUE, "📝 New report", fresh === 1 ? "An incident or shortage was reported" : fresh + " incidents or shortages were reported", Issues.INCIDENT_COLOR, HodDeskActivity);
      }
    } catch (ignored) {
      // the alert is optional
    }

    // 10.0: PG Arena: a faculty like or a Wall of Fame entry for this person, the day's duel and the month card (no details on the lock screen)
    try {
      const mine = [];
      for (const k of Kudos.toMe(c, db)) mine.push("k" + k.get("id"));
      const sid = Cloud.myStaff(c);
      const meN = Wrapped.norm(Reminders.myName(c, db));
      for (const f of db.rows("SELECT id, staff_id, name FROM " + Fame.TABLE))
        if (sid > 0 && String(sid) === f.get("staff_id") || Wrapped.names(f.get("name"), meN)) mine.push("f" + f.get("id"));
      mine.sort();
      const prev = p.getString("arena_mine", "");
      let likes = 0, fame = 0;
      for (const id of mine) if (!(("," + prev + ",").includes("," + id + ","))) { if (id.startsWith("k")) likes++; else fame++; }
      e.putString("arena_mine", mine.join(","));
      if (p.contains("arena_mine")) {
        if (fame > 0) Background.show(c, Background.N_KUDOS, "🏅 You are on the Wall of Fame", "Faculty named you. Tap to see.", Fame.COLOR, FameActivity);
        else if (likes > 0) Background.show(c, Background.N_KUDOS, "👏 Applause! A faculty member liked your work", likes === 1 ? "Tap to see what they liked" : likes + " new likes. Tap to see.", Kudos.COLOR, ArenaActivity);
      }
      const role = Cloud.role(c);
      const pg = "pg" === role || "crmi" === role;
      const dd = Duel.day();
      if (pg && dd !== p.getString("duel_told", "") && Dates.time().getHour() < 22 && Duel.mine(c, db, dd) == null) {
        e.putString("duel_told", dd);
        Background.show(c, Background.N_DUEL, "⚔ Today's Daily Duel is ready", "5 quick questions, 20 seconds each. Beat your unit!", Duel.COLOR, DuelActivity);
      }
      const lastMonth = Dates.today().minusMonths(1).toString().substring(0, 7);
      if (sid > 0 && Dates.today().getDayOfMonth() <= 3 && lastMonth !== p.getString("month_told", "")) {
        e.putString("month_told", lastMonth);
        Background.show(c, Background.N_MONTH, "📊 Your month in medicine is ready", Wrapped.period(lastMonth) + " in story cards. Share it on your status.", 0xFF7C3AED,
            new Intent(c, WrappedActivity).putExtra("who", Wrapped.ME).putExtra("year", lastMonth));
      }
    } catch (ignored) {
      // the alert is optional
    }

    // 10.10: a code blue running anywhere (ward and bed, never the name), with its own vibration
    try {
      const cb = CodeBlue.running(db);
      const startMs = cb == null ? 0 : Ui.toLong(cb.get("start_ms"), 0);
      if (cb != null && System.currentTimeMillis() - startMs < 15 * 60000 && Ui.nz(cb.get("id")) !== p.getString("code_told", "")) {
        e.putString("code_told", Ui.nz(cb.get("id")));
        const pt = db.row("SELECT location, bed FROM patients WHERE id=?", Ui.nz(cb.get("patient_id")));
        const where = pt != null ? Protocols.where(pt) : Db.shortName(Ui.nz(cb.get("ward")));
        if (Ui.nz(cb.get("by_name")) !== CallDutyActivity.myName(c))
          Background.show(c, Background.N_CODE, "🚨 CODE BLUE", (where.isEmpty() ? "A code blue is running" : where) + ". Tap to open the recorder.", CodeBlue.COLOR,
              new Intent(c, CodeBlueActivity).putExtra("patient", Ui.nz(cb.get("patient_id"))));
      }
    } catch (ignored) {
      // optional
    }

    // 10.10: teaching moments for the PGs, and a rare case admitted anywhere (ward and bed, never the name)
    try {
      const role = Cloud.role(c);
      const doctor = "pg" === role || "crmi" === role || SignOff.faculty(c) || Cloud.isAdmin(c);
      const tSeen = p.getString("teach_seen", "");
      if (tSeen.isEmpty()) e.putString("teach_seen", Dates.todayIso() + " " + Dates.now());
      else {
        let tMax = tSeen, line = null;
        const me = CallDutyActivity.myName(c);
        let n = 0;
        for (const t of TeachPoints.since(db, tSeen)) {
          if (Ui.nz(t.get("time")).compareTo(tMax) > 0) tMax = t.get("time");
          if (Ui.nz(t.get("by_name")) === me) continue;
          n++;
          line = TeachPoints.where(t) + ": " + Ui.nz(t.get("point"));
        }
        e.putString("teach_seen", tMax);
        if (n > 0 && ("pg" === role || "crmi" === role || Cloud.isOwner(c)))
          Background.show(c, Background.N_TEACH, "💡 Teaching moment", n === 1 ? line : n + " new teaching points. Latest: " + line, TeachPoints.COLOR, TeachActivity);
      }
      const rare = [];
      let rareLine = null;
      for (const r of RareCase.inWards(db)) {
        rare.push(String(r.get("id")));
        if (!(("," + p.getString("rare_in", "") + ",").contains("," + r.get("id") + ","))) rareLine = r.get("rare_name") + " in " + Protocols.where(r);
      }
      const first = !p.contains("rare_in");
      e.putString("rare_in", rare.sort().join(","));
      if (!first && rareLine != null && doctor)
        Background.show(c, Background.N_RARE, "🦓 Rare case in the department", rareLine + ". Go and see it while the patient is here.", RareCase.COLOR, RareCaseActivity);
    } catch (ignored) {
      // optional
    }

    // early warning: a patient newly at a red NEWS2 (never names or numbers on the lock screen)
    try {
      if (SessionAttendance.canRun(c) || Cloud.isAdmin(c)) {
        const red = [];
        for (const f of Ews.flagged(db)) if (f.result.red()) red.push(f.patient.get("id"));
        red.sort();
        const prev = p.getString("ews_red", "");
        let fresh = 0;
        for (const id of red) if (!(("," + prev + ",").includes("," + id + ","))) fresh++;
        e.putString("ews_red", red.join(","));
        if (fresh > 0 && p.contains("ews_red")) Background.show(c, Background.N_EWS, "🔴 Early warning", fresh == 1 ? "1 patient has a high NEWS2 score" : fresh + " patients have a high NEWS2 score", Ui.RED, MainActivity);
      }
    } catch (ignored) {
      // the warning is optional
    }

    // deterioration watch (8.30): a patient newly with a red worsening trend, and the 7:30 AM morning brief once a day
    try {
      if (SessionAttendance.canRun(c) || Cloud.isAdmin(c) || "pg" === Cloud.role(c)) {
        const red = [];
        for (const h of Watch.all(db)) if (Watch.anyRed(h.flags)) red.push(h.patient.get("id"));
        red.sort();
        const prev = p.getString("watch_red", "");
        let fresh = 0;
        for (const id of red) if (!(("," + prev + ",").includes("," + id + ","))) fresh++;
        e.putString("watch_red", red.join(","));
        if (fresh > 0 && p.contains("watch_red")) Background.show(c, Background.N_WATCH, "⚠ Deterioration watch", fresh == 1 ? "1 patient's trend is getting worse" : fresh + " patients' trends are getting worse", Ui.RED, WatchActivity);
        const today = Dates.todayIso();
        if (!Dates.time().isBefore(MorningBrief.START) && Dates.time().getHour() < 13 && !today.equals(p.getString("brief_day", ""))) {
          e.putString("brief_day", today);
          const first = MorningBrief.build(db, MorningBrief.myUnit(c, db), LocalDateTime.of(Dates.today(), Dates.time())).first.size();
          Background.show(c, Background.N_BRIEF, "🌅 Morning brief is ready", first == 0 ? "A quiet night: nobody flagged to see first" : first + (first == 1 ? " patient" : " patients") + " to see first on the ward round", MorningBrief.COLOR, MorningBriefActivity);
        }
      }
    } catch (ignored) {
      // optional
    }

    // pending results (8.60): a test newly overdue, or a result newly back and not yet seen (no names on the lock screen)
    try {
      if (SessionAttendance.canRun(c) || Cloud.isAdmin(c) || "pg" === Cloud.role(c)) {
        const due = [];
        for (const r of Results.overdue(db, Protocols.now())) due.push("o" + r.get("id"));
        for (const r of Results.unseen(db)) due.push("b" + r.get("id"));
        due.sort();
        const prev = p.getString("results_due", "");
        let late = 0, back = 0;
        for (const id of due) if (!(("," + prev + ",").includes("," + id + ","))) { if (id.startsWith("o")) late++; else back++; }
        e.putString("results_due", due.join(","));
        if (late + back > 0 && p.contains("results_due")) {
          const bits = [];
          if (late > 0) bits.push(late + (late == 1 ? " test is overdue" : " tests are overdue"));
          if (back > 0) bits.push(back + (back == 1 ? " result is back" : " results are back") + " to be seen");
          Background.show(c, Background.N_RESULTS, "🧪 Pending results", bits.join(", "), Results.COLOR, ResultsActivity);
        }
      }
    } catch (ignored) {
      // optional
    }

    // the handover from last night's team, once each morning
    const day = Dates.admitDay().minusDays(1).toString();
    const items = db.num("SELECT COUNT(*) FROM handovers WHERE day=?", day);
    if (items > 0 && !day.equals(p.getString("handover_day", ""))) {
      e.putString("handover_day", day);
      Background.show(c, Background.N_HANDOVER, "🔁 Handover from last night's team", items + (items == 1 ? " patient" : " patients")
        + " to see first: sick patients, pending tests and plans", Ui.TEAL, HandoverActivity);
    }

    // waiting for this person
    const lines = [];
    let total = 0;
    const ap = Approvals.canApproveAny(c) ? Approvals.waitingForMe(c, db) : 0;
    if (ap > 0) lines.add(ap + " new " + (ap == 1 ? "entry" : "entries") + " to approve");
    total += ap;
    if (SessionAttendance.canRun(c)) {
      let lv = 0;
      for (const r of db.rows("SELECT ap_status, prof_status, nodal_status, hod_status FROM pg_leaves"))
        if (PgLeaveActivity.overall(r).equals("Awaiting approval")) lv++;
      if (lv > 0) lines.add(lv + " PG leave " + (lv == 1 ? "letter" : "letters") + " awaiting approval");
      const lb = Logbook.waitingToSign(c, db);
      if (lb > 0) lines.add(lb + " logbook " + (lb == 1 ? "procedure" : "procedures") + " to sign");
      total += lv + lb;
    }
    const sw = Swaps.waitingFor(db, c);
    if (sw[0] > 0) lines.add(sw[0] + " duty " + (sw[0] == 1 ? "swap" : "swaps") + " waiting for your reply");
    if (sw[1] > 0) lines.add(sw[1] + " duty " + (sw[1] == 1 ? "swap" : "swaps") + " waiting for your approval");
    total += sw[0] + sw[1];
    const dq = Doubts.waitingForMe(c, db);
    if (dq > 0) lines.add(dq + " PG " + (dq === 1 ? "doubt needs" : "doubts need") + " an answer");
    total += dq;
    const um = UnitMoves.waitingForMe(c, db).size();
    if (um > 0) lines.add(um + (um == 1 ? " case" : " cases") + " another unit asks your unit to take over");
    total += um;
    const ex = ExamCases.waitingForMe(c, db).size();
    if (ex > 0) lines.add(ex + " exam " + (ex == 1 ? "case" : "cases") + " for another unit's students to allow");
    total += ex;
    if (Cloud.isAdmin(c)) {
      const fl = db.num("SELECT COUNT(*) FROM faculty_leaves WHERE status='Applied'");
      if (fl > 0) lines.add(fl + " faculty leave " + (fl == 1 ? "request" : "requests"));
      total += fl;
    }
    const before = p.getInt("waiting", -1);
    e.putInt("waiting", total);
    if (before >= 0 && total > before) {
      const s = new StringBuilder();
      for (const l of lines) s.append(s.length() == 0 ? "" : "\n").append(l);
      Background.show(c, Background.N_WAITING, "Waiting for you · " + total, s.toString(), Ui.AMBER, MainActivity);
    }
    e.apply();
  }

  static channel(c) {
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null || Build.VERSION.SDK_INT < 26) return;
    const ch = new NotificationChannel(Background.CHANNEL, "Urgent messages and approvals", NotificationManager.IMPORTANCE_HIGH);
    ch.setDescription("HOD urgent messages, the morning handover and things waiting for you, even when the app is closed");
    nm.createNotificationChannel(ch);
  }

  /** open: a screen class or an Intent. */
  static show(c, id, title, text, color, open) {
    if (typeof open === 'function') open = new Intent(c, open);
    Background.channel(c);
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null) return;
    open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
    const pi = PendingIntent.getActivity(c, id, open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const b = new Notification.Builder(c, Background.CHANNEL);
    b.setSmallIcon(R.drawable.ic_notice)
      .setContentTitle(title)
      .setContentText(text.contains("\n") ? text.substring(0, text.indexOf('\n')) : text)
      .setStyle(new Notification.BigTextStyle().bigText(text))
      .setShowWhen(true)
      .setColor(color)
      .setAutoCancel(true)
      .setContentIntent(pi);
    if (Build.VERSION.SDK_INT < 26) b.setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_ALL);
    try {
      if (Notify.on(c)) {
        nm.notify(id, b.build());
        const bz = Buzz.forNotification(id);
        if (bz != null) Buzz.buzz(c, bz);   // 10.10: its own vibration pattern
      }
    } catch (ignored) {
      // notifications not allowed on this phone
    }
  }

  /** Android 13 and later: asks once for permission to show notifications, so alerts can reach a closed app. */
  static askOnce(a) {
    if (Build.VERSION.SDK_INT < 33 || !Cloud.active(a)) return;
    if (a.checkSelfPermission("android.permission.POST_NOTIFICATIONS") == PackageManager.PERMISSION_GRANTED) return;
    if (Background.prefs(a).getBoolean("asked", false)) return;
    Background.prefs(a).edit().putBoolean("asked", true).apply();
    a.requestPermissions(["android.permission.POST_NOTIFICATIONS"], 78);
  }
}
;
