/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Shared screen plumbing: gradient header, database access, redraw on resume and common rows. */
class Base extends Activity {
  constructor() {
    super();
    this.db = null;
    this._scroll = null;
    /** True while the bars are slid away; kept across redraws so a refresh does not bring them back. */
    this.barsHidden = false;
    this.titleText = "";          // Java: private CharSequence title
    this.subtitle = null;
    this.headerColors = Ui.HERO;
    this._actionLabel = null;
    this._actionListener = null;
    this._ticker = new Handler(Looper.getMainLooper());
    this._tick = {
      run: () => {
        Sync.kick(this);
        this._ticker.postDelayed(this._tick, 30000);
      }
    };
    this._cloudBadge = null;
    /** Pages are kept to this width on tablets so lines stay readable (8.10); a screen with two panes raises it. */
    this.maxWidthDp = 880;
  }

  /** A tablet or a phone on its side: wide enough for two panes. Web: the width of the app's frame. */
  static wide(c) {
    const el = document.getElementById('app');
    return (el && el.clientWidth ? el.clientWidth : c.getResources().getConfiguration().screenWidthDp) >= 720;
  }

  onCreate(b) {
    super.onCreate(b);
    Look.apply(this);
    Crashes.install(this);
    Crashes.screen = this.constructor.name;
    this.db = Db.get(this);
    if (!(this instanceof AccountActivity) && Cloud.loginRequired(this)) { Cloud.openLogin(this); this.finish(); }
    else if (AdminControl.screenOff(this, this.db, this.constructor.name)) {
      Ui.toast(this, "The admin has turned this section off");
      this.finish();
    }
  }

  /** False on the first-page sign-in, which has nowhere to go back to. */
  showBack() { return true; }

  onResume() {
    super.onResume();
    Crashes.screen = this.constructor.name;
    if (!(this instanceof AccountActivity) && Cloud.loginRequired(this)) { Cloud.openLogin(this); this.finish(); return; }
    if (!(this instanceof LockActivity)) {
      if (Lock.needed(this)) { Lock.open(this); return; }
      Lock.shown();
    }
    this.render();
    Sync.setListener({
      synced: (changed) => {
        if (this.isFinishing()) return;
        if (!(this instanceof AccountActivity) && Cloud.loginRequired(this)) { Cloud.openLogin(this); this.finish(); return; }
        if (changed && this.liveRefresh()) this.render();
        else this.refreshCloudBadge();
      }
    });
    Sync.kick(this);
    Reminders.schedule(this);
    Background.schedule(this);
    try {
      Live.start(this);
    } catch (e) {
      // instant alerts are optional
    }
    this._ticker.removeCallbacks(this._tick);
    this._ticker.postDelayed(this._tick, 30000);
  }

  onPause() {
    super.onPause();
    if (!(this instanceof LockActivity)) Lock.hidden();
    Sync.setListener(null);
    this._ticker.removeCallbacks(this._tick);
  }

  /** Whether this screen may redraw itself when records arrive from other phones (not while someone is typing). */
  liveRefresh() {
    return true;
  }

  refreshCloudBadge() {
    const cloudBadge = this._cloudBadge;
    if (cloudBadge == null) return;
    const pending = this.db.pending();
    const err = Cloud.prefs(this).getString("last_error", "");
    cloudBadge.setText(SyncStatus.chip(pending, err));
    cloudBadge.setBackground(Ui.round(this, !err.isEmpty() ? 0x66F59E0B : pending > 0 ? 0x40FFFFFF : 0x26FFFFFF, 14));
  }

  /** abstract void render(); */
  render() {}

  /** Profile photos (People, 9.00) come back here on any screen; screens with their own results call super first. */
  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    People.onResult(this, req, res, data);
    VoiceInput.onResult(req, res, data);
    if (req === Album.REQ_PICK && res === RESULT_OK && data != null) {
      const n = Album.onPicked(this, this.db, data);
      Ui.toast(this, n === 0 ? "No photos were added" : n + (n === 1 ? " photo added to " : " photos added to ") + Album.pendingAlbum);
      this.render();
    }
  }

  /** Every screen gets the ✨ Copilot button over its content (8.90). */
  setContentView(v) {
    super.setContentView(v);
    Copilot.attach(this);
  }

  onTitleChanged(t, color) {
    super.onTitleChanged(t, color);
    this.titleText = t;
  }

  headerColor(color) {
    this.headerColors = Ui.shades(color);
  }

  /** A text button shown at the right of the header. */
  headerAction(label, l) {
    this._actionLabel = label;
    this._actionListener = l;
  }

  header() {
    const headerColors = this.headerColors;
    this.getWindow().setStatusBarColor(headerColors[0]);
    const h = Ui.h(this);
    h.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,
      headerColors.length > 1 ? headerColors : [headerColors[0], headerColors[0]]));
    h.setPadding(Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 12));
    h.setElevation(Ui.dp(this, 4));
    if (!(this instanceof MainActivity) && this.showBack()) {
      const back = new ImageView(this);
      back.setImageResource(R.drawable.ic_back);
      back.setColorFilter(Color.WHITE);
      const p = Ui.dp(this, 10);
      back.setPadding(p, p, p, p);
      back.setBackground(Ui.round(this, 0x00FFFFFF, 22));
      Ui.ripple(back, 0x44FFFFFF);
      back.setOnClickListener({ onClick: (v) => { this.finish(); } });
      h.addView(back, Ui.lp(Ui.dp(this, 44), Ui.dp(this, 44)));
    } else {
      h.setPadding(Ui.dp(this, 18), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12));
    }
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 4), 0, Ui.dp(this, 8), 0);
    const tt = Ui.tv(this, String(this.titleText == null ? "" : this.titleText), 20, Color.WHITE, true);
    tt.setSingleLine(true);
    tt.setEllipsize(TextUtils.TruncateAt.END);
    t.addView(tt);
    if (this.subtitle != null && !this.subtitle.isEmpty()) t.addView(Ui.tv(this, this.subtitle, 13, 0xD9FFFFFF, false));
    h.addView(t, Ui.weight(1));
    this._cloudBadge = null;
    if (Cloud.active(this) && !(this instanceof AccountActivity) && !(this instanceof LockActivity)) {
      const cloudBadge = this._cloudBadge = Ui.tv(this, "☁", 13, Color.WHITE, true);
      cloudBadge.setPadding(Ui.dp(this, 10), Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 6));
      cloudBadge.setOnClickListener({ onClick: (v) => { SyncStatus.dialog(this); } });
      this.refreshCloudBadge();
      h.addView(cloudBadge);
      if (this._actionLabel != null) Ui.margins(cloudBadge, 0, 0, 8, 0);
    }
    if (this._actionLabel != null) {
      const a = Ui.tv(this, this._actionLabel, 14, Color.WHITE, true);
      a.setBackground(Ui.round(this, 0x33FFFFFF, 18));
      a.setPadding(Ui.dp(this, 14), Ui.dp(this, 7), Ui.dp(this, 14), Ui.dp(this, 7));
      Ui.ripple(a, 0x44FFFFFF);
      a.setOnClickListener(this._actionListener);
      h.addView(a);
    }
    return h;
  }

  /** Replaces the screen with header + scrolling page, keeping the scroll position across redraws. */
  setPage(content) {
    const y = this._scroll == null ? 0 : this._scroll.getScrollY();
    content.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 28));
    const scroll = this._scroll = Ui.scroll(this, Base.capped(this, content, this.maxWidthDp));
    if (this.pageBg) scroll.setBackgroundColor(this.pageBg);   // 10.31: a screen with its own page colour (the dark intercom)
    const top = Ui.v(this);
    top.addView(this.header(), Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    // 10.4: a shared-database phone without internet says so on every screen
    const off = this instanceof AccountActivity || this instanceof LockActivity ? null : Net.bar(this);
    if (off != null) top.addView(off, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    // 10.42: bottomBar, a bar fixed at the bottom of the screen (the PG leave page's gold band)
    this.setContentView(this.floatingBars(scroll, top, this.bottomBar || null));
    Undo.attach(this);
    scroll.post({ run: () => { scroll.scrollTo(0, y); } });
  }

  /**
   * 10.19 (user asked, for more room on phones, mostly sideways): the header (with the offline line) and the bottom bar float over
   * the page. Scrolling down slides them away; scrolling up a little, or reaching the top or the end, brings them back.
   */
  floatingBars(sv, top, bottom) {
    const frame = new FrameLayout(this);
    frame.setBackground(new Glass.Backdrop());
    sv.setClipToPadding(false);
    frame.addView(sv, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
    frame.addView(top, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.TOP));
    if (bottom != null) frame.addView(bottom, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.BOTTOM));
    // the page starts below the header and ends above the bottom bar, so nothing is covered while the bars show
    const pad = { onLayoutChange: () => {
      const pt = top.getHeight(), pb = bottom == null ? 0 : bottom.getHeight();
      if (sv.getPaddingTop() !== pt || sv.getPaddingBottom() !== pb) sv.setPadding(0, pt, 0, pb);
      if (this.barsHidden) {
        top.setTranslationY(-pt);
        if (bottom != null) bottom.setTranslationY(pb);
      }
    } };
    top.addOnLayoutChangeListener(pad);
    if (bottom != null) bottom.addOnLayoutChangeListener(pad);
    let last = -1, run = 0;
    sv.setOnScrollChangeListener({ onScrollChange: (v, x, y) => {
      // the first call is the redraw putting the page back where it was: it changes nothing
      if (last < 0) { last = y; return; }
      const dy = y - last;
      last = y;
      if (dy === 0) return;
      run = (run > 0) === (dy > 0) ? run + dy : dy;
      const step = Ui.dp(this, 24);
      const show = y <= top.getHeight() || !sv.canScrollVertically(1) || run < -step;
      if (show && this.barsHidden) {
        this.barsHidden = false;
        Base.slide(top, 0);
        if (bottom != null) Base.slide(bottom, 0);
      } else if (!show && !this.barsHidden && run > step) {
        this.barsHidden = true;
        Base.slide(top, -top.getHeight());
        if (bottom != null) Base.slide(bottom, bottom.getHeight());
      }
    } });
    return frame;
  }

  static slide(v, y) {
    v.animate().translationY(y).setDuration(220).start();
  }

  /** The page centred at no more than maxDp wide (only on screens wider than that). */
  /** Home tiles in a row: 4 on a phone, up to 8 on a wide tablet, so tiles keep their size when the page fills the screen. */
  static tileCols(c) {
    return Math.max(4, Math.min(8, Math.floor(c.getResources().getConfiguration().screenWidthDp / 150)));
  }

  /** Ward census cards in a row: 2 on a phone, up to 4 on a wide tablet. */
  static censusCols(c) {
    return Math.max(2, Math.min(4, Math.floor(c.getResources().getConfiguration().screenWidthDp / 330)));
  }

  static capped(c, content, maxDp) {
    // 9.87 (the admin's wish): pages fill the whole tablet screen; home tiles add columns instead (tileCols)
    if (Base.FULL_WIDTH) return content;
    const el = document.getElementById('app');
    const w = el && el.clientWidth ? el.clientWidth : c.getResources().getConfiguration().screenWidthDp;
    if (w <= maxDp + 40) return content;
    const wrap = Ui.v(c);
    wrap.setGravity(Gravity.CENTER_HORIZONTAL);
    wrap.addView(content, new LinearLayout.LayoutParams(Ui.dp(c, maxDp), ViewGroup.LayoutParams.WRAP_CONTENT));
    return wrap;
  }

  open(cls, ...kv) {
    if (kv.length === 1 && Array.isArray(kv[0])) kv = kv[0];
    const i = new Intent(this, cls);
    for (let k = 0; k + 1 < kv.length; k += 2) i.putExtra(kv[k], kv[k + 1]);
    this.startActivity(i);
  }

  opener(cls, ...kv) {
    if (kv.length === 1 && Array.isArray(kv[0])) kv = kv[0];
    return new Base.Opener(this, cls, kv);
  }

  // ---------- rows shared by several screens ----------

  static sexLabel(s) {
    return "F" === s ? "Female" : "Male";
  }

  static where(p) {
    const loc = p.get("location");
    if (Db.isSpecial(loc)) return Db.shortName(loc) + " (parent " + p.get("home_unit") + ")";
    if (Db.KDP === loc) return "Kandiyaperi " + ("F" === p.get("sex") ? "female" : "male") + " ward";
    return loc + " " + ("F" === p.get("sex") ? "female" : "male") + " ward";
  }

  static statusPill(c, p) {
    const st = p.get("status");
    if (Db.DIED === st) return Ui.pill(c, "Died", Ui.SLATE);
    if (Db.DISCHARGED === st) return Ui.softPill(c, "Discharged", Ui.GREEN);
    const loc = p.get("location");
    if (Db.isSpecial(loc) || Db.KDP === loc) return Ui.pill(c, Db.shortName(loc), Ui.unitColor(loc));
    return Ui.softPill(c, "In ward", Ui.PRIMARY);
  }

  /** 10.39: the patient card in the user's "Female patients" picture; extra goes under the diagnosis, action at the bottom right. */
  patientRow(p, extra = null, action = null) {
    const db = this.db;
    const card = Ui.card(this);
    card.setBackground(Ui.outline(this, Color.WHITE, 0xFFE2E8F0, 18));
    card.setOrientation(LinearLayout.HORIZONTAL);
    card.setBaselineAligned(false);
    card.setPadding(0, 0, Ui.dp(this, 12), 0);
    const stripe = new View(this);
    stripe.setBackground(Ui.round(this, Ui.unitColor(p.get("location")), 3));
    const sp = new LinearLayout.LayoutParams(Ui.dp(this, 6), ViewGroup.LayoutParams.MATCH_PARENT);
    sp.setMargins(Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 10));
    card.addView(stripe, sp);

    const body = Ui.v(this);
    body.setPadding(0, Ui.dp(this, 12), 0, Ui.dp(this, 12));
    const age = Ui.nz(p.get("age")).isEmpty() ? "" : p.get("age") + " y, ";
    body.addView(Ui.tv(this, p.get("name") + "  ·  " + age + Base.sexLabel(p.get("sex")), 18, PatientRowDesign.NAVY, true));
    const chips = Ui.h(this);
    if (!Ui.nz(p.get("ip_no")).isEmpty()) chips.addView(PatientRowDesign.chip(this, R.drawable.ic_badge, "IP " + p.get("ip_no")));
    if (chips.getChildCount() > 0) {
      body.addView(chips);
      Ui.margins(chips, 0, 6, 0, 0);
    }
    body.addView(PatientRowDesign.hLine(this));
    let line = "Adm " + NoticeDesign.date(p.get("admit_date"));
    if (!Ui.nz(p.get("outcome_date")).isEmpty()) line += "  →  " + NoticeDesign.date(p.get("outcome_date"));
    body.addView(PatientRowDesign.line(this, R.drawable.ic_calendar, line, 1));
    if (!Ui.nz(p.get("diagnosis")).isEmpty()) body.addView(PatientRowDesign.line(this, R.drawable.ic_heart, p.get("diagnosis"), 2));
    if (extra != null) body.addView(extra);
    card.addView(body, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
    card.addView(PatientRowDesign.vLine(this));

    const right = Ui.v(this);
    right.setGravity(Gravity.CENTER_HORIZONTAL | Gravity.CENTER_VERTICAL);
    right.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 10));
    right.addView(PatientRowDesign.placePill(this, p));
    if (Db.isSpecial(p.get("location")) && !Ui.nz(p.get("home_unit")).isEmpty() && Db.IN === p.get("status")) {
      const par = PatientRowDesign.soft(this, "Parent : " + p.get("home_unit"));
      right.addView(par);
      Ui.margins(par, 0, 6, 0, 0);
    }
    if (!Ui.nz(p.get("bed")).isEmpty() && Db.IN === p.get("status")) {
      const bd = PatientRowDesign.soft(this, "Bed " + p.get("bed"));
      right.addView(bd);
      Ui.margins(bd, 0, 6, 0, 0);
    }
    const tasks = p.get("id") == null ? 0 : Tasks.pending(db, Long.parseLong(p.get("id")));
    if (tasks > 0) {
      const tk = Ui.softPill(this, "⏳ " + tasks + (tasks === 1 ? " task" : " tasks"), Tasks.COLOR);
      right.addView(tk);
      Ui.margins(tk, 0, 4, 0, 0);
    }
    const cat = Ui.nz(p.get("category"));
    if (Db.HEMOPHILIA === cat || Db.STROKE === cat) {
      const cg = Ui.softPill(this, Db.HEMOPHILIA === cat ? "🩸 Hemophilia" : "🧠 Stroke", Db.HEMOPHILIA === cat ? Ui.PINK : Ui.PURPLE);
      right.addView(cg);
      Ui.margins(cg, 0, 4, 0, 0);
    }
    if (p.get("id") != null && Db.IN === p.get("status") && p.containsKey("admit_date") && Readmit.previous(db, p) != null) {
      const ra = Ui.softPill(this, "↩ Readmitted", Readmit.COLOR);
      right.addView(ra);
      Ui.margins(ra, 0, 4, 0, 0);
    }
    if (p.get("id") != null && Db.IN === p.get("status") && !p.containsKey("at_loc")) {
      const cd = Countdown.pill(this, db, Long.parseLong(p.get("id")));
      if (cd != null) {
        right.addView(cd);
        Ui.margins(cd, 0, 4, 0, 0);
      }
      if (p.containsKey("diagnosis") && RareCase.of(p) != null) {
        const rr = Ui.softPill(this, "🦓 Rare", RareCase.COLOR);
        right.addView(rr);
        Ui.margins(rr, 0, 4, 0, 0);
      }
    }
    if (p.get("id") != null && Db.IN === p.get("status") && "1" === p.get("quick")) {
      const qk = Ui.softPill(this, "⚡ Fill details", FormActivity.QUICK_COLOR);
      right.addView(qk);
      Ui.margins(qk, 0, 4, 0, 0);
    }
    if (p.get("id") != null && Db.IN === p.get("status") && ExamCases.forPatient(db, Long.parseLong(p.get("id"))) != null) {
      const ex = Ui.softPill(this, "🎓 Exam case", ExamCases.COLOR);
      right.addView(ex);
      Ui.margins(ex, 0, 4, 0, 0);
    }
    if (p.get("id") != null && Db.IN === p.get("status")) {
      const ew = Ews.latest(db, Long.parseLong(p.get("id")));
      if (ew != null && ew.flagged()) {
        const nw = Ui.softPill(this, "NEWS " + ew.total + (ew.partial ? "*" : ""), ew.color);
        right.addView(nw);
        Ui.margins(nw, 0, 4, 0, 0);
      }
      const wf = Watch.check(db, Long.parseLong(p.get("id")), LocalDateTime.of(Dates.today(), Dates.time()), false);
      if (!wf.isEmpty()) {
        const wt = Ui.softPill(this, "⚠ Watch", Watch.anyRed(wf) ? Ui.RED : Watch.COLOR);
        right.addView(wt);
        Ui.margins(wt, 0, 4, 0, 0);
      }
    }
    if ("1" === p.get("cmchis")) {
      const cm = Ui.softPill(this, "CMCHIS", Ui.TEAL);
      right.addView(cm);
      Ui.margins(cm, 0, 4, 0, 0);
    }
    if (action != null) {
      right.addView(action);
      Ui.margins(action, 0, 8, 0, 0);
    }
    card.addView(right, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.MATCH_PARENT));
    Ui.ripple(card, Ui.alpha(Ui.PRIMARY, 0x22));
    card.setOnClickListener(this.opener(PatientActivity, "id", p.get("id")));
    return card;
  }

  emptyNote(s) {
    const t = Ui.muted(this, s);
    t.setGravity(Gravity.CENTER);
    t.setPadding(Ui.dp(this, 24), Ui.dp(this, 18), Ui.dp(this, 24), Ui.dp(this, 18));
    return t;
  }

  /**
   * A small list card: coloured pill, title, subtitle, right-side text.
   * maxLines: how many subtitle lines show (the AI and watch lists show every reason); 4 when left out.
   */
  entryCard(pill, pillColor, title, sub, right, l, maxLines) {
    if (maxLines === undefined) maxLines = 4;
    const card = Ui.card(this);
    const top = Ui.h(this);
    if (pill != null) top.addView(Ui.softPill(this, pill, pillColor));
    const sp = new View(this);
    top.addView(sp, new LinearLayoutParams(0, 1, 1));
    if (right != null) top.addView(Ui.muted(this, right));
    card.addView(top);
    const t = Ui.tv(this, title, 16, Ui.TEXT, true);
    card.addView(t);
    Ui.margins(t, 0, 6, 0, 0);
    if (sub != null && !sub.isEmpty()) {
      const s = Ui.muted(this, sub);
      s.setMaxLines(maxLines);
      card.addView(s);
    }
    if (l != null) {
      Ui.ripple(card, Ui.alpha(pillColor, 0x1A));
      card.setOnClickListener(l);
    }
    return card;
  }

  // ---------- weekly academic checklist (home + academic screens) ----------

  /** States of a weekly item. */
  static INFO = 0;
  static DONE = 1;
  static DUE = 2;
  static MISSED = 3;

  /** A phone-width screen (9.92): cards stack and the academics header wraps so names are never cut off. */
  static narrow(c) {
    const el = document.getElementById('app');
    return (el && el.clientWidth ? el.clientWidth : c.getResources().getConfiguration().screenWidthDp) < 600;
  }

  static stateColor(state) {
    return state === Base.DONE ? Ui.GREEN : state === Base.DUE ? Ui.AMBER : state === Base.MISSED ? Ui.RED : 0xFF64748B;
  }

  /**
   * One weekly item as a pastel 3D tile: a glossy sphere icon, a progress ring (done of target),
   * the name and when it runs, a status and a one-line detail. Tiles sink when pressed.
   */
  scheduleLine(card, title, when, detail, state, done, target, openArgs) {
    const DONE = Base.DONE, DUE = Base.DUE, MISSED = Base.MISSED;
    const key = openArgs.length > 3 ? openArgs[3] : openArgs[1];
    let color, icon;
    switch (key) {
      case "MBBS": color = 0xFF1D4ED8; icon = R.drawable.ic_school; break;
      case "PG": color = 0xFF047857; icon = R.drawable.ic_people; break;
      case "CONF": color = 0xFF7E22CE; icon = R.drawable.ic_mic; break;
      case "JC": color = 0xFFEA580C; icon = R.drawable.ic_book; break;
      case "TOPIC": color = 0xFF0891B2; icon = R.drawable.ic_bulb; break;
      case "SYMP": color = 0xFFCA8A04; icon = R.drawable.ic_trophy; break;
      default: color = 0xFFBE123C; icon = R.drawable.ic_shield; break;
    }
    const wide = "cmchis" === key;
    const stateCol = Base.stateColor(state);
    const stateLabel = state === DONE ? "Done" : state === DUE ? "Due" : state === MISSED ? "Missed" : "Not this week";
    const ink = Ui.mix(color, Color.BLACK, 0.6);

    // 9.91 (the admin's design): a larger glass card per section; two are solid (MBBS teal, Physicon blue), the rest soft pastel
    let face, solid = false, ink2 = ink;
    switch (key) {
      case "MBBS": face = [0xFF4CC3BE, 0xFF2A9BA0, 0xFF1D7F88]; solid = true; break;
      case "PG": face = [0xFFEDF5F1, 0xFFDCE9E3, 0xFFC8DBD2]; ink2 = 0xFF1F3B33; break;
      case "CONF": face = [0xFF3F7BDB, 0xFF2557B0, 0xFF183F86]; solid = true; break;
      case "JC": face = [0xFFFFF0E8, 0xFFFFDCCB, 0xFFFFC9B0]; ink2 = 0xFF7C2D12; break;
      case "TOPIC": face = [0xFFF1F3FF, 0xFFE0E5FD, 0xFFCED6F8]; ink2 = 0xFF1E2A5A; break;
      case "SYMP": face = [0xFFFFF8E6, 0xFFF8EBC8, 0xFFEFDBA6]; ink2 = 0xFF5B4210; break;
      default: face = [Ui.mix(color, Color.WHITE, 0.9), Ui.mix(color, Color.WHITE, 0.8), Ui.mix(color, Color.WHITE, 0.7)]; break;
    }
    if (solid) ink2 = Color.WHITE;
    const sub = solid ? 0xE6FFFFFF : Ui.mix(ink2, Color.WHITE, 0.25);
    const sc = !solid ? stateCol : state === MISSED ? 0xFFFECACA : state === DUE ? 0xFFFDE68A : state === DONE ? 0xFFBBF7D0 : 0xD9FFFFFF;

    const tile = Ui.v(this);
    const bg = new GradientDrawable(GradientDrawable.Orientation.TL_BR, face);
    bg.setCornerRadius(Ui.dp(this, 18));
    bg.setStroke(Ui.dp(this, 1), solid ? 0x59FFFFFF : Ui.mix(face[2], Color.BLACK, 0.08));
    tile.setBackground(bg);
    tile.setPadding(Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10));
    tile.setElevation(Ui.dp(this, 3));
    Glass.softShadow(tile, solid ? face[1] : face[2]);
    tile.setTag(wide ? "wide" : "tile");
    tile.setTag(R.id.tag_state, state);
    tile._title = title;

    // 9.92: on a phone the card stacks (icon above the name) so every name shows in full, even with large text
    const stack = Base.narrow(this) && !wide;
    const tt = Ui.tv(this, title, 16, ink2, true);
    if (stack) tt.setMaxLines(2);
    else {
      tt.setSingleLine(true);
      tt.setEllipsize(TextUtils.TruncateAt.END);
    }
    const head = Ui.h(this);
    head.setGravity(Gravity.CENTER_VERTICAL);
    head.addView(tt, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));
    if (state === DONE) {
      const pill = Ui.tv(this, "Done", 11, solid ? Color.WHITE : 0xFF15803D, true);
      pill.setBackground(Ui.round(this, solid ? 0x40FFFFFF : 0xFFDCFCE7, 10));
      pill.setPadding(Ui.dp(this, 8), Ui.dp(this, 2), Ui.dp(this, 8), Ui.dp(this, 2));
      head.addView(pill);
    }

    const status = Ui.h(this);
    status.setGravity(Gravity.CENTER_VERTICAL);
    const dot = state === DUE ? Slab.pulse(this, sc) : new View(this);
    if (state !== DUE) dot.setBackground(Ui.round(this, sc, 4));
    status.addView(dot, Ui.lp(Ui.dp(this, 7), Ui.dp(this, 7)));
    const sl = Ui.tv(this, stateLabel + (target > 0 ? "  ·  " + done + "/" + target : ""), 12, sc, true);
    sl.setPadding(Ui.dp(this, 5), 0, 0, 0);
    if (!stack) sl.setSingleLine(true);
    status.addView(sl, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));

    const foot = Ui.h(this);
    foot.setGravity(Gravity.CENTER_VERTICAL);
    const dt = Ui.tv(this, wide ? when + " · " + detail : detail, 12, !solid && state === MISSED ? Ui.RED : sub, false);
    if (stack) dt.setMaxLines(2);
    else dt.setSingleLine(true);
    dt.setEllipsize(TextUtils.TruncateAt.END);
    foot.addView(dt, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));
    foot.addView(Ui.tv(this, " ›", 16, sub, true));

    if (stack) {
      const top = Ui.h(this);
      top.setGravity(Gravity.CENTER_VERTICAL);
      const g = new View(this);
      g.setBackground(new Glass.Crystal(this, icon, color));
      top.addView(g, Ui.lp(Ui.dp(this, 46), Ui.dp(this, 46)));
      top.addView(new View(this), new LinearLayout.LayoutParams(0, 1, 1));
      if (state === DONE) {
        head.removeViewAt(head.getChildCount() - 1);
        const pill = Ui.tv(this, "Done", 11, solid ? Color.WHITE : 0xFF15803D, true);
        pill.setBackground(Ui.round(this, solid ? 0x40FFFFFF : 0xFFDCFCE7, 10));
        pill.setPadding(Ui.dp(this, 8), Ui.dp(this, 2), Ui.dp(this, 8), Ui.dp(this, 2));
        top.addView(pill);
      }
      tile.addView(top);
      tile.addView(head);
      Ui.margins(head, 0, 8, 0, 2);
      if (state !== DONE) tile.addView(status);
      tile.addView(foot);
      Ui.margins(foot, 0, 3, 0, 0);
    }
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    const gem = new View(this);
    gem.setBackground(new Glass.Crystal(this, icon, color));
    if (!stack) row.addView(gem, Ui.lp(Ui.dp(this, wide ? 60 : 56), Ui.dp(this, wide ? 60 : 56)));
    const mid = Ui.v(this);
    mid.setPadding(Ui.dp(this, 10), 0, 0, 0);
    if (!stack) {
      mid.addView(head);
      if (state !== DONE) mid.addView(status);
      mid.addView(foot);
      Ui.margins(foot, 0, 2, 0, 0);
      row.addView(mid, Ui.weight(1));
      tile.addView(row);
    }
    if (wide) {
      const bar = new Slab.Progress(this, target <= 0 ? 0 : done / target, done >= target ? Ui.GREEN : color);
      tile.addView(bar, Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 5)));
      Ui.margins(bar, 0, 6, 0, 0);
    }

    const go = {
      onClick: (v) => {
        if ("cmchis" === openArgs[1]) this.open(CmchisActivity);
        else this.open(FormActivity, openArgs);
      }
    };
    Ui.ripple(tile, Ui.alpha(color, 0x22));
    Slab.pressable(tile, 2);
    tile.setOnClickListener(go);
    card.addView(tile);
  }

  /** A header strip for the week (number, dates, how many items are done) above the tiles laid two to a row. */
  tileGrid(collected, weekStart) {
    const INFO = Base.INFO, DONE = Base.DONE, MISSED = Base.MISSED;
    const tiles = [];
    for (let i = 0; i < collected.getChildCount(); i++) if (collected.getChildAt(i).getTag() != null) tiles.add(collected.getChildAt(i));
    collected.removeAllViews();

    const out = Ui.v(this);
    out.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 10), Ui.dp(this, 4));

    let done = 0, missed = 0, counted = 0;
    for (const t of tiles) {
      const st = t.getTag(R.id.tag_state);
      if (st !== INFO) counted++;
      if (st === DONE) done++;
      if (st === MISSED) missed++;
    }
    // 9.91 (the admin's design): title with a search box and a filter, then a dark "Weekly Progress" bar
    const titleRow = Ui.h(this);
    titleRow.setGravity(Gravity.CENTER_VERTICAL);
    titleRow.setPadding(Ui.dp(this, 6), Ui.dp(this, 14), Ui.dp(this, 4), Ui.dp(this, 8));
    const bar = new View(this);
    bar.setBackground(Ui.round(this, 0xFF8B5CF6, 2));
    titleRow.addView(bar, Ui.lp(Ui.dp(this, 4), Ui.dp(this, 22)));
    const ttl = Ui.tv(this, "This week's academics", 19, Ui.TEXT, true);
    ttl.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 6), 0);
    titleRow.addView(ttl, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));
    // 9.92: on a phone the search and filter go on their own line under the full title
    const small = Base.narrow(this);
    let tools = titleRow;
    if (small) {
      out.addView(titleRow);
      tools = Ui.h(this);
      tools.setGravity(Gravity.CENTER_VERTICAL);
      tools.setPadding(Ui.dp(this, 4), 0, Ui.dp(this, 4), Ui.dp(this, 8));
    }
    const search = Ui.h(this);
    search.setGravity(Gravity.CENTER_VERTICAL);
    search.setBackground(Ui.outline(this, 0xF2FFFFFF, 0xFFDDE3EA, 12));
    search.setPadding(Ui.dp(this, 8), 0, Ui.dp(this, 6), 0);
    const lens = new ImageView(this);
    lens.setImageResource(R.drawable.ic_search);
    lens.setColorFilter(0xFF94A3B8);
    search.addView(lens, Ui.lp(Ui.dp(this, 16), Ui.dp(this, 16)));
    const q = new EditText(this);
    q.setHint("Search");
    q.setSingleLine(true);
    q.setTextSize(13);
    q.setBackground(Ui.round(this, 0x00000000, 0));
    q.setText(this.acadQuery || "");
    q.setPadding(Ui.dp(this, 6), Ui.dp(this, 6), 0, Ui.dp(this, 6));
    if (small) search.addView(q, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));
    else search.addView(q, Ui.lp(Ui.dp(this, 92), LinearLayout.LayoutParams.WRAP_CONTENT));
    if (small) tools.addView(search, new LinearLayout.LayoutParams(0, Ui.dp(this, 40), 1));
    else tools.addView(search, Ui.lp(LinearLayout.LayoutParams.WRAP_CONTENT, Ui.dp(this, 36)));
    const tune = new ImageView(this);
    tune.setImageResource(R.drawable.ic_tune);
    tune.setPadding(Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8));
    const tp = Ui.lp(Ui.dp(this, small ? 40 : 36), Ui.dp(this, small ? 40 : 36));
    tp.leftMargin = Ui.dp(this, 8);
    tools.addView(tune, tp);
    out.addView(tools);

    const head = Ui.h(this);
    head.setGravity(Gravity.CENTER_VERTICAL);
    const hb = new GradientDrawable(GradientDrawable.Orientation.TL_BR, [0xFF3B4656, 0xFF1E2633, 0xFF0F141C]);
    hb.setCornerRadius(Ui.dp(this, 18));
    hb.setStroke(Ui.dp(this, 1), 0x33FFFFFF);
    head.setBackground(hb);
    head.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
    head.setElevation(Ui.dp(this, 4));
    const wkNo = Ui.tv(this, "WK\n" + weekStart.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR), 13, 0xFFFBBF24, true);
    wkNo.setGravity(Gravity.CENTER);
    wkNo.setLineSpacing(0, 0.9);
    wkNo.setBackground(Ui.outline(this, 0xFF2A2416, 0xFFD4A72C, 10));
    head.addView(wkNo, Ui.lp(Ui.dp(this, 44), Ui.dp(this, 44)));
    const wp = Ui.tv(this, "Weekly Progress", 17, Color.WHITE, true);
    wp.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    const right = Ui.v(this);
    right.setGravity(small ? Gravity.START : Gravity.END);
    if (small) {
      // 9.92: on a phone the counts and dashes sit under the title, so nothing is cut off
      right.setPadding(Ui.dp(this, 12), 0, 0, 0);
      right.addView(wp);
      wp.setPadding(0, 0, 0, Ui.dp(this, 2));
      head.addView(right, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));
    } else {
      wp.setSingleLine(true);
      head.addView(wp, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1));
    }
    const sumRow = Ui.h(this);
    sumRow.setGravity((small ? Gravity.START : Gravity.END) | Gravity.CENTER_VERTICAL);
    sumRow.addView(Ui.tv(this, done + " of " + counted + " done", 13, 0xFFE2E8F0, true));
    if (missed > 0) {
      sumRow.addView(Ui.tv(this, "  •  ", 13, 0xFFE2E8F0, true));
      sumRow.addView(Ui.tv(this, missed + " missed", 13, 0xFFF87171, true));
    }
    right.addView(sumRow);
    const dots = Ui.h(this);
    dots.setGravity((small ? Gravity.START : Gravity.END) | Gravity.CENTER_VERTICAL);
    for (const t of tiles) {
      const st = t.getTag(R.id.tag_state);
      const d = new View(this);
      d.setBackground(Ui.round(this, st === INFO ? 0x55FFFFFF : Base.stateColor(st), 3));
      const p = Ui.lp(Ui.dp(this, 20), Ui.dp(this, 4));
      p.setMargins(small ? 0 : Ui.dp(this, 4), Ui.dp(this, 7), small ? Ui.dp(this, 4) : 0, 0);
      dots.addView(d, p);
    }
    right.addView(dots);
    if (!small) head.addView(right);
    const hp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    hp.setMargins(Ui.dp(this, 4), Ui.dp(this, 2), Ui.dp(this, 4), Ui.dp(this, 6));
    out.addView(head, hp);

    const filter = () => {
      const f = (this.acadQuery || "").trim().toLowerCase();
      for (const t of tiles) {
        const st = t.getTag(R.id.tag_state);
        const show = (f === "" || String(t._title).toLowerCase().indexOf(f) >= 0) && (!this.acadOpenOnly || st === Base.DUE || st === MISSED);
        t.setVisibility(show ? View.VISIBLE : View.GONE);
      }
      tune.setColorFilter(this.acadOpenOnly ? Color.WHITE : 0xFF64748B);
      tune.setBackground(Ui.round(this, this.acadOpenOnly ? 0xFF8B5CF6 : 0xFFE2E8F0, 10));
    };
    q.addTextChangedListener({
      beforeTextChanged: () => {}, onTextChanged: () => {},
      afterTextChanged: (e) => { this.acadQuery = e.toString(); filter(); }
    });
    tune.setOnClickListener({
      onClick: (v) => {
        this.acadOpenOnly = !this.acadOpenOnly;
        filter();
        Ui.toast(this, this.acadOpenOnly ? "Showing only what is due or missed" : "Showing all sections");
      }
    });
    wp.post(filter);

    let row = null;
    for (const t of tiles) {
      const wide = "wide" === t.getTag();
      if (row == null || wide || row.getChildCount() === 2) {
        row = Ui.h(this);
        out.addView(row);
      }
      const p = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.MATCH_PARENT, 1);
      p.setMargins(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
      row.addView(t, p);
      if (wide) row = null;
    }
    if (row != null && row.getChildCount() === 1) {
      const filler = new View(this);
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 5), 0, Ui.dp(this, 5), 0);
      row.addView(filler, p);
    }
    head.setOnClickListener(this.opener(WeekAcademicsActivity));
    return out;
  }

  scheduleCard() {
    const db = this.db;
    const INFO = Base.INFO, DONE = Base.DONE, DUE = Base.DUE, MISSED = Base.MISSED;
    const today = Dates.today();
    const t = today.toString();
    const ws = Dates.weekStart(today);
    const w0 = ws.toString(), w1 = ws.plusDays(6).toString();
    const m0 = Dates.monthStart(today).toString(), m1 = Dates.monthStart(today).plusMonths(1).minusDays(1).toString();
    const card = Ui.v(this);

    const dow = Dates.dow(today);

    const todayClasses = db.num("SELECT COUNT(*) FROM classes WHERE kind='MBBS' AND date=?", t);
    const daysElapsed = Math.min(dow, 6);
    const daysCovered = db.num("SELECT COUNT(DISTINCT date) FROM classes WHERE kind='MBBS' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "MBBS class", "Mon – Sat",
      dow === 7 ? "No class on Sunday" : todayClasses > 0 ? "Logged today (" + todayClasses + ")" : "Not logged today",
      dow === 7 ? INFO : todayClasses > 0 ? DONE : DUE, daysCovered, daysElapsed, ["kind", "class", "sub", "MBBS"]);

    const pg = db.num("SELECT COUNT(*) FROM classes WHERE kind='PG' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "MD PG class", "Twice a week", pg >= 2 ? "Both held this week" : pg + " of 2 held this week",
      pg >= 2 ? DONE : (dow >= 6 ? MISSED : DUE), pg, 2, ["kind", "class", "sub", "PG"]);

    const wed = Dates.weekday(ws, DayOfWeek.WEDNESDAY);
    const conf = db.num("SELECT COUNT(*) FROM academics WHERE kind='CONF' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "Physicon", "Every Wednesday",
      conf > 0 ? "Held this week" : today.isAfter(wed) ? "Wed " + Dates.shortFmt(wed) + " not logged" : "Due " + (today.equals(wed) ? "today" : "Wed " + Dates.shortFmt(wed)),
      conf > 0 ? DONE : today.isAfter(wed) ? MISSED : DUE, Math.min(conf, 1), 1, ["kind", "academic", "sub", "CONF"]);

    const anchor = Dates.parse(db.setting("jc_anchor", ""));
    const sat = Dates.weekday(ws, DayOfWeek.SATURDAY);
    const jc = db.num("SELECT COUNT(*) FROM academics WHERE kind='JC' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    if (Dates.isJournalClubDay(sat, anchor)) {
      this.scheduleLine(card, "Journal club", "Alternate Saturday",
        jc > 0 ? "Held this week" : today.isAfter(sat) ? "Not logged" : "Due " + (today.equals(sat) ? "today" : "Sat " + Dates.shortFmt(sat)),
        jc > 0 ? DONE : today.isAfter(sat) ? MISSED : DUE, Math.min(jc, 1), 1, ["kind", "academic", "sub", "JC"]);
    } else {
      this.scheduleLine(card, "Journal club", "Alternate Saturday",
        (jc > 0 ? "Held this week. " : "") + "Next on Sat " + Dates.shortFmt(Dates.nextJournalClub(sat.plusDays(1), anchor)),
        jc > 0 ? DONE : INFO, Math.min(jc, 1), jc > 0 ? 1 : 0, ["kind", "academic", "sub", "JC"]);
    }

    const topic = db.num("SELECT COUNT(*) FROM academics WHERE kind='TOPIC' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "Topic discussion", "PG · weekly", topic > 0 ? "Held this week (" + topic + ")" : "Not logged this week",
      topic > 0 ? DONE : (dow === 7 ? MISSED : DUE), Math.min(topic, 1), 1, ["kind", "academic", "sub", "TOPIC"]);

    const symp = db.num("SELECT COUNT(*) FROM academics WHERE kind='SYMP' AND date BETWEEN ? AND ? AND date<=?", m0, m1, t);
    const lateMonth = today.getDayOfMonth() > today.lengthOfMonth() - 3;
    this.scheduleLine(card, "Symposium", "Monthly", symp > 0 ? "Held in " + Dates.month(today) : "Not yet held in " + Dates.month(today),
      symp > 0 ? DONE : lateMonth ? MISSED : DUE, Math.min(symp, 1), 1, ["kind", "academic", "sub", "SYMP"]);
    return this.tileGrid(card, ws);
  }
}

/** A tap that opens a screen; the home page reads its screen to let the admin hide a section (9.71). */
Base.Opener = class {
  constructor(a, cls, kv) {
    this.a = a;
    this.cls = cls;
    this.kv = kv;
  }

  onClick(v) { this.a.open(this.cls, this.kv); }

  /** The screen's name when the tap opens it plainly (no extras), else "". */
  static screenOf(l) {
    return l instanceof Base.Opener && l.kv.length === 0 ? l.cls.name : "";
  }
};

/** Pages use the whole screen width on tablets (9.87). */
Base.FULL_WIDTH = true;
;
