/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Sign-in to the department's shared database, joining it, sync status and (for the admin) members. */
class AccountActivity extends Base {
  /** Set while a background step runs; tests wait on it. */
  static busy = 0;

  constructor() {
    super();
    this.members = null;
    this.membersError = null;
    this.creating = false;
    /** Opened as the app's first page: sign in before anything else. */
    this.gate = false;
  }

  onCreate(b) {
    super.onCreate(b);
    this.gate = this.getIntent().getBooleanExtra("gate", false);
    this.setTitle(this.gate ? "TVMCHMED" : "Shared database");
    this.headerColor(this.gate ? Ui.PRIMARY : Ui.TEAL);
  }

  showBack() { return !this.gate; }

  onBackPressed() {
    if (this.gate) this.moveTaskToBack(true);
    else super.onBackPressed();
  }

  liveRefresh() {
    return !Cloud.signedIn(this) || Cloud.active(this);
  }

  render() {
    if (this.gate && Cloud.active(this)) {
      this.startActivity(new Intent(this, MainActivity)
        .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK));
      this.finish();
      return;
    }
    const page = Ui.v(this);
    this.headerAction(null, null);
    if (!Cloud.configured(this)) {
      this.subtitle = "Not set up";
      page.addView(this.intro());
      page.addView(this.serverCard());
    } else if (!Cloud.signedIn(this)) {
      this.subtitle = this.gate ? "Sign in to continue" : "Signed out";
      page.addView(this.gate ? this.brand() : this.intro());
      page.addView(this.signInCard());
      const srv = Ui.tv(this, "Server: " + Cloud.url(this) + "  ·  change", 12, Ui.MUTED, false);
      srv.setPadding(Ui.dp(this, 20), Ui.dp(this, 4), Ui.dp(this, 20), 0);
      srv.setOnClickListener({ onClick: (v) => { this.serverDialog(); } });
      if (!this.gate) page.addView(srv);
    } else if (StudentPortal.isStudent(this)) {
      // 10.26: an approved MBBS student sees only their own posting, attendance and marks
      this.subtitle = Cloud.prefs(this).getString("name", "") + "  ·  MBBS student";
      page.addView(StudentPortal.page(this, { run: () => { Sync.leave(this); this.render(); } }));
    } else if (!Cloud.approved(this)) {
      this.subtitle = Cloud.prefs(this).getString("email", "");
      page.addView(this.waitingCard());
      if ("pending" === Cloud.role(this)) page.addView(StudentPortal.joinCard(this, { run: () => { this.render(); } }));
    } else if (!Cloud.active(this)) {
      this.subtitle = Cloud.prefs(this).getString("email", "");
      page.addView(this.startCard());
    } else {
      this.subtitle = Cloud.prefs(this).getString("name", "") + "  ·  " + Cloud.myRoleLabel(this, this.db);
      this.headerAction("Sync now", { onClick: (v) => { this.syncNow(); } });
      page.addView(this.statusCard());
      if (Cloud.isOwner(this)) page.addView(this.apCard());
      if (Cloud.mayRemoveAnyone(this, this.db)) page.addView(this.membersSection());
    }
    if (this.gate) page.addView(Copyright.footer(this, Ui.MUTED));
    this.setPage(page);
  }

  // ---------- pieces ----------

  /** The first page's welcome: department logo, app name and what signing in gives. */
  brand() {
    const c = Ui.card(this);
    c.setBackground(Glass.hero(this, Ui.HERO, 22));
    c.setGravity(Gravity.CENTER_HORIZONTAL);
    const logo = new ImageView(this);
    logo.setImageResource(R.drawable.dept_logo);
    logo.setBackground(Ui.round(this, Color.WHITE, 20));
    logo.setClipToOutline(true);
    c.addView(logo, Ui.lp(Ui.dp(this, 88), Ui.dp(this, 88)));
    const n = Ui.tv(this, "TVMCHMED", 22, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    n.setPadding(0, Ui.dp(this, 10), 0, 0);
    c.addView(n);
    const d = Ui.tv(this, this.db.setting("dept", "Department of Medicine") + "\n" + this.db.setting("college", "Tirunelveli Medical College Hospital"), 13, 0xE6FFFFFF, false);
    d.setGravity(Gravity.CENTER);
    c.addView(d);
    const w = Ui.tv(this, "Sign in with your email and password to open the app. New here? Create an account, and the admin will approve you.", 13, Color.WHITE, true);
    w.setGravity(Gravity.CENTER);
    w.setPadding(0, Ui.dp(this, 10), 0, 0);
    c.addView(w);
    return c;
  }

  intro() {
    const c = Ui.card(this);
    c.setBackground(Glass.hero(this, Ui.shades(Ui.TEAL), 20));
    c.addView(Ui.tv(this, "One set of records for the whole department", 18, Color.WHITE, true));
    c.addView(Ui.tv(this, "Sign in so admissions, transfers, DAP entries, attendance, notices and faculty records "
      + "made on any phone appear on every phone. The app keeps working without internet and catches up when it is back.", 13, 0xE6FFFFFF, false));
    c.addView(Ui.tv(this, "The first person to sign in becomes the admin and approves everyone else.", 13, Color.WHITE, true));
    return c;
  }

  serverCard() {
    const c = Ui.card(this);
    c.addView(Ui.title(this, "Connect to the department's project"));
    c.addView(Ui.muted(this, "Enter the Project URL and anon public key from Supabase → Project Settings → API."));
    const b = Ui.button(this, "Enter server details", Ui.TEAL, { onClick: (v) => { this.serverDialog(); } });
    c.addView(b);
    Ui.margins(b, 0, 12, 0, 0);
    return c;
  }

  serverDialog() {
    const f = new Form(this);
    f.text("url", "Project URL (https://….supabase.co)", Cloud.url(this), InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_URI);
    f.multi("key", "anon public key", Cloud.key(this));
    Ui.formDialog(this, "Server", f, "Save", {
      run: () => {
        const u = f.get("url"), k = f.get("key").replaceAllRx("\\s+", "");
        if (!u.startsWith("https://")) { Ui.toast(this, "The URL starts with https://"); return false; }
        if (k.length < 20) { Ui.toast(this, "Paste the full anon key"); return false; }
        Cloud.prefs(this).edit().putString("url", u).putString("key", k).apply();
        this.render();
        return true;
      }
    });
  }

  signInCard() {
    const c = Ui.card(this);
    const f = new Form(this);
    f.view.addView(Ui.title(this, this.creating ? "Create your account" : "Sign in"));
    if (this.creating) f.text("name", "Your name (e.g. Dr. A. Kumar)", Cloud.prefs(this).getString("name", "Dr. "), Form.TEXT);
    f.text("email", "Email", Cloud.prefs(this).getString("email", ""), InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
    f.text("password", this.creating ? "Choose a password (at least 8 characters)" : "Password", "", InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
    c.addView(f.view);
    const go = Ui.button(this, this.creating ? "Create account" : "Sign in", Ui.TEAL, {
      onClick: (v) => {
        const email = f.get("email").toLowerCase(), pw = f.get("password");
        const name = this.creating ? f.get("name") : Cloud.prefs(this).getString("name", "");
        if (!email.contains("@")) { Ui.toast(this, "Enter your email"); return; }
        if (pw.length < (this.creating ? 8 : 1)) { Ui.toast(this, this.creating ? "Use at least 8 characters" : "Enter your password"); return; }
        if (this.creating && (name.isEmpty() || name.equals("Dr."))) { Ui.toast(this, "Enter your name"); return; }
        const creating = this.creating;
        this.bg(creating ? "Creating account…" : "Signing in…", { run: () => Cloud.signIn(this, email, pw, name, creating) });
      }
    });
    c.addView(go);
    Ui.margins(go, 0, 14, 0, 0);
    const sw = Ui.outlineButton(this, this.creating ? "I already have an account" : "New here? Create an account", Ui.TEAL, {
      onClick: (v) => { this.creating = !this.creating; this.render(); }
    });
    c.addView(sw);
    Ui.margins(sw, 0, 8, 0, 0);
    if (!this.creating) {
      const forgot = Ui.tv(this, "Forgot password?", 13, Ui.TEAL, true);
      forgot.setPadding(0, Ui.dp(this, 12), 0, 0);
      forgot.setOnClickListener({
        onClick: (v) => {
          const email = f.get("email").toLowerCase();
          if (!email.contains("@")) { Ui.toast(this, "Enter your email first"); return; }
          this.bg("Sending…", {
            run: () => {
              Cloud.resetPassword(this, email);
              return "A password reset link was sent to " + email + ".";
            }
          });
        }
      });
      c.addView(forgot);
    }
    return c;
  }

  waitingCard() {
    const c = Ui.card(this);
    c.addView(Ui.iconBadge(this, R.drawable.ic_lock, Ui.AMBER, 48));
    const blocked = "blocked".equals(Cloud.role(this));
    c.addView(Ui.title(this, blocked ? "Removed from the app" : "Waiting for approval"));
    c.addView(Ui.muted(this, blocked && Conduct.removedForConduct(this) ? "This account was removed for breaking the department rule: " + Conduct.RULE
        + "\n\nThe department's records have been deleted from this phone. Contact the admin if this is a mistake."
      : blocked ? "The admin, the HOD or a faculty member of your unit has removed this account, so the department's records, case sheets and files have been deleted from this phone. Contact the HOD if this is a mistake."
      : "You're signed in as " + Cloud.prefs(this).getString("email", "") + ". Ask the admin, the HOD or the Medical Registrar to approve you in the app, then tap Check again."));
    c.addView(Ui.buttonRow(this,
      Ui.button(this, "Check again", Ui.TEAL, {
        onClick: (v) => {
          this.bg("Checking…", {
            run: () => {
              Cloud.join(this, Cloud.prefs(this).getString("name", ""));
              return Cloud.approved(this) || StudentPortal.isStudent(this) ? null : "Not approved yet.";
            }
          });
        }
      }),
      Ui.outlineButton(this, "Sign out", Ui.RED, { onClick: (v) => { Sync.leave(this); this.render(); } })));
    return c;
  }

  startCard() {
    const c = Ui.card(this);
    c.addView(Ui.title(this, "Approved as " + Cloud.roleLabel(Cloud.role(this))));
    const msg = Ui.muted(this, "Checking the shared database…");
    c.addView(msg);
    const buttons = Ui.v(this);
    c.addView(buttons);
    new Thread({
      run: () => {
        // Web: serverEmpty is asynchronous.
        const done = (fEmpty, fErr) => this.runOnUiThread({
          run: () => { this.startChoices(msg, buttons, fEmpty, fErr); }
        });
        Sync.serverEmpty(this).then((e) => done(e, null), (e) => done(false, e.getMessage()));
      }
    }).start();
    return c;
  }

  startChoices(msg, buttons, empty, err) {
    if (err != null) {
      msg.setText("Could not reach the shared database: " + err);
      buttons.addView(Ui.button(this, "Try again", Ui.TEAL, { onClick: (v) => { this.render(); } }));
      return;
    }
    const local = Sync.localData(this.db);
    if (empty && local) {
      msg.setText("The shared database is empty. Upload this phone's records (" + this.db.num("SELECT COUNT(*) FROM patients")
        + " patients, " + this.db.num("SELECT COUNT(*) FROM staff") + " staff, documents and photos) as the department's starting data?");
      buttons.addView(Ui.button(this, "Upload this phone's records", Ui.TEAL, this.startListener(true)));
      buttons.addView(Ui.outlineButton(this, "Start empty instead", Ui.SLATE, this.startListener(false)));
    } else if (local) {
      msg.setText("The department already has shared records. This phone's own records will be replaced by them. "
        + "Make a backup first (Menu → Back up data) if you want to keep a copy.");
      buttons.addView(Ui.button(this, "Replace with shared records", Ui.TEAL, this.startListener(false)));
    } else {
      msg.setText(empty ? "The shared database is empty. Records you enter now will be shared." : "Ready to download the department's records.");
      buttons.addView(Ui.button(this, "Start sharing", Ui.TEAL, this.startListener(false)));
    }
    for (let i = 0; i < buttons.getChildCount(); i++) Ui.margins(buttons.getChildAt(i), 0, 10, 0, 0);
  }

  startListener(upload) {
    return {
      onClick: (v) => {
        this.bg(upload ? "Uploading records…" : "Downloading records…", {
          run: () => {
            // Web: start() is asynchronous, so hand the Promise to bg().
            return Sync.start(this, upload).then(() => Sync.run(this)).then(() => null);
          }
        });
      }
    };
  }

  statusCard() {
    const c = Ui.card(this);
    const p = Cloud.prefs(this);
    const last = p.getLong("last_sync", 0);
    const err = p.getString("last_error", "");
    const pending = this.db.pending();
    const top = Ui.h(this);
    top.addView(Ui.iconBadge(this, R.drawable.ic_cloud, err.isEmpty() ? Ui.GREEN : Ui.AMBER, 44));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 12), 0, 0, 0);
    t.addView(Ui.tv(this, err.isEmpty() ? (pending == 0 ? "Up to date" : pending + " changes waiting to upload") : "Not synced: " + err, 16, Ui.TEXT, true));
    t.addView(Ui.muted(this, last == 0 ? "Not synced yet" : "Last synced " + DateUtils.getRelativeTimeSpanString(last, System.currentTimeMillis(), DateUtils.MINUTE_IN_MILLIS)));
    top.addView(t, Ui.weight(1));
    c.addView(top);
    c.addView(Ui.divider(this));
    c.addView(Ui.kv(this, "Signed in as", p.getString("name", "") + "\n" + p.getString("email", "")));
    c.addView(Ui.kv(this, "Role", Cloud.myRoleLabel(this, this.db)));
    const sid = Cloud.myStaff(this);
    const me = sid > 0 ? this.db.row("SELECT name FROM staff WHERE id=?", String(sid)) : null;
    c.addView(Ui.kv(this, "Linked to (Students / Staff list)", me == null ? "Not linked yet (the admin links it)" : me.get("name")));
    // your photo beside your name everywhere (9.00)
    const pic = People.mine(this, 64, Ui.TEAL);
    if (pic != null) {
      const pr = Ui.h(this);
      pr.setGravity(Gravity.CENTER_VERTICAL);
      pr.addView(pic);
      const pt = Ui.v(this);
      pt.setPadding(Ui.dp(this, 12), 0, 0, 0);
      pt.addView(Ui.tv(this, "Your photo", 15, Ui.TEXT, true));
      pt.addView(Ui.muted(this, "Shown beside your name on the team boards, lists and chats, so everyone can recognise you. Tap the picture to add or change it."));
      pr.addView(pt, Ui.weight(1));
      c.addView(pr);
      Ui.margins(pr, 0, 12, 0, 0);
    }
    const out = Ui.outlineButton(this, "Sign out of this phone", Ui.RED, { onClick: (v) => { this.signOut(); } });
    c.addView(out);
    Ui.margins(out, 0, 12, 0, 0);
    return c;
  }

  signOut() {
    const pending = this.db.pending();
    const m = pending > 0 ? pending + " changes on this phone have not been uploaded yet and would be lost the next time you sign in. Connect to the internet and sync first."
      : "Records stay on this phone but stop updating. Signing in again downloads the shared records afresh.";
    Ui.confirm(this, "Sign out?", m, "Sign out", {
      run: () => { Sync.leave(this); this.members = null; this.render(); }
    });
  }

  syncNow() {
    Ui.toast(this, "Syncing…");
    Sync.now(this, {
      done: (error) => {
        Ui.toast(this, error == null ? "Up to date" : "Not synced: " + error);
        this.render();
      }
    });
  }

  // ---------- the admin as an Assistant Professor ----------

  /** The admin (Dr. S. Rajkumar) is also an Assistant Professor: linked to his own Faculty entry he appears in the DAP,
   *  roster, leave and logbook lists like any Assistant Professor, and his admin powers let him do their work in every unit. */
  apCard() {
    const c = Ui.card(this);
    c.addView(Ui.heading(this, "You as Assistant Professor", Ui.PRIMARY));
    const s = Cloud.myApEntry(this, this.db);
    if (s != null) {
      c.addView(Ui.kv(this, "Faculty entry", s.get("name") + "\nAssistant Professor  ·  " + Db.unitName(s.get("unit"))));
      c.addView(Ui.muted(this, "You keep every admin power and can do any Assistant Professor's work in any unit: case sheets, approvals, "
        + "PG leave, logbook signing, CMCHIS, call over and duty registers. You appear as Assistant Professor of your own unit in rosters and discharge summaries."));
    } else {
      c.addView(Ui.muted(this, "Link your admin account to your Faculty entry as an Assistant Professor, so you appear in duty, leave and logbook lists "
        + "and can apply for your own leave. Your admin powers stay as they are."));
    }
    const b = Ui.outlineButton(this, s == null ? "Set me up as Assistant Professor" : "Change my unit", Ui.PRIMARY, {
      onClick: (v) => { this.apDialog(s); }
    });
    c.addView(b);
    Ui.margins(b, 0, 12, 0, 0);
    return c;
  }

  apDialog(cur) {
    const f = new Form(this);
    const match = cur != null ? cur : Cloud.apMatch(this, this.db);
    let name = match != null ? match.get("name") : Cloud.prefs(this).getString("name", "");
    if (name.trim().isEmpty()) name = "Dr. S. Rajkumar";
    f.text("name", "Your name as on the Faculty list", name, InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_WORDS);
    const unit = match != null && !Ui.nz(match.get("unit")).isEmpty() ? match.get("unit") : "M1";
    f.choice("unit", "Your own unit", StaffActivity.UNIT_LABELS, StaffActivity.UNIT_VALUES, unit, null);
    const m = match;
    Ui.formDialog(this, "You as Assistant Professor", f, "Save", {
      run: () => {
        const n = f.get("name").trim();
        if (n.isEmpty() || n.equals("Dr.")) {
          Ui.toast(this, "Enter your name");
          return false;
        }
        const sid = Cloud.saveApEntry(this, this.db, m, n, f.get("unit"));
        this.bg("Linking…", {
          run: () => {
            Cloud.setMember(this, Cloud.prefs(this).getString("user_id", ""), "admin", sid);
            Cloud.join(this, "");
            this.members = null;
            return "You are now admin and Assistant Professor.";
          }
        });
        return true;
      }
    });
  }

  // ---------- members (admin, HOD, Medical Registrar; others see only whom they may remove) ----------

  membersSection() {
    const box = Ui.v(this);
    box.addView(Ui.heading(this, "Members", Ui.TEAL));
    if (this.members == null && this.membersError == null) {
      box.addView(this.emptyNote("Loading members…"));
      new Thread({
        run: () => {
          try { this.members = Cloud.members(this); this.membersError = null; }
          catch (e) { this.membersError = e.getMessage(); }
          this.runOnUiThread({
            run: () => { if (!this.isFinishing()) this.render(); }
          });
        }
      }).start();
      return box;
    }
    if (this.membersError != null) {
      box.addView(this.emptyNote("Could not load members: " + this.membersError));
      this.membersError = null;
      return box;
    }
    if (!Cloud.isAdmin(this)) return this.removableSection(box);
    const waiting = [], rest = [], removed = [];
    for (let i = 0; i < this.members.length(); i++) {
      const m = this.members.optJSONObject(i);
      const r = m.optString("role");
      if ("pending".equals(r)) waiting.add(m); else if ("blocked".equals(r)) removed.add(m); else rest.add(m);
    }
    if (!waiting.isEmpty()) {
      box.addView(Ui.section(this, "Waiting for approval  ·  " + waiting.length));
      for (const m of waiting) box.addView(this.memberRow(m));
    }
    box.addView(Ui.section(this, "Members  ·  " + rest.length));
    for (const m of rest) box.addView(this.memberRow(m));
    if (!removed.isEmpty()) {
      box.addView(Ui.section(this, "Removed  ·  " + removed.length));
      for (const m of removed) box.addView(this.memberRow(m));
    }
    const note = Ui.muted(this, "New people install the app and tap “Create an account” on this screen. They appear here for approval. "
      + "To remove someone, tap their name and choose “Removed (no access)”: the server stops them at once and their phone deletes the department's records the next time it connects. "
      + (Cloud.isOwner(this) ? "Only you (the admin) can appoint or remove the HOD and the admin." : "Only the admin can appoint or remove the HOD and the admin."));
    note.setPadding(Ui.dp(this, 18), Ui.dp(this, 6), Ui.dp(this, 18), 0);
    box.addView(note);
    return box;
  }

  /** For PGs, Assistant Professors and Professors: the members of their own unit they may remove. */
  removableSection(box) {
    const can = [];
    for (let i = 0; i < this.members.length(); i++) {
      const m = this.members.optJSONObject(i);
      if (!"blocked".equals(m.optString("role")) && !"pending".equals(m.optString("role")) && Cloud.canRemove(this, this.db, m)) can.add(m);
    }
    const unit = Cloud.unitOf(this.db, Cloud.myStaff(this));
    box.addView(Ui.section(this, "Members you can remove  ·  " + can.length));
    if (can.isEmpty()) box.addView(this.emptyNote("No one in " + Db.unitName(unit) + " you can remove."));
    for (const m of can) {
      const sid = Cloud.staffOf(m);
      const st = sid > 0 ? this.db.row("SELECT name, role FROM staff WHERE id=?", String(sid)) : null;
      const name = st != null ? st.get("name") : m.optString("name", m.optString("email"));
      box.addView(this.entryCard(st != null ? st.get("role") : Cloud.roleLabel(m.optString("role")), Ui.TEAL, name, m.optString("email"), "Tap to remove",
        { onClick: (v) => { this.confirmRemove(m); } }));
    }
    const note = Ui.muted(this, "In your own unit: PGs remove MBBS students; Assistant Professors and Professors remove PGs, CRMIs and MBBS students; "
      + "Professors remove Assistant Professors. Other faculty and workers are removed by the HOD, the Medical Registrar or the admin.");
    note.setPadding(Ui.dp(this, 18), Ui.dp(this, 6), Ui.dp(this, 18), 0);
    box.addView(note);
    return box;
  }

  confirmRemove(m) {
    const who = m.optString("name", m.optString("email"));
    Ui.confirm(this, "Remove " + who + "?", who + " will no longer be able to open or download any record. "
      + "Their phone deletes the department's records, case sheets and files the next time it connects. The HOD or the admin can give access back later.",
      "Remove", {
        run: () => {
          this.bg("Removing…", {
            run: () => {
              Cloud.removeMember(this, m.getString("user_id"));
              this.members = null;
              return who + " was removed.";
            }
          });
        }
      });
  }

  memberRow(m) {
    const role = m.optString("role");
    const sid = m.isNull("staff_id") ? -1 : m.optLong("staff_id", -1);
    const st = sid > 0 ? this.db.row("SELECT name FROM staff WHERE id=?", String(sid)) : null;
    const sub = m.optString("email") + (st == null ? "" : "\nLinked to: " + st.get("name"));
    const col = role.equals("pending") ? Ui.AMBER : role.equals("blocked") ? Ui.RED : Cloud.isManager(role) ? Ui.PRIMARY : Ui.TEAL;
    const name = m.isNull("name") || m.optString("name").isEmpty() ? m.optString("email") : m.optString("name");
    return this.entryCard(Cloud.roleLabel(role), col, name, sub, role.equals("pending") ? "Tap to approve" : null, {
      onClick: (v) => { this.memberDialog(m); }
    });
  }

  memberDialog(m) {
    const f = new Form(this);
    const role = m.optString("role");
    const kind = Cloud.kind(this.db, role, Cloud.staffOf(m));
    const owner = Cloud.isOwner(this), hod = "hod".equals(Cloud.role(this));
    if (!owner && (kind.equals("ADMIN") || kind.equals("HOD") || (!hod && kind.equals("REGISTRAR")))) {
      new AlertDialog.Builder(this).setMessage(kind.equals("REGISTRAR") ? "Only the HOD or the admin can change the Medical Registrar."
        : "Only the admin can change or remove the " + (kind.equals("HOD") ? "HOD." : "admin.")).setPositiveButton("OK", null).show();
      return;
    }
    // The admin appoints the admin and the HOD; the admin or the HOD appoints the Medical Registrar.
    const rl = [], rv = [];
    for (let i = 0; i < Cloud.ROLES.length; i++) {
      const r = Cloud.ROLES[i];
      if (!owner && (r.equals("admin") || r.equals("hod"))) continue;
      if (!owner && !hod && r.equals("registrar") && !role.equals("registrar")) continue;
      rl.add(Cloud.ROLE_LABELS[i]);
      rv.add(r);
    }
    f.choice("role", "Role", rl, rv, role.equals("pending") ? this.guessRole(m) : role, null);
    const staff = this.db.rows("SELECT id, name, role FROM staff WHERE COALESCE(approval,'')='' ORDER BY name");
    const labels = new Array(staff.length + 1).fill(null), values = new Array(staff.length + 1).fill(null);
    labels[0] = "Not linked";
    values[0] = "-1";
    for (let i = 0; i < staff.length; i++) {
      labels[i + 1] = staff[i].get("name") + "  (" + staff[i].get("role") + ")";
      values[i + 1] = staff[i].get("id");
    }
    let cur = m.isNull("staff_id") ? "-1" : String(m.optLong("staff_id"));
    if (cur.equals("-1")) for (const s of staff) if (s.get("name").equalsIgnoreCase(m.optString("name").trim())) cur = s.get("id");
    f.choice("staff", "Linked to (Students / Staff list entry)", labels, values, cur, null);
    Ui.formDialog(this, m.optString("name", m.optString("email")), f, "Save", {
      run: () => {
        const r = f.get("role");
        const sid = Long.parseLong(f.get("staff"));
        const save = {
          run: () => {
            this.bg("Saving…", {
              run: () => {
                Cloud.setMember(this, m.getString("user_id"), r, sid);
                this.members = null;
                if (m.getString("user_id").equals(Cloud.prefs(this).getString("user_id", "")))
                  Cloud.join(this, "");
                return null;
              }
            });
          }
        };
        if (r.equals("blocked") && !m.optString("role").equals("blocked")) {
          const who = m.optString("name", m.optString("email"));
          Ui.confirm(this, "Remove " + who + "?", who + " will no longer be able to open or download any record. "
            + "Their phone deletes the department's records, case sheets and files the next time it connects. You can give access back later by choosing a role again.",
            "Remove", save);
        } else save.run();
        return true;
      }
    });
  }

  guessRole(m) {
    const s = this.db.row("SELECT role FROM staff WHERE lower(name)=lower(?)", m.optString("name").trim());
    if (s == null) return "faculty";
    const r = s.get("role");
    if (r.equals("Professor") || r.equals("Associate Professor")) return "professor";
    if (Db.isFaculty(r)) return "faculty";
    if (r.equals("Postgraduate")) return "pg";
    if (r.equals("CRMI")) return "crmi";
    if (r.startsWith("MBBS")) return "student";
    return "staff";
  }

  // ---------- background work ----------

  // interface Task { String run() throws Exception; }  (an object { run: () => string|null })

  /** Runs network work off the main thread with a spinner; shows the returned message or the error. */
  bg(what, task) {
    const pd = new ProgressDialog(this);
    pd.setMessage(what);
    pd.setCancelable(false);
    pd.show();
    AccountActivity.busy++;
    new Thread({
      run: () => {
        const fail = (e) => "Failed: " + (e.getMessage == null || e.getMessage() == null ? String(e) : e.getMessage());
        let msg;
        try { msg = task.run(); } catch (e) { msg = fail(e); }
        // Web: a task may return a Promise (asynchronous sync calls).
        Promise.resolve(msg).catch(fail).then((m) => this.runOnUiThread({
          run: () => {
            try { pd.dismiss(); } catch (ignored) {}
            AccountActivity.busy--;
            if (this.isFinishing()) return;
            if (m != null) new AlertDialog.Builder(this).setMessage(m).setPositiveButton("OK", null).show();
            this.render();
          }
        }));
      }
    }).start();
  }
}
;
