/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** IMA ADPCM voice codec: 16-bit speech to 4 bits a sample (a quarter of the size). Each block starts with its own predictor and step index, so a lost block never spoils the next one. */
class Adpcm {
  static STEP = [7, 8, 9, 10, 11, 12, 13, 14, 16, 17, 19, 21, 23, 25, 28, 31, 34, 37, 41, 45, 50, 55, 60, 66, 73, 80, 88, 97, 107, 118, 130, 143,
    157, 173, 190, 209, 230, 253, 279, 307, 337, 371, 408, 449, 494, 544, 598, 658, 724, 796, 876, 963, 1060, 1166, 1282, 1411, 1552, 1707, 1878, 2066, 2272,
    2499, 2749, 3024, 3327, 3660, 4026, 4428, 4871, 5358, 5894, 6484, 7132, 7845, 8630, 9493, 10442, 11487, 12635, 13899, 15289, 16818, 18500, 20350, 22385,
    24623, 27086, 29794, 32767];
  static ADJ = [-1, -1, -1, -1, 2, 4, 6, 8];

  constructor() { this.pred = 0; this.idx = 0; }

  /** Encodes n samples; the encoder keeps its state between blocks. (Web: the intercom is a stub; the codec is kept as is.) */
  encode(pcm, n) {
    const out = new Uint8Array(3 + ((n + 1) >> 1));
    out[0] = this.pred & 0xFF;
    out[1] = (this.pred >> 8) & 0xFF;
    out[2] = this.idx & 0xFF;
    for (let i = 0; i < n; i++) {
      let step = Adpcm.STEP[this.idx];
      let diff = pcm[i] - this.pred;
      let code = 0;
      if (diff < 0) {
        code = 8;
        diff = -diff;
      }
      let d = step >> 3;
      if (diff >= step) { code |= 4; diff -= step; d += step; }
      step >>= 1;
      if (diff >= step) { code |= 2; diff -= step; d += step; }
      step >>= 1;
      if (diff >= step) { code |= 1; d += step; }
      this.pred += (code & 8) != 0 ? -d : d;
      this.pred = Math.max(-32768, Math.min(32767, this.pred));
      this.idx = Math.max(0, Math.min(88, this.idx + Adpcm.ADJ[code & 7]));
      const at = 3 + (i >> 1);
      if ((i & 1) == 0) out[at] = code;
      else out[at] |= (code << 4) & 0xFF;
    }
    return out;
  }

  /** Decodes one block; the result has two samples per byte after the 3-byte header. */
  static decode(b) {
    if (b == null || b.length < 4) return new Int16Array(0);
    let p = (((b[0] & 0xFF) | ((b[1] & 0xFF) << 8)) << 16) >> 16;
    let ix = Math.max(0, Math.min(88, b[2] & 0xFF));
    const n = (b.length - 3) * 2;
    const out = new Int16Array(n);
    for (let i = 0; i < n; i++) {
      const code = (i & 1) == 0 ? b[3 + (i >> 1)] & 0x0F : ((b[3 + (i >> 1)] & 0xFF) >> 4) & 0x0F;
      const step = Adpcm.STEP[ix];
      let d = step >> 3;
      if ((code & 4) != 0) d += step;
      if ((code & 2) != 0) d += step >> 1;
      if ((code & 1) != 0) d += step >> 2;
      p += (code & 8) != 0 ? -d : d;
      p = Math.max(-32768, Math.min(32767, p));
      ix = Math.max(0, Math.min(88, ix + Adpcm.ADJ[code & 7]));
      out[i] = p;
    }
    return out;
  }
}
;
/* ---- app/Ai.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Case and discharge summaries rewritten by Claude (Anthropic). Off until an API key is added in Settings; the key stays in
 * this phone's preferences and is never synced or put in the app. Only the summary text is sent, with the name, IP number,
 * phone, address and CMCHIS number taken out first.
 */
class Ai {
  static endpoint = 'https://api.anthropic.com/v1/messages';
  static MODEL = 'claude-opus-5-5';
  static GONE = 'the patient';

  static prefs(c) {
    return c.getSharedPreferences('ai', Context.MODE_PRIVATE);
  }

  static key(c) {
    return nz(Ai.prefs(c).getString('key', '')).trim();
  }

  static ready(c) {
    return !Ai.key(c).isEmpty() && Ai.prefs(c).getBoolean('on', true);
  }

  // ---------- which AI writes inside the app ----------

  static CLAUDE = 'Claude';
  static GEMINI = 'Gemini';
  /** Google's Gemini API (free key from aistudio.google.com); the model name and ":generateContent" are added. */
  static geminiBase = 'https://generativelanguage.googleapis.com/v1beta/models/';
  static GEMINI_MODELS = ['gemini-flash-latest', 'gemini-2.5-flash'];

  static geminiKey(c) {
    return nz(Ai.prefs(c).getString('gemini_key', '')).trim();
  }

  static setGeminiKey(c, key) {
    Ai.prefs(c).edit().putString('gemini_key', Ui.nz(key).trim()).apply();
  }

  /** The AIs that can write inside the app on this phone: Claude with a key, Gemini with a (free) key. */
  static engines(c) {
    const out = [];
    if (!Ai.prefs(c).getBoolean('on', true)) return out;
    if (!Ai.key(c).isEmpty()) out.add(Ai.CLAUDE);
    if (!Ai.geminiKey(c).isEmpty()) out.add(Ai.GEMINI);
    return out;
  }

  static engineLabel(engine) {
    return Ai.GEMINI.equals(engine) ? 'Write here with Gemini (free key)' : 'Write here with Claude (your key)';
  }

  static company(engine) {
    return Ai.GEMINI.equals(engine) ? 'Gemini (Google)' : 'Claude AI (Anthropic)';
  }

  static setKey(c, key, on) {
    Ai.prefs(c).edit().putString('key', Ui.nz(key).trim()).putBoolean('on', on).apply();
  }

  /** "sk-ant-api03-abcd…wxyz" style, so the key can be recognised without showing it. */
  static masked(k) {
    k = Ui.nz(k).trim();
    if (k.length < 12) return k.isEmpty() ? '' : '••••';
    return k.substring(0, 7) + '…' + k.substring(k.length - 4);
  }

  // ---------- removing who the patient is ----------

  static TITLES = ['mr', 'mrs', 'ms', 'miss', 'master', 'baby', 'dr', 'smt', 'thiru', 'selvi', 'tmt', 'w/o', 's/o', 'd/o'];

  /** The text with the patient's name, IP number, phone, address and CMCHIS number replaced. Age, sex and dates stay. */
  static deidentify(text, p) {
    let t = Ui.nz(text);
    for (const k of ['ip_no', 'pin_no', 'cmchis_no', 'phone', 'address']) {
      const v = Ui.nz(p.get(k)).trim();
      if (v.length >= 3) t = Pattern.compile(Pattern.quote(v), Pattern.CASE_INSENSITIVE).matcher(t).replaceAll('[removed]');
    }
    const name = Ui.nz(p.get('name')).trim();
    if (!name.isEmpty()) {
      t = Pattern.compile('(?<![\\p{L}])' + Pattern.quote(name) + '(?![\\p{L}])', Pattern.CASE_INSENSITIVE).matcher(t).replaceAll(Ai.GONE);
      for (const w of name.jsplit('[\\s.,]+')) {
        if (w.length < 3 || Ai.isTitle(w)) continue;
        t = Pattern.compile('(?<![\\p{L}])' + Pattern.quote(w) + '(?![\\p{L}])', Pattern.CASE_INSENSITIVE).matcher(t).replaceAll(Ai.GONE);
      }
      t = t.replaceAllRx('(?i)(' + Ai.GONE + '[\\s.,]*){2,}', Ai.GONE + ' ');
    }
    // any other phone-like number (10 digits, with or without +91)
    t = t.replaceAllRx('(?<!\\d)(\\+?91[\\s-]?)?[6-9]\\d{4}[\\s-]?\\d{5}(?!\\d)', '[phone removed]');
    return t;
  }

  static isTitle(w) {
    const b = w.toLowerCase().split('.').join('');
    for (const t of Ai.TITLES) if (t.split('/').join('').equals(b.split('/').join(''))) return true;
    return false;
  }

  // ---------- the request ----------

  static system(caseKind) {
    return 'You are a senior consultant physician in the Department of General Medicine at Tirunelveli Medical College Hospital, '
        + 'a government teaching hospital in Tamil Nadu, India. You turn the notes a postgraduate wrote from the case sheet into a polished '
        + (caseKind ? 'case summary that a consultant can read in a minute when the patient is presented or referred'
          : 'discharge summary that the patient\'s next doctor, the CMCHIS insurance desk and the patient can rely on') + '.\n\n'
        + 'Rules:\n'
        + '- Use only the facts in the notes. Never add a finding, value, dose, date, diagnosis or advice that is not there. '
        + 'If something is unclear, keep the original wording rather than guess.\n'
        + '- The patient\'s identity was removed on purpose. Refer to them as "the patient" or by age and sex, never invent a name.\n'
        + '- Return every heading you are given, with exactly the same wording and in the same order. A heading with no facts gets an empty text.\n'
        + '- Write in the standard style of an Indian medical college summary: crisp clinical sentences, accepted abbreviations '
        + '(c/o, h/o, k/c/o, BP, PR, RR, SpO2, CVS, RS, P/A, CNS, S1S2, NVBS, Hb, TC, DC, RFT, LFT), values with their units.\n'
        + '- Presenting complaints: one flowing sentence in chronological order with durations.\n'
        + '- Examination: general examination first (consciousness, vitals, pallor, icterus, cyanosis, clubbing, lymphadenopathy, oedema), '
        + 'then each system on its own line.\n'
        + '- Investigations: one line per group (CBC, RFT, LFT, electrolytes, sugar, urine, serology and others), values separated by commas, '
        + 'abnormal values first within a group and marked with (H) or (L) only when the notes give or clearly imply the normal range.\n'
        + '- Treatment and medicines: one line per drug with dose, route and frequency as written; keep brand or generic names as given.\n'
        + (caseKind ? '- Course so far: a short paragraph on how the patient has responded until now.\n'
          : '- Course in hospital: a short paragraph on how the patient responded. Condition at discharge, advice and follow-up: '
          + 'short clear lines the patient can follow. Medicines on discharge one per line, written as form, name, dose, frequency and duration, '
          + 'for example: Tab. Metformin 500 mg BD x 30 days. Use OD, BD, TDS, QID, HS, SOS or a 1-0-1 pattern for the frequency, '
          + 'keeping what the notes say.\n')
        + '- No markdown, no asterisks, no bullet symbols; use plain lines. Keep it as short as it can be without losing a fact.';
  }

  /** The patient and the notes, names taken out: the part of the request that describes this case. */
  static notes(caseKind, secs, p) {
    const u = new StringBuilder();
    u.append('Rewrite this ').append(caseKind ? 'case summary' : 'discharge summary').append('.\n');
    const age = Ui.nz(p.get('age'));
    u.append('Patient: ').append(age.isEmpty() ? '' : age + '-year-old ').append('F'.equals(p.get('sex')) ? 'female' : 'male').append('.\n');
    u.append('Headings, in order: ');
    let i = 0;
    for (const h of secs.keySet()) u.append(i++ === 0 ? '' : ' | ').append(h);
    u.append('\n\n<notes>\n');
    for (const e of secs.entrySet())
      u.append('## ').append(e.getKey()).append('\n').append(Ai.deidentify(e.getValue(), p).trim()).append('\n\n');
    u.append('</notes>');
    return u.toString();
  }

  // ---------- free way: through the Claude app ----------

  static CLAUDE_APP = 'com.anthropic.claude';

  /** Everything to paste into the Claude app (free plan): the rules, the reply format and the notes. */
  static chatPrompt(caseKind, secs, p) {
    const b = new StringBuilder(Ai.system(caseKind)).append('\n\n');
    b.append('Reply format: for each heading write a line with the heading between === marks, for example === Diagnosis ===, '
        + 'then its text on the next lines. Write nothing before the first heading and nothing after the last one.\n\n');
    b.append(Ai.notes(caseKind, secs, p));
    return b.toString();
  }

  static HEAD = Pattern.compile('^\\s*(?:={2,}|#{1,4}|\\*\\*)\\s*(.+?)\\s*(?:={2,}|\\*\\*)?\\s*:?\\s*$');

  /** Claude's answer pasted back from the Claude app, split into the app's headings. Text under an unknown heading is dropped. */
  static parseChat(answer, secs) {
    const got = new JMap();
    let cur = null;
    for (const line of Ui.nz(answer).split('\r').join('').jsplit('\n')) {
      const m = Ai.HEAD.matcher(line);
      let h = null;
      const mm = m.matches();
      if (mm) h = Ai.match(m.group(1).split('*').join(''), secs);
      if (h == null && line.trim().length < 60) h = Ai.match(line.split('*').join('').split(':').join(''), secs);
      if (h != null) {
        cur = got.containsKey(h) ? null : new StringBuilder();
        if (cur != null) got.put(h, cur);
      } else if (mm && line.contains('===')) {
        cur = null; // a heading the app doesn't have
      } else if (cur != null) cur.append(line).append('\n');
    }
    const out = new JMap();
    for (const e of got.entrySet()) out.put(e.getKey(), Ai.clean(e.getValue().toString()));
    if (out.isEmpty()) throw new Ai.Failure('This doesn\'t look like the AI\'s summary. In the AI app, tap Copy under its answer, then come back and tap Paste.');
    return out;
  }

  static request(caseKind, secs, p) {
    const u = Ai.notes(caseKind, secs, p);

    const section = new JSONObject()
        .put('type', 'object')
        .put('properties', new JSONObject()
            .put('heading', new JSONObject().put('type', 'string'))
            .put('text', new JSONObject().put('type', 'string')))
        .put('required', new JSONArray().put('heading').put('text'))
        .put('additionalProperties', false);
    const schema = new JSONObject()
        .put('type', 'object')
        .put('properties', new JSONObject().put('sections', new JSONObject().put('type', 'array').put('items', section)))
        .put('required', new JSONArray().put('sections'))
        .put('additionalProperties', false);
    return new JSONObject()
        .put('model', Ai.MODEL)
        .put('max_tokens', 16000)
        .put('system', Ai.system(caseKind))
        .put('output_config', new JSONObject().put('effort', 'high')
            .put('format', new JSONObject().put('type', 'json_schema').put('schema', schema)))
        .put('messages', new JSONArray().put(new JSONObject().put('role', 'user').put('content', u)));
  }

  /**
   * Sends the summary to Claude and returns the rewritten parts, by heading. Runs on a background thread.
   * rewrite(c, caseKind, secs, p) uses Claude; rewrite(c, engine, caseKind, secs, p) picks the AI.
   */
  static rewrite(c, engine, caseKind, secs, p) {
    if (arguments.length === 4) return Ai.rewrite(c, Ai.CLAUDE, engine, caseKind, secs);
    if (Ai.GEMINI.equals(engine)) {
      let schema;
      try {
        const section = new JSONObject().put('type', 'OBJECT')
            .put('properties', new JSONObject().put('heading', new JSONObject().put('type', 'STRING')).put('text', new JSONObject().put('type', 'STRING')))
            .put('required', new JSONArray().put('heading').put('text'));
        schema = new JSONObject().put('type', 'OBJECT')
            .put('properties', new JSONObject().put('sections', new JSONObject().put('type', 'ARRAY').put('items', section)))
            .put('required', new JSONArray().put('sections'));
      } catch (e) {
        throw new Ai.Failure('Could not prepare the summary');
      }
      return Ai.sectionsFrom(Ai.gemini(c, Ai.system(caseKind), Ai.notes(caseKind, secs, p), schema), secs, 'Gemini');
    }
    const key = Ai.key(c);
    if (key.isEmpty()) throw new Ai.Failure('Add your Anthropic API key in Settings → AI summaries first.');
    let body;
    try {
      body = Ai.request(caseKind, secs, p).toString();
    } catch (e) {
      if (e instanceof Ai.Failure) throw e;
      throw new Ai.Failure('Could not prepare the summary');
    }
    const r = Ai.post(key, body);
    return Ai.parse(Integer.parseInt(r[0]), r[1], secs);
  }

  /** One Messages API call: {status code, body}. post(key, body) for Claude, post(url, keyHeader, key, body) for either. */
  static post(url, keyHeader, key, body) {
    if (arguments.length === 2) return Ai.post(Ai.endpoint, 'x-api-key', url, keyHeader);
    const claude = 'x-api-key'.equals(keyHeader);
    const who = claude ? 'Claude' : 'Gemini';
    let h = null;
    let code;
    let reply;
    try {
      h = new URL_(url).openConnection();
      h.setRequestMethod('POST');
      h.setConnectTimeout(20000);
      h.setReadTimeout(240000);
      h.setDoOutput(true);
      h.setRequestProperty('content-type', 'application/json');
      h.setRequestProperty(keyHeader, key);
      if (claude) {
        h.setRequestProperty('anthropic-version', '2023-06-01');
        // browsers may only call the Messages API directly with this header
        h.setRequestProperty('anthropic-dangerous-direct-browser-access', 'true');
      }
      const os = h.getOutputStream();
      os.write(jbytes(body));
      os.close();
      code = h.getResponseCode();
      reply = Ai.read(code >= 400 ? h.getErrorStream() : h.getInputStream());
    } catch (e) {
      if (e instanceof IOException) throw new Ai.Failure('No internet connection, or ' + who + ' could not be reached.');
      throw e;
    } finally {
      if (h != null) h.disconnect();
    }
    return [String(code), reply];
  }

  // ---------- Gemini (Google) ----------

  /** One Gemini request with a JSON answer in the given schema; returns that JSON text. Runs on a background thread. */
  static gemini(c, system, user, schema) {
    const key = Ai.geminiKey(c);
    if (key.isEmpty()) throw new Ai.Failure('Add your free Gemini key in Settings → AI summaries first.');
    let body;
    try {
      body = new JSONObject()
          .put('systemInstruction', new JSONObject().put('parts', new JSONArray().put(new JSONObject().put('text', system))))
          .put('contents', new JSONArray().put(new JSONObject().put('role', 'user').put('parts', new JSONArray().put(new JSONObject().put('text', user)))))
          .put('generationConfig', new JSONObject().put('responseMimeType', 'application/json').put('responseSchema', schema))
          .toString();
    } catch (e) {
      throw new Ai.Failure('Could not prepare the summary');
    }
    let r = null;
    for (const model of Ai.GEMINI_MODELS) {
      r = Ai.post(Ai.geminiBase + model + ':generateContent', 'x-goog-api-key', key, body);
      if (!'404'.equals(r[0])) break;   // that model name is not offered: try the next
    }
    return Ai.geminiText(Integer.parseInt(r[0]), r[1]);
  }

  /**
   * Gemini reads a picture (inline_data, base64 JPEG) with the user's own Gemini key and answers in JSON text. Only the image and
   * the prompt are sent. responseSchema is optional (null: free JSON). Runs on a background thread.
   * vision(c, jpeg, prompt) is the same with no schema.
   */
  static vision(c, jpeg, prompt, schema) {
    if (schema === undefined) schema = null;
    if (jpeg == null || jpeg.length === 0) throw new Ai.Failure('There is no picture to read');
    return Ai.visionPages(c, [jpeg], prompt, schema, true);
  }

  static isPdf(b) {
    return b != null && b.length > 4 && b[0] === 0x25 && b[1] === 0x50 && b[2] === 0x44 && b[3] === 0x46;
  }

  /** Several pictures in one question (the pages of a paper case sheet, 8.00). json false: the answer is plain text. */
  static visionPages(c, jpegs, prompt, schema, json) {
    const key = Ai.geminiKey(c);
    if (key.isEmpty()) throw new Ai.Failure('Add your free Gemini key in Settings → AI summaries first.');
    if (jpegs == null || jpegs.length === 0) throw new Ai.Failure('There is no picture to read');
    let body;
    try {
      const gen = new JSONObject();
      if (json) gen.put('responseMimeType', 'application/json');
      if (json && schema != null) gen.put('responseSchema', schema);
      const parts = new JSONArray().put(new JSONObject().put('text', prompt));
      for (const jpeg of jpegs)   // a PDF file (8.70) goes as it is: Gemini reads PDFs too
        parts.put(new JSONObject().put('inline_data', new JSONObject().put('mime_type', Ai.isPdf(jpeg) ? 'application/pdf' : 'image/jpeg')
            .put('data', Base64.encodeToString(jpeg, Base64.NO_WRAP))));
      body = new JSONObject()
          .put('contents', new JSONArray().put(new JSONObject().put('role', 'user').put('parts', parts)))
          .put('generationConfig', gen)
          .toString();
    } catch (e) {
      throw new Ai.Failure('Could not prepare the picture');
    }
    let r = null;
    for (const model of Ai.GEMINI_MODELS) {
      r = Ai.post(Ai.geminiBase + model + ':generateContent', 'x-goog-api-key', key, body);
      if (!'404'.equals(r[0])) break;
    }
    return Ai.geminiText(Integer.parseInt(r[0]), r[1]);
  }

  static geminiText(code, reply) {
    let r;
    try {
      r = new JSONObject(reply);
    } catch (e) {
      throw new Ai.Failure('Gemini sent an answer this app could not read (' + code + ')');
    }
    if (code >= 400) {
      const err = r.optJSONObject('error');
      const msg = err == null ? '' : err.optString('message'), status = err == null ? '' : err.optString('status');
      if (msg.contains('API key not valid') || msg.contains('API_KEY_INVALID') || code === 401) throw new Ai.Failure('The Gemini key was not accepted. Check it in Settings → AI summaries.');
      if (code === 403 || 'PERMISSION_DENIED'.equals(status)) throw new Ai.Failure('This Gemini key is not allowed to use Gemini. Make a new key at aistudio.google.com.');
      if (code === 429 || 'RESOURCE_EXHAUSTED'.equals(status)) throw new Ai.Failure('Gemini\'s free limit is used up for now. Try again in a few minutes, or tomorrow.');
      if (code >= 500) throw new Ai.Failure('Gemini is busy just now. Try again in a minute.');
      throw new Ai.Failure('Gemini could not write it: ' + (msg.isEmpty() ? 'error ' + code : msg));
    }
    const fb = r.optJSONObject('promptFeedback');
    if (fb != null && !fb.optString('blockReason').isEmpty()) throw new Ai.Failure('Gemini declined to write this. Edit it by hand instead.');
    const cands = r.optJSONArray('candidates');
    const cand = cands == null ? null : cands.optJSONObject(0);
    if (cand == null) throw new Ai.Failure('Gemini sent no answer');
    const finish = cand.optString('finishReason');
    if ('MAX_TOKENS'.equals(finish)) throw new Ai.Failure('The answer was too long. Shorten the case sheet notes and try again.');
    if ('SAFETY'.equals(finish) || 'RECITATION'.equals(finish) || 'PROHIBITED_CONTENT'.equals(finish)) throw new Ai.Failure('Gemini declined to write this. Edit it by hand instead.');
    const content = cand.optJSONObject('content');
    const parts = content == null ? null : content.optJSONArray('parts');
    const text = new StringBuilder();
    if (parts != null) for (let i = 0; i < parts.length(); i++) {
      const part = parts.optJSONObject(i);
      if (part != null && !part.optBoolean('thought')) text.append(part.optString('text'));
    }
    if (text.length() === 0) throw new Ai.Failure('Gemini sent no text');
    return text.toString();
  }

  // ---------- course in hospital only (case sheet) ----------

  static COURSE = 'Course in hospital';

  static courseSystem() {
    return 'You are a physician in the Department of General Medicine at Tirunelveli Medical College Hospital, India, '
        + 'writing the "Course in hospital" paragraph of a discharge summary from the case sheet notes below.\n'
        + '- Use only facts in the notes: never invent results, doses, dates or events. Leave out what is not there.\n'
        + '- Chronological: condition on admission, what was found, the treatment given, how the patient responded, '
        + 'complications, and the condition at the end.\n'
        + '- One plain paragraph of 80 to 180 words, past tense, standard medical abbreviations. '
        + 'No name, no headings, no markdown, no bullet points.';
  }

  static courseNotes(secs, p) {
    const u = new StringBuilder('Write the course in hospital for this patient.\n');
    const age = Ui.nz(p.get('age'));
    u.append('Patient: ').append(age.isEmpty() ? '' : age + '-year-old ').append('F'.equals(p.get('sex')) ? 'female' : 'male').append('.\n\n<notes>\n');
    for (const e of secs.entrySet()) {
      if (e.getKey().equalsIgnoreCase(Ai.COURSE) || Ui.nz(e.getValue()).trim().isEmpty()) continue;
      u.append('## ').append(e.getKey()).append('\n').append(Ai.deidentify(e.getValue(), p).trim()).append('\n\n');
    }
    return u.append('</notes>').toString();
  }

  /** For the free chat apps: the rules and the notes, answer to be pasted back. */
  static coursePrompt(secs, p) {
    return Ai.courseSystem() + '\n\nReply with the paragraph only, nothing before or after it.\n\n' + Ai.courseNotes(secs, p);
  }

  /** The pasted answer from a chat app: drops a heading line or a lead-in like "Here is ...:". */
  static parseCourse(answer) {
    let t = Ai.clean(Ui.nz(answer).split('\r').join(''));
    t = t.replace(/^\s*(={2,}\s*)?course in hospital\s*(={2,})?\s*:?\s*\n/is, '');
    t = t.replace(/^(sure|certainly|here is|here's)[^\n]*:\s*\n+/i, '').trim();
    if (t.contains('<notes>') || t.length < 30) throw new Ai.Failure('This doesn\'t look like the AI\'s answer. In the AI app, tap Copy under its answer, then come back and tap Paste.');
    return t;
  }

  /** API key way: the paragraph written by Claude (course(c, secs, p)) or the chosen AI (course(c, engine, secs, p)). Runs on a background thread. */
  static course(c, engine, secs, p) {
    if (arguments.length === 3) return Ai.course(c, Ai.CLAUDE, engine, secs);
    return Ai.single(c, engine, Ai.courseSystem(), Ai.courseNotes(secs, p), 8000);
  }

  // ---------- AI check of the case: differential diagnosis and treatment (case sheet) ----------

  static REVIEW = 'AI check';
  static REVIEW_HEADS = ['PROBLEM', 'DIFFERENTIAL DIAGNOSIS', 'MUST NOT MISS', 'INVESTIGATIONS TO CONSIDER',
    'TREATMENT CHECK', 'SUGGESTED TREATMENT', 'MISSING INFORMATION', 'DISCUSS WITH THE UNIT'];

  static reviewSystem() {
    return 'You are a senior consultant physician reviewing a case for the Department of General Medicine, Tirunelveli Medical College '
        + 'Hospital, Tamil Nadu, India (a government teaching hospital). The treating team wants a second opinion on the diagnosis and '
        + 'the treatment, to catch mistakes before they harm the patient.\n'
        + '- Reason as in Harrison\'s Principles of Internal Medicine (latest edition) and current evidence-based guidelines '
        + '(Indian guidelines such as ICMR, NVBDCP or RSSDI where they apply; otherwise international ones). Name a guideline '
        + 'only when you are sure it exists, with its year. Never invent page numbers, trials, doses or references.\n'
        + '- Think of conditions common in South India: scrub typhus, leptospirosis, dengue, malaria, enteric fever, tuberculosis, '
        + 'melioidosis, snake bite, organophosphate, paraquat and rat-killer poisoning, alcohol-related disease.\n'
        + '- Use only the facts in the notes. When something needed is missing (weight, renal function, allergy, pregnancy), say so; '
        + 'do not assume it.\n'
        + '- TREATMENT CHECK: go through every drug listed. For each one that needs it, say whether the indication fits, and flag a '
        + 'wrong or unusual dose, route or frequency, a dose that needs change for the creatinine, liver, age or pregnancy, interactions, '
        + 'contraindications, allergy clashes, duplicate drugs and important drugs that seem to be missing. Say clearly when a drug '
        + 'looks dangerous for this patient. If nothing is wrong, say so.\n'
        + '- Use drugs available in Indian government hospitals where you can.\n'
        + '- Write in plain text with these headings, each alone on its own line in capitals, in this order: '
        + TextUtils.join(', ', Ai.REVIEW_HEADS) + '. Short numbered points under each, most important first. '
        + 'No markdown, no tables, no patient name.\n'
        + '- End with one line: "Decision support only: the treating doctor decides."';
  }

  static reviewNotes(secs, p) {
    const u = new StringBuilder('Review the diagnosis and treatment of this patient.\n');
    const age = Ui.nz(p.get('age'));
    u.append('Patient: ').append(age.isEmpty() ? '' : age + '-year-old ').append('F'.equals(p.get('sex')) ? 'female' : 'male').append('.\n\n<notes>\n');
    for (const e of secs.entrySet()) {
      if (Ui.nz(e.getValue()).trim().isEmpty()) continue;
      u.append('## ').append(e.getKey()).append('\n').append(Ai.deidentify(e.getValue(), p).trim()).append('\n\n');
    }
    return u.append('</notes>').toString();
  }

  /** For the free chat apps: the rules and the notes, answer to be pasted back. */
  static reviewPrompt(secs, p) {
    return Ai.reviewSystem() + '\n\nReply with the review only.\n\n' + Ai.reviewNotes(secs, p);
  }

  /** The pasted review from a chat app, with stray markdown and a lead-in line dropped. */
  static parseReview(answer) {
    let t = Ai.clean(Ui.nz(answer).split('\r').join(''));
    t = t.replace(/^(sure|certainly|here is|here's|okay|ok)[^\n]*:?\s*\n+/i, '').trim();
    if (t.contains('<notes>') || t.length < 80) throw new Ai.Failure('This doesn\'t look like the AI\'s answer. In the AI app, tap Copy under its answer, then come back and tap Paste.');
    return t;
  }

  /** API key way: the review written by Claude or Gemini. Runs on a background thread. */
  static review(c, engine, secs, p) {
    return Ai.single(c, engine, Ai.reviewSystem(), Ai.reviewNotes(secs, p), 16000);
  }

  /** One answer as plain text (inside a one-field JSON reply) from Claude or Gemini. Runs on a background thread. */
  static single(c, engine, system, user, maxTokens) {
    if (Ai.GEMINI.equals(engine)) {
      let schema;
      try {
        schema = new JSONObject().put('type', 'OBJECT').put('properties', new JSONObject().put('course', new JSONObject().put('type', 'STRING')))
            .put('required', new JSONArray().put('course'));
      } catch (e) {
        throw new Ai.Failure('Could not prepare the notes');
      }
      const text = Ai.gemini(c, system, user, schema);
      try {
        const course = Ai.clean(new JSONObject(text).optString('course'));
        if (course.isEmpty()) throw new Ai.Failure('Gemini sent no text');
        return course;
      } catch (e) {
        if (e instanceof Ai.Failure) throw e;
        throw new Ai.Failure('Gemini\'s answer was not in the expected form');
      }
    }
    const key = Ai.key(c);
    if (key.isEmpty()) throw new Ai.Failure('Add your Anthropic API key in Settings → AI summaries first.');
    let body;
    try {
      const schema = new JSONObject().put('type', 'object')
          .put('properties', new JSONObject().put('course', new JSONObject().put('type', 'string')))
          .put('required', new JSONArray().put('course')).put('additionalProperties', false);
      body = new JSONObject().put('model', Ai.MODEL).put('max_tokens', maxTokens).put('system', system)
          .put('output_config', new JSONObject().put('effort', 'high')
              .put('format', new JSONObject().put('type', 'json_schema').put('schema', schema)))
          .put('messages', new JSONArray().put(new JSONObject().put('role', 'user').put('content', user))).toString();
    } catch (e) {
      throw new Ai.Failure('Could not prepare the notes');
    }
    const r = Ai.post(key, body);
    const one = new JMap();
    one.put('course', '');
    // reuse the error handling of parse() by wrapping the answer as a single section
    const code = Integer.parseInt(r[0]);
    if (code >= 400) Ai.parse(code, r[1], one);
    try {
      const res = new JSONObject(r[1]);
      if ('refusal'.equals(res.optString('stop_reason'))) throw new Ai.Failure('Claude declined to answer this. Write it by hand instead.');
      const content = res.optJSONArray('content');
      if (content != null) for (let i = 0; i < content.length(); i++) {
        const b = content.optJSONObject(i);
        if (b != null && 'text'.equals(b.optString('type'))) return Ai.clean(new JSONObject(b.optString('text')).optString('course'));
      }
    } catch (e) {
      if (e instanceof Ai.Failure) throw e;
      throw new Ai.Failure('Claude\'s answer was not in the expected form');
    }
    throw new Ai.Failure('Claude sent no text');
  }

  static parse(code, reply, secs) {
    let r;
    try {
      r = new JSONObject(reply);
    } catch (e) {
      throw new Ai.Failure('Claude sent an answer this app could not read (' + code + ')');
    }
    if (code >= 400) {
      const err = r.optJSONObject('error');
      const type = err == null ? '' : err.optString('type');
      if (code === 401 || 'authentication_error'.equals(type)) throw new Ai.Failure('The API key was not accepted. Check it in Settings → AI summaries.');
      if (code === 403 || 'permission_error'.equals(type)) throw new Ai.Failure('This API key is not allowed to use Claude.');
      if (code === 429 || code === 529 || code >= 500) throw new Ai.Failure('Claude is busy just now. Try again in a minute.');
      if (err != null && err.optString('message').toLowerCase().contains('credit')) throw new Ai.Failure('The Anthropic account has no credit left.');
      throw new Ai.Failure('Claude could not write it: ' + (err == null ? 'error ' + code : err.optString('message')));
    }
    const stop = r.optString('stop_reason');
    if ('refusal'.equals(stop)) throw new Ai.Failure('Claude declined to write this summary. Edit it by hand instead.');
    if ('max_tokens'.equals(stop)) throw new Ai.Failure('The summary was too long for one answer. Shorten the case sheet notes and try again.');
    const content = r.optJSONArray('content');
    let text = null;
    if (content != null) for (let i = 0; i < content.length(); i++) {
      const b = content.optJSONObject(i);
      if (b != null && 'text'.equals(b.optString('type'))) {
        text = b.optString('text');
        break;
      }
    }
    if (text == null) throw new Ai.Failure('Claude sent no summary');
    return Ai.sectionsFrom(text, secs, 'Claude');
  }

  /** {"sections":[{heading,text}]} matched to the app's headings. */
  static sectionsFrom(text, secs, who) {
    let arr;
    try {
      arr = new JSONObject(text).getJSONArray('sections');
    } catch (e) {
      throw new Ai.Failure(who + '\'s summary was not in the expected form');
    }
    const out = new JMap();
    for (let i = 0; i < arr.length(); i++) {
      const s = arr.optJSONObject(i);
      if (s == null) continue;
      const h = Ai.match(s.optString('heading'), secs);
      if (h != null && !out.containsKey(h)) out.put(h, Ai.clean(s.optString('text')));
    }
    if (out.isEmpty()) throw new Ai.Failure(who + '\'s summary did not match the headings');
    return out;
  }

  /** The app's heading that this answer heading means (same words, ignoring case and punctuation). */
  static match(h, secs) {
    const n = Ai.norm(h);
    for (const k of secs.keySet()) if (Ai.norm(k).equals(n)) return k;
    return null;
  }

  static norm(s) {
    return Ui.nz(s).toLowerCase().replaceAllRx('[^a-z0-9]+', '');
  }

  /** Drops stray markdown so the text looks right in Word, PDF and WhatsApp. */
  static clean(s) {
    s = Ui.nz(s).split('**').join('').replace(/^\s*[-*•]\s+/gm, '').replace(/^#+\s*/gm, '');
    return s.replaceAllRx('\n{3,}', '\n\n').trim();
  }

  static read(inp) {
    if (inp == null) return '';
    const b = new ByteArrayOutputStream();
    const buf = new Uint8Array(8192);
    let n;
    while ((n = inp.read(buf)) > 0) b.write(buf, 0, n);
    inp.close();
    return jstr(b.toByteArray());
  }
}

Ai.Failure = class extends Error {
  constructor(m) { super(m); this.name = 'Failure'; }
};
;
