/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** New faculty and student entries waiting for approval: approve, approve all, or reject with a reason. */
class ApprovalActivity extends Base {

  static ORDER = " ORDER BY CASE WHEN role IN ('Professor','Associate Professor','Assistant Professor') THEN 0 WHEN role='Postgraduate' THEN 1 "
    + "WHEN role='CRMI' THEN 2 ELSE 3 END, added_on, name";

  render() {
    const mine = [], others = [];
    for (const s of this.db.rows("SELECT * FROM staff WHERE approval=?" + ApprovalActivity.ORDER, Approvals.PENDING))
      (Approvals.canApprove(this, s.get("role")) ? mine : others).add(s);
    const rejected = this.db.rows("SELECT * FROM staff WHERE approval=?" + ApprovalActivity.ORDER, Approvals.REJECTED);

    this.setTitle("Approvals");
    this.subtitle = mine.isEmpty() ? "Nothing waiting for you" : mine.size() + " awaiting your approval";
    this.headerColor(Ui.AMBER);
    const page = Ui.v(this);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Ui.AMBER), 20));
    hero.addView(Ui.tv(this, mine.isEmpty() ? "All caught up" : mine.size() + " new " + (mine.size() === 1 ? "entry" : "entries") + " to check", 18, Color.WHITE, true));
    hero.addView(Ui.tv(this, "Faculty entries are approved by the HOD. PG, CRMI and MBBS entries are approved by any faculty member. "
      + "Until approved, a name is left out of attendance, rosters and name lists.", 13, 0xE6FFFFFF, false));
    if (mine.size() > 1) {
      const all = mine;
      const ok = Ui.button(this, "Approve all " + mine.size(), Ui.GREEN, {
        onClick: (v) => {
          Ui.confirm(this, "Approve all?", all.size() + " entries will be approved.", "Approve all", {
            run: () => {
              for (const s of all) Approvals.approve(this.db, this, Long.parseLong(s.get("id")));
              this.render();
            }
          });
        }
      });
      hero.addView(ok);
      Ui.margins(ok, 0, 12, 0, 0);
    }
    page.addView(hero);

    if (Cloud.active(this) && Cloud.isAdmin(this)) {
      const acc = Ui.card(this);
      acc.addView(Ui.tv(this, "App sign-ups", 15, Ui.TEXT, true));
      acc.addView(Ui.muted(this, "People who sign in to the app are approved, and given a role, under Account."));
      const go = Ui.outlineButton(this, "Open Account", Ui.PRIMARY, this.opener(AccountActivity));
      acc.addView(go);
      Ui.margins(go, 0, 8, 0, 0);
      page.addView(acc);
    }

    if (!mine.isEmpty()) {
      page.addView(Ui.heading(this, "Awaiting your approval", Ui.AMBER));
      for (const s of mine) page.addView(this.entry(s, true));
    } else {
      page.addView(this.emptyNote("No new faculty or student entries are waiting for you."));
    }
    if (!others.isEmpty()) {
      page.addView(Ui.heading(this, "Waiting for the HOD", Ui.SLATE));
      for (const s of others) page.addView(this.entry(s, false));
    }
    if (!rejected.isEmpty()) {
      page.addView(Ui.heading(this, "Not approved", Ui.RED));
      for (const s of rejected) page.addView(this.entry(s, false));
    }
    const recent = this.db.rows("SELECT * FROM staff WHERE " + Approvals.APPROVED_SQL + " AND approved_on<>'' ORDER BY approved_on DESC LIMIT 10");
    if (!recent.isEmpty()) {
      page.addView(Ui.heading(this, "Recently approved", Ui.GREEN));
      const card = Ui.card(this);
      for (const s of recent) {
        card.addView(Ui.kv(this, s.get("name") + "  (" + ApprovalActivity.label(s) + ")",
          Dates.nice(s.get("approved_on").jsplit(" ")[0]) + (Ui.nz(s.get("approved_by")).isEmpty() ? "" : " · " + s.get("approved_by"))));
      }
      page.addView(card);
    }
    this.setPage(page);
  }

  static label(s) {
    const r = s.get("role");
    return r.equals("Postgraduate") ? "PG" : r;
  }

  entry(s, canAct) {
    const faculty = Db.isFaculty(s.get("role"));
    const color = faculty ? Ui.PRIMARY_DARK : Approvals.isStudent(s.get("role")) ? Ui.TEAL : Ui.SLATE;
    const card = Ui.card(this);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.softPill(this, ApprovalActivity.label(s), color));
    const sp = new View(this);
    top.addView(sp, new LinearLayoutParams(0, 1, 1));
    const ap = Approvals.pill(this, s);
    if (ap != null && !canAct) top.addView(ap);
    card.addView(top);
    const name = Ui.tv(this, s.get("name"), 17, Ui.TEXT, true);
    card.addView(name);
    Ui.margins(name, 0, 6, 0, 0);
    const bits = [];
    bits.add(Db.unitName(s.get("unit")));
    if (!Ui.nz(s.get("reg_no")).isEmpty()) bits.add(s.get("reg_no"));
    if (!Ui.nz(s.get("batch")).isEmpty()) bits.add(s.get("batch"));
    if (!Ui.nz(s.get("qualification")).isEmpty()) bits.add(s.get("qualification"));
    if (!Ui.nz(s.get("phone")).isEmpty()) bits.add(s.get("phone"));
    card.addView(Ui.muted(this, TextUtils.join("  ·  ", bits)));
    let who = Ui.nz(s.get("added_by")).isEmpty() ? "" : "Added by " + s.get("added_by");
    if (!Ui.nz(s.get("added_on")).isEmpty()) who += (who.isEmpty() ? "Added on " : " on ") + Dates.nice(s.get("added_on").jsplit(" ")[0]);
    if (!who.isEmpty()) card.addView(Ui.muted(this, who));
    if (Approvals.REJECTED.equals(s.get("approval"))) {
      const why = "Not approved" + (Ui.nz(s.get("approved_by")).isEmpty() ? "" : " by " + s.get("approved_by"))
        + (Ui.nz(s.get("approval_note")).isEmpty() ? "" : ": " + s.get("approval_note"));
      const w = Ui.tv(this, why, 13, Ui.RED, true);
      card.addView(w);
      Ui.margins(w, 0, 4, 0, 0);
    }
    const id = Long.parseLong(s.get("id"));
    if (canAct) {
      const row = Ui.buttonRow(this,
        Ui.button(this, "Approve", Ui.GREEN, {
          onClick: (v) => {
            Approvals.approve(this.db, this, id);
            Ui.toast(this, s.get("name") + " approved");
            this.render();
          }
        }),
        Ui.outlineButton(this, "Reject", Ui.RED, {
          onClick: (v) => { this.reject(s); }
        }));
      card.addView(row);
      Ui.margins(row, 0, 10, 0, 0);
    }
    Ui.ripple(card, Ui.alpha(color, 0x1A));
    card.setOnClickListener({
      onClick: (v) => { this.edit(s); }
    });
    return card;
  }

  edit(s) {
    const again = {
      run: () => { this.render(); }
    };
    if (Db.isFaculty(s.get("role"))) {
      if (Cloud.canSeeFaculty(this)) this.open(FacultyProfileActivity, "id", s.get("id"));
    } else {
      StaffActivity.studentDialog(this, s, s.get("role"), s.get("unit"), again);
    }
  }

  reject(s) {
    const f = new Form(this);
    f.multi("why", "Reason (shown to the person who added it)", "");
    Ui.formDialog(this, "Reject " + s.get("name") + "?", f, "Reject", {
      run: () => {
        Approvals.reject(this.db, this, Long.parseLong(s.get("id")), f.get("why"));
        this.render();
        return true;
      }
    });
  }
}
;
/* ---- app/Arena.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * PG Arena (10.0): the Daily Duel, the Mystery case, the Unit League, faculty likes and the Wall of Fame in one place, with a
 * home card that shows the day's duel topper glowing until the next 7:30 AM. Rankings show the top 10 and your own place only,
 * so nobody is shown as last.
 */
class Arena {
  static COLOR = 0xFF7C3AED;
  static GRADIENT = [0xFF1E1B4B, 0xFF6D28D9, 0xFFDB2777];
  static GOLD = 0xFFFDE047;
  static TOP = 10;

  /** A ranking card: the top 10 and, when lower, the viewer's own place. key: the score column; mine: the viewer's row. */
  static board(a, rows, mine, key, suffix) {
    const card = Ui.card(a);
    if (rows.isEmpty()) {
      card.addView(Ui.muted(a, "Nobody yet."));
      return card;
    }
    let myRank = 0;
    for (let i = 0; i < rows.size(); i++) if (mine != null && rows.get(i).get("id").equals(mine.get("id"))) myRank = i + 1;
    for (let i = 0; i < Math.min(Arena.TOP, rows.size()); i++) card.addView(Arena.line(a, i + 1, rows.get(i), key, suffix, i + 1 === myRank));
    if (myRank > Arena.TOP) {
      card.addView(Ui.tv(a, "⋯", 14, Ui.MUTED, true));
      card.addView(Arena.line(a, myRank, rows.get(myRank - 1), key, suffix, true));
    }
    return card;
  }

  static line(a, rank, r, key, suffix, me) {
    return Arena.row(a, rank, Ui.nz(r.get("name")) + (Ui.nz(r.get("unit")).isEmpty() ? "" : "  (" + r.get("unit") + ")"), Ui.nz(r.get(key)) + suffix, me);
  }

  static row(a, rank, name, value, me) {
    const row = Ui.h(a);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(Ui.dp(a, 8), Ui.dp(a, 7), Ui.dp(a, 8), Ui.dp(a, 7));
    if (me) row.setBackground(Ui.round(a, Ui.alpha(Arena.COLOR, 0x22), 10));
    const medal = rank === 1 ? "👑" : rank === 2 ? "🥈" : rank === 3 ? "🥉" : rank + ".";
    const m = Ui.tv(a, medal, rank <= 3 ? 18 : 14, Ui.MUTED, true);
    row.addView(m, Ui.lp(Ui.dp(a, 40), LinearLayout.LayoutParams.WRAP_CONTENT));
    row.addView(Ui.tv(a, name + (me ? "  · you" : ""), 15, Ui.TEXT, me || rank === 1), Ui.weight(1));
    row.addView(Ui.tv(a, value, 15, rank === 1 ? League.COLOR : Ui.TEXT, true));
    return row;
  }

  /** A soft glow that breathes, for the topper's line. */
  static glow(t) {
    t.setShadowLayer(14, 0, 0, Arena.GOLD);
    const an = new AlphaAnimation(0.6, 1);
    an.setDuration(900);
    an.setRepeatCount(Animation.INFINITE);
    an.setRepeatMode(Animation.REVERSE);
    t.startAnimation(an);
  }

  static homeRow(a, icon, title, line, l) {
    const r = Ui.h(a);
    r.setGravity(Gravity.CENTER_VERTICAL);
    r.setBackground(Glass.frost(a, 14));
    r.setPadding(Ui.dp(a, 12), Ui.dp(a, 9), Ui.dp(a, 12), Ui.dp(a, 9));
    r.addView(Ui.tv(a, icon, 20, Color.WHITE, false), Ui.lp(Ui.dp(a, 36), LinearLayout.LayoutParams.WRAP_CONTENT));
    const t = Ui.v(a);
    t.addView(Ui.tv(a, title, 14, Color.WHITE, true));
    const sub = Ui.tv(a, line, 12, 0xE6FFFFFF, false);
    sub.setMaxLines(2);
    t.addView(sub);
    r.addView(t, Ui.weight(1));
    r.addView(Ui.tv(a, "›", 20, Color.WHITE, true));
    r.setOnClickListener(l);
    const lp = new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(0, Ui.dp(a, 8), 0, 0);
    r.setLayoutParams(lp);
    return r;
  }

  /** The home card: duel (with the topper glowing), mystery, league and the wall of fame. */
  static homeCard(a, db) {
    const card = Ui.card(a);
    card.setBackground(Glass.hero(a, Arena.GRADIENT, 20));
    const top = Ui.h(a);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Slab.pulse(a, 0xFFF472B6), Ui.lp(Ui.dp(a, 10), Ui.dp(a, 10)));
    const h = Ui.tv(a, "  PG ARENA", 12, Color.WHITE, true);
    h.setLetterSpacing(0.14);
    top.addView(h, Ui.weight(1));
    const champ = League.champion(db);
    if (!champ.isEmpty()) {
      const ch = Ui.tv(a, "🏆 " + champ + " champion", 11, Color.WHITE, true);
      ch.setBackground(Glass.frost(a, 12));
      ch.setPadding(Ui.dp(a, 10), Ui.dp(a, 3), Ui.dp(a, 10), Ui.dp(a, 3));
      top.addView(ch);
    }
    top.setOnClickListener(a.opener(ArenaActivity));
    card.addView(top);

    const t = Duel.topper(db, Duel.day());
    if (t != null) {
      const tt = Ui.tv(a, "👑 Today's topper: " + t.get("name") + (Ui.nz(t.get("unit")).isEmpty() ? "" : " (" + t.get("unit") + ")") + "  ·  " + t.get("score") + " pts",
          15, Arena.GOLD, true);
      tt.setPadding(0, Ui.dp(a, 10), 0, 0);
      Arena.glow(tt);
      tt.setOnClickListener(a.opener(DuelActivity));
      card.addView(tt);
    }
    card.addView(Arena.homeRow(a, "⚔", "Daily Duel", Duel.homeLine(a, db), a.opener(DuelActivity)));
    if (Mystery.today(db) != null || Mystery.canSet(a)) card.addView(Arena.homeRow(a, "🕵", "Mystery case", Mystery.homeLine(a, db), a.opener(MysteryActivity)));
    card.addView(Arena.homeRow(a, "🏆", "Unit League", League.homeLine(a, db), a.opener(LeagueActivity)));
    card.addView(Arena.homeRow(a, "🏅", "Wall of Fame", Fame.homeLine(db), a.opener(FameActivity)));
    return card;
  }
}
