'use strict';
/** Staff attendance (daily marks), leave register and monthly summary. */
class AttendanceActivity extends Base {
  constructor() { super(); this.view = 0; this.day = null; this.month = null; }

  static VIEWS = ["Daily", "Leave", "Monthly"];
  static FACULTY_ROLES = "('Professor','Associate Professor','Assistant Professor')";
  static $clinit() {
    AttendanceActivity.ATT_COLORS = [Ui.GREEN, Ui.RED, Ui.AMBER, Ui.PRIMARY, Ui.SLATE, Ui.TEAL];
    AttendanceActivity.UNIT_ORDER = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.FEVER, Db.CCB, Db.GERI, Db.RHEUM, Db.KDP, Db.DEPT];
  }

  onCreate(b) {
    super.onCreate(b);
    this.day = Dates.today();
    this.month = Dates.monthStart(this.day);
    this.setTitle("Attendance & leave");
    this.subtitle = "All staff of the department";
    this.headerColor(Ui.GREEN);
  }

  render() {
    this.headerAction(this.view === 1 ? "+ Leave" : null, this.view === 1 ? {
      onClick: (v) => { this.leaveDialog(null); }
    } : null);
    const page = Ui.v(this);
    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    for (let i = 0; i < AttendanceActivity.VIEWS.length; i++) {
      const idx = i;
      const t = Ui.tv(this, AttendanceActivity.VIEWS[i], 14, i === this.view ? Ui.GREEN : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      if (i === this.view) {
        t.setBackground(Ui.round(this, Color.WHITE, 11));
        t.setElevation(Ui.dp(this, 1));
      }
      t.setOnClickListener({
        onClick: (v) => { this.view = idx; this.render(); }
      });
      seg.addView(t, Ui.weight(1));
    }
    page.addView(seg);
    Ui.margins(seg, 12, 4, 12, 4);

    const staff = this.db.num("SELECT COUNT(*) FROM staff WHERE " + Db.NOT_STUDENT);
    if (staff === 0) {
      page.addView(this.emptyNote("Add staff first (each unit's team, or Menu → Students for PGs and CRMIs) to mark attendance."));
      const b = Ui.button(this, "Open students", Ui.GREEN, this.opener(StaffActivity));
      page.addView(b);
      Ui.margins(b, 24, 0, 24, 0);
    } else if (this.view === 0) this.daily(page);
    else if (this.view === 1) this.leaves(page);
    else this.monthly(page);
    this.setPage(page);
  }

  navRow(label, prev, next, showNext) {
    const nav = Ui.h(this);
    nav.addView(Ui.outlineButton(this, "‹", Ui.GREEN, prev));
    const d = Ui.tv(this, label, 15, Ui.TEXT, true);
    d.setGravity(Gravity.CENTER);
    nav.addView(d, Ui.weight(1));
    const n = Ui.outlineButton(this, "›", Ui.GREEN, next);
    if (!showNext) n.setVisibility(View.INVISIBLE);
    nav.addView(n);
    return nav;
  }

  // ---------- daily ----------

  daily(page) {
    const iso = this.day.toString();
    const top = Ui.card(this);
    top.addView(this.navRow(Dates.longFmt(this.day), {
      onClick: (v) => { this.day = this.day.minusDays(1); this.render(); }
    }, {
      onClick: (v) => { this.day = this.day.plusDays(1); this.render(); }
    }, this.day.isBefore(Dates.today())));
    const all = this.db.rows("SELECT * FROM staff WHERE " + Db.NOT_STUDENT + " ORDER BY unit, role, name");
    const counts = new Array(Db.ATT_CODES.length).fill(0);
    let unmarked = 0;
    for (const s of all) {
      const st = this.db.attendance(Long.parseLong(s.get("id")), iso);
      const i = AttendanceActivity.indexOf(st);
      if (i >= 0) counts[i]++;
      else unmarked++;
    }
    const sr = Ui.statRow(this,
      Ui.stat(this, String(counts[0]), "Present", Ui.GREEN),
      Ui.stat(this, String(counts[1]), "Absent", Ui.RED),
      Ui.stat(this, String(counts[2]), "Leave", Ui.AMBER),
      Ui.stat(this, String(counts[3] + counts[4]), "OD / off", Ui.PRIMARY),
      Ui.stat(this, String(unmarked), "Unmarked", Ui.MUTED));
    top.addView(sr);
    Ui.margins(sr, 0, 10, 0, 0);
    if (unmarked > 0) {
      const all_p = Ui.button(this, "Mark the " + unmarked + " unmarked as present", Ui.GREEN, {
        onClick: (v) => {
          for (const s of this.db.rows("SELECT id FROM staff WHERE " + Db.NOT_STUDENT)) {
            const sid = Long.parseLong(s.get("id"));
            if (this.db.attendance(sid, iso).isEmpty()) this.db.setAttendance(sid, iso, "P");
          }
          this.render();
        }
      });
      top.addView(all_p);
      Ui.margins(all_p, 0, 10, 0, 0);
    }
    top.addView(Ui.muted(this, "Tap a mark to set it; tap it again to clear. Approved leave shows as L automatically."));
    page.addView(top);

    let cur = null;
    let card = null;
    for (const s of all) {
      if (!s.get("unit").equals(cur)) {
        cur = s.get("unit");
        page.addView(Ui.heading(this, Db.unitName(cur), Ui.unitColor(cur)));
        card = Ui.card(this);
        page.addView(card);
      }
      const sid = Long.parseLong(s.get("id"));
      const st = this.db.attendance(sid, iso);
      const row = Ui.v(this);
      row.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
      const nm = Ui.h(this);
      nm.addView(Ui.tv(this, s.get("name"), 15, Ui.TEXT, true), Ui.weight(1));
      nm.addView(Ui.muted(this, s.get("role")));
      row.addView(nm);
      const marks = Ui.h(this);
      for (let i = 0; i < Db.ATT_CODES.length; i++) {
        const code = Db.ATT_CODES[i];
        const on = code.equals(st);
        const col = AttendanceActivity.ATT_COLORS[i];
        const m = Ui.tv(this, code, 13, on ? Color.WHITE : col, true);
        m.setGravity(Gravity.CENTER);
        m.setBackground(on ? Ui.round(this, col, 10) : Ui.outline(this, Ui.CARD, Ui.alpha(col, 0x66), 10));
        m.setPadding(0, Ui.dp(this, 7), 0, Ui.dp(this, 7));
        Ui.ripple(m, Ui.alpha(col, 0x33));
        m.setOnClickListener({
          onClick: (v) => {
            this.db.setAttendance(sid, iso, on ? "" : code);
            this.render();
          }
        });
        const p = Ui.weight(1);
        if (i > 0) p.leftMargin = Ui.dp(this, 6);
        marks.addView(m, p);
      }
      row.addView(marks);
      Ui.margins(marks, 0, 6, 0, 0);
      card.addView(row);
    }
  }

  static indexOf(code) {
    for (let i = 0; i < Db.ATT_CODES.length; i++) if (Db.ATT_CODES[i].equals(code)) return i;
    return -1;
  }

  // ---------- leave ----------

  leaves(page) {
    const iso = Dates.todayIso();
    const sum = Ui.card(this);
    sum.addView(Ui.statRow(this,
      Ui.stat(this, String(this.db.num("SELECT COUNT(*) FROM leaves WHERE status='Approved' AND ? BETWEEN from_date AND to_date", iso)), "On leave today", Ui.AMBER),
      Ui.stat(this, String(this.db.num("SELECT COUNT(*) FROM leaves WHERE status='Applied'")), "Awaiting approval", Ui.ORANGE),
      Ui.stat(this, String(this.db.num("SELECT COUNT(*) FROM leaves WHERE status='Approved' AND from_date>?", iso)), "Upcoming", Ui.PRIMARY)));
    const add = Ui.button(this, "+ Add leave", Ui.GREEN, {
      onClick: (v) => { this.leaveDialog(null); }
    });
    sum.addView(add);
    Ui.margins(add, 0, 10, 0, 0);
    page.addView(sum);
    page.addView(this.entryCard("Open", Ui.PRIMARY_DARK, "Leave register",
      (Cloud.canSeeFacultyLeave(this) ? "Faculty CL, COL, PL, RH, EL, ML (faculty only) and " : "") + "PG CL, academic leave and week off, with what is left", "📒", this.opener(LeaveRegisterActivity)));
    page.addView(this.entryCard("Open", Ui.PURPLE, "PG leave",
      "Leave letters, approved by the unit Assistant Professor, Professor and HOD", "PG", this.opener(PgLeaveActivity)));
    page.addView(Ui.heading(this, "Leave register (other staff)", Ui.GREEN));
    const rows = this.db.rows("SELECT l.*, s.name, s.role, s.unit FROM leaves l LEFT JOIN staff s ON s.id=l.staff_id "
      + (Cloud.canSeeFacultyLeave(this) ? "" : "WHERE s.role IS NULL OR s.role NOT IN " + AttendanceActivity.FACULTY_ROLES + " ")
      + "ORDER BY CASE l.status WHEN 'Applied' THEN 0 ELSE 1 END, l.from_date DESC LIMIT 200");
    if (rows.isEmpty()) page.addView(this.emptyNote("No leave recorded yet."));
    for (const r of rows) {
      const st = r.get("status");
      const col = "Approved" === st ? Ui.GREEN : "Rejected" === st ? Ui.RED : Ui.ORANGE;
      const range = Dates.nice(r.get("from_date")) + (r.get("to_date").equals(r.get("from_date")) ? "" : " to " + Dates.nice(r.get("to_date")));
      const card = this.entryCard(st, col, Ui.nz(r.get("name")).isEmpty() ? "(staff removed)" : r.get("name"),
        r.get("type") + "  ·  " + range + "  ·  " + AttendanceActivity.fmtDays(r.get("days")) + (r.get("reason").isEmpty() ? "" : "\n" + r.get("reason")),
        Db.shortName(r.get("unit")), {
          onClick: (v) => { this.leaveDialog(r); }
        });
      if ("Applied" === st) {
        const b = Ui.buttonRow(this,
          Ui.outlineButton(this, "Approve", Ui.GREEN, {
            onClick: (v) => { this.setLeaveStatus(r.get("id"), "Approved"); }
          }),
          Ui.outlineButton(this, "Reject", Ui.RED, {
            onClick: (v) => { this.setLeaveStatus(r.get("id"), "Rejected"); }
          }));
        card.addView(b);
        Ui.margins(b, 0, 8, 0, 0);
      }
      page.addView(card);
    }
  }

  static fmtDays(d) {
    let v;
    try { v = Double.parseDouble(d); } catch (e) { return d; }
    return (v === Math.floor(v) ? String(Math.trunc(v)) : String(v)) + (v === 1 ? " day" : " days");
  }

  setLeaveStatus(id, st) {
    const cv = new ContentValues();
    cv.put("status", st);
    this.db.update("leaves", cv, Long.parseLong(id));
    this.render();
  }

  leaveDialog(r) {
    // Faculty use Faculty leave and PGs use PG leave; this register is for everyone else.
    const staff = this.db.rows("SELECT id, name, unit FROM staff WHERE role NOT IN " + AttendanceActivity.FACULTY_ROLES + " AND role<>'Postgraduate' AND " + Db.NOT_STUDENT
      + (r == null ? "" : " OR id=" + Long.parseLong(Ui.nz(r.get("staff_id")).isEmpty() ? "0" : r.get("staff_id"))) + " ORDER BY name");
    const ids = new Array(staff.size()).fill(null), names = new Array(staff.size()).fill(null);
    for (let i = 0; i < staff.size(); i++) {
      ids[i] = staff.get(i).get("id");
      names[i] = staff.get(i).get("name") + " (" + Db.shortName(staff.get(i).get("unit")) + ")";
    }
    if (ids.length === 0) {
      Ui.toast(this, "Add staff first");
      return;
    }
    const f = new Form(this);
    f.choice("staff_id", "Staff member", names, ids, r == null ? ids[0] : r.get("staff_id"), null);
    f.choice("type", "Type of leave", Db.LEAVE_TYPES, Db.LEAVE_TYPES, r == null ? Db.LEAVE_TYPES[0] : r.get("type"), null);
    f.date("from_date", "From", r == null ? Dates.todayIso() : r.get("from_date"));
    f.date("to_date", "To", r == null ? Dates.todayIso() : r.get("to_date"));
    f.check("half", "Half day", r != null && "0.5" === r.get("days"));
    f.multi("reason", "Reason", r == null ? "" : r.get("reason"));
    f.choice("status", "Status", Db.LEAVE_STATUS, Db.LEAVE_STATUS, r == null ? "Applied" : r.get("status"), null);
    if (r != null) {
      const del = Ui.outlineButton(this, "Delete this leave", Ui.RED, {
        onClick: (v) => {
          this.db.delete("leaves", Long.parseLong(r.get("id")));
          Ui.toast(this, "Deleted");
          this.render();
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "Add leave" : "Edit leave", f, "Save", {
      run: () => {
        const a = Dates.parse(f.get("from_date")), b = Dates.parse(f.get("to_date"));
        if (a == null || b == null || b.isBefore(a)) {
          Ui.toast(this, "“To” date must be on or after “From”");
          return false;
        }
        const cv = new ContentValues();
        cv.put("staff_id", f.get("staff_id"));
        cv.put("type", f.get("type"));
        cv.put("from_date", a.toString());
        cv.put("to_date", b.toString());
        cv.put("days", "1" === f.get("half") ? 0.5 : ChronoUnit.DAYS.between(a, b) + 1);
        cv.put("reason", f.get("reason"));
        cv.put("status", f.get("status"));
        if (r == null) this.db.insert("leaves", cv);
        else this.db.update("leaves", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  // ---------- monthly ----------

  monthly(page) {
    const top = Ui.card(this);
    top.addView(this.navRow(Dates.month(this.month), {
      onClick: (v) => { this.month = this.month.minusMonths(1); this.render(); }
    }, {
      onClick: (v) => { this.month = this.month.plusMonths(1); this.render(); }
    }, this.month.isBefore(Dates.monthStart(Dates.today()))));
    top.addView(Ui.muted(this, "P present · A absent · L leave · OD on duty · PDO post-duty off · WO week off"));
    page.addView(top);
    let end = this.month.plusMonths(1).minusDays(1);
    if (end.isAfter(Dates.today())) end = Dates.today();
    for (const u of AttendanceActivity.UNIT_ORDER) {
      const staff = this.db.rows("SELECT * FROM staff WHERE unit=? AND " + Db.NOT_STUDENT + " ORDER BY role, name", u);
      if (staff.isEmpty()) continue;
      page.addView(Ui.heading(this, Db.unitName(u), Ui.unitColor(u)));
      const card = Ui.card(this);
      for (const s of staff) {
        const sid = Long.parseLong(s.get("id"));
        const c = new Array(Db.ATT_CODES.length).fill(0);
        for (let d = this.month; !d.isAfter(end); d = d.plusDays(1)) {
          const i = AttendanceActivity.indexOf(this.db.attendance(sid, d.toString()));
          if (i >= 0) c[i]++;
        }
        const row = Ui.h(this);
        row.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
        const nm = Ui.v(this);
        nm.addView(Ui.tv(this, s.get("name"), 14, Ui.TEXT, true));
        nm.addView(Ui.muted(this, s.get("role")));
        row.addView(nm, Ui.weight(1.6));
        for (let i = 0; i < c.length; i++) {
          const t = Ui.tv(this, Db.ATT_CODES[i] + "\n" + c[i], 12, c[i] > 0 ? AttendanceActivity.ATT_COLORS[i] : 0xFFCBD5E1, true);
          t.setGravity(Gravity.CENTER);
          row.addView(t, Ui.weight(0.6));
        }
        card.addView(row);
      }
      page.addView(card);
    }
  }
}
;
/* ---- app/Away.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Who is away (9.72), for the unit team boards. Faculty leave itself stays private to the faculty, so a faculty phone keeps
 * a small shared copy of each approved leave (who, from, to, kind: no reason) in the table "away"; every member's phone
 * reads it, together with the staff attendance marks and approved PG leave, to show on the board who is on leave today
 * and who goes on leave soon.
 */
class Away {
  static TABLE = "away";
  static LEAVE = 0xFFF59E0B;
  static DUTY = 0xFF0EA5E9;

  /** On this phone, when it can see faculty leave: brings the shared copy in line with the approved faculty leaves. */
  static mirror(c, db) {
    if (!Cloud.canSeeFacultyLeave(c)) return;
    const keep = new Set();
    for (const l of db.rows("SELECT * FROM faculty_leaves WHERE status='Approved' AND type<>'COL credit' AND to_date>=?", Dates.today().minusDays(7).toString())) {
      const src = "fl:" + l.get("id");
      keep.add(src);
      const kind = Ui.nz(l.get("type")).equals("Week off") ? "Week off" : "Leave";
      const r = db.row("SELECT * FROM " + Away.TABLE + " WHERE src=?", src);
      if (r != null && Ui.nz(r.get("staff_id")).equals(Ui.nz(l.get("staff_id"))) && Ui.nz(r.get("from_date")).equals(Ui.nz(l.get("from_date")))
        && Ui.nz(r.get("to_date")).equals(Ui.nz(l.get("to_date"))) && Ui.nz(r.get("kind")).equals(kind)) continue;
      const cv = new ContentValues();
      cv.put("src", src);
      cv.put("staff_id", Ui.nz(l.get("staff_id")));
      cv.put("from_date", Ui.nz(l.get("from_date")));
      cv.put("to_date", Ui.nz(l.get("to_date")));
      cv.put("kind", kind);
      if (r == null) db.insert(Away.TABLE, cv);
      else db.update(Away.TABLE, cv, Long.parseLong(r.get("id")));
    }
    // a leave withdrawn, refused or deleted: its copy goes (old ones too, after a week)
    for (const r of db.rows("SELECT id, src, to_date FROM " + Away.TABLE + " WHERE src LIKE 'fl:%'"))
      if (!keep.has(r.get("src"))) db.delete(Away.TABLE, Long.parseLong(r.get("id")));
  }

  /** Away on a day: "Leave", "Week off", "On duty" (elsewhere) or "" when at work. */
  static on(db, staffId, iso) {
    const a = db.attendance(Ui.toLong(staffId, -1), iso);
    if ("L" === a) return "Leave";
    if ("WO" === a) return "Week off";
    if ("OD" === a) return "On duty";
    const r = db.row("SELECT kind FROM " + Away.TABLE + " WHERE staff_id=? AND ? BETWEEN from_date AND to_date", String(staffId), iso);
    return r == null ? "" : Ui.nz(r.get("kind"));
  }

  /** The first working day after this person's absence that covers today (for "back on Mon 27 Oct"). */
  static backOn(db, staffId, today) {
    let d = today;
    for (let i = 0; i < 60 && !Away.on(db, staffId, d.toString()).isEmpty(); i++) d = d.plusDays(1);
    return d;
  }

  /** The next day within a week when this person will be away, or null. */
  static soon(db, staffId, today) {
    for (let i = 1; i <= 7; i++) {
      const d = today.plusDays(i);
      const k = Away.on(db, staffId, d.toString());
      if (k.equals("Leave") || k.equals("On duty")) return d;
    }
    return null;
  }

  static icon(kind) {
    return kind.equals("On duty") ? "✈️" : kind.equals("Week off") ? "🏖️" : "🌴";
  }

  /** "Mon 27 Oct" */
  static day(d) {
    return d.format(DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH));
  }
}
;
/* ---- app/Backup.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Backup file: a ZIP holding tvmchmed.json (all records) and files/... (notice images, faculty photos and documents).
 * Restore also accepts the plain JSON backups made by versions 1 and 2.
 * Web: write() returns a Promise (the stored files are loaded into memory first); read() stays synchronous.
 */
class Backup {
  static JSON = "tvmchmed.json";

  static async write(db, os) {
    // Web: synchronous file reads only work for files in memory, so load them all first
    const base = db.file("");
    const rels = [];
    for (const d of Db.FILE_DIRS) Backup.listTree(new File(base, d), rels);
    await VFS.preload(rels);
    const z = new ZipOutputStream(os);
    try {
      z.putNextEntry(new ZipEntry(Backup.JSON));
      z.write(jbytes(db.exportAll().toString(1)));
      z.closeEntry();
      for (const d of Db.FILE_DIRS) Backup.addDir(z, base, new File(base, d));
    } finally {
      z.close();
    }
  }

  /** Web: the stored files under a folder, as paths under filesDir. */
  static listTree(dir, out) {
    const list = dir.listFiles();
    if (list == null) return;
    for (const f of list) {
      if (f.isDirectory()) { Backup.listTree(f, out); continue; }
      out.push(f.rel());
    }
  }

  static addDir(z, base, dir) {
    const list = dir.listFiles();
    if (list == null) return;
    for (const f of list) {
      if (f.isDirectory()) { Backup.addDir(z, base, f); continue; }
      const rel = f.getAbsolutePath().substring(base.getAbsolutePath().length + 1);
      const e = new ZipEntry("files/" + rel);
      // Photos and PDFs are already compressed.
      z.putNextEntry(e);
      const inp = new FileInputStream(f);
      try {
        const buf = new Uint8Array(16384);
        let n;
        while ((n = inp.read(buf)) > 0) z.write(buf, 0, n);
      } finally {
        inp.close();
      }
      z.closeEntry();
    }
  }

  /** Replaces all records (and, for ZIP backups, all stored files) with the backup's contents. */
  static read(db, raw) {
    const all = Backup.readAll(raw);
    const inp = new ByteArrayInputStream(all);
    const a = all.length > 0 ? all[0] : -1, b = all.length > 1 ? all[1] : -1;
    if (a !== 'P'.charCodeAt(0) || b !== 'K'.charCodeAt(0)) {
      db.importAll(new JSONObject(jstr(Backup.readAll(inp))));
      return;
    }
    const base = db.file("");
    const stage = new File(base, "restore_tmp");
    Backup.deleteTree(stage);
    stage.mkdirs();
    let json = null;
    const z = new ZipInputStream(inp);
    try {
      let e;
      while ((e = z.getNextEntry()) != null) {
        const name = e.getName();
        if (e.isDirectory()) continue;
        if (name.equals(Backup.JSON)) {
          json = new JSONObject(jstr(Backup.readAll(z)));
        } else if (name.startsWith("files/")) {
          const rel = name.substring(6);
          let allowed = false;
          for (const d of Db.FILE_DIRS) if (rel.startsWith(d + "/")) allowed = true;
          const out = new File(stage, rel);
          // (Java: the canonical path must stay inside the staging folder)
          if (!allowed || rel.split("/").includes("..")) continue;
          out.getParentFile().mkdirs();
          const fo = new FileOutputStream(out);
          try {
            const buf = new Uint8Array(16384);
            let n;
            while ((n = z.read(buf)) > 0) fo.write(buf, 0, n);
          } finally {
            fo.close();
          }
        }
      }
    } finally {
      z.close();
    }
    if (json == null) {
      Backup.deleteTree(stage);
      throw new IOException("Not a TVMCHMED backup file");
    }
    db.importAll(json);
    for (const d of Db.FILE_DIRS) {
      const cur = new File(base, d);
      Backup.deleteTree(cur);
      const staged = new File(stage, d);
      if (staged.exists() && !Backup.moveTree(staged, cur)) throw new IOException("Could not restore " + d);
    }
    Backup.deleteTree(stage);
  }

  /** Web: renameTo of a folder, file by file (the browser's file store has no real folders). */
  static moveTree(from, to) {
    const list = from.listFiles();
    if (list == null) return from.renameTo(to);
    let ok = true;
    for (const f of list) if (!Backup.moveTree(f, new File(to, f.getName()))) ok = false;
    return ok;
  }

  static readAll(inp) {
    const bo = new ByteArrayOutputStream();
    const buf = new Uint8Array(16384);
    let n;
    while ((n = inp.read(buf)) > 0) bo.write(buf, 0, n);
    return bo.toByteArray();
  }

  static deleteTree(f) {
    const list = f.listFiles();
    if (list != null) for (const c of list) Backup.deleteTree(c);
    f.delete();
  }
}
;
/* ---- app/Beacon.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Bluetooth check-in for Physicon and journal club. While attendance is open, the organiser's phone broadcasts a short
 * Bluetooth signal (session number + a token that changes every 30 seconds). Phones in the hall with the app pick it
 * up, even in the pocket, check the token against the session's secret and mark their owner present.
 * Bluetooth only reaches a few metres to the room's walls, so being marked means being in the hall.
 *
 * In the browser there is no Bluetooth LE advertising or background scanning: supported() is false, the signal never
 * starts (adError says so) and everyone checks in with the changing code instead. The token, parsing and
 * verification logic is kept so signals heard by the Android app and synced here still check out the same way.
 */
class Beacon {
  constructor() {}

  static SERVICE = "00007a11-0000-1000-8000-00805f9b34fb";
  static MAGIC = [0x54, 0x56];   // 'T', 'V'
  static REQ_PERMS = 78;
  static WEB_NOTE = "Bluetooth check-in works in the Android app; use the code here";

  /** Browsers cannot send or listen for the Bluetooth signal. */
  static supported() {
    return false;
  }

  // ---------- the signal ----------

  static token(secret, sessionId, window) {
    try {
      const mac = Mac.getInstance("HmacSHA256");
      mac.init(new SecretKeySpec(jbytes(secret), "HmacSHA256"));
      const h = mac.doFinal(jbytes("ble:" + sessionId + ":" + window));
      return new Uint8Array([h[0], h[1], h[2], h[3]]);
    } catch (e) {
      throw new IllegalStateException(e);
    }
  }

  static payload(s, millis) {
    const b = new Uint8Array(14);
    b[0] = Beacon.MAGIC[0];
    b[1] = Beacon.MAGIC[1];
    new DataView(b.buffer).setBigInt64(2, BigInt(Long.parseLong(s.get("id"))));
    b.set(Beacon.token(s.get("att_secret"), s.get("id"), SessionAttendance.window(millis)), 10);
    return b;
  }

  /** {sessionId, tokenHex} from a received signal, or null if it is not ours. */
  static parse(data) {
    if (data == null || data.length !== 14 || (data[0] & 0xff) !== Beacon.MAGIC[0] || (data[1] & 0xff) !== Beacon.MAGIC[1]) return null;
    const u = data instanceof Uint8Array ? data : Uint8Array.from(data, x => x & 0xff);
    const id = new DataView(u.buffer, u.byteOffset, u.byteLength).getBigInt64(2);
    return [String(id), Beacon.hex(u, 10, 4)];
  }

  static hex(d, off, len) {
    const sb = new StringBuilder();
    for (let i = off; i < off + len; i++) sb.append(jfmt("%02x", d[i] & 0xff));
    return sb.toString();
  }

  static valid(s, tokenHex, seenAt) {
    if (s == null || Ui.nz(s.get("att_secret")).isEmpty()) return false;
    const w = SessionAttendance.window(seenAt);
    for (let x = w - 2; x <= w + 1; x++) if (Beacon.hex(Beacon.token(s.get("att_secret"), s.get("id"), x), 0, 4).equals(tokenHex)) return true;
    return false;
  }

  // ---------- permissions ----------

  static perms() {
    if (Build.VERSION.SDK_INT >= 31) return [Manifest.permission.BLUETOOTH_SCAN, Manifest.permission.BLUETOOTH_ADVERTISE];
    return [Manifest.permission.ACCESS_FINE_LOCATION];
  }

  static allowed(c) {
    if (!Beacon.supported()) return false;
    for (const p of Beacon.perms()) if (c.checkSelfPermission(p) !== PackageManager.PERMISSION_GRANTED) return false;
    return true;
  }

  static ask(a) {
    if (!Beacon.supported()) {
      Toast.makeText(a, Beacon.WEB_NOTE, Toast.LENGTH_LONG).show();
      return;
    }
    if (!Beacon.allowed(a)) a.requestPermissions(Beacon.perms(), Beacon.REQ_PERMS);
  }

  static adapter(c) {
    const m = c.getSystemService(Context.BLUETOOTH_SERVICE);
    return m == null ? null : m.getAdapter();
  }

  static bluetoothOn(c) {
    const a = Beacon.adapter(c);
    try {
      return a != null && a.isEnabled();
    } catch (e) {
      return false;
    }
  }

  // ---------- organiser: broadcasting ----------

  static adCallback = null;
  static adWindow = -1;
  static adError = "";

  /** Starts or refreshes the signal for an open session (call every second; it changes only when the token does). */
  static advertise(c, s) {
    const now = System.currentTimeMillis();
    const w = SessionAttendance.window(now);
    if (Beacon.adCallback != null && w === Beacon.adWindow) return;
    Beacon.stopAdvertising(c);
    if (!Beacon.supported()) {
      Beacon.adError = "Bluetooth check-in works only in the Android app";
      return;
    }
    if (!Beacon.allowed(c) || !Beacon.bluetoothOn(c)) {
      Beacon.adError = !Beacon.allowed(c) ? "Bluetooth permission not given" : "Bluetooth is off";
      return;
    }
    const a = Beacon.adapter(c);
    const adv = a == null ? null : a.getBluetoothLeAdvertiser();
    if (adv == null) {
      Beacon.adError = "This phone cannot send the Bluetooth signal";
      return;
    }
    const set = { mode: "LOW_LATENCY", tx: "MEDIUM", connectable: false };
    const data = { service: Beacon.SERVICE, data: Beacon.payload(s, now) };
    Beacon.adCallback = {
      onStartSuccess: (settingsInEffect) => { Beacon.adError = ""; },
      onStartFailure: (errorCode) => { Beacon.adError = "Bluetooth signal could not start (" + errorCode + ")"; }
    };
    Beacon.adWindow = w;
    try {
      adv.startAdvertising(set, data, Beacon.adCallback);
    } catch (e) {
      Beacon.adError = "Bluetooth permission not given";
      Beacon.adCallback = null;
    }
  }

  static stopAdvertising(c) {
    if (Beacon.adCallback == null) return;
    try {
      const a = Beacon.adapter(c);
      const adv = a == null ? null : a.getBluetoothLeAdvertiser();
      if (adv != null) adv.stopAdvertising(Beacon.adCallback);
    } catch (ignored) {
    }
    Beacon.adCallback = null;
    Beacon.adWindow = -1;
  }

  static advertising() {
    return Beacon.adCallback != null;
  }

  // ---------- everyone else: listening ----------

  /** Physicon / journal club sessions today that this person could be checked in to, with attendance open or about to be. */
  static listenFor(c, db) {
    const out = [];
    const me = SessionAttendance.me(c, db);
    if (me == null) return out;
    const now = LocalDateTime.now();
    for (const s of db.rows("SELECT * FROM academics WHERE kind IN ('CONF','JC') AND (date=? OR att_open='1')", Dates.todayIso())) {
      if (SessionAttendance.isPresent(db, s.get("id"), me)) continue;
      const open = SessionAttendance.isOpen(s);
      const start = LocalDateTime.of(Dates.today(), Reminders.clock(s.get("time"), LocalTime.of(9, 0)));
      const around = !now.isBefore(start.minusMinutes(30)) && now.isBefore(start.plusHours(SessionAttendance.HOURS_OPEN));
      if (open || (Ui.nz(s.get("att_secret")).isEmpty() && s.get("date").equals(Dates.todayIso()) && around)) out.add(s);
    }
    return out;
  }

  /** When listening should next start or stop today (for the alarm), or null. */
  static nextChange(c, db) {
    const now = LocalDateTime.now();
    let best = null;
    for (const s of db.rows("SELECT * FROM academics WHERE kind IN ('CONF','JC') AND date=?", Dates.todayIso())) {
      const start = LocalDateTime.of(Dates.today(), Reminders.clock(s.get("time"), LocalTime.of(9, 0)));
      for (const t of [start.minusMinutes(30), start.plusHours(SessionAttendance.HOURS_OPEN)])
        if (t.isAfter(now) && (best == null || t.isBefore(best))) best = t;
    }
    return best;
  }

  static scanIntent(c) {
    const i = new Intent(c, Beacon.Receiver).setAction("com.tvmchmed.app.BEACON");
    const flags = PendingIntent.FLAG_UPDATE_CURRENT | (Build.VERSION.SDK_INT >= 31 ? PendingIntent.FLAG_MUTABLE : 0);
    return PendingIntent.getBroadcast(c, 1, i, flags);
  }

  /** Listens in the background (screen off too) while a session is on, and stops afterwards. Safe to call often. */
  static refresh(c) {
    const app = c.getApplicationContext();
    if (!Beacon.supported()) return;   // no background Bluetooth scanning in a browser
    const db = Db.get(app);
    const want = Reminders.prefs(app).getBoolean("ble", true) && !Beacon.listenFor(app, db).isEmpty();
    const a = Beacon.adapter(app);
    if (a == null || !Beacon.allowed(app)) return;
    try {
      const sc = a.isEnabled() ? a.getBluetoothLeScanner() : null;
      if (sc == null) return;
      if (!want) {
        sc.stopScan(Beacon.scanIntent(app));
        return;
      }
      const f = { service: Beacon.SERVICE, data: new Uint8Array(0) };
      const set = { mode: "LOW_POWER" };
      sc.startScan([f], set, Beacon.scanIntent(app));
    } catch (e) {
      // permission withdrawn or Bluetooth just turned off: try again next time
    }
  }

  // ---------- what was heard ----------

  /** Notes a signal heard at seenAt; marks the person present now if it checks out, else after the next sync. */
  static heard(c, data, seenAt) {
    const p = Beacon.parse(data);
    if (p == null) return false;
    const seen = new JSet(Reminders.prefs(c).getStringSet("ble_seen", new JSet()));
    seen.add(p[0] + "|" + p[1] + "|" + seenAt);
    Reminders.prefs(c).edit().putStringSet("ble_seen", seen).apply();
    return Beacon.verifyPending(c) > 0;
  }

  /** Checks signals heard earlier against the sessions now on this phone. Returns how many check-ins were made. */
  static verifyPending(c) {
    const seen = Reminders.prefs(c).getStringSet("ble_seen", new JSet());
    if (seen.isEmpty()) return 0;
    const db = Db.get(c);
    const me = SessionAttendance.me(c, db);
    const keep = new JSet();
    let n = 0;
    const now = System.currentTimeMillis();
    for (const e of seen) {
      const p = e.jsplit("\\|");
      if (p.length !== 3) continue;
      const at = Long.parseLong(p[2]);
      const s = db.row("SELECT * FROM academics WHERE id=?", p[0]);
      if (me != null && s != null && Beacon.valid(s, p[1], at)) {
        if (SessionAttendance.mark(db, c, s.get("id"), me, "Bluetooth")) {
          n++;
          Beacon.notifyMarked(c, s);
        }
      } else if (now - at < 6 * 60 * 60 * 1000) {
        keep.add(e);        // the session may not have reached this phone yet
      }
    }
    Reminders.prefs(c).edit().putStringSet("ble_seen", keep).apply();
    if (n > 0) Beacon.refresh(c);
    return n;
  }

  static notifyMarked(c, s) {
    Reminders.channel(c);
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null) return;
    const open = new Intent(c, CheckinActivity).putExtra("id", s.get("id")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
    const pi = PendingIntent.getActivity(c, ("att" + s.get("id")).hashCode(), open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const b = new Notification.Builder(c, Reminders.CHANNEL);
    b.setSmallIcon(R.drawable.ic_approve)
      .setContentTitle("Marked present: " + Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, s.get("kind")))
      .setContentText(Ui.nz(s.get("topic")))
      .setColor(Ui.GREEN)
      .setAutoCancel(true)
      .setContentIntent(pi);
    if (Notify.on(c)) nm.notify(("att" + s.get("id")).hashCode(), b.build());
  }
}

/** Receives what the background scan heard. (Never called in a browser: there is no background Bluetooth scan.) */
Beacon.Receiver = class extends BroadcastReceiver {
  onReceive(context, intent) {
    const c = context.getApplicationContext();
    const results = intent.getParcelableExtra("android.bluetooth.le.extra.LIST_SCAN_RESULT");
    if (results == null) return;
    let any = false;
    const now = System.currentTimeMillis();
    for (const r of results) {
      const rec = r.getScanRecord();
      const d = rec == null ? null : rec.getServiceData(Beacon.SERVICE);
      if (Beacon.parse(d) != null) {
        any = true;
        Beacon.heard(c, d, now);
      }
    }
    if (!any || Reminders.prefs(c).getStringSet("ble_seen", new JSet()).isEmpty() || !Cloud.active(c)) return;
    // heard a session this phone does not know yet: fetch it, then check again
    const pr = this.goAsync();
    const done = [false];
    const finish = {
      run: () => {
        if (done[0]) return;
        done[0] = true;
        Beacon.verifyPending(c);
        pr.finish();
      }
    };
    new Handler(Looper.getMainLooper()).postDelayed(finish, 25000);
    Sync.now(c, {
      done: (err) => { finish.run(); }
    });
  }
};
;
/* ---- app/BedBoardActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Bed board: every bed of a ward, IMCU (toxicology T1..T13, non-toxicology N1..N12) or the Critical Care Block (12),
 * free or occupied. Tap a free bed to put a waiting patient in it; tap an occupied bed to open, move or clear.
 */
class BedBoardActivity extends Base {
  constructor() {
    super();
    this.ward = null;
    /** 10.4: the patient picked up with a long press, to drop on a free bed (move) or another patient (swap). */
    this.moving = null;
  }

  static COLOR = 0xFF0369A1;

  onCreate(b) {
    super.onCreate(b);
    this.ward = this.getIntent().getStringExtra("code");
    if (this.ward == null) this.ward = b != null && b.getString("ward") != null ? b.getString("ward") : Db.IMCU;
    this.setTitle("Bed board");
    this.subtitle = "Free and occupied beds, ward by ward";
    this.headerColor(BedBoardActivity.COLOR);
    this.headerAction("🖨 Ward list", { onClick: (v) => { WardList.print(this, this.ward); } });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putString("ward", this.ward);
  }

  static sections(db, code) {
    const out = [];
    if (Db.IMCU.equals(code)) {
      const t = new BedBoardActivity.Section("Toxicology wing", null), n = new BedBoardActivity.Section("Non-toxicology wing", null);
      for (let i = 1; i <= Db.TOX_BEDS; i++) t.beds.add("T" + i);
      for (let i = 1; i <= Db.NONTOX_BEDS; i++) n.beds.add("N" + i);
      out.add(t);
      out.add(n);
      return out;
    }
    if (Db.CCB.equals(code)) {
      const s = new BedBoardActivity.Section("Critical Care Block", null);
      for (let i = 1; i <= 12; i++) s.beds.add(String(i));
      out.add(s);
      return out;
    }
    const u = db.unit(code);
    let m = Ui.toInt(u.get("male_cap"), 0), f = Ui.toInt(u.get("female_cap"), 0);
    let maxM = 0, maxF = 0;
    for (const p of db.rows("SELECT sex, bed FROM patients WHERE status='IN' AND location=?", code)) {
      const n = Ui.toInt(BedBoardActivity.norm(p.get("bed")), 0);
      if ("F".equals(p.get("sex"))) maxF = Math.max(maxF, n); else maxM = Math.max(maxM, n);
    }
    if (m === 0 && f === 0) { m = 20; f = 20; }
    const ms = new BedBoardActivity.Section("Male ward", "M"), fs = new BedBoardActivity.Section("Female ward", "F");
    for (let i = 1; i <= Math.max(m, Math.min(maxM, 99)); i++) ms.beds.add(String(i));
    for (let i = 1; i <= Math.max(f, Math.min(maxF, 99)); i++) fs.beds.add(String(i));
    if (!ms.beds.isEmpty()) out.add(ms);
    if (!fs.beds.isEmpty()) out.add(fs);
    return out;
  }

  /** "Bed 07", "b-7", " t3 " → "7", "T3". */
  static norm(bed) {
    const b = Ui.nz(bed).trim().toUpperCase().split("BED").join("").replaceAllRx("[\\s.\\-#:]", "");
    const m = /^([A-Z]?)0*(\d+)$/.exec(b);
    return m != null ? m[1] + m[2] : b;
  }

  static key(s, bed) {
    return (s.sex == null ? "" : s.sex + ":") + bed;
  }

  static keyOf(p, secs) {
    const b = BedBoardActivity.norm(p.get("bed"));
    if (b.isEmpty()) return null;
    for (const s of secs) {
      if (s.sex != null && !s.sex.equals("F".equals(p.get("sex")) ? "F" : "M")) continue;
      if (s.beds.contains(b)) return BedBoardActivity.key(s, b);
    }
    return null;
  }

  render() {
    const page = Ui.v(this);
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 6));
    for (const w of Db.CENSUS_WARDS) {
      const c = Ui.chip(this, Db.shortName(w) + " · " + this.db.census(w, null), w.equals(this.ward), Ui.unitColor(w));
      c.setOnClickListener({
        onClick: (v) => { this.ward = w; this.render(); }
      });
      chips.addView(c);
      Ui.margins(c, 0, 0, 6, 0);
    }
    page.addView(Ui.hscroll(this, chips));

    const secs = BedBoardActivity.sections(this.db, this.ward);
    const inBed = new JMap();
    const noBed = [];
    for (const p of this.db.rows("SELECT * FROM patients WHERE status='IN' AND location=? ORDER BY name", this.ward)) {
      const k = BedBoardActivity.keyOf(p, secs);
      if (k == null) noBed.add(p);
      else {
        if (!inBed.containsKey(k)) inBed.put(k, []);
        inBed.get(k).add(p);
      }
    }
    let beds = 0;
    for (const s of secs) beds += s.beds.size();
    const occupied = inBed.size();
    const sick = [];
    for (const r of this.db.rows("SELECT patient_id FROM duty_sick WHERE date=?", Dates.admitDay().toString())) sick.add(Ui.nz(r.get("patient_id")));

    const color = Ui.unitColor(this.ward);
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(color), 20));
    hero.addView(Ui.tv(this, Db.unitName(this.ward), 20, Color.WHITE, true));
    const stats = Ui.statRow(this, this.white(String(occupied), "Occupied"), this.white(String(Math.max(0, beds - occupied)), "Free"),
        this.white(String(noBed.size()), "No bed no."), this.white(String(beds), "Beds"));
    hero.addView(stats);
    Ui.margins(stats, 0, 8, 0, 0);
    page.addView(hero);
    if (this.moving != null) {
      const mv = Ui.card(this);
      mv.setBackground(Ui.round(this, 0xFFFEF3C7, 16));
      mv.addView(Ui.tv(this, "Moving " + Ui.nz(this.moving.get("name")) + " (bed " + Ui.nz(this.moving.get("bed")) + ")", 15, 0xFF92400E, true));
      mv.addView(Ui.muted(this, "Tap a free bed to move, or another patient to swap beds."));
      const cancel = Ui.outlineButton(this, "Cancel", Ui.SLATE, { onClick: (v) => { this.moving = null; this.render(); } });
      mv.addView(cancel);
      Ui.margins(cancel, 0, 8, 0, 0);
      page.addView(mv);
    } else if (inBed.size() > 1) page.addView(Ui.muted(this, "      Long-press a patient to pick them up, then tap a free bed or another patient."));

    for (const s of secs) {
      let occ = 0;
      for (const b of s.beds) if (inBed.containsKey(BedBoardActivity.key(s, b))) occ++;
      page.addView(Ui.heading(this, s.label + "  ·  " + occ + " / " + s.beds.size(), color));
      const grid = Ui.v(this);
      grid.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 10), 0);
      let row = null;
      for (let i = 0; i < s.beds.size(); i++) {
        if (i % 4 === 0) {
          row = Ui.h(this);
          grid.addView(row);
        }
        const bed = s.beds.get(i);
        const ps = inBed.get(BedBoardActivity.key(s, bed));
        const lp = Ui.weight(1);
        lp.setMargins(Ui.dp(this, 3), Ui.dp(this, 3), Ui.dp(this, 3), Ui.dp(this, 3));
        row.addView(this.tile(s, bed, ps, sick, noBed, color), lp);
      }
      const pad = s.beds.size() % 4 === 0 ? 0 : 4 - s.beds.size() % 4;
      for (let i = 0; i < pad; i++) row.addView(new View(this), Ui.weight(1));
      page.addView(grid);
    }

    if (!noBed.isEmpty()) {
      page.addView(Ui.heading(this, "Without a bed number  ·  " + noBed.size(), Ui.ORANGE));
      page.addView(Ui.muted(this, "      Tap a free bed above to put one of them in it."));
      for (const p of noBed) page.addView(this.patientRow(p));
    }
    this.setPage(page);
  }

  white(v, l) {
    const s = Ui.v(this);
    s.setGravity(Gravity.CENTER);
    s.addView(Ui.tv(this, v, 20, Color.WHITE, true));
    s.addView(Ui.tv(this, l, 11, 0xD9FFFFFF, false));
    return s;
  }

  tile(s, bed, ps, sick, noBed, color) {
    const t = Ui.v(this);
    t.setGravity(Gravity.CENTER);
    t.setMinimumHeight(Ui.dp(this, 70));
    t.setPadding(Ui.dp(this, 4), Ui.dp(this, 6), Ui.dp(this, 4), Ui.dp(this, 6));
    if (ps == null) {
      const g = Ui.round(this, Color.WHITE, 12);
      g.setStroke(Ui.dp(this, 1.5), 0xFF86EFAC);
      t.setBackground(g);
      t.addView(Ui.tv(this, bed, 16, Ui.GREEN, true));
      t.addView(Ui.tv(this, "Free", 11, Ui.GREEN, false));
      t.setOnClickListener({
        onClick: (v) => {
          if (this.moving != null) this.drop(s, bed, null);
          else this.placeDialog(s, bed, noBed);
        }
      });
    } else {
      const p = ps.get(0);
      const isSick = sick.contains(p.get("id"));
      const fill = "F".equals(p.get("sex")) ? 0xFFFCE7F3 : 0xFFDBEAFE;
      const g = Ui.round(this, fill, 12);
      g.setStroke(Ui.dp(this, isSick ? 2.5 : 1), isSick ? Ui.RED : Ui.mix(color, Color.WHITE, 0.4));
      t.setBackground(g);
      t.addView(Ui.tv(this, bed + (ps.size() > 1 ? "  +" + (ps.size() - 1) : ""), 14, Ui.TEXT, true));
      const first = Ui.nz(p.get("name")).trim();
      const n = Ui.tv(this, first.length > 12 ? first.substring(0, 12) : first, 11, Ui.TEXT, false);
      n.setSingleLine(true);
      t.addView(n);
      const tasks = Tasks.pending(this.db, Long.parseLong(p.get("id")));
      t.addView(Ui.tv(this, (Ui.nz(p.get("age")).isEmpty() ? "" : p.get("age") + " ") + Ui.nz(p.get("sex")) + (isSick ? " · sick" : "") + (tasks > 0 ? " · ⏳" + tasks : ""),
          10, isSick ? Ui.RED : Ui.MUTED, isSick));
      if (this.moving != null && Ui.nz(this.moving.get("id")) === Ui.nz(p.get("id"))) {
        const pg = Ui.round(this, 0xFFFEF3C7, 12);
        pg.setStroke(Ui.dp(this, 3), 0xFFF59E0B);
        t.setBackground(pg);
      }
      t.setOnClickListener({
        onClick: (v) => {
          if (this.moving != null) this.drop(s, bed, p);
          else this.bedMenu(s, bed, ps);
        }
      });
      t.setOnLongClickListener({
        onLongClick: (v) => {
          this.moving = p;
          this.render();
          return true;
        }
      });
    }
    for (let i = 0; i < t.getChildCount(); i++) if (t.getChildAt(i) instanceof TextView) t.getChildAt(i).setGravity(Gravity.CENTER);
    return t;
  }

  placeDialog(s, bed, noBed) {
    const fit = [];
    for (const p of noBed) if (s.sex == null || s.sex.equals("F".equals(p.get("sex")) ? "F" : "M")) fit.add(p);
    if (fit.isEmpty()) {
      Ui.toast(this, "No patient here is waiting for a bed number. New patients come in with + Admit.");
      return;
    }
    const names = new Array(fit.size()).fill(null);
    for (let i = 0; i < names.length; i++) names[i] = PatientPick.label(fit.get(i));
    new AlertDialog.Builder(this).setTitle("Put in bed " + bed)
        .setItems(names, {
          onClick: (d, w) => { this.setBed(fit.get(w), bed); }
        }).setNegativeButton("Cancel", null).show();
  }

  bedMenu(s, bed, ps) {
    const p = ps.get(0);
    new AlertDialog.Builder(this).setTitle("Bed " + bed + "  ·  " + p.get("name"))
        .setItems(["Open patient", "Move to another bed", "Clear the bed number"], {
          onClick: (d, w) => {
            if (w === 0) this.open(PatientActivity, "id", p.get("id"));
            else if (w === 1) this.moveDialog(s, p);
            else this.setBed(p, "");
          }
        }).setNegativeButton("Close", null).show();
  }

  moveDialog(from, p) {
    const secs = BedBoardActivity.sections(this.db, this.ward);
    const taken = new JSet();
    for (const o of this.db.rows("SELECT * FROM patients WHERE status='IN' AND location=?", this.ward)) {
      const k = BedBoardActivity.keyOf(o, secs);
      if (k != null) taken.add(k);
    }
    const free = [];
    for (const s of secs) {
      if (s.sex != null && !s.sex.equals("F".equals(p.get("sex")) ? "F" : "M")) continue;
      for (const b of s.beds) if (!taken.contains(BedBoardActivity.key(s, b))) free.add(b);
    }
    if (free.isEmpty()) {
      Ui.toast(this, "No free bed here");
      return;
    }
    new AlertDialog.Builder(this).setTitle("Move " + p.get("name") + " to")
        .setItems(free.slice(), {
          onClick: (d, w) => { this.setBed(p, free.get(w)); }
        }).setNegativeButton("Cancel", null).show();
  }

  /** The picked-up patient goes to a free bed, or swaps with the patient in it. Sex-wise wards keep their sex. */
  drop(s, bed, other) {
    const m = this.moving;
    this.moving = null;
    if (other != null && Ui.nz(other.get("id")) === Ui.nz(m.get("id"))) {
      this.render();
      return;
    }
    if (s.sex != null && s.sex !== ("F".equals(m.get("sex")) ? "F" : "M")) {
      Ui.toast(this, "That bed is in the " + ("F" === s.sex ? "female" : "male") + " ward");
      this.render();
      return;
    }
    const snap = new Undo.Snap().row(this.db, "patients", Long.parseLong(m.get("id")));
    if (other != null) {
      snap.row(this.db, "patients", Long.parseLong(other.get("id")));
      const sexO = "F".equals(other.get("sex")) ? "F" : "M";
      const oldBed = Ui.nz(m.get("bed"));
      this.setBedQuiet(other, oldBed);
      this.setBedQuiet(m, bed);
      this.render();
      Undo.offer(this, "Swapped " + BedBoardActivity.first(m) + " and " + BedBoardActivity.first(other), snap);
      if (sexO !== ("F".equals(m.get("sex")) ? "F" : "M")) Ui.toast(this, "Check: the two patients are of different sex");
      return;
    }
    this.setBedQuiet(m, bed);
    this.render();
    Undo.offer(this, BedBoardActivity.first(m) + " moved to bed " + bed, snap);
  }

  static first(p) {
    const n = Ui.nz(p.get("name")).trim();
    return n.length > 16 ? n.substring(0, 16) : n;
  }

  setBedQuiet(p, bed) {
    const cv = new ContentValues();
    cv.put("bed", bed);
    if (Db.IMCU.equals(this.ward)) cv.put("imcu_wing", bed.startsWith("T") ? Db.TOX : bed.startsWith("N") ? Db.NONTOX : Ui.nz(p.get("imcu_wing")));
    this.db.update("patients", cv, Long.parseLong(p.get("id")));
  }

  setBed(p, bed) {
    const cv = new ContentValues();
    cv.put("bed", bed);
    if (Db.IMCU.equals(this.ward)) cv.put("imcu_wing", bed.startsWith("T") ? Db.TOX : bed.startsWith("N") ? Db.NONTOX : Ui.nz(p.get("imcu_wing")));
    this.db.update("patients", cv, Long.parseLong(p.get("id")));
    this.render();
  }
}

/** A bed's sections: label, the bed numbers in it, and the sex it takes (null = any). */
BedBoardActivity.Section = class {
  constructor(label, sex) {
    this.label = label;
    this.sex = sex;
    this.beds = [];
  }
};
;
