'use strict';
/** The call screen. Web stub: the Intercom works only in the Android app, so this closes at once. */
class CallActivity extends Activity {
  onCreate(b) {
    super.onCreate(b);
    this.finish();
  }

  changed() {
  }

  static initials(name) {
    const p = name.split("Dr.").join("").split("Dr ").join("").trim().jsplit("\\s+");
    let s = p.length == 0 || p[0].isEmpty() ? "?" : p[0].substring(0, 1);
    if (p.length > 1) s += p[p.length - 1].substring(0, 1);
    return s.toUpperCase();
  }

  static clock(ms) {
    const s = Math.max(0, idiv(ms, 1000));
    return pad2(idiv(s, 60)) + ":" + pad2(s % 60);
  }

  onBackPressed() {
    this.finish();
  }
}
