  static hpiDesc(name) {
    for (const r of CaseSheet.HPI_DESC) if (r[0].equalsIgnoreCase(name)) return r.slice(1, r.length);
    return [];
  }

  /** "Fever for 5 days: high grade, intermittent, with chills and rigors; gradual onset, progressive. Other notes" */
  static hpiLine(name, dur, desc, onset, course, more) {
    const d = [];
    for (const x of desc) d.add(CaseSheet.lower(x));
    const oc = [];
    if (!Ui.nz(onset).isEmpty()) oc.add(onset.toLowerCase() + " onset");
    if (!Ui.nz(course).isEmpty()) oc.add(course.toLowerCase());
    const b = new StringBuilder(name);
    if (!Ui.nz(dur).trim().isEmpty()) b.append(" for ").append(dur.trim());
    let body = TextUtils.join(", ", d);
    if (!oc.isEmpty()) body = body.isEmpty() ? TextUtils.join(", ", oc) : body + "; " + TextUtils.join(", ", oc);
    if (!Ui.nz(more).trim().isEmpty()) body = body.isEmpty() ? more.trim() : body + ". " + more.trim();
    b.append(": ").append(body);
    return b.toString().trim();
  }

  /** The questions asked for a complaint (empty for most). */
  static questionsFor(name) {
    for (const g of CaseSheet.COMPLAINT_GROUPS)
      for (let i = 1; i < g.length; i++)
        if (g[i][0].equalsIgnoreCase(name)) return g[i].slice(1, g[i].length);
    return [];
  }

  static complaints(o) {
    let a = o.optJSONArray(CaseSheet.COMPLAINTS);
    if (a != null) return a;
    // older sheets: one complaint per line, "Fever - 5 days"
    a = new JSONArray();
    for (const l of CaseSheet.s(o, "complaints").jsplit("\n")) {
      const x = l.trim();
      if (x.isEmpty()) continue;
      const parts = x.jsplit("\\s+[-–]\\s+|\\s*[–:]\\s*|\\s*-\\s*(?=\\d)", 2);
      const c = new JSONObject();
      try {
        c.put("name", parts[0]);
        if (parts.length === 2) c.put("dur", parts[1]);
      } catch (ignored) {
      }
      a.put(c);
    }
    return a;
  }

  /** "Weakness of limbs (right, upper limb; sudden onset) - 2 days" */
  static complaintLine(c) {
    if (c == null) return "";
    const q = [];
    const opts = c.optJSONObject("opts");
    if (opts != null) for (const qs of CaseSheet.questionsFor(c.optString("name"))) {
      const v = opts.optString(qs.jsplit("\\|")[0]).trim();
      if (!v.isEmpty()) q.add(v.matches("(mMRC|NYHA).*") ? v : v.toLowerCase());
    }
    const note = c.optString("note").trim();
    let extra = TextUtils.join(", ", q);
    if (!note.isEmpty()) extra = extra.isEmpty() ? note : extra + "; " + note;
    let line = c.optString("name").trim() + (extra.isEmpty() ? "" : " (" + extra + ")");
    const dur = c.optString("dur").trim();
    if (!dur.isEmpty()) line += " - " + dur;
    return line;
  }

  /** Saves the list and keeps the plain "complaints" text (one line each) in step with it. */
  static putComplaints(o, a) {
    const lines = [];
    for (let i = 0; i < a.length(); i++) {
      const l = CaseSheet.complaintLine(a.optJSONObject(i));
      if (!l.isEmpty()) lines.add(l);
    }
    try {
      o.put(CaseSheet.COMPLAINTS, a);
      if (lines.isEmpty()) o.remove("complaints");
      else o.put("complaints", TextUtils.join("\n", lines));
    } catch (ignored) {
    }
  }
    static EDEMA = ["", "No pedal edema", "Bilateral, painless (pitting)", "Bilateral, painful", "Unilateral, painless", "Unilateral, painful"];
    static DRUG_TYPES = ["IV fluid", "Injection", "Tablet", "Capsule", "Syrup", "ORS", "Enema", "Nebulisation", "Other"];
    static FREQUENCIES = ["OD", "BD", "TDS", "QID", "HS", "SOS", "STAT", "Q4H", "Q6H", "Q8H", "Continuous infusion", "Once weekly"];
    static TREATMENT = "treatment";
    static DIS_MEDS = "dis_meds";
    /** Daily progress notes (a list) and the saved AI check of the case. */
    static PROGRESS = "progress";
