'use strict';
/** A patient's case sheet: sections 1 to 20, each opened as a form; treatment as a list of drugs. */
class CaseSheetActivity extends Base {
  constructor() {
    super();
    this.id = 0;
    this.p = null;
    this.data = null;
    this.editable = true;
    this.prefillShown = false;
    this.notePrefillShown = false;
    this.askedThisFocus = false;
    this.dictTarget = null;
    this.dictMulti = false;
    this.scanCamera = null;
    this.scanPages = [];
  }

  static REQ_DICT_FIELD = 91;
  static REQ_DICT_ALL = 92;
  static REQ_SCAN_CAMERA = 93;
  static REQ_SCAN_PICK = 94;
  static REQ_SCAN_LIVE = 95;
  /** The Tamil voice note (8.30): the browser's speech dialog in Tamil, then the AI writes the English note. */
  static REQ_TAMIL = 95;
  static PROGRESS_COLOR = 0xFF0891B2;
  static AI_COLOR = 0xFF7C3AED;
  static FOOD = ["", "Before food", "After food", "With food", "Empty stomach", "At bedtime"];
  static $clinit() {
    CaseSheetActivity.COMMON_DRUGS = Drugs.names();
  }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    // 10.35: the clean style of the patient page
    this.clean = true;
    this.pageBg = PatientDesign.PAGE;
  }

  render() {
    const p = this.p = this.db.row("SELECT * FROM patients WHERE id=?", String(this.id));
    if (p == null) {
      this.finish();
      return;
    }
    this.data = CaseSheet.load(this.db, this.id);
    this.editable = CaseSheet.canEdit(this, this.db, p);
    this.setTitle("Case sheet");
    const age = p.get("age").isEmpty() ? "" : p.get("age") + " y, ";
    this.subtitle = p.get("name") + "  ·  " + age + Base.sexLabel(p.get("sex")) + (p.get("ip_no").isEmpty() ? "" : "  ·  IP " + p.get("ip_no"));
    this.headerColor(PatientDesign.INK);
    this.headerAction("Summary", this.opener(DischargeActivity, "id", String(this.id)));
    const page = Ui.v(this);

    const female = "F" === p.get("sex");
    let done = 0, total = 0;
    const ai = AdminControl.aiCheckOn(this.db);
    for (const s of CaseSheet.SECTIONS) {
      if (s.femaleOnly && !female) continue;
      if (!ai && s.key === CaseSheet.AI_REVIEW) continue;
      total++;
      if (CaseSheet.filled(this.data, s)) done++;
    }
    const wb = CaseSheet.writtenBy(this.data);
    const id = this.id;
    page.addView(PatientDesign.heroFor(this, this.db, p, done + " of " + total + " sections filled",
      (wb.isEmpty() ? "" : "Written by " + wb + " · ") + "Shared online with the department. Tap a section to " + (this.editable ? "fill it." : "read it."),
      ["Admitted", "Filled", "Bed"], [PatientDesign.shortDate(p.get("admit_date")), done + " / " + total, Ui.nz(p.get("bed"))], [
        PatientDesign.action(this, R.drawable.ic_people, "Patient", false, this.opener(PatientActivity, "id", String(id))),
        PatientDesign.action(this, R.drawable.ic_event, "Timeline", false, this.opener(TimelineActivity, "id", String(id))),
        PatientDesign.action(this, R.drawable.ic_menu, "Summary", false, this.opener(DischargeActivity, "id", String(id), "kind", DischargeActivity.CASE)),
        PatientDesign.action(this, R.drawable.ic_approve, "Discharge", true, this.opener(DischargeActivity, "id", String(id)))]));
    const likes = Kudos.bar(this, this.db, "case_sheets", String(this.id), "case sheet", "", wb);
    if (likes != null) {
      const lc = Ui.card(this);
      lc.addView(likes);
      page.addView(lc);
    }
    if (this.editable) page.addView(this.dictateCard());
    if (this.editable) page.addView(this.scanCard());
    const back = this.returnBanner();
    if (back != null) page.addView(back);
    if (!this.editable) {
      const lock = Ui.card(this);
      lock.setBackground(Ui.round(this, Ui.alpha(Ui.AMBER, 0x22), 16));
      lock.addView(Ui.tv(this, "🔒  View only", 15, 0xFF92400E, true));
      lock.addView(Ui.tv(this, "This case sheet belongs to " + CaseSheet.ownerLabel(p) + ". Only its faculty, PGs and CRMIs, the admin and the HOD can change it.", 13, 0xFF92400E, false));
      page.addView(lock);
    }

    let group = null;
    for (const s of CaseSheet.SECTIONS) {
      if (s.femaleOnly && !female) continue;
      if (!ai && s.key === CaseSheet.AI_REVIEW) continue;
      const g = CaseSheetActivity.groupOf(s.key);
      if (g !== group) {
        group = g;
        page.addView(Ui.heading(this, g, CaseSheetActivity.groupColor(g)));
      }
      page.addView(this.sectionCard(s, CaseSheetActivity.groupColor(g)));
    }
    this.setPage(page);
    // the clinical lines of a WhatsApp admission message (8.70), once, through the same preview as a scanned sheet
    const prefill = this.getIntent().getStringExtra("prefill");
    if (prefill != null && !this.prefillShown && this.editable) {
      this.prefillShown = true;
      const parts = CaseScan.parse(prefill);
      if (!parts.isEmpty()) this.previewParts(parts, "From the WhatsApp message", null);
    }
    // a progress note drafted by the Copilot (8.90), opened once for the doctor to check and save
    const notePre = this.getIntent().getStringExtra("note_prefill");
    if (notePre != null && !this.notePrefillShown && this.editable) {
      this.notePrefillShown = true;
      try {
        this.note(-1, new JSONObject(notePre));
      } catch (e) {
        this.note(-1);
      }
    }
  }

  liveRefresh() {
    return false;
  }

  /** True (with a note) when this phone's person may not change the case sheet. */
  locked() {
    if (this.editable) return false;
    Ui.toast(this, "View only: only " + CaseSheet.ownerLabel(this.p) + " staff, the admin or the HOD can change this case sheet");
    return true;
  }

  static groupOf(key) {
    switch (key) {
      case "written_by":
        return "Written by";
      case "complaints": case "hpi": case "allergy": case "past": case "personal": case "rxhistory": case "family": case "menstrual": case "marital": case "obstetric": case "sexual":
        return "History";
      case "general": case "vitals": case "cvs_exam": case "rs_exam": case "abd_exam": case "cns_exam":
        return "Examination";
      case "sugar": case "urine_lytes": case "cbc_sec": case "rft_sec": case "lft_sec": case "lytes_sec": case "labs": case "urine": case "usg": case "cxr": case "ecg": case "echo": case "ct": case "mri": case "abg": case "immuno": case "serology": case "repeat_labs": case "thyroid": case "lipid_sec":
        return "Investigations";
      case "opinions": case CaseSheet.TREATMENT: case "management":
        return "Opinions and treatment";
      case CaseSheet.PROGRESS:
        return "Progress notes";
      case CaseSheet.AI_REVIEW:
        return "AI check";
      default:
        return "Discharge";
    }
  }

  static groupColor(g) {
    switch (g) {
      case "History": return Ui.PRIMARY;
      case "Written by": return 0xFF4F46E5;
      case "Examination": return Ui.TEAL;
      case "Investigations": return Ui.PURPLE;
      case "Opinions and treatment": return Ui.ORANGE;
      case "Progress notes": return CaseSheetActivity.PROGRESS_COLOR;
      case "AI check": return CaseSheetActivity.AI_COLOR;
      default: return Ui.GREEN;
    }
  }

  sectionCard(s, color) {
    const card = Ui.card(this);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const accent = new View(this);
    accent.setBackground(Ui.round(this, color, 2));
    top.addView(accent, Ui.lp(Ui.dp(this, 4), Ui.dp(this, 20)));
    const t = Ui.tv(this, s.title, 16, Ui.TEXT, true);
    t.setPadding(Ui.dp(this, 10), 0, 0, 0);
    top.addView(t, Ui.weight(1));
    const filled = CaseSheet.filled(this.data, s);
    top.addView(filled ? Ui.softPill(this, "✓ Filled", Ui.GREEN) : Ui.softPill(this, this.editable ? "Add" : "Empty", Ui.MUTED));
    card.addView(top);
    const pv = CaseSheet.preview(this.data, s);
    const list = s.key === CaseSheet.TREATMENT || s.key === CaseSheet.DIS_MEDS
      || s.key === CaseSheet.PROGRESS || s.key === CaseSheet.AI_REVIEW;
    if (!pv.isEmpty() && !list && s.key !== "complaints") {
      const m = Ui.muted(this, pv);
      m.setMaxLines(3);
      card.addView(m);
      Ui.margins(m, 0, 6, 0, 0);
    }
    const ab = CaseSheet.abnormal(this.data, s, this.p.get("sex"));
    if (!ab.isEmpty()) {
      const w = Ui.tv(this, "⚠ Abnormal: " + ab, 13, Ui.RED, true);
      card.addView(w);
      Ui.margins(w, 0, 6, 0, 0);
    }
    if (s.key === CaseSheet.PROGRESS) {
      this.progressList(card);
    } else if (s.key === CaseSheet.AI_REVIEW) {
      this.aiReviewCard(card);
    } else if (list) {
      this.drugList(card, s.key);
    } else if (s.key === "complaints") {
      this.complaintList(card);
    } else {
      Ui.ripple(card, Ui.alpha(color, 0x22));
      card.setOnClickListener({ onClick: (v) => { this.edit(s); } });
    }
    return card;
  }

  /** Whether a field shows now: its condition holds, and the field it depends on is itself showing. */
  static visible(f, fs, fd) {
    if (fd.ifKey == null) return true;
    if (!fd.ifVal.jsplit("\\|").contains(f.get(fd.ifKey))) return false;
    for (const c of fs) if (fd.ifKey === c.key) return CaseSheetActivity.visible(f, fs, c);
    return true;
  }

  edit(s) {
    const f = new Form(this);
    const fs = s.fields;
    const controllers = new JSet();
    for (const fd of fs) if (fd.ifKey != null) controllers.add(fd.ifKey);
    if (s.key === "abg") controllers.add("abg_course");
    if (s.key === "ecg") for (const fd of fs) if (fd.kind === CaseSheet.CHOICE) controllers.add(fd.key);
    if (s.key === "personal") for (const fd of fs) if (fd.kind === CaseSheet.CHOICE) controllers.add(fd.key);
    const afterChange = [null];
    const refresh = {
      changed: (value) => {
        if (afterChange[0] != null) run(afterChange[0]);
        for (const fd of fs) if (fd.ifKey != null) f.show(fd.key, CaseSheetActivity.visible(f, fs, fd));
      }
    };
    const sex = this.p.get("sex");
    const extra = [];
    if (s.key === "rxhistory") this.rxHistory(f, extra);
    for (let i = 0; i < fs.length; i++) {
      const fd = fs[i];
      if (!fd.forSex(sex)) continue;
      const v = CaseSheet.s(this.data, fd.key);
      // half-width fields pair up two to a row
      if (CaseSheetActivity.half(fd) && CaseSheetActivity.rowStart(fs, i)) f.beginRow();
      switch (fd.kind) {
        case CaseSheet.HEAD: f.heading(fd.label); break;
        case CaseSheet.NUM: this.watchLab(f.text(fd.key, fd.label, v, Form.DECIMAL), fd.key, f); break;
        case CaseSheet.MULTI:
          this.mic(f.multi(fd.key, fd.label, v), true);
          if (fd.key === "final_dx") {
            Icd11.attach(this, f, fd.key);
            Diagnoses.attach(this, f, fd.key);
          }
          break;
        case CaseSheet.TEXT:
          if (fd.key === "wb_name") {
            this.pgPicker(f, v);
            break;
          }
          if (CaseSheet.range(fd.key, sex, "", "") != null) this.watchLab(f.text(fd.key, fd.label, v, Form.PLAIN), fd.key, f);
          else {
            const te = f.text(fd.key, fd.label, v, Form.PLAIN);
            if (!fd.key.endsWith("_calc") && !fd.key.startsWith("alc_") && !fd.key.startsWith("smk_")) this.mic(te, false);
          }
          break;
        case CaseSheet.CHECK: f.check(fd.key, fd.label, "1" === v); break;
        case CaseSheet.WHEEL: f.wheel(fd.key, fd.label, fd.min, fd.max, v, fd.options.length > 0 ? fd.options[0] : null, refresh); break;
        case CaseSheet.CHOICE:
          if (fd.options.length > 14) {
            const labels = fd.options.slice();
            for (let j = 0; j < labels.length; j++) if (labels[j].isEmpty()) labels[j] = "–";
            f.choice(fd.key, fd.label, labels, fd.options, v, controllers.contains(fd.key) ? refresh : null);
          } else if (controllers.contains(fd.key)) f.segment(fd.key, fd.label, fd.options, v, CaseSheetActivity.normalOf(fd), refresh);
          else f.segment(fd.key, fd.label, fd.options, v, CaseSheetActivity.normalOf(fd));
          break;
        case CaseSheet.DATE: f.optionalDate(fd.key, fd.label, v); break;
      }
      if (CaseSheetActivity.half(fd) && (!CaseSheetActivity.rowStart(fs, i) || i + 1 >= fs.length || !CaseSheetActivity.half(fs[i + 1]))) f.endRow();
    }
    if (s.key === "past") {
      const hint = Ui.muted(this, "HFpEF, HFrEF and valvular heart disease go with CAD; ascites, varices and HRS go with DCLD. Tap a band to choose it.");
      f.view.addView(hint, 0);
    }
    if (s.key === "course") this.courseAi(f);
    if (s.key === "hpi") this.hpiFromComplaints(f);
    if (s.key === "abg") this.abgCalculator(f, afterChange);
    if (s.key === "ecg") this.ecgCalculator(f, fs, afterChange);
    if (s.key === "personal") this.habitCalculator(f, afterChange);
    if (s.key === "final") this.finalDxHelp(f);
    if (s.key === "discharge" && CaseSheet.s(this.data, "dis_date").isEmpty() && Db.DISCHARGED === this.p.get("status")) f.set("dis_date", this.p.get("outcome_date"));
    if (!this.editable) {
      Ui.formDialog(this, s.title + "  (view only)", f, "Close", { run: () => true });
      return;
    }
    Ui.formDialog(this, s.title, f, "Save", {
      run: () => {
        try {
          for (const k of extra) {
            const v = f.get(k);
            if (v.isEmpty()) this.data.remove(k);
            else this.data.put(k, v);
          }
          for (const fd of s.fields) {
            if (fd.kind === CaseSheet.HEAD) continue;
            const v = fd.forSex(sex) && CaseSheetActivity.visible(f, fs, fd) ? f.get(fd.key) : "";
            if (fd.kind === CaseSheet.CHECK && v !== "1") this.data.remove(fd.key);
            else if (v.isEmpty()) this.data.remove(fd.key);
            else this.data.put(fd.key, v);
          }
        } catch (e) {
          if (e instanceof JSONException) return true;
          throw e;
        }
        if (s.key === "course") DischargeActivity.forgetCourseEdits(this.data);
        CaseSheet.save(this.db, this.id, this.data);
        this.render();
        return true;
      }
    });
  }

  // ---------- paper case sheet: photos to case sheet (8.00) ----------

  /** "Scan the paper case sheet" under the dictation card. */
  scanCard() {
    const card = Ui.card(this);
    card.addView(Ui.title(this, "📷  Scan the paper case sheet"));
    const hint = Ui.muted(this, "Photograph the handwritten pages (up to " + CaseScan.MAX_PAGES + "). An AI reads them into the sections; nothing is saved until you check the preview.");
    card.addView(hint);
    Ui.margins(hint, 0, 4, 0, 6);
    card.addView(Ui.buttonRow(this, Ui.button(this, "📹  Live scan", Ui.PRIMARY, {
      onClick: (v) => { if (!this.locked()) this.scanLive(); }
    }), Ui.outlineButton(this, "📷  Photos", Ui.PRIMARY, {
      onClick: (v) => { if (!this.locked()) this.scanStart(); }
    })));
    return card;
  }

  /** Live scan (8.70): hold the phone over the pages; each is taken by itself. Read when Done is tapped. */
  scanLive() {
    this.scanClean();
    LiveScanActivity.start(this, "casescan", CaseScan.MAX_PAGES, "Paper case sheet: cover the name and IP number", CaseSheetActivity.REQ_SCAN_LIVE);
  }

  scanStart() {
    this.scanClean();
    const how = Ai.geminiKey(this).isEmpty() ? "No Gemini key is saved, so the pages go to the free AI app you choose (ChatGPT, Claude or Gemini)."
      : "The pages are read by Google Gemini with your own key.";
    new AlertDialog.Builder(this).setTitle("Scan the paper case sheet")
      .setMessage("The photos are sent to an AI to read them. Fold or cover the patient's name, IP number and address before taking them. "
        + how + " Handwriting can be misread: check every section before adding it.")
      .setPositiveButton("Camera", { onClick: (d, w) => { this.scanCam(); } })
      .setNeutralButton("Gallery", { onClick: (d, w) => { Store.pick(this, ["image/*"], CaseSheetActivity.REQ_SCAN_PICK); } })
      .setNegativeButton("Cancel", null).show();
  }

  scanCam() {
    this.scanCamera = Imaging.DIR + "/casescan_" + System.currentTimeMillis() + ".jpg";
    if (!Store.capture(this, this.scanCamera, CaseSheetActivity.REQ_SCAN_CAMERA)) this.scanCamera = null;
  }

  scanResult(req, res, data) {
    if (res !== RESULT_OK) {
      if (this.scanPages.length > 0) this.scanMore();
      return;
    }
    try {
      let rel = null;
      if (req === CaseSheetActivity.REQ_SCAN_CAMERA && this.scanCamera != null) {
        rel = this.scanCamera;
        this.scanCamera = null;
      } else if (req === CaseSheetActivity.REQ_SCAN_PICK && data != null && data.getData() != null) rel = Store.importUri(this, data.getData(), Imaging.DIR, "casescan");
      if (rel == null) return;
      const f = this.db.file(rel);
      const jpg = f.exists() ? LabScan.jpeg(f) : null;
      if (jpg == null) {
        f.delete();
        Ui.toast(this, "Pick or take a photo (JPG or PNG)");
        return;
      }
      const out = new FileOutputStream(f);
      try { out.write(jpg); } finally { out.close(); }
      this.scanPages.push(rel);
      this.scanMore();
    } catch (e) {
      Ui.toast(this, "Could not use the picture: " + (e && e.getMessage ? e.getMessage() : e));
    }
  }

  /** After each page: another page, or read what there is. */
  scanMore() {
    const n = this.scanPages.length;
    const b = new AlertDialog.Builder(this).setTitle(n + (n === 1 ? " page" : " pages") + " ready")
      .setMessage(n < CaseScan.MAX_PAGES ? "Add the next page, or read the pages now." : "That is the most pages read at once. Read them now.")
      .setPositiveButton("Read now", { onClick: (d, w) => { this.scanRead(); } })
      .setNegativeButton("Cancel", { onClick: (d, w) => { this.scanClean(); } });
    if (n < CaseScan.MAX_PAGES) b.setNeutralButton("Next page", { onClick: (d, w) => { this.scanCam(); } });
    b.setCancelable(false).show();
  }

  /** Gemini reads the pages with the user's key; without one they go to a free AI chat app. */
  scanRead() {
    if (this.scanPages.length === 0) return;
    if (Ai.geminiKey(this).isEmpty()) {
      this.scanChooseApp();
      return;
    }
    const jpgs = [];
    for (const rel of this.scanPages) {
      const jpg = LabScan.jpeg(this.db.file(rel));
      if (jpg != null) jpgs.push(jpg);
    }
    if (jpgs.length === 0) {
      Ui.toast(this, "Could not open the photos");
      return;
    }
    const wait = new AlertDialog.Builder(this).setTitle("Gemini is reading the pages…")
      .setMessage("Only the photos are sent. Keep the app open.").setCancelable(false).show();
    new Thread({
      run: () => {
        let got = null, err = null;
        try {
          got = Ai.visionPages(this, jpgs, CaseScan.prompt(), null, false);
        } catch (e) {
          if (e instanceof Ai.Failure) err = e.getMessage();
          else err = "Could not read them: " + (e && e.getMessage ? e.getMessage() : e);
        }
        const res = got, error = err;
        this.runOnUiThread({
          run: () => {
            if (this.isFinishing()) return;
            try { wait.dismiss(); } catch (ignored) { }
            this.scanClean();
            if (error != null) {
              new AlertDialog.Builder(this).setTitle("Pages not read").setMessage(error).setPositiveButton("OK", null).show();
              return;
            }
            const parts = CaseScan.parse(res);
            if (parts.isEmpty()) {
              new AlertDialog.Builder(this).setTitle("Nothing could be read")
                .setMessage("Try clearer photos, one page per photo, taken straight from above in good light.").setPositiveButton("OK", null).show();
              return;
            }
            this.previewParts(parts, "Read from the paper case sheet", null);
          }
        });
      }
    }).start();
  }

  scanChooseApp() {
    const apps = DischargeActivity.CHAT_APPS;
    const items = [];
    for (const a of apps) items.push("Free: " + a[0] + " app");
    items.push("Read inside the app: add a free Gemini key");
    new AlertDialog.Builder(this).setTitle("Which AI app reads the pages?")
      .setItems(items, {
        onClick: (d, w) => {
          if (w < apps.length) this.scanToApp(apps[w]);
          else {
            this.scanClean();
            this.open(SettingsActivity);
          }
        }
      }).setNegativeButton("Cancel", { onClick: (d, w) => { this.scanClean(); } }).show();
  }

  scanToApp(app) {
    const prompt = CaseScan.prompt();
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Case sheet question", prompt));
    const uris = [];
    for (const rel of this.scanPages) uris.push(DocProvider.uri(rel));
    const i = new Intent(uris.length === 1 ? Intent.ACTION_SEND : Intent.ACTION_SEND_MULTIPLE);
    i.setType("image/jpeg");
    if (uris.length === 1) i.putExtra(Intent.EXTRA_STREAM, uris[0]);
    else i.putExtra(Intent.EXTRA_STREAM, uris);
    i.putExtra(Intent.EXTRA_TEXT, prompt);
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK);
    AiReturn.expect(this, this.id, AiReturn.SCAN, app[0], prompt);
    i.setPackage(app[1]);
    try {
      this.startActivity(i);
      Ui.toast(this, "In " + app[0] + " send the pages with the question (it is copied too), copy the answer, then come back");
    } catch (noApp) {
      try {
        i.setPackage(null);
        this.startActivity(Intent.createChooser(i, "Send the pages to " + app[0]).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        Ui.toast(this, "Choose " + app[0] + ", send the pages, copy the answer, then come back");
      } catch (e) {
        AiReturn.clear(this);
        Ui.toast(this, app[0] + " is not installed on this phone");
      }
    }
    this.render();
  }

  /** The photos are deleted once read (or given up), so no patient page stays on the phone. */
  scanClean() {
    this.scanPages = [];
    try {
      const fs = this.db.file(Imaging.DIR).listFiles();
      if (fs != null) for (const f of fs) if (f.getName().startsWith("casescan")) f.delete();
    } catch (ignored) { }
  }

  // ---------- dictation: voice to case sheet ----------

  dictLang() {
    try {
      return this.getSharedPreferences("dictation", Context.MODE_PRIVATE).getString("lang", Dictation.EN);
    } catch (e) {
      return Dictation.EN;
    }
  }

  setDictLang(l) {
    try { this.getSharedPreferences("dictation", Context.MODE_PRIVATE).edit().putString("lang", l).apply(); } catch (ignored) { }
  }

  dictLangLabel() {
    return Dictation.TA === this.dictLang() ? "தமிழ் (Tamil)" : "English (India)";
  }

  /** The speech dialog (RecognizerIntent, shimmed on the browser's Web Speech API in _shim_S.js): the browser asks for the microphone. */
  listen(req) {
    const i = new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);
    const lang = this.dictLang();
    i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);
    i.putExtra(RecognizerIntent.EXTRA_LANGUAGE, lang);
    i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_PREFERENCE, lang);
    i.putExtra(RecognizerIntent.EXTRA_PROMPT, req === CaseSheetActivity.REQ_DICT_ALL ? "Say a heading, then its details" : "Speak now");
    i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1);
    i.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS, 3500);
    i.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS, 3500);
    try {
      this.startActivityForResult(i, req);
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      new AlertDialog.Builder(this).setTitle("Voice typing is not available")
        .setMessage("Your browser does not support voice typing. Use Chrome on Android or Safari on iPhone. You can still type.")
        .setPositiveButton("OK", null).show();
    }
  }

  /** Small "Dictate" and language buttons under a free-text field of a section; the spoken text is appended to the field. */
  mic(e, multi) {
    if (!this.editable || !(e.getParent() instanceof LinearLayout)) return;
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    const lang = Ui.softPill(this, this.dictLangLabel(), Ui.MUTED);
    const mic = Ui.softPill(this, "🎤 Dictate", Ui.PRIMARY);
    mic.setOnClickListener({
      onClick: (v) => {
        this.dictTarget = e;
        this.dictMulti = multi;
        this.listen(CaseSheetActivity.REQ_DICT_FIELD);
      }
    });
    lang.setOnClickListener({
      onClick: (v) => {
        this.setDictLang(Dictation.TA === this.dictLang() ? Dictation.EN : Dictation.TA);
        lang.setText(this.dictLangLabel());
      }
    });
    row.addView(mic);
    row.addView(lang);
    Ui.margins(lang, 8, 0, 0, 0);
    e.getParent().addView(row);
    Ui.margins(row, 0, 2, 0, 0);
  }

  /** "Dictate the history" at the top of the case sheet. */
  dictateCard() {
    const card = Ui.card(this);
    card.addView(Ui.title(this, "🎤  Dictate the history"));
    const hint = Ui.muted(this, Dictation.help() + " Nothing is saved until you check the preview.");
    card.addView(hint);
    Ui.margins(hint, 0, 4, 0, 6);
    const lang = Ui.outlineButton(this, "Language: " + this.dictLangLabel(), Ui.SLATE, null);
    lang.setOnClickListener({
      onClick: (v) => {
        this.setDictLang(Dictation.TA === this.dictLang() ? Dictation.EN : Dictation.TA);
        lang.setText("Language: " + this.dictLangLabel());
      }
    });
    card.addView(Ui.buttonRow(this, Ui.button(this, "🎤  Start", Ui.PRIMARY, {
      onClick: (v) => { if (!this.locked()) this.listen(CaseSheetActivity.REQ_DICT_ALL); }
    }), lang));
    return card;
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req === CaseSheetActivity.REQ_SCAN_CAMERA || req === CaseSheetActivity.REQ_SCAN_PICK) {
      this.scanResult(req, res, data);
      return;
    }
    if (req === CaseSheetActivity.REQ_SCAN_LIVE) {
      if (res === RESULT_OK) {
        this.scanPages.addAll(LiveScanActivity.pagesOf(data));
        if (!this.scanPages.isEmpty()) this.scanRead();
      }
      return;
    }
    if (req === CaseSheetActivity.REQ_TAMIL) {
      if (res !== RESULT_OK || data == null) return;
      const rt = data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);
      const words = rt == null || rt.isEmpty() ? "" : MedSpeech.clean(MedSpeech.pickBest(rt.toArray ? rt.toArray() : rt), Dictation.TA);
      if (words.isEmpty()) {
        Ui.toast(this, "Nothing was heard");
        return;
      }
      this.tamilSpoken(words);
      return;
    }
    if (req !== CaseSheetActivity.REQ_DICT_FIELD && req !== CaseSheetActivity.REQ_DICT_ALL) return;
    if (res !== RESULT_OK || data == null) return;
    const r = data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);
    const said = r == null || r.isEmpty() ? "" : MedSpeech.clean(MedSpeech.pickBest(r.toArray ? r.toArray() : r), this.dictLang());
    if (said.isEmpty()) {
      Ui.toast(this, "Nothing was heard");
      return;
    }
    if (req === CaseSheetActivity.REQ_DICT_FIELD) {
      if (this.dictTarget == null) return;
      this.dictTarget.setText(Dictation.append(this.dictTarget.getText().toString(), said, this.dictMulti));
      this.dictTarget.setSelection(this.dictTarget.getText().length());
    } else this.previewDictation(said);
  }

  /** Parsed sections with a tick box and editable text each; OK appends them to the case sheet. */
  previewDictation(said) {
    this.previewParts(Dictation.parse(said), "Dictated history", said);
  }

  /** said: the spoken text (offers "Clean up with AI"), or null for parts read from a paper case sheet. */
  previewParts(parts, title, said) {
    if (parts.isEmpty()) {
      Ui.toast(this, "Nothing to add");
      return;
    }
    const box = Ui.v(this);
    const pad = Ui.dp(this, 20);
    box.setPadding(pad, Ui.dp(this, 4), pad, Ui.dp(this, 8));
    box.addView(Ui.muted(this, "Tick what to add and correct the text if needed. It is added after what is already written; nothing is overwritten. Vitals already filled are kept."));
    const checks = [];
    const edits = [];
    for (const part of parts) {
      const cb = new CheckBox(this);
      const has = part.number && !CaseSheet.s(this.data, part.field).isEmpty();
      cb.setText(part.title + (has ? "  (already filled: kept)" : ""));
      cb.setTextSize(14);
      cb.setChecked(!has);
      const et = new EditText(this);
      et.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
      et.setText(part.text);
      et.setTextSize(15);
      box.addView(cb);
      box.addView(et);
      checks.add(cb);
      edits.add(et);
    }
    const sv = new ScrollView(this);
    sv.addView(box);
    const cleanUp = said != null && AdminControl.aiCheckOn(this.db) && !Ai.engines(this).isEmpty();
    const b = new AlertDialog.Builder(this).setTitle(title).setView(sv)
      .setPositiveButton("Add to case sheet", null).setNegativeButton("Cancel", null);
    if (cleanUp) b.setNeutralButton("Clean up with AI", null);
    const d = b.create();
    d.setOnShowListener({
      onShow: (di) => {
        d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener({
          onClick: (v) => {
            this.applyDictation(parts, checks, edits);
            d.dismiss();
          }
        });
        if (cleanUp) d.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener({
          onClick: (v) => { this.cleanDictation(said, d); }
        });
      }
    });
    d.show();
  }

  applyDictation(parts, checks, edits) {
    if (this.locked()) return;
    let n = 0;
    try {
      for (let i = 0; i < parts.size(); i++) {
        const part = parts.get(i);
        const t = edits.get(i).getText().toString().trim();
        if (!checks.get(i).isChecked() || t.isEmpty()) continue;
        if (part.field === "complaints") {
          const a = CaseSheet.complaints(this.data);
          for (const it of Dictation.complaintItems(t)) {
            let dup = false;
            for (let k = 0; k < a.length(); k++) if (a.optJSONObject(k) != null && a.optJSONObject(k).optString("name").equalsIgnoreCase(it[0])) dup = true;
            if (dup) continue;
            const c = new JSONObject();
            c.put("name", it[0]);
            if (!it[1].isEmpty()) c.put("dur", it[1]);
            a.put(c);
          }
          CaseSheet.putComplaints(this.data, a);
        } else if (part.number) {
          if (!CaseSheet.s(this.data, part.field).isEmpty()) continue;
          this.data.put(part.field, t);
        } else if (part.field === "allergy_note" && Dictation.saysNone(t)) {
          if (CaseSheet.s(this.data, "allergy").isEmpty()) this.data.put("allergy", CaseSheet.ALLERGY_NO);
        } else {
          this.data.put(part.field, Dictation.append(CaseSheet.s(this.data, part.field), t, part.multi));
          if (part.field === "allergy_note" && CaseSheet.s(this.data, "allergy").isEmpty()) this.data.put("allergy", CaseSheet.ALLERGY_YES);
        }
        n++;
      }
      CaseSheet.save(this.db, this.id, this.data);
    } catch (e) {
      if (!(e instanceof JSONException)) throw e;
      Ui.toast(this, "Could not add the dictation");
      return;
    }
    this.render();
    Ui.toast(this, n === 0 ? "Nothing added" : n + (n === 1 ? " item" : " items") + " added. Open each section to check");
  }

  /** Optional: an AI tidies the spoken text (decision support only; the name and numbers that identify the patient are taken out first). */
  cleanDictation(said, preview) {
    const eng = Ai.engines(this);
    if (eng.isEmpty()) return;
    const engine = eng.get(0);
    const text = Ai.deidentify(said, this.p);
    const wait = new AlertDialog.Builder(this).setTitle(engine + " is tidying the text…")
      .setMessage("Only the dictated text is sent, with the name, IP number, phone, address and CMCHIS number taken out first. Keep the app open.").setCancelable(false).show();
    new Thread({
      run: () => {
        let got = null, err = null;
        try {
          got = Ai.single(this, engine,
            "You tidy a doctor's dictated clinical history in India. Keep every fact and number exactly as said. Fix spelling, grammar and obvious speech-recognition errors of medical words only when you are certain. "
              + "Do not add, infer, diagnose or advise anything. Keep the headings the doctor said (complaints, history of present illness, past history, personal history, family history, drug history, allergy, general examination, vitals, "
              + "systemic examination, CVS, respiratory system, abdomen, CNS, provisional diagnosis, plan), each as 'Heading: text' on its own line. Reply with the tidied text only.",
            text, 2000);
        } catch (e) {
          if (e instanceof Ai.Failure) err = e.getMessage();
          else err = "Could not tidy it: " + e.getMessage();
        }
        const res = got, error = err;
        this.runOnUiThread({
          run: () => {
            if (this.isFinishing()) return;
            try { wait.dismiss(); } catch (ignored) { }
            if (error != null) {
              new AlertDialog.Builder(this).setTitle("Not tidied").setMessage(error).setPositiveButton("OK", null).show();
              return;
            }
            try { preview.dismiss(); } catch (ignored) { }
            this.previewDictation(res);
          }
        });
      }
    }).start();
  }

  // ---------- abnormal lab values, as they are typed ----------

  /** Colours a lab value red when high and blue when low, with the normal range under it. */
  watchLab(e, key, f) {
    if (CaseSheet.range(key, this.p.get("sex"), "", "") == null) return;
    const note = Ui.tv(this, "", 12, Ui.MUTED, true);
    e.getParent().addView(note);
    const paint = {
      run: () => {
        const v = e.getText().toString().trim();
        const fl = v.isEmpty() ? "" : CaseSheet.flag(key, v, this.p.get("sex"), this.formView(f));
        const col = fl === "H" ? Ui.RED : fl === "L" ? 0xFF1D4ED8 : Ui.TEXT;
        e.setTextColor(col);
        const rg = CaseSheet.rangeText(key, this.p.get("sex"), this.formView(f));
        note.setText(fl.isEmpty() ? (rg.isEmpty() ? "" : "Normal " + rg) : (fl === "H" ? "↑ High" : "↓ Low") + " (normal " + rg + ")");
        note.setTextColor(fl.isEmpty() ? Ui.MUTED : col);
      }
    };
    paint.run();
    e.addTextChangedListener({
      beforeTextChanged: (x, a, b, d) => {},
      onTextChanged: (x, a, b, d) => {},
      afterTextChanged: (x) => { paint.run(); }
    });
  }

  /** T4 / T3 type as chosen in the open form (their normal ranges depend on it). */
  formView(f) {
    const o = new JSONObject();
    try {
      o.put("t4_type", f.get("t4_type"));
      o.put("t3_type", f.get("t3_type"));
    } catch (ignored) {
    }
    return o;
  }

  // ---------- treatment history from the past history ----------

  /** For each illness ticked in the past history: its drugs (tap to add), how long, and whether taken regularly. */
  rxHistory(f, extra) {
    const list = CaseSheet.comorbidities(this.data);
    if (list.isEmpty()) {
      const h = Ui.muted(this, "Tick the illnesses in Past history first; each then gets its own medicines here.");
      f.view.addView(h);
      return;
    }
    let ci = 0;
    for (const c of list) {
      const k = "rx_" + c[0].substring(3);
      f.heading(c[1]);
      const drugs = f.text(k + "_drug", "Medications (tap below or type)", CaseSheet.s(this.data, k + "_drug"), Form.PLAIN);
      if (c.length > 2) {
        const flow = new Bands.Flow(this);
        const color = Bands.color(ci);
        for (let i = 2; i < c.length; i++) {
          const name = c[i];
          const b = new Bands.Band(this, name, color);
          b.setChecked(CaseSheetActivity.hasDrug(drugs.getText().toString(), name));
          b.setOnCheckedChangeListener({
            onCheckedChanged: (x, on) => {
              const cur = drugs.getText().toString().trim();
              if (on && !CaseSheetActivity.hasDrug(cur, name)) drugs.setText(cur.isEmpty() ? name : cur + ", " + name);
              if (!on) drugs.setText(CaseSheetActivity.removeDrug(cur, name));
            }
          });
          flow.addView(b);
        }
        drugs.getParent().addView(flow);
      }
      f.beginRow();
      f.text(k + "_dur", "Duration (e.g. 5 years)", CaseSheet.s(this.data, k + "_dur"), Form.PLAIN);
      f.endRow();
      f.segment(k + "_reg", "Taking", CaseSheet.REGULAR, CaseSheet.s(this.data, k + "_reg"), "Taking regularly");
      extra.add(k + "_drug");
      extra.add(k + "_dur");
      extra.add(k + "_reg");
      ci++;
    }
    f.heading("Other drugs");
  }

  static hasDrug(list, name) {
    for (const x of list.jsplit(",")) if (x.trim().equalsIgnoreCase(name)) return true;
    return false;
  }

  static removeDrug(list, name) {
    const keep = [];
    for (const x of list.jsplit(",")) if (!x.trim().isEmpty() && !x.trim().equalsIgnoreCase(name)) keep.add(x.trim());
    return TextUtils.join(", ", keep);
  }

  // ---------- history of present illness from the complaints ----------

  /** Tap a complaint to start a line for it in the history; the patient's own complaints come first. */
  hpiFromComplaints(f) {
    const h = Ui.tv(this, "Add from complaints (tap to start a line)", 13, Ui.MUTED, true);
    f.view.addView(h);
    Ui.margins(h, 0, 12, 0, 4);
    const own = new JMap();
    const cl = CaseSheet.complaints(this.data);
    for (let i = 0; i < cl.length(); i++) {
      const c = cl.optJSONObject(i);
      if (c != null && !c.optString("name").trim().isEmpty()) own.put(c.optString("name").trim(), c.optString("dur").trim());
    }
    if (!own.isEmpty()) {
      const mine = new Bands.Flow(this);
      for (const e of own.entrySet()) mine.addView(this.hpiBand(f, e.getKey(), e.getValue(), Ui.PRIMARY));
      f.view.addView(mine);
    }
    const all = Ui.v(this);
    all.setVisibility(View.GONE);
    let gi = 0;
    for (const g of CaseSheet.COMPLAINT_GROUPS) {
      const color = Bands.color(gi++);
      const gh = Ui.tv(this, g[0][0], 12, Bands.ink(color), true);
      gh.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 2));
      all.addView(gh);
      const fl = new Bands.Flow(this);
      for (let i = 1; i < g.length; i++) if (!own.containsKey(g[i][0])) fl.addView(this.hpiBand(f, g[i][0], "", color));
      all.addView(fl);
    }
    const more = Ui.outlineButton(this, "Show all complaints", Ui.PRIMARY, null);
    more.setOnClickListener({
      onClick: (v) => {
        const show = all.getVisibility() !== View.VISIBLE;
        all.setVisibility(show ? View.VISIBLE : View.GONE);
        more.setText(show ? "Hide the list" : "Show all complaints");
      }
    });
    f.view.addView(more);
    Ui.margins(more, 0, 6, 0, 0);
    f.view.addView(all);
  }

  hpiBand(f, name, dur, color) {
    const b = new Bands.Band(this, name, color);
    b.setChecked(CaseSheetActivity.hpiLineIndex(f.get("hpi"), name) >= 0);
    b.setOnClickListener({
      onClick: (v) => {
        b.setChecked(CaseSheetActivity.hpiLineIndex(f.get("hpi"), name) >= 0);
        this.hpiDialog(f, name, dur, b);
      }
    });
    return b;
  }

  /** The line of the HPI that begins with this complaint, or -1. */
  static hpiLineIndex(hpi, name) {
    const lines = Ui.nz(hpi).jsplit("\n", -1);
    const n = name.toLowerCase();
    for (let i = 0; i < lines.length; i++) if (lines[i].trim().toLowerCase().startsWith(n)) return i;
    return -1;
  }

  /** Duration, onset, course and the usual descriptions of one complaint; writes (or rewrites) its line in the HPI. */
  hpiDialog(f, name, dur, band) {
    const d = new Form(this);
    d.text("dur", "Duration (e.g. 5 days, 2 weeks)", dur, Form.PLAIN);
    d.segment("unit", "Duration in", ["", "hours", "days", "weeks", "months", "years"], "");
    d.segment("onset", "Onset", CaseSheet.HPI_ONSET, "");
    d.segment("course", "Course", CaseSheet.HPI_COURSE, "");
    const desc = CaseSheet.hpiDesc(name);
    if (desc.length > 0) {
      d.heading("Description");
      for (let i = 0; i < desc.length; i++) d.check("d" + i, desc[i], false);
    }
    d.multi("more", "Other details", "");
    Ui.formDialog(this, name, d, "Add to history", {
      run: () => {
        let du = d.get("dur").trim();
        const u = d.get("unit");
        if (!u.isEmpty() && du.matches("\\d+(\\.\\d+)?")) du = du + " " + (du === "1" ? u.substring(0, u.length - 1) : u);
        else if (!u.isEmpty() && du.isEmpty()) du = u;
        const picked = [];
        for (let i = 0; i < desc.length; i++) if ("1" === d.get("d" + i)) picked.add(desc[i]);
        const line = CaseSheet.hpiLine(name, du, picked, d.get("onset"), d.get("course"), d.get("more"));
        const cur = f.get("hpi");
        const at = CaseSheetActivity.hpiLineIndex(cur, name);
        if (at >= 0) {
          const lines = cur.jsplit("\n", -1);
          lines[at] = line;
          f.set("hpi", TextUtils.join("\n", lines));
        } else f.set("hpi", cur.isEmpty() ? line : cur + "\n" + line);
        band.setChecked(true);
        return true;
      }
    });
  }

  // ---------- ABG calculator ----------

  /** Works out the acid-base disorder as the values are typed, and can put the reading in the impression. */
  abgCalculator(f, hook) {
    const box = Ui.v(this);
    box.setBackground(Ui.outline(this, Ui.mix(Ui.PURPLE, Color.WHITE, 0.92), Ui.PURPLE, 12));
    box.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 10));
    box.addView(Ui.tv(this, "ABG calculator", 14, Ui.PURPLE, true));
    const out = Ui.tv(this, "", 14, Ui.TEXT, true);
    const steps = Ui.tv(this, "", 12, Ui.MUTED, false);
    box.addView(out);
    box.addView(steps);
    const use = Ui.outlineButton(this, "Use as impression", Ui.PURPLE, null);
    box.addView(use);
    Ui.margins(use, 0, 8, 0, 0);
    f.view.addView(box);
    Ui.margins(box, 0, 14, 0, 0);
    const keys = ["abg_ph", "abg_po2", "abg_pco2", "abg_hco3", "abg_na", "abg_cl", "abg_alb", "abg_fio2", "abg_ag", "abg_course"];
    const calc = {
      run: () => {
        const o = new JSONObject();
        try {
          for (const k of keys) o.put(k, f.get(k));
        } catch (ignored) {
        }
        const c = CaseSheet.abgCalc(o);
        if (c == null) {
          out.setText("Enter pH, pCO2 and HCO3 to see the reading.");
          steps.setText("");
          use.setVisibility(View.GONE);
          return;
        }
        out.setText(CaseSheet.cap(c.reading));
        steps.setText(TextUtils.join("\n", c.steps));
        use.setVisibility(View.VISIBLE);
        use.setTag(CaseSheet.cap(c.reading));
      }
    };
    use.setOnClickListener({ onClick: (v) => { f.set("abg", String(use.getTag())); } });
    CaseSheetActivity.attachWatchers(f.view, calc);
    hook[0] = calc;
    calc.run();
  }

  // ---------- ECG impression from the findings ----------

  /** Works out the ECG impression as findings are chosen; it is used when the impression is left blank, or copied in with a tap. */
  ecgCalculator(f, fs, hook) {
    const box = Ui.v(this);
    box.setBackground(Ui.outline(this, Ui.mix(Ui.PURPLE, Color.WHITE, 0.92), Ui.PURPLE, 12));
    box.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 10));
    box.addView(Ui.tv(this, "Calculated impression", 14, Ui.PURPLE, true));
    const out = Ui.tv(this, "", 14, Ui.TEXT, true);
    box.addView(out);
    box.addView(Ui.muted(this, "Worked out on this phone from the findings above (rate, intervals, blocks, axis, ST/T by territory, QTc). Check it against the tracing."));
    const use = Ui.outlineButton(this, "Use as final impression", Ui.PURPLE, null);
    box.addView(use);
    Ui.margins(use, 0, 8, 0, 0);
    f.view.addView(box);
    Ui.margins(box, 0, 14, 0, 0);
    const sex = this.p.get("sex");
    const calc = {
      run: () => {
        const o = new JSONObject();
        try {
          for (const fd of fs) if (!fd.key.isEmpty() && fd.key !== "ecg" && CaseSheetActivity.visible(f, fs, fd)) o.put(fd.key, f.get(fd.key));
        } catch (ignored) {
        }
        const imp = CaseSheet.ecgImpression(o, sex);
        out.setText(imp.isEmpty() ? "Choose the rhythm, rate and intervals to see the impression." : imp);
        use.setVisibility(imp.isEmpty() ? View.GONE : View.VISIBLE);
        use.setTag(imp);
      }
    };
    use.setOnClickListener({ onClick: (v) => { f.set("ecg", String(use.getTag())); } });
    CaseSheetActivity.attachWatchers(f.view, calc);
    hook[0] = calc;
    calc.run();
  }

  // ---------- alcohol grams and pack-years ----------

  /** Fills the alcohol % from the brand, and works out grams of alcohol a day and pack-years as they are entered. */
  habitCalculator(f, hook) {
    const brand = [CaseSheet.s(this.data, "alc_brand")];
    const keys = ["alc_brand", "alc_abv", "alc_qty", "alc_unit", "alc_days", "alc_per", "smk_years", "smk_packs", "smk_sticks"];
    const calc = {
      run: () => {
        const b = f.get("alc_brand");
        if (b !== brand[0]) {
          brand[0] = b;
          const r = CaseSheet.row(CaseSheet.ALC_BRANDS, b);
          if (r != null) CaseSheetActivity.setIfChanged(f, "alc_abv", r[2]);
        }
        const o = new JSONObject();
        try {
          for (const k of keys) o.put(k, f.get(k));
        } catch (ignored) {
        }
        CaseSheetActivity.setIfChanged(f, "alc_calc", CaseSheet.alcoholCalc(o));
        CaseSheetActivity.setIfChanged(f, "smk_calc", CaseSheet.smokingCalc(o));
      }
    };
    CaseSheetActivity.attachWatchers(f.view, calc);
    hook[0] = calc;
    calc.run();
  }

  static setIfChanged(f, key, v) {
    if (f.has(key) && f.get(key) !== v) f.set(key, v);
  }

  /** Re-runs r whenever any text box or band in the form changes. */
  static attachWatchers(v, r) {
    if (v instanceof EditText) {
      v.addTextChangedListener({
        beforeTextChanged: (x, a, b, d) => {},
        onTextChanged: (x, a, b, d) => {},
        afterTextChanged: (x) => { run(r); }
      });
    } else if (v instanceof CompoundButton) {
      v.setOnCheckedChangeListener({ onCheckedChanged: (b, on) => { run(r); } });
    } else if (v instanceof ViewGroup) {
      const g = v;
      for (let i = 0; i < g.getChildCount(); i++) CaseSheetActivity.attachWatchers(g.getChildAt(i), r);
    }
  }

  // ---------- course in hospital written by AI (names taken out first) ----------

  courseAi(f) {
    const hint = Ui.muted(this, "AI can write this paragraph from the rest of the case sheet. Anything typed here is used as notes. Check it before you save.");
    f.view.addView(hint);
    Ui.margins(hint, 0, 10, 0, 0);
    const ai = Ui.button(this, "✨  Write course with AI", Ui.PURPLE, { onClick: (v) => { this.askCourseAi(f); } });
    f.view.addView(ai);
    Ui.margins(ai, 0, 8, 0, 0);
    const paste = Ui.button(this, "📋  Paste the AI answer", Ui.AMBER, { onClick: (v) => { this.pasteCourse(f); } });
    f.view.addView(paste);
    Ui.margins(paste, 0, 8, 0, 0);
  }

  /** The case sheet as the summary headings, plus what the doctor has typed for the course so far. */
  courseSecs(f) {
    const secs = CaseSheet.summary(this.db, this.p, this.data);
    if (!f.get("course").trim().isEmpty()) secs.put("Doctor's notes on the course (use and expand)", f.get("course"));
    return secs;
  }

  askCourseAi(f) {
    const eng = Ai.engines(this);
    const apps = DischargeActivity.CHAT_APPS;
    const items = [];
    for (const a of apps) items.add("Free: " + a[0] + " app");
    for (const x of eng) items.add(Ai.engineLabel(x));
    if (eng.isEmpty()) items.add("Write here: add a free Gemini key or a Claude key");
    new AlertDialog.Builder(this).setTitle("Write course with AI")
      .setItems(items.slice(), {
        onClick: (d, w) => {
          if (w < apps.length) this.courseToApp(f, apps[w]);
          else if (w - apps.length < eng.size()) this.courseByKey(f, eng.get(w - apps.length));
          else this.open(SettingsActivity);
        }
      }).setNegativeButton("Cancel", null).show();
  }

  courseToApp(f, app) {
    const prompt = Ai.coursePrompt(this.courseSecs(f), this.p);
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Course for AI", prompt));
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, prompt);
    i.setPackage(app[1]);
    i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
    AiReturn.expect(this, this.id, AiReturn.COURSE, app[0], prompt);
    try {
      this.startActivity(i);
      Ui.toast(this, "In " + app[0] + ", copy the answer, then come back to TVMCHMED");
    } catch (noApp) {
      try {
        this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(app[2])).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        Ui.toast(this, "Copied: paste it in " + app[0] + ", then copy the answer back");
      } catch (e) {
        Ui.toast(this, "Copied: open " + app[0] + " and paste it");
      }
    }
  }

  pasteCourse(f) {
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    let text = "";
    if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
      const c = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
      text = c == null ? "" : c.toString();
    }
    try {
      if (AiReturn.isPrompt(this, text)) throw new Ai.Failure("The clipboard still has the notes sent to the AI app. In that app, tap Copy under its answer first.");
      f.set("course", Ai.parseCourse(text));
      AiReturn.clear(this);
      Ui.toast(this, "Pasted. Check it, then Save");
    } catch (e) {
      if (!(e instanceof Ai.Failure)) throw e;
      new AlertDialog.Builder(this).setTitle("Nothing to paste yet").setMessage(e.getMessage()).setPositiveButton("OK", null).show();
    }
  }

  courseByKey(f, engine) {
    const secs = this.courseSecs(f);
    const pt = this.p;
    const wait = new AlertDialog.Builder(this).setTitle(engine + " is writing…")
      .setMessage("The name, IP number, phone, address and CMCHIS number are taken out first. Keep the app open.").setCancelable(false).show();
    new Thread({
      run: () => {
        let got = null, err = null;
        try {
          got = Ai.course(this, engine, secs, pt);
        } catch (e) {
          if (e instanceof Ai.Failure) err = e.getMessage();
          else err = "Could not write it: " + e.getMessage();
        }
        const res = got, error = err;
        this.runOnUiThread({
          run: () => {
            if (this.isFinishing()) return;
            try { wait.dismiss(); } catch (ignored) { }
            if (error != null) {
              new AlertDialog.Builder(this).setTitle("Course not written").setMessage(error).setPositiveButton("OK", null).show();
              return;
            }
            f.set("course", res);
            Ui.toast(this, "Written by " + engine + " AI. Check it, then Save");
          }
        });
      }
    }).start();
  }

  // ---------- coming back from ChatGPT, Claude or Gemini ----------

  /** "Back from ChatGPT?" card with a Paste button while an answer is awaited for this patient. */
  returnBanner() {
    const w = AiReturn.waiting(this, this.id);
    if (w == null || !this.editable || AiReturn.LABS === w[0]) return null;
    const c = Ui.card(this);
    c.setBackground(Ui.round(this, Ui.alpha(CaseSheetActivity.AI_COLOR, 0x1C), 16));
    const what = AiReturn.REVIEW === w[0] ? "AI check" : AiReturn.SCAN === w[0] ? "Paper case sheet" : "Course in hospital";
    c.addView(Ui.tv(this, "↩  Waiting for " + w[1] + "'s answer (" + what + ")", 15, CaseSheetActivity.AI_COLOR, true));
    c.addView(Ui.muted(this, "In " + w[1] + ", tap Copy under its answer, come back here and tap Paste."));
    const row = Ui.buttonRow(this,
      Ui.button(this, "📋  Paste " + w[1] + "'s answer", CaseSheetActivity.AI_COLOR, { onClick: (v) => { this.pasteReturn(w[0], w[1], true); } }),
      Ui.button(this, "Cancel", Ui.SLATE, {
        onClick: (v) => {
          AiReturn.clear(this);
          this.render();
        }
      }));
    c.addView(row);
    Ui.margins(row, 0, 8, 0, 0);
    return c;
  }

  /** Back from the AI app with its answer copied: offer to paste it at once (the clipboard is readable only with focus). */
  onWindowFocusChanged(focus) {
    super.onWindowFocusChanged(focus);
    if (!focus || this.askedThisFocus || !this.editable) return;
    const w = AiReturn.waiting(this, this.id);
    if (w == null || AiReturn.LABS === w[0]) return;
    const text = this.clip();
    if (text.isEmpty() || AiReturn.isPrompt(this, text)) return;
    this.askedThisFocus = true;
    new AlertDialog.Builder(this).setTitle("Paste " + w[1] + "'s answer?")
      .setMessage(text.length > 300 ? text.substring(0, 300) + "…" : text)
      .setPositiveButton("Paste", { onClick: (d, x) => { this.pasteReturn(w[0], w[1], true); } })
      .setNegativeButton("Not now", null).show();
  }

  onPause() {
    super.onPause();
    this.askedThisFocus = false;
  }

  clip() {
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    try {
      if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
        const c = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
        return c == null ? "" : c.toString();
      }
    } catch (ignored) { }
    return "";
  }

  /** Puts the copied answer where it belongs: the AI check, or the course in hospital. */
  pasteReturn(kind, app, explain) {
    const text = this.clip();
    try {
      if (AiReturn.isPrompt(this, text)) throw new Ai.Failure("The clipboard still has the case sent to " + app + ". In " + app + ", tap Copy under its answer first.");
      if (AiReturn.SCAN === kind) {
        const parts = CaseScan.parse(text);
        if (parts.isEmpty()) throw new Ai.Failure("No case sheet headings were found in the copied text. In " + app + ", tap Copy under its answer (lines like Chief complaints: ...) and try again.");
        AiReturn.clear(this);
        this.scanClean();
        this.render();
        this.previewParts(parts, "Read from the paper case sheet", null);
      } else if (AiReturn.REVIEW === kind) {
        const rev = Ai.parseReview(text);
        AiReturn.clear(this);
        this.saveReview(rev, app);
      } else {
        const course = Ai.parseCourse(text);
        AiReturn.clear(this);
        this.data.put("course", course);
        DischargeActivity.forgetCourseEdits(this.data);
        CaseSheet.save(this.db, this.id, this.data);
        this.render();
        Ui.toast(this, "Course in hospital pasted. Open it to check");
      }
    } catch (e) {
      if (e instanceof Ai.Failure) {
        if (explain) new AlertDialog.Builder(this).setTitle("Nothing to paste yet").setMessage(e.getMessage()).setPositiveButton("OK", null).show();
      } else if (!(e instanceof JSONException)) throw e;
    }
  }

  // ---------- progress notes ----------

  progressList(card) {
    const notes = CaseSheet.notesByTime(this.data);
    if (notes.isEmpty()) {
      const m = Ui.muted(this, "One note a day (or whenever things change): what changed in the history, the findings, new results, any new diagnosis and the plan.");
      card.addView(m);
      Ui.margins(m, 0, 6, 0, 0);
    }
    // newest first
    for (let k = notes.size() - 1; k >= 0; k--) {
      const n = notes.get(k);
      const idx = n.optInt("_i", -1);
      const row = Ui.v(this);
      row.setBackground(Ui.round(this, Ui.alpha(CaseSheetActivity.PROGRESS_COLOR, 0x14), 12));
      row.setPadding(Ui.dp(this, 10), Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 8));
      const top = Ui.h(this);
      top.setGravity(Gravity.CENTER_VERTICAL);
      top.addView(Ui.tv(this, CaseSheet.noteHead(n, this.p.get("admit_date")), 14, CaseSheetActivity.PROGRESS_COLOR, true), Ui.weight(1));
      const st = CaseSheet.s(n, "status");
      if (!st.isEmpty()) top.addView(Ui.softPill(this, st, CaseSheetActivity.statusColor(st)));
      row.addView(top);
      const body = CaseSheet.noteBody(n).replaceAllRx("(?m)^Status: .*\n?", "");
      if (!body.isEmpty()) row.addView(Ui.tv(this, body, 13, Ui.TEXT, false));
      if (!CaseSheet.s(n, "new_dx").isEmpty()) row.addView(Ui.tv(this, "➕ New diagnosis: " + CaseSheet.s(n, "new_dx"), 13, Ui.RED, true));
      if (!CaseSheet.s(n, "by").isEmpty()) row.addView(Ui.muted(this, "By " + CaseSheet.s(n, "by")));
      Ui.ripple(row, Ui.alpha(CaseSheetActivity.PROGRESS_COLOR, 0x22));
      row.setOnClickListener({ onClick: (v) => { this.note(idx); } });
      card.addView(row);
      Ui.margins(row, 0, 8, 0, 0);
    }
    if (this.editable) {
      const add = Ui.outlineButton(this, "+ Add progress note", CaseSheetActivity.PROGRESS_COLOR, { onClick: (v) => { this.note(-1); } });
      card.addView(add);
      Ui.margins(add, 0, 8, 0, 0);
      const ta = Ui.outlineButton(this, "🎙 Speak in Tamil → English note", CaseSheetActivity.PROGRESS_COLOR, {
        onClick: (v) => { this.tamilNote(); }
      });
      card.addView(ta);
      Ui.margins(ta, 0, 8, 0, 0);
      const app = AiRun.waiting(this, this.tamilWait());
      if (!app.isEmpty()) {
        const paste = Ui.button(this, "Paste " + app + "'s English note", CaseSheetActivity.PROGRESS_COLOR, {
          onClick: (v) => {
            const t = AiRun.paste(this, this.tamilWait(), TamilNote.MARK);
            if (t != null) this.note(-1, TamilNote.parse(t));
          }
        });
        card.addView(paste);
        Ui.margins(paste, 0, 8, 0, 0);
      }
    }
  }

  // ---------- Tamil voice to English progress note (8.30) ----------

  tamilWait() {
    return "tamilnote_wait_" + this.id;
  }

  /** The browser's speech dialog in Tamil (RecognizerIntent, as the other dictation buttons); the words come back in onActivityResult. */
  tamilNote() {
    this.setDictLang(Dictation.TA);
    const i = new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);
    i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);
    i.putExtra(RecognizerIntent.EXTRA_LANGUAGE, Dictation.TA);
    i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_PREFERENCE, Dictation.TA);
    i.putExtra(RecognizerIntent.EXTRA_PROMPT, "Speak the progress note (Tamil or English)");
    i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1);
    i.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS, 3500);
    i.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS, 3500);
    try {
      this.startActivityForResult(i, CaseSheetActivity.REQ_TAMIL);
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(this, "The microphone or speech service is not available on this phone");
    }
  }

  /** The spoken words (names taken out) go to the AI; its English note opens in the progress note form to check. */
  tamilSpoken(text) {
    if (Ui.nz(text).trim().isEmpty()) return;
    const spoken = Ai.deidentify(text, this.p);
    AiRun.ask(this, "Writing the English note", TamilNote.system(), TamilNote.user(spoken), 3000, this.tamilWait(),
        "Keep the words as spoken", {
          got: (res, who) => {
            let pre = new JSONObject();
            if (res == null) {
              try { pre.put("hx", spoken); } catch (ignored) { }
            } else pre = TamilNote.parse(res);
            this.note(-1, pre);
          }
        });
  }

  static statusColor(st) {
    switch (st) {
      case "Better": return Ui.GREEN;
      case "Worse": return Ui.ORANGE;
      case "Critical": return Ui.RED;
      default: return Ui.MUTED;
    }
  }

  /** Adds (idx -1) or edits a progress note. prefill: a new note's parts written from speech (Tamil note, 8.30), to check before saving. */
  note(idx, prefill) {
    if (prefill === undefined) prefill = null;
    const all = CaseSheet.notes(this.data);
    const n = idx >= 0 ? all.optJSONObject(idx) : null;
    const src = n != null ? n : prefill;
    const f = new Form(this);
    f.date("date", "Date", n == null ? Dates.todayIso() : CaseSheet.s(n, "date"));
    f.time("time", "Time", n == null ? Dates.now() : CaseSheet.s(n, "time"));
    f.segment("status", "Patient today", CaseSheet.PROGRESS_STATUS, src == null ? "" : CaseSheet.s(src, "status"), "Better");
    f.multi("hx", "Changes in history / new symptoms", src == null ? "" : CaseSheet.s(src, "hx"));
    f.heading("Vitals");
    const vit = [["pr", "Pulse (/min)"], ["sbp", "SBP (mmHg)"], ["dbp", "DBP (mmHg)"], ["rr", "RR (/min)"], ["spo2", "SpO2 (%)"], ["temp", "Temp (°F)"], ["grbs", "GRBS (mg/dl)"]];
    for (let i = 0; i < vit.length; i++) {
      if (i % 2 === 0) f.beginRow();
      f.text(vit[i][0], vit[i][1], src == null ? "" : CaseSheet.s(src, vit[i][0]), Form.DECIMAL);
      if (i % 2 === 1 || i === vit.length - 1) f.endRow();
    }
    f.multi("exam", "Clinical findings (new or changed signs)", src == null ? "" : CaseSheet.s(src, "exam"));
    f.multi("results", "New investigation results", src == null ? "" : CaseSheet.s(src, "results"));
    f.multi("new_dx", "New diagnosis added today", src == null ? "" : CaseSheet.s(src, "new_dx"));
    Diagnoses.attach(this, f, "new_dx");
    f.multi("plan", "Plan / changes in treatment", src == null ? "" : CaseSheet.s(src, "plan"));
    if (this.editable) f.check("to_dx", "Add the new diagnosis to the patient's diagnosis", true);
    if (this.editable && n != null) f.check("delete", "Delete this note (tap Save)", false);
    if (!this.editable) {
      Ui.formDialog(this, "Progress note  (view only)", f, "Close", { run: () => true });
      return;
    }
    Ui.formDialog(this, n == null ? "Progress note" : "Edit progress note", f, "Save", {
      run: () => {
        if ("1" === f.get("delete")) {
          const keep = new JSONArray();
          for (let i = 0; i < all.length(); i++) if (i !== idx) keep.put(all.opt(i));
          try { this.data.put(CaseSheet.PROGRESS, keep); } catch (ignored) { }
          CaseSheet.save(this.db, this.id, this.data);
          this.render();
          return true;
        }
        const keys = ["date", "time", "status", "hx", "pr", "sbp", "dbp", "rr", "spo2", "temp", "grbs", "exam", "results", "new_dx", "plan"];
        const o = new JSONObject();
        let any = false;
        try {
          for (const k of keys) {
            const v = f.get(k).trim();
            if (v.isEmpty()) continue;
            o.put(k, v);
            if (k !== "date" && k !== "time") any = true;
          }
          if (!any) {
            Ui.toast(this, "Write what changed, the findings or the plan");
            return false;
          }
          o.put("by", n != null && !CaseSheet.s(n, "by").isEmpty() ? CaseSheet.s(n, "by") : CallDutyActivity.myName(this));
          if (n == null) all.put(o);
          else all.put(idx, o);
          this.data.put(CaseSheet.PROGRESS, all);
        } catch (e) {
          if (e instanceof JSONException) return true;
          throw e;
        }
        if ("1" === f.get("to_dx") && !f.get("new_dx").trim().isEmpty()) {
          const dx = Ui.nz(this.p.get("diagnosis"));
          const merged = Diagnoses.parts(dx).isEmpty() ? f.get("new_dx").trim() : CaseSheetActivity.withNew(dx, f.get("new_dx"));
          if (merged !== dx) {
            const cv = new ContentValues();
            cv.put("diagnosis", merged);
            this.db.update("patients", cv, this.id);
          }
        }
        CaseSheet.save(this.db, this.id, this.data);
        this.render();
        return true;
      }
    });
  }

  /** The diagnosis text with the parts of add that it does not already name. */
  static withNew(dx, add) {
    const b = new StringBuilder(Ui.nz(dx).trim());
    for (const d of Diagnoses.parts(add)) {
      if (b.toString().toLowerCase().contains(d.toLowerCase())) continue;
      if (b.length() > 0) b.append(", ");
      b.append(d);
    }
    return b.toString();
  }

  /** Final diagnosis form: starts from the working diagnosis and offers the diagnoses added in the progress notes. */
  finalDxHelp(f) {
    if (f.get("final_dx").trim().isEmpty()) f.set("final_dx", Ui.nz(this.p.get("diagnosis")));
    const added = CaseSheet.newDiagnoses(this.data);
    if (added.isEmpty()) return;
    const m = Ui.tv(this, "Added in the progress notes: " + TextUtils.join(", ", added), 13, CaseSheetActivity.PROGRESS_COLOR, true);
    f.view.addView(m);
    Ui.margins(m, 0, 10, 0, 0);
    const b = Ui.outlineButton(this, "Add these to the final diagnosis", CaseSheetActivity.PROGRESS_COLOR, {
      onClick: (v) => {
        f.set("final_dx", CaseSheetActivity.withNew(f.get("final_dx"), TextUtils.join(", ", added)));
      }
    });
    f.view.addView(b);
    Ui.margins(b, 0, 6, 0, 0);
  }

  // ---------- AI check: differential diagnosis and treatment ----------

  aiReviewCard(card) {
    const warn = Ui.tv(this, "⚠ Decision support only. AI can be wrong or out of date. It does not replace the treating doctor, "
      + "the unit faculty or the drug chart: check every dose before acting. The name, IP number, phone, address and CMCHIS number are taken out first.", 12, 0xFF92400E, false);
    warn.setBackground(Ui.round(this, Ui.alpha(Ui.AMBER, 0x22), 10));
    warn.setPadding(Ui.dp(this, 10), Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 8));
    card.addView(warn);
    Ui.margins(warn, 0, 8, 0, 0);
    const rev = CaseSheet.s(this.data, CaseSheet.AI_REVIEW);
    if (!rev.isEmpty()) {
      const when = CaseSheet.s(this.data, "ai_review_at"), by = CaseSheet.s(this.data, "ai_review_by");
      const meta = Ui.tv(this, "Checked" + (by.isEmpty() ? "" : " by " + by) + (when.isEmpty() ? "" : " on " + when)
        + (this.reviewStale() ? "  ·  the case sheet changed since: run it again" : ""), 12, this.reviewStale() ? Ui.ORANGE : Ui.MUTED, true);
      card.addView(meta);
      Ui.margins(meta, 0, 8, 0, 0);
      const t = Ui.tv(this, rev, 13, Ui.TEXT, false);
      t.setMaxLines(8);
      t.setEllipsize(TextUtils.TruncateAt.END);
      card.addView(t);
      Ui.margins(t, 0, 4, 0, 0);
      const read = Ui.outlineButton(this, "Read the full AI check", CaseSheetActivity.AI_COLOR, { onClick: (v) => { this.showReview(); } });
      card.addView(read);
      Ui.margins(read, 0, 8, 0, 0);
    } else {
      const m = Ui.muted(this, "AI reads the whole case sheet (history, examination, results, treatment, progress notes) and lists the differential diagnosis, "
        + "must-not-miss conditions, tests to consider, and checks each drug for dose, kidney or liver adjustment, interactions, allergy and contraindications.");
      card.addView(m);
      Ui.margins(m, 0, 8, 0, 0);
    }
    if (!this.editable) return;
    const row = Ui.buttonRow(this,
      Ui.button(this, "✨  " + (rev.isEmpty() ? "Check with AI" : "Check again"), CaseSheetActivity.AI_COLOR, { onClick: (v) => { this.askReview(); } }),
      Ui.button(this, "📋  Paste answer", Ui.AMBER, { onClick: (v) => { this.pasteReview(); } }));
    card.addView(row);
    Ui.margins(row, 0, 8, 0, 0);
  }

  /** True when the case sheet text sent to the AI is no longer what it was when the check was made. */
  reviewStale() {
    const h = CaseSheet.s(this.data, "ai_review_hash");
    return !h.isEmpty() && h !== this.reviewHash();
  }

  reviewHash() {
    return Integer.toHexString(Ai.reviewNotes(this.reviewSecs(), this.p).hashCode());
  }

  /** Everything the case sheet holds, as summary headings, with the progress notes. */
  reviewSecs() {
    const all = CaseSheet.summary(this.db, this.p, this.data), out = new JMap();
    const dx = CaseSheet.withNewDiagnoses(Ui.nz(this.p.get("diagnosis")), this.data);
    if (!dx.isEmpty()) out.put("Working diagnosis", dx);
    if (!CaseSheet.s(this.data, "final_dx").isEmpty()) out.put("Final diagnosis (as written)", CaseSheet.s(this.data, "final_dx"));
    const skip = ["Diagnosis", "Course in the hospital", "Condition on discharge", "Advice on discharge", "Follow-up"];
    for (const e of all.entrySet()) {
      if (skip.contains(e.getKey())) continue;
      out.put(e.getKey(), e.getValue());
    }
    if (!CaseSheet.s(this.data, "course").isEmpty()) out.put("Course so far", CaseSheet.s(this.data, "course"));
    const prog = CaseSheet.progressText(this.data, this.p.get("admit_date"), false);
    if (!prog.isEmpty()) out.put("Progress notes", prog);
    return out;
  }

  askReview() {
    const eng = Ai.engines(this);
    const apps = DischargeActivity.CHAT_APPS;
    const items = [];
    for (const a of apps) items.add("Free: " + a[0] + " app");
    for (const x of eng) items.add(Ai.engineLabel(x));
    if (eng.isEmpty()) items.add("Check here: add a free Gemini key or a Claude key");
    new AlertDialog.Builder(this).setTitle("AI check: diagnosis and treatment")
      .setItems(items.slice(), {
        onClick: (d, w) => {
          if (w < apps.length) this.reviewToApp(apps[w]);
          else if (w - apps.length < eng.size()) this.reviewByKey(eng.get(w - apps.length));
          else this.open(SettingsActivity);
        }
      }).setNegativeButton("Cancel", null).show();
  }

  reviewToApp(app) {
    const prompt = Ai.reviewPrompt(this.reviewSecs(), this.p);
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Case for AI check", prompt));
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, prompt);
    i.setPackage(app[1]);
    i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
    AiReturn.expect(this, this.id, AiReturn.REVIEW, app[0], prompt);
    try {
      this.startActivity(i);
      Ui.toast(this, "In " + app[0] + ", copy the answer, then come back to TVMCHMED");
    } catch (noApp) {
      try {
        this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(app[2])).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        Ui.toast(this, "Copied: paste it in " + app[0] + ", then copy the answer back");
      } catch (e) {
        Ui.toast(this, "Copied: open " + app[0] + " and paste it");
      }
    }
    try { this.data.put("ai_review_pending", app[0]); } catch (ignored) { }
    CaseSheet.save(this.db, this.id, this.data);
  }

  pasteReview() {
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    let text = "";
    if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
      const c = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
      text = c == null ? "" : c.toString();
    }
    try {
      if (AiReturn.isPrompt(this, text)) throw new Ai.Failure("The clipboard still has the case sent to the AI app. In that app, tap Copy under its answer first.");
      const by = CaseSheet.s(this.data, "ai_review_pending");
      this.saveReview(Ai.parseReview(text), by.isEmpty() ? "AI app" : by);
    } catch (e) {
      if (!(e instanceof Ai.Failure)) throw e;
      new AlertDialog.Builder(this).setTitle("Nothing to paste yet").setMessage(e.getMessage()).setPositiveButton("OK", null).show();
    }
  }

  saveReview(text, by) {
    try {
      this.data.put(CaseSheet.AI_REVIEW, text);
      this.data.put("ai_review_by", by);
      this.data.put("ai_review_at", Dates.nice(Dates.todayIso()) + " " + Dates.now());
      this.data.put("ai_review_hash", this.reviewHash());
      this.data.remove("ai_review_pending");
      AiReturn.clear(this);
    } catch (e) {
      if (e instanceof JSONException) return;
      throw e;
    }
    CaseSheet.save(this.db, this.id, this.data);
    this.render();
    this.showReview();
  }

  showReview() {
    const rev = CaseSheet.s(this.data, CaseSheet.AI_REVIEW);
    if (rev.isEmpty()) return;
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 18), Ui.dp(this, 8), Ui.dp(this, 18), Ui.dp(this, 8));
    const warn = Ui.tv(this, "Decision support only: the treating doctor decides. Check doses and discuss with the unit faculty.", 12, 0xFF92400E, true);
    box.addView(warn);
    for (const line of rev.jsplit("\n")) {
      const t = line.trim();
      let head = false;
      for (const h of Ai.REVIEW_HEADS) if (t.split(":").join("").equalsIgnoreCase(h)) head = true;
      const tv = Ui.tv(this, t, head ? 15 : 14, head ? CaseSheetActivity.AI_COLOR : Ui.TEXT, head);
      if (head) tv.setPadding(0, Ui.dp(this, 10), 0, 0);
      box.addView(tv);
    }
    const sv = new ScrollView(this);
    sv.addView(box);
    new AlertDialog.Builder(this).setTitle("AI check").setView(sv)
      .setPositiveButton("Close", null)
      .setNeutralButton("Share", {
        onClick: (d, w) => {
          const i = new Intent(Intent.ACTION_SEND);
          i.setType("text/plain");
          i.putExtra(Intent.EXTRA_TEXT, "AI check (decision support only)\n\n" + CaseSheet.s(this.data, CaseSheet.AI_REVIEW));
          this.startActivity(Intent.createChooser(i, "Share AI check"));
        }
      }).show();
  }

  reviewByKey(engine) {
    const secs = this.reviewSecs();
    const pt = this.p;
    const wait = new AlertDialog.Builder(this).setTitle(engine + " is checking the case…")
      .setMessage("The name, IP number, phone, address and CMCHIS number are taken out first. This can take a minute; keep the app open.").setCancelable(false).show();
    new Thread({
      run: () => {
        let got = null, err = null;
        try {
          got = Ai.review(this, engine, secs, pt);
        } catch (e) {
          if (e instanceof Ai.Failure) err = e.getMessage();
          else err = "Could not check it: " + e.getMessage();
        }
        const res = got, error = err;
        this.runOnUiThread({
          run: () => {
            if (this.isFinishing()) return;
            try { wait.dismiss(); } catch (ignored) { }
            if (error != null) {
              new AlertDialog.Builder(this).setTitle("AI check not done").setMessage(error).setPositiveButton("OK", null).show();
              return;
            }
            this.saveReview(res, engine);
          }
        });
      }
    }).start();
  }

  /** True when field i begins a new pair (counting half fields since the last full-width one). */
  static rowStart(fs, i) {
    let run = 0;
    for (let j = i - 1; j >= 0 && CaseSheetActivity.half(fs[j]); j--) run++;
    return run % 2 === 0;
  }

  /** Half width side by side, except option lists too long to sit in half a row. */
  static half(fd) {
    if (!fd.isHalf) return false;
    if (fd.kind !== CaseSheet.CHOICE) return true;
    let n = 0, len = 0;
    for (const o of fd.options) if (!o.isEmpty()) {
      n++;
      len = Math.max(len, o.length);
    }
    return n <= 2 && len <= 11;
  }

  /** The reassuring answer to a question (shown green); others show red. */
  static normalOf(fd) {
    switch (fd.key) {
      case "ge_conscious": case "ge_oriented": return "Yes";
      case "rs_nvbs": return "Present";
      case "cvs_s1s2": return "Heard";
      case "pulse_rhythm": return "Regular";
      case "ecg_u": return "Absent";
      case "echo_rwma": return "No RWMA";
      case "ge_jvp": return "Not elevated";
      case "u_acetone": return "Negative";
      case "ob_events": return "Uneventful";
      case "cxr_result": return "No significant abnormality";
      case "cxr_trachea": return "No deviation";
      case "ecg_prwp": case "ecg_lvc": return "Absent";
      case "ecg_bbb": case "ecg_chamber": case "ecg_hb": return "None";
    }
    for (const o of fd.options) if (o === "Normal") return o;
    for (const o of fd.options) if (o === "No" || o === "Negative") return o;
    return null;
  }

  // ---------- complaints ----------

  complaintList(card) {
    const a = CaseSheet.complaints(this.data);
    if (a.length() > 0) {
      const h = Ui.muted(this, "Tap a complaint for its duration and details, long-press to remove it.");
      card.addView(h);
      Ui.margins(h, 0, 4, 0, 0);
    }
    for (let i = 0; i < a.length(); i++) {
      const idx = i;
      const c = a.optJSONObject(i);
      if (c == null) continue;
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      const line = CaseSheet.complaintLine(c);
      const dur = c.optString("dur").trim();
      const what = dur.isEmpty() ? line : line.substring(0, line.length - dur.length - 3);
      const name = Ui.tv(this, what, 15, Ui.TEXT, true);
      row.addView(name, Ui.weight(1));
      row.addView(dur.isEmpty() ? Ui.softPill(this, "Set duration", Ui.AMBER) : Ui.softPill(this, dur, Ui.PRIMARY));
      Ui.ripple(row, Ui.alpha(Ui.PRIMARY, 0x22));
      row.setOnClickListener({ onClick: (v) => { this.complaint(idx); } });
      row.setOnLongClickListener({
        onLongClick: (v) => {
          if (this.locked()) return true;
          Ui.confirm(this, "Remove complaint?", c.optString("name"), "Remove", {
            run: () => {
              const cur = CaseSheet.complaints(this.data);
              cur.remove(idx);
              this.putComplaints(cur);
              this.render();
            }
          });
          return true;
        }
      });
      card.addView(row);
      card.addView(Ui.divider(this));
    }
    if (!this.editable) return;
    const add = Ui.button(this, "+ Add complaints", Ui.PRIMARY, { onClick: (v) => { this.pickComplaints(); } });
    card.addView(add);
    Ui.margins(add, 0, 8, 0, 0);
  }

  /** Tick several complaints from the list (or type one that is not there); each is then given its duration. */
  pickComplaints() {
    if (this.locked()) return;
    const picked = new JSet();
    const cur = CaseSheet.complaints(this.data);
    const have = new JSet();
    for (let i = 0; i < cur.length(); i++) have.add(cur.optJSONObject(i) == null ? "" : cur.optJSONObject(i).optString("name").toLowerCase());
    const box = Ui.v(this);
    const pd = Ui.dp(this, 16);
    box.setPadding(pd, Ui.dp(this, 4), pd, 0);
    const search = new EditText(this);
    search.setHint("Search, or type a complaint not on the list");
    search.setSingleLine(true);
    search.setTextSize(15);
    box.addView(search);
    const sv = new ScrollView(this);
    const list = Ui.v(this);
    sv.addView(list);
    box.addView(sv, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 380)));
    this.fillComplaints(list, picked, have, "");
    search.addTextChangedListener({
      beforeTextChanged: (x, a, b, d) => {},
      onTextChanged: (x, a, b, d) => {},
      afterTextChanged: (e) => { this.fillComplaints(list, picked, have, e.toString()); }
    });
    new AlertDialog.Builder(this).setTitle("Complaints").setView(box)
      .setPositiveButton("Add", {
        onClick: (d, w) => {
          const typed = search.getText().toString().trim();
          if (picked.isEmpty() && !typed.isEmpty() && !have.contains(typed.toLowerCase())) picked.add(CaseSheet.cap(typed));
          const first = cur.length();
          for (const n of picked) {
            try {
              cur.put(new JSONObject().put("name", n));
            } catch (ignored) {
            }
          }
          this.putComplaints(cur);
          this.render();
          if (cur.length() > first) this.complaint(first);
        }
      })
      .setNegativeButton("Cancel", null).show();
  }

  fillComplaints(list, picked, have, q) {
    list.removeAllViews();
    const ql = q.trim().toLowerCase();
    let shown = 0, gi = 0;
    for (const g of CaseSheet.COMPLAINT_GROUPS) {
      const color = Bands.color(gi++);
      let head = false;
      let flow = null;
      for (let i = 1; i < g.length; i++) {
        const n = g[i][0];
        if (have.contains(n.toLowerCase())) continue;
        if (!ql.isEmpty() && !n.toLowerCase().contains(ql) && !g[0][0].toLowerCase().contains(ql)) continue;
        if (!head) {
          const h = Ui.tv(this, g[0][0], 14, Bands.ink(color), true);
          h.setPadding(0, Ui.dp(this, 14), 0, Ui.dp(this, 6));
          list.addView(h);
          flow = new Bands.Flow(this);
          list.addView(flow);
          head = true;
        }
        const cb = new Bands.Band(this, n + (g[i].length > 1 ? "  ›" : ""), color);
        cb.setChecked(picked.contains(n));
        cb.setOnCheckedChangeListener({
          onCheckedChanged: (b, on) => {
            if (on) picked.add(n);
            else picked.remove(n);
          }
        });
        flow.addView(cb);
        shown++;
      }
    }
    if (shown === 0) list.addView(Ui.muted(this, "Not on the list. Tap Add to add “" + q.trim() + "” as a complaint."));
  }

  /** Duration, the complaint's own questions (side, type, grade) and a free note. */
  complaint(idx) {
    if (this.locked()) return;
    const a = CaseSheet.complaints(this.data);
    const c = a.optJSONObject(idx);
    if (c == null) return;
    const f = new Form(this);
    const qs = CaseSheet.questionsFor(c.optString("name"));
    const opts = c.optJSONObject("opts");
    for (let i = 0; i < qs.length; i++) {
      const parts = qs[i].jsplit("\\|");
      const vals = new Array(parts.length).fill(null);
      vals[0] = "";
      System.arraycopy(parts, 1, vals, 1, parts.length - 1);
      const cur = opts == null ? "" : opts.optString(parts[0]);
      if (vals.length <= 4) f.segment("q" + i, parts[0], vals, cur);
      else {
        const labels = vals.slice();
        labels[0] = "–";
        f.choice("q" + i, parts[0], labels, vals, cur, null);
      }
    }
    const dur = c.optString("dur").trim();
    let num = "", unit = "days";
    const m = Pattern.compile("^(\\d+(?:\\.\\d+)?)\\s*(hours?|days?|weeks?|months?|years?)$").matcher(dur);
    if (m.find()) {
      num = m.group(1);
      unit = m.group(2).endsWith("s") ? m.group(2) : m.group(2) + "s";
    } else if (!dur.isEmpty()) num = dur;
    f.beginRow();
    f.text("dur_n", "Duration", num, Form.PLAIN);
    f.choice("dur_u", " ", CaseSheet.DURATION_UNITS, CaseSheet.DURATION_UNITS, unit, null);
    f.endRow();
    f.text("note", "Details (onset, character, severity…)", c.optString("note"), Form.PLAIN);
    Ui.formDialog(this, c.optString("name"), f, "Save", {
      run: () => {
        try {
          const o = new JSONObject();
          for (let i = 0; i < qs.length; i++) {
            const v = f.get("q" + i);
            if (!v.isEmpty()) o.put(qs[i].jsplit("\\|")[0], v);
          }
          if (o.length() > 0) c.put("opts", o);
          else c.remove("opts");
          const n = f.get("dur_n"), u = f.get("dur_u");
          if (n.isEmpty()) c.remove("dur");
          else if (n.matches("\\d+(\\.\\d+)?")) c.put("dur", n + " " + (n === "1" ? u.substring(0, u.length - 1) : u));
          else c.put("dur", n);
          if (f.get("note").isEmpty()) c.remove("note");
          else c.put("note", f.get("note"));
          const cur = CaseSheet.complaints(this.data);
          cur.put(idx, c);
          this.putComplaints(cur);
        } catch (e) {
          if (!(e instanceof JSONException)) throw e;
        }
        this.render();
        return true;
      }
    });
  }

  putComplaints(a) {
    if (this.locked()) return;
    CaseSheet.putComplaints(this.data, a);
    CaseSheet.save(this.db, this.id, this.data);
  }

  // ---------- treatment ----------

  drugList(card, key) {
    const dis = key === CaseSheet.DIS_MEDS;
    const a = CaseSheet.drugs(this.data, key);
    if (dis) {
      const h = Ui.muted(this, "Medicines to take at home: drug, dose, frequency and days. Treatment-chart drugs marked \"continue on discharge\" are added after these.");
      card.addView(h);
      Ui.margins(h, 0, 4, 0, 0);
    }
    if (a.length() > 0) {
      const h = Ui.muted(this, "Tap a drug to edit it, long-press to remove it.");
      card.addView(h);
      Ui.margins(h, 0, 4, 0, 0);
    }
    for (let i = 0; i < a.length(); i++) {
      const idx = i;
      const d = a.optJSONObject(i);
      if (d == null) continue;
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      const txt = Ui.v(this);
      txt.addView(Ui.tv(this, CaseSheet.drugLine(d, false), 15, Ui.TEXT, true));
      const sub = d.optString("type") + (d.optString("freq").isEmpty() ? "" : "  ·  " + d.optString("freq"))
        + (d.optString("days").isEmpty() ? "" : "  ·  " + d.optString("days") + (d.optString("days").matches("\\d+") ? " days" : ""))
        + (d.optString("food").isEmpty() ? "" : "  ·  " + d.optString("food"));
      txt.addView(Ui.muted(this, sub));
      row.addView(txt, Ui.weight(1));
      if ("1" === d.optString("continue")) row.addView(Ui.softPill(this, "On discharge", Ui.TEAL));
      Ui.ripple(row, Ui.alpha(Ui.ORANGE, 0x22));
      row.setOnClickListener({ onClick: (v) => { this.drug(idx, key); } });
      const label = CaseSheet.drugLine(d, true);
      row.setOnLongClickListener({
        onLongClick: (v) => {
          if (this.locked()) return true;
          Ui.confirm(this, "Remove drug?", label, "Remove", {
            run: () => {
              const cur = CaseSheet.drugs(this.data, key);
              cur.remove(idx);
              this.put(cur, key);
              this.render();
            }
          });
          return true;
        }
      });
      card.addView(row);
      card.addView(Ui.divider(this));
    }
    if (a.length() > 0) {
      const chk = Ui.outlineButton(this, "Check all drugs", Ui.ORANGE, {
        onClick: (v) => { DrugCheckUi.show(this, "Drug check", DrugCheckUi.run(this.db, this.p, this.data, CaseSheet.drugs(this.data, key)), true); }
      });
      card.addView(chk);
      Ui.margins(chk, 0, 8, 0, 0);
      if (CaseSheet.TREATMENT === key) {
        const kd = Ui.outlineButton(this, "💧 Kidney doses", KidneyDose.COLOR, this.opener(KidneyDoseActivity, "id", String(this.id)));
        card.addView(kd);
        Ui.margins(kd, 0, 6, 0, 0);
      }
      const dn = Ui.muted(this, "Decision support, check a drug reference. Offline list, not complete.");
      dn.setTextSize(11);
      card.addView(dn);
    }
    if (!this.editable) return;
    if (dis && CaseSheet.drugs(this.data).length() > 0) {
      const pick = Ui.button(this, "Choose from treatment given", Ui.PRIMARY, { onClick: (v) => { this.pickFromTreatment(); } });
      card.addView(pick);
      Ui.margins(pick, 0, 8, 0, 0);
    }
    const add = Ui.button(this, dis ? "+ Add discharge medicine" : "+ Add drug or fluid", dis ? Ui.TEAL : Ui.ORANGE, { onClick: (v) => { this.drug(-1, key); } });
    card.addView(add);
    Ui.margins(add, 0, 8, 0, 0);
  }

  /** The treatment chart's drugs to tick; ticked ones are copied into the discharge medicines to set days and food. */
  pickFromTreatment() {
    if (this.locked()) return;
    const tr = CaseSheet.drugs(this.data);
    const dm = CaseSheet.drugs(this.data, CaseSheet.DIS_MEDS);
    const have = new JSet();
    for (let i = 0; i < dm.length(); i++) if (dm.optJSONObject(i) != null) have.add(dm.optJSONObject(i).optString("name").trim().toLowerCase());
    const offer = [];
    for (let i = 0; i < tr.length(); i++) {
      const d = tr.optJSONObject(i);
      if (d == null || d.optString("name").trim().isEmpty() || have.contains(d.optString("name").trim().toLowerCase())) continue;
      offer.add(d);
    }
    if (offer.isEmpty()) {
      Ui.toast(this, "All treatment drugs are already in the discharge medicines");
      return;
    }
    const labels = new Array(offer.size()).fill(null);
    const on = new Array(offer.size()).fill(false);
    for (let i = 0; i < labels.length; i++) {
      const d = offer.get(i);
      labels[i] = CaseSheet.drugLine(d, true);
      const type = d.optString("type");
      on[i] = "1" === d.optString("continue") || type === "Tablet" || type === "Capsule" || type === "Syrup";
    }
    new AlertDialog.Builder(this).setTitle("Choose from treatment given")
      .setMultiChoiceItems(labels, on, { onClick: (d, w, c) => { on[w] = c; } })
      .setPositiveButton("Add", {
        onClick: (d, w) => {
          const cur = CaseSheet.drugs(this.data, CaseSheet.DIS_MEDS);
          let n = 0;
          for (let i = 0; i < on.length; i++) {
            if (!on[i]) continue;
            const src = offer.get(i), x = new JSONObject();
            try {
              for (const k of ["type", "name", "dose", "route", "freq"]) if (!src.optString(k).isEmpty()) x.put(k, src.optString(k));
              x.put("days", "");
              cur.put(x);
              n++;
            } catch (ignored) {
            }
          }
          this.put(cur, CaseSheet.DIS_MEDS);
          this.render();
          if (n > 0) Ui.toast(this, n + " added. Tap each to set the days and food timing");
        }
      }).setNegativeButton("Cancel", null).show();
  }

  /** Add (idx = -1) or edit one drug: type, name, dose, frequency, days, continue on discharge. */
  drug(idx, key) {
    if (this.locked()) return;
    const dis = key === CaseSheet.DIS_MEDS;
    const a = CaseSheet.drugs(this.data, key);
    const d = idx >= 0 ? a.optJSONObject(idx) : new JSONObject();
    const f = new Form(this);
    const type = d.optString("type", "Tablet");
    const typeChanged = [null];
    f.choice("type", "Type", CaseSheet.DRUG_TYPES, CaseSheet.DRUG_TYPES, type.isEmpty() ? "Tablet" : type, {
      changed: (v) => { if (typeChanged[0] != null) typeChanged[0].changed(v); }
    });
    const nameField = f.suggest("name", "Drug or fluid name", d.optString("name"), CaseSheetActivity.COMMON_DRUGS);
    const usual = Ui.muted(this, "Typing a drug or IV fluid fills in its usual adult dose and frequency or rate. Check them for this patient.");
    usual.setTextSize(12);
    f.view.addView(usual);
    f.text("dose", "Dose (e.g. 500 mg, 1 g, 500 ml, 8 units)", d.optString("dose"), Form.PLAIN);
    f.segment("route", "Route", CaseSheet.ROUTES, idx >= 0 ? d.optString("route") : CaseSheetActivity.defaultRoute(type.isEmpty() ? "Tablet" : type));
    f.suggest("freq", "Frequency or rate (OD, BD, TDS, 75 ml/hr…)", d.optString("freq"), CaseSheet.FREQUENCIES);
    // usual dose and frequency for the drug typed; a value the doctor typed is never overwritten
    const filled = [d.optString("dose"), d.optString("freq")];
    const fillUsual = {
      run: () => {
        const u = Drugs.find(f.get("name"), f.get("type"));
        if (u == null) return;
        if (u[1] !== f.get("type") && (f.get("dose").trim().isEmpty() || f.get("dose") === filled[0])) {
          f.set("type", u[1]);
          f.set("route", CaseSheetActivity.defaultRoute(u[1]));
        }
        if (f.get("dose").trim().isEmpty() || f.get("dose") === filled[0]) { f.set("dose", u[2]); filled[0] = u[2]; }
        if (f.get("freq").trim().isEmpty() || f.get("freq") === filled[1]) { f.set("freq", u[4]); filled[1] = u[4]; }
        if (!u[3].isEmpty()) f.set("route", u[3]);
      }
    };
    if (idx >= 0) { filled[0] = "\u0000"; filled[1] = "\u0000"; }   // editing: keep what was written
    nameField.addTextChangedListener({
      beforeTextChanged: (s, a, b, c) => {},
      onTextChanged: (s, a, b, c) => {},
      afterTextChanged: (s) => { fillUsual.run(); }
    });
    f.text("days", "Days", d.optString("days"), Form.PLAIN);
    if (dis) f.segment("food", "Food", CaseSheetActivity.FOOD, d.optString("food"), "");
    else f.check("continue", "Continue on discharge (goes into the discharge advice)", "1" === d.optString("continue"));
    const startType = type.isEmpty() ? "Tablet" : type;
    typeChanged[0] = {
      changed: (v) => {
        if (v !== startType || idx < 0) f.set("route", CaseSheetActivity.defaultRoute(v));
        fillUsual.run();   // e.g. Paracetamol tablet -> injection
      }
    };
    Ui.formDialog(this, dis ? (idx >= 0 ? "Edit discharge medicine" : "Add discharge medicine") : idx >= 0 ? "Edit treatment" : "Add treatment", f, "Save", {
      run: () => {
        if (!f.require("name", "Enter the drug or fluid")) return false;
        const n = new JSONObject();
        try {
          n.put("type", f.get("type"));
          n.put("name", f.get("name"));
          n.put("dose", f.get("dose"));
          if (!f.get("route").isEmpty()) n.put("route", f.get("route"));
          n.put("freq", f.get("freq"));
          n.put("days", f.get("days"));
          if (!dis && "1" === f.get("continue")) n.put("continue", "1");
          if (dis && !f.get("food").isEmpty()) n.put("food", f.get("food"));
          const cur = CaseSheet.drugs(this.data, key);
          if (idx >= 0 && idx < cur.length()) cur.put(idx, n);
          else cur.put(n);
          this.put(cur, key);
        } catch (e) {
          if (!(e instanceof JSONException)) throw e;
        }
        this.render();
        // offline drug check on the patient's whole list; a warning only, the drug is already saved
        DrugCheckUi.show(this, "Drug check: please review", DrugCheckUi.run(this.db, this.p, this.data, CaseSheet.drugs(this.data, key)), false);
        return true;
      }
    });
  }

  /** The usual route for a type of drug; blank for injections, which may be IV, IM or SC. */
  static defaultRoute(type) {
    switch (type) {
      case "Tablet": case "Capsule": case "Syrup": case "ORS": return "PO";
      case "IV fluid": return "IV";
      default: return "";
    }
  }

  put(a, key) {
    if (this.locked()) return;
    try {
      this.data.put(key, a);
    } catch (ignored) {
    }
    CaseSheet.save(this.db, this.id, this.data);
  }

  /** PG name with the department's PGs to pick from; picking one fills the year from their batch. A PG's own phone fills itself in. */
  pgPicker(f, v) {
    const pgs = this.db.rows("SELECT name, batch FROM staff WHERE role='Postgraduate' AND " + Approvals.APPROVED_SQL + " ORDER BY name");
    const names = new Array(pgs.size()).fill(null);
    for (let i = 0; i < names.length; i++) names[i] = pgs.get(i).get("name");
    if (v.isEmpty() && "PG" === CalendarActivity.audienceOf(this, this.db, Reminders.myName(this, this.db))) v = Reminders.myName(this, this.db);
    const a = f.suggest("wb_name", "Name of the PG", v, names);
    a.setOnItemClickListener({
      onItemClick: (parent, view, pos, rowId) => {
        // the browser's suggestion list reports no adapter position: the picked name is the box's text
        const picked = parent != null && parent.getItemAtPosition ? parent.getItemAtPosition(pos) : view.getText().toString();
        CaseSheetActivity.fillYear(f, String(picked), pgs);
      }
    });
    if (!v.isEmpty() && CaseSheet.s(this.data, "wb_year").isEmpty()) {
      const name = v;
      f.view.post({ run: () => { CaseSheetActivity.fillYear(f, name, pgs); } });
    }
  }

  static fillYear(f, name, pgs) {
    for (const pg of pgs) {
      if (pg.get("name") !== name) continue;
      const y = CaseSheet.pgYear(pg.get("batch"), Dates.today());
      if (y > 0) f.set("wb_year", CaseSheet.PG_YEARS[y - 1]);
    }
  }
}
;
