/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One patient's bedside chart (BP, diabetic, I/O, OPC or ventilator): trend, entries by day, add / edit, Word and PDF. */
class ChartActivity extends Base {
  constructor() { super(); this.pid = 0; this.code = null; }

  onCreate(b) {
    super.onCreate(b);
    this.pid = Long.parseLong(this.getIntent().getStringExtra("id"));
    this.code = this.getIntent().getStringExtra("kind");
    if (this.code == null) this.code = Charts.BP;
  }

  render() {
    const db = this.db;
    const p = db.row("SELECT * FROM patients WHERE id=?", String(this.pid));
    if (p == null) { this.finish(); return; }
    const k = Charts.kind(this.code);
    this.setTitle(k.name);
    this.subtitle = p.get("name") + (Ui.nz(p.get("bed")).isEmpty() ? "" : "  ·  bed " + p.get("bed")) + "  ·  " + Db.shortName(p.get("location"));
    this.headerColor(k.color);
    this.headerAction("+ Entry", { onClick: (v) => { this.entry(null); } });
    const page = Ui.v(this);

    // the five charts for this patient; suggested ones marked
    const chips = Ui.h(this);
    for (const x of Charts.KINDS) {
      const n = Charts.count(db, this.pid, x.code);
      const label = x.name.split(" chart").join("") + (n > 0 ? " · " + n : Charts.suggested(p, x.code) ? " •" : "");
      const c = Ui.chip(this, label, x.code === this.code, x.color);
      c.setOnClickListener({ onClick: (v) => { this.code = x.code; this.render(); } });
      chips.addView(c);
    }
    chips.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 4));
    page.addView(Ui.hscroll(this, chips));

    const all = Charts.entries(db, this.pid, this.code);
    const last = all.isEmpty() ? null : all.get(all.size() - 1);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(k.color), 20));
    hero.addView(Ui.tv(this, k.about, 13, 0xE6FFFFFF, false));
    if (last == null) {
      hero.addView(Ui.tv(this, "No entries yet", 20, Color.WHITE, true));
      hero.addView(Ui.tv(this, Charts.suggested(p, this.code) ? "Suggested for " + Ui.nz(p.get("diagnosis")) + ". Tap + Entry to start." : "Tap + Entry to start the chart.", 13, 0xE6FFFFFF, false));
    } else {
      const o = Charts.data(last);
      hero.addView(Ui.tv(this, Charts.line(k, o).isEmpty() ? "Entry" : Charts.line(k, o), 19, Color.WHITE, true));
      const when = Dates.nice(last.get("date")) + " " + last.get("time") + (Ui.nz(last.get("by_name")).isEmpty() ? "" : "  ·  " + last.get("by_name"));
      hero.addView(Ui.tv(this, "Last entry " + when + "  ·  " + all.size() + (all.size() === 1 ? " entry" : " entries"), 13, 0xE6FFFFFF, false));
      if (this.code === Charts.OPC && !Charts.opcStatus(o).isEmpty()) {
        const st = Ui.tv(this, Charts.opcStatus(o), 14, Color.WHITE, true);
        st.setBackground(Glass.frost(this, 12));
        st.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 6));
        hero.addView(st);
        Ui.margins(st, 0, 10, 0, 0);
      }
    }
    const acts = Ui.buttonRow(this,
      this.frost(Ui.button(this, "+ Add entry", k.color, { onClick: (v) => { this.entry(null); } })),
      this.frost(Ui.button(this, "Word", k.color, { onClick: (v) => { this.export(p, "docx"); } })),
      this.frost(Ui.button(this, "PDF", k.color, { onClick: (v) => { this.export(p, "pdf"); } })));
    hero.addView(acts);
    Ui.margins(acts, 0, 12, 0, 0);
    page.addView(hero);

    const days = Charts.byDay(all);
    // trend
    const t = this.trend(k, all, days);
    if (t != null) {
      const tc = Ui.card(this);
      tc.addView(Ui.title(this, "Trend"));
      tc.addView(t, Ui.lp(MATCH_PARENT, Ui.dp(this, 190)));
      page.addView(tc);
    }

    // entries, newest day first
    const order = ArrayList(days.keySet());
    order.reverse();
    const weight = Charts.weight(all);
    for (const d of order) {
      const es = days.get(d);
      page.addView(Ui.heading(this, Dates.nice(d) + "  ·  " + es.size() + (es.size() === 1 ? " entry" : " entries"), k.color));
      if (this.code === Charts.IO) page.addView(this.ioCard(es, weight));
      if (this.code === Charts.DM) page.addView(this.dmCard(k, all, d, es));
      for (let i = es.size() - 1; i >= 0; i--) {
        const e = es.get(i);
        const o = Charts.data(e);
        const w = Charts.worst(k, o);
        const sub = (o.optString("note").isEmpty() ? "" : o.optString("note"))
          + (Ui.nz(e.get("by_name")).isEmpty() ? "" : (o.optString("note").isEmpty() ? "" : "\n") + "By " + e.get("by_name"));
        page.addView(this.entryCard(e.get("time"), w === 0 ? k.color : w, Charts.line(k, o).isEmpty() ? "Entry" : Charts.line(k, o), sub, null,
          { onClick: (v) => { this.entry(e); } }));
      }
    }
    if (all.isEmpty()) page.addView(this.emptyNote("Entries appear here by day (7:30 AM to 7:30 AM), coloured red, amber or green by the readings."));
    this.setPage(page);
  }

  frost(t) {
    t.setBackground(Glass.frost(this, 14));
    return t;
  }

  ioCard(es, weight) {
    const t = Charts.ioTotals(es, weight);
    const c = Ui.card(this);
    const r = Ui.h(this);
    r.addView(this.stat(ChartActivity.fmt(t[0]) + " ml", "Intake", 0xFF2563EB), Ui.weight(1));
    r.addView(this.stat(ChartActivity.fmt(t[1]) + " ml", "Output", Charts.AMBER), Ui.weight(1));
    r.addView(this.stat((t[3] > 0 ? "+" : "") + ChartActivity.fmt(t[3]), "Balance", t[3] >= 0 ? 0xFF2563EB : Charts.AMBER), Ui.weight(1));
    c.addView(r);
    const uo = "Urine " + ChartActivity.fmt(t[2]) + " ml" + (Number.isNaN(t[4]) ? "  (add body weight for ml/kg/hr)" : "  ·  " + jfmt("%.2f", t[4]) + " ml/kg/hr");
    const u = Ui.tv(this, uo, 14, t[2] < 400 || (!Number.isNaN(t[4]) && t[4] < 0.5) ? Charts.RED : Ui.TEXT, true);
    c.addView(u);
    Ui.margins(u, 0, 8, 0, 0);
    return c;
  }

  dmCard(k, all, d, es) {
    const c = Ui.card(this);
    const row = Ui.h(this);
    for (let i = 0; i < Charts.DM_SLOTS.length; i++) {
      let v = "";
      let fl = 0;
      for (const e of es) {
        const o = Charts.data(e);
        if (Charts.DM_SLOTS[i] === o.optString("slot") && !o.optString("grbs").isEmpty()) {
          v = o.optString("grbs");
          fl = Charts.flag(k, o, "grbs");
        }
      }
      const cell = Ui.v(this);
      cell.setGravity(Gravity.CENTER);
      const val = Ui.tv(this, v.isEmpty() ? "–" : v, 14, fl === 0 ? Ui.MUTED : fl, true);
      val.setGravity(Gravity.CENTER);
      cell.addView(val);
      const lab = Ui.tv(this, Charts.DM_SHORT[i], 10, Ui.MUTED, false);
      lab.setGravity(Gravity.CENTER);
      cell.addView(lab);
      row.addView(cell, Ui.weight(1));
    }
    c.addView(row);
    const reg = Charts.regimenUpTo(all, d);
    if (!reg.isEmpty()) {
      const r = Ui.tv(this, "Regimen: " + reg, 13, k.color, true);
      c.addView(r);
      Ui.margins(r, 0, 8, 0, 0);
    }
    return c;
  }

  stat(v, l, color) {
    const s = Ui.v(this);
    s.setGravity(Gravity.CENTER);
    const a = Ui.tv(this, v, 17, color, true);
    a.setGravity(Gravity.CENTER);
    s.addView(a);
    const b = Ui.muted(this, l);
    b.setGravity(Gravity.CENTER);
    s.addView(b);
    return s;
  }

  static fmt(v) {
    if (Number.isNaN(v)) return "-";
    return v === Math.rint(v) ? String(Math.trunc(v)) : jfmt("%.1f", v);
  }

  // ---------- add / edit ----------

  entry(e) {
    const db = this.db;
    const k = Charts.kind(this.code);
    const o = e == null ? new JSONObject() : Charts.data(e);
    const f = new Form(this);
    const time = e != null ? e.get("time") : this.code === Charts.BP ? jfmt("%02d:00", Dates.time().getHour()) : Dates.time().format(DateTimeFormatter.ofPattern("HH:mm"));
    const date = e != null ? e.get("date") : Dates.today().toString();
    f.beginRow();
    f.date("date", "Date", date);
    f.time("time", "Time", time);
    f.endRow();
    let carry = null;
    if (e == null && this.code === Charts.VENT) {
      const last = Charts.last(db, this.pid, this.code);
      if (last != null) {
        carry = Charts.data(last);
        const n = Ui.muted(this, "Settings are carried over from the last entry. Change only what was changed.");
        n.setTextSize(12);
        f.view.addView(n);
      }
    }
    if (e == null && this.code === Charts.DM) {
      const reg = Charts.regimenUpTo(Charts.entries(db, this.pid, this.code), Dates.admitDay());
      if (!reg.isEmpty()) {
        const n = Ui.muted(this, "Current regimen: " + reg + ". Write a new regimen only when it changes.");
        n.setTextSize(12);
        f.view.addView(n);
      }
    }
    let open = false;
    for (const fd of k.fields) {
      let v = o.optString(fd.key);
      if (e == null && carry != null && fd._setting) v = carry.optString(fd.key);
      const label = fd.label + (fd.unit.isEmpty() ? "" : " (" + fd.unit + ")");
      if (fd.type === Charts.NUM || fd.type === Charts.DEC) {
        if (!open) { f.beginRow(); open = true; }
        f.text(fd.key, label, v, fd.type === Charts.NUM ? Form.NUMBER : Form.DECIMAL);
        if (ChartActivity.rowFull(f)) { f.endRow(); open = false; }
      } else {
        if (open) { f.endRow(); open = false; }
        if (fd.type === Charts.SEG) f.segment(fd.key, label, fd.opts, v);
        else f.text(fd.key, label, v, Form.PLAIN);
      }
    }
    if (open) f.endRow();
    f.text("by", "Recorded by", e != null ? e.get("by_name") : CallDutyActivity.myName(this), Form.TEXT);
    if (e != null) {
      const del = Ui.outlineButton(this, "Delete entry", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete this entry?", Dates.nice(e.get("date")) + " " + e.get("time"), "Delete", {
            run: () => { db.delete("charts", Long.parseLong(e.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, (e == null ? "New " : "Edit ") + k.name.toLowerCase() + " entry", f, "Save", {
      run: () => {
        const n = new JSONObject();
        let any = false;
        try {
          for (const fd of k.fields) {
            const v = f.get(fd.key).trim();
            if (!v.isEmpty()) { n.put(fd.key, v); any = true; }
          }
        } catch (ignored) {
        }
        if (!any) { Ui.toast(this, "Enter at least one reading"); return false; }
        if (this.code === Charts.BP && (n.optString("sbp").isEmpty() !== n.optString("dbp").isEmpty())) {
          Ui.toast(this, "Enter both systolic and diastolic BP");
          return false;
        }
        const t = f.get("time").isEmpty() ? Dates.now() : f.get("time");
        const cid = Charts.save(db, e == null ? 0 : Long.parseLong(e.get("id")), this.pid, this.code, f.get("date"), t, n, f.get("by").trim());
        if (this.code === Charts.VITALS) DapDuty.raiseNews(this, db, this.pid, cid, n);
        CallDutyActivity.rememberName(this, f.get("by"));
        this.render();
        return true;
      }
    });
  }

  /** Numbers sit two to a row. (Java reads Form's private field "row" by reflection.) */
  static rowFull(f) {
    try {
      const row = f._row !== undefined ? f._row : f.row;
      if (row != null && typeof row.getChildCount !== 'function') return true;
      return row != null && row.getChildCount() >= 2;
    } catch (ex) {
      return true;
    }
  }

  // ---------- Word / PDF ----------

  export(p, kind) {
    const labels = ["Today (from 7:30 AM)", "Last 3 days", "Whole stay"];
    new AlertDialog.Builder(this).setTitle((kind === "pdf" ? "PDF" : "Word") + ": which days?")
      .setItems(labels, {
        onClick: (d, w) => {
          const to = Dates.admitDay();
          const from = w === 0 ? to : w === 1 ? to.minusDays(2) : null;
          this.file(p, kind, from, w === 2 ? null : to);
        }
      }).setNegativeButton("Cancel", null).show();
  }

  file(p, kind, from, to) {
    let rel;
    try {
      const f = Charts.doc(this.db, p, this.code, from, to);
      rel = kind === "pdf" ? f.pdf(this) : f.docx(this);
    } catch (ex) {
      Ui.toast(this, "Could not make the file: " + ex.getMessage());
      return;
    }
    const subject = Charts.kind(this.code).name + " " + p.get("name");
    new AlertDialog.Builder(this).setTitle((kind === "pdf" ? "PDF" : "Word") + " file ready")
      .setItems(["Send on WhatsApp", "Share (email, Drive…)", "Open"], {
        onClick: (d, w) => {
          if (w === 0) this.whatsapp(rel, subject);
          else if (w === 1) Store.share(this, rel, subject);
          else Store.openWith(this, rel);
        }
      }).setNegativeButton("Close", null).show();
  }

  whatsapp(rel, subject) {
    const u = Uri.ofRel(rel);
    const i = new Intent(Intent.ACTION_SEND);
    i.setType(mimeOf(rel));
    i.putExtra(Intent.EXTRA_STREAM, u);
    i.setClipData(ClipData.newRawUri(subject, u));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    Store.share(this, rel, subject);
  }

  // ---------- trend ----------

  trend(k, all, days) {
    const t = new ChartActivity.Trend(this);
    const tail = ChartActivity.tail;
    if (this.code === Charts.IO) {
      const xs = [];
      const inn = [], out = [], urine = [];
      const w = Charts.weight(all);
      for (const d of days.entrySet()) {
        const tt = Charts.ioTotals(d.getValue(), w);
        xs.add(d.getKey().format(DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH)));
        inn.add(tt[0]); out.add(tt[1]); urine.add(tt[2]);
      }
      if (xs.size() < 2) return null;
      t.x = tail(xs);
      t.add("Intake", 0xFF2563EB, tail(inn));
      t.add("Output", Charts.AMBER, tail(out));
      t.add("Urine", 0xFF0891B2, tail(urine));
      t.ref(400, Charts.RED, "400 ml");
      return t;
    }
    const xs = [];
    for (const e of all) xs.add(e.get("time"));
    let series;
    switch (this.code) {
      case Charts.BP: series = [["sbp", "SBP", "" + 0xFFDC2626], ["dbp", "DBP", "" + 0xFF2563EB], ["map", "MAP", "" + 0xFF7C3AED]];
        t.ref(140, Charts.AMBER, "140"); t.ref(90, Charts.RED, "90"); break;
      case Charts.DM: series = [["grbs", "GRBS", "" + 0xFF7C3AED]];
        t.ref(180, Charts.AMBER, "180"); t.ref(70, Charts.RED, "70"); break;
      case Charts.OPC: series = [["hr", "Pulse", "" + 0xFFDC2626], ["sbp", "SBP", "" + 0xFF2563EB]];
        t.ref(80, Charts.GREEN, "80"); break;
      case Charts.VITALS: series = [["news", "NEWS2", "" + Ews.COLOR]];
        t.ref(5, Charts.AMBER, "5"); t.ref(7, Charts.RED, "7"); break;
      default: series = [["fio2", "FiO2 %", "" + 0xFF0F766E], ["spo2", "SpO2 %", "" + 0xFF2563EB]];
        t.ref(90, Charts.RED, "90"); break;
    }
    let points = 0;
    for (const s of series) {
      const v = [];
      let n = 0;
      for (const e of all) {
        const o = Charts.data(e);
        const d = s[0] === "map" ? Charts.map(o) : s[0] === "news" ? (Ews.score(o).count === 0 ? NaN : Ews.score(o).total) : Charts.num(o, s[0]);
        v.add(d);
        if (!Number.isNaN(d)) n++;
      }
      points = Math.max(points, n);
      t.add(s[1], Integer.parseInt(s[2]), tail(v));
    }
    if (points < 2) return null;
    t.x = tail(xs);
    return t;
  }

  static tail(l) {
    return l.size() <= 24 ? l : ArrayList(l.subList(l.size() - 24, l.size()));
  }
}

/** A small line chart: several series over the entries, with reference lines. */
ChartActivity.Trend = class extends View {
  constructor(c) {
    super(c);
    this.x = [];
    this.names = [];
    this.colors = [];
    this.values = [];
    this.refs = [];
    this.refLabels = [];
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.d = c.getResources().getDisplayMetrics().density;
  }

  add(name, color, v) { this.names.add(name); this.colors.add(color); this.values.add(v); }

  ref(v, color, label) { this.refs.add([v, color]); this.refLabels.add(label); }

  onDraw(cv) {
    const p = this.p, d = this.d, x = this.x, names = this.names, colors = this.colors, values = this.values, refs = this.refs;
    const w = this.getWidth(), h = this.getHeight();
    const left = 30 * d, right = w - 8 * d, top = 22 * d, bottom = h - 18 * d;
    let lo = Number.MAX_VALUE, hi = -Number.MAX_VALUE;
    for (const s of values) for (const v of s) if (!Number.isNaN(v)) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
    for (const r of refs) { lo = Math.min(lo, r[0]); hi = Math.max(hi, r[0]); }
    if (lo === Number.MAX_VALUE) return;
    const pad = Math.max(5, (hi - lo) * 0.1);
    lo = Math.max(0, lo - pad);
    hi += pad;
    const n = Math.max(2, x.size());
    // legend
    p.setTextSize(11 * d);
    p.setStyle(Paint.Style.FILL);
    let lx = left;
    for (let i = 0; i < names.size(); i++) {
      p.setColor(colors.get(i));
      cv.drawCircle(lx + 4 * d, 10 * d, 4 * d, p);
      p.setColor(0xFF334155);
      cv.drawText(names.get(i), lx + 11 * d, 14 * d, p);
      lx += p.measureText(names.get(i)) + 26 * d;
    }
    // reference lines
    p.setStrokeWidth(1.2 * d);
    for (let i = 0; i < refs.size(); i++) {
      const y = bottom - (refs.get(i)[0] - lo) / (hi - lo) * (bottom - top);
      p.setStyle(Paint.Style.STROKE);
      p.setColor(Ui.alpha(refs.get(i)[1], 0x99));
      p.setPathEffect(new DashPathEffect([6 * d, 5 * d], 0));
      cv.drawLine(left, y, right, y, p);
      p.setPathEffect(null);
      p.setStyle(Paint.Style.FILL);
      p.setTextSize(10 * d);
      cv.drawText(this.refLabels.get(i), 2 * d, y + 4 * d, p);
    }
    // axis
    p.setColor(0xFFCBD5E1);
    p.setStrokeWidth(1 * d);
    cv.drawLine(left, bottom, right, bottom, p);
    p.setColor(0xFF64748B);
    p.setTextSize(10 * d);
    if (!x.isEmpty()) {
      cv.drawText(x.get(0), left, h - 4 * d, p);
      const lastX = x.get(x.size() - 1);
      cv.drawText(lastX, right - p.measureText(lastX), h - 4 * d, p);
    }
    // series
    for (let s = 0; s < values.size(); s++) {
      const v = values.get(s);
      const path = new Path();
      let started = false;
      p.setColor(colors.get(s));
      for (let i = 0; i < v.size(); i++) {
        if (Number.isNaN(v.get(i))) continue;
        const px = left + (right - left) * i / (n - 1);
        const py = bottom - (v.get(i) - lo) / (hi - lo) * (bottom - top);
        if (!started) { path.moveTo(px, py); started = true; } else path.lineTo(px, py);
        p.setStyle(Paint.Style.FILL);
        cv.drawCircle(px, py, 3.2 * d, p);
      }
      p.setStyle(Paint.Style.STROKE);
      p.setStrokeWidth(2.2 * d);
      cv.drawPath(path, p);
    }
    p.setStyle(Paint.Style.FILL);
  }
};
;
/* ---- app/Charts.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Bedside monitoring charts for one patient: hourly BP, diabetic (sugar and insulin), intake / output,
 * organophosphorus poisoning and ventilator settings. Entries live in the charts table (one row each);
 * a chart's day runs 7:30 AM to 7:30 AM like the admission day.
 */
class Charts {
  constructor() {}

  static BP = "BP";
  static DM = "DM";
  static IO = "IO";
  static OPC = "OPC";
  static VENT = "VENT";
  static VITALS = "VITALS";
  static NUM = 0;
  static DEC = 1;
  static TEXT = 2;
  static SEG = 3;

  static DM_SLOTS = ["Fasting", "Post-breakfast", "Pre-lunch", "Post-lunch", "Pre-dinner", "Post-dinner", "Bedtime", "3 AM", "Random"];
  static DM_SHORT = ["FBS", "Post-BF", "Pre-L", "Post-L", "Pre-D", "Post-D", "HS", "3 AM", "RBS"];
  static VENT_MODES = ["VC-AC", "PC-AC", "PRVC", "SIMV", "PSV", "CPAP", "NIV (BiPAP)", "T-piece"];

  static RED = 0xFFDC2626;
  static AMBER = 0xFFD97706;
  static GREEN = 0xFF16A34A;

  static $clinit() {
    const F = Charts.F, Kind = Charts.Kind;
    const BP = Charts.BP, DM = Charts.DM, IO = Charts.IO, OPC = Charts.OPC, VENT = Charts.VENT;
    const NUM = Charts.NUM, DEC = Charts.DEC, TEXT = Charts.TEXT, SEG = Charts.SEG;
    Charts.KINDS = [
      new Kind(BP, "BP chart", "HOURLY BP CHART", "Hourly BP for hypertensive and shock patients", 0xFFDC2626, R.drawable.ic_heart,
        [new F("sbp", "Systolic", NUM, "mmHg"), new F("dbp", "Diastolic", NUM, "mmHg"), new F("hr", "Pulse", NUM, "/min"),
          new F("spo2", "SpO2", NUM, "%"), new F("pressor", "Vasopressor and dose (e.g. NA 0.1 mcg/kg/min)", TEXT, ""),
          new F("drug", "Antihypertensive given", TEXT, ""), new F("note", "Remarks", TEXT, "")],
        ["sbp", "dbp", "map", "hr", "spo2", "pressor", "drug", "note"],
        ["SBP", "DBP", "MAP", "Pulse", "SpO2", "Vasopressor", "Antihypertensive", "Remarks"]),
      new Kind(DM, "Diabetic chart", "DIABETIC CHART", "Blood sugar and the day's insulin regimen", 0xFF7C3AED, R.drawable.ic_drop,
        [new F("slot", "When", SEG, "", Charts.DM_SLOTS), new F("grbs", "GRBS", NUM, "mg/dl"),
          new F("ketone", "Urine ketones", SEG, "", "Nil", "Trace", "+", "++", "+++"),
          new F("given", "Insulin given now (type and units)", TEXT, ""),
          new F("regimen", "Insulin regimen from now (e.g. HAI 8-8-8, Glargine 12 units HS)", TEXT, ""),
          new F("oha", "Oral drugs", TEXT, ""), new F("note", "Remarks", TEXT, "")],
        ["slot", "grbs", "ketone", "given", "regimen", "note"],
        ["When", "GRBS", "Ketones", "Insulin given", "Regimen", "Remarks"]),
      new Kind(IO, "I/O chart", "INTAKE / OUTPUT CHART", "Intake and urine output for heart, kidney and liver patients", 0xFF0284C7, R.drawable.ic_drop,
        [new F("oral", "Oral intake", NUM, "ml"), new F("iv", "IV fluids", NUM, "ml"), new F("rt", "Ryle's tube feed", NUM, "ml"),
          new F("urine", "Urine", NUM, "ml"), new F("drain", "Drain / RT aspirate", NUM, "ml"), new F("vomit", "Vomitus / stool", NUM, "ml"),
          new F("weight", "Body weight", DEC, "kg"), new F("note", "Remarks", TEXT, "")],
        ["oral", "iv", "rt", "in", "urine", "drain", "vomit", "out", "bal", "note"],
        ["Oral", "IV", "RT feed", "Total in", "Urine", "Drain/RT", "Vomit/stool", "Total out", "Balance", "Remarks"]),
      new Kind(OPC, "OPC chart", "ORGANOPHOSPHORUS POISONING CHART", "Atropinisation and PAM for OP poisoning", 0xFFD97706, R.drawable.ic_warn,
        [new F("pupil", "Pupil size", DEC, "mm"), new F("hr", "Pulse", NUM, "/min"), new F("sbp", "Systolic BP", NUM, "mmHg"),
          new F("rr", "Resp. rate", NUM, "/min"), new F("spo2", "SpO2", NUM, "%"), new F("temp", "Temperature", DEC, "°F"),
          new F("secretions", "Secretions", SEG, "", "Dry", "Moist", "Copious"), new F("crepts", "Chest crepitations", SEG, "", "Absent", "Present"),
          new F("axilla", "Axilla", SEG, "", "Dry", "Sweating"), new F("bowel", "Bowel sounds", SEG, "", "Present", "Absent"),
          new F("fasc", "Fasciculations", SEG, "", "Absent", "Present"), new F("gcs", "GCS", NUM, "/15"),
          new F("atropine", "Atropine (bolus mg / infusion mg/hr)", TEXT, ""), new F("pam", "PAM", TEXT, ""),
          new F("airway", "Airway", SEG, "", "Own", "NIV", "Intubated"), new F("note", "Remarks", TEXT, "")],
        ["pupil", "hr", "sbp", "secretions", "crepts", "axilla", "bowel", "fasc", "gcs", "atropine", "pam", "status"],
        ["Pupil", "Pulse", "SBP", "Secretions", "Crepts", "Axilla", "Bowel", "Fasc.", "GCS", "Atropine", "PAM", "Status"]),
      new Kind(VENT, "Ventilator chart", "VENTILATOR CHART", "Ventilator settings and ABG as they change", 0xFF0F766E, R.drawable.ic_cloud,
        [new F("mode", "Mode", SEG, "", Charts.VENT_MODES).setting(), new F("fio2", "FiO2", NUM, "%").setting(), new F("peep", "PEEP", NUM, "cmH2O").setting(),
          new F("vt", "Tidal volume", NUM, "ml").setting(), new F("rrset", "Set RR", NUM, "/min").setting(), new F("pi", "Pinsp / PS", NUM, "cmH2O").setting(),
          new F("ie", "I:E", TEXT, "").setting(), new F("ppeak", "Peak pressure", NUM, "cmH2O"), new F("pplat", "Plateau pressure", NUM, "cmH2O"),
          new F("rrtot", "Total RR", NUM, "/min"), new F("spo2", "SpO2", NUM, "%"), new F("ph", "pH", DEC, ""), new F("pco2", "pCO2", NUM, "mmHg"),
          new F("po2", "pO2", NUM, "mmHg"), new F("hco3", "HCO3", DEC, "mEq/l"), new F("sedation", "Sedation", TEXT, ""), new F("note", "Remarks", TEXT, "")],
        ["mode", "fio2", "peep", "vt", "rrset", "pi", "ppeak", "pplat", "dp", "spo2", "ph", "pco2", "po2", "pf", "note"],
        ["Mode", "FiO2", "PEEP", "Vt", "Set RR", "Pi/PS", "Ppeak", "Pplat", "ΔP", "SpO2", "pH", "pCO2", "pO2", "P/F", "Remarks"]),
      new Kind(Charts.VITALS, "Vitals chart", "VITALS / NEWS2 CHART", "Vitals with the NEWS2 early warning score (decision support)", 0xFFBE185D, R.drawable.ic_heart,
        [new F("rr", "Resp. rate", NUM, "/min"), new F("spo2", "SpO2", NUM, "%"), new F("o2", "Air or oxygen", SEG, "", "Air", "Oxygen"),
          new F("temp", "Temperature", DEC, "°F"), new F("sbp", "Systolic BP", NUM, "mmHg"), new F("hr", "Pulse", NUM, "/min"),
          new F("avpu", "Consciousness", SEG, "", "Alert", "Confusion", "Voice", "Pain", "Unresponsive"),
          new F("scale2", "SpO2 scale 2 (COPD or hypercapnic failure, target 88-92%)", SEG, "", "No", "Yes"), new F("note", "Remarks", TEXT, "")],
        ["rr", "spo2", "o2", "scale2", "temp", "sbp", "hr", "avpu", "news", "note"],
        ["RR", "SpO2", "Air/O2", "Scale 2", "Temp °F", "SBP", "Pulse", "ACVPU", "NEWS", "Remarks"]),
    ];
  }

  static kind(code) {
    for (const k of Charts.KINDS) if (k.code === code) return k;
    return Charts.KINDS[0];
  }

  // ---------- which charts a patient needs ----------

  static BP_RX = Pattern.compile("hypertens|\\bhtn\\b|shock|sepsis|septic|hypotens|\\bich\\b|intra ?cerebral|eclampsia|dissection|hypertensive");
  static DM_RX = Pattern.compile("diabet|\\bt[12]? ?dm\\b|\\bdm\\b|\\bdka\\b|\\bhhs\\b|hyperglyc|hypoglyc|ketoacidosis");
  static IO_RX = Pattern.compile("heart|cardi|\\bccf\\b|\\bchf\\b|\\bhf|\\bcad\\b|\\bmi\\b|stemi|\\bacs\\b|\\brhd\\b|valv|\\baf\\b|"
    + "\\baki\\b|\\bckd\\b|renal|kidney|nephr|esrd|dialysis|uraemi|uremi|cirrho|\\bcld\\b|liver|hepat|jaundice|ascites|\\balf\\b|encephalopathy|portal");
  static OPC_RX = Pattern.compile("organo ?phosph|\\bop ?(poison|compound|consumption)|\\bopc\\b|carbamate|\\bop\\b");
  static VENT_RX = Pattern.compile("ventilat|intubat|\\bmv\\b");

  static text(p) {
    return (Ui.nz(p.get("diagnosis")) + " " + Ui.nz(p.get("category")) + " " + Ui.nz(p.get("tox_agent")) + " " + Ui.nz(p.get("tox_kind"))).toLowerCase();
  }

  /** True when the patient's diagnosis calls for this chart. */
  static suggested(p, code) {
    const t = Charts.text(p);
    switch (code) {
      case Charts.BP: return Charts.BP_RX.matcher(t).find();
      case Charts.DM: return Charts.DM_RX.matcher(t).find();
      case Charts.IO: return Charts.IO_RX.matcher(t).find();
      case Charts.OPC: return Charts.OPC_RX.matcher(t).find();
      case Charts.VENT: return "1" === p.get("vent") || Charts.VENT_RX.matcher(t).find();
      case Charts.VITALS: return true;   // NEWS2 for every in-patient
    }
    return false;
  }

  // ---------- entries ----------

  /** The chart day an entry belongs to: before 7:30 AM it is still the previous day. */
  static chartDay(date, time) {
    const d = Dates.parse(date);
    if (d == null) return null;
    const t = Charts.parseTime(time);
    return t != null && t.isBefore(Dates.CHANGEOVER) ? d.minusDays(1) : d;
  }

  static parseTime(s) {
    try { return LocalTime.parse(Ui.nz(s)); } catch (e) { return null; }
  }

  static entries(db, pid, code) {
    return db.rows("SELECT * FROM charts WHERE patient_id=? AND kind=? ORDER BY date, time, id", String(pid), code);
  }

  static count(db, pid, code) {
    return db.num("SELECT COUNT(*) FROM charts WHERE patient_id=? AND kind=?", String(pid), code);
  }

  static last(db, pid, code) {
    return db.row("SELECT * FROM charts WHERE patient_id=? AND kind=? ORDER BY date DESC, time DESC, id DESC LIMIT 1", String(pid), code);
  }

  static data(e) {
    try { return new JSONObject(Ui.nz(e.get("data"))); } catch (ex) { return new JSONObject(); }
  }

  static save(db, id, pid, code, date, time, o, by) {
    const cv = new ContentValues();
    cv.put("patient_id", String(pid));
    cv.put("kind", code);
    cv.put("date", date);
    cv.put("time", time);
    cv.put("data", o.toString());
    cv.put("by_name", by);
    if (id > 0) {
      db.update("charts", cv, id);
      return id;
    }
    cv.put("created", Dates.todayIso() + " " + Dates.now());
    return db.insert("charts", cv);
  }

  /** Entries grouped by chart day, oldest day first. */
  static byDay(es) {
    const m = new ObjKeyMap();
    const sorted = ArrayList(es);
    Collections.sort(sorted, { compare: (a, b) => Charts.stamp(a).compareTo(Charts.stamp(b)) });
    for (const e of sorted) {
      const d = Charts.chartDay(e.get("date"), e.get("time"));
      if (d == null) continue;
      if (!m.containsKey(d)) m.put(d, []);
      m.get(d).add(e);
    }
    return m;
  }

  static stamp(e) {
    return Ui.nz(e.get("date")) + " " + Ui.nz(e.get("time"));
  }

  // ---------- values, computed columns and colours ----------

  static num(o, k) {
    const s = o.optString(k).trim().replaceAllRx("[^0-9.\\-]", "");
    if (s.isEmpty() || s === "." || s === "-") return NaN;
    try { return Double.parseDouble(s); } catch (e) { return NaN; }
  }

  static fmt(v) {
    if (Number.isNaN(v)) return "";
    return v === Math.rint(v) ? String(Math.trunc(v)) : jfmt("%.1f", v);
  }

  static map(o) {
    const s = Charts.num(o, "sbp"), d = Charts.num(o, "dbp");
    return Number.isNaN(s) || Number.isNaN(d) ? NaN : Math.round((s + 2 * d) / 3);
  }

  static intake(o) { return Charts.sum(o, "oral", "iv", "rt"); }

  static output(o) { return Charts.sum(o, "urine", "drain", "vomit"); }

  static sum(o, ...ks) {
    if (ks.length === 1 && Array.isArray(ks[0])) ks = ks[0];
    let t = 0;
    let any = false;
    for (const k of ks) {
      const v = Charts.num(o, k);
      if (!Number.isNaN(v)) { t += v; any = true; }
    }
    return any ? t : NaN;
  }

  /** P/F ratio from pO2 and FiO2. */
  static pf(o) {
    const po2 = Charts.num(o, "po2"), f = Charts.num(o, "fio2");
    return Number.isNaN(po2) || Number.isNaN(f) || f <= 0 ? NaN : Math.round(po2 / (f > 1 ? f / 100 : f));
  }

  /** Driving pressure: plateau minus PEEP. */
  static dp(o) {
    const a = Charts.num(o, "pplat"), b = Charts.num(o, "peep");
    return Number.isNaN(a) || Number.isNaN(b) ? NaN : a - b;
  }

  /** OP poisoning: atropinised when the chest is clear, pulse over 80, SBP over 80, pupils no longer pinpoint and axillae dry. */
  static opcStatus(o) {
    const hr = Charts.num(o, "hr"), sbp = Charts.num(o, "sbp"), pupil = Charts.num(o, "pupil"), temp = Charts.num(o, "temp");
    const toxic = hr > 120 || temp > 100.4 || "Absent" === o.optString("bowel");
    const known = !Number.isNaN(hr) || !o.optString("crepts").isEmpty() || !o.optString("axilla").isEmpty();
    if (!known) return "";
    const clear = "Present" !== o.optString("crepts") && "Copious" !== o.optString("secretions");
    const ok = clear && (Number.isNaN(hr) || hr > 80) && (Number.isNaN(sbp) || sbp > 80)
      && (Number.isNaN(pupil) || pupil > 2) && "Sweating" !== o.optString("axilla");
    if (ok && toxic) return "Atropinised; watch for atropine toxicity";
    if (ok) return "Atropinised";
    return "Not yet atropinised";
  }

  /** The text in a table cell (a field or a computed column). */
  static cell(k, o, col) {
    switch (col) {
      case "map": return Charts.fmt(Charts.map(o));
      case "in": return Charts.fmt(Charts.intake(o));
      case "out": return Charts.fmt(Charts.output(o));
      case "bal": {
        const i = Charts.intake(o), x = Charts.output(o);
        if (Number.isNaN(i) && Number.isNaN(x)) return "";
        const b = (Number.isNaN(i) ? 0 : i) - (Number.isNaN(x) ? 0 : x);
        return (b > 0 ? "+" : "") + Charts.fmt(b);
      }
      case "pf": return Charts.fmt(Charts.pf(o));
      case "dp": return Charts.fmt(Charts.dp(o));
      case "status": return Charts.opcStatus(o);
      case "news": return Ews.cell(o);
    }
    return o.optString(col).trim();
  }

  /** RED, AMBER, GREEN or 0 for a cell's value. */
  static flag(k, o, col) {
    const RED = Charts.RED, AMBER = Charts.AMBER, GREEN = Charts.GREEN, num = Charts.num;
    let v;
    switch (k.code + ":" + col) {
      case "BP:sbp": v = num(o, "sbp"); return Number.isNaN(v) ? 0 : v >= 180 || v < 90 ? RED : v >= 140 ? AMBER : GREEN;
      case "BP:dbp": v = num(o, "dbp"); return Number.isNaN(v) ? 0 : v >= 110 || v < 50 ? RED : v >= 90 ? AMBER : GREEN;
      case "BP:map": v = Charts.map(o); return Number.isNaN(v) ? 0 : v < 65 ? RED : GREEN;
      case "BP:hr": case "OPC:hr": v = num(o, "hr"); return Number.isNaN(v) ? 0 : v > 120 || v < 50 ? RED : v > 100 || v < 60 ? AMBER : 0;
      case "BP:spo2": case "VENT:spo2": v = num(o, "spo2"); return Number.isNaN(v) ? 0 : v < 90 ? RED : v < 94 ? AMBER : 0;
      case "DM:grbs": v = num(o, "grbs"); return Number.isNaN(v) ? 0 : v < 70 || v > 300 ? RED : v > 180 ? AMBER : GREEN;
      case "DM:ketone": return o.optString("ketone").startsWith("+") ? RED : o.optString("ketone") === "Trace" ? AMBER : 0;
      case "IO:bal": {
        const i = Charts.intake(o), x = Charts.output(o);
        if (Number.isNaN(i) && Number.isNaN(x)) return 0;
        const b = (Number.isNaN(i) ? 0 : i) - (Number.isNaN(x) ? 0 : x);
        return b > 0 ? 0xFF2563EB : b < 0 ? AMBER : 0;
      }
      case "OPC:pupil": v = num(o, "pupil"); return Number.isNaN(v) ? 0 : v <= 2 ? RED : GREEN;
      case "OPC:sbp": v = num(o, "sbp"); return Number.isNaN(v) ? 0 : v <= 80 ? RED : 0;
      case "OPC:secretions": return "Copious" === o.optString("secretions") ? RED : "Moist" === o.optString("secretions") ? AMBER : "Dry" === o.optString("secretions") ? GREEN : 0;
      case "OPC:crepts": return "Present" === o.optString("crepts") ? RED : "Absent" === o.optString("crepts") ? GREEN : 0;
      case "OPC:axilla": return "Sweating" === o.optString("axilla") ? RED : "Dry" === o.optString("axilla") ? GREEN : 0;
      case "OPC:bowel": return "Absent" === o.optString("bowel") ? AMBER : 0;
      case "OPC:fasc": return "Present" === o.optString("fasc") ? RED : 0;
      case "OPC:gcs": v = num(o, "gcs"); return Number.isNaN(v) ? 0 : v <= 8 ? RED : v < 13 ? AMBER : 0;
      case "OPC:status": { const s = Charts.opcStatus(o); return s.isEmpty() ? 0 : s.startsWith("Not") ? RED : s.contains("toxicity") ? AMBER : GREEN; }
      case "VENT:fio2": v = num(o, "fio2"); return Number.isNaN(v) ? 0 : v >= 80 ? RED : v >= 60 ? AMBER : 0;
      case "VENT:peep": v = num(o, "peep"); return Number.isNaN(v) ? 0 : v >= 12 ? AMBER : 0;
      case "VENT:pplat": v = num(o, "pplat"); return Number.isNaN(v) ? 0 : v > 30 ? RED : 0;
      case "VENT:ppeak": v = num(o, "ppeak"); return Number.isNaN(v) ? 0 : v > 40 ? RED : 0;
      case "VENT:dp": v = Charts.dp(o); return Number.isNaN(v) ? 0 : v > 15 ? RED : 0;
      case "VENT:ph": v = num(o, "ph"); return Number.isNaN(v) ? 0 : v < 7.25 || v > 7.55 ? RED : v < 7.35 || v > 7.45 ? AMBER : GREEN;
      case "VENT:pco2": v = num(o, "pco2"); return Number.isNaN(v) ? 0 : v > 60 || v < 25 ? RED : v > 45 || v < 35 ? AMBER : 0;
      case "VITALS:news": return Ews.flag(o);
      case "VITALS:rr": case "VITALS:spo2": case "VITALS:temp": case "VITALS:sbp": case "VITALS:hr": case "VITALS:avpu": return Ews.paramFlag(o, col);
      case "VENT:pf": v = Charts.pf(o); return Number.isNaN(v) ? 0 : v < 100 ? RED : v < 200 ? AMBER : v < 300 ? 0xFFCA8A04 : GREEN;
    }
    return 0;
  }

  /** One-line reading of an entry for lists and the hero. */
  static line(k, o) {
    const b = [];
    switch (k.code) {
      case Charts.BP:
        if (!o.optString("sbp").isEmpty()) b.add("BP " + o.optString("sbp") + "/" + o.optString("dbp") + (Number.isNaN(Charts.map(o)) ? "" : " (MAP " + Charts.fmt(Charts.map(o)) + ")"));
        if (!o.optString("hr").isEmpty()) b.add("PR " + o.optString("hr"));
        if (!o.optString("spo2").isEmpty()) b.add("SpO2 " + o.optString("spo2") + "%");
        if (!o.optString("pressor").isEmpty()) b.add(o.optString("pressor"));
        if (!o.optString("drug").isEmpty()) b.add(o.optString("drug"));
        break;
      case Charts.DM:
        if (!o.optString("grbs").isEmpty()) b.add((o.optString("slot").isEmpty() ? "" : o.optString("slot") + " ") + "GRBS " + o.optString("grbs"));
        if (!o.optString("ketone").isEmpty()) b.add("ketones " + o.optString("ketone"));
        if (!o.optString("given").isEmpty()) b.add("given " + o.optString("given"));
        if (!o.optString("regimen").isEmpty()) b.add("regimen " + o.optString("regimen"));
        break;
      case Charts.IO:
        if (!Number.isNaN(Charts.intake(o))) b.add("In " + Charts.fmt(Charts.intake(o)) + " ml");
        if (!Number.isNaN(Charts.output(o))) b.add("Out " + Charts.fmt(Charts.output(o)) + " ml" + (o.optString("urine").isEmpty() ? "" : " (urine " + o.optString("urine") + ")"));
        break;
      case Charts.OPC:
        if (!o.optString("pupil").isEmpty()) b.add("Pupil " + o.optString("pupil") + " mm");
        if (!o.optString("hr").isEmpty()) b.add("PR " + o.optString("hr"));
        if (!o.optString("sbp").isEmpty()) b.add("SBP " + o.optString("sbp"));
        if (!o.optString("crepts").isEmpty()) b.add("crepts " + o.optString("crepts").toLowerCase());
        if (!o.optString("atropine").isEmpty()) b.add("atropine " + o.optString("atropine"));
        break;
      case Charts.VENT:
        if (!o.optString("mode").isEmpty()) b.add(o.optString("mode"));
        if (!o.optString("fio2").isEmpty()) b.add("FiO2 " + o.optString("fio2") + "%");
        if (!o.optString("peep").isEmpty()) b.add("PEEP " + o.optString("peep"));
        if (!o.optString("vt").isEmpty()) b.add("Vt " + o.optString("vt"));
        if (!o.optString("rrset").isEmpty()) b.add("RR " + o.optString("rrset"));
        if (!Number.isNaN(Charts.pf(o))) b.add("P/F " + Charts.fmt(Charts.pf(o)));
        break;
      case Charts.VITALS: {
        const r = Ews.score(o);
        if (r.count > 0) b.add("NEWS " + r.total + (r.partial ? "*" : "") + " " + r.band);
        if (!o.optString("rr").isEmpty()) b.add("RR " + o.optString("rr"));
        if (!o.optString("spo2").isEmpty()) b.add("SpO2 " + o.optString("spo2") + "%" + ("Oxygen" === o.optString("o2") ? " on O2" : ""));
        if (!o.optString("sbp").isEmpty()) b.add("SBP " + o.optString("sbp"));
        if (!o.optString("hr").isEmpty()) b.add("PR " + o.optString("hr"));
        if (!o.optString("temp").isEmpty()) b.add(o.optString("temp") + "°F");
        if (!o.optString("avpu").isEmpty() && "Alert" !== o.optString("avpu")) b.add(o.optString("avpu"));
        break;
      }
    }
    if (b.isEmpty() && !o.optString("note").isEmpty()) b.add(o.optString("note"));
    return TextUtils.join("  ·  ", b);
  }

  /** The worst colour among an entry's columns (for the time pill in lists). */
  static worst(k, o) {
    let w = 0;
    for (const c of k.cols) {
      const f = Charts.flag(k, o, c);
      if (f === Charts.RED) return Charts.RED;
      if (f === Charts.AMBER) w = Charts.AMBER;
      else if (f !== 0 && w === 0) w = Charts.GREEN;
    }
    return w;
  }

  /** I/O totals for a day: intake, output, urine, balance, and urine ml/kg/hr when the weight is known. */
  static ioTotals(day, weight) {
    let inn = 0, out = 0, urine = 0;
    for (const e of day) {
      const o = Charts.data(e);
      if (!Number.isNaN(Charts.intake(o))) inn += Charts.intake(o);
      if (!Number.isNaN(Charts.output(o))) out += Charts.output(o);
      const u = Charts.num(o, "urine");
      if (!Number.isNaN(u)) urine += u;
    }
    const perKg = weight > 0 ? urine / weight / 24 : NaN;
    return [inn, out, urine, inn - out, perKg];
  }

  static weight(es) {
    let w = NaN;
    for (const e of es) {
      const v = Charts.num(Charts.data(e), "weight");
      if (!Number.isNaN(v) && v > 0) w = v;
    }
    return w;
  }

  /** The insulin regimen in force at the end of a day (the latest one written up to then). */
  static regimenUpTo(all, day) {
    let r = "";
    for (const e of all) {
      const d = Charts.chartDay(e.get("date"), e.get("time"));
      if (d != null && !d.isAfter(day) && !Charts.data(e).optString("regimen").trim().isEmpty()) r = Charts.data(e).optString("regimen").trim();
    }
    return r;
  }

  // ---------- Word / PDF ----------

  static c(s) { return new FormDoc.Cell(s); }

  static soft(flag) {
    return flag === Charts.RED ? 0xFFFDE2E1 : flag === Charts.AMBER ? 0xFFFFF1D6 : flag === Charts.GREEN ? 0xFFDCFCE7 : flag === 0xFFCA8A04 ? 0xFFFEF9C3 : flag === 0xFF2563EB ? 0xFFDBEAFE : 0;
  }

  /** The chart as a coloured A4 document, for the days from..to (null = whole stay). */
  static doc(db, p, code, from, to) {
    const c = Charts.c;
    const k = Charts.kind(code);
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = k.title;
    const all = Charts.entries(db, Long.parseLong(p.get("id")), code);
    const days = Charts.byDay(all);
    const keep = [];
    for (const d of days.keySet()) if ((from == null || !d.isBefore(from)) && (to == null || !d.isAfter(to))) keep.add(d);
    const period = keep.isEmpty() ? "No entries" : keep.size() === 1 ? Dates.nice(keep.get(0)) : Dates.nice(keep.get(0)) + " to " + Dates.nice(keep.get(keep.size() - 1));
    f.footer = Ui.nz(p.get("name")) + "  •  " + k.name + "  •  " + period + "  •  " + f.dept;
    f.fileBase = k.name.split("/").join("").split(" ").join("_") + "_" + Ui.nz(p.get("name")).replaceAllRx("[^A-Za-z0-9]+", "_") + "_" + (keep.isEmpty() ? Dates.todayIso() : keep.get(keep.size() - 1).toString());

    const head = 0xFFF1F5F9;
    const h = f.block(null, 0, 0.34, 0.22, 0.22, 0.22);
    const age = Ui.nz(p.get("age")) + (Ui.nz(p.get("sex")).isEmpty() ? "" : " / " + p.get("sex"));
    h.row(15, c("Name: " + Ui.nz(p.get("name"))).b(), c("Age / Sex: " + age), c("IP No: " + Ui.nz(p.get("ip_no"))), c("Unit: " + Db.shortName(Ui.nz(p.get("home_unit")).isEmpty() ? p.get("location") : p.get("home_unit"))));
    h.row(15, c("Diagnosis: " + Ui.nz(p.get("diagnosis"))).span(2), c("Ward: " + Db.shortName(p.get("location")) + (Ui.nz(p.get("bed")).isEmpty() ? "" : ", bed " + p.get("bed"))), c("Period: " + period));

    if (code === Charts.DM) Charts.dmGrid(f, k, all, days, keep);
    for (const d of keep) {
      const es = days.get(d);
      const w = Charts.widths(k);
      const b = f.block(Dates.nice(d).toUpperCase() + "  ·  7:30 AM to 7:30 AM  ·  " + es.size() + (es.size() === 1 ? " entry" : " entries"), k.color, w);
      const hr = b.row(14, c("Time").b().fill(head).size(7));
      for (const hd of k.heads) hr.cells.add(c(hd).b().center().fill(head).size(7));
      let prev = null;
      for (const e of es) {
        const o = Charts.data(e);
        const r = b.row(13, c(Ui.nz(e.get("time"))).b().size(7.5));
        for (const col of k.cols) {
          const v = Charts.cell(k, o, col);
          const fl = Charts.flag(k, o, col);
          const cc = c(v).size(7.5);
          if (col !== "note" && col !== "given" && col !== "regimen" && col !== "pressor" && col !== "drug"
            && col !== "atropine" && col !== "pam" && col !== "status") cc.center();
          if (fl !== 0) cc.fill(Charts.soft(fl)).color(fl === 0xFFCA8A04 ? 0xFF854D0E : fl).b();
          const fd = k.field(col);
          if (fd != null && fd._setting && prev != null && !v.isEmpty() && v !== prev.optString(col).trim()) cc.fill(0xFFFEF3C7).color(0xFF92400E).b();
          r.cells.add(cc);
        }
        prev = o;
      }
      if (code === Charts.IO) {
        const t = Charts.ioTotals(es, Charts.weight(all));
        const tr = b.row(14, c("Total").b().fill(0xFFE0F2FE));
        const vals = ["", "", "", Charts.fmt(t[0]), Charts.fmt(t[2]), "", "", Charts.fmt(t[1]), (t[3] > 0 ? "+" : "") + Charts.fmt(t[3]),
          Number.isNaN(t[4]) ? "" : "Urine " + jfmt("%.2f", t[4]) + " ml/kg/hr"];
        for (let i = 0; i < vals.length; i++) {
          const cc = c(vals[i]).b().center().fill(0xFFE0F2FE).size(7.5);
          if (i === 4 && t[2] < 400) cc.fill(0xFFFDE2E1).color(Charts.RED);
          if (i === 9 && !Number.isNaN(t[4]) && t[4] < 0.5) cc.fill(0xFFFDE2E1).color(Charts.RED);
          tr.cells.add(cc);
        }
      }
    }
    if (keep.isEmpty()) f.block(null, 0, 1).row(16, c("No entries in this period."));

    const lg = f.block("COLOUR KEY", 0xFF64748B, 0.18, 0.82);
    for (const l of Charts.legend(code)) lg.row(13, c(l[0]).b().center().fill(Charts.soft(Integer.parseInt(l[2]))).color(Integer.parseInt(l[2])).size(7.5), c(l[1]).size(7.5));
    return f;
  }

  /** Diabetic chart summary: one row per day, one column per time of the day, and the regimen. */
  static dmGrid(f, k, all, days, keep) {
    const c = Charts.c, RED = Charts.RED, AMBER = Charts.AMBER, GREEN = Charts.GREEN;
    const w = new Array(Charts.DM_SHORT.length + 2).fill(0);
    w[0] = 0.11;
    for (let i = 0; i < Charts.DM_SHORT.length; i++) w[i + 1] = 0.065;
    w[w.length - 1] = 1 - 0.11 - 0.065 * Charts.DM_SHORT.length;
    const b = f.block("SUGAR AT A GLANCE (GRBS mg/dl) AND THE DAY'S INSULIN REGIMEN", k.color, w);
    const hr = b.row(14, c("Date").b().fill(0xFFF3E8FF).size(7));
    for (const s of Charts.DM_SHORT) hr.cells.add(c(s).b().center().fill(0xFFF3E8FF).size(7));
    hr.cells.add(c("Insulin regimen").b().fill(0xFFF3E8FF).size(7));
    let before = "";
    for (const d of days.keySet()) {
      if (keep.contains(d)) break;
      before = Charts.regimenUpTo(all, d);
    }
    for (const d of keep) {
      const r = b.row(14, c(d.format(DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH))).b().size(7.5));
      for (const slot of Charts.DM_SLOTS) {
        const v = new StringBuilder();
        let worst = 0;
        for (const e of days.get(d)) {
          const o = Charts.data(e);
          if (slot !== o.optString("slot") || o.optString("grbs").isEmpty()) continue;
          v.append(v.length() === 0 ? "" : ", ").append(o.optString("grbs"));
          const fl = Charts.flag(k, o, "grbs");
          if (fl === RED || worst === 0 || (fl === AMBER && worst === GREEN)) worst = fl;
        }
        const cc = c(v.toString()).center().size(7.5);
        if (worst !== 0) cc.fill(Charts.soft(worst)).color(worst).b();
        r.cells.add(cc);
      }
      const reg = Charts.regimenUpTo(all, d);
      const changed = !reg.isEmpty() && reg !== before;
      const rc = c(reg + (changed && !before.isEmpty() ? "  (changed)" : "")).size(7.5);
      if (changed && !before.isEmpty()) rc.fill(0xFFFEF3C7).color(0xFF92400E).b();
      r.cells.add(rc);
      before = reg;
    }
  }

  static widths(k) {
    const n = k.cols.length;
    const w = new Array(n + 1).fill(0);
    const time = 0.07;
    // wide text columns get more room
    let units = 0;
    for (const c of k.cols) units += Charts.wide(c) ? 2.4 : 1;
    w[0] = time;
    for (let i = 0; i < n; i++) w[i + 1] = (1 - time) * (Charts.wide(k.cols[i]) ? 2.4 : 1) / units;
    return w;
  }

  static wide(c) {
    return c === "note" || c === "given" || c === "regimen" || c === "pressor" || c === "drug" || c === "atropine" || c === "status";
  }

  static legend(code) {
    const r = String(Charts.RED), a = String(Charts.AMBER), g = String(Charts.GREEN);
    switch (code) {
      case Charts.BP: return [["Red", "SBP ≥ 180 or < 90, DBP ≥ 110 or < 50, MAP < 65, pulse > 120 or < 50, SpO2 < 90", r],
        ["Amber", "SBP 140–179, DBP 90–109, pulse 101–120 or 50–59, SpO2 90–93", a], ["Green", "In the target range", g]];
      case Charts.DM: return [["Red", "GRBS < 70 or > 300, urine ketones +", r], ["Amber", "GRBS 181–300, ketones trace; regimen changed that day", a],
        ["Green", "GRBS 70–180", g]];
      case Charts.IO: return [["Red", "Urine < 400 ml in the day, or < 0.5 ml/kg/hr", r], ["Blue", "Positive balance (more in than out)", String(0xFF2563EB)],
        ["Amber", "Negative balance (more out than in)", a]];
      case Charts.OPC: return [["Red", "Pinpoint pupils (≤ 2 mm), crepitations, copious secretions, sweating axilla, SBP ≤ 80, fasciculations, GCS ≤ 8: not yet atropinised", r],
        ["Amber", "Moist secretions, absent bowel sounds, pulse > 100: watch for atropine toxicity", a],
        ["Green", "Atropinisation targets met: clear chest, pulse > 80, SBP > 80, pupils not pinpoint, dry axillae", g]];
      case Charts.VITALS: return [["Red", "NEWS2 7 or more (high: emergency assessment); a single reading scoring 3 shows red in its own cell", r],
        ["Amber", "NEWS2 5-6 (medium: urgent review), or any single reading scoring 3 (low-medium: urgent ward review); readings scoring 1-2", a], ["Green", "NEWS2 0-4 (low). * = partial score, some readings missing. Decision support only (Royal College of Physicians NEWS2, 2017).", g]];
      default: return [["Red", "FiO2 ≥ 80%, Pplat > 30, ΔP > 15, Ppeak > 40, P/F < 100, pH < 7.25, SpO2 < 90", r],
        ["Amber", "Setting changed from the previous entry; FiO2 60–79%, PEEP ≥ 12, P/F 100–199", a], ["Green", "pH 7.35–7.45, P/F ≥ 300", g]];
    }
  }
}

Charts.F = class {
  constructor(key, label, type, unit, ...opts) {
    if (opts.length === 1 && Array.isArray(opts[0])) opts = opts[0];
    this.key = key; this.label = label; this.type = type; this.unit = unit; this.opts = opts;
    this._setting = false;   // a ventilator setting: a change from the last entry is highlighted (Java field "setting")
  }

  setting() { this._setting = true; return this; }
};

Charts.Kind = class {
  /** Columns in the table and the Word / PDF file: field keys, or computed ones (map, pf, dp, status, in, out, bal). */
  constructor(code, name, title, about, color, icon, fields, cols, heads) {
    this.code = code; this.name = name; this.title = title; this.about = about; this.color = color; this.icon = icon;
    this.fields = fields; this.cols = cols; this.heads = heads;
  }

  field(key) {
    for (const f of this.fields) if (f.key === key) return f;
    return null;
  }
};
;
