/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Faculty chat: the All faculty chat (id 0, everyone), direct chats and groups.
 * Members are kept as ",12,34," so the server shares each chat only with its members.
 * Read receipts compare times, since message ids from different phones are not in order.
 */
class Chat {
  constructor() {}

  static GREEN = 0xFF0F8A5F;
  static DARK = 0xFF075E54;
  static BUBBLE_ME = 0xFFDCF8C6;
  static WALL = 0xFFECE5DD;
  static TICK_BLUE = 0xFF34B7F1;
  static ALL = 0;
  /** The Duty team chat: today's DAP and duty PGs, without the HOD. It has no row of its own. */
  static DUTY = 4000000000000000000;
  static CHANNEL = "chat";
  static MAX_FILE = 20 * 1024 * 1024;
  static STAMP = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS");
  /** The chat open on screen now, so its messages don't also pop up as notifications. */
  static openChat = -1;

  static now() {
    return LocalDateTime.now().format(Chat.STAMP);
  }

  static stamp(t) {
    return t.format(Chat.STAMP);
  }

  static parse(t) {
    try {
      return LocalDateTime.parse(t, Chat.STAMP);
    } catch (e) {
      return null;
    }
  }

  /**
   * faculty(Context): Faculty chats: HOD, Professors, Associate and Assistant Professors (anyone on a phone that isn't shared).
   * faculty(Db): the faculty rows.
   */
  static faculty(x) {
    if (x instanceof Db) {
      const db = x;
      return db.rows("SELECT * FROM staff WHERE role IN ('Professor','Associate Professor','Assistant Professor') AND " + Approvals.APPROVED_SQL
          + " ORDER BY CASE role WHEN 'Professor' THEN 0 WHEN 'Associate Professor' THEN 1 ELSE 2 END, name");
    }
    return SessionAttendance.canRun(x);
  }

  /** The chat screens: the faculty, and anyone on today's duty team or who was on an earlier one. */
  static canUse(c) {
    if (Chat.faculty(c)) return true;
    const db = Db.get(c);
    return !Chat.isHod(c, db) && (Chat.inDuty(c, db) || db.num("SELECT COUNT(*) FROM chat_messages WHERE chat_id=?", String(Chat.DUTY)) > 0);
  }

  // ---------- the Duty team chat ----------

  static bare(name) {
    const x = Ui.nz(name).toLowerCase().replaceAllRx("\\b(prof|dr|md|mbbs|dnb|frcp)\\b", " ");
    return x.replaceAllRx("[^a-z]", "");
  }

  static sameName(a, b) {
    const x = Chat.bare(a), y = Chat.bare(b);
    if (x.isEmpty() || y.isEmpty()) return false;
    if (x.equals(y)) return true;
    // "S. Kumar" = "Kumar" (an initial more or less), but "Kumar" is not "Rathnakumar"
    const lo = Math.min(x.length, y.length), hi = Math.max(x.length, y.length);
    return lo > 4 && lo * 10 >= hi * 7 && (x.contains(y) || y.contains(x));
  }

  static staffId(db, name) {
    for (const s of db.rows("SELECT id, name FROM staff WHERE " + Approvals.APPROVED_SQL + " ORDER BY id"))
      if (Chat.sameName(s.get("name"), name)) return Long.parseLong(s.get("id"));
    return -1;
  }

  /** Is this phone's person the HOD (the name in Settings)? The HOD is left out of the Duty team. */
  static isHod(c, db) {
    if ("hod" === Cloud.role(c)) return true;
    const hod = db.setting("hod", "");
    return !hod.isEmpty() && Chat.sameName(Chat.myName(c, db), hod);
  }

  /** Staff ids of today's duty team: the DAP and the PGs on the call duty desk, never the HOD. */
  static dutyTeam(db) {
    const ids = [];
    const hod = db.setting("hod", "");
    for (const e of CallDutyActivity.members(db, Dates.admitDay().toString()).entrySet()) {
      if ("HOD" === e.getValue()[0] || (!hod.isEmpty() && Chat.sameName(e.getKey(), hod))) continue;
      const id = Chat.staffId(db, e.getKey());
      if (id > 0 && !ids.contains(id)) ids.add(id);
    }
    return ids;
  }

  static inDuty(c, db) {
    const me = Chat.me(c);
    return me > 0 ? Chat.dutyTeam(db).contains(me) : !Cloud.active(c);
  }

  static dutyChat(db) {
    const m = new JMap();
    m.put("id", String(Chat.DUTY));
    m.put("kind", "duty");
    m.put("name", "Duty team");
    m.put("members", Chat.members(Chat.dutyTeam(db)));
    m.put("created_by", "");
    return m;
  }

  static isDuty(chat) {
    return "duty" === chat.get("kind");
  }

  /** Who may write in a chat: in the Duty team only today's team. */
  static canPost(c, db, chat) {
    return !Chat.isDuty(chat) || Chat.inDuty(c, db);
  }

  static me(c) {
    return Cloud.active(c) ? Cloud.myStaff(c) : -1;
  }

  static myName(c, db) {
    const me = Chat.me(c);
    if (me > 0) {
      const s = db.row("SELECT name FROM staff WHERE id=?", String(me));
      if (s != null && !s.get("name").isEmpty()) return s.get("name");
    }
    let n = Cloud.active(c) ? Cloud.prefs(c).getString("name", "") : "";
    if (n.isEmpty()) n = CallDutyActivity.myName(c);
    return n.isEmpty() ? "Me" : n;
  }

  static staff(db, id) {
    return db.row("SELECT * FROM staff WHERE id=?", Ui.nz(id));
  }

  static members(ids) {
    const sb = new StringBuilder(",");
    for (const id of ids) sb.append(id).append(',');
    return sb.toString();
  }

  static memberIds(chat) {
    const out = [];
    for (const s of Ui.nz(chat.get("members")).jsplit(",")) if (!s.trim().isEmpty()) out.add(s.trim());
    return out;
  }

  /** The All faculty chat, which has no row of its own. */
  static allChat() {
    const m = new JMap();
    m.put("id", "0");
    m.put("kind", "all");
    m.put("name", "All faculty");
    m.put("members", "");
    m.put("created_by", "");
    return m;
  }

  static chat(db, id) {
    return id == Chat.ALL ? Chat.allChat() : id == Chat.DUTY ? Chat.dutyChat(db) : db.row("SELECT * FROM chats WHERE id=?", String(id));
  }

  /** Chats this person is in: All faculty first, the Duty team second, then direct chats and groups. */
  static chats(c, db) {
    const out = [];
    const fac = Chat.faculty(c);
    if (fac) out.add(Chat.allChat());
    if (!Chat.isHod(c, db) && (Chat.inDuty(c, db) || db.num("SELECT COUNT(*) FROM chat_messages WHERE chat_id=?", String(Chat.DUTY)) > 0)) out.add(Chat.dutyChat(db));
    if (!fac) return out;
    const me = Chat.me(c);
    for (const r of db.rows("SELECT * FROM chats ORDER BY id"))
      if (me <= 0 || Ui.nz(r.get("members")).contains("," + me + ",")) out.add(r);
    return out;
  }

  static isGroup(chat) {
    return "direct" !== chat.get("kind");
  }

  /** For a direct chat, the other person. */
  static other(c, db, chat) {
    const me = String(Chat.me(c));
    for (const id of Chat.memberIds(chat)) if (!id.equals(me)) return Chat.staff(db, id);
    return null;
  }

  static title(c, db, chat) {
    if (Chat.isGroup(chat)) return Ui.nz(chat.get("name")).isEmpty() ? "Group" : chat.get("name");
    const o = Chat.other(c, db, chat);
    return o == null ? "Chat" : o.get("name");
  }

  static lastRead(db, chatId, me) {
    const r = db.row("SELECT MAX(time) AS t FROM chat_reads WHERE chat_id=? AND staff_id=?", chatId, String(me));
    return r == null ? "" : Ui.nz(r.get("t"));
  }

  static unread(c, db, chatId) {
    const me = Chat.me(c);
    return db.num("SELECT COUNT(*) FROM chat_messages WHERE chat_id=? AND sender_id<>? AND deleted='' AND time>?",
        chatId, String(me), Chat.lastRead(db, chatId, me));
  }

  static totalUnread(c, db) {
    if (!Chat.canUse(c)) return 0;
    let n = 0;
    for (const ch of Chat.chats(c, db)) n += Chat.unread(c, db, ch.get("id"));
    return n;
  }

  /** Notes that this person has read the chat up to its latest message. */
  /** Who a new message or read receipt is shared with. The Duty team changes every day: today's team, and always the sender. */
  static shareWith(c, chat) {
    let members = Ui.nz(chat.get("members"));
    if (!Chat.isDuty(chat)) return members;
    if (Chat.me(c) > 0 && !members.contains("," + Chat.me(c) + ",")) members = (members.isEmpty() ? "," : members) + Chat.me(c) + ",";
    return members.isEmpty() ? ",-1," : members;
  }

  static markRead(c, db, chat) {
    const id = chat.get("id");
    const last = db.row("SELECT MAX(time) AS t FROM chat_messages WHERE chat_id=?", id);
    const t = last == null ? "" : Ui.nz(last.get("t"));
    const me = Chat.me(c);
    if (t.isEmpty() || t.compareTo(Chat.lastRead(db, id, me)) <= 0) return;
    const r = db.row("SELECT id FROM chat_reads WHERE chat_id=? AND staff_id=? ORDER BY time DESC LIMIT 1", id, String(me));
    const cv = new ContentValues();
    cv.put("chat_id", id);
    cv.put("staff_id", me);
    cv.put("time", t);
    cv.put("members", Chat.shareWith(c, chat));
    if (r == null) db.insert("chat_reads", cv);
    else db.update("chat_reads", cv, Long.parseLong(r.get("id")));
  }

  /** Read times of the other members, by staff id. */
  static readTimes(db, chatId) {
    const out = new JMap();
    for (const r of db.rows("SELECT staff_id, MAX(time) AS t FROM chat_reads WHERE chat_id=? GROUP BY staff_id", chatId))
      out.put(r.get("staff_id"), r.get("t"));
    return out;
  }

  /** Everyone who should read a chat (for All faculty, every faculty member with a login). */
  static audience(db, chat) {
    if (Chat.isDuty(chat)) {
      const ids = [];
      for (const id of Chat.dutyTeam(db)) ids.add(String(id));
      return ids;
    }
    if (Chat.isGroup(chat) && Ui.nz(chat.get("members")).isEmpty()) {
      const ids = [];
      for (const s of Chat.faculty(db)) ids.add(s.get("id"));
      return ids;
    }
    return Chat.memberIds(chat);
  }

  static send(c, db, chat, text, file, fileName, replyTo, important) {
    const cv = new ContentValues();
    cv.put("chat_id", chat.get("id"));
    cv.put("sender_id", Chat.me(c));
    cv.put("sender_name", Chat.myName(c, db));
    cv.put("text", text);
    cv.put("time", Chat.now());
    cv.put("reply_to", Ui.nz(replyTo).isEmpty() ? null : replyTo);
    cv.put("file", Ui.nz(file));
    cv.put("file_name", Ui.nz(fileName));
    cv.put("important", important ? "1" : "");
    cv.put("deleted", "");
    cv.put("members", Chat.shareWith(c, chat));
    const id = db.insert("chat_messages", cv);
    Chat.markRead(c, db, chat);
    return id;
  }

  /** One line for lists and notifications. */
  static preview(m) {
    if ("1" === m.get("deleted")) return "This message was deleted";
    let t = Ui.nz(m.get("text")).split("\n").join(" ").trim();
    if (!Ui.nz(m.get("file")).isEmpty()) {
      const f = Store.isImage(m.get("file")) ? "📷 Photo" : "📎 " + (Ui.nz(m.get("file_name")).isEmpty() ? "File" : m.get("file_name"));
      t = t.isEmpty() ? f : f + " · " + t;
    }
    return ("1" === m.get("important") ? "❗ " : "") + t;
  }

  /** "10:42", "Yesterday" or "7 Oct". */
  static when(time) {
    const t = Chat.parse(time);
    if (t == null) return "";
    if (t.toLocalDate().equals(Dates.today())) return Chat.clock(time);
    if (t.toLocalDate().equals(Dates.today().minusDays(1))) return "Yesterday";
    return Dates.shortFmt(t.toLocalDate());
  }

  static clock(time) {
    const t = Chat.parse(time);
    if (t == null) return "";
    const h = t.getHour() % 12 === 0 ? 12 : t.getHour() % 12;
    return h + ":" + jfmt("%02d", t.getMinute()) + (t.getHour() < 12 ? " AM" : " PM");
  }

  // ---------- notifications ----------

  static channel(c) {
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null || Build.VERSION.SDK_INT < 26) return;
    const ch = new NotificationChannel(Chat.CHANNEL, "Faculty chat", NotificationManager.IMPORTANCE_HIGH);
    ch.setDescription("New messages from the faculty");
    nm.createNotificationChannel(ch);
  }

  /** After a sync, tells the person about messages that arrived from others. */
  static notifyNew(c) {
    if (!Cloud.active(c) || !Chat.canUse(c)) return;
    const db = Db.get(c);
    const p = c.getSharedPreferences("chat", Context.MODE_PRIVATE);
    const seen = p.getString("seen", "");
    const me = Chat.me(c);
    const fresh = [];
    let max = seen;
    for (const ch of Chat.chats(c, db)) {
      const read = Chat.lastRead(db, ch.get("id"), me);
      for (const m of db.rows("SELECT * FROM chat_messages WHERE chat_id=? AND sender_id<>? AND deleted='' AND time>? AND time>? ORDER BY time",
          ch.get("id"), String(me), seen, read)) {
        if (Ui.nz(m.get("time")).compareTo(max) > 0) max = m.get("time");
        if (Long.parseLong(ch.get("id")) != Chat.openChat) {
          m.put("chat_title", Chat.title(c, db, ch));
          fresh.add(m);
        }
      }
    }
    p.edit().putString("seen", max.isEmpty() ? Chat.now() : max).apply();
    if (seen.isEmpty() || fresh.isEmpty()) return; // first run: don't announce old messages
    Chat.channel(c);
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null) return;
    const last = fresh.get(fresh.size() - 1);
    let oneChat = true;
    let important = false;
    for (const m of fresh) {
      if (!m.get("chat_id").equals(last.get("chat_id"))) oneChat = false;
      if ("1" === m.get("important")) important = true;
    }
    const open = new Intent(c, oneChat ? ChatActivity : ChatListActivity);
    if (oneChat) open.putExtra("chat", last.get("chat_id"));
    open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
    const pi = PendingIntent.getActivity(c, 7100, open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const title = oneChat ? last.get("chat_title") : fresh.size() + " new messages";
    const body = new StringBuilder();
    for (let i = Math.max(0, fresh.size() - 6); i < fresh.size(); i++) {
      const m = fresh.get(i);
      if (body.length() > 0) body.append('\n');
      const group = !oneChat || db.num("SELECT COUNT(*) FROM chats WHERE id=? AND kind='direct'", m.get("chat_id")) === 0;
      body.append(group ? m.get("sender_name") + ": " : "").append(String(Chat.DUTY) === m.get("chat_id") ? "🔒 New message" : Chat.preview(m));
    }
    const bs = body.toString();
    const b = Build.VERSION.SDK_INT >= 26 ? new Notification.Builder(c, Chat.CHANNEL) : new Notification.Builder(c);
    b.setSmallIcon(R.drawable.ic_chat)
        .setContentTitle((important ? "❗ " : "") + title)
        .setContentText(bs.substring(bs.lastIndexOf("\n") + 1))
        .setStyle(new Notification.BigTextStyle().bigText(bs))
        .setShowWhen(true)
        .setColor(Chat.GREEN)
        .setNumber(fresh.size())
        .setAutoCancel(true)
        .setContentIntent(pi);
    if (Build.VERSION.SDK_INT < 26) b.setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_ALL);
    try {
      if (Notify.on(c)) nm.notify(7100, b.build());
    } catch (ignored) {
      // notifications not allowed on this phone
    }
  }
}
;
