/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One faculty chat: bubbles, ticks, replies, important messages, photos and files. */
class ChatActivity extends Base {
  constructor() {
    super();
    this.chat = null;
    this.chatId = 0;
    this.input = null;
    this.list = null;
    this.root = null;
    this.top = null;
    this.jumpBottom = true;
    this.replyBar = null;
    this.replyTo = null;
    this.important = false;
    this.onlyImportant = false;
    this.importantBtn = null;
    this.pendingCamera = null;
    this.handler = new Handler(Looper.getMainLooper());
    this.fast = {
      run: () => {
        Sync.kick(this);
        // the DAP's duty ended (7:30 AM): the Duty team chat starts empty
        if (this.chat != null && Chat.isDuty(this.chat) && E2e.purgeLocal(this) > 0) this.render();
        this.handler.postDelayed(this.fast, 5000);
      }
    };
  }

  static REQ_PHOTO = 41;
  static REQ_FILE = 42;
  static REQ_CAMERA = 43;

  onCreate(b) {
    super.onCreate(b);
    try {
      this.chatId = Long.parseLong(Ui.nz(this.getIntent().getStringExtra("chat")));
    } catch (e) {
      this.chatId = Chat.ALL;
    }
    if (b != null) this.pendingCamera = b.getString("cam");
    this.headerColor(Chat.DARK);
    if (this.chatId == Chat.DUTY) {
      // no screenshots or screen recording, and a blank preview in the recent apps list
      this.getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE, WindowManager.LayoutParams.FLAG_SECURE);
      E2e.purgeLocal(this);
      E2e.ensureKey(this, this.db);
    }
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putString("cam", this.pendingCamera);
  }

  onResume() {
    Chat.openChat = this.chatId;
    super.onResume();
    this.handler.removeCallbacks(this.fast);
    this.handler.postDelayed(this.fast, 5000);
  }

  onPause() {
    super.onPause();
    Chat.openChat = -1;
    this.handler.removeCallbacks(this.fast);
  }

  me() {
    return String(Chat.me(this));
  }

  render() {
    const db = this.db;
    this.chat = Chat.chat(db, this.chatId);
    if (this.chat == null || !Chat.canUse(this)) {
      Ui.toast(this, "This chat is not available");
      this.finish();
      return;
    }
    if (this.root == null) {
      this.root = Ui.v(this);
      this.root.setBackgroundColor(Chat.WALL);
      this.top = new FrameLayout(this);
      this.root.addView(this.top, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
      this.list = new ScrollView(this);
      this.list.setFillViewport(true);
      this.root.addView(this.list, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
      this.replyBar = Ui.v(this);
      this.root.addView(this.replyBar);
      this.root.addView(this.inputBar());
      this.setContentView(this.root);
    }
    const head = Ui.v(this);
    head.addView(this.header(), Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    if (this.onlyImportant) {
      const t = Ui.tv(this, "❗ Important messages only  ·  tap to show all", 13, Color.WHITE, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      t.setBackgroundColor(Ui.RED);
      t.setOnClickListener({ onClick: (v) => { this.onlyImportant = false; this.jumpBottom = true; this.render(); } });
      head.addView(t);
    }
    this.top.removeAllViews();
    this.top.addView(head);
    const bottom = this.jumpBottom || !this.list.canScrollVertically(1);
    this.jumpBottom = false;
    const oldY = this.list.getScrollY();
    this.list.removeAllViews();
    this.list.addView(this.messages());
    this.showReply();
    this.list.post({
      run: () => {
        if (bottom) this.list.fullScroll(View.FOCUS_DOWN);
        else this.list.scrollTo(0, oldY);
      }
    });
    Chat.markRead(this, db, this.chat);
  }

  // ---------- header ----------

  header() {
    const db = this.db;
    this.getWindow().setStatusBarColor(Chat.DARK);
    const h = Ui.h(this);
    h.setGravity(Gravity.CENTER_VERTICAL);
    h.setBackgroundColor(Chat.DARK);
    h.setPadding(Ui.dp(this, 4), Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8));
    h.setElevation(Ui.dp(this, 4));
    const back = new ImageView(this);
    back.setImageResource(R.drawable.ic_back);
    back.setColorFilter(Color.WHITE);
    const p = Ui.dp(this, 8);
    back.setPadding(p, p, p, p);
    Ui.ripple(back, 0x44FFFFFF);
    back.setOnClickListener({ onClick: (v) => { this.finish(); } });
    h.addView(back, Ui.lp(Ui.dp(this, 40), Ui.dp(this, 40)));
    h.addView(new ChatActivity.ChatListAvatar(this).make(this.chat, 40));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 6), 0);
    const tt = Ui.tv(this, Chat.title(this, db, this.chat), 17, Color.WHITE, true);
    tt.setSingleLine(true);
    tt.setEllipsize(TextUtils.TruncateAt.END);
    t.addView(tt);
    const st = Ui.tv(this, this.subtitleText(), 12, 0xD9FFFFFF, false);
    st.setSingleLine(true);
    st.setEllipsize(TextUtils.TruncateAt.END);
    t.addView(st);
    t.setOnClickListener({ onClick: (v) => { this.info(); } });
    h.addView(t, Ui.weight(1));
    const imp = Ui.tv(this, "❗", 18, Color.WHITE, true);
    imp.setPadding(Ui.dp(this, 10), Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 6));
    Ui.ripple(imp, 0x44FFFFFF);
    imp.setOnClickListener({ onClick: (v) => { this.onlyImportant = !this.onlyImportant; this.jumpBottom = true; this.render(); } });
    h.addView(imp);
    return h;
  }

  subtitleText() {
    const db = this.db;
    if (!Chat.isGroup(this.chat)) {
      const o = Chat.other(this, db, this.chat);
      return o == null ? "" : o.get("role") + (Ui.nz(o.get("unit")).isEmpty() ? "" : " · " + o.get("unit")) + "  ·  tap for info";
    }
    const sb = new StringBuilder();
    for (const id of Chat.audience(db, this.chat)) {
      const s = Chat.staff(db, id);
      if (s == null) continue;
      if (sb.length() > 0) sb.append(", ");
      sb.append(id.equals(this.me()) ? "You" : s.get("name"));
    }
    return sb.length() === 0 ? "Tap for info" : sb.toString();
  }

  // ---------- messages ----------

  messages() {
    const db = this.db;
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8));
    const duty = Chat.isDuty(this.chat);
    if (duty) box.addView(this.dutyNote());
    const ms = db.rows("SELECT * FROM chat_messages WHERE chat_id=? AND time>=?" + (this.onlyImportant ? " AND important='1' AND deleted=''" : "")
        + " ORDER BY time, id", String(this.chatId), duty ? E2e.dutyStart() : "");
    if (ms.isEmpty()) {
      const t = Ui.tv(this, this.onlyImportant ? "No important messages." : "🔒 Messages here are shared only with "
          + (Chat.isGroup(this.chat) && Ui.nz(this.chat.get("members")).isEmpty() ? "the department faculty." : "the members of this chat.") + "\nSay hello 👋", 13, 0xFF54656F, false);
      t.setGravity(Gravity.CENTER);
      t.setBackground(Ui.round(this, 0xFFFFF5C4, 10));
      t.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
      box.addView(t);
      Ui.margins(t, 24, 16, 24, 0);
      return box;
    }
    const reads = Chat.readTimes(db, String(this.chatId));
    const audience = Chat.audience(db, this.chat);
    let day = null;
    let prevSender = "";
    for (const m of ms) {
      const t = Chat.parse(m.get("time"));
      const d = t == null ? null : t.toLocalDate();
      if (d != null && !d.equals(day)) {
        day = d;
        const sep = Ui.tv(this, d.equals(Dates.today()) ? "Today" : d.equals(Dates.today().minusDays(1)) ? "Yesterday" : Dates.longFmt(d), 12, 0xFF54656F, true);
        sep.setBackground(Ui.round(this, 0xFFE1F3FB, 8));
        sep.setPadding(Ui.dp(this, 10), Ui.dp(this, 4), Ui.dp(this, 10), Ui.dp(this, 4));
        const c = Ui.h(this);
        c.setGravity(Gravity.CENTER);
        c.addView(sep);
        box.addView(c);
        Ui.margins(c, 0, 8, 0, 6);
        prevSender = "";
      }
      box.addView(this.bubble(m, !m.get("sender_id").equals(prevSender), reads, audience));
      prevSender = m.get("sender_id");
    }
    return box;
  }

  /** The Duty team rules, and how many of today's team can open locked messages. */
  dutyNote() {
    const team = Chat.dutyTeam(this.db);
    const ready = E2e.ready(this.db, team);
    let s = "🔒 End-to-end encrypted: only today's duty team can read these messages and files.\n"
        + "⏱ Everything here disappears at 7:30 AM when the DAP's duty ends.\n🚫 Screenshots are blocked.";
    if (ready < team.size()) s += "\n⚠ " + (team.size() - ready) + " of " + team.size() + " team members need to open the latest app before they can read new messages.";
    const t = Ui.tv(this, s, 12, 0xFF54656F, false);
    t.setBackground(Ui.round(this, 0xFFFFF5C4, 10));
    t.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 8));
    const lp = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 16), Ui.dp(this, 4), Ui.dp(this, 16), Ui.dp(this, 8));
    t.setLayoutParams(lp);
    return t;
  }

  bubble(m, firstOfRun, reads, audience) {
    const db = this.db;
    const mine = m.get("sender_id").equals(this.me());
    const deleted = "1" === m.get("deleted");
    const imp = "1" === m.get("important") && !deleted;
    const lc = {
      onLongClick: (v) => {
        this.menu(m);
        return true;
      }
    };
    const row = Ui.h(this);
    row.setGravity(mine ? Gravity.END : Gravity.START);
    const b = Ui.v(this);
    b.setPadding(Ui.dp(this, 9), Ui.dp(this, 6), Ui.dp(this, 9), Ui.dp(this, 5));
    const fill = mine ? Chat.BUBBLE_ME : Color.WHITE;
    b.setBackground(imp ? Ui.outline(this, fill, Ui.RED, 12) : Ui.round(this, fill, 12));
    b.setElevation(Ui.dp(this, 1));
    if (imp) {
      const il = Ui.tv(this, "❗ IMPORTANT", 11, Ui.RED, true);
      b.addView(il);
    }
    if (!mine && Chat.isGroup(this.chat) && firstOfRun) {
      const col = Bands.ink(Bands.color(Math.abs(m.get("sender_id").hashCode())));
      b.addView(Ui.tv(this, Ui.nz(m.get("sender_name")), 13, col, true));
    }
    if (deleted) {
      const t = Ui.tv(this, "🚫 This message was deleted", 14, Ui.MUTED, false);
      t.setTypeface(t.getTypeface(), Typeface.ITALIC);
      b.addView(t);
    } else {
      const rt = Ui.nz(m.get("reply_to"));
      if (!rt.isEmpty()) {
        const q = db.row("SELECT * FROM chat_messages WHERE id=?", rt);
        if (q != null) b.addView(this.quote(q));
      }
      const file = Ui.nz(m.get("file"));
      if (!file.isEmpty()) {
        const at = this.attachment(m);
        at.setOnLongClickListener(lc);
        b.addView(at);
      }
      const text = Ui.nz(m.get("text"));
      if (!text.isEmpty()) {
        const t = Ui.tv(this, text, 15, 0xFF111B21, false);
        t.setAutoLinkMask(Linkify.WEB_URLS | Linkify.PHONE_NUMBERS);
        t.setLinksClickable(true);
        t.setOnLongClickListener(lc);
        b.addView(t);
      }
    }
    const foot = Ui.h(this);
    foot.setGravity(Gravity.END | Gravity.CENTER_VERTICAL);
    foot.addView(Ui.tv(this, Chat.clock(m.get("time")), 11, 0xFF667781, false));
    if (mine && !deleted) {
      const tick = Ui.tv(this, this.ticks(m, reads, audience), 12, 0xFF667781, true);
      if (tick.getText().toString().endsWith("✓✓") && this.readByAll(m, reads, audience)) tick.setTextColor(Chat.TICK_BLUE);
      foot.addView(tick);
      Ui.margins(tick, 4, 0, 0, 0);
    }
    b.addView(foot, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    b.setOnLongClickListener(lc);
    const max = toInt(this.getResources().getDisplayMetrics().widthPixels * 0.8);
    b.setMinimumWidth(Ui.dp(this, 90));
    const lp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    row.addView(b, lp);
    b.measure(View.MeasureSpec.makeMeasureSpec(max, View.MeasureSpec.AT_MOST), View.MeasureSpec.UNSPECIFIED);
    if (b.getMeasuredWidth() >= max) lp.width = max;
    // web: the bubble is laid out later, so cap its width the way the phone's measure pass does
    b.setMaxWidth(max);
    row.setPadding(mine ? Ui.dp(this, 48) : 0, Ui.dp(this, firstOfRun ? 6 : 2), mine ? 0 : Ui.dp(this, 48), 0);
    return row;
  }

  /** ✓ waiting to go up, ✓✓ delivered to the department, blue ✓✓ read by everyone in the chat. */
  ticks(m, reads, audience) {
    if (!Cloud.active(this)) return "✓";
    if (this.db.num("SELECT COUNT(*) FROM outbox WHERE tbl='chat_messages' AND pk=?", m.get("id")) > 0) return "✓";
    return "✓✓";
  }

  readByAll(m, reads, audience) {
    let others = 0;
    for (const id of audience) {
      if (id.equals(this.me())) continue;
      others++;
      if (Ui.nz(reads.get(id)).compareTo(m.get("time")) < 0) return false;
    }
    return others > 0;
  }

  quote(q) {
    const box = Ui.h(this);
    const bar = new View(this);
    const col = q.get("sender_id").equals(this.me()) ? Chat.GREEN : Bands.ink(Bands.color(Math.abs(q.get("sender_id").hashCode())));
    bar.setBackgroundColor(col);
    box.addView(bar, new LinearLayout.LayoutParams(Ui.dp(this, 4), ViewGroup.LayoutParams.MATCH_PARENT));
    const tx = Ui.v(this);
    tx.setPadding(Ui.dp(this, 8), Ui.dp(this, 4), Ui.dp(this, 8), Ui.dp(this, 4));
    tx.addView(Ui.tv(this, q.get("sender_id").equals(this.me()) ? "You" : Ui.nz(q.get("sender_name")), 12, col, true));
    const pv = Ui.tv(this, Chat.preview(q), 13, 0xFF54656F, false);
    pv.setMaxLines(2);
    pv.setEllipsize(TextUtils.TruncateAt.END);
    tx.addView(pv);
    box.addView(tx, Ui.weight(1));
    box.setBackground(Ui.round(this, 0x14000000, 6));
    const lp = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    lp.bottomMargin = Ui.dp(this, 4);
    box.setLayoutParams(lp);
    return box;
  }

  attachment(m) {
    const rel = m.get("file");
    const f = this.db.file(rel);
    const bm = Store.isImage(rel) && f.exists() ? Ui.loadScaled(f, 700) : null;
    if (bm != null) {
      const iv = new ImageView(this);
      iv.setImageBitmap(bm);
      iv.setAdjustViewBounds(true);
      iv.setMaxHeight(Ui.dp(this, 260));
      iv.setScaleType(ImageView.ScaleType.CENTER_CROP);
      iv.setOutlineProvider({
        getOutline: (v, o) => { o.setRoundRect(0, 0, v.getWidth(), v.getHeight(), Ui.dp(this, 8)); }
      });
      iv.setClipToOutline(true);
      iv.setOnClickListener({ onClick: (v) => { Ui.showImage(this, f); } });
      const lp = Ui.lp(Ui.dp(this, 230), ViewGroup.LayoutParams.WRAP_CONTENT);
      lp.bottomMargin = Ui.dp(this, 4);
      iv.setLayoutParams(lp);
      return iv;
    }
    const chip = Ui.h(this);
    chip.setGravity(Gravity.CENTER_VERTICAL);
    chip.setPadding(Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 8));
    chip.setBackground(Ui.round(this, 0x12000000, 8));
    const kind = Ui.tv(this, Store.isImage(rel) ? "📷" : Store.kindLabel(rel), 11, Color.WHITE, true);
    kind.setGravity(Gravity.CENTER);
    kind.setBackground(Ui.round(this, Store.isImage(rel) ? Chat.GREEN : Ui.RED, 6));
    chip.addView(kind, Ui.lp(Ui.dp(this, 38), Ui.dp(this, 38)));
    const tx = Ui.v(this);
    tx.setPadding(Ui.dp(this, 8), 0, 0, 0);
    const name = Ui.nz(m.get("file_name")).isEmpty() ? (Store.isImage(rel) ? "Photo" : "File") : m.get("file_name");
    const n = Ui.tv(this, name, 14, 0xFF111B21, true);
    n.setMaxLines(2);
    tx.addView(n);
    tx.addView(Ui.tv(this, f.exists() ? Store.sizeLabel(f.length()) + " · tap to open" : "Tap to download", 11, 0xFF667781, false));
    chip.addView(tx, Ui.weight(1));
    chip.setOnClickListener({
      onClick: (v) => {
        if (f.exists()) {
          if (Store.isImage(rel)) Ui.showImage(this, f);
          else Store.openWith(this, rel);
        } else this.download(rel);
      }
    });
    const lp = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    lp.bottomMargin = Ui.dp(this, 4);
    chip.setLayoutParams(lp);
    return chip;
  }

  download(rel) {
    if (!Cloud.active(this)) {
      Ui.toast(this, "This file is not on this phone");
      return;
    }
    Ui.toast(this, "Downloading…");
    const done = (err) => {
      this.handler.post({
        run: () => {
          if (this.isFinishing()) return;
          if (err != null) Ui.toast(this, err);
          this.render();
        }
      });
    };
    // web: Sync.fetchFile returns a Promise (the phone ran it on a background thread)
    let p;
    try {
      p = Promise.resolve(Sync.fetchFile(this, this.db, rel));
    } catch (e) {
      p = Promise.reject(e);
    }
    p.then(() => done(null), (e) => done("Could not download: " + (e && e.getMessage ? e.getMessage() : e)));
  }

  // ---------- message menu ----------

  menu(m) {
    const db = this.db;
    const mine = m.get("sender_id").equals(this.me());
    const deleted = "1" === m.get("deleted");
    if (deleted) return;
    const items = [];
    items.add("Reply");
    const duty = Chat.isDuty(this.chat);
    // Duty team messages stay inside the chat: no copying or forwarding
    if (!duty && !Ui.nz(m.get("text")).isEmpty()) items.add("Copy text");
    if (!duty) items.add("Forward");
    if (mine) items.add("1" === m.get("important") ? "Remove important mark" : "Mark as important");
    if (mine) items.add("Message info");
    if (mine) items.add("Delete for everyone");
    if (!mine && Conduct.canReport(this, m.get("sender_id"))) items.add("🚩 Report to admin");
    new AlertDialog.Builder(this).setItems(items.slice(), {
      onClick: (d, w) => {
        const it = items.get(w);
        if (it.equals("Reply")) {
          this.replyTo = m;
          this.showReply();
          this.input.requestFocus();
        } else if (it.equals("Copy text")) {
          const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
          if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("message", m.get("text")));
          Ui.toast(this, "Copied");
        } else if (it.equals("Forward")) {
          this.forward(m);
        } else if (it.startsWith("Remove important") || it.startsWith("Mark as important")) {
          const cv = new ContentValues();
          cv.put("important", "1" === m.get("important") ? "" : "1");
          db.update("chat_messages", cv, Long.parseLong(m.get("id")));
          this.render();
        } else if (it.equals("🚩 Report to admin")) {
          Conduct.report(this, "chat_messages", m.get("id"), m.get("sender_id"), m.get("sender_name"), m.get("text"), m.get("file"));
        } else if (it.equals("Message info")) {
          this.messageInfo(m);
        } else if (it.equals("Delete for everyone")) {
          Ui.confirm(this, "Delete for everyone?", Chat.preview(m), "Delete", {
            run: () => {
              const cv = new ContentValues();
              cv.put("deleted", "1");
              cv.put("text", "");
              cv.put("file", "");
              cv.put("file_name", "");
              cv.put("important", "");
              db.update("chat_messages", cv, Long.parseLong(m.get("id")));
              this.render();
            }
          });
        }
      }
    }).show();
  }

  messageInfo(m) {
    const db = this.db;
    const reads = Chat.readTimes(db, String(this.chatId));
    const read = new StringBuilder(), not = new StringBuilder();
    for (const id of Chat.audience(db, this.chat)) {
      if (id.equals(this.me())) continue;
      const s = Chat.staff(db, id);
      const name = s == null ? "Member " + id : s.get("name");
      const r = Ui.nz(reads.get(id));
      if (r.compareTo(m.get("time")) >= 0) read.append("✓✓ ").append(name).append("  ·  ").append(Chat.when(r)).append('\n');
      else not.append("○ ").append(name).append('\n');
    }
    const msg = "Sent " + Chat.when(m.get("time")) + (Chat.when(m.get("time")).contains(":") ? "" : ", " + Chat.clock(m.get("time"))) + "\n\nRead by\n"
        + (read.length() === 0 ? "No one yet\n" : read.toString()) + (not.length() === 0 ? "" : "\nNot read yet\n" + not.toString());
    new AlertDialog.Builder(this).setTitle("Message info").setMessage(msg.trim()).setPositiveButton("Close", null).show();
  }

  forward(m) {
    const db = this.db;
    const chats = Chat.chats(this, db);
    const names = new Array(chats.size()).fill(null);
    for (let i = 0; i < chats.size(); i++) names[i] = Chat.title(this, db, chats.get(i));
    new AlertDialog.Builder(this).setTitle("Forward to").setItems(names, {
      onClick: (d, w) => {
        const to = chats.get(w);
        const text = Ui.nz(m.get("text"));
        Chat.send(this, db, to, "↪ Forwarded" + (text.isEmpty() ? "" : "\n" + text), m.get("file"), m.get("file_name"), null, false);
        this.open(ChatActivity, "chat", to.get("id"));
      }
    }).show();
  }

  // ---------- writing ----------

  showReply() {
    if (this.replyBar == null) return;
    this.replyBar.removeAllViews();
    if (this.replyTo == null) return;
    const r = Ui.h(this);
    r.setGravity(Gravity.CENTER_VERTICAL);
    r.setBackgroundColor(0xFFF0F2F5);
    r.setPadding(Ui.dp(this, 8), Ui.dp(this, 6), Ui.dp(this, 8), 0);
    const q = this.quote(this.replyTo);
    r.addView(q, Ui.weight(1));
    const x = Ui.tv(this, "✕", 18, Ui.MUTED, true);
    x.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 8), Ui.dp(this, 4));
    x.setOnClickListener({
      onClick: (v) => {
        this.replyTo = null;
        this.showReply();
      }
    });
    r.addView(x);
    this.replyBar.addView(r);
  }

  roundIcon(res, bg, tint, sizeDp, l) {
    const iv = new ImageView(this);
    iv.setImageResource(res);
    iv.setColorFilter(tint);
    const p = Ui.dp(this, sizeDp * 0.24);
    iv.setPadding(p, p, p, p);
    iv.setBackground(Ui.round(this, bg, sizeDp / 2));
    Ui.ripple(iv, 0x33000000);
    iv.setOnClickListener(l);
    iv.setLayoutParams(Ui.lp(Ui.dp(this, sizeDp), Ui.dp(this, sizeDp)));
    return iv;
  }

  /** Duty team files go under chat/duty, which the PGs may upload to. */
  dir() {
    return Chat.isDuty(this.chat) ? "chat/duty" : "chat";
  }

  inputBar() {
    if (!Chat.canPost(this, this.db, this.chat)) {
      const t = Ui.tv(this, "Only today's DAP and call-duty PGs can post in Duty team.", 13, 0xFF54656F, false);
      t.setGravity(Gravity.CENTER);
      t.setBackgroundColor(0xFFF0F2F5);
      t.setPadding(Ui.dp(this, 16), Ui.dp(this, 14), Ui.dp(this, 16), Ui.dp(this, 14));
      this.input = new EditText(this);
      return t;
    }
    const bar = Ui.h(this);
    bar.setGravity(Gravity.BOTTOM);
    bar.setBackgroundColor(0xFFF0F2F5);
    bar.setPadding(Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6));
    const field = Ui.h(this);
    field.setGravity(Gravity.CENTER_VERTICAL);
    field.setBackground(Ui.round(this, Color.WHITE, 22));
    field.setPadding(Ui.dp(this, 4), 0, Ui.dp(this, 4), 0);
    this.importantBtn = Ui.tv(this, "!", 17, this.important ? Color.WHITE : Ui.RED, true);
    this.importantBtn.setGravity(Gravity.CENTER);
    this.importantBtn.setBackground(Ui.round(this, this.important ? Ui.RED : Ui.alpha(Ui.RED, 0x1A), 15));
    this.importantBtn.setOnClickListener({
      onClick: (v) => {
        this.important = !this.important;
        this.importantBtn.setTextColor(this.important ? Color.WHITE : Ui.RED);
        this.importantBtn.setBackground(Ui.round(this, this.important ? Ui.RED : Ui.alpha(Ui.RED, 0x1A), 15));
        Ui.toast(this, this.important ? "Next message will be marked important" : "Normal message");
      }
    });
    field.addView(this.importantBtn, Ui.lp(Ui.dp(this, 30), Ui.dp(this, 30)));
    Ui.margins(this.importantBtn, 4, 0, 0, 0);
    this.input = new EditText(this);
    this.input.setHint("Message");
    this.input.setBackground(null);
    this.input.setTextSize(16);
    this.input.setMaxLines(5);
    this.input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
    this.input.setPadding(Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 4), Ui.dp(this, 10));
    field.addView(this.input, Ui.weight(1));
    field.addView(this.roundIcon(R.drawable.ic_attach, 0x00000000, 0xFF54656F, 38, { onClick: (v) => { this.attach(); } }));
    field.addView(this.roundIcon(R.drawable.ic_camera, 0x00000000, 0xFF54656F, 38, {
      onClick: (v) => {
        this.pendingCamera = this.dir() + "/cam_" + System.currentTimeMillis() + ".jpg";
        Store.capture(this, this.pendingCamera, ChatActivity.REQ_CAMERA);
      }
    }));
    bar.addView(field, Ui.weight(1));
    const send = this.roundIcon(R.drawable.ic_send, Chat.GREEN, Color.WHITE, 46, { onClick: (v) => { this.sendText(); } });
    bar.addView(send);
    Ui.margins(send, 6, 0, 0, 0);
    return bar;
  }

  liveRefresh() {
    return true;
  }

  sendText() {
    const text = this.input.getText().toString().trim();
    if (text.isEmpty()) return;
    Chat.send(this, this.db, this.chat, text, "", "", this.replyTo == null ? null : this.replyTo.get("id"), this.important);
    this.input.setText("");
    this.replyTo = null;
    this.important = false;
    this.jumpBottom = true;
    this.render();
  }

  attach() {
    new AlertDialog.Builder(this).setItems(["Photo from gallery", "Document (PDF, Word, Excel, PPT)"], {
      onClick: (d, w) => {
        if (w === 0) Store.pick(this, ["image/*"], ChatActivity.REQ_PHOTO);
        else Store.pick(this, ["*/*"], ChatActivity.REQ_FILE);
      }
    }).show();
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (res !== RESULT_OK) return;
    const db = this.db;
    try {
      let rel, name;
      if (req === ChatActivity.REQ_CAMERA) {
        if (this.pendingCamera == null) return;
        const f = db.file(this.pendingCamera);
        if (!f.exists() || f.length() === 0) return;
        Store.shrink(f, 2000);
        rel = this.pendingCamera;
        name = "Photo";
        this.pendingCamera = null;
      } else if ((req === ChatActivity.REQ_PHOTO || req === ChatActivity.REQ_FILE) && data != null && data.getData() != null) {
        const uri = data.getData();
        name = Store.displayName(this, uri);
        rel = Store.importUri(this, uri, this.dir(), "chat");
        if (db.file(rel).length() > Chat.MAX_FILE) {
          db.file(rel).delete();
          Ui.toast(this, "Files up to 20 MB can be sent");
          return;
        }
      } else return;
      this.caption(rel, name);
    } catch (e) {
      Ui.toast(this, "Could not attach: " + (e && e.getMessage ? e.getMessage() : e));
    }
  }

  /** Asks for an optional caption, then sends the photo or file. */
  caption(rel, name) {
    const db = this.db;
    const f = new Form(this);
    if (Store.isImage(rel)) {
      const iv = new ImageView(this);
      iv.setImageBitmap(Ui.loadScaled(db.file(rel), 600));
      iv.setAdjustViewBounds(true);
      iv.setMaxHeight(Ui.dp(this, 220));
      f.view.addView(iv);
    } else f.view.addView(Ui.body(this, "📎 " + name + "  ·  " + Store.sizeLabel(db.file(rel).length())));
    f.text("caption", "Add a caption", this.input.getText().toString().trim(), Form.PLAIN);
    f.check("important", "Mark as important", this.important);
    Ui.formDialog(this, "Send to " + Chat.title(this, db, this.chat), f, "Send", {
      run: () => {
        Chat.send(this, db, this.chat, f.get("caption"), rel, Store.isImage(rel) ? "" : name,
            this.replyTo == null ? null : this.replyTo.get("id"), "1" === f.get("important"));
        this.input.setText("");
        this.replyTo = null;
        this.important = false;
        this.jumpBottom = true;
        this.render();
        return true;
      }
    });
  }

  // ---------- chat info ----------

  info() {
    const db = this.db;
    const v = Ui.v(this);
    v.setPadding(Ui.dp(this, 20), Ui.dp(this, 8), Ui.dp(this, 20), 0);
    const msgs = db.num("SELECT COUNT(*) FROM chat_messages WHERE chat_id=? AND deleted=''", String(this.chatId));
    const imp = db.num("SELECT COUNT(*) FROM chat_messages WHERE chat_id=? AND important='1' AND deleted=''", String(this.chatId));
    const files = db.num("SELECT COUNT(*) FROM chat_messages WHERE chat_id=? AND file<>'' AND deleted=''", String(this.chatId));
    v.addView(Ui.muted(this, msgs + " messages  ·  " + imp + " important  ·  " + files + " photos and files"));
    const h = Ui.tv(this, Chat.isGroup(this.chat) ? "Members" : "Contact", 14, Chat.DARK, true);
    h.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 4));
    v.addView(h);
    for (const id of Chat.audience(db, this.chat)) {
      const s = Chat.staff(db, id);
      if (s == null) continue;
      const r = Ui.h(this);
      r.setGravity(Gravity.CENTER_VERTICAL);
      r.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
      r.addView(Store.avatar(this, s, 36, Bands.color(Math.abs(id.hashCode()))));
      const tx = Ui.v(this);
      tx.setPadding(Ui.dp(this, 10), 0, 0, 0);
      tx.addView(Ui.tv(this, s.get("name") + (id.equals(this.me()) ? " (you)" : ""), 14, Ui.TEXT, true));
      tx.addView(Ui.muted(this, s.get("role") + (Ui.nz(s.get("phone")).isEmpty() ? "" : " · " + s.get("phone"))));
      r.addView(tx, Ui.weight(1));
      if (!Ui.nz(s.get("phone")).isEmpty() && !id.equals(this.me())) {
        const phone = s.get("phone");
        const call = this.roundIcon(R.drawable.ic_phone, Ui.alpha(Chat.GREEN, 0x22), Chat.GREEN, 34, {
          onClick: (vv) => {
            try {
              this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + phone)));
            } catch (e) {
              Ui.toast(this, "No phone app");
            }
          }
        });
        r.addView(call);
      }
      v.addView(r);
    }
    const b = new AlertDialog.Builder(this).setTitle(Chat.title(this, db, this.chat)).setView(Ui.scroll(this, v))
        .setNegativeButton("Close", null);
    const canEdit = "group" === this.chat.get("kind") && (this.chat.get("created_by").equals(this.me()) || !Cloud.active(this) || Cloud.isAdmin(this));
    if (canEdit) b.setPositiveButton("Edit group", {
      onClick: (d, w) => {
        ChatListActivity.groupDialog(this, this.chat, { run: () => { this.render(); } });
      }
    });
    b.show();
  }
}

/** Avatar for the header, the same as in the chat list. */
ChatActivity.ChatListAvatar = class {
  constructor(outer) { this.outer = outer; }

  make(ch, sizeDp) {
    const a = this.outer;
    if (!Chat.isGroup(ch)) {
      const o = Chat.other(a, a.db, ch);
      if (o != null) return Store.avatar(a, o, sizeDp, Bands.color(Math.abs(o.get("id").hashCode())));
    }
    const iv = new ImageView(a);
    const duty = Chat.isDuty(ch);
    iv.setImageResource(Chat.ALL == Long.parseLong(ch.get("id")) ? R.drawable.ic_chat : duty ? R.drawable.ic_shield : R.drawable.ic_group);
    iv.setColorFilter(Color.WHITE);
    const p = Ui.dp(a, sizeDp / 4.5);
    iv.setPadding(p, p, p, p);
    iv.setBackground(Ui.gradient(a, duty ? [0xFF2563EB, 0xFF1E3A8A] : [Chat.GREEN, 0xFF064E3B], sizeDp / 2));
    iv.setLayoutParams(Ui.lp(Ui.dp(a, sizeDp), Ui.dp(a, sizeDp)));
    return iv;
  }
};
;
