'use strict';
/** Faculty chat: the list of chats, newest first, with unread counts. */
class ChatListActivity extends Base {

  onCreate(b) {
    super.onCreate(b);
    // the list shows Duty team previews, so it is kept out of screenshots too
    if (!Chat.isHod(this, this.db) && Chat.inDuty(this, this.db))
      this.getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE, WindowManager.LayoutParams.FLAG_SECURE);
    this.setTitle(Chat.faculty(this) ? "Faculty chat" : "Duty team chat");
    this.subtitle = Chat.faculty(this) ? "Faculty chats and today's duty team" : "Today's DAP and call-duty PGs";
    this.headerColor(Chat.DARK);
    if (Chat.faculty(this)) this.headerAction("+ New", { onClick: (v) => { this.newChat(); } });
  }

  render() {
    const db = this.db;
    E2e.purgeLocal(this);
    const page = Ui.v(this);
    if (!Chat.canUse(this)) {
      page.addView(this.emptyNote("Chat is for the faculty, and for today's DAP and call-duty PGs in the Duty team group."));
      this.setPage(page);
      return;
    }
    const chats = Chat.chats(this, db);
    for (const ch of chats) {
      const last = db.row("SELECT * FROM chat_messages WHERE chat_id=? ORDER BY time DESC, id DESC LIMIT 1", ch.get("id"));
      ch.put("_last", last == null ? Ui.nz(ch.get("created_on")) : last.get("time"));
      ch.put("_preview", last == null ? "" : (last.get("sender_id").equals(String(Chat.me(this))) ? "You: "
          : Chat.isGroup(ch) ? ChatListActivity.first(last.get("sender_name")) + ": " : "") + Chat.preview(last));
    }
    const pinned = [];
    for (const ch of chats) if (Chat.ALL == Long.parseLong(ch.get("id")) || Chat.isDuty(ch)) pinned.add(ch);
    chats.removeAll(pinned);
    Collections.sort(chats, {
      compare: (a, b) => b.get("_last").compareTo(a.get("_last"))
    });
    chats.addAll(0, pinned); // All faculty, then Duty team, stay on top
    const list = Ui.card(this);
    list.setPadding(0, Ui.dp(this, 4), 0, Ui.dp(this, 4));
    for (let i = 0; i < chats.size(); i++) {
      if (i > 0) list.addView(Ui.divider(this));
      list.addView(this.row(chats.get(i)));
    }
    page.addView(list);
    if (chats.size() === pinned.size() && Chat.faculty(this)) page.addView(this.emptyNote("Tap + New to message one faculty member or to make a group."));
    const note = Ui.muted(this, "Messages are shared only with the people in each chat. Duty team is today's DAP and call-duty PGs (from the call duty desk), without the HOD; it changes every admission day at 7:30 AM. Messages arrive while the app is open or syncing; there are no alerts when the app is closed.");
    note.setPadding(Ui.dp(this, 20), Ui.dp(this, 10), Ui.dp(this, 20), 0);
    page.addView(note);
    this.setPage(page);
  }

  /** "Dr. A. Kumar" -> "Kumar": the first word that isn't a title or an initial. */
  static first(name) {
    for (const w of Ui.nz(name).jsplit("[\\s]+")) {
      const bare = w.split(".").join("");
      if (bare.length > 2 && !bare.equalsIgnoreCase("prof")) return w;
    }
    return Ui.nz(name).trim();
  }

  /** Group picture: green circle with the group's initials or a people icon. */
  avatar(ch, sizeDp) {
    if (!Chat.isGroup(ch)) {
      const o = Chat.other(this, this.db, ch);
      if (o != null) return Store.avatar(this, o, sizeDp, Bands.color(Math.abs(o.get("id").hashCode())));
    }
    const iv = new ImageView(this);
    const duty = Chat.isDuty(ch);
    iv.setImageResource(Chat.ALL == Long.parseLong(ch.get("id")) ? R.drawable.ic_chat : duty ? R.drawable.ic_shield : R.drawable.ic_group);
    iv.setColorFilter(Color.WHITE);
    const p = Ui.dp(this, sizeDp / 4.5);
    iv.setPadding(p, p, p, p);
    iv.setBackground(Ui.gradient(this, duty ? [0xFF2563EB, 0xFF1E3A8A] : [Chat.GREEN, Chat.DARK], sizeDp / 2));
    iv.setLayoutParams(Ui.lp(Ui.dp(this, sizeDp), Ui.dp(this, sizeDp)));
    return iv;
  }

  row(ch) {
    const db = this.db;
    const r = Ui.h(this);
    r.setGravity(Gravity.CENTER_VERTICAL);
    r.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
    const av = this.avatar(ch, 50);
    r.addView(av);
    const mid = Ui.v(this);
    mid.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    const t = Ui.tv(this, Chat.title(this, db, ch), 16, Ui.TEXT, true);
    t.setSingleLine(true);
    t.setEllipsize(TextUtils.TruncateAt.END);
    mid.addView(t);
    const pv = ch.get("_preview");
    const p = Ui.tv(this, pv.isEmpty() ? (Chat.ALL == Long.parseLong(ch.get("id")) ? "Every faculty member" : Chat.isDuty(ch) ? "Today's DAP and call-duty PGs" : "No messages yet") : pv, 13, Ui.MUTED, false);
    p.setSingleLine(true);
    p.setEllipsize(TextUtils.TruncateAt.END);
    mid.addView(p);
    r.addView(mid, Ui.weight(1));
    const right = Ui.v(this);
    right.setGravity(Gravity.END);
    const unread = Chat.unread(this, db, ch.get("id"));
    const w = Ui.tv(this, Chat.when(ch.get("_last")), 11, unread > 0 ? Chat.GREEN : Ui.MUTED, unread > 0);
    right.addView(w);
    if (unread > 0) {
      const u = Ui.tv(this, unread > 99 ? "99+" : String(unread), 11, Color.WHITE, true);
      u.setGravity(Gravity.CENTER);
      u.setMinWidth(Ui.dp(this, 22));
      u.setPadding(Ui.dp(this, 6), Ui.dp(this, 2), Ui.dp(this, 6), Ui.dp(this, 2));
      u.setBackground(Ui.round(this, 0xFF25D366, 11));
      right.addView(u);
      Ui.margins(u, 0, 4, 0, 0);
    }
    r.addView(right);
    Ui.ripple(r, Ui.alpha(Chat.GREEN, 0x1A));
    r.setOnClickListener(this.opener(ChatActivity, "chat", ch.get("id")));
    return r;
  }

  newChat() {
    new AlertDialog.Builder(this).setTitle("New")
        .setItems(["Message one faculty member", "New group"], {
          onClick: (d, w) => {
            if (w === 0) this.pickPerson();
            else ChatListActivity.groupDialog(this, null, null);
          }
        }).show();
  }

  static others(a) {
    const out = [];
    const me = String(Chat.me(a));
    for (const s of Chat.faculty(a.db)) if (!s.get("id").equals(me)) out.add(s);
    return out;
  }

  pickPerson() {
    const people = ChatListActivity.others(this);
    if (people.isEmpty()) {
      Ui.toast(this, "Add faculty in the Faculty section first");
      return;
    }
    const box = Ui.v(this);
    const dlg = [null];
    for (const s of people) {
      const r = Ui.h(this);
      r.setGravity(Gravity.CENTER_VERTICAL);
      r.setPadding(Ui.dp(this, 18), Ui.dp(this, 8), Ui.dp(this, 18), Ui.dp(this, 8));
      r.addView(Store.avatar(this, s, 40, Bands.color(Math.abs(s.get("id").hashCode()))));
      const tx = Ui.v(this);
      tx.setPadding(Ui.dp(this, 12), 0, 0, 0);
      tx.addView(Ui.tv(this, s.get("name"), 15, Ui.TEXT, true));
      tx.addView(Ui.muted(this, s.get("role") + (Ui.nz(s.get("unit")).isEmpty() ? "" : " · " + s.get("unit"))));
      r.addView(tx, Ui.weight(1));
      Ui.ripple(r, Ui.alpha(Chat.GREEN, 0x1A));
      r.setOnClickListener({
        onClick: (v) => {
          if (dlg[0] != null) dlg[0].dismiss();
          this.open(ChatActivity, "chat", String(this.direct(s.get("id"))));
        }
      });
      box.addView(r);
    }
    dlg[0] = new AlertDialog.Builder(this).setTitle("Message").setView(Ui.scroll(this, box)).setNegativeButton("Cancel", null).show();
  }

  /** The direct chat with this person, made if there isn't one. */
  direct(otherId) {
    const db = this.db;
    const me = Chat.me(this);
    const a = "," + me + "," + otherId + ",", b = "," + otherId + "," + me + ",";
    const r = db.row("SELECT id FROM chats WHERE kind='direct' AND (members=? OR members=?)", a, b);
    if (r != null) return Long.parseLong(r.get("id"));
    const cv = new ContentValues();
    cv.put("kind", "direct");
    cv.put("name", "");
    cv.put("members", a);
    cv.put("created_by", me);
    cv.put("created_on", Chat.now());
    return db.insert("chats", cv);
  }

  /** Make a group, or (with a chat) rename it and change its members. */
  static groupDialog(a, group, done) {
    const f = new Form(a);
    f.text("name", "Group name *", group == null ? "" : group.get("name"), Form.PLAIN);
    f.heading("Members");
    const people = ChatListActivity.others(a);
    const boxes = [];
    const cur = group == null ? "" : Ui.nz(group.get("members"));
    for (const s of people) boxes.add(f.check("m" + s.get("id"), s.get("name"), cur.contains("," + s.get("id") + ",")));
    Ui.formDialog(a, group == null ? "New group" : "Group", f, "Save", {
      run: () => {
        if (!f.require("name", "Give the group a name")) return false;
        const ids = [];
        ids.add(Chat.me(a));
        for (let i = 0; i < people.size(); i++) if (boxes.get(i).isChecked()) ids.add(Long.parseLong(people.get(i).get("id")));
        if (ids.size() < 2) {
          Ui.toast(a, "Choose at least one member");
          return false;
        }
        const cv = new ContentValues();
        cv.put("kind", "group");
        cv.put("name", f.get("name"));
        cv.put("members", Chat.members(ids));
        if (group == null) {
          cv.put("created_by", Chat.me(a));
          cv.put("created_on", Chat.now());
          const id = a.db.insert("chats", cv);
          a.open(ChatActivity, "chat", String(id));
        } else {
          a.db.update("chats", cv, Long.parseLong(group.get("id")));
          if (done != null) run(done);
        }
        return true;
      }
    });
  }
}
;
