/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Attendance for one Physicon / journal club session: the organiser shows the changing code, everyone else enters it;
 * the list of who is present (with time) and who has not checked in.
 */
class CheckinActivity extends Base {
  constructor() {
    super();
    this.sid = null;
    this.codeView = null;
    this.countdown = null;
    this.bleView = null;
    // (named tickHandler / every so they do not clash with Base's own private ticker fields)
    this.tickHandler = new Handler(Looper.getMainLooper());
    this.every = {
      run: () => {
        this.showCode();
        this.tickHandler.postDelayed(this.every, 1000);
      }
    };
  }

  onCreate(b) {
    super.onCreate(b);
    this.sid = this.getIntent().getStringExtra("id");
    this.setTitle("Attendance");
    this.headerColor(Ui.PURPLE);
  }

  onResume() {
    super.onResume();
    this.tickHandler.removeCallbacks(this.every);
    this.tickHandler.post(this.every);
  }

  onPause() {
    super.onPause();
    this.tickHandler.removeCallbacks(this.every);
    Beacon.stopAdvertising(this);
  }

  session() {
    return this.db.row("SELECT * FROM academics WHERE id=?", Ui.nz(this.sid));
  }

  render() {
    const s = this.session();
    const page = Ui.v(this);
    this.codeView = null;
    this.countdown = null;
    this.bleView = null;
    if (s == null) {
      page.addView(this.emptyNote("This session was removed."));
      this.setPage(page);
      return;
    }
    const kind = Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, s.get("kind"));
    this.subtitle = kind + " · " + Dates.nice(s.get("date"));
    const open = SessionAttendance.isOpen(s);
    const runner = SessionAttendance.canRun(this);
    const present = SessionAttendance.present(this.db, this.sid);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Ui.PURPLE), 20));
    hero.addView(Ui.tv(this, Ui.nz(s.get("topic")).isEmpty() ? kind : s.get("topic"), 18, 0xFFFFFFFF, true));
    hero.addView(Ui.tv(this, present.size() + " present" + (open ? "  ·  attendance open" : "  ·  attendance closed"), 13, 0xE6FFFFFF, false));
    if (open && runner) {
      hero.addView(Ui.tv(this, "Show this code on the screen. Everyone enters it in the app on their own phone.", 13, 0xE6FFFFFF, false));
      this.codeView = Ui.tv(this, "", 64, 0xFFFFFFFF, true);
      this.codeView.setGravity(Gravity.CENTER);
      this.codeView.setLetterSpacing(0.25);
      hero.addView(this.codeView);
      this.countdown = Ui.tv(this, "", 13, 0xE6FFFFFF, false);
      this.countdown.setGravity(Gravity.CENTER);
      hero.addView(this.countdown);
      this.bleView = Ui.tv(this, "", 13, 0xFFFFFFFF, true);
      this.bleView.setGravity(Gravity.CENTER);
      hero.addView(this.bleView);
      Ui.margins(this.bleView, 0, 6, 0, 0);
      if (!Beacon.allowed(this) && Beacon.supported()) {
        const allow = Ui.button(this, "Allow Bluetooth for automatic check-in", Ui.AMBER, {
          onClick: (v) => { Beacon.ask(this); }
        });
        hero.addView(allow);
        Ui.margins(allow, 0, 8, 0, 0);
      }
      this.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
      this.showCode();
    }
    const btns = [];
    if (open) {
      const me = SessionAttendance.me(this, this.db);
      if (!runner && !Beacon.allowed(this) && Beacon.supported() && !Reminders.prefs(this).getBoolean("ble_asked_" + this.sid, false)) {
        Reminders.prefs(this).edit().putBoolean("ble_asked_" + this.sid, true).apply();
        Beacon.ask(this);
      }
      if (me == null || !SessionAttendance.isPresent(this.db, this.sid, me)) {
        btns.add(Ui.button(this, "Enter code", Ui.GREEN, {
          onClick: (v) => { this.enterCode(); }
        }));
      } else {
        hero.addView(Ui.tv(this, "You are marked present.", 14, 0xFFFFFFFF, true));
      }
    }
    if (runner) {
      btns.add(Ui.button(this, open ? "Stop attendance" : (Ui.nz(s.get("att_secret")).isEmpty() ? "Start attendance" : "Open again"),
        open ? Ui.RED : Ui.GREEN, {
          onClick: (v) => {
            if (open) {
              SessionAttendance.stop(this.db, Long.parseLong(this.sid));
              Beacon.stopAdvertising(this);
              this.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
            } else {
              SessionAttendance.start(this.db, this, Long.parseLong(this.sid));
              if (Beacon.supported()) Beacon.ask(this);
            }
            this.render();
          }
        }));
    }
    if (!btns.isEmpty()) {
      const row = Ui.buttonRow(this, btns);
      hero.addView(row);
      Ui.margins(row, 0, 12, 0, 0);
    }
    page.addView(hero);

    page.addView(Ui.heading(this, "Present (" + present.size() + ")", Ui.GREEN));
    const pc = Ui.card(this);
    if (present.isEmpty()) pc.addView(Ui.muted(this, "No one has checked in yet."));
    for (const p of present) {
      let t = Ui.nz(p.get("time"));
      t = t.length >= 16 ? t.substring(11, 16) : t;
      const how = "code" === p.get("method") ? "" : "manual" === p.get("method") ? "  (added by " + p.get("by_name") + ")" : "  (" + p.get("method") + ")";
      pc.addView(Ui.kv(this, p.get("name") + "  ·  " + CheckinActivity.label(p.get("role")), t + how));
    }
    page.addView(pc);
    if (runner) {
      const row = Ui.buttonRow(this,
        Ui.outlineButton(this, "Add by name", Ui.PURPLE, {
          onClick: (v) => { this.addByName(); }
        }),
        Ui.outlineButton(this, "Share list", Ui.PURPLE, {
          onClick: (v) => { this.share(s, present); }
        }));
      page.addView(row);
      Ui.margins(row, 12, 8, 12, 0);
    }

    const absent = SessionAttendance.absent(this.db, this.sid);
    if (!absent.isEmpty()) {
      page.addView(Ui.heading(this, "Not checked in (" + absent.size() + ")", Ui.SLATE));
      const ac = Ui.card(this);
      for (const a of absent) ac.addView(Ui.kv(this, a.get("name"), CheckinActivity.label(a.get("role"))));
      page.addView(ac);
    }
    this.setPage(page);
  }

  static label(role) {
    return "Postgraduate" === role ? "PG" : Ui.nz(role);
  }

  showCode() {
    if (this.codeView == null) return;
    const s = this.session();
    if (s == null || !SessionAttendance.isOpen(s)) return;
    const now = System.currentTimeMillis();
    this.codeView.setText(SessionAttendance.codeNow(s, now));
    Beacon.advertise(this, s);
    this.bleView.setText(Beacon.advertising() && Beacon.adError.isEmpty() ? "Bluetooth signal on: phones in the hall check in by themselves"
      : (Beacon.adError.isEmpty() ? "Starting the Bluetooth signal…" : Beacon.adError + ". The code still works."));
    this.countdown.setText("Changes in " + SessionAttendance.secondsLeft(now) + " s  ·  " + SessionAttendance.count(this.db, this.sid) + " present");
  }

  enterCode() {
    const me = SessionAttendance.me(this, this.db);
    const f = new Form(this);
    if (me == null) f.suggest("name", "Your name (as in the faculty / student list)", "", this.db.staffNames(""));
    const e = f.text("code", "4-digit code shown in the hall", "", InputType.TYPE_CLASS_NUMBER);
    e.setTextSize(28);
    Ui.formDialog(this, "Check in", f, "Check in", {
      run: () => {
        const s = this.session();
        if (s == null || !SessionAttendance.isOpen(s)) {
          Ui.toast(this, "Attendance is closed for this session");
          return true;
        }
        let who = me;
        if (who == null) {
          who = this.db.row("SELECT * FROM staff WHERE name=? AND " + Approvals.APPROVED_SQL + " LIMIT 1", f.get("name"));
          if (who == null) {
            Ui.toast(this, "Choose your name from the list");
            return false;
          }
          Reminders.prefs(this).edit().putString("name", who.get("name")).apply();
        }
        if (!SessionAttendance.check(s, f.get("code"), System.currentTimeMillis())) {
          Ui.toast(this, "That code is not right or has expired. Enter the code on the screen now.");
          return false;
        }
        const added = SessionAttendance.mark(this.db, this, this.sid, who, "code");
        Ui.toast(this, added ? "Marked present" : "You were already marked present");
        this.render();
        return true;
      }
    });
  }

  addByName() {
    const f = new Form(this);
    f.suggest("name", "Name", "", this.db.staffNames(""));
    Ui.formDialog(this, "Mark present", f, "Mark present", {
      run: () => {
        const who = this.db.row("SELECT * FROM staff WHERE name=? AND " + Approvals.APPROVED_SQL + " LIMIT 1", f.get("name"));
        if (who == null) {
          Ui.toast(this, "Choose a name from the list");
          return false;
        }
        SessionAttendance.mark(this.db, this, this.sid, who, "manual");
        this.render();
        return true;
      }
    });
  }

  share(s, present) {
    const sb = new StringBuilder();
    sb.append(Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, s.get("kind"))).append(" · ").append(Dates.nice(s.get("date"))).append('\n');
    if (!Ui.nz(s.get("topic")).isEmpty()) sb.append(s.get("topic")).append('\n');
    sb.append("Present: ").append(present.size()).append("\n\n");
    let i = 1;
    for (const p of present) {
      const t = Ui.nz(p.get("time"));
      sb.append(i++).append(". ").append(p.get("name")).append(" (").append(CheckinActivity.label(p.get("role"))).append(")")
        .append(t.length >= 16 ? " " + t.substring(11, 16) : "").append('\n');
    }
    const i2 = new Intent(Intent.ACTION_SEND);
    i2.setType("text/plain");
    i2.putExtra(Intent.EXTRA_TEXT, sb.toString());
    this.startActivity(Intent.createChooser(i2, "Share attendance"));
  }
}
;
/* ---- app/ClinicalAudit.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Clinical audit (7.87). Two parts:
 * 1. Census analysis, worked out on the phone: admissions, outcomes, mortality, LAMA, length of stay, ICU transfers and
 *    the change from the period before, per unit; and red flags (early deaths, long stays, no final diagnosis, no case
 *    sheet, stroke in the window not thrombolysed, snake bite without ASV recorded).
 * 2. AI review: the chosen cases, with name, IP number, phone and address removed, go to Claude or Gemini (the key in
 *    Settings) or to a free AI app, which audits the diagnosis and management against current guidelines.
 * Run on demand by the HOD, the registrar, the admin and the faculty. Saved audits are kept (table audits) for the meeting.
 */
class ClinicalAudit {
  constructor() {}

  static TABLE = "audits";
  static COLOR = 0xFF9F1239;
  static HERO = [0xFFE11D48, 0xFF9F1239, 0xFF4C0519];
  static ALL = "ALL";
  static PERIODS = ["Yesterday", "This week", "Last week", "This month", "Last month"];
  static CASE_SETS = ["Deaths", "Deaths and red-flag cases", "All discharges and deaths"];
  static MAX_CASES = 20;

  /** Faculty of any rank, the HOD, the registrar and the admin. */
  static canUse(c) {
    if (!Cloud.active(c)) return true;
    const r = Cloud.role(c);
    return Cloud.isManager(r) || "professor" === r || "faculty" === r;
  }

  /** {from, to} for a period name, inclusive, by admission day (7:30 AM to 7:30 AM). */
  static range(period) {
    const d = Dates.admitDay();
    switch (period) {
      case "Yesterday": return [d.minusDays(1), d.minusDays(1)];
      case "This week": return [d.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)), d];
      case "Last week": {
        const m = d.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)).minusWeeks(1);
        return [m, m.plusDays(6)];
      }
      case "Last month": {
        const m = d.withDayOfMonth(1).minusMonths(1);
        return [m, m.withDayOfMonth(m.lengthOfMonth())];
      }
      default: return [d.withDayOfMonth(1), d];
    }
  }

  /** The same length of time just before. */
  static before(r) {
    const days = ChronoUnit.DAYS.between(r[0], r[1]) + 1;
    return [r[0].minusDays(days), r[0].minusDays(1)];
  }

  static label(r) {
    return r[0].equals(r[1]) ? Dates.nice(r[0].toString()) : Dates.nice(r[0].toString()) + " to " + Dates.nice(r[1].toString());
  }

  // ---------- numbers ----------

  static unitSql(unit) {
    return ClinicalAudit.ALL === unit ? "" : " AND p.home_unit='" + unit.split("'").join("") + "'";
  }

  static stats(db, unit, r) {
    const a = r[0].toString(), b = r[1].toString(), u = ClinicalAudit.unitSql(unit);
    const s = new ClinicalAudit.Stats();
    const ev = "SELECT COUNT(*) FROM events e JOIN patients p ON p.id=e.patient_id WHERE e.type=? AND e.date BETWEEN ? AND ?" + u;
    s.admissions = db.num(ev, Db.ADMIT, a, b);
    s.discharges = db.num(ev, Db.DISCHARGE, a, b);
    s.deaths = db.num(ev, Db.DEATH, a, b);
    s.lama = db.num(ev + " AND e.note LIKE 'Against medical advice%'", Db.DISCHARGE, a, b);
    s.absconded = db.num(ev + " AND e.note LIKE 'Absconded%'", Db.DISCHARGE, a, b);
    s.referred = db.num(ev + " AND (e.note LIKE 'Referred%' OR e.note LIKE '" + Db.BACK_TO + "%')", Db.DISCHARGE, a, b);
    s.toImcu = db.num(ev + " AND e.to_loc=?", Db.TRANSFER, a, b, Db.IMCU);
    s.toCcb = db.num(ev + " AND e.to_loc=?", Db.TRANSFER, a, b, Db.CCB);
    s.inNow = db.num("SELECT COUNT(*) FROM patients p WHERE p.status=?" + u, Db.IN);
    let sum = 0;
    let n = 0;
    for (const p of db.rows("SELECT p.admit_date, p.outcome_date FROM patients p WHERE p.status<>? AND p.outcome_date BETWEEN ? AND ?" + u, Db.IN, a, b)) {
      const x = Dates.parse(p.get("admit_date")), y = Dates.parse(p.get("outcome_date"));
      if (x == null || y == null) continue;
      sum += Math.max(0, ChronoUnit.DAYS.between(x, y));
      n++;
    }
    s.alos = n === 0 ? 0 : sum / n;
    return s;
  }

  /** "▲ 12%" style change against the period before. */
  static change(now, before) {
    if (before === 0) return now === 0 ? "" : "new";
    const pc = Math.round((now - before) * 100.0 / before);
    return pc === 0 ? "same" : (pc > 0 ? "▲ " : "▼ ") + Math.abs(pc) + "%";
  }

  // ---------- red flags ----------

  static F_EARLY = "Death within 24 h of admission";
  static F_LONG = "In hospital over 14 days";
  static F_NODX = "No final diagnosis";
  static F_NOCS = "Case sheet not written";
  static F_STROKE = "Stroke in window, not thrombolysed";
  static F_ASV = "Snake bite: ASV not recorded";
  static F_LAMA = "Left against advice / absconded";
  static F_NOCAUSE = "Death: cause not recorded";

  static who(p) {
    return Ui.nz(p.get("name")) + (Ui.nz(p.get("age")).isEmpty() ? "" : ", " + p.get("age") + "/" + Ui.nz(p.get("sex")))
      + "  ·  " + Ui.nz(p.get("home_unit")) + (Ui.nz(p.get("ip_no")).isEmpty() ? "" : "  ·  IP " + p.get("ip_no"));
  }

  static flags(db, unit, r) {
    const A = ClinicalAudit, Flag = ClinicalAudit.Flag, who = ClinicalAudit.who;
    const a = r[0].toString(), b = r[1].toString(), u = A.unitSql(unit);
    const out = [];
    // outcomes in the period
    for (const p of db.rows("SELECT p.* FROM patients p WHERE p.status<>? AND p.outcome_date BETWEEN ? AND ?" + u + " ORDER BY p.outcome_date", Db.IN, a, b)) {
      const id = p.get("id");
      const died = Db.DIED === p.get("status");
      const x = Dates.parse(p.get("admit_date")), y = Dates.parse(p.get("outcome_date"));
      if (died && x != null && y != null && ChronoUnit.DAYS.between(x, y) <= 1) out.add(new Flag(A.F_EARLY, id, who(p) + "  ·  died " + Dates.nice(p.get("outcome_date"))));
      if (died && Ui.nz(p.get("outcome_note")).trim().isEmpty()) out.add(new Flag(A.F_NOCAUSE, id, who(p)));
      const cs = CaseSheet.load(db, Long.parseLong(id));
      if (CaseSheet.s(cs, "final_dx").trim().isEmpty() && !Ui.nz(p.get("outcome_note")).contains("Final diagnosis:"))
        out.add(new Flag(A.F_NODX, id, who(p) + "  ·  " + (died ? "died" : "discharged") + " " + Dates.nice(p.get("outcome_date"))));
      const note = Ui.nz(p.get("outcome_note"));
      if (note.startsWith("Against medical advice") || note.startsWith("Absconded")) out.add(new Flag(A.F_LAMA, id, who(p) + "  ·  " + note.jsplit("\\.")[0]));
    }
    // everyone admitted in the period
    for (const p of db.rows("SELECT p.* FROM patients p WHERE p.admit_date BETWEEN ? AND ?" + u + " ORDER BY p.admit_date", a, b)) {
      const id = p.get("id");
      const x = Dates.parse(p.get("admit_date"));
      const overDay = x != null && x.isBefore(Dates.today());
      if (overDay && Ui.nz(p.get("cs_by")).isEmpty() && db.num("SELECT COUNT(*) FROM case_sheets WHERE id=?", id) === 0)
        out.add(new Flag(A.F_NOCS, id, who(p) + "  ·  admitted " + Dates.nice(p.get("admit_date"))));
      if ("Within 4.5 h" === p.get("st_window") && "Haemorrhagic" !== p.get("st_type") && "Yes" !== p.get("st_lysis"))
        out.add(new Flag(A.F_STROKE, id, who(p) + "  ·  " + Ui.nz(p.get("diagnosis"))));
      if ("Snake bite" === p.get("tox_kind") && Ui.toInt(p.get("sb_asv"), 0) === 0)
        out.add(new Flag(A.F_ASV, id, who(p) + "  ·  " + Ui.nz(p.get("sb_snake"))));
    }
    // still in hospital after 14 days
    for (const p of db.rows("SELECT p.* FROM patients p WHERE p.status=? AND p.admit_date<=?" + u + " ORDER BY p.admit_date", Db.IN, Dates.today().minusDays(14).toString()))
      out.add(new Flag(A.F_LONG, p.get("id"), who(p) + "  ·  since " + Dates.nice(p.get("admit_date")) + "  ·  " + Db.shortName(p.get("location"))));
    return out;
  }

  // ---------- the AI review ----------

  /** The patients to review: deaths, deaths and flagged cases, or every outcome, newest first, at most MAX_CASES. */
  static cases(db, unit, r, set) {
    const A = ClinicalAudit;
    const a = r[0].toString(), b = r[1].toString(), u = A.unitSql(unit);
    const out = [];
    const ids = new JSet();
    for (const p of db.rows("SELECT p.* FROM patients p WHERE p.status=? AND p.outcome_date BETWEEN ? AND ?" + u + " ORDER BY p.outcome_date DESC", Db.DIED, a, b))
      if (ids.add(p.get("id"))) out.add(p);
    if (A.CASE_SETS[0] !== set) {
      if (A.CASE_SETS[1] === set) {
        for (const f of A.flags(db, unit, r)) {
          if (ids.contains(f.pid)) continue;
          const p = db.row("SELECT * FROM patients WHERE id=?", f.pid);
          if (p != null && ids.add(f.pid)) out.add(p);
        }
      } else {
        for (const p of db.rows("SELECT p.* FROM patients p WHERE p.status=? AND p.outcome_date BETWEEN ? AND ?" + u + " ORDER BY p.outcome_date DESC", Db.DISCHARGED, a, b))
          if (ids.add(p.get("id"))) out.add(p);
      }
    }
    return out.size() > A.MAX_CASES ? ArrayList(out.subList(0, A.MAX_CASES)) : out;
  }

  static auditSystem() {
    return "You are a senior consultant physician conducting the clinical audit of the Department of General Medicine, Tirunelveli "
      + "Medical College Hospital, Tamil Nadu, India (a government teaching hospital). You audit each case's diagnosis and "
      + "management against current evidence-based guidelines, to improve care. Be fair and specific.\n"
      + "- Use the latest guidelines you know: Indian ones where they apply (ICMR standard treatment workflows, NVBDCP/NCVBDC, "
      + "RSSDI, National snakebite protocol, NTEP, CSI, IAN), otherwise international ones (Surviving Sepsis Campaign, ADA, ESC/ACC/AHA, "
      + "AHA/ASA stroke, GOLD, GINA, KDIGO, AASLD/EASL, IDSA, WHO). Name each guideline with its year only when you are sure it "
      + "exists. Never invent trials, doses, page numbers or references. Say when your knowledge may be out of date.\n"
      + "- Use only the facts in the notes. If the notes are too thin to judge something, say \"not documented\" instead of "
      + "assuming it was not done.\n"
      + "- Think of conditions common in South India: scrub typhus, leptospirosis, dengue, malaria, enteric fever, tuberculosis, "
      + "melioidosis, snake bite, organophosphate, paraquat and rat-killer poisoning, alcohol-related disease.\n"
      + "- For each case write, under a line \"CASE n\": Diagnosis (fits the findings? alternatives missed?), Management "
      + "(matches the guideline? name it), Gaps (what was missed, delayed or not documented), Good practice, and a Grade: "
      + "Standard met / Partly met / Not met / Cannot judge.\n"
      + "- Then a part \"OVERALL\": common patterns across the cases, deaths that may have been preventable (with the reason), "
      + "documentation gaps, and 3 to 5 concrete action points for the unit.\n"
      + "- Plain text only: no markdown, no tables, no patient names. Short points.\n"
      + "- End with one line: \"Audit support only: the department's audit committee decides.\"";
  }

  /** The cases as de-identified notes, numbered CASE 1..n in the order given. */
  static auditNotes(db, unit, r, cases) {
    const u = new StringBuilder("Audit these " + cases.size() + " cases of " + (ClinicalAudit.ALL === unit ? "the department" : unit + " unit")
      + ", " + ClinicalAudit.label(r) + ".\n");
    let n = 0;
    for (const p of cases) {
      n++;
      u.append("\n<case n=\"").append(n).append("\">\n");
      u.append("Outcome: ").append(Db.DIED === p.get("status") ? "died" : Db.IN === p.get("status") ? "still in hospital" : "discharged")
        .append(", ").append(ClinicalAudit.stayDays(p)).append(" days in hospital");
      const place = Ui.nz(p.get("death_place"));
      if (!place.isEmpty()) u.append(", died in ").append(place);
      u.append(".\n");
      if (!Ui.nz(p.get("outcome_note")).isEmpty()) u.append("Outcome note: ").append(Ai.deidentify(p.get("outcome_note"), p)).append("\n");
      const o = CaseSheet.load(db, Long.parseLong(p.get("id")));
      const secs = CaseSheet.summary(db, p, o);
      for (const e of secs.entrySet()) {
        let v = Ui.nz(e.getValue()).trim();
        if (v.isEmpty()) continue;
        if (v.length > 1500) v = v.substring(0, 1500) + " …";
        u.append("## ").append(e.getKey()).append("\n").append(Ai.deidentify(v, p)).append("\n");
      }
      u.append("</case>\n");
    }
    return u.toString();
  }

  static stayDays(p) {
    const x = Dates.parse(p.get("admit_date"));
    let y = Dates.parse(p.get("outcome_date"));
    if (y == null) y = Dates.today();
    return x == null ? 0 : Math.max(0, ChronoUnit.DAYS.between(x, y));
  }

  /** For the free chat apps: rules and cases together. */
  static auditPrompt(db, unit, r, cases) {
    return ClinicalAudit.auditSystem() + "\n\nReply with the audit only.\n\n" + ClinicalAudit.auditNotes(db, unit, r, cases);
  }

  /** API key way. Runs on a background thread. (throws Ai.Failure) */
  static review(c, engine, db, unit, r, cases) {
    return Ai.single(c, engine, ClinicalAudit.auditSystem(), ClinicalAudit.auditNotes(db, unit, r, cases), 32000);
  }

  static parseAnswer(answer) {
    let t = Ai.clean(Ui.nz(answer).split("\r").join(""));
    t = t.replaceAllRx("(?i)^(sure|certainly|here is|here's|okay|ok)[^\n]*:?\\s*\n+", "").trim();
    if (t.contains("<case n=") || t.length < 120) throw new Ai.Failure("This doesn't look like the AI's audit. In the AI app, tap Copy under its answer, then come back and tap Paste.");
    return t;
  }

  /** Case n → "Name, age/sex · unit · IP": kept with the saved audit so the team knows which patient each case is. */
  static key(cases) {
    const sb = new StringBuilder();
    let n = 0;
    for (const p of cases) sb.append("CASE ").append(++n).append(": ").append(ClinicalAudit.who(p)).append("  ·  ")
      .append(Db.DIED === p.get("status") ? "died" : "discharged").append(" ").append(Dates.nice(p.get("outcome_date"))).append("\n");
    return sb.toString().trim();
  }

  static save(c, db, unit, r, set, how, text, key) {
    const cv = new ContentValues();
    cv.put("unit", unit);
    cv.put("date_from", r[0].toString());
    cv.put("date_to", r[1].toString());
    cv.put("case_set", set);
    cv.put("how", how);
    cv.put("text", text);
    cv.put("case_key", key);
    cv.put("by_name", Chat.myName(c, db));
    cv.put("time", Chat.now());
    return db.insert(ClinicalAudit.TABLE, cv);
  }

  // ---------- the report ----------

  static c(t) {
    return new FormDoc.Cell(t);
  }

  static h(t) {
    return new FormDoc.Cell(t).b().fill(0xFFFFE4E6);
  }

  /** The audit as a PDF or Word document: numbers, units, red flags and (if given) the saved AI review. */
  static report(db, unit, r, audit) {
    const A = ClinicalAudit, c = ClinicalAudit.c, h = ClinicalAudit.h;
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "CLINICAL AUDIT · " + (A.ALL === unit ? "DEPARTMENT" : unit + " UNIT") + " · " + A.label(r).toUpperCase();
    f.footer = "Clinical audit  •  " + A.label(r) + "  •  " + f.dept;
    f.fileBase = "Clinical_audit_" + (A.ALL === unit ? "dept" : unit) + "_" + r[0] + "_" + r[1];
    const s = A.stats(db, unit, r), p = A.stats(db, unit, A.before(r));
    const b = f.block("CENSUS  ·  compared with " + A.label(A.before(r)), A.COLOR, 0.25, 0.25, 0.25, 0.25);
    b.row(16, h("Admissions"), h("Discharges"), h("Deaths"), h("Mortality"));
    b.row(16, c(s.admissions + "  (" + p.admissions + ")").center(), c(s.discharges + "  (" + p.discharges + ")").center(),
      c(s.deaths + "  (" + p.deaths + ")").center(), c(s.mortality() + "  (" + p.mortality() + ")").center());
    b.row(16, h("LAMA / absconded"), h("Referred / sent back"), h("To IMCU / CCB"), h("Average stay"));
    b.row(16, c(s.lama + " / " + s.absconded).center(), c(String(s.referred)).center(), c(s.toImcu + " / " + s.toCcb).center(),
      c(jfmt("%.1f days", s.alos)).center());
    if (A.ALL === unit) {
      const ub = f.block("UNITS", 0xFF0F766E, 0.16, 0.14, 0.14, 0.14, 0.14, 0.14, 0.14);
      ub.row(14, h("Unit"), h("Admitted"), h("Discharged"), h("Deaths"), h("Mortality"), h("LAMA"), h("Avg stay"));
      for (const w of Db.WARD_UNITS) {
        const x = A.stats(db, w, r);
        ub.row(14, c(w).b(), c(String(x.admissions)).center(), c(String(x.discharges)).center(), c(String(x.deaths)).center(),
          c(x.mortality()).center(), c(String(x.lama + x.absconded)).center(), c(jfmt("%.1f", x.alos)).center());
      }
    }
    const fl = A.flags(db, unit, r);
    const fb = f.block("RED FLAGS  ·  " + fl.size(), 0xFFB45309, 0.32, 0.68);
    if (fl.isEmpty()) fb.row(14, c("None").span(2));
    for (const x of fl) fb.row(14, c(x.kind).b(), c(x.text));
    if (audit != null) {
      const ab = f.block("AI REVIEW OF DIAGNOSIS AND MANAGEMENT  ·  " + Ui.nz(audit.get("how")), 0xFF4338CA, 1);
      ab.row(14, c(Ui.nz(audit.get("case_key"))).size(9));
      ab.row(14, c(Ui.nz(audit.get("text"))));
      ab.row(14, c("Saved by " + Ui.nz(audit.get("by_name")) + ", " + Chat.when(audit.get("time")) + ". Audit support only: the department's audit committee decides.").size(8));
    }
    return f;
  }
}

ClinicalAudit.Stats = class {
  constructor() {
    this.admissions = 0; this.discharges = 0; this.deaths = 0; this.lama = 0; this.absconded = 0; this.referred = 0;
    this.toImcu = 0; this.toCcb = 0; this.inNow = 0;
    this.alos = 0;
  }

  mortality() {
    return MonthlyReport.pct(this.deaths, this.deaths + this.discharges);
  }

  mortalityValue() {
    return this.deaths + this.discharges === 0 ? 0 : this.deaths * 100.0 / (this.deaths + this.discharges);
  }
};

ClinicalAudit.Flag = class {
  constructor(kind, pid, text) {
    this.kind = kind;
    this.pid = pid;
    this.text = text;
  }
};
;
/* ---- app/ClinicalAuditActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Clinical audit (7.87): pick a period and a unit; the census numbers against the period before, the units side by
 * side, the red flags (each opens the patient), the AI review of the cases, saved audits, and the report as PDF or Word.
 */
class ClinicalAuditActivity extends Base {
  constructor() {
    super();
    this.period = "This month";
    this.unit = ClinicalAudit.ALL;
    this.busy = false;
    this.openKinds = new JSet();
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Clinical audit");
    this.headerColor(ClinicalAudit.COLOR);
  }

  waitPrefs() {
    return this.getSharedPreferences("audit_wait", Context.MODE_PRIVATE);
  }

  render() {
    const db = this.db;
    const page = Ui.v(this);
    if (!ClinicalAudit.canUse(this)) {
      this.subtitle = "Faculty, HOD and admin";
      const t = Ui.tv(this, "🔒 The clinical audit is for the faculty, the HOD, the registrar and the admin.", 15, Ui.MUTED, false);
      t.setGravity(Gravity.CENTER);
      t.setPadding(Ui.dp(this, 24), Ui.dp(this, 40), Ui.dp(this, 24), Ui.dp(this, 40));
      page.addView(t);
      this.setPage(page);
      return;
    }
    const r = ClinicalAudit.range(this.period);
    this.subtitle = (ClinicalAudit.ALL === this.unit ? "Department" : this.unit + " unit") + "  ·  " + ClinicalAudit.label(r);
    const s = ClinicalAudit.stats(db, this.unit, r), p = ClinicalAudit.stats(db, this.unit, ClinicalAudit.before(r));
    const flags = ClinicalAudit.flags(db, this.unit, r);

    page.addView(this.hero(r, s, p, flags.size()));

    // period and unit
    const pf = Ui.h(this);
    pf.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 2));
    for (const x of ClinicalAudit.PERIODS) pf.addView(this.chip(x, x === this.period, ClinicalAudit.COLOR, true, x));
    page.addView(Ui.hscroll(this, pf));
    const uf = Ui.h(this);
    uf.setPadding(Ui.dp(this, 12), Ui.dp(this, 2), Ui.dp(this, 12), Ui.dp(this, 2));
    uf.addView(this.chip("All units", ClinicalAudit.ALL === this.unit, ClinicalAudit.COLOR, false, ClinicalAudit.ALL));
    for (const w of Db.WARD_UNITS) uf.addView(this.chip(w, w === this.unit, Ui.unitColor(w), false, w));
    page.addView(Ui.hscroll(this, uf));

    // the numbers
    page.addView(Ui.heading(this, "Census  ·  against " + ClinicalAudit.label(ClinicalAudit.before(r)), ClinicalAudit.COLOR));
    const nc = Ui.card(this);
    nc.addView(Ui.statRow(this, this.stat(s.admissions, p.admissions, "Admitted", 0xFF2563EB, false),
      this.stat(s.discharges, p.discharges, "Discharged", 0xFF16A34A, false), this.stat(s.deaths, p.deaths, "Deaths", 0xFFDC2626, true)));
    const gap = Ui.space(this, 10);
    nc.addView(gap);
    nc.addView(Ui.statRow(this, Ui.stat(this, s.mortality(), "Mortality (" + p.mortality() + ")", 0xFF9F1239),
      this.stat(s.lama + s.absconded, p.lama + p.absconded, "LAMA / absconded", 0xFFB45309, true),
      Ui.stat(this, jfmt("%.1f", s.alos), "Avg stay, days (" + jfmt("%.1f", p.alos) + ")", 0xFF0F766E)));
    nc.addView(Ui.space(this, 10));
    nc.addView(Ui.statRow(this, this.stat(s.toImcu, p.toImcu, "To IMCU", 0xFF7C3AED, false), this.stat(s.toCcb, p.toCcb, "To CCB", 0xFF7C3AED, false),
      this.stat(s.referred, p.referred, "Referred / sent back", Ui.SLATE, false)));
    nc.addView(Ui.space(this, 6));
    nc.addView(Ui.muted(this, "Small figures in brackets and the arrows compare with " + ClinicalAudit.label(ClinicalAudit.before(r))
      + ". In hospital now: " + s.inNow + "."));
    page.addView(nc);

    if (ClinicalAudit.ALL === this.unit) page.addView(this.unitsCard(r));

    // red flags
    page.addView(Ui.heading(this, "Red flags  ·  " + flags.size(), 0xFFB45309));
    if (flags.isEmpty()) page.addView(this.note("No red flags in this period."));
    else page.addView(this.flagsCard(flags));

    // AI review
    page.addView(Ui.heading(this, "AI review of diagnosis and management", 0xFF4338CA));
    page.addView(this.aiCard(r));

    // saved audits
    const saved = db.rows("SELECT * FROM " + ClinicalAudit.TABLE + " ORDER BY time DESC, id DESC LIMIT 30");
    page.addView(Ui.heading(this, "Saved audits  ·  " + saved.size(), Ui.PRIMARY));
    if (saved.isEmpty()) page.addView(this.note("AI reviews you save appear here, for everyone in the faculty."));
    for (const a of saved) page.addView(this.savedCard(a));

    // report
    const rr = Ui.h(this);
    rr.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 16));
    const w = Ui.outlineButton(this, "Report as Word", 0xFF2563EB, { onClick: (v) => { this.file(null, false); } });
    rr.addView(w, Ui.weight(1));
    const pd = Ui.outlineButton(this, "Report as PDF", 0xFFDC2626, { onClick: (v) => { this.file(null, true); } });
    rr.addView(pd, Ui.weight(1));
    Ui.margins(pd, 8, 0, 0, 0);
    page.addView(rr);
    this.setPage(page);
  }

  chip(label, on, color, isPeriod, value) {
    const c = Ui.chip(this, label, on, color);
    c.setOnClickListener({
      onClick: (v) => {
        if (isPeriod) this.period = value;
        else this.unit = value;
        this.render();
      }
    });
    return c;
  }

  /** A number with its change; for deaths and LAMA a rise is shown in red, for the rest in blue. */
  stat(now, before, label, color, badWhenUp) {
    const l = Ui.stat(this, String(now), label + " (" + before + ")", color);
    const ch = ClinicalAudit.change(now, before);
    if (!ch.isEmpty()) {
      const up = ch.startsWith("▲") || ch === "new";
      let cc = ch === "same" ? Ui.MUTED : (up === badWhenUp ? 0xFFDC2626 : 0xFF16A34A);
      if (!badWhenUp && ch !== "same") cc = 0xFF2563EB;
      const t = Ui.tv(this, ch, 11, cc, true);
      t.setGravity(Gravity.CENTER);
      l.addView(t);
    }
    return l;
  }

  hero(r, s, p, flags) {
    const h = Ui.v(this);
    h.setBackground(Glass.hero(this, ClinicalAudit.HERO, 24));
    h.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const tag = Ui.tv(this, "🩺 CLINICAL AUDIT", 11, Color.WHITE, true);
    tag.setLetterSpacing(0.12);
    h.addView(tag);
    h.addView(Ui.tv(this, (ClinicalAudit.ALL === this.unit ? "Department of Medicine" : this.unit + " unit") + "  ·  " + this.period, 20, Color.WHITE, true));
    h.addView(Ui.tv(this, ClinicalAudit.label(r), 13, 0xE6FFFFFF, false));
    h.addView(Ui.tv(this, s.admissions + " admitted  ·  " + s.deaths + (s.deaths === 1 ? " death" : " deaths") + "  ·  mortality " + s.mortality() + "  ·  " + flags + " red flags", 13, Color.WHITE, true));
    const lp = Ui.lp(MATCH_PARENT, WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    h.setLayoutParams(lp);
    return h;
  }

  note(s) {
    const t = Ui.tv(this, s, 13, Ui.MUTED, false);
    t.setPadding(Ui.dp(this, 20), Ui.dp(this, 6), Ui.dp(this, 20), Ui.dp(this, 10));
    return t;
  }

  unitsCard(r) {
    const card = Ui.card(this);
    const hr = this.row("Unit", "Adm", "Disch", "Deaths", "Mort.", "Stay", true, Ui.TEXT);
    card.addView(hr);
    let worst = -1;
    let worstUnit = "";
    for (const w of Db.WARD_UNITS) {
      const x = ClinicalAudit.stats(this.db, w, r);
      card.addView(this.row(w, String(x.admissions), String(x.discharges), String(x.deaths), x.mortality(),
        jfmt("%.1f", x.alos), false, Ui.unitColor(w)));
      if (x.deaths + x.discharges >= 5 && x.mortalityValue() > worst) {
        worst = x.mortalityValue();
        worstUnit = w;
      }
    }
    if (!worstUnit.isEmpty() && worst > 0) card.addView(Ui.muted(this, "Highest mortality: " + worstUnit + " (units with at least 5 outcomes)."));
    return card;
  }

  row(a, b, c, d, e, f, head, color) {
    const l = Ui.h(this);
    l.setPadding(0, Ui.dp(this, 4), 0, Ui.dp(this, 4));
    const v = [a, b, c, d, e, f];
    for (let i = 0; i < v.length; i++) {
      const t = Ui.tv(this, v[i], 13, i === 0 ? color : (head ? Ui.MUTED : Ui.TEXT), head || i === 0);
      t.setGravity(i === 0 ? Gravity.START : Gravity.CENTER);
      l.addView(t, Ui.weight(i === 0 ? 1.1 : 1));
    }
    return l;
  }

  flagsCard(flags) {
    const card = Ui.card(this);
    const kinds = new JMap();
    for (const f of flags) kinds.put(f.kind, (kinds.containsKey(f.kind) ? kinds.get(f.kind) : 0) + 1);
    const ks = Ui.h(this);
    for (const e of kinds.entrySet()) {
      const pill = Ui.softPill(this, e.getKey() + " · " + e.getValue(), 0xFFB45309);
      ks.addView(pill);
      Ui.margins(pill, 0, 0, 6, 0);
    }
    card.addView(Ui.hscroll(this, ks));
    let last = "";
    let shown = 0;
    for (const f of flags) {
      if (f.kind !== last) {
        const k = Ui.tv(this, "⚑ " + f.kind, 14, 0xFFB45309, true);
        card.addView(k);
        Ui.margins(k, 0, 10, 0, 2);
        last = f.kind;
        shown = 0;
      }
      // long lists show the first 5, with a tap to see the rest
      if (++shown > 5 && !this.openKinds.contains(f.kind)) {
        if (shown === 6) {
          const more = Ui.tv(this, "Show all " + kinds.get(f.kind) + " ›", 13, ClinicalAudit.COLOR, true);
          more.setPadding(Ui.dp(this, 8), Ui.dp(this, 5), 0, Ui.dp(this, 5));
          more.setOnClickListener({
            onClick: (v) => {
              this.openKinds.add(f.kind);
              this.render();
            }
          });
          card.addView(more);
        }
        continue;
      }
      const t = Ui.tv(this, f.text + "  ›", 13, Ui.TEXT, false);
      t.setPadding(Ui.dp(this, 8), Ui.dp(this, 5), 0, Ui.dp(this, 5));
      t.setOnClickListener(this.opener(PatientActivity, "id", f.pid));
      card.addView(t);
    }
    return card;
  }

  // ---------- AI review ----------

  aiCard(r) {
    const card = Ui.card(this);
    card.addView(Ui.body(this, "The AI checks each case's diagnosis and management against current guidelines and writes an overall summary "
      + "with action points. Names, IP numbers, phone numbers and addresses are removed before sending. At most "
      + ClinicalAudit.MAX_CASES + " cases at a time."));
    const w = this.waitPrefs();
    if (w.contains("set")) {
      const paste = Ui.button(this, "📋  Paste the AI's audit (" + w.getString("app", "AI") + ")", 0xFF4338CA, { onClick: (v) => { this.pasteAnswer(); } });
      card.addView(paste);
      Ui.margins(paste, 0, 10, 0, 0);
    }
    const go = Ui.button(this, "✨  Run AI review for " + (ClinicalAudit.ALL === this.unit ? "the department" : this.unit) + ", " + this.period.toLowerCase(),
      ClinicalAudit.COLOR, { onClick: (v) => { this.chooseSet(r); } });
    card.addView(go);
    Ui.margins(go, 0, 10, 0, 0);
    card.addView(Ui.muted(this, "Audit support only: the department's audit committee decides."));
    return card;
  }

  chooseSet(r) {
    const db = this.db;
    const items = new Array(ClinicalAudit.CASE_SETS.length).fill(null);
    for (let i = 0; i < items.length; i++)
      items[i] = ClinicalAudit.CASE_SETS[i] + "  (" + ClinicalAudit.cases(db, this.unit, r, ClinicalAudit.CASE_SETS[i]).size() + ")";
    new AlertDialog.Builder(this).setTitle("Which cases?").setItems(items, {
      onClick: (d, i) => {
        const set = ClinicalAudit.CASE_SETS[i];
        const cases = ClinicalAudit.cases(db, this.unit, r, set);
        if (cases.isEmpty()) Ui.toast(this, "No cases of that kind in this period");
        else this.chooseAi(r, set, cases);
      }
    }).setNegativeButton("Cancel", null).show();
  }

  chooseAi(r, set, cases) {
    const engines = Ai.engines(this);
    const apps = DischargeActivity.CHAT_APPS;
    const items = new Array(engines.size() + apps.length).fill(null);
    for (let i = 0; i < engines.size(); i++) items[i] = Ai.engineLabel(engines.get(i));
    for (let i = 0; i < apps.length; i++) items[engines.size() + i] = "Free " + apps[i][0] + " app (copy and paste)";
    new AlertDialog.Builder(this).setTitle(cases.size() + " cases: review with").setItems(items, {
      onClick: (d, i) => {
        if (i < engines.size()) this.runAi(r, set, cases, engines.get(i));
        else this.freeApp(r, set, cases, apps[i - engines.size()]);
      }
    }).setNegativeButton("Cancel", null).show();
  }

  runAi(r, set, cases, engine) {
    if (this.busy) return;
    this.busy = true;
    const db = this.db;
    const u = this.unit;
    const wait = new AlertDialog.Builder(this).setTitle("✨ Auditing")
      .setMessage(Ai.company(engine) + " is reviewing " + cases.size() + " cases against the guidelines…").setCancelable(false).show();
    const main = new Handler(Looper.getMainLooper());
    new Thread({
      run: () => {
        let out = null, err = null;
        try {
          out = ClinicalAudit.review(this, engine, db, u, r, cases);
        } catch (f) {
          if (f instanceof Ai.Failure) err = f.getMessage();
          else err = "Could not reach the AI: " + f.getMessage();
        }
        const o = out, e = err;
        main.post({
          run: () => {
            this.busy = false;
            try { wait.dismiss(); } catch (ignored) { }
            if (o != null && !o.trim().isEmpty()) this.saved(ClinicalAudit.save(this, db, u, r, set,
              Ai.GEMINI === engine ? "Gemini AI" : "Claude AI", o.trim(), ClinicalAudit.key(cases)));
            else new AlertDialog.Builder(this).setTitle("Not done").setMessage(e == null ? "No answer" : e).setPositiveButton("OK", null).show();
          }
        });
      }
    }).start();
  }

  freeApp(r, set, cases, app) {
    const prompt = ClinicalAudit.auditPrompt(this.db, this.unit, r, cases);
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Cases for audit", prompt));
    this.waitPrefs().edit().putString("unit", this.unit).putString("from", r[0].toString()).putString("to", r[1].toString())
      .putString("set", set).putString("app", app[0]).putString("key", ClinicalAudit.key(cases)).apply();
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, prompt);
    i.setPackage(app[1]);
    i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
    try {
      this.startActivity(i);
      Ui.toast(this, "In " + app[0] + ": send it, tap Copy under the answer, come back and tap Paste");
    } catch (noApp) {
      try {
        this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(app[2])).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        Ui.toast(this, "Copied: paste it in " + app[0]);
      } catch (e) {
        Ui.toast(this, "Copied: open " + app[0] + " and paste it");
      }
    }
    this.render();
  }

  pasteAnswer() {
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    let text = "";
    if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
      const s = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
      text = s == null ? "" : s.toString().trim();
    }
    this.pasteText(text);
  }

  /** Also the test hook. */
  pasteText(text) {
    const w = this.waitPrefs();
    let clean;
    try {
      clean = ClinicalAudit.parseAnswer(text);
    } catch (f) {
      if (!(f instanceof Ai.Failure)) throw f;
      new AlertDialog.Builder(this).setTitle("Nothing to paste yet").setMessage(f.getMessage()).setPositiveButton("OK", null).show();
      return;
    }
    let r = [Dates.parse(w.getString("from", "")), Dates.parse(w.getString("to", ""))];
    if (r[0] == null || r[1] == null) r = ClinicalAudit.range(this.period);
    const id = ClinicalAudit.save(this, this.db, w.getString("unit", this.unit), r, w.getString("set", ""), w.getString("app", "AI") + " AI", clean, w.getString("key", ""));
    w.edit().clear().apply();
    this.saved(id);
  }

  saved(id) {
    Ui.toast(this, "Audit saved");
    this.render();
    const a = this.db.row("SELECT * FROM " + ClinicalAudit.TABLE + " WHERE id=?", String(id));
    if (a != null) this.show(a);
  }

  savedCard(a) {
    const card = Ui.card(this);
    const hr = Ui.h(this);
    hr.setGravity(Gravity.CENTER_VERTICAL);
    const u = Ui.nz(a.get("unit"));
    hr.addView(Ui.tv(this, (ClinicalAudit.ALL === u ? "Department" : u) + "  ·  " + Ui.nz(a.get("case_set")), 15, ClinicalAudit.COLOR, true), Ui.weight(1));
    hr.addView(Ui.softPill(this, Ui.nz(a.get("how")), 0xFF4338CA));
    card.addView(hr);
    card.addView(Ui.muted(this, ClinicalAudit.label(ClinicalAuditActivity.range(a)) + "  ·  by " + Ui.nz(a.get("by_name")) + "  ·  " + Chat.when(a.get("time"))));
    const t = Ui.nz(a.get("text"));
    const ov = t.indexOf("OVERALL");
    let peek = (ov >= 0 ? t.substring(ov) : t);
    if (peek.length > 220) peek = peek.substring(0, 220) + " …";
    card.addView(Ui.tv(this, peek, 13, Ui.TEXT, false));
    card.setOnClickListener({ onClick: (v) => { this.show(a); } });
    return card;
  }

  static range(a) {
    let x = Dates.parse(a.get("date_from")), y = Dates.parse(a.get("date_to"));
    if (x == null) x = Dates.today();
    if (y == null) y = x;
    return [x, y];
  }

  show(a) {
    const db = this.db;
    const v = Ui.v(this);
    v.setPadding(Ui.dp(this, 20), Ui.dp(this, 8), Ui.dp(this, 20), Ui.dp(this, 8));
    const k = Ui.tv(this, Ui.nz(a.get("case_key")), 12, Ui.MUTED, false);
    k.setTextIsSelectable(true);
    v.addView(k);
    const t = Ui.tv(this, Ui.nz(a.get("text")), 13, Ui.TEXT, false);
    t.setTextIsSelectable(true);
    t.setLineSpacing(0, 1.12);
    v.addView(t);
    Ui.margins(t, 0, 10, 0, 0);
    const b = new AlertDialog.Builder(this).setTitle("Audit · " + ClinicalAudit.label(ClinicalAuditActivity.range(a))).setView(Ui.scroll(this, v))
      .setPositiveButton("PDF", { onClick: (d, w) => { this.file(a, true); } })
      .setNeutralButton("Word", { onClick: (d, w) => { this.file(a, false); } });
    if (Cloud.isAdmin(this) || Chat.myName(this, db) === a.get("by_name"))
      b.setNegativeButton("Delete", {
        onClick: (d, w) => {
          Ui.confirm(this, "Delete this audit?", "It is removed for everyone.", "Delete", {
            run: () => {
              db.delete(ClinicalAudit.TABLE, Long.parseLong(a.get("id")));
              this.render();
            }
          });
        }
      });
    b.show();
  }

  // ---------- the report ----------

  file(audit, pdf) {
    let rel;
    const u = audit == null ? this.unit : Ui.nz(audit.get("unit"));
    const r = audit == null ? ClinicalAudit.range(this.period) : ClinicalAuditActivity.range(audit);
    try {
      const f = ClinicalAudit.report(this.db, u, r, audit);
      rel = pdf ? f.pdf(this) : f.docx(this);
    } catch (e) {
      Ui.toast(this, "Could not make the file: " + e.getMessage());
      return;
    }
    const subject = "Clinical audit " + ClinicalAudit.label(r);
    new AlertDialog.Builder(this).setTitle((pdf ? "PDF" : "Word") + " report ready")
      .setItems(["Share (WhatsApp, email, Drive…)", "Open"], {
        onClick: (d, w) => {
          if (w === 0) Store.share(this, rel, subject);
          else Store.openWith(this, rel);
        }
      }).setNegativeButton("Close", null).show();
  }
}
;
