/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Weekly CMCHIS case entry for each unit and IMCU. */
class CmchisActivity extends Base {
  constructor() {
    super();
    this.week = null;
    this.mode = 0;          // 0 patients, 1 weekly totals
    this.unit = "M1";
    this.stage = null;      // step filter, or null for all
    this.cases = new JMap();
    this.amounts = new JMap();
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("CMCHIS");
    this.subtitle = "Patients put up by each unit and IMCU";
    this.headerColor(Ui.PINK);
    this.week = Dates.weekStart(Dates.today());
  }

  liveRefresh() {
    return false;
  }

  render() {
    const db = this.db;
    this.cases.clear();
    this.amounts.clear();
    const w0 = this.week.toString(), w1 = this.week.plusDays(6).toString();
    const page = Ui.v(this);
    page.addView(this.modeBar());
    this.headerAction(this.mode === 0 ? "+ Patient" : null, this.mode === 0 ? { onClick: (v) => { this.caseDialog(null); } } : null);
    if (this.mode === 0) {
      this.patients(page);
      this.setPage(page);
      return;
    }

    const nav = Ui.card(this);
    const row = Ui.h(this);
    row.addView(Ui.outlineButton(this, "‹ Prev", Ui.TEAL, { onClick: (v) => { this.week = this.week.minusWeeks(1); this.render(); } }));
    const mid = Ui.v(this);
    mid.setGravity(Gravity.CENTER);
    mid.addView(Ui.tv(this, "Week", 12, Ui.MUTED, false));
    mid.addView(Ui.tv(this, Dates.shortFmt(this.week) + " – " + Dates.nice(this.week.plusDays(6)), 15, Ui.TEXT, true));
    row.addView(mid, Ui.weight(1));
    const next = Ui.outlineButton(this, "Next ›", Ui.TEAL, { onClick: (v) => { this.week = this.week.plusWeeks(1); this.render(); } });
    row.addView(next);
    if (!this.week.isBefore(Dates.weekStart(Dates.today()))) next.setVisibility(View.INVISIBLE);
    nav.addView(row);
    page.addView(nav);

    page.addView(Ui.section(this, "Cases put up this week"));
    const card = Ui.card(this);
    const head = Ui.h(this);
    head.addView(Ui.muted(this, "Unit"), Ui.weight(1.2));
    head.addView(Ui.muted(this, "Cases"), Ui.weight(1));
    head.addView(Ui.muted(this, "Amount ₹ (optional)"), Ui.weight(1.5));
    card.addView(head);
    for (const u of Db.UNITS) {
      const r = db.row("SELECT * FROM cmchis WHERE week_start=? AND unit=?", w0, u);
      const flagged = db.num("SELECT COUNT(*) FROM patients p JOIN events e ON e.patient_id=p.id AND e.type='ADMIT' "
        + "WHERE p.cmchis=1 AND e.to_loc=? AND e.date BETWEEN ? AND ?", u, w0, w1);
      const line = Ui.h(this);
      const lbl = Ui.v(this);
      lbl.addView(Ui.pill(this, Db.shortName(u), Ui.unitColor(u)), Ui.lp(-2, -2));
      lbl.addView(Ui.tv(this, flagged + " flagged adm.", 11, Ui.MUTED, false));
      line.addView(lbl, Ui.weight(1.2));
      const c = new EditText(this);
      c.setInputType(Form.NUMBER);
      c.setHint(String(flagged));
      if (r != null) c.setText(r.get("cases"));
      line.addView(c, Ui.weight(1));
      const a = new EditText(this);
      a.setInputType(Form.DECIMAL);
      if (r != null && !r.get("amount").isEmpty() && "0" !== r.get("amount") && "0.0" !== r.get("amount")) a.setText(r.get("amount"));
      line.addView(a, Ui.weight(1.5));
      this.cases.put(u, c);
      this.amounts.put(u, a);
      card.addView(line);
    }
    card.addView(Ui.muted(this, "“Flagged adm.” counts patients admitted this week and marked CMCHIS in their record."));
    const save = Ui.button(this, "Save week", Ui.TEAL, { onClick: (v) => { this.save(); } });
    card.addView(save);
    Ui.margins(save, 0, 12, 0, 0);
    page.addView(card);

    page.addView(Ui.section(this, "Recent weeks"));
    const hist = Ui.card(this);
    const weeks = db.rows("SELECT week_start, SUM(cases) AS n, COUNT(*) AS units, SUM(amount) AS amt FROM cmchis GROUP BY week_start ORDER BY week_start DESC LIMIT 12");
    if (weeks.isEmpty()) hist.addView(Ui.muted(this, "No weeks entered yet"));
    for (const w of weeks) {
      const l = Ui.h(this);
      l.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
      l.addView(Ui.body(this, "Week of " + Dates.nice(w.get("week_start"))), Ui.weight(1.4));
      l.addView(Ui.muted(this, w.get("units") + "/" + Db.UNITS.length + " wards"), Ui.weight(1));
      const n = Ui.tv(this, w.get("n") + " cases", 15, Ui.TEAL, true);
      n.setGravity(Gravity.END);
      l.addView(n, Ui.weight(1));
      Ui.ripple(l, Ui.alpha(Ui.TEAL, 0x1A));
      l.setOnClickListener({
        onClick: (v) => {
          const d = Dates.parse(w.get("week_start"));
          if (d != null) { this.week = d; this.render(); }
        }
      });
      hist.addView(l);
    }
    page.addView(hist);
    this.setPage(page);
  }

  modeBar() {
    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const labels = ["Patients & approval", "Weekly totals"];
    for (let i = 0; i < labels.length; i++) {
      const idx = i;
      const t = Ui.tv(this, labels[i], 14, i === this.mode ? Ui.PINK : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      if (i === this.mode) t.setBackground(Ui.round(this, 0xFFFFFFFF, 11));
      t.setOnClickListener({ onClick: (v) => { this.mode = idx; this.render(); } });
      seg.addView(t, Ui.weight(1));
    }
    Ui.margins(seg, 12, 4, 12, 4);
    return seg;
  }

  // ---------- patients put up under CMCHIS, per unit, with approval ----------

  patients(page) {
    const db = this.db;
    const money = (x) => Math.round(x).toLocaleString('en-US');   // String.format(Locale.ROOT, "%,.0f", x)
    const m0 = Dates.monthStart(Dates.today()).toString();
    // All wards at a glance (this month)
    const over = Ui.card(this);
    over.addView(Ui.tv(this, Dates.month(Dates.today()) + "  ·  all units", 13, Ui.MUTED, true));
    over.addView(Ui.statRow(this,
      Ui.stat(this, String(db.num("SELECT COUNT(*) FROM cmchis_cases WHERE date>=?", m0)), "Put up", Ui.PINK),
      Ui.stat(this, String(db.num("SELECT COUNT(*) FROM cmchis_cases WHERE date>=? AND " + CmchisStages.APPROVED_SQL, m0)), "Approved", Ui.GREEN),
      Ui.stat(this, String(db.num("SELECT COUNT(*) FROM cmchis_cases WHERE date>=? AND status=?", m0, CmchisStages.REJECTED)), "Rejected", Ui.RED),
      Ui.stat(this, String(db.num("SELECT COUNT(*) FROM cmchis_cases WHERE " + CmchisStages.AWAITING_SQL)), "In process", Ui.AMBER)));
    let credited = 0;
    const cr = db.row("SELECT SUM(CASE WHEN credited>0 THEN credited ELSE amount END) AS s FROM cmchis_cases WHERE date>=? AND status=?", m0, CmchisStages.CREDITED);
    try { credited = Double.parseDouble(cr.get("s")); } catch (ignored) {}
    if (credited > 0) over.addView(Ui.kv(this, "Amount credited this month", "₹" + money(credited)));
    page.addView(over);
    // 10.17: claim tracker (user's pick 165): the money, claims not started and patients who may be eligible
    page.addView(CmchisClaims.money(this, this.db));
    CmchisClaims.sections(this, this.db, page, { run: () => { this.render(); } });
    page.addView(this.entryCard("Packages", CmchisPackages.COLOR, "CMCHIS packages · General Medicine",
      CmchisPackages.LIST.length + " packages with codes and rates. Search by disease, word or code.", "›", {
        onClick: (v) => { CmchisPackages.pick(this, "", null); }
      }));

    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    for (const u of Db.CMCHIS_UNITS) {
      const pend = db.num("SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND " + CmchisStages.AWAITING_SQL, u);
      const c = Ui.chip(this, Db.shortName(u) + (pend > 0 ? "  " + pend : ""), u === this.unit, Ui.unitColor(u));
      c.setOnClickListener({ onClick: (v) => { this.unit = u; this.stage = null; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    const color = Ui.unitColor(this.unit);
    page.addView(Ui.heading(this, Db.unitName(this.unit) + " · CMCHIS patients", color));
    const add = Ui.button(this, "+ Add " + Db.shortName(this.unit) + " patient", color, { onClick: (v) => { this.caseDialog(null); } });
    page.addView(add);
    Ui.margins(add, 14, 0, 14, 4);

    // filter by step
    const steps = Ui.h(this);
    steps.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
    const all = db.num("SELECT COUNT(*) FROM cmchis_cases WHERE unit=?", this.unit);
    const allChip = Ui.chip(this, "All  " + all, this.stage == null, Ui.PINK);
    allChip.setOnClickListener({ onClick: (v) => { this.stage = null; this.render(); } });
    steps.addView(allChip);
    for (const st of CmchisStages.ALL) {
      const n = db.num("SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND status=?", this.unit, st);
      if (n === 0 && st !== this.stage) continue;
      const c = Ui.chip(this, st + "  " + n, st === this.stage, CmchisStages.color(st));
      c.setOnClickListener({ onClick: (v) => { this.stage = st; this.render(); } });
      steps.addView(c);
    }
    page.addView(Ui.hscroll(this, steps));

    const rows = this.stage == null
      ? db.rows("SELECT * FROM cmchis_cases WHERE unit=? ORDER BY CASE WHEN " + CmchisStages.AWAITING_SQL + " THEN 0 WHEN status IN ('Approved','Discharge summary submitted') THEN 1 ELSE 2 END, date DESC, id DESC LIMIT 200", this.unit)
      : db.rows("SELECT * FROM cmchis_cases WHERE unit=? AND status=? ORDER BY date DESC, id DESC LIMIT 200", this.unit, this.stage);
    if (rows.isEmpty()) page.addView(this.emptyNote(this.stage == null ? "No CMCHIS patients entered for " + Db.shortName(this.unit) + " yet." : "No patients at this step."));
    for (const r of rows) {
      const st = CmchisStages.of(r.get("status"));
      const col = CmchisStages.color(st);
      const sub = new StringBuilder();
      if (!r.get("age_sex").isEmpty()) sub.append(r.get("age_sex")).append("  ·  ");
      if (!r.get("ip_no").isEmpty()) sub.append("IP ").append(r.get("ip_no")).append("  ·  ");
      if (!r.get("cmchis_no").isEmpty()) sub.append("CMCHIS ").append(r.get("cmchis_no"));
      let line2 = r.get("diagnosis") + (r.get("package").isEmpty() ? "" : "  ·  " + r.get("package"));
      let amt = 0, got = 0;
      try { amt = Double.parseDouble(r.get("amount")); } catch (ignored) {}
      try { got = Double.parseDouble(Ui.nz(r.get("credited"))); } catch (ignored) {}
      if (amt > 0) line2 += "  ·  ₹" + money(amt);
      if (got > 0) line2 += "  ·  credited ₹" + money(got);
      if (!r.get("remarks").isEmpty()) line2 += "\n" + r.get("remarks");
      const card = this.entryCard(st, col, r.get("patient"), sub.toString().replaceAllRx("  ·  $", "") + (line2.trim().isEmpty() ? "" : "\n" + line2.trim()),
        Dates.nice(r.get("date")), { onClick: (v) => { this.caseDialog(r); } });
      const hist = CmchisStages.history(r);
      if (!hist.isEmpty()) {
        const h = Ui.muted(this, TextUtils.join("  →  ", hist.subList(Math.max(0, hist.size() - 3), hist.size())));
        h.setTextSize(12);
        card.addView(h);
        Ui.margins(h, 0, 4, 0, 0);
      }
      const pd = CmchisClaims.papersDone(r);
      const papers = Ui.softPill(this, "📎 Papers " + pd + " / " + CmchisClaims.PAPERS.length, pd === CmchisClaims.PAPERS.length ? Ui.GREEN : CmchisClaims.COLOR);
      papers.setOnClickListener({
        onClick: (v) => {
          CmchisClaims.papersDialog(this, this.db, r, { run: () => { this.render(); } });
        }
      });
      const pr = Ui.h(this);
      pr.addView(papers);
      card.addView(pr);
      Ui.margins(pr, 0, 6, 0, 0);
      if (st !== CmchisStages.CREDITED && st !== CmchisStages.REJECTED) {
        const next = CmchisActivity.nextStep(st);
        const b = Ui.buttonRow(this,
          Ui.outlineButton(this, next == null ? "Update status" : "→ " + next, col, { onClick: (v) => { this.statusDialog(r, next); } }),
          Ui.outlineButton(this, "Other step…", Ui.SLATE, { onClick: (v) => { this.statusDialog(r, null); } }));
        card.addView(b);
        Ui.margins(b, 0, 8, 0, 0);
      }
      page.addView(card);
    }
  }

  /** The usual next step after this one. */
  static nextStep(st) {
    const S = CmchisStages;
    switch (st) {
      case S.PREAUTH: return S.VALIDATED;
      case S.VALIDATED: return S.APPROVED;
      case S.MORE: return S.APPROVED;
      case S.ENHANCE: return S.APPROVED;
      case S.APPROVED: return S.DISCHARGE;
      case S.EXPIRED: return S.DISCHARGE;
      case S.DISCHARGE: return S.CREDITED;
      default: return null;
    }
  }

  /** Moves a claim to a step (preselected, or picked from all nine), with the date and a note. */
  statusDialog(r, preset) {
    const f = new Form(this);
    const cur = CmchisStages.of(r.get("status"));
    f.view.addView(Ui.muted(this, r.get("patient") + "  ·  now: " + cur));
    f.choice("status", "New status", CmchisStages.ALL, CmchisStages.ALL, preset != null ? preset : cur, {
      changed: (v) => {
        f.show("credited", v === CmchisStages.CREDITED);
      }
    });
    f.date("date", "Date", Dates.todayIso());
    f.text("credited", "Amount credited ₹", "", Form.DECIMAL);
    f.show("credited", CmchisStages.CREDITED === (preset != null ? preset : cur));
    f.multi("note", "Note (query raised, reason for rejection, enhancement asked…)", "");
    Ui.formDialog(this, "CMCHIS status", f, "Save", {
      run: () => {
        let got = 0;
        try { if (!f.get("credited").isEmpty()) got = Double.parseDouble(f.get("credited")); } catch (ignored) {}
        CmchisStages.set(this.db, this, Long.parseLong(r.get("id")), f.get("status"), f.get("date"), f.get("note"), got);
        this.render();
        return true;
      }
    });
  }

  caseDialog(r) {
    const db = this.db;
    const f = new Form(this);
    f.choice("unit", "Unit", Db.shortNames(Db.CMCHIS_UNITS), Db.CMCHIS_UNITS, r == null ? this.unit : r.get("unit"), null);
    const names = [];
    for (const p of db.rows("SELECT name FROM patients WHERE (home_unit=? OR location=?) ORDER BY admit_date DESC LIMIT 300", this.unit, this.unit)) names.add(p.get("name"));
    f.suggest("patient", "Patient name *", r == null ? "" : r.get("patient"), names);
    f.text("age_sex", "Age / sex", r == null ? "" : r.get("age_sex"), Form.PLAIN);
    f.text("ip_no", "IP number", r == null ? "" : r.get("ip_no"), Form.PLAIN);
    f.text("cmchis_no", "CMCHIS card / pre-auth no.", r == null ? "" : r.get("cmchis_no"), Form.PLAIN);
    f.text("diagnosis", "Diagnosis", r == null ? "" : r.get("diagnosis"), Form.PLAIN);
    f.multi("package", "Package / procedure", r == null ? "" : r.get("package"));
    // 10.15: choose from the General Medicine package list, those that fit the diagnosis first (user asked)
    const choose = Ui.outlineButton(this, "Choose from the CMCHIS package list", CmchisPackages.COLOR, {
      onClick: (v) => {
        let dx = f.get("diagnosis");
        if (dx.isEmpty()) {
          const p = this.db.row("SELECT diagnosis FROM patients WHERE name=? ORDER BY admit_date DESC LIMIT 1", f.get("patient"));
          if (p != null) dx = Ui.nz(p.get("diagnosis"));
        }
        CmchisPackages.pick(this, dx, {
          picked: (pkg) => {
            f.set("package", CmchisPackages.label(pkg));
            if (f.get("amount").isEmpty()) f.set("amount", pkg[2]);
          }
        });
      }
    });
    f.view.addView(choose);
    Ui.margins(choose, 0, 6, 0, 0);
    f.text("amount", "Amount ₹ (optional)", r == null ? "" : r.get("amount").replaceAllRx("\\.0$", "").replaceAllRx("^0$", ""), Form.DECIMAL);
    f.date("date", "Date put up", r == null ? Dates.todayIso() : r.get("date"));
    if (r == null) f.choice("status", "Status", CmchisStages.ALL, CmchisStages.ALL, CmchisStages.PREAUTH, null);
    else {
      const hist = CmchisStages.history(r);
      f.view.addView(Ui.muted(this, "Status: " + CmchisStages.of(r.get("status")) + (hist.isEmpty() ? "" : "\n" + TextUtils.join("\n", hist))
        + "\nChange it with the status buttons on the card."));
    }
    f.multi("remarks", "Remarks (query, reason if rejected)", r == null ? "" : r.get("remarks"));
    if (r != null) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete this entry?", r.get("patient"), "Delete", {
            run: () => { db.delete("cmchis_cases", Long.parseLong(r.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "CMCHIS patient" : "Edit CMCHIS patient", f, "Save", {
      run: () => {
        if (!f.require("patient", "Enter the patient's name")) return false;
        const cv = new ContentValues();
        for (const k of ["unit", "patient", "age_sex", "ip_no", "cmchis_no", "diagnosis", "package", "date", "remarks"]) cv.put(k, f.get(k));
        let amt = 0;
        try { if (!f.get("amount").isEmpty()) amt = Double.parseDouble(f.get("amount")); } catch (ignored) {}
        cv.put("amount", amt);
        // Link to the admitted patient with this name, filling IP number and age/sex if left blank.
        const p = db.row("SELECT * FROM patients WHERE name=? AND (home_unit=? OR location=?) ORDER BY admit_date DESC LIMIT 1", f.get("patient"), f.get("unit"), f.get("unit"));
        if (p != null) {
          cv.put("patient_id", p.get("id"));
          if (f.get("ip_no").isEmpty()) cv.put("ip_no", p.get("ip_no"));
          if (f.get("age_sex").isEmpty()) cv.put("age_sex", (p.get("age").isEmpty() ? "" : p.get("age") + " / ") + ("F" === p.get("sex") ? "F" : "M"));
          if (f.get("diagnosis").isEmpty()) cv.put("diagnosis", p.get("diagnosis"));
          if (f.get("cmchis_no").isEmpty()) cv.put("cmchis_no", Ui.nz(p.get("cmchis_no")));
          if (f.get("package").isEmpty()) cv.put("package", Ui.nz(p.get("cmchis_pkg")));
        }
        this.unit = f.get("unit");
        if (r == null) {
          const nid = db.insert("cmchis_cases", cv);
          CmchisStages.set(db, this, nid, f.get("status"), f.get("date"), "", 0);
        } else db.update("cmchis_cases", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  save() {
    const db = this.db;
    const w0 = this.week.toString();
    const w = db.getWritableDatabase();
    let saved = 0;
    for (const u of Db.UNITS) {
      const c = this.cases.get(u).getText().toString().trim();
      const a = this.amounts.get(u).getText().toString().trim();
      if (c.isEmpty()) {
        w.delete("cmchis", "week_start=? AND unit=?", [w0, u]);
        continue;
      }
      const cv = new ContentValues();
      cv.put("week_start", w0);
      cv.put("unit", u);
      cv.put("cases", Ui.toInt(c, 0));
      let amt = 0;
      try { if (!a.isEmpty()) amt = Double.parseDouble(a); } catch (ignored) {}
      cv.put("amount", amt);
      db.upsertBy("cmchis", cv, "week_start=? AND unit=?", w0, u);
      saved++;
    }
    Ui.toast(this, "Saved " + saved + " of " + Db.UNITS.length + " wards for week of " + Dates.nice(this.week));
    this.render();
  }
}
;
