'use strict';
/**
 * The steps of a CMCHIS claim, from pre-authorisation to the amount being credited.
 * Each change is kept in status_log (one line per step: date|status|by|note) so the card shows the claim's history.
 */
class CmchisStages {
  constructor() {}

  static PREAUTH = "Pre-auth submitted";
  static VALIDATED = "Validated";
  static MORE = "Need more submitted";
  static ENHANCE = "Enhancement needed";
  static APPROVED = "Approved";
  static REJECTED = "Rejected";
  static EXPIRED = "Patient expired";
  static DISCHARGE = "Discharge summary submitted";
  static CREDITED = "Amount credited";

  static ALL = [CmchisStages.PREAUTH, CmchisStages.VALIDATED, CmchisStages.MORE, CmchisStages.ENHANCE, CmchisStages.APPROVED,
    CmchisStages.REJECTED, CmchisStages.EXPIRED, CmchisStages.DISCHARGE, CmchisStages.CREDITED];

  /** Steps still waiting on the insurer's decision: counted as "awaiting" on the home screen. */
  static AWAITING_SQL = "status IN ('" + CmchisStages.PREAUTH + "','" + CmchisStages.VALIDATED + "','" + CmchisStages.MORE + "','" + CmchisStages.ENHANCE + "')";
  /** Approved claims, including those further along (summary sent, amount credited). */
  static APPROVED_SQL = "status IN ('" + CmchisStages.APPROVED + "','" + CmchisStages.DISCHARGE + "','" + CmchisStages.CREDITED + "')";

  static color(st) {
    switch (st) {
      case CmchisStages.PREAUTH: return Ui.AMBER;
      case CmchisStages.VALIDATED: return Ui.SKY;
      case CmchisStages.MORE: return Ui.ORANGE;
      case CmchisStages.ENHANCE: return Ui.PURPLE;
      case CmchisStages.APPROVED: return Ui.GREEN;
      case CmchisStages.REJECTED: return Ui.RED;
      case CmchisStages.EXPIRED: return Ui.SLATE;
      case CmchisStages.DISCHARGE: return Ui.TEAL;
      case CmchisStages.CREDITED: return 0xFF047857;
      default: return Ui.AMBER;
    }
  }

  /** Older entries (Pending / Approved / Not approved) and free text from imported files, as one of the nine steps. */
  static of(raw) {
    const S = CmchisStages;
    const s = Ui.nz(raw).trim();
    for (const a of S.ALL) if (a.equalsIgnoreCase(s)) return a;
    const l = s.toLowerCase();
    if (l.isEmpty() || l === "pending") return S.PREAUTH;
    if (l.contains("credit") || l.contains("paid") || l.contains("settled")) return S.CREDITED;
    if (l.contains("discharge")) return S.DISCHARGE;
    if (l.contains("expired") || l.contains("death") || l.contains("died")) return S.EXPIRED;
    if (l.contains("enhanc")) return S.ENHANCE;
    if (l.contains("more") || l.contains("query")) return S.MORE;
    if (l.contains("not") || l.contains("reject") || l.contains("denied")) return S.REJECTED;
    if (l.contains("approv") || l === "yes") return S.APPROVED;
    if (l.contains("valid")) return S.VALIDATED;
    return S.PREAUTH;
  }

  /** Sets a claim's step and adds it to its history. */
  static set(db, c, id, status, date, note, credited) {
    const S = CmchisStages;
    const r = db.row("SELECT status_log FROM cmchis_cases WHERE id=?", String(id));
    const log = r == null ? "" : Ui.nz(r.get("status_log"));
    const by = Approvals.me(c);
    const line = date + "|" + status + "|" + by.split("|").join("/") + "|" + Ui.nz(note).split("|").join("/").split("\n").join(" ");
    const cv = new ContentValues();
    cv.put("status", status);
    cv.put("status_date", date);
    cv.put("status_log", log.isEmpty() ? line : log + "\n" + line);
    if (status === S.CREDITED && credited > 0) cv.put("credited", credited);
    if (!Ui.nz(note).isEmpty() && (status === S.REJECTED || status === S.MORE || status === S.ENHANCE)) cv.put("remarks", note);
    db.update("cmchis_cases", cv, id);
  }

  /** The history as short lines, oldest first: "08-10 Pre-auth submitted". */
  static history(r) {
    const out = [];
    for (const l of Ui.nz(r.get("status_log")).jsplit("\n")) {
      const p = l.jsplit("\\|", -1);
      if (p.length < 2 || p[1].isEmpty()) continue;
      let d = Dates.nice(p[0]);
      if (d.length >= 5) d = d.substring(0, 5);
      out.add(d + " " + p[1] + (p.length > 3 && !p[3].isEmpty() ? " (" + p[3] + ")" : ""));
    }
    return out;
  }
}
;
