/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Convict cases: admitted by the day's admitting unit, moved the next day to the convict ward, which is the ward of
 * the medical unit in charge that month (M1 to M7 in turn). Listed unit by unit.
 */
class ConvictActivity extends Base {
  static COLOR = 0xFF475569;

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Convict cases");
    this.subtitle = "Convict ward this month: " + this.db.rotationUnit() + " unit";
    this.headerColor(ConvictActivity.COLOR);
    this.headerAction("+ Admit", this.opener(FormActivity, "kind", "patient"));
  }

  render() {
    const page = Ui.v(this);
    const ward = this.db.rotationUnit();
    page.addView(UnitActivity.rotationCard(this, this.db));
    // still to move: in another ward and admitted before the current admission day
    const due = this.db.rows("SELECT * FROM patients WHERE status='IN' AND convict='1' AND location<>? AND admit_date<? ORDER BY admit_date",
      ward, Dates.admitDay().toString());
    page.addView(Ui.heading(this, "To move to the " + ward + " convict ward  ·  " + due.length, Ui.RED));
    if (due.isEmpty()) page.addView(this.emptyNote("None waiting"));
    for (const p of due) page.addView(this.patientRow(p));
    // each unit's own convict admissions, wherever the patient is now
    page.addView(Ui.heading(this, "Convict cases by admitting unit", ConvictActivity.COLOR));
    let total = 0;
    for (const u of Db.WARD_UNITS) {
      const rows = this.db.rows("SELECT p.* FROM patients p JOIN events e ON e.patient_id=p.id AND e.type='ADMIT' "
        + "WHERE p.status='IN' AND p.convict='1' AND e.from_loc=? ORDER BY p.admit_date DESC", u);
      total += rows.length;
      if (rows.isEmpty()) continue;
      page.addView(Ui.section(this, "Admitted by " + u + "  ·  " + rows.length));
      for (const p of rows) page.addView(this.patientRow(p));
    }
    if (total == 0) page.addView(this.emptyNote("No convict cases in hospital now"));
    const m0 = Dates.monthStart(Dates.today()).toString();
    const month = this.db.rows("SELECT * FROM patients WHERE convict='1' AND admit_date>=? ORDER BY admit_date DESC", m0);
    page.addView(Ui.heading(this, Dates.month(Dates.today()) + ": convict admissions  ·  " + month.length, ConvictActivity.COLOR));
    for (const p of month) if (!"IN".equals(p.get("status"))) page.addView(this.patientRow(p));
    this.setPage(page);
  }
}
;
