/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Relative counselling log (10.2): who was told what and when, by which doctor, in which language, and whether they understood,
 * with the consent form signed if any. Kept per patient for medico-legal cover; printed as a dated record with signature lines.
 * The patient page warns when a sick patient (NEWS2 7 or more, or Worse or Critical in the last note) has no entry in 24 hours.
 */
class Counsel {
  static TABLE = "counsel_logs";
  static COLOR = 0xFF7C2D12;
  static TOPICS = ["Diagnosis explained", "Condition is serious", "Condition is critical, risk to life", "Need for ICU / ventilator",
    "Procedure and its risks", "Blood transfusion", "Not responding to treatment", "Do not resuscitate / limits of care", "Death informed",
    "Referral to another hospital", "Discharge and follow-up", "CMCHIS / cost"];
  static RELATIONS = ["Husband", "Wife", "Son", "Daughter", "Father", "Mother", "Brother", "Sister", "Other relative", "Friend / bystander", "Patient himself / herself"];
  static LANGS = ["Tamil", "English", "Tamil and English", "Other"];

  static forPatient(db, pid) {
    return db.rows("SELECT * FROM " + Counsel.TABLE + " WHERE patient_id=? ORDER BY date DESC, time DESC, id DESC", String(pid));
  }

  /** Whether the patient is sick enough that the family should have been told in the last 24 hours. */
  static sick(db, pid) {
    const e = Ews.latest(db, pid);
    if (e != null && e.count > 0 && e.total >= 7) return true;
    let last = null;
    for (const n of CaseSheet.notesByTime(CaseSheet.load(db, pid))) last = n;
    const st = last == null ? "" : CaseSheet.s(last, "status");
    return "Critical" === st || "Worse" === st;
  }

  static recent(db, pid) {
    const cut = LocalDateTime.of(Dates.today(), Dates.time()).minusHours(24);
    for (const r of Counsel.forPatient(db, pid)) {
      const t = Ui.nz(r.get("date")) + "T" + (Ui.nz(r.get("time")).isEmpty() ? "00:00" : r.get("time"));
      if (t.compareTo(cut.toString().substring(0, 16)) >= 0) return true;
    }
    return false;
  }

  static line(r) {
    let b = Ui.nz(r.get("relative")) + (Ui.nz(r.get("relation")).isEmpty() ? "" : " (" + r.get("relation") + ")");
    b += "\nTold: " + Ui.nz(r.get("topics")).split("|").join(", ");
    if (!Ui.nz(r.get("notes")).isEmpty()) b += "\n" + r.get("notes");
    b += "\nIn " + Ui.nz(r.get("lang")) + ("1" === r.get("understood") ? " · understood" : " · understanding not confirmed");
    if (!Ui.nz(r.get("consent")).isEmpty()) b += " · consent signed: " + r.get("consent");
    b += "\nBy " + Ui.nz(r.get("by_name"));
    return b;
  }

  /** The patient page's section: the log, the add button, the consent forms. */
  static section(a, db, p) {
    const pid = Long.parseLong(p.get("id"));
    const box = Ui.v(a);
    const rows = Counsel.forPatient(db, pid);
    box.addView(Ui.heading(a, "Relatives counselled  ·  " + rows.length, Counsel.COLOR));
    const card = Ui.card(a);
    if (Db.IN === p.get("status") && Counsel.sick(db, pid) && !Counsel.recent(db, pid))
      card.addView(Ui.tv(a, "⚠ Sick patient: no counselling recorded in the last 24 hours", 14, Ui.RED, true));
    if (rows.isEmpty()) card.addView(Ui.muted(a, "Record each time the family is told about the illness, risks, procedures or death: who was told, what, in which language. It protects the doctor if questions come later."));
    for (const r of rows) {
      const e = Ui.v(a);
      e.setPadding(0, Ui.dp(a, 6), 0, Ui.dp(a, 6));
      e.addView(Ui.tv(a, Dates.nice(Ui.nz(r.get("date"))) + " " + Ui.nz(r.get("time")), 13, Counsel.COLOR, true));
      e.addView(Ui.tv(a, Counsel.line(r), 14, Ui.TEXT, false));
      e.setOnLongClickListener({
        onLongClick: (v) => {
          if (CaseSheet.canEdit(a, db, p)) Counsel.edit(a, db, p, r);
          return true;
        }
      });
      card.addView(e);
    }
    const btns = Ui.buttonRow(a, Ui.outlineButton(a, "+ Record counselling", Counsel.COLOR, {
      onClick: (v) => {
        if (!CaseSheet.canEdit(a, db, p)) {
          Ui.toast(a, "Only this patient's unit team records counselling");
          return;
        }
        Counsel.edit(a, db, p, null);
      }
    }), Ui.outlineButton(a, "📝 Consent forms", Consent.COLOR, a.opener(ConsentActivity, "id", String(pid))));
    card.addView(btns);
    Ui.margins(btns, 0, 8, 0, 0);
    if (!rows.isEmpty()) {
      const pdf = Ui.outlineButton(a, "Print the counselling record (PDF)", Ui.SLATE, { onClick: (v) => { Counsel.print(a, db, p); } });
      card.addView(pdf);
      Ui.margins(pdf, 0, 8, 0, 0);
    }
    box.addView(card);
    return box;
  }

  static edit(a, db, p, old) {
    const f = new Form(a);
    f.date("date", "Date", old == null ? Dates.todayIso() : old.get("date"));
    f.time("time", "Time", old == null ? Dates.now() : old.get("time"));
    f.text("relative", "Name of the person told", old == null ? "" : old.get("relative"), Form.TEXT);
    f.choice("relation", "Relation to the patient", Counsel.RELATIONS, Counsel.RELATIONS, old == null ? Counsel.RELATIONS[0] : old.get("relation"), null);
    f.text("phone", "Their mobile (optional)", old == null ? "" : old.get("phone"), Form.TEXT);
    const on = old == null ? [] : Ui.nz(old.get("topics")).split("|");
    f.heading("What was explained");
    for (let i = 0; i < Counsel.TOPICS.length; i++) f.check("t" + i, Counsel.TOPICS[i], on.contains(Counsel.TOPICS[i]));
    f.multi("notes", "In your words (what was said, their questions)", old == null ? "" : old.get("notes"));
    f.choice("lang", "Language", Counsel.LANGS, Counsel.LANGS, old == null ? Counsel.LANGS[0] : old.get("lang"), null);
    f.check("understood", "They said they understood", old == null || "1" === old.get("understood"));
    const cs = [""].concat(Consent.KINDS.map((k) => k.en));
    const cl = cs.slice();
    cl[0] = "None";
    f.choice("consent", "Consent form signed", cl, cs, old == null ? "" : Ui.nz(old.get("consent")), null);
    Ui.formDialog(a, old == null ? "Record counselling" : "Edit counselling", f, "Save", {
      run: () => {
        if (!f.require("relative", "Write who was told")) return false;
        const t = [];
        for (let i = 0; i < Counsel.TOPICS.length; i++) if ("1" === f.get("t" + i)) t.push(Counsel.TOPICS[i]);
        if (t.length === 0 && f.get("notes").trim().isEmpty()) {
          Ui.toast(a, "Tick what was explained, or write it");
          return false;
        }
        const cv = new ContentValues();
        for (const k of ["date", "time", "relative", "relation", "phone", "notes", "lang", "consent"]) cv.put(k, f.get(k).trim());
        cv.put("topics", t.join("|"));
        cv.put("understood", "1" === f.get("understood") ? "1" : "0");
        if (old == null) {
          cv.put("patient_id", p.get("id"));
          cv.put("by_name", CallDutyActivity.myName(a));
          const me = SessionAttendance.me(a, db);
          cv.put("by_role", me == null ? "" : Ui.nz(me.get("role")));
          cv.put("created", LocalDateTime.now().withNano(0).toString());
          db.insert(Counsel.TABLE, cv);
        } else db.update(Counsel.TABLE, cv, Long.parseLong(old.get("id")));
        Sync.kick(a);
        a.render();
        return true;
      }
    });
  }

  static build(db, p) {
    const L = 0xFFEEF4F7, frac = Consent.frac;
    const f = new FormDoc();
    f.upper = "";
    f.college = "Tirunelveli Medical College Hospital";
    f.address = "Tirunelveli";
    f.dept = "Department of Medicine";
    f.title = "RECORD OF COUNSELLING OF RELATIVES";
    f.footer = "Counselling record – Dept. of Medicine, Tirunelveli Medical College Hospital";
    f.fileBase = "Counselling_" + Ui.nz(p.get("ip_no")).replace(/[^A-Za-z0-9]+/g, "_");
    const pt = f.block("Patient", 0xFF1E3A5F, frac(1.1, 1.6, 1.1, 1.6));
    pt.row(18, new FormDoc.Cell("Name").b().fill(L), new FormDoc.Cell(Ui.nz(p.get("name"))).span(3));
    pt.row(18, new FormDoc.Cell("Age / Sex").b().fill(L), new FormDoc.Cell(Ui.nz(p.get("age")) + " / " + Ui.nz(p.get("sex"))),
        new FormDoc.Cell("IP No.").b().fill(L), new FormDoc.Cell(Ui.nz(p.get("ip_no"))));
    pt.row(18, new FormDoc.Cell("Unit / Ward").b().fill(L), new FormDoc.Cell(Db.unitName(Ui.nz(p.get("home_unit"))) + " / " + Db.unitName(Ui.nz(p.get("location")))),
        new FormDoc.Cell("Admitted").b().fill(L), new FormDoc.Cell(Dates.nice(Ui.nz(p.get("admit_date")))));
    pt.row(18, new FormDoc.Cell("Diagnosis").b().fill(L), new FormDoc.Cell(Ui.nz(p.get("diagnosis"))).span(3));
    const rows = Counsel.forPatient(db, Long.parseLong(p.get("id"))).slice().reverse();
    const lg = f.block("Counselling (oldest first)", Counsel.COLOR, frac(1, 3.2, 1.2, 1.2));
    lg.row(16, new FormDoc.Cell("Date / time").b().fill(L), new FormDoc.Cell("Who was told and what").b().fill(L),
        new FormDoc.Cell("Relative's signature").b().fill(L), new FormDoc.Cell("Doctor's signature").b().fill(L));
    for (const r of rows)
      lg.row(40, new FormDoc.Cell(Dates.nice(Ui.nz(r.get("date"))) + "\n" + Ui.nz(r.get("time"))).size(8), new FormDoc.Cell(Counsel.line(r)).size(8),
          new FormDoc.Cell(""), new FormDoc.Cell(Ui.nz(r.get("by_name"))).size(7).bottom());
    return f;
  }

  static print(a, db, p) {
    new AlertDialog.Builder(a).setTitle("Counselling record")
        .setItems(["PDF (open / print)", "PDF (share)", "Word"], {
          onClick: (di, w) => {
            try {
              const f = Counsel.build(db, p);
              const rel = w === 2 ? f.docx(a) : f.pdf(a);
              if (w === 0) Store.openWith(a, rel);
              else Store.share(a, rel, "Counselling record " + Ui.nz(p.get("name")));
            } catch (e) {
              Ui.toast(a, "Could not make the file: " + (e.getMessage ? e.getMessage() : e));
            }
          }
        }).setNegativeButton("Cancel", null).show();
  }
}
;
/* ---- app/Countdown.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Countdown clocks (10.10, idea 150): everything with a time on a patient, ticking down. Protocol steps (the next dose or
 * check), results expected back, and timers a doctor sets ("repeat K at 6 PM", stored as a task with a date and time).
 * Each in-patient's card shows the soonest one; the "Due soon" screen lists them all with live clocks; an alarm rings when
 * a timer is due. No AI: only the times already recorded.
 */
class Countdown {
  static COLOR = 0xFFEA580C;
  static N_TIMER = 7223;
  static TIMER = "Timer";
  static timer = null;

  static Item = class {
    constructor(pid, what, kind, due) {
      this.pid = pid; this.what = what; this.kind = kind; this.due = due;
    }
  };

  static now() {
    return LocalDateTime.of(Dates.today(), Dates.time());
  }

  /** Everything with a time for in-patients (pid 0: all of them), soonest first. */
  static items(db, pid) {
    const out = [];
    const one = pid > 0 ? " AND p.id=" + pid : "";
    // protocol steps
    for (const r of db.rows("SELECT r.* FROM " + Protocols.TABLE + " r JOIN patients p ON p.id=r.patient_id WHERE r.ended='' AND p.status='IN'" + one)) {
      const p = Protocols.byId(r.get("protocol"));
      if (p == null) continue;
      const id = Ui.toLong(r.get("patient_id"), 0);
      for (const t of p.tracks) {
        const d = Protocols.due(r, p, t);
        if (d != null) out.push(new Countdown.Item(id, t.label + " (" + p.name + ")", "⏱", d));
      }
    }
    // results expected back
    for (const r of db.rows("SELECT r.patient_id, r.test, r.due FROM inv_sent r JOIN patients p ON p.id=r.patient_id WHERE r.status='' AND r.due<>'' AND p.status='IN'" + one)) {
      const d = Protocols.parse(r.get("due"));
      if (d != null) out.push(new Countdown.Item(Ui.toLong(r.get("patient_id"), 0), Ui.nz(r.get("test")) + " result", "🧪", d));
    }
    // timers and tasks with a time
    for (const r of db.rows("SELECT t.patient_id, t.text, t.due FROM tasks t JOIN patients p ON p.id=t.patient_id WHERE t.done='' AND length(t.due)=16 AND p.status='IN'" + one)) {
      const d = Protocols.parse(r.get("due"));
      if (d != null) out.push(new Countdown.Item(Ui.toLong(r.get("patient_id"), 0), Ui.nz(r.get("text")), "⏰", d));
    }
    out.sort((a, b) => a.due.compareTo(b.due));
    return out;
  }

  static next(db, pid) {
    const l = Countdown.items(db, pid);
    return l.length === 0 ? null : l[0];
  }

  /** "in 1 h 05 min", "in 4:32" (under 10 minutes, with seconds), "DUE NOW", "OVERDUE 12 min". */
  static left(due, now, secNow) {
    const s = Duration.between(now, due).getSeconds() - secNow;
    if (s <= 0 && s > -60) return "DUE NOW";
    if (s < 0) {
      const m = Math.trunc(-s / 60);
      return "OVERDUE " + (m >= 60 ? Math.trunc(m / 60) + " h " + m % 60 + " min" : m + " min");
    }
    if (s < 600) return "in " + Math.trunc(s / 60) + ":" + jfmt("%02d", s % 60);
    const m = Math.trunc((s + 59) / 60);
    if (m < 60) return "in " + m + " min";
    if (m < 24 * 60) return "in " + Math.trunc(m / 60) + " h " + jfmt("%02d", m % 60) + " min";
    return "in " + Math.trunc(m / (24 * 60)) + " d";
  }

  static color(due, now) {
    const m = Duration.between(now, due).toMinutes();
    return m < 0 ? Ui.RED : m < 30 ? Countdown.COLOR : Ui.TEAL;
  }

  /** The pill on a patient's card: the soonest timed thing in the next 24 hours, or null. */
  static pill(a, db, pid) {
    const i = Countdown.next(db, pid);
    const now = Countdown.now();
    if (i == null || Duration.between(now, i.due).toHours() >= 24) return null;
    const what = i.what.length > 22 ? i.what.substring(0, 21) + "…" : i.what;
    return Ui.softPill(a, i.kind + " " + what + " " + Countdown.left(i.due, now, 0), Countdown.color(i.due, now));
  }

  /** "Set a timer": what, and when (in so many minutes, or at a time). Stored as a task so it shows everywhere tasks do. */
  static timerDialog(a, db, pid) {
    const f = new Form(a);
    f.suggest("text", "What is due", "", ["Repeat potassium", "Repeat sugar", "Repeat ABG", "Antibiotic dose", "Check urine output", "Review BP",
      "Repeat ECG", "Recheck GCS", "Stop the infusion", "Call relatives"]);
    const ins = ["15", "30", "60", "120", "240", "360", "at"];
    f.choice("in", "When", ["15 min", "30 min", "1 hour", "2 hours", "4 hours", "6 hours", "At a time"], ins, "60", {
      changed: (v) => { f.show("at", "at" === v); }
    });
    f.time("at", "Time", Dates.now());
    f.show("at", false);
    Ui.formDialog(a, "⏰ Set a timer", f, "Start", {
      run: () => {
        if (!f.require("text", "Write what is due")) return false;
        const now = Countdown.now();
        let due;
        if ("at" === f.get("in")) {
          const t = LocalTime.parse(f.get("at"));
          due = LocalDateTime.of(Dates.today(), t);
          if (!due.isAfter(now)) due = due.plusDays(1);
        } else due = now.plusMinutes(Ui.toInt(f.get("in"), 60));
        const cv = new ContentValues();
        cv.put("patient_id", pid);
        cv.put("kind", Countdown.TIMER);
        cv.put("text", f.get("text").trim());
        cv.put("due", Protocols.stamp(due));
        cv.put("by_name", CallDutyActivity.myName(a));
        cv.put("time", Dates.todayIso() + " " + Dates.now());
        db.insert("tasks", cv);
        Countdown.schedule(a);
        Ui.toast(a, "Timer set for " + due.toLocalTime());
        a.render();
        return true;
      }
    });
  }

  /** Patient page: the patient's clocks and the "Set a timer" button. */
  static section(a, db, pid) {
    const box = Ui.v(a);
    const l = Countdown.items(db, pid);
    box.addView(Ui.heading(a, "Countdown clocks" + (l.length === 0 ? "" : "  ·  " + l.length), Countdown.COLOR));
    const card = Ui.card(a);
    const now = Countdown.now();
    if (l.length === 0) card.addView(Ui.muted(a, "Nothing timed yet. Set a timer (\"repeat K at 6 PM\"), or start a protocol or send a test with an expected time."));
    for (const i of l) {
      const row = Ui.h(a);
      row.setPadding(0, Ui.dp(a, 4), 0, Ui.dp(a, 4));
      const w = Ui.tv(a, i.kind + "  " + i.what, 14, Ui.TEXT, false);
      row.addView(w, Ui.weight(1));
      row.addView(Ui.softPill(a, Countdown.left(i.due, now, 0), Countdown.color(i.due, now)));
      card.addView(row);
    }
    const add = Ui.outlineButton(a, "⏰ Set a timer", Countdown.COLOR, { onClick: () => { Countdown.timerDialog(a, db, pid); } });
    card.addView(add);
    Ui.margins(add, 0, 8, 0, 0);
    box.addView(card);
    return box;
  }

  /** Home card: how many things fall due in the next hour (and how many are overdue); null when none. */
  static homeCard(a, db) {
    const now = Countdown.now();
    let soon = 0, late = 0;
    for (const i of Countdown.items(db, 0)) {
      const m = Duration.between(now, i.due).toMinutes();
      if (m < 0) late++;
      else if (m <= 60) soon++;
    }
    if (soon + late === 0) return null;
    const c = late > 0 ? Ui.RED : Countdown.COLOR;
    const card = a.entryCard("COUNTDOWN", c, "⏱ " + (soon > 0 ? soon + " due in the next hour" : "") + (soon > 0 && late > 0 ? "  ·  " : "") + (late > 0 ? late + " overdue" : ""),
        "Protocol steps, results expected and timers, ticking live.", null, a.opener(CountdownActivity));
    const g = Ui.round(a, Ui.mix(c, Color.WHITE, 0.92), 18);
    g.setStroke(Ui.dp(a, 2), c);
    card.setBackground(g);
    return card;
  }

  // ---------------------------------------------------------------- the alarm for timers

  static timers(db) {
    return db.rows("SELECT t.*, p.location, p.bed FROM tasks t JOIN patients p ON p.id=t.patient_id WHERE t.done='' AND t.kind=? AND length(t.due)=16 AND p.status='IN' ORDER BY t.due", Countdown.TIMER);
  }

  static schedule(c) {
    const app = c.getApplicationContext();
    const db = Db.get(app);
    const told = app.getSharedPreferences("countdown", Context.MODE_PRIVATE).getString("told", "");
    let soon = null;
    for (const t of Countdown.timers(db)) {
      if (("," + told + ",").contains("," + t.get("id") + ",")) continue;
      const d = Protocols.parse(t.get("due"));
      if (d != null && (soon == null || d.isBefore(soon))) soon = d;
    }
    // Web: in place of AlarmManager, a timer while the page is open
    if (Countdown.timer != null) {
      clearTimeout(Countdown.timer);
      Countdown.timer = null;
    }
    if (soon == null) return;
    const now = Countdown.now();
    if (soon.isBefore(now)) soon = now.plusMinutes(1);
    const delay = Math.min(Math.max(1000, Protocols.millis(soon) - System.currentTimeMillis()), 2147483000);
    Countdown.timer = setTimeout(() => {
      Countdown.timer = null;
      try {
        new Countdown.Receiver().onReceive(app, new Intent(app, Countdown.Receiver).setAction("com.tvmchmed.app.TIMER"));
      } catch (ignored) {
        // the screen still shows DUE NOW
      }
    }, delay);
  }

  /** Timers that just fell due: one notification (bed and what, no name), each timer once. */
  static notifyDue(c) {
    const db = Db.get(c);
    const p = c.getSharedPreferences("countdown", Context.MODE_PRIVATE);
    const told = p.getString("told", "");
    const now = Countdown.now();
    let s = "";
    const keep = [];
    let first = -1;
    for (const t of Countdown.timers(db)) {
      const id = t.get("id");
      const d = Protocols.parse(t.get("due"));
      if (("," + told + ",").contains("," + id + ",")) { keep.push(id); continue; }
      if (d == null || d.isAfter(now)) continue;
      keep.push(id);
      s += (s.length === 0 ? "" : "\n") + Protocols.where(t) + ": " + Ui.nz(t.get("text"));
      if (first < 0) first = Ui.toLong(t.get("patient_id"), -1);
    }
    p.edit().putString("told", keep.join(",")).apply();
    if (s.length === 0) return;
    const open = first > 0 ? new Intent(c, PatientActivity).putExtra("id", String(first)) : new Intent(c, CountdownActivity);
    Background.show(c, Countdown.N_TIMER, "⏰ Timer due", s, Countdown.COLOR, open);
  }
}

Countdown.Receiver = class extends BroadcastReceiver {
  onReceive(context, intent) {
    try {
      Countdown.notifyDue(context);
    } finally {
      Countdown.schedule(context);
    }
  }
};
;
