/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** DAP duty register: one entry per 24-hour Duty Assistant Professor shift. */
class DapActivity extends Base {
  constructor() {
    super();
    this.mode = 0;
    this.day = Dates.today();
  }

  onCreate(b) {
    super.onCreate(b);
    this.mode = "1" === this.getIntent().getStringExtra("mode") ? 1 : 0;
    this.setTitle("DAP duty register");
    this.subtitle = "Duty Assistant Professor · 7:30 AM to 7:30 AM";
    this.headerAction("+ Entry", this.opener(FormActivity, "kind", "dap"));
  }

  render() {
    const db = this.db;
    const page = Ui.v(this);
    page.addView(this.modeBar());
    if (this.mode === 1) {
      this.headerAction("+ Roster", this.opener(RosterFormActivity, "date", this.day.toString()));
      this.roster(page);
      this.setPage(page);
      return;
    }
    this.headerAction("+ Entry", this.opener(FormActivity, "kind", "dap"));
    const iso = Dates.todayIso();
    const today = db.row("SELECT * FROM dap WHERE date=? ORDER BY id DESC LIMIT 1", iso);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.HERO, 20));
    hero.addView(Ui.tv(this, "Today · " + Dates.longFmt(Dates.today()), 13, 0xD9FFFFFF, true));
    if (today == null) {
      hero.addView(Ui.tv(this, "Today's DAP entry not made yet", 18, Color.WHITE, true));
      const b = Ui.tv(this, "+  Make today's entry", 15, Ui.PRIMARY, true);
      b.setGravity(Gravity.CENTER);
      b.setBackground(Ui.round(this, Color.WHITE, 12));
      b.setPadding(0, Ui.dp(this, 11), 0, Ui.dp(this, 11));
      Ui.ripple(b, Ui.alpha(Ui.PRIMARY, 0x33));
      b.setOnClickListener(this.opener(FormActivity, "kind", "dap"));
      hero.addView(b);
      Ui.margins(b, 0, 12, 0, 0);
    } else {
      hero.addView(Ui.tv(this, today.get("dap_name"), 20, Color.WHITE, true));
      hero.addView(Ui.tv(this, "Admitting: " + Db.unitName(today.get("unit")), 13, 0xD9FFFFFF, false));
      const s = Ui.statRow(this, this.ws(today.get("admissions"), "Admitted"), this.ws(today.get("abscond"), "Absconded"),
          this.ws(today.get("ama"), "AMA"), this.ws(today.get("deaths"), "Deaths"), this.ws(today.get("census"), "Census"));
      s.setBackground(Glass.frost(this, 14));
      s.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 10));
      hero.addView(s);
      Ui.margins(s, 0, 12, 0, 0);
      Ui.ripple(hero, 0x33FFFFFF);
      hero.setOnClickListener(this.opener(FormActivity, "kind", "dap", "id", today.get("id")));
    }
    page.addView(hero);

    // 9.97: escalated alerts first, then the report made from the records and the beds
    const esc = DapReportActivity.escalationCard(this, db);
    if (esc != null) page.addView(esc);
    const rb = Ui.v(this);
    rb.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), 0);
    rb.addView(Ui.button(this, "📋 DAP report (made automatically)", DapDuty.COLOR, this.opener(DapReportActivity)));
    page.addView(rb);
    page.addView(DapReportActivity.bedsCard(this, db));

    const t = Dates.today();
    const m0 = Dates.monthStart(t).toString();
    page.addView(Ui.heading(this, Dates.month(t) + " totals", Ui.PRIMARY));
    const tot = Ui.card(this);
    tot.addView(Ui.statRow(this,
        Ui.stat(this, String(db.num("SELECT SUM(admissions) FROM dap WHERE date BETWEEN ? AND ?", m0, iso)), "Admitted", Ui.PRIMARY),
        Ui.stat(this, String(db.num("SELECT SUM(abscond) FROM dap WHERE date BETWEEN ? AND ?", m0, iso)), "Absconded", Ui.ORANGE),
        Ui.stat(this, String(db.num("SELECT SUM(ama) FROM dap WHERE date BETWEEN ? AND ?", m0, iso)), "AMA", Ui.AMBER),
        Ui.stat(this, String(db.num("SELECT SUM(deaths) FROM dap WHERE date BETWEEN ? AND ?", m0, iso)), "Deaths", Ui.SLATE)));
    tot.addView(Ui.muted(this, db.num("SELECT COUNT(*) FROM dap WHERE date BETWEEN ? AND ?", m0, iso) + " duty days logged this month"));
    page.addView(tot);

    page.addView(Ui.heading(this, "Register", Ui.PRIMARY));
    const rows = db.rows("SELECT * FROM dap ORDER BY date DESC, id DESC LIMIT 120");
    if (rows.isEmpty()) page.addView(this.emptyNote("No duty entries yet."));
    for (const r of rows) {
      const n = DapActivity.n;
      const counts = "Adm " + n(r.get("admissions")) + " · Abscond " + n(r.get("abscond")) + " · AMA " + n(r.get("ama"))
          + " · Deaths " + n(r.get("deaths")) + " · Census " + n(r.get("census"));
      const sub = counts + (r.get("issues").isEmpty() ? "" : "\nIssues: " + r.get("issues"));
      page.addView(this.entryCard(Db.shortName(r.get("unit")), Ui.unitColor(r.get("unit")), r.get("dap_name"), sub,
          Dates.nice(r.get("date")), this.opener(FormActivity, "kind", "dap", "id", r.get("id"))));
    }
    this.setPage(page);
  }

  static n(s) {
    return s == null || s.isEmpty() ? "0" : s;
  }

  ws(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    const a = Ui.tv(this, DapActivity.n(v), 20, Color.WHITE, true);
    a.setGravity(Gravity.CENTER);
    l.addView(a);
    const b = Ui.tv(this, label, 11, 0xCCFFFFFF, false);
    b.setGravity(Gravity.CENTER);
    l.addView(b);
    return l;
  }

  modeBar() {
    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const labels = ["DAP register", "Daily duty roster"];
    for (let i = 0; i < labels.length; i++) {
      const idx = i;
      const t = Ui.tv(this, labels[i], 14, i === this.mode ? Ui.PRIMARY : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      if (i === this.mode) t.setBackground(Ui.round(this, 0xFFFFFFFF, 11));
      t.setOnClickListener({ onClick: (v) => { this.mode = idx; this.render(); } });
      seg.addView(t, Ui.weight(1));
    }
    Ui.margins(seg, 12, 4, 12, 4);
    return seg;
  }

  // ---------- daily duty roster ----------

  roster(page) {
    const db = this.db;
    const r = db.row("SELECT * FROM duty_roster WHERE date=? ORDER BY id DESC LIMIT 1", this.day.toString());
    const nav = Ui.card(this);
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.addView(Ui.outlineButton(this, "‹", Ui.PRIMARY, { onClick: (v) => { this.day = this.day.minusDays(1); this.render(); } }));
    const mid = Ui.v(this);
    mid.setGravity(Gravity.CENTER);
    mid.addView(Ui.tv(this, this.day.equals(Dates.today()) ? "Today" : this.day.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH), 12, Ui.MUTED, false));
    mid.addView(Ui.tv(this, Dates.longFmt(this.day), 15, Ui.TEXT, true));
    row.addView(mid, Ui.weight(1));
    row.addView(Ui.outlineButton(this, "›", Ui.PRIMARY, { onClick: (v) => { this.day = this.day.plusDays(1); this.render(); } }));
    nav.addView(row);
    page.addView(nav);

    if (r == null) {
      const c = Ui.card(this);
      c.addView(Ui.title(this, "No duty roster for this day yet"));
      c.addView(Ui.muted(this, "Enter the faculty, DAP, PGs and CRRIs on duty, or paste the morning roster message from WhatsApp."));
      const b = Ui.button(this, "+  Enter duty roster", Ui.PRIMARY, this.opener(RosterFormActivity, "date", this.day.toString()));
      c.addView(b);
      Ui.margins(b, 0, 12, 0, 0);
      page.addView(c);
      const recent = db.rows("SELECT date, unit, dap FROM duty_roster ORDER BY date DESC LIMIT 14");
      if (!recent.isEmpty()) page.addView(Ui.heading(this, "Recent rosters", Ui.PRIMARY));
      for (const m of recent) {
        page.addView(this.entryCard(Db.shortName(m.get("unit")), Ui.unitColor(m.get("unit")), Dates.longFmt(Dates.parse(m.get("date"))),
            "DAP: " + Roster.name(Ui.nz(m.get("dap")).jsplit("\n")[0]), "", { onClick: (v) => { this.day = Dates.parse(m.get("date")); this.render(); } }));
      }
      return;
    }

    const unit = Ui.nz(r.get("unit"));
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Ui.unitColor(unit)), 20));
    hero.addView(Ui.tv(this, "Admission day · " + Db.unitName(unit), 13, 0xE6FFFFFF, true));
    const chief = Ui.nz(r.get("chief")).trim();
    if (!chief.isEmpty()) hero.addView(Ui.tv(this, "Chief: " + Roster.name(chief.jsplit("\n")[0]), 18, Color.WHITE, true));
    const dap = Ui.nz(r.get("dap")).trim();
    if (!dap.isEmpty()) hero.addView(Ui.tv(this, "DAP: " + Roster.name(dap.jsplit("\n")[0]), 15, Color.WHITE, false));
    const acts = Ui.h(this);
    const share = Ui.tv(this, "Share on WhatsApp", 14, Ui.unitColor(unit), true);
    share.setGravity(Gravity.CENTER);
    share.setBackground(Ui.round(this, Color.WHITE, 12));
    share.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 10));
    share.setOnClickListener({ onClick: (v) => { ReportActivity.shareText(this, Roster.shareText(db, r)); } });
    acts.addView(share, Ui.weight(1));
    const edit = Ui.tv(this, "Edit", 14, Color.WHITE, true);
    edit.setGravity(Gravity.CENTER);
    edit.setBackground(Ui.round(this, 0x33FFFFFF, 12));
    edit.setPadding(Ui.dp(this, 22), Ui.dp(this, 10), Ui.dp(this, 22), Ui.dp(this, 10));
    edit.setOnClickListener(this.opener(RosterFormActivity, "date", this.day.toString()));
    acts.addView(edit);
    Ui.margins(edit, 8, 0, 0, 0);
    hero.addView(acts);
    Ui.margins(acts, 0, 12, 0, 0);
    page.addView(hero);

    for (let g = 0; g < Roster.FIELDS.length; g++) {
      let any = false;
      for (const f of Roster.FIELDS[g]) if (!Ui.nz(r.get(f[0])).trim().isEmpty()) any = true;
      if (!any) continue;
      page.addView(Ui.heading(this, Roster.GROUPS[g], g === 0 ? Ui.unitColor(unit) : g === 4 ? Ui.unitColor(Db.IMCU) : g === 5 ? Ui.unitColor(Db.CCB) : g === 6 ? Ui.unitColor(Db.FEVER) : Ui.PRIMARY));
      const card = Ui.card(this);
      let first = true;
      for (const f of Roster.FIELDS[g]) {
        const v = Ui.nz(r.get(f[0])).trim();
        if (v.isEmpty()) continue;
        const lab = Ui.tv(this, f[1], 12, Ui.MUTED, true);
        lab.setPadding(0, first ? 0 : Ui.dp(this, 10), 0, Ui.dp(this, 2));
        card.addView(lab);
        first = false;
        for (const line of v.jsplit("\n")) if (!line.trim().isEmpty()) card.addView(this.personRow(line));
      }
      page.addView(card);
    }
    if (!Ui.nz(r.get("notes")).trim().isEmpty()) {
      const n = Ui.card(this);
      n.addView(Ui.kv(this, "Notes", r.get("notes")));
      page.addView(n);
    }
  }

  /** One person on duty; tap the phone to call. */
  personRow(line) {
    // 10.13: the full name on its own line, the phone and WhatsApp under it (user asked)
    const box = Ui.v(this);
    box.setPadding(0, Ui.dp(this, 3), 0, Ui.dp(this, 5));
    box.addView(Ui.tv(this, Roster.name(line), 15, Ui.TEXT, false));
    const row = Ui.h(this);
    row.setPadding(0, Ui.dp(this, 3), 0, 0);
    box.addView(row);
    const ph = Roster.phone(line);
    if (!ph.isEmpty()) {
      const call = Ui.softPill(this, "📞 " + ph, Ui.GREEN);
      call.setOnClickListener({
        onClick: (v) => {
          try { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + ph))); } catch (ignored) {}
        }
      });
      row.addView(call);
      if (WhatsApp.usable(ph)) {
        const wa = WhatsApp.pill(this, ph);
        row.addView(wa);
        Ui.margins(wa, 6, 0, 0, 0);
      }
    }
    return box;
  }
}
