/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The case summary (with "kind" = case: the patient so far, to share) or the discharge summary, written on the phone from the case sheet: history, examination, investigations and the
 * response to treatment. Each part can be edited before it is saved as Word or PDF.
 */
class DischargeActivity extends Base {
  constructor() {
    super();
    this.caseKind = false;
    this.id = 0;
    this.p = null;
    this.data = null;
    this.boxes = new JMap();
    /** Other units see and share the summary but cannot change it (CaseSheet.canEdit). */
    this.editable = true;
  }

  static EDITS = "summary_edit";
  static CASE_EDITS = "case_summary_edit";
  static CASE = "case";
  /** Beside each set of edits: the case sheet text each edit replaced, to notice later case sheet changes. */
  static BASE = "_base";

  /** The free chat apps: name, Android package, web address when the app isn't installed. */
  static $clinit() {
    DischargeActivity.CHAT_APPS = [
      ["ChatGPT", "com.openai.chatgpt", "https://chatgpt.com/"],
      ["Claude", Ai.CLAUDE_APP, "https://claude.ai/new"],
      ["Gemini", "com.google.android.apps.bard", "https://gemini.google.com/app"]];
  }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    this.caseKind = DischargeActivity.CASE.equals(this.getIntent().getStringExtra("kind"));
  }

  liveRefresh() {
    return false;
  }

  static generated(db, p, data, caseKind) {
    return caseKind ? CaseSheet.caseSummary(db, p, data) : CaseSheet.summary(db, p, data);
  }

  /** The generated summary with any saved edits laid over it (caseKind defaults to false). */
  static sections(db, p, data, caseKind) {
    if (caseKind === undefined) caseKind = false;
    const gen = DischargeActivity.generated(db, p, data, caseKind);
    const ed = data.optJSONObject(caseKind ? DischargeActivity.CASE_EDITS : DischargeActivity.EDITS);
    const base = data.optJSONObject((caseKind ? DischargeActivity.CASE_EDITS : DischargeActivity.EDITS) + DischargeActivity.BASE);
    const out = new JMap();
    for (const e of gen.entrySet()) {
      // an edit stands until the case sheet part it was made from changes; then the case sheet wins again
      const stale = base != null && base.has(e.getKey()) && !base.optString(e.getKey()).equals(e.getValue().trim());
      const v = ed != null && ed.has(e.getKey()) && !stale ? ed.optString(e.getKey()) : e.getValue();
      out.put(e.getKey(), v);
    }
    return out;
  }

  render() {
    const db = this.db, id = this.id;
    this.p = db.row("SELECT * FROM patients WHERE id=?", String(id));
    const p = this.p;
    this.editable = p == null || CaseSheet.canEdit(this, db, p);
    if (p == null) {
      this.finish();
      return;
    }
    this.data = CaseSheet.load(db, id);
    const caseKind = this.caseKind, editable = this.editable;
    this.setTitle(caseKind ? "Case summary" : "Discharge summary");
    const editsKey = caseKind ? DischargeActivity.CASE_EDITS : DischargeActivity.EDITS;
    const color = caseKind ? Ui.SKY : Ui.TEAL;
    this.subtitle = p.get("name") + (p.get("ip_no").isEmpty() ? "" : "  ·  IP " + p.get("ip_no"));
    this.headerColor(color);
    this.headerAction("Case sheet", {
      onClick: (v) => {
        this.saveEdits(false);
        this.open(CaseSheetActivity, "id", String(id));
      }
    });
    const page = Ui.v(this);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(color), 20));
    const edited = this.data.optJSONObject(editsKey) != null && this.data.optJSONObject(editsKey).length() > 0;
    hero.addView(Ui.tv(this, caseKind ? "The patient so far, ready to share" : "Written from the case sheet", 17, Color.WHITE, true));
    hero.addView(Ui.tv(this, (caseKind ? "Admission, history, examination, the investigations available now and the current treatment. "
        + "Share it on WhatsApp as a message, Word or PDF." : "Made on this phone from the history, examination, investigations and treatment. "
        + "Check and edit any part below, then save it as Word or PDF.") + (edited ? "\nSome parts have your edits." : ""), 13, 0xD9FFFFFF, false));
    const row = Ui.buttonRow(this,
        Ui.button(this, "Word (.docx)", Ui.PRIMARY, {
          onClick: (v) => { this.export(false); }
        }),
        Ui.button(this, "PDF", Ui.RED, {
          onClick: (v) => { this.export(true); }
        }),
        Ui.button(this, "Message", Ui.GREEN, {
          onClick: (v) => { this.shareText(); }
        }));
    hero.addView(row);
    Ui.margins(row, 0, 10, 0, 0);
    if (!caseKind) {
      const form = Ui.button(this, "📄  TVMC discharge form (PDF / Word)", FormDoc.NAVY, {
        onClick: (v) => { this.askForm(); }
      });
      hero.addView(form);
      Ui.margins(form, 0, 8, 0, 0);
    }
    // AI rewrite of the case summary, and (8.30) the whole discharge summary in one tap from the case sheet and the stay
    if (editable) {
      const ai = Ui.button(this, caseKind ? "✨  Write with AI" : "✨  Write the whole summary with AI", Ui.PURPLE, {
        onClick: (v) => { this.askAi(); }
      });
      hero.addView(ai);
      Ui.margins(ai, 0, 8, 0, 0);
    }
    if (editable && Ai.prefs(this).getBoolean(this.pendingKey(), false)) {
      const paste = Ui.button(this, "📋  Paste the AI answer", Ui.AMBER, {
        onClick: (v) => { this.pasteAnswer(); }
      });
      hero.addView(paste);
      Ui.margins(paste, 0, 8, 0, 0);
      const how = Ui.tv(this, "In " + Ai.prefs(this).getString(this.pendingKey() + "_app", "the AI app") + ", tap Copy under the answer, then come back here and tap Paste.", 12, 0xE6FFFFFF, false);
      hero.addView(how);
      Ui.margins(how, 0, 6, 0, 0);
    }
    const aiWhen = this.data.optString(DischargeActivity.aiKey(caseKind));
    if (!aiWhen.isEmpty()) {
      const n = Ui.tv(this, "Written by " + this.data.optString(DischargeActivity.aiKey(caseKind) + "_by", "Claude AI") + " on " + aiWhen + ". Check every part before you share it.", 12, 0xE6FFFFFF, true);
      hero.addView(n);
      Ui.margins(n, 0, 8, 0, 0);
    }
    page.addView(hero);
    // 9.30: the unit's Assistant Professor checks and approves the discharge summary before it is printed
    if (!caseKind) page.addView(SignOff.bar(this, this.db, this.p, SignOff.DISCHARGE, { run: () => { this.saveEdits(false); } },
      { run: () => { this.render(); } }));

    let filled = 0;
    for (const s of CaseSheet.SECTIONS) if (CaseSheet.filled(this.data, s)) filled++;
    if (filled < 4) {
      const warn = Ui.card(this);
      warn.addView(Ui.tv(this, "The case sheet is mostly empty", 15, Ui.ORANGE, true));
      warn.addView(Ui.muted(this, "Fill the complaints, examination, investigations and treatment in the case sheet; the summary is written from them."));
      const go = Ui.outlineButton(this, "Open case sheet", Ui.ORANGE, this.opener(CaseSheetActivity, "id", String(id)));
      warn.addView(go);
      Ui.margins(go, 0, 8, 0, 0);
      page.addView(warn);
    }

    this.boxes.clear();
    const ed = this.data.optJSONObject(editsKey);
    for (const e of DischargeActivity.sections(db, p, this.data, caseKind).entrySet()) {
      const mine = ed != null && ed.has(e.getKey());
      page.addView(Ui.heading(this, e.getKey() + (mine ? "  (edited)" : ""), color));
      const card = Ui.card(this);
      const t = new EditText(this);
      t.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
      t.setSingleLine(false);
      t.setMinLines(1);
      t.setTextSize(15);
      t.setTextColor(Ui.TEXT);
      t.setBackground(null);
      t.setPadding(0, 0, 0, 0);
      t.setText(e.getValue());
      card.addView(t);
      if (!editable) {
        t.setFocusable(false);
        t.setKeyListener(null);
      }
      this.boxes.put(e.getKey(), t);
      page.addView(card);
    }

    if (!editable) {
      page.addView(this.emptyNote("🔒  View only: this summary belongs to " + CaseSheet.ownerLabel(p) + ". Only its faculty, PGs and CRMIs, the admin and the HOD can change it."));
      this.setPage(page);
      return;
    }
    const more = Ui.card(this);
    more.addView(Ui.buttonRow(this,
        Ui.outlineButton(this, "Save edits", Ui.GREEN, {
          onClick: (v) => {
            this.saveEdits(true);
            this.render();
          }
        }),
        Ui.outlineButton(this, "Rewrite from case sheet", Ui.ORANGE, {
          onClick: (v) => {
            Ui.confirm(this, "Rewrite the summary?", "Your edits on this screen are dropped and the summary is written again from the case sheet.", "Rewrite", {
              run: () => {
                this.data.remove(editsKey);
                this.data.remove(editsKey + DischargeActivity.BASE);
                this.data.remove(DischargeActivity.aiKey(caseKind));
                this.data.remove(DischargeActivity.aiKey(caseKind) + "_by");
                Ai.prefs(this).edit().remove(this.pendingKey()).apply();
                CaseSheet.save(db, id, this.data);
                this.render();
              }
            });
          }
        })));
    page.addView(more);
    this.setPage(page);
  }

  onPause() {
    super.onPause();
    this.saveEdits(false);
  }

  /** Keeps every part that differs from what the case sheet would write. */
  saveEdits(toast) {
    const data = this.data;
    if (this.p == null || data == null || this.boxes.isEmpty() || !this.editable) return;
    const gen = DischargeActivity.generated(this.db, this.p, data, this.caseKind);
    const editsKey = this.caseKind ? DischargeActivity.CASE_EDITS : DischargeActivity.EDITS;
    const ed = new JSONObject(), base = new JSONObject();
    try {
      for (const e of this.boxes.entrySet()) {
        const v = e.getValue().getText().toString().trim();
        const g = gen.containsKey(e.getKey()) ? gen.get(e.getKey()).trim() : "";
        if (!v.equals(g)) {
          ed.put(e.getKey(), v);
          base.put(e.getKey(), g);
        }
      }
      if (ed.length() > 0) {
        data.put(editsKey, ed);
        data.put(editsKey + DischargeActivity.BASE, base);
      } else {
        data.remove(editsKey);
        data.remove(editsKey + DischargeActivity.BASE);
      }
    } catch (ignored) {
      if (!(ignored instanceof JSONException)) throw ignored;
    }
    CaseSheet.save(this.db, this.id, data);
    if (toast) Ui.toast(this, ed.length() > 0 ? "Edits saved" : "No edits; the summary follows the case sheet");
  }

  /** The case sheet's course was rewritten: drop old summary edits of the course so the new one shows. */
  static forgetCourseEdits(data) {
    const k = [[DischargeActivity.EDITS, "Course in the hospital"], [DischargeActivity.CASE_EDITS, "Course so far"]];
    for (const x of k) {
      const ed = data.optJSONObject(x[0]), base = data.optJSONObject(x[0] + DischargeActivity.BASE);
      if (ed != null) ed.remove(x[1]);
      if (base != null) base.remove(x[1]);
      if (ed != null && ed.length() === 0) {
        data.remove(x[0]);
        data.remove(x[0] + DischargeActivity.BASE);
      }
    }
  }

  static aiKey(caseKind) {
    return caseKind ? "ai_case_summary" : "ai_summary";
  }

  /** The parts as they stand on screen now. */
  current() {
    const out = new JMap();
    for (const e of this.boxes.entrySet()) out.put(e.getKey(), e.getValue().getText().toString());
    return out;
  }

  /** What the AI is given: the headings on screen and, for the discharge summary, the whole stay from the timeline. */
  aiSecs() {
    const secs = this.current();
    if (!this.caseKind) {
      const rec = DischargeAi.record(this.db, this.id);
      if (!rec.isEmpty()) secs.put(DischargeAi.SOURCE, rec);
    }
    return secs;
  }

  askAi() {
    const eng = Ai.engines(this);
    if (!this.caseKind && eng.size() === 1) {
      this.askPaid(eng.get(0));   // one tap: the only AI set up writes it
      return;
    }
    const items = [];
    for (const x of eng) items.add(Ai.engineLabel(x));
    items.add("Free: ChatGPT, Claude or Gemini app");
    if (eng.isEmpty()) items.add("Write here: add a free Gemini key or a Claude key");
    new AlertDialog.Builder(this).setTitle("Write with AI")
        .setItems(ArrayList(items), {
          onClick: (d, w) => {
            if (w < eng.size()) this.askPaid(eng.get(w));
            else if (w === eng.size()) this.askFree();
            else this.open(SettingsActivity);
          }
        }).setNegativeButton("Cancel", null).show();
  }

  pendingKey() {
    return "pending_" + this.id + (this.caseKind ? "_case" : "");
  }

  askFree() {
    const names = new Array(DischargeActivity.CHAT_APPS.length).fill(null);
    for (let i = 0; i < names.length; i++) names[i] = DischargeActivity.CHAT_APPS[i][0];
    new AlertDialog.Builder(this).setTitle("Which AI app?").setItems(names, {
      onClick: (d, w) => { this.freeSteps(DischargeActivity.CHAT_APPS[w]); }
    }).setNegativeButton("Cancel", null).show();
  }

  freeSteps(app) {
    const n = app[0];
    const privacy = n.equals("Claude") ? "" : "\n\nTip: in " + n + "'s settings, turn off " + (n.equals("ChatGPT") ? "\"Improve the model for everyone\"" : "\"Gemini Apps Activity\"")
        + " so the case is not used to train it.";
    Ui.confirm(this, "Use " + n + " (free)", "The summary opens in " + n + " with the patient's name, IP number, phone, address and CMCHIS number "
        + "taken out. It is also copied, so you can paste it there if it doesn't appear.\n\n"
        + "1. Send it in " + n + " and wait for the answer.\n2. Tap Copy under the answer.\n"
        + "3. Come back here and tap \"Paste the AI answer\". Then save it as Word or PDF.\n\n"
        + "Needs the free " + n + " app or website, signed in." + privacy, "Open " + n, {
      run: () => { this.sendToChatApp(app); }
    });
  }

  sendToChatApp(app) {
    this.saveEdits(false);
    const prompt = Ai.chatPrompt(this.caseKind, this.aiSecs(), this.p);
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Summary for AI", prompt));
    Ai.prefs(this).edit().putBoolean(this.pendingKey(), true).putString(this.pendingKey() + "_app", app[0]).apply();
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, prompt);
    i.setPackage(app[1]);
    try {
      this.startActivity(i);
      Ui.toast(this, "Copied too: paste it in " + app[0] + " if the box is empty");
    } catch (noApp) {
      try {
        this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(app[2])));
        Ui.toast(this, "Copied: paste it in the message box of " + app[0]);
      } catch (e) {
        Ui.toast(this, "Copied: open " + app[0] + " and paste it");
      }
    }
    this.render();
  }

  pasteAnswer() {
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    let text = "";
    if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
      const t = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
      text = t == null ? "" : t.toString();
    }
    let res;
    try {
      if (text.contains("Reply format: for each heading")) throw new Ai.Failure("That is still the request sent to the AI. In the AI app, tap Copy under its answer first.");
      res = Ai.parseChat(text, this.current());
    } catch (f) {
      if (!(f instanceof Ai.Failure)) throw f;
      new AlertDialog.Builder(this).setTitle("Nothing to paste yet").setMessage(f.getMessage()).setPositiveButton("OK", null).show();
      return;
    }
    const who = Ai.prefs(this).getString(this.pendingKey() + "_app", "AI");
    Ai.prefs(this).edit().remove(this.pendingKey()).remove(this.pendingKey() + "_app").apply();
    this.applyAi(res, who.equals("AI") ? "AI" : who + " (AI)");
  }

  askPaid(engine) {
    Ui.confirm(this, "Write with AI?", "The text below is sent to " + Ai.company(engine) + " to be rewritten. The patient's name, IP number, phone, "
        + "address and CMCHIS number are taken out first; age, sex, dates and the clinical details are sent.\n\n"
        + "The text on this screen is replaced by " + engine + "'s version. Check every part before you share it. "
        + "\"Rewrite from case sheet\" brings back the app's own version.", "Write", {
      run: () => { this.runAi(engine); }
    });
  }

  runAi(engine) {
    this.saveEdits(false);
    const secs = this.aiSecs();
    const pt = this.p;
    const wait = new AlertDialog.Builder(this).setTitle(engine + " is writing…")
        .setMessage("This takes up to a minute. Keep the app open.").setCancelable(false).show();
    new Thread({
      run: () => {
        let got = null;
        let err = null;
        try {
          got = Ai.rewrite(this, engine, this.caseKind, secs, pt);
        } catch (f) {
          if (f instanceof Ai.Failure) err = f.getMessage();
          else err = "Could not write it: " + f.getMessage();
        }
        const res = got;
        const error = err;
        this.runOnUiThread({
          run: () => {
            if (this.isFinishing()) return;
            try { wait.dismiss(); } catch (ignored) { }
            if (error != null) {
              new AlertDialog.Builder(this).setTitle("AI summary not written").setMessage(error)
                  .setPositiveButton("OK", null).show();
              return;
            }
            this.applyAi(res, engine + " AI");
          }
        });
      }
    }).start();
  }

  applyAi(res, who) {
    for (const e of res.entrySet()) {
      const t = this.boxes.get(e.getKey());
      if (t != null) t.setText(e.getValue());
    }
    this.saveEdits(false);
    try {
      this.data.put(DischargeActivity.aiKey(this.caseKind) + "_by", who);
      this.data.put(DischargeActivity.aiKey(this.caseKind), Dates.nice(Dates.today().toString()) + " " + LocalTime.now().withSecond(0).withNano(0));
    } catch (ignored) {
      if (!(ignored instanceof JSONException)) throw ignored;
    }
    CaseSheet.save(this.db, this.id, this.data);
    Ui.toast(this, "Written by " + who + ". Check it before sharing.");
    this.render();
  }

  /** The summary as plain text, to paste into WhatsApp or SMS. */
  static asText(db, p, secs, caseKind) {
    const b = new StringBuilder();
    b.append("*").append(caseKind ? "CASE SUMMARY" : "DISCHARGE SUMMARY").append("*\n");
    const age = Ui.nz(p.get("age"));
    b.append("*").append(p.get("name")).append("*, ").append(age.isEmpty() ? "" : age + " y / ").append(Base.sexLabel(p.get("sex")));
    if (!Ui.nz(p.get("ip_no")).isEmpty()) b.append(", IP ").append(p.get("ip_no"));
    b.append("\n").append(Db.unitName(p.get("home_unit"))).append(", ").append(db.setting("dept", "Department of General Medicine")).append("\n");
    for (const e of secs.entrySet()) {
      if (e.getValue().trim().isEmpty()) continue;
      b.append("\n*").append(e.getKey()).append(":*\n").append(e.getValue().trim()).append("\n");
    }
    return b.toString().trim();
  }

  shareText() {
    this.saveEdits(false);
    this.data = CaseSheet.load(this.db, this.id);
    const p = this.p;
    let text = DischargeActivity.asText(this.db, p, DischargeActivity.sections(this.db, p, this.data, this.caseKind), this.caseKind);
    if (!this.caseKind) text += "\n\n_" + SignOff.printLine(this.db, p, SignOff.DISCHARGE) + "_";
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, text);
    i.putExtra(Intent.EXTRA_SUBJECT, (this.caseKind ? "Case summary of " : "Discharge summary of ") + p.get("name"));
    try {
      this.startActivity(Intent.createChooser(i, "Share as message"));
    } catch (e) {
      Ui.toast(this, "No app to share with");
    }
  }

  export(pdf) {
    this.saveEdits(false);
    if (this.caseKind) {
      this.make(pdf);
      return;
    }
    SignOff.beforePrint(this, this.db, this.p, SignOff.DISCHARGE, { run: () => { this.make(pdf); } }, { run: () => { this.render(); } });
  }

  make(pdf) {
    this.data = CaseSheet.load(this.db, this.id);
    const p = this.p;
    let rel;
    try {
      const secs = DischargeActivity.sections(this.db, p, this.data, this.caseKind);
      if (!this.caseKind) secs.put("Faculty sign-off", SignOff.printLine(this.db, p, SignOff.DISCHARGE));
      const d = SummaryExport.build(this.db, p, secs, this.data);
      if (this.caseKind) SummaryExport.asCaseSummary(d);
      rel = pdf ? SummaryExport.pdf(this, d) : SummaryExport.docx(this, d);
    } catch (e) {
      Ui.toast(this, "Could not make the file: " + e.getMessage());
      return;
    }
    this.showFile(rel, pdf, (this.caseKind ? "Case summary of " : "Discharge summary of ") + p.get("name"));
  }

  /** The department's two-page discharge form, filled from the case sheet; blank boxes are left to write by hand. */
  askForm() {
    new AlertDialog.Builder(this).setTitle("TVMC discharge form")
        .setItems(["PDF", "Word (.docx)"], {
          onClick: (d, w) => { this.exportForm(w === 0); }
        }).setNegativeButton("Cancel", null).show();
  }

  exportForm(pdf) {
    this.saveEdits(false);
    SignOff.beforePrint(this, this.db, this.p, SignOff.DISCHARGE, { run: () => { this.makeForm(pdf); } }, { run: () => { this.render(); } });
  }

  makeForm(pdf) {
    this.data = CaseSheet.load(this.db, this.id);
    let rel;
    try {
      const f = DischargeForm.build(this.db, this.p, this.data);
      f.signed = SignOff.printLine(this.db, this.p, SignOff.DISCHARGE);
      rel = pdf ? f.pdf(this) : f.docx(this);
    } catch (e) {
      Ui.toast(this, "Could not make the form: " + e.getMessage());
      return;
    }
    this.showFile(rel, pdf, "Discharge summary of " + this.p.get("name"));
  }

  showFile(rel, pdf, subject) {
    // the file may still be being written (a Promise of its path): continue once it is ready
    if (rel && typeof rel.then === 'function') {
      rel.then(r => this.showFile(r, pdf, subject), e => Ui.toast(this, "Could not make the file: " + (e && e.message)));
      return;
    }
    const items = ["Open", "Share (WhatsApp, email, Drive…)", "Save to Downloads"];
    new AlertDialog.Builder(this).setTitle((pdf ? "PDF" : "Word file") + " ready")
        .setItems(items, {
          onClick: (di, which) => {
            if (which === 0) Store.openWith(this, rel);
            else if (which === 1) Store.share(this, rel, subject);
            else {
              try {
                if (SummaryExport.toDownloads(this, rel))
                  Ui.toast(this, "Saved in Downloads/TVMCHMED");
                else Ui.toast(this, "On this Android version, use Share and pick Files or Drive");
              } catch (e) {
                Ui.toast(this, "Could not save: " + e.getMessage());
              }
            }
          }
        }).setNegativeButton("Close", null).show();
  }
}
;
