/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The department's printed discharge summary form (10 coloured sections on two A4 pages), filled from the patient's
 * record and case sheet on this phone, without AI. Boxes with nothing recorded stay blank to be written by hand.
 */
class DischargeForm {
  constructor() {}

  // section colours: bar, light fill for the labels
  static TEAL = 0xFF00897B; static TEAL_L = 0xFFE0F2F1; static BLUE = 0xFF1565C0; static BLUE_L = 0xFFE3F2FD; static RED = 0xFFC62828; static RED_L = 0xFFFFEBEE;
  static PURPLE = 0xFF6A1B9A; static PURPLE_L = 0xFFF3E5F5; static ORANGE = 0xFFE65100; static ORANGE_L = 0xFFFFF3E0; static INDIGO = 0xFF283593; static INDIGO_L = 0xFFE8EAF6;
  static GREEN = 0xFF2E7D32; static GREEN_L = 0xFFE8F5E9; static PINK = 0xFFAD1457; static PINK_L = 0xFFFCE4EC;

  static c(t) { return new FormDoc.Cell(t); }

  /** The case sheet keys behind a lab row of the form, in the order of its " / " parts. */
  static labKeys(code) {
    switch (code) {
      case "hb": return ["cbc_hb"];
      case "tc": return ["cbc_tc"];
      case "dc": return ["cbc_p", "cbc_l", "cbc_e"];
      case "plt": return ["cbc_plt"];
      case "pcv": return ["cbc_hct"];
      case "rbs": return ["rbs"];
      case "urea": return ["rft_urea"];
      case "creat": return ["rft_creat"];
      case "nak": return ["na", "k"];
      case "hco3": return ["abg_hco3"];
      case "bili": return ["lft_tb", "lft_db"];
      case "sgot": return ["lft_sgot", "lft_sgpt"];
      case "alp": return ["lft_alp"];
      case "prot": return ["lft_prot", "lft_alb"];
      case "inr": return ["", "inr"];
      default: return [];
    }
  }

  /** A lab value cell, in bold red when any part is outside the normal range. */
  static lab(cell, code, value, sex, o) {
    const keys = DischargeForm.labKeys(code), parts = Ui.nz(value).jsplit("\\s*/\\s*");
    for (let i = 0; i < keys.length && i < parts.length; i++)
      if (!keys[i].isEmpty() && !CaseSheet.flag(keys[i], parts[i], sex, o).isEmpty()) return cell.b().color(0xFFC62828);
    return cell;
  }

  static lbl(t, color, fill) { return new FormDoc.Cell(t).b().color(color).fill(fill); }

  static s(o, k) { return CaseSheet.s(o, k); }

  static on(o, k) { return "1".equals(DischargeForm.s(o, k)); }

  /** Non-empty parts joined with " / ". */
  static slash(...parts) {
    if (parts.length === 1 && Array.isArray(parts[0])) parts = parts[0];
    const out = [];
    for (const x of parts) if (x != null && !x.trim().isEmpty()) out.add(x.trim());
    return TextUtils.join(" / ", out);
  }

  static joinLines(l, sep) {
    return TextUtils.join(sep, l);
  }

  static build(db, p, o) {
    const c = DischargeForm.c, s = DischargeForm.s, on = DischargeForm.on, slash = DischargeForm.slash, lbl = DischargeForm.lbl,
        lab = DischargeForm.lab, joinLines = DischargeForm.joinLines, dr = DischargeForm.dr;
    const { TEAL, TEAL_L, BLUE, RED, RED_L, PURPLE, PURPLE_L, ORANGE, ORANGE_L, INDIGO, INDIGO_L, GREEN, GREEN_L, PINK, PINK_L } = DischargeForm;
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "DISCHARGE SUMMARY";
    f.footer = "Please bring this discharge summary at every hospital visit  •  " + f.dept + ", " + f.college;
    f.fileBase = "Discharge_form_" + Store.safeName(p.get("name")) + (Ui.nz(p.get("ip_no")).isEmpty() ? "" : "_IP" + Store.safeName(p.get("ip_no")));
    const female = "F".equals(p.get("sex"));
    const pid = Long.parseLong(p.get("id"));
    const unit = Ui.nz(p.get("home_unit"));
    const secs = DischargeActivity.sections(db, p, o, false);

    // unit / ward strip
    const units = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.FEVER];
    const unitLabels = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", "IMCU", "FEVER WARD"];
    const chip = [0xFFFCE4EC, 0xFFFFF3E0, 0xFFFFFDE7, 0xFFE8F5E9, 0xFFE0F7FA, 0xFFE3F2FD, 0xFFEDE7F6, 0xFFF8BBD0, 0xFFFFCCBC];
    const been = new JSet();
    been.add(unit);
    been.add(Ui.nz(p.get("location")));
    for (const e of db.rows("SELECT from_loc, to_loc FROM events WHERE patient_id=?", String(pid))) {
      been.add(Ui.nz(e.get("from_loc")));
      been.add(Ui.nz(e.get("to_loc")));
    }
    const u = f.block(null, 0, 0.12, 0.08, 0.08, 0.08, 0.08, 0.08, 0.08, 0.08, 0.13, 0.19);
    const ur = u.row(17, c("UNIT / WARD").b().fill(FormDoc.NAVY).color(0xFFFFFFFF).center());
    for (let i = 0; i < units.length; i++)
      ur.cells.add(c(FormDoc.box(units[i].equals(unit) || (i >= 7 && been.contains(units[i])), unitLabels[i])).b().fill(chip[i]).color(0xFF334155).center());

    // 1. patient details
    const four = [0.17, 0.33, 0.17, 0.33];
    const b1 = f.block("1.  PATIENT DETAILS", TEAL, four);
    const age = Ui.nz(p.get("age"));
    const adm = db.row("SELECT * FROM events WHERE patient_id=? AND type=? ORDER BY id LIMIT 1", String(pid), Db.ADMIT);
    const dis = db.row("SELECT * FROM events WHERE patient_id=? AND type IN (?,?) ORDER BY id DESC LIMIT 1", String(pid), Db.DISCHARGE, Db.DEATH);
    let disDate = s(o, "dis_date");
    if (disDate.isEmpty() && !Ui.nz(p.get("outcome_date")).isEmpty()) disDate = p.get("outcome_date");
    const admWhen = Dates.nice(p.get("admit_date")) + (adm == null || Ui.nz(adm.get("time")).isEmpty() ? "" : "  " + adm.get("time"));
    let disTime = s(o, "dis_time");
    if (disTime.isEmpty() && dis != null) disTime = Ui.nz(dis.get("time"));
    const disWhen = disDate.isEmpty() ? "" : Dates.nice(disDate) + (disTime.isEmpty() ? "" : "  " + disTime);
    let stay = "";
    try {
      const a = Dates.parse(p.get("admit_date")), z = disDate.isEmpty() ? Dates.today() : Dates.parse(disDate);
      stay = String(Math.max(1, ChronoUnit.DAYS.between(a, z))) + (Math.max(1, ChronoUnit.DAYS.between(a, z)) === 1 ? " day" : " days") + (disDate.isEmpty() ? " (so far)" : "");
    } catch (ignored) {
    }
    const cmchis = slash("1".equals(p.get("cmchis")) ? (Ui.nz(p.get("cmchis_no")).isEmpty() ? "CMCHIS" : p.get("cmchis_no")) : "", s(o, "aadhaar"));
    b1.row(14, lbl("Name", TEAL, TEAL_L), c(p.get("name")).b(), lbl("Age / Sex", TEAL, TEAL_L), c((age.isEmpty() ? "" : age + " years / ") + Base.sexLabel(p.get("sex"))));
    b1.row(14, lbl("IP No.", TEAL, TEAL_L), c(p.get("ip_no")).b(), lbl("OP No.", TEAL, TEAL_L), c(s(o, "op_no")));
    b1.row(14, lbl("Ward / Bed No.", TEAL, TEAL_L), c(Base.where(p) + (Ui.nz(p.get("bed")).isEmpty() ? "" : ", bed " + p.get("bed"))),
        lbl("CMCHIS / Aadhaar No.", TEAL, TEAL_L), c(cmchis));
    b1.row(14, lbl("Address", TEAL, TEAL_L), c(p.get("address")), lbl("Phone No.", TEAL, TEAL_L), c(p.get("phone")));
    b1.row(14, lbl("Date & Time of Admission", TEAL, TEAL_L), c(admWhen), lbl("Date & Time of Discharge", TEAL, TEAL_L), c(disWhen));
    let mlc = Ui.nz(p.get("mlc"));
    if (mlc.isEmpty()) mlc = s(o, "mlc").equals("Yes") ? "MLC" : s(o, "mlc").equals("No") ? "NMLC" : "";
    const arNo = Ui.nz(p.get("ar_no")).isEmpty() ? s(o, "ar_no") : p.get("ar_no");
    b1.row(14, lbl("Duration of Stay", TEAL, TEAL_L), c(stay), lbl("MLC", TEAL, TEAL_L),
        c(FormDoc.box("NMLC".equals(mlc), "NMLC") + "   " + FormDoc.box("MLC".equals(mlc), "MLC") + "      AR No.: " + arNo));
    let type = s(o, "dis_type");
    const cond = s(o, "dis_condition");
    if (type.isEmpty() && cond.contains("against")) type = "Against medical advice";
    if (type.isEmpty() && cond.contains("Referred")) type = "Referred / Transferred";
    b1.row(14, lbl("Type of Discharge", TEAL, TEAL_L), c(FormDoc.box(type.equals("Routine"), "Routine") + "   " + FormDoc.box(type.equals("On request"), "On request")
        + "   " + FormDoc.box(type.equals("Against medical advice"), "Against medical advice") + "   "
        + FormDoc.box(type.startsWith("Referred"), "Referred / Transferred to: ") + s(o, "ref_to")).span(3));

    // 2. treating team
    const b2 = f.block("2.  TREATING TEAM", BLUE, 0.25, 0.25, 0.25, 0.25);
    b2.row(15, c("UNIT CHIEF (Professor)").b().fill(0xFFBBDEFB).color(BLUE).center(), c("ASSISTANT PROFESSORS").b().fill(0xFFC8E6C9).color(GREEN).center(),
        c("POSTGRADUATES").b().fill(0xFFE1BEE7).color(PURPLE).center(), c("CRMIs").b().fill(0xFFFFE0B2).color(ORANGE).center());
    const ur0 = db.row("SELECT head FROM units WHERE code=?", unit);
    const chief = ur0 == null ? "" : Ui.nz(ur0.get("head"));
    const ap = DischargeForm.team(db, unit, "'Assistant Professor','Associate Professor'"), pg = DischargeForm.team(db, unit, "'Postgraduate'"), cr = DischargeForm.team(db, unit, "'CRMI'");
    const col1 = [dr(chief), "Review OP: " + (CaseSheet.reviewDay(unit) > 0 ? Dates.DAYS[CaseSheet.reviewDay(unit)] + ", OPD 3, 10–12" : db.setting("op_days_" + unit, "")), "Contact / Extn.: " + db.setting("contact_" + unit, "")];
    for (let i = 0; i < 3; i++)
      b2.row(14, c(col1[i]).size(8).color(i === 0 ? 0xFF0F172A : 0xFF475569).b(), c((i + 1) + ". " + dr(i < ap.size() ? ap.get(i) : "")).size(8),
          c((i + 1) + ". " + dr(i < pg.size() ? pg.get(i) : "")).size(8), c((i + 1) + ". " + dr(i < cr.size() ? cr.get(i) : "")).size(8));

    // 3. final diagnosis
    const b3 = f.block("3.  FINAL DIAGNOSIS", RED, 0.17, 0.50, 0.13, 0.20);
    const dx = Ui.nz(secs.get("Diagnosis"));
    b3.row(24, lbl("Primary Diagnosis", RED, RED_L), c(dx).b().size(9.5).span(3));
    let sec = s(o, "sec_dx");
    if (sec.isEmpty()) {
      const al0 = CaseSheet.allergyText(o);   // allergy has its own row below
      let ph = Ui.nz(secs.get("Past history"));
      if (!al0.isEmpty()) ph = ph.split(al0).join("").trim();
      sec = ph.replaceAllRx("^(?i)known case of ", "").replaceAllRx("\\.$", "");
    }
    if (sec.equalsIgnoreCase("No known comorbidities") || sec.equalsIgnoreCase("No significant past history")) sec = "";
    b3.row(20, lbl("Secondary Diagnoses / Co-morbidities", RED, RED_L), c(sec), lbl("ICD-10 Code", RED, RED_L), c(s(o, "icd10")).b());
    const al = s(o, "allergy");
    b3.row(14, c("DRUG ALLERGY").b().fill(RED).color(0xFFFFFFFF), c(FormDoc.box(al.equals(CaseSheet.ALLERGY_NO), "No known allergy") + "   "
        + FormDoc.box(al.equals(CaseSheet.ALLERGY_YES), "Allergy present – specify: ") + slash(s(o, "allergy_kind"), s(o, "allergy_note"))).b().color(RED).fill(RED_L).span(3));

    // 4. presenting complaints & history
    const b4 = f.block("4.  PRESENTING COMPLAINTS & HISTORY", PURPLE, 0.17, 0.83);
    const comp = [];
    const cl = CaseSheet.complaints(o);
    for (let i = 0; i < cl.length(); i++) {
      const x = cl.optJSONObject(i);
      if (x != null && !CaseSheet.complaintLine(x).trim().isEmpty()) comp.add(CaseSheet.complaintLine(x).trim());
    }
    b4.row(30, lbl("Presenting Complaints (with duration)", PURPLE, PURPLE_L), c(joinLines(comp, "\n")));
    b4.row(34, lbl("History of Present Illness (brief)", PURPLE, PURPLE_L), c(s(o, "hpi")));
    const others = (s(o, "ph_others") + " " + s(o, "ph_notes")).toLowerCase();
    const ph = [on(o, "ph_dm"), on(o, "ph_sht"), on(o, "ph_cad") || on(o, "ph_hfpef") || on(o, "ph_hfref") || on(o, "ph_vhd"),
      others.matches(".*\\b(cva|stroke)\\b.*"), on(o, "ph_ckd"), on(o, "ph_dcld"), on(o, "ph_tb"), on(o, "ph_ba") || on(o, "ph_copd"),
      on(o, "ph_epilepsy") || on(o, "ph_seizure"), others.matches(".*(thyroid|hypothyroid|hyperthyroid).*")];
    const phL = ["DM", "SHTN", "CAD", "CVA", "CKD", "CLD", "TB", "BA / COPD", "Seizure", "Thyroid"];
    const rest = [];
    const extra = [["ph_hfpef", "HFpEF"], ["ph_hfref", "HFrEF"], ["ph_vhd", "Valvular heart disease"], ["ph_aki", "AKI"], ["ph_ascites", "Ascites"],
      ["ph_varices", "Esophageal varices"], ["ph_hrs", "HRS"]];
    for (const x of extra) if (on(o, x[0])) rest.add(x[1]);
    for (const k of ["ph_others", "ph_notes"]) if (!s(o, k).isEmpty()) rest.add(s(o, k).split("\n").join("; "));
    if (!CaseSheet.rxHistoryText(o).isEmpty()) rest.add(CaseSheet.rxHistoryText(o).split("\n").join("; "));
    b4.row(26, lbl("Past History", PURPLE, PURPLE_L), c(FormDoc.boxes(phL, ph) + "\nOthers / duration / regular medications: " + joinLines(rest, "; ")));
    const diet = s(o, "diet");
    const none = !on(o, "smoking") && !on(o, "alcohol") && !on(o, "tobacco") && CaseSheet.filled(o, DischargeForm.section("personal"));
    b4.row(14, lbl("Personal History", PURPLE, PURPLE_L), c(FormDoc.boxes(["Smoker", "Alcohol", "Tobacco chewer", "None"],
        [on(o, "smoking"), on(o, "alcohol"), on(o, "tobacco"), none])
        + "      Diet: " + FormDoc.box(diet.equals("Vegetarian"), "Veg") + "   " + FormDoc.box(diet.equals("Mixed") || diet.equals("Non-vegetarian"), "Mixed")
        + "      Occupation: " + s(o, "occupation")));

    // 5. examination at admission
    const b5 = f.block("5.  EXAMINATION AT ADMISSION", ORANGE, 0.17, 0.12, 0.12, 0.11, 0.12, 0.12, 0.12, 0.12);
    const vh = ["Pulse (/min)", "BP (mmHg)", "RR (/min)", "Temp (°F)", "SpO₂ (%)", "GRBS (mg/dL)", "GCS (E V M)"];
    const vr = b5.row(14, lbl("Vitals", ORANGE, ORANGE_L));
    for (const h of vh) vr.cells.add(c(h).b().size(7.5).color(ORANGE).fill(ORANGE_L).center());
    const bp = s(o, "sbp").isEmpty() ? "" : s(o, "sbp") + (s(o, "dbp").isEmpty() ? "" : " / " + s(o, "dbp"));
    const pulse = s(o, "pr") + (s(o, "pulse_rhythm").isEmpty() || s(o, "pr").isEmpty() ? "" : " " + s(o, "pulse_rhythm").toLowerCase());
    b5.row(14, lbl("", ORANGE, ORANGE_L), c(pulse).center(), c(bp).center(), c(s(o, "rr")).center(), c(s(o, "temp")).center(),
        c(s(o, "spo2")).center(), c(s(o, "grbs")).center(), c(s(o, "gcs")).center());
    const edema = s(o, "ge_edema");
    const ge = [s(o, "ge_pallor").equals("Yes"), s(o, "ge_icterus").equals("Yes"), s(o, "ge_cyanosis").equals("Yes"), s(o, "ge_clubbing").equals("Yes"),
      s(o, "ge_glap").equals("Yes"), !edema.isEmpty() && !edema.startsWith("No")];
    const gen = [];
    if (s(o, "ge_conscious").equals("Yes")) gen.add("conscious");
    if (s(o, "ge_oriented").equals("Yes")) gen.add("oriented");
    if (s(o, "ge_febrile").equals("Yes")) gen.add("febrile");
    if (s(o, "ge_tachypnoea").equals("Yes")) gen.add("tachypnoeic at rest");
    if (!s(o, "ge_jvp").isEmpty()) gen.add("JVP " + s(o, "ge_jvp").toLowerCase());
    if (ge[5]) gen.add("pedal edema: " + edema.toLowerCase());
    if (!s(o, "ge_other").isEmpty()) gen.add(s(o, "ge_other"));
    b5.row(26, lbl("General Examination", ORANGE, ORANGE_L), c(FormDoc.boxes(["Pallor", "Icterus", "Cyanosis", "Clubbing", "Lymphadenopathy", "Pedal oedema"], ge)
        + "\nBuilt / nourishment / other findings: " + joinLines(gen, ", ")).span(7));
    b5.row(26, lbl("CVS", ORANGE, ORANGE_L), c(CaseSheet.cvsText(o)).span(3), lbl("RS", ORANGE, ORANGE_L), c(CaseSheet.rsText(o)).span(3));
    b5.row(26, lbl("Per Abdomen", ORANGE, ORANGE_L), c(CaseSheet.abdText(o)).span(3), lbl("CNS", ORANGE, ORANGE_L), c(CaseSheet.cnsText(o)).span(3));

    // 6. investigations
    const b6 = f.block("6.  INVESTIGATIONS", INDIGO, 0.2, 0.1, 0.1, 0.1, 0.2, 0.1, 0.1, 0.1);
    b6.pageBefore = true;
    const ih = b6.row(14);
    for (const h of ["Test", "Admission", "Repeat", "Discharge", "Test", "Admission", "Repeat", "Discharge"])
      ih.cells.add(c(h).b().size(7.5).color(0xFFFFFFFF).fill(0xFF5C6BC0).center());
    const plt = s(o, "cbc_plt").isEmpty() ? Ui.nz(p.get("platelet")) : s(o, "cbc_plt");
    const labs = [
      ["Haemoglobin (g/dL)", s(o, "cbc_hb"), "hb", "Bilirubin Total / Direct", slash(s(o, "lft_tb"), s(o, "lft_db")), "bili"],
      ["Total count (/cu.mm)", s(o, "cbc_tc"), "tc", "SGOT / SGPT (U/L)", slash(s(o, "lft_sgot"), s(o, "lft_sgpt")), "sgot"],
      ["DC (P / L / E)", slash(s(o, "cbc_p"), s(o, "cbc_l"), s(o, "cbc_e")), "dc", "ALP (U/L)", s(o, "lft_alp"), "alp"],
      ["Platelets (lakh/cu.mm)", plt, "plt", "Total protein / Albumin", slash(s(o, "lft_prot"), s(o, "lft_alb")), "prot"],
      ["PCV (%) / ESR (mm/hr)", slash(s(o, "cbc_hct"), s(o, "esr")), "pcv", "PT / INR", slash(s(o, "pt"), s(o, "inr")), "inr"],
      ["RBS (mg/dL)", s(o, "rbs"), "rbs", "Urine Alb / Sugar / Deposits", slash(s(o, "u_albumin"), s(o, "u_sugar"), s(o, "u_deposits")), "urine"],
      ["Urea (mg/dL)", s(o, "rft_urea"), "urea", "FBS / PPBS / HbA1c", slash(s(o, "fbs"), s(o, "ppbs"), s(o, "hba1c")), ""],
      ["Creatinine (mg/dL)", s(o, "rft_creat"), "creat", "Lipid profile", CaseSheet.lipidText(o), ""],
      ["Na⁺ / K⁺ (mEq/L)", slash(s(o, "na"), s(o, "k")), "nak", "Thyroid (TSH / T4 / T3)", CaseSheet.thyroidText(o), ""],
      ["Bicarbonate / Chloride", s(o, "abg_hco3"), "hco3", "Others", DischargeForm.othersLab(o), ""]];
    for (const r of labs) {
      const sx = p.get("sex");
      const row = b6.row(13, lbl(r[0], INDIGO, INDIGO_L).size(7.5), lab(c(r[1]).center().size(8), r[2], r[1], sx, o),
          lab(c(s(o, "r_" + r[2])).center().size(8), r[2], s(o, "r_" + r[2]), sx, o),
          lab(c(s(o, "d_" + r[2])).center().size(8), r[2], s(o, "d_" + r[2]), sx, o), lbl(r[3], INDIGO, INDIGO_L).size(7.5));
      if (r[5].isEmpty()) row.cells.add(c(r[4]).size(8).span(3));
      else {
        row.cells.add(lab(c(r[4]).center().size(8), r[5], r[4], sx, o));
        row.cells.add(lab(c(s(o, "r_" + r[5])).center().size(8), r[5], s(o, "r_" + r[5]), sx, o));
        row.cells.add(lab(c(s(o, "d_" + r[5])).center().size(8), r[5], s(o, "d_" + r[5]), sx, o));
      }
    }
    let dengue = CaseSheet.dengueText(o);
    if (dengue.isEmpty() && "1".equals(p.get("dengue"))) dengue = "Positive" + (Ui.nz(p.get("dengue_test")).isEmpty() ? "" : " (" + p.get("dengue_test") + ")");
    const img = DischargeForm.img;
    const ctmri = slash(img(o, "ct_brain", "CT brain"), img(o, "ct_chest", "CT chest"), img(o, "ct_abd", "CT abdomen"), img(o, "mri", "MRI brain"));
    const oth = [];
    if (!s(o, "inv_other").isEmpty()) oth.add(s(o, "inv_other"));
    if (!CaseSheet.abgText(o).isEmpty()) oth.add("ABG: " + CaseSheet.abgText(o).split(" (suggested from the values)").join("")
        .split("high anion gap metabolic acidosis").join("HAGMA").split("normal anion gap metabolic acidosis").join("NAGMA"));
    if (!s(o, "smear").isEmpty()) oth.add("Smear: " + s(o, "smear"));
    if (!s(o, "cul_sputum").isEmpty()) oth.add("Sputum C&S: " + s(o, "cul_sputum"));
    if (!s(o, "cul_pus").isEmpty()) oth.add("Pus C&S: " + s(o, "cul_pus"));
    const two = [
      ["HIV / HBsAg / Anti-HCV", slash(s(o, "hiv"), s(o, "hbsag"), s(o, "hcv")), "MP / MF (smear / card)", CaseSheet.mpText(o)],
      ["Dengue NS1 / IgM / IgG", dengue, "Scrub / Leptospira IgM", CaseSheet.scrubLeptoText(o)],
      ["Widal / Blood C&S", slash(CaseSheet.widalText(o), s(o, "cul_blood")), "Urine C&S / CBNAAT", slash(s(o, "cul_urine"), CaseSheet.cbnaatText(o))],
      ["ECG", CaseSheet.ecgText(o), "Chest X-ray", CaseSheet.cxrText(o)],
      ["USG Abdomen", CaseSheet.usgText(o), "Echocardiography", CaseSheet.echoText(o)],
      ["CT / MRI", ctmri, "Other investigations", joinLines(oth, "; ")]];
    for (const r of two)
      b6.row(13, lbl(r[0], PINK, PINK_L).size(7.5), c(r[1]).size(8).span(3), lbl(r[2], PINK, PINK_L).size(7.5), c(r[3]).size(8).span(3));

    // 7. course and treatment
    const b7 = f.block("7.  COURSE IN HOSPITAL & TREATMENT GIVEN", GREEN, 0.2, 0.3, 0.2, 0.3);
    const course = new StringBuilder(Ui.nz(secs.get("Course in the hospital")));
    const tx = Ui.nz(secs.get("Treatment given")).split("• ").join("").split("\n").join("; ");
    if (!tx.isEmpty()) course.append(course.length() > 0 ? "\n" : "").append("Treatment given: ").append(tx);
    b7.row(44, c(course.toString()).span(4));
    let icu = s(o, "icu_stay");
    if (icu.isEmpty() && been.contains(Db.IMCU)) icu = "IMCU stay" + ("1".equals(p.get("vent")) ? ", ventilator" : "");
    const ops = [];
    const opk = [["op_surgery", "Surgery"], ["op_pulmo", "Pulmonology"], ["op_cardio", "Cardiology"], ["op_neuro", "Neurology"], ["op_uro", "Urology"],
      ["op_cts", "CTS"], ["op_vascular", "Vascular surgery"], ["op_rheum", "Rheumatology"], ["op_other", "Others"]];
    for (const x of opk) if (!s(o, x[0]).isEmpty()) ops.add(x[1]);
    const proc = [];
    if (!s(o, "procedures").isEmpty()) proc.add(s(o, "procedures"));
    if (!CaseSheet.proceduresText(o).isEmpty()) proc.add(CaseSheet.proceduresText(o));
    if (s(o, "mg_cbd").equals("Yes")) proc.add("Continuous bladder drainage");
    if (s(o, "mg_ryles").equals("Yes")) proc.add(s(o, "mg_ryles_type").equals("Ryles tube feeding") ? "Ryles tube feeding"
        : "Ryles tube" + (s(o, "mg_ryles_type").isEmpty() ? "" : " (" + s(o, "mg_ryles_type").toLowerCase() + ")"));
    const trans = s(o, "transfusion").isEmpty() ? CaseSheet.cap(CaseSheet.transfusionText(o)) : s(o, "transfusion");
    b7.row(14, lbl("Procedures done", GREEN, GREEN_L), c(joinLines(proc, "; ")), lbl("Blood transfusion", GREEN, GREEN_L), c(trans));
    b7.row(14, lbl("IMCU / Ventilator / NIV", GREEN, GREEN_L), c(icu), lbl("Cross-consultations", GREEN, GREEN_L), c(joinLines(ops, ", ")));

    // 8. condition at discharge
    const b8 = f.block("8.  CONDITION AT DISCHARGE", TEAL, 0.17, 0.83);
    let st = s(o, "dis_status");
    if (st.isEmpty()) {
      if (cond.startsWith("Improved") || cond.startsWith("Symptomatically")) st = "Improved";
      else if (cond.startsWith("Stable") || cond.startsWith("Hemodynamically")) st = "Stable";
      else if (cond.startsWith("Referred")) st = "Needs higher-centre care";
    }
    const stL = ["Recovered", "Improved", "Stable", "Unchanged", "Needs higher-centre care"];
    const stOn = new Array(stL.length).fill(false);
    for (let i = 0; i < stL.length; i++) stOn[i] = stL[i].equals(st);
    b8.row(14, lbl("Status", TEAL, TEAL_L), c(FormDoc.boxes(stL, stOn) + (s(o, "dis_note").isEmpty() ? "" : "      " + s(o, "dis_note"))));
    const blank = DischargeForm.blank;
    b8.row(14, lbl("Vitals at discharge", TEAL, TEAL_L), c("Pulse " + blank(s(o, "dv_pr")) + " /min      BP " + blank(s(o, "dv_sbp")) + " / " + blank(s(o, "dv_dbp"))
        + " mmHg      RR " + blank(s(o, "dv_rr")) + " /min      SpO₂ " + blank(s(o, "dv_spo2")) + " %      Temp " + blank(s(o, "dv_temp")) + " °F"));

    // 9. discharge medications
    const b9 = f.block("9.  DISCHARGE MEDICATIONS  (generic names in CAPITALS)", PURPLE, 0.06, 0.30, 0.09, 0.08, 0.16, 0.12, 0.19);
    const mh = b9.row(14);
    for (const h of ["S.No", "Drug name & strength", "Dose", "Route", "Frequency (M – A – N)", "Duration", "Food relation / remarks"])
      mh.cells.add(c(h).b().size(7.5).color(PURPLE).fill(PURPLE_L).center());
    const meds = DischargeForm.meds(o);
    const rows = Math.max(meds.size() + 1, 4);   // 9.72: one blank row to write in, at least 4 rows
    for (let i = 0; i < rows; i++) {
      const m = i < meds.size() ? meds.get(i) : ["", "", "", "", "", ""];
      b9.row(13, c(String(i + 1)).b().center().fill(PURPLE_L), c(m[0]).b(), c(m[1]).center(), c(m[2]).center(), c(m[3]).center(), c(m[4]).center(), c(m[5]));
    }

    // 10. advice & follow-up
    const b10 = f.block("10.  ADVICE & FOLLOW-UP", ORANGE, 0.17, 0.36, 0.15, 0.32);
    const adviceText = (s(o, "advice") + " " + s(o, "adv_diet")).toLowerCase();
    const dietOn = [on(o, "diet_normal") || s(o, "adv_diet").equals("Normal diet"), on(o, "diet_diabetic") || adviceText.contains("diabetic diet"),
      on(o, "diet_lowsalt") || adviceText.contains("low salt") || adviceText.contains("salt restrict"), on(o, "diet_renal") || adviceText.contains("renal diet")];
    let act = s(o, "activity");
    if (act.isEmpty()) act = s(o, "adv_activity").split(" activity").join("").split("Normal").join("Normal").split("Restricted").join("Restricted");
    b10.row(14, lbl("Diet", ORANGE, ORANGE_L), c(FormDoc.boxes(["Normal", "Diabetic", "Low salt", "Renal"], dietOn)),
        lbl("Activity", ORANGE, ORANGE_L), c(FormDoc.boxes(["Normal", "Restricted", "Bed rest"],
            [act.equals("Normal"), act.equals("Restricted"), act.equals("Bed rest")])));
    const special = [];
    if (!s(o, "special").isEmpty()) special.add(s(o, "special").split("\n").join("; "));
    for (const l of CaseSheet.adviceLines(o)) if (!l.equals(s(o, "adv_diet")) && !l.equals(s(o, "adv_activity"))) special.add(l);
    for (const l of s(o, "advice").jsplit("\n")) {
      const t = l.trim().replaceAllRx("^[•\\-*]\\s*", "");
      if (!t.isEmpty() && SummaryExport.med(t) == null && !t.toLowerCase().matches("(diabetic|low salt|renal|normal) diet\\.?")) special.add(t);
    }
    b10.row(22, lbl("Special instructions", ORANGE, ORANGE_L), c(joinLines(special, "; ")).span(3));
    const review = CaseSheet.reviewText(unit, o) + (s(o, "review_reports").isEmpty() ? "" : ".   With reports of: " + s(o, "review_reports"));
    b10.row(14, lbl("Review", ORANGE, ORANGE_L), c(review).b().span(3));
    b10.row(14, lbl("Pending reports", ORANGE, ORANGE_L), c(s(o, "pending")), lbl("Referred to", ORANGE, ORANGE_L), c(s(o, "referred")));
    const wL = ["Breathlessness", "Chest pain", "High fever", "Drowsiness / fits", "Bleeding", "Reduced urine output", "Persistent vomiting"];
    const wK = ["w_breath", "w_chest", "w_fever", "w_drowsy", "w_bleed", "w_urine", "w_vomit"];
    const wOn = new Array(wK.length).fill(false);
    for (let i = 0; i < wK.length; i++) wOn[i] = on(o, wK[i]);
    b10.row(26, c("COME TO CASUALTY AT ONCE IF").b().fill(RED).color(0xFFFFFFFF),
        c(FormDoc.boxes(wL, wOn) + "   " + FormDoc.box(!s(o, "w_other").isEmpty(), "Others: ") + s(o, "w_other")).b().color(RED).fill(RED_L).span(3));

    // signatures
    const sg = f.block(null, 0, 0.25, 0.25, 0.25, 0.25);
    sg.keep = true;
    sg.row(28, c("Name & signature").size(7).color(0xFF94A3B8).bottom(), c("Name & signature").size(7).color(0xFF94A3B8).bottom(),
        c("Name & signature").size(7).color(0xFF94A3B8).bottom(), (chief.isEmpty() ? c("Name & signature").size(7).color(0xFF94A3B8) : c(dr(chief)).size(7.5).color(0xFF334155)).bottom());
    sg.row(14, c("CRMI (prepared by)").b().fill(0xFFFFE0B2).color(ORANGE).center(), c("POSTGRADUATE (verified by)").b().fill(0xFFE1BEE7).color(PURPLE).center(),
        c("ASSISTANT PROFESSOR").b().fill(0xFFC8E6C9).color(GREEN).center(), c("UNIT CHIEF (Professor)").b().fill(0xFFBBDEFB).color(BLUE).center());
    sg.row(14, c("Summary received; instructions explained in patient’s own language.        Patient / Attender signature: ________________        Date: __________")
        .b().fill(FormDoc.NAVY).color(0xFFFFFFFF).size(8).span(4));
    void female;
    return f;
  }

  static blank(v) {
    return v == null || v.trim().isEmpty() ? "______" : v.trim();
  }

  /** "Dr. A. Kumar", without doubling a "Dr." that is already there. */
  static dr(name) {
    const n = Ui.nz(name).trim();
    if (n.isEmpty()) return "Dr.";
    return n.toLowerCase().startsWith("dr") || n.toLowerCase().startsWith("prof") ? n : "Dr. " + n;
  }

  static team(db, unit, roles) {
    const out = [];
    for (const r of db.rows("SELECT name FROM staff WHERE unit=? AND role IN (" + roles + ") AND " + Approvals.APPROVED_SQL + " ORDER BY name", unit))
      out.add(r.get("name"));
    return out;
  }

  static section(key) {
    for (const s of CaseSheet.SECTIONS) if (s.key.equals(key)) return s;
    return CaseSheet.SECTIONS[0];
  }

  static img(o, k, label) {
    const t = CaseSheet.imagingText(o, k);
    return t.isEmpty() ? "" : label + ": " + t;
  }

  static othersLab(o) {
    const s = DischargeForm.s;
    const l = [];
    const k = [["ca", "Ca"], ["uric", "Uric acid"], ["crp", "CRP"], ["ana", "ANA"], ["ra", "RA"], ["ena", "ENA"], ["aptt", "aPTT"]];
    for (const x of k) if (!s(o, x[0]).isEmpty()) l.add(x[1] + " " + s(o, x[0]));
    if (!s(o, "u_pcr").isEmpty()) l.add("Spot PCR " + s(o, "u_pcr"));
    return DischargeForm.joinLines(l, ", ");
  }

  /** Discharge medicines: name & strength, dose, route, M-A-N, duration, remarks. From the treatment chart ("continue") and advice lines. */
  static meds(o) {
    const out = [];
    for (const d of CaseSheet.dischargeMeds(o)) {
      const line = CaseSheet.drugLine(d, false);
      const name = line.isEmpty() ? "" : DischargeForm.form(line.split(d.optString("dose").trim()).join("").trim());
      const days = d.optString("days").trim();
      out.add([name, d.optString("dose").trim(), d.optString("route").trim(), DischargeForm.man(d.optString("freq").trim()),
        days.matches("\\d+") ? days + " days" : days, DischargeForm.slash(d.optString("food").trim(), d.optString("note").trim())]);
    }
    for (const l of DischargeForm.s(o, "advice").jsplit("\n")) {
      const m = SummaryExport.med(l);
      if (m == null) continue;
      const w = m.name.jsplit(" ");
      let cut = w.length;
      for (let i = 1; i < w.length; i++) if (w[i].matches("(?i)[0-9.,/]+(mg|g|mcg|ml|iu|units?)?")) { cut = i; break; }
      const nm = new StringBuilder(), dose = new StringBuilder();
      for (let i = 0; i < w.length; i++) (i < cut ? nm : dose).append(i === 0 || i === cut ? "" : " ").append(w[i]);
      let route = dose.toString().replaceAllRx("(?i).*\\b(IV|IM|SC|SL|INH|PR)\\b.*", "$1");
      if (route.equals(dose.toString())) route = "";
      out.add([DischargeForm.form(nm.toString()), dose.toString().replaceAllRx("(?i)\\b(IV|IM|SC|SL|INH|PR)\\b", "").trim(),
        route.isEmpty() ? (nm.toString().matches("(?i)^(tab|cap|syp|syr).*") ? "Oral" : "") : route.toUpperCase(),
        m.slots != null ? m.slots[0] + " – " + m.slots[1] + " – " + m.slots[2] : m.when, m.days, ""]);
    }
    return out;
  }

  /** "Tab. Metformin" -> "Tab. METFORMIN": the form asks for drug names in capitals. */
  static form(name) {
    const n = name.trim();
    const sp = n.indexOf(' ');
    if (sp > 0 && n.substring(0, sp).matches("(?i)(tab|cap|inj|syr|syp|ivf|neb|ors|enema)\\.?")) return n.substring(0, sp + 1) + n.substring(sp + 1).toUpperCase();
    return n.toUpperCase();
  }

  /** OD / BD / TDS / HS / 1-0-1 written as morning - afternoon - night. */
  static man(freq) {
    const f = freq.trim().toUpperCase();
    switch (f) {
      case "OD": return "1 – 0 – 0";
      case "BD": case "BID": return "1 – 0 – 1";
      case "TDS": case "TID": return "1 – 1 – 1";
      case "HS": return "0 – 0 – 1";
      case "QID": return "4 times a day";
      case "SOS": case "PRN": return "When needed";
      default: return f.matches("[0-9½/]+-[0-9½/]+-[0-9½/]+") ? f.split("-").join(" – ") : freq;
    }
  }
}
;
