/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** PG dissertations: each PG's topic, guide and progress through the milestones up to university acceptance. */
class DissertationActivity extends Base {
  constructor() {
    super();
    this.id = -1;
    this.filter = "ALL";
  }

  static COLOR = 0xFF4F46E5;
  /** Milestones in order: key, label. Each is stored as the date it was done, in column s_key. */
  static STEPS = [
      ["topic", "Topic and guide allotted"],
      ["protocol", "Protocol presented in the department"],
      ["iec", "Ethics committee (IEC) approval"],
      ["ctri", "CTRI registration (if needed)"],
      ["data_start", "Data collection started"],
      ["data_done", "Data collection completed"],
      ["analysis", "Statistical analysis done"],
      ["draft", "Full draft given to the guide"],
      ["guide_ok", "Corrections done, guide approved"],
      ["plagiarism", "Plagiarism check passed"],
      ["submitted", "Submitted to the university"],
      ["accepted", "Accepted by the university"]];
  /** Steps that only the guide or faculty can tick. */
  static FACULTY_STEPS = new JSet(["guide_ok", "accepted"]);
  static DESIGNS = ["Prospective observational", "Cross-sectional", "Case-control", "Cohort", "Randomised controlled trial", "Retrospective", "Diagnostic accuracy", "Other"];

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    this.setTitle(this.id >= 0 ? "Dissertation" : "PG dissertations");
    this.subtitle = this.id >= 0 ? null : "Topic, guide and progress of every PG";
    this.headerColor(DissertationActivity.COLOR);
  }

  static isFaculty(c) {
    return SessionAttendance.canRun(c);
  }

  /** Faculty edit every dissertation; a PG edits their own. */
  canEdit(d) {
    if (DissertationActivity.isFaculty(this)) return true;
    const me = Reminders.myName(this, this.db);
    return !me.isEmpty() && Reminders.anyLine(d.get("pg"), Reminders.tokens(me), "");
  }

  // ---------- progress ----------

  static done(d, step) {
    return !Ui.nz(d.get("s_" + step)).isEmpty();
  }

  /** Steps counted for this dissertation: CTRI only when it was done. */
  static steps(d) {
    const out = [];
    for (const s of DissertationActivity.STEPS) if (!s[0].equals("ctri") || DissertationActivity.done(d, "ctri")) out.add(s);
    return out;
  }

  static percent(d) {
    const st = DissertationActivity.steps(d);
    let n = 0;
    for (const s of st) if (DissertationActivity.done(d, s[0])) n++;
    return Math.round(n * 100 / st.size());
  }

  static next(d) {
    for (const s of DissertationActivity.steps(d)) if (!DissertationActivity.done(d, s[0])) return s;
    return null;
  }

  /** Done, Submitted, Overdue, Behind or On track. */
  static state(d) {
    const done = DissertationActivity.done;
    if (done(d, "accepted")) return "Accepted";
    if (done(d, "submitted")) return "Submitted";
    const due = Dates.parse(d.get("due_date"));
    if (due == null) return "On track";
    const left = due.toEpochDay() - Dates.today().toEpochDay();
    if (left < 0) return "Overdue";
    if (left <= 90 && !done(d, "draft")) return "Behind";
    if (left <= 180 && !done(d, "data_done")) return "Behind";
    if (left <= 365 && !done(d, "iec")) return "Behind";
    return "On track";
  }

  static stateColor(s) {
    if ("Overdue".equals(s)) return Ui.RED;
    if ("Behind".equals(s)) return Ui.ORANGE;
    if ("Accepted".equals(s) || "Submitted".equals(s)) return Ui.GREEN;
    return Ui.TEAL;
  }

  // ---------- screens ----------

  render() {
    const db = this.db, COLOR = DissertationActivity.COLOR;
    if (this.id >= 0) {
      this.renderOne();
      return;
    }
    if (DissertationActivity.isFaculty(this)) this.headerAction("+ PG", { onClick: (v) => { this.editDialog(null); } });
    const page = Ui.v(this);
    const all = db.rows("SELECT * FROM dissertations ORDER BY batch DESC, pg");
    let behind = 0, sub = 0, track = 0;
    for (const d of all) {
      const s = DissertationActivity.state(d);
      if ("Behind".equals(s) || "Overdue".equals(s)) behind++;
      else if ("Submitted".equals(s) || "Accepted".equals(s)) sub++;
      else track++;
    }
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(COLOR), 20));
    hero.addView(Ui.statRow(this, this.white(all.size(), "PGs"), this.white(track, "On track"), this.white(behind, "Behind / overdue"), this.white(sub, "Submitted")));
    page.addView(hero);

    const batches = new JSet();
    for (const d of all) if (!Ui.nz(d.get("batch")).isEmpty()) batches.add(d.get("batch"));
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    const opts = [];
    opts.add("ALL");
    opts.add("BEHIND");
    opts.addAll(batches);
    for (const o of opts) {
      const label = o.equals("ALL") ? "All" : o.equals("BEHIND") ? "Behind / overdue" : "Batch " + o;
      const c = Ui.chip(this, label, o.equals(this.filter), o.equals("BEHIND") ? Ui.ORANGE : COLOR);
      c.setOnClickListener({ onClick: (v) => { this.filter = o; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    const filter = this.filter;
    let shown = 0;
    for (const d of all) {
      const s = DissertationActivity.state(d);
      if (filter.equals("BEHIND") && !s.equals("Behind") && !s.equals("Overdue")) continue;
      if (!filter.equals("ALL") && !filter.equals("BEHIND") && !filter.equals(d.get("batch"))) continue;
      page.addView(this.listCard(d));
      shown++;
    }
    if (shown === 0) page.addView(this.emptyNote(all.isEmpty() ? "No dissertations yet." : "None here."));
    if (all.isEmpty() && DissertationActivity.isFaculty(this)) {
      const pgs = db.rows("SELECT * FROM staff WHERE role='Postgraduate' AND " + Approvals.APPROVED_SQL + " ORDER BY name");
      if (!pgs.isEmpty()) {
        const add = Ui.button(this, "Add all " + pgs.size() + " PGs from the Students list", COLOR, {
          onClick: (v) => {
            for (const p of pgs) {
              const cv = new ContentValues();
              cv.put("staff_id", p.get("id"));
              cv.put("pg", p.get("name"));
              cv.put("unit", p.get("unit"));
              cv.put("batch", Ui.nz(p.get("batch")));
              cv.put("updated", Alerts.now());
              this.db.insert("dissertations", cv);
            }
            this.render();
          }
        });
        page.addView(add);
        Ui.margins(add, 14, 8, 14, 0);
      }
    }
    this.setPage(page);
  }

  white(n, label) {
    const s = Ui.stat(this, String(n), label, Color.WHITE);
    for (let i = 0; i < s.getChildCount(); i++)
      if (s.getChildAt(i) instanceof TextView) s.getChildAt(i).setTextColor(i === 0 ? Color.WHITE : 0xD9FFFFFF);
    return s;
  }

  listCard(d) {
    const st = DissertationActivity.state(d);
    const pc = DissertationActivity.percent(d);
    const sub = [];
    sub.add(Ui.nz(d.get("title")).isEmpty() ? "Topic not entered yet" : d.get("title"));
    const g = (Ui.nz(d.get("guide")).isEmpty() ? "" : "Guide: " + d.get("guide")) + (Ui.nz(d.get("unit")).isEmpty() ? "" : "  ·  " + Db.shortName(d.get("unit")));
    if (!g.trim().isEmpty()) sub.add(g.replaceAllRx("^  ·  ", ""));
    const nx = DissertationActivity.next(d);
    if (nx != null) sub.add("Next: " + nx[1]);
    const right = Dates.parse(d.get("due_date")) == null ? null : "Due " + Dates.nice(d.get("due_date"));
    const card = this.entryCard(st + "  ·  " + pc + "%", DissertationActivity.stateColor(st), d.get("pg"), TextUtils.join("\n", sub), right,
        this.opener(DissertationActivity, "id", d.get("id")));
    card.addView(Ui.bar(this, pc, 100, DissertationActivity.stateColor(st)));
    return card;
  }

  renderOne() {
    const COLOR = DissertationActivity.COLOR;
    const d = this.db.row("SELECT * FROM dissertations WHERE id=?", String(this.id));
    if (d == null) {
      this.finish();
      return;
    }
    this.setTitle(d.get("pg"));
    this.subtitle = "Dissertation" + (Ui.nz(d.get("batch")).isEmpty() ? "" : "  ·  batch " + d.get("batch"));
    const edit = this.canEdit(d);
    if (edit) this.headerAction("Edit", { onClick: (v) => { this.editDialog(d); } });
    const page = Ui.v(this);
    const st = DissertationActivity.state(d);
    const pc = DissertationActivity.percent(d);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(COLOR), 20));
    hero.addView(Ui.tv(this, Ui.nz(d.get("title")).isEmpty() ? "Topic not entered yet" : d.get("title"), 17, Color.WHITE, true));
    const pct = Ui.tv(this, pc + "% done  ·  " + st, 14, 0xE6FFFFFF, true);
    hero.addView(pct);
    Ui.margins(pct, 0, 6, 0, 0);
    const bar = Ui.bar(this, pc, 100, 0xFFFFFFFF);
    hero.addView(bar);
    page.addView(hero);

    const info = Ui.card(this);
    info.addView(Ui.kv(this, "Guide", d.get("guide")));
    info.addView(Ui.kv(this, "Co-guide", d.get("co_guide")));
    info.addView(Ui.kv(this, "Unit", Ui.nz(d.get("unit")).isEmpty() ? "" : Db.unitName(d.get("unit"))));
    info.addView(Ui.kv(this, "Study design", d.get("design")));
    info.addView(Ui.kv(this, "Sample size", d.get("sample_size")));
    info.addView(Ui.kv(this, "IEC number", d.get("iec_no")));
    if (!Ui.nz(d.get("ctri_no")).isEmpty()) info.addView(Ui.kv(this, "CTRI number", d.get("ctri_no")));
    const due = Dates.parse(d.get("due_date"));
    info.addView(Ui.kv(this, "University submission due", due == null ? "" : Dates.nice(due) + DissertationActivity.daysLeft(due)));
    page.addView(info);

    page.addView(Ui.heading(this, "Milestones", COLOR));
    const ms = Ui.card(this);
    const st2 = [];
    for (const s of DissertationActivity.STEPS) st2.add(s);
    const nx = DissertationActivity.next(d);
    for (let i = 0; i < st2.size(); i++) {
      if (i > 0) ms.addView(Ui.divider(this));
      ms.addView(this.stepRow(d, st2.get(i), nx != null && nx[0].equals(st2.get(i)[0]), edit));
    }
    page.addView(ms);

    const tc = this.db.num("SELECT COUNT(*) FROM thesis_cases WHERE diss_id=?", String(this.id));
    const tf = Thesis.fields(d).length();
    const th = Ui.v(this);
    th.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    th.addView(Ui.button(this, "📊  Thesis data: " + (tf === 0 ? "make the form" : tc + (tc === 1 ? " case" : " cases") + ", master chart, statistics"), Thesis.COLOR,
        this.opener(ThesisActivity, "diss", String(this.id))));
    page.addView(th);

    page.addView(Ui.heading(this, "Progress notes", COLOR));
    const notes = Ui.card(this);
    const log = Ui.nz(d.get("notes")).trim();
    if (log.isEmpty()) notes.addView(Ui.muted(this, "No notes yet. Guides and the PG can add how the work is going."));
    else {
      const lines = log.jsplit("\n");
      for (let i = lines.length - 1; i >= 0; i--) {
        const t = Ui.body(this, lines[i]);
        t.setPadding(0, Ui.dp(this, 3), 0, Ui.dp(this, 3));
        notes.addView(t);
      }
    }
    if (edit || DissertationActivity.isFaculty(this)) {
      const add = Ui.outlineButton(this, "+ Add progress note", COLOR, { onClick: (v) => { this.noteDialog(d); } });
      notes.addView(add);
      Ui.margins(add, 0, 8, 0, 0);
    }
    page.addView(notes);

    const share = Ui.outlineButton(this, "Share progress", COLOR, {
      onClick: (v) => {
        const i = new Intent(Intent.ACTION_SEND);
        i.setType("text/plain");
        i.putExtra(Intent.EXTRA_TEXT, DissertationActivity.shareText(d));
        this.startActivity(Intent.createChooser(i, "Share progress"));
      }
    });
    page.addView(share);
    Ui.margins(share, 14, 12, 14, 0);
    this.setPage(page);
  }

  static daysLeft(due) {
    const left = due.toEpochDay() - Dates.today().toEpochDay();
    return left < 0 ? " (" + (-left) + " days overdue)" : " (" + left + " days left)";
  }

  stepRow(d, s, isNext, edit) {
    const COLOR = DissertationActivity.COLOR;
    const ok = DissertationActivity.done(d, s[0]);
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
    const mark = Ui.tv(this, ok ? "✓" : isNext ? "●" : "", 14, Color.WHITE, true);
    mark.setGravity(Gravity.CENTER);
    const bg = Ui.round(this, ok ? Ui.GREEN : isNext ? Ui.alpha(COLOR, 0x22) : 0xFFFFFFFF, 13);
    if (!ok) bg.setStroke(Ui.dp(this, 2), isNext ? COLOR : 0xFFCBD5E1);
    mark.setBackground(bg);
    if (isNext) mark.setTextColor(COLOR);
    row.addView(mark, new LinearLayout.LayoutParams(Ui.dp(this, 26), Ui.dp(this, 26)));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 6), 0);
    t.addView(Ui.tv(this, s[1], 15, ok ? Ui.TEXT : isNext ? COLOR : Ui.MUTED, ok || isNext));
    let extra = "";
    if (s[0].equals("data_start") || s[0].equals("data_done")) {
      const n = Ui.toInt(d.get("collected"), 0), of = Ui.toInt(d.get("sample_size"), 0);
      if (of > 0 || n > 0) extra = n + (of > 0 ? " of " + of : "") + " cases collected";
    }
    if (s[0].equals("iec") && !Ui.nz(d.get("iec_no")).isEmpty()) extra = "IEC no. " + d.get("iec_no");
    const when = ok ? "Done " + Dates.nice(d.get("s_" + s[0])) : "";
    const line = when + (when.isEmpty() || extra.isEmpty() ? "" : "  ·  ") + extra;
    if (!line.isEmpty()) t.addView(Ui.muted(this, line));
    row.addView(t, Ui.weight(1));
    const allowed = edit && (!DissertationActivity.FACULTY_STEPS.contains(s[0]) || DissertationActivity.isFaculty(this));
    if (allowed && !ok) {
      const b = Ui.softPill(this, "Mark done", isNext ? COLOR : Ui.SLATE);
      b.setOnClickListener({ onClick: (v) => { this.stepDialog(d, s); } });
      row.addView(b);
    }
    if (allowed) row.setOnClickListener({ onClick: (v) => { this.stepDialog(d, s); } });
    return row;
  }

  stepDialog(d, s) {
    const ok = DissertationActivity.done(d, s[0]);
    const f = new Form(this);
    f.date("on", "Done on", ok ? d.get("s_" + s[0]) : Dates.todayIso());
    if (s[0].equals("iec")) f.text("iec_no", "IEC approval number", d.get("iec_no"), Form.PLAIN);
    if (s[0].equals("ctri")) f.text("ctri_no", "CTRI number", d.get("ctri_no"), Form.PLAIN);
    if (s[0].equals("data_start") || s[0].equals("data_done")) f.text("collected", "Cases collected so far", d.get("collected"), Form.NUMBER);
    if (ok) f.segment("state", "Status", ["Done", "Not done yet"], "Done");
    Ui.formDialog(this, s[1], f, ok ? "Save" : "Mark done", {
      run: () => {
        const cv = new ContentValues();
        cv.put("s_" + s[0], f.get("on"));
        if (ok && "Not done yet".equals(f.get("state"))) cv.put("s_" + s[0], "");
        if (s[0].equals("iec")) cv.put("iec_no", f.get("iec_no").trim());
        if (s[0].equals("ctri")) cv.put("ctri_no", f.get("ctri_no").trim());
        if (s[0].equals("data_start") || s[0].equals("data_done")) cv.put("collected", f.get("collected").trim());
        cv.put("updated", Alerts.now());
        this.db.update("dissertations", cv, this.id);
        this.render();
        return true;
      }
    });
  }

  noteDialog(d) {
    const f = new Form(this);
    f.multi("note", "Note *", "");
    f.text("by", "By", Reminders.myName(this, this.db), Form.PLAIN);
    Ui.formDialog(this, "Progress note", f, "Save", {
      run: () => {
        if (!f.require("note", "Write the note")) return false;
        const line = Dates.nice(Dates.today()) + " · " + f.get("note").trim().split("\n").join(" ") + (f.get("by").trim().isEmpty() ? "" : " (" + f.get("by").trim() + ")");
        const old = Ui.nz(d.get("notes")).trim();
        const cv = new ContentValues();
        cv.put("notes", old.isEmpty() ? line : old + "\n" + line);
        cv.put("updated", Alerts.now());
        this.db.update("dissertations", cv, Long.parseLong(d.get("id")));
        this.render();
        return true;
      }
    });
  }

  editDialog(d) {
    const db = this.db;
    const f = new Form(this);
    const pgs = [], fac = [];
    for (const p of db.rows("SELECT name FROM staff WHERE role='Postgraduate' ORDER BY name")) pgs.add(p.get("name"));
    for (const p of db.rows("SELECT name FROM staff WHERE role IN ('Professor','Associate Professor','Assistant Professor') ORDER BY name")) fac.add(p.get("name"));
    f.suggest("pg", "PG name *", d == null ? "" : d.get("pg"), pgs.slice());
    f.text("batch", "Batch (year of joining, e.g. 2024)", d == null ? "" : d.get("batch"), Form.PLAIN);
    f.choice("unit", "Unit", Db.shortNames(Db.WARD_UNITS), Db.WARD_UNITS, d == null ? "" : d.get("unit"), null);
    f.multi("title", "Dissertation title", d == null ? "" : d.get("title"));
    f.suggest("guide", "Guide", d == null ? "" : d.get("guide"), fac.slice());
    f.suggest("co_guide", "Co-guide", d == null ? "" : d.get("co_guide"), fac.slice());
    f.choice("design", "Study design", DissertationActivity.DESIGNS, DissertationActivity.DESIGNS, d == null ? "" : d.get("design"), null);
    f.text("sample_size", "Sample size", d == null ? "" : d.get("sample_size"), Form.NUMBER);
    f.optionalDate("due_date", "University submission due date", d == null ? "" : d.get("due_date"));
    if (d != null && DissertationActivity.isFaculty(this)) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete dissertation?", d.get("pg"), "Delete", {
            run: () => { this.db.delete("dissertations", Long.parseLong(d.get("id"))); this.finish(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, d == null ? "Add a PG's dissertation" : "Edit dissertation", f, "Save", {
      run: () => {
        if (!f.require("pg", "Enter the PG's name")) return false;
        const cv = new ContentValues();
        for (const k of ["pg", "batch", "unit", "title", "guide", "co_guide", "design", "sample_size", "due_date"]) cv.put(k, f.get(k).trim());
        const s = this.db.row("SELECT id FROM staff WHERE name=? AND role='Postgraduate' LIMIT 1", f.get("pg").trim());
        if (s != null) cv.put("staff_id", s.get("id"));
        if (!f.get("title").trim().isEmpty() && (d == null || !DissertationActivity.done(d, "topic"))) cv.put("s_topic", Dates.todayIso());
        cv.put("updated", Alerts.now());
        if (d == null) {
          const nid = this.db.insert("dissertations", cv);
          this.open(DissertationActivity, "id", String(nid));
        } else this.db.update("dissertations", cv, Long.parseLong(d.get("id")));
        this.render();
        return true;
      }
    });
  }

  static shareText(d) {
    const A = DissertationActivity;
    const sb = new StringBuilder("*Dissertation progress: " + d.get("pg") + "*\n");
    if (!Ui.nz(d.get("title")).isEmpty()) sb.append(d.get("title")).append('\n');
    if (!Ui.nz(d.get("guide")).isEmpty()) sb.append("Guide: ").append(d.get("guide")).append('\n');
    sb.append(A.percent(d)).append("% done, ").append(A.state(d)).append('\n');
    for (const s of A.steps(d)) sb.append(A.done(d, s[0]) ? "✅ " : "⬜ ").append(s[1]).append(A.done(d, s[0]) ? " (" + Dates.nice(d.get("s_" + s[0])) + ")" : "").append('\n');
    const due = Dates.parse(d.get("due_date"));
    if (due != null) sb.append("Due: ").append(Dates.nice(due)).append(A.daysLeft(due));
    return sb.toString().trim();
  }
}
;
/* ---- app/DocVerify.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Verification codes on downloads (8.10). Every PDF and Word file made from the department template gets a short code
 * (like K7QM-2XPA) printed with a QR code. The code, the title, who made it and when are kept in the shared table doc_verify,
 * so anyone in the department can type the code in "Verify a document" and see whether the paper really came from the app.
 */
class DocVerify {
  /** A new code, "XXXX-XXXX" (no 0/O or 1/I to misread). */
  static newCode() {
    const b = new StringBuilder();
    const r = new SecureRandom();
    for (let i = 0; i < 8; i++) {
      if (i === 4) b.append('-');
      b.append(DocVerify.ALPHABET.charAt(r.nextInt(DocVerify.ALPHABET.length)));
    }
    return b.toString();
  }

  /** "k7qm 2xpa", "K7QM2XPA" and "K7QM-2XPA" are the same code. */
  static normalise(code) {
    const s = Ui.nz(code).toUpperCase().replaceAllRx("[^A-Z0-9]", "");
    return s.length === 8 ? s.substring(0, 4) + "-" + s.substring(4) : s;
  }

  /** Records a document and returns its code. */
  static register(c, title, fileBase, madeBy) {
    const db = Db.get(c);
    const code = DocVerify.newCode();
    const cv = new ContentValues();
    cv.put("code", code);
    cv.put("title", Ui.nz(title));
    cv.put("file_base", Ui.nz(fileBase));
    cv.put("made_by", Ui.nz(madeBy));
    cv.put("made_at", Dates.todayIso() + " " + Dates.now());
    db.insert(DocVerify.TABLE, cv);
    return code;
  }

  static find(db, code) {
    const n = DocVerify.normalise(code);
    if (n.length !== 9) return null;
    return db.row("SELECT * FROM " + DocVerify.TABLE + " WHERE code=? ORDER BY id DESC LIMIT 1", n);
  }

  /** What a phone camera shows when the QR code is scanned. */
  static qrText(code, title, madeAt) {
    let t = Ui.nz(title);
    if (t.length > 60) t = t.substring(0, 57) + "...";
    return "TVMCHMED verification code " + code + "\n" + t + "\nMade " + madeAt + "\nCheck it in TVMCHMED > Verify a document";
  }

  /** "18 Oct 2026, 10:30" for the printed line. */
  static when(madeAt) {
    const m = Ui.nz(madeAt);
    const d = m.length >= 10 ? Dates.nice(m.substring(0, 10)) : m;
    return m.length > 11 ? d + ", " + m.substring(11) : d;
  }
}
DocVerify.TABLE = "doc_verify";
DocVerify.COLOR = 0xFF0D3B66;
DocVerify.ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
;
/* ---- app/Docs.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Missing documentation (10.4): inpatients in for more than a day with no progress note in the last 24 hours, and
 * patients discharged in the last week whose case sheet has no final diagnosis. Shown on the home page for the member's
 * unit, on its own screen for every unit, and as the "Notes" column of the unit scorecard.
 */
class Docs {
  static COLOR = 0xFFBE123C;
  static HOURS = 24;

  static at(date, time) {
    const d = Dates.parse(date);
    if (d == null) return null;
    let t = LocalTime.MIDNIGHT;
    try {
      if (!Ui.nz(time).isEmpty()) t = LocalTime.parse(time);
    } catch (ignored) {
    }
    return LocalDateTime.of(d, t);
  }

  /** When the patient came in: the admission's date and time. */
  static admittedAt(db, p) {
    const e = db.row("SELECT date, time FROM events WHERE patient_id=? AND type=?", p.get("id"), Db.ADMIT);
    return Docs.at(e != null ? e.get("date") : p.get("admit_date"), e != null ? e.get("time") : "");
  }

  /** The time of the latest progress note, or null. */
  static lastNote(cs) {
    let best = null;
    for (const n of CaseSheet.notesByTime(cs)) {
      const at = Docs.at(CaseSheet.s(n, "date"), CaseSheet.s(n, "time"));
      if (at == null) continue;
      if (best == null || at.isAfter(best)) best = at;
    }
    return best;
  }

  static gaps(db, unit, now) {
    const out = [];
    const cut = now.minusHours(Docs.HOURS);
    // 10.4 speed: the admission times and the case sheets of every inpatient in two queries, not two per patient
    const sheets = new Map();
    for (const r of db.rows("SELECT c.id, c.data FROM case_sheets c JOIN patients p ON p.id=c.id WHERE p.status='IN'")) sheets.set(Ui.nz(r.get("id")), r.get("data"));
    for (const p of db.rows("SELECT p.*, e.date AS adm_d, e.time AS adm_t FROM patients p LEFT JOIN events e ON e.patient_id=p.id AND e.type=? "
        + "WHERE p.status='IN' ORDER BY p.location, p.bed, p.name", Db.ADMIT)) {
      if (!MorningBrief.inUnit(p, Ui.nz(unit))) continue;
      const inAt = Docs.at(p.get("adm_d") != null ? p.get("adm_d") : p.get("admit_date"), p.get("adm_d") != null ? p.get("adm_t") : "");
      if (inAt == null || inAt.isAfter(cut)) continue;
      let last = null;
      const data = sheets.get(Ui.nz(p.get("id")));
      if (data != null) {
        try {
          last = Docs.lastNote(new JSONObject(Ui.nz(data)));
        } catch (ignored) {
        }
      }
      if (last != null && !last.isBefore(cut)) continue;
      out.push({ p: p, noNote: true,
        what: last == null ? "No progress note yet" : "Last note " + Dates.nice(last.toLocalDate().toString()) + " " + last.toLocalTime().toString() });
    }
    const from = now.toLocalDate().minusDays(7).toString();
    for (const p of db.rows("SELECT * FROM patients WHERE status=? AND outcome_date>=? ORDER BY outcome_date DESC", Db.DISCHARGED, from)) {
      if (!MorningBrief.inUnit(p, Ui.nz(unit))) continue;
      if (!CaseSheet.s(CaseSheet.load(db, Long.parseLong(p.get("id"))), "final_dx").trim().isEmpty()) continue;
      out.push({ p: p, noNote: false, what: "Discharged " + Dates.nice(p.get("outcome_date")) + " without a final diagnosis in the case sheet" });
    }
    return out;
  }

  /** Share of the unit's discharges in the period with a final diagnosis in the case sheet, or -1 when none. */
  static finalDxPercent(db, unit, from, to) {
    let all = 0, ok = 0;
    for (const p of db.rows("SELECT id FROM patients WHERE status=? AND home_unit=? AND outcome_date BETWEEN ? AND ?", Db.DISCHARGED, unit, from, to)) {
      all++;
      if (!CaseSheet.s(CaseSheet.load(db, Long.parseLong(p.get("id"))), "final_dx").trim().isEmpty()) ok++;
    }
    return all === 0 ? -1 : Math.round(ok * 100 / all);
  }

  static homeCard(a, db) {
    const unit = MorningBrief.myUnit(a, db);
    const g = Docs.gaps(db, unit, LocalDateTime.of(Dates.today(), Dates.time()));
    if (g.length === 0) return null;
    let notes = 0;
    for (const x of g) if (x.noNote) notes++;
    const card = Ui.card(a);
    card.addView(Ui.softPill(a, "MISSING NOTES" + (unit.isEmpty() ? "" : " · " + Db.shortName(unit)), Docs.COLOR));
    const bits = [];
    if (notes > 0) bits.push(notes + (notes === 1 ? " patient" : " patients") + " without a note in 24 h");
    if (g.length > notes) bits.push((g.length - notes) + " discharged without final diagnosis");
    const t = Ui.tv(a, "📝 " + bits.join("  ·  "), 16, Ui.TEXT, true);
    card.addView(t);
    Ui.margins(t, 0, 6, 0, 0);
    const go = Ui.outlineButton(a, "See who", Docs.COLOR, a.opener(DocsActivity, "unit", unit));
    card.addView(go);
    Ui.margins(go, 0, 10, 0, 0);
    const bg = Ui.round(a, Ui.mix(Docs.COLOR, Color.WHITE, 0.94), 18);
    bg.setStroke(Ui.dp(a, 2), Docs.COLOR);
    card.setBackground(bg);
    return card;
  }
}
;
/* ---- app/DocsActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Missing documentation (10.4): who has no progress note in 24 hours or no final diagnosis, by unit. */
class DocsActivity extends Base {
  constructor() {
    super();
    this.unit = "";
  }

  onCreate(b) {
    super.onCreate(b);
    const u = this.getIntent().getStringExtra("unit");
    if (u != null) this.unit = u;
    this.setTitle("Missing notes");
    this.subtitle = "No progress note in 24 h · no final diagnosis";
    this.headerColor(Docs.COLOR);
  }

  render() {
    const page = Ui.v(this);
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    for (const u of [""].concat(Db.WARD_UNITS)) {
      const c = Ui.chip(this, u.isEmpty() ? "All units" : Db.shortName(u), u === this.unit, u.isEmpty() ? Docs.COLOR : Ui.unitColor(u));
      c.setOnClickListener({ onClick: (v) => { this.unit = u; this.render(); } });
      chips.addView(c);
      Ui.margins(c, 0, 0, 6, 0);
    }
    page.addView(Ui.hscroll(this, chips));
    const g = Docs.gaps(this.db, this.unit, LocalDateTime.of(Dates.today(), Dates.time()));
    if (g.length === 0) {
      const ok = Ui.card(this);
      ok.addView(Ui.tv(this, "✓ All notes are up to date", 17, Ui.GREEN, true));
      ok.addView(Ui.muted(this, "Every inpatient in for more than a day has a progress note in the last 24 hours, and every discharge of the last week has a final diagnosis."));
      page.addView(ok);
    }
    let head1 = false, head2 = false;
    for (const x of g) {
      if (x.noNote && !head1) {
        page.addView(Ui.heading(this, "No progress note in 24 hours", Docs.COLOR));
        head1 = true;
      }
      if (!x.noNote && !head2) {
        page.addView(Ui.heading(this, "Discharged without a final diagnosis", Ui.ORANGE));
        head2 = true;
      }
      this.addEntry(page, x);
    }
    this.setPage(page);
  }

  addEntry(page, x) {
    page.addView(this.entryCard(Db.shortName(Ui.nz(x.p.get("location"))) + (Ui.nz(x.p.get("bed")).isEmpty() ? "" : " · bed " + x.p.get("bed")),
        Ui.unitColor(Ui.nz(x.p.get("home_unit"))), Ui.nz(x.p.get("name")), x.what + "\n" + Ui.nz(x.p.get("diagnosis")), null,
        this.opener(CaseSheetActivity, "id", x.p.get("id")), 3));
  }
}
;
/* ---- app/DoubtBubble.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * 10.7 (the admin's picture): the golden glass heart of the PG question corner, in place of the old speech bubble. It
 * revolves on its own axis: the more doubts are open the faster it turns, and it beats faster too, every beat sending a
 * golden ripple across the floor. Rings of golden light circle it with a comet running round each, one golden pearl
 * orbits for each open doubt, and golden bokeh drifts in the dark behind. When a doubt gets an answer it slows and a pearl
 * bursts into sparkles; when every doubt has an answer it glides to rest facing front, beating calmly, a green tick pops up
 * and golden confetti falls. Tap it for a spin. The heart is the picture doubt_heart.webp (cut out from the admin's
 * picture); everything else is drawn here.
 */
class DoubtBubble extends View {
  static SPARK = [0xFFFFE7A3, 0xFFFFD24A, 0xFFF5B43C, 0xFFFFF4D6, 0xFFFFFFFF, 0xFFE89B2A];
  static BOKEH = [0xFFFFC94A, 0xFFF5A623, 0xFFFFE08A, 0xFF5B8CFF, 0xFFFFB347];
  static MAX_DOTS = 14;
  static BOKEH_N = 26;
  static RIPPLES = 6;
  /** Edge shades from the far side (dark) to just behind the face (bright). */
  static EDGE = [0xFF4A2F04, 0xFF6B4508, 0xFF8C5B0E, 0xFFAD7418, 0xFFCB8F26, 0xFFE3AC3E];
  static LAYERS = 16;

  constructor(c) {
    super(c);
    this.dp = Ui.dp(c, 1);
    this.aspect = 525 / 720;   // the heart picture's width / height
    const A = Paint.ANTI_ALIAS_FLAG;
    this.bmp = new Paint(A | Paint.FILTER_BITMAP_FLAG); this.aura = new Paint(A); this.core = new Paint(A);
    this.plain = new Paint(A); this.line = new Paint(A);
    this.star = new Path();
    this.oval = new RectF(); this.box = new RectF();
    this.parts = [];
    const N = DoubtBubble.BOKEH_N;
    this.bx = new Array(N).fill(0); this.by = new Array(N).fill(0); this.br = new Array(N).fill(0); this.bp = new Array(N).fill(0);
    this.ripple = new Array(DoubtBubble.RIPPLES).fill(9);
    this.openN = 0; this.shownOpen = -1;
    this.shown = 0; this.angle = 0; this.spd = 0; this.orbit = 0; this.t = 0; this.comet = 0; this.beatPh = 0;
    this.badge = 0; this.confetti = 0; this.emit = 0;
    this.last = 0; this.running = false; this.pend = 0; this.nextRipple = 0;
    this.tick = {
      run: () => {
        if (!this.isAttachedToWindow()) { this.running = false; return; }
        const now = System.nanoTime();
        const dt = this.last === 0 ? 0.016 : Math.min(0.05, (now - this.last) / 1e9);
        this.last = now;
        this.step(dt);
        this.invalidate();
        this.postDelayed(this.tick, 16);
      }
    };
    // a deep night sky, warming to gold at the floor
    const sky = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, [0xFF03050C, 0xFF070D24, 0xFF120F14, 0xFF241703]);
    sky.setCornerRadius(24 * this.dp);
    this.setBackground(sky);
    this.heart = BitmapFactory.decodeResource(c.getResources(), R.drawable.doubt_heart);
    this.aura.setShader(new RadialGradient(0, 0, 2.4, [0xAAFFC53D, 0x55F59E0B, 0x18F59E0B, 0x00F59E0B], [0, 0.35, 0.7, 1], Shader.TileMode.CLAMP));
    this.core.setShader(new RadialGradient(0, 0, 1, [0xEEFFFFFF, 0x99FFE7A3, 0x00FFD24A], [0, 0.3, 1], Shader.TileMode.CLAMP));
    this.line.setStyle(Paint.Style.STROKE);
    this.line.setStrokeCap(Paint.Cap.ROUND);
    for (let i = 0; i < N; i++) {
      this.bx[i] = DoubtBubble.frac(Math.sin(i * 12.9898 + 1.0) * 43758.5453);
      this.by[i] = DoubtBubble.frac(Math.sin(i * 78.233 + 2.0) * 24634.6345);
      this.br[i] = 0.25 + 0.75 * DoubtBubble.frac(Math.sin(i * 93.989 + 4.0) * 35758.5453);
      this.bp[i] = DoubtBubble.frac(Math.sin(i * 39.346 + 3.0) * 53758.5453) * 6.28;
    }
  }

  static frac(v) {
    return v - Math.floor(v);
  }

  /** Sets how many doubts have no answer yet; fewer than before bursts a pearl, none at all sends confetti. */
  setOpen(n) {
    if (this.shownOpen < 0) {            // first time: show the state without a celebration
      this.shownOpen = n;
      this.openN = n;
      this.shown = Math.min(n, DoubtBubble.MAX_DOTS);
      this.badge = n === 0 ? 1 : 0;
      this.spd = Doubts.spin(n);
      return;
    }
    if (n < this.openN) {
      this.pend = Math.max(this.pend, n === 0 ? 2 : 1);   // burst once the view has a size
      if (n === 0) this.confetti = 3;
    }
    if (n > this.openN) this.badge = 0;
    this.openN = n;
  }

  /** A flick: a quick extra spin and a puff of golden sparkles. */
  kick() {
    this.spd += 520;
    this.burst(this.getWidth() / 2, this.getHeight() * 0.44, 18, 140 * this.dp);
  }

  /** Degrees per second right now (for tests and the label). */
  speed() {
    return this.spd;
  }

  resting() {
    return this.openN === 0 && this.spd < 2;
  }

  /** Heartbeats per minute: calm at rest, quicker with every open doubt. */
  static bpm(open) {
    return open <= 0 ? 54 : Math.min(150, 66 + 9 * open);
  }

  onAttachedToWindow() {
    super.onAttachedToWindow && super.onAttachedToWindow();
    this.start();
  }

  wake() {
    this.start();
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = 0;
    this.postDelayed(this.tick, 16);
  }

  step(dt) {
    this.t += dt;
    const target = Doubts.spin(this.openN);
    this.spd += (target - this.spd) * Math.min(1, dt * (target > this.spd ? 2.0 : 1.4));
    this.angle += this.spd * dt;
    if (target === 0) {
      if (this.spd < 60) {          // glide to rest facing front
        const rest = Math.ceil(this.angle / 360) * 360;
        this.angle += (rest - this.angle) * Math.min(1, dt * 3.5);
        this.spd -= this.spd * Math.min(1, dt * 4);
        if (this.spd < 2 && rest - this.angle < 0.4) {
          this.spd = 0;
          this.angle = 0;
        }
      }
    }
    if (this.angle > 3600) this.angle -= 3600;
    this.orbit += (this.openN > 0 ? 26 + this.spd * 0.6 : 9) * dt;
    if (this.orbit > 3600) this.orbit -= 3600;
    this.comet += (40 + this.spd * 0.35) * dt;
    if (this.comet > 3600) this.comet -= 3600;
    // the heartbeat: every beat starts a ripple on the floor
    const before = this.beatPh;
    this.beatPh += dt * DoubtBubble.bpm(this.openN) / 60;
    if (Math.trunc(this.beatPh) !== Math.trunc(before)) {
      this.ripple[this.nextRipple] = 0;
      this.nextRipple = (this.nextRipple + 1) % DoubtBubble.RIPPLES;
    }
    if (this.beatPh > 1000) this.beatPh -= 1000;
    for (let i = 0; i < DoubtBubble.RIPPLES; i++) if (this.ripple[i] < 9) this.ripple[i] += dt;
    const want = Math.min(this.openN, DoubtBubble.MAX_DOTS);
    this.shown += (want - this.shown) * Math.min(1, dt * 3);
    this.badge += ((this.openN === 0 ? 1 : 0) - this.badge) * Math.min(1, dt * 4);
    const w = this.getWidth(), h = this.getHeight(), u = DoubtBubble.unit(w, h), cx = w / 2, cy = h * 0.44;
    const dp = this.dp, SPARK = DoubtBubble.SPARK;
    if (this.pend > 0 && w > 0) {
      this.burst(cx, cy, this.pend === 2 ? 60 : 24, this.pend === 2 ? 230 * dp : 150 * dp);
      this.pend = 0;
    }
    // golden dust thrown off while it turns, a slow rising glitter at rest
    this.emit += dt * (this.openN > 0 ? 9 + this.spd / 8 : 6);
    while (this.emit >= 1) {
      this.emit -= 1;
      const a = Math.random() * 6.2832;
      const r = u * (this.openN > 0 ? 0.95 : 0.75);
      const p = this.spawn(cx + Math.cos(a) * r * 0.8, cy + Math.sin(a) * r, SPARK[Math.trunc(Math.random() * SPARK.length)]);
      const v = this.openN > 0 ? 26 * dp + this.spd * 0.05 * dp : 10 * dp;
      p.vx = -Math.sin(a) * v;
      p.vy = Math.cos(a) * v * 0.5 - 16 * dp;
      p.max = p.life = 0.8 + Math.random() * 0.8;
    }
    if (this.confetti > 0) {
      this.confetti -= dt;
      for (let i = 0; i < 2; i++) {
        const p = this.spawn(Math.random() * w, -6 * dp, SPARK[Math.trunc(Math.random() * SPARK.length)]);
        p.vx = (Math.random() - 0.5) * 60 * dp;
        p.vy = 70 * dp + Math.random() * 90 * dp;
        p.grav = 40 * dp;
        p.size = (2.5 + Math.random() * 3) * dp;
        p.max = p.life = 2.2;
      }
    }
    for (let i = this.parts.length - 1; i >= 0; i--) {
      const p = this.parts[i];
      p.life -= dt;
      if (p.life <= 0) { this.parts.splice(i, 1); continue; }
      p.vy += p.grav * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
  }

  spawn(x, y, color) {
    const p = { x: x, y: y, vx: 0, vy: 0, life: 1, max: 1, size: (1.5 + Math.random() * 2.4) * this.dp, grav: 0, color: color };
    if (this.parts.length > 180) this.parts.shift();
    this.parts.push(p);
    return p;
  }

  burst(x, y, n, speedPx) {
    const SPARK = DoubtBubble.SPARK;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * 6.2832;
      const v = speedPx * (0.35 + Math.random() * 0.65);
      const p = this.spawn(x, y, SPARK[Math.trunc(Math.random() * SPARK.length)]);
      p.vx = Math.cos(a) * v;
      p.vy = Math.sin(a) * v;
      p.grav = 60 * this.dp;
      p.max = p.life = 0.8 + Math.random() * 0.7;
    }
  }

  static unit(w, h) {
    return Math.min(w * 0.24, h * 0.29);
  }

  /** Lub-dub: two quick swells in each beat (0 between beats, about 1 at the top of the first). */
  beat() {
    const ph = DoubtBubble.frac(this.beatPh);
    const a = (ph - 0.06) / 0.07, b = (ph - 0.30) / 0.07;
    return Math.exp(-a * a) + 0.6 * Math.exp(-b * b);
  }

  /** The heart picture turned by ang degrees about its upright axis (the back shows the mirror image, like glass). */
  drawHeart(cv, cx, cy, u, ang, alpha) {
    if (this.heart == null || alpha <= 0) return;
    const c = Math.cos(ang * Math.PI / 180);
    const sxs = Math.abs(c) < 0.03 ? (c < 0 ? -0.03 : 0.03) : c;
    const hh = u * 1.05, hw = hh * this.aspect;
    this.bmp.setAlpha(Math.trunc(alpha));
    cv.save();
    cv.translate(cx, cy);
    cv.scale(sxs, 1);
    this.box.set(-hw, -hh, hw, hh);
    cv.drawBitmap(this.heart, null, this.box, this.bmp);
    cv.restore();
  }

  // ---------- 10.31: the solid 3D heart (user asked): a thick golden slab with a lit face ----------

  /** The heart's outline in each edge shade, and a canvas for the lit face; made once the picture has a size. */
  prepare3d() {
    if (this.edges != null) return true;
    if (this.heart == null || this.heart.getWidth() <= 0 || this.heart.getHeight() <= 0) return false;
    if (!this.fx) {
      this.fx = new Paint(Paint.ANTI_ALIAS_FLAG);
      this.atop = new PorterDuffXfermode(PorterDuff.Mode.SRC_ATOP);
      this.srcIn = new PorterDuffXfermode(PorterDuff.Mode.SRC_IN);
    }
    const w = Math.max(1, Math.trunc(this.heart.getWidth() / 2)), h = Math.max(1, Math.trunc(this.heart.getHeight() / 2));
    const out = [];
    const all = new Rect(0, 0, w, h);
    for (let i = 0; i < DoubtBubble.EDGE.length; i++) {
      const b = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
      const c = new Canvas(b);
      c.drawBitmap(this.heart, null, all, null);
      this.fx.setShader(null);
      this.fx.setXfermode(this.srcIn);
      this.fx.setColor(DoubtBubble.EDGE[i]);
      c.drawRect(0, 0, w, h, this.fx);
      this.fx.setXfermode(null);
      out.push(b);
    }
    this.face = Bitmap.createBitmap(this.heart.getWidth(), this.heart.getHeight(), Bitmap.Config.ARGB_8888);
    this.faceCv = new Canvas(this.face);
    this.edges = out;
    return true;
  }

  /** The face for this angle: the picture, a band of light sweeping across as it turns, darker when turned away. */
  lightFace(s, c) {
    const w = this.face.getWidth(), h = this.face.getHeight();
    this.faceCv.drawColor(0, PorterDuff.Mode.CLEAR);
    this.faceCv.drawBitmap(this.heart, 0, 0, null);
    const mid = w * (0.5 - 0.9 * s);
    this.fx.setXfermode(this.atop);
    this.fx.setShader(new LinearGradient(mid - w * 0.45, 0, mid + w * 0.45, h * 0.35,
      [0x00FFFFFF, 0x00FFFFFF, 0x99FFF6DA, 0x00FFFFFF, 0x00FFFFFF], [0, 0.3, 0.5, 0.7, 1], Shader.TileMode.CLAMP));
    this.faceCv.drawRect(0, 0, w, h, this.fx);
    this.fx.setShader(null);
    const dark = 0.55 * (1 - Math.abs(c)) + (c < 0 ? 0.12 : 0);
    this.fx.setColor(Color.argb(Math.trunc(255 * Math.min(0.7, dark)), 20, 10, 0));
    this.faceCv.drawRect(0, 0, w, h, this.fx);
    this.fx.setXfermode(null);
  }

  /** The heart as a solid: edge layers stacked through its thickness, then the lit face that looks at you. */
  drawSolidHeart(cv, cx, cy, u, ang) {
    if (!this.prepare3d()) {
      this.drawHeart(cv, cx, cy, u, ang, 255);
      return;
    }
    const r = ang * Math.PI / 180;
    const c = Math.cos(r), s = Math.sin(r);
    const sxs = Math.abs(c) < 0.03 ? (c < 0 ? -0.03 : 0.03) : c;
    const hh = u * 1.05, hw = hh * this.aspect, depth = hw * 0.30, sign = c < 0 ? -1 : 1;
    const L = DoubtBubble.LAYERS;
    this.bmp.setAlpha(255);
    this.box.set(-hw, -hh, hw, hh);
    for (let j = 0; j <= L; j++) {
      const z = (j / L - 0.5) * depth * sign;   // far side first, the face last
      cv.save();
      cv.translate(cx + z * s, cy);
      cv.scale(sxs, 1);
      if (j < L) {
        cv.drawBitmap(this.edges[Math.min(DoubtBubble.EDGE.length - 1, Math.trunc(j * DoubtBubble.EDGE.length / L))], null, this.box, this.bmp);
      } else {
        this.lightFace(s * sign, c);
        cv.drawBitmap(this.face, null, this.box, this.bmp);
      }
      cv.restore();
    }
  }

  /** One tilted ring of golden light round the heart with a comet running round it: its front or back half. */
  ringHalf(cv, cx, cy, tilt, rx, ry, phase, front) {
    const dp = this.dp, line = this.line, plain = this.plain;
    cv.save();
    cv.translate(cx, cy);
    cv.rotate(tilt);
    this.oval.set(-rx, -ry, rx, ry);
    const start = front ? 0 : 180;
    line.setStrokeWidth(7 * dp);
    line.setColor(0x26FFC53D);
    cv.drawArc(this.oval, start, 180, false, line);
    line.setStrokeWidth(1.6 * dp);
    line.setColor(front ? 0xCCFFD875 : 0x77FFD875);
    cv.drawArc(this.oval, start, 180, false, line);
    const head = (phase % 360 + 360) % 360;
    for (let k = 0; k < 10; k++) {
      const an = ((head - k * 5) % 360 + 360) % 360;
      if ((an < 180) !== front) continue;
      const r = an * Math.PI / 180;
      const x = Math.cos(r) * rx, y = Math.sin(r) * ry;
      const f = 1 - k / 10;
      plain.setColor(Color.argb(Math.trunc(200 * f * f), 255, 226, 140));
      cv.drawCircle(x, y, (k === 0 ? 3.4 : 2.6 * f + 0.6) * dp, plain);
      if (k === 0) {
        plain.setColor(0x55FFD24A);
        cv.drawCircle(x, y, 9 * dp, plain);
        plain.setColor(0xFFFFFFFF);
        this.spark(cv, x, y, 2.6 * dp);
      }
    }
    cv.restore();
  }

  pearl(cv, i, cx, cy, u, front) {
    const k = Math.max(0, Math.min(1, this.shown - i));
    if (k <= 0.01) return;
    const cnt = Math.max(1, Math.ceil(this.shown));
    const a = (this.orbit + i * 360 / cnt) * Math.PI / 180;
    const z = Math.sin(a);
    if ((z >= 0) !== front) return;
    const rx = u * 1.45, ry = rx * 0.26;
    const x = cx + Math.cos(a) * rx, y = cy + u * 0.25 + z * ry;
    const r = u * 0.075 * (0.75 + 0.25 * z) * k;
    const plain = this.plain;
    plain.setColor(0x44FFC53D);
    cv.drawCircle(x, y, r * 2.4, plain);
    plain.setColor(i % 2 === 0 ? 0xFFFFC53D : 0xFFF59E0B);
    cv.drawCircle(x, y, r, plain);
    plain.setColor(0xEEFFFFFF);
    cv.drawCircle(x - r * 0.3, y - r * 0.3, r * 0.34, plain);
  }

  onDraw(cv) {
    const w = this.getWidth(), h = this.getHeight();
    if (w <= 0 || h <= 0) return;
    if (!this.running) this.start();
    const dp = this.dp, plain = this.plain, line = this.line, oval = this.oval, t = this.t;
    const u = DoubtBubble.unit(w, h), cx = w / 2;
    const bob = Math.sin(t * 1.5) * u * 0.04;
    const cy = h * 0.44 + bob, floor = h * 0.44 + u * 1.22;
    const b = this.beat(), pump = 1 + 0.045 * b;

    // golden bokeh drifting up through the dark
    for (let i = 0; i < DoubtBubble.BOKEH_N; i++) {
      const br = this.br[i], bp = this.bp[i];
      const y = DoubtBubble.frac(this.by[i] - t * 0.012 * (0.5 + br)) * h;
      const x = this.bx[i] * w + Math.sin(t * 0.3 + bp) * 6 * dp;
      const tw = 0.5 + 0.5 * Math.sin(t * (0.8 + i % 4 * 0.3) + bp);
      const r = (3 + br * 11) * dp;
      const col = DoubtBubble.BOKEH[i % DoubtBubble.BOKEH.length];
      plain.setColor(((col & 0x00FFFFFF) | (Math.trunc(12 + 18 * tw) << 24)) >>> 0);
      cv.drawCircle(x, y, r * 1.5, plain);
      plain.setColor(((col & 0x00FFFFFF) | (Math.trunc(30 + 55 * tw) << 24)) >>> 0);
      cv.drawCircle(x, y, r * 0.75, plain);
    }
    // the warm glow behind, swelling with each beat
    cv.save();
    cv.translate(cx, cy);
    const g = u * (1 + 0.10 * b + 0.03 * Math.sin(t * 1.1));
    cv.scale(g, g);
    cv.drawCircle(0, 0, 2.4, this.aura);
    cv.restore();

    // the floor: still rings, a ripple from each beat, the glowing pool and the reflection
    line.setStrokeWidth(1.2 * dp);
    for (let k = 1; k <= 3; k++) {
      line.setColor(Color.argb(60 - k * 14, 255, 200, 90));
      oval.set(cx - u * 0.5 * k, floor - u * 0.09 * k, cx + u * 0.5 * k, floor + u * 0.09 * k);
      cv.drawOval(oval, line);
    }
    for (let i = 0; i < DoubtBubble.RIPPLES; i++) {
      const age = this.ripple[i];
      if (age >= 2.4) continue;
      const f = age / 2.4, rx = u * (0.3 + 2.1 * f);
      line.setStrokeWidth((2.2 - 1.4 * f) * dp);
      line.setColor(Color.argb(Math.trunc(190 * (1 - f) * (1 - f)), 255, 210, 110));
      oval.set(cx - rx, floor - rx * 0.17, cx + rx, floor + rx * 0.17);
      cv.drawOval(oval, line);
    }
    if (this.heart != null) {
      // the reflection: upside down under the floor, fading away in bands
      const depth = Math.min(h - floor, u * 0.9);
      const bands = 6;
      for (let k = 0; k < bands; k++) {
        cv.save();
        cv.clipRect(0, floor + depth * k / bands, w, floor + depth * (k + 1) / bands);
        cv.translate(0, 2 * floor);
        cv.scale(1, -1);
        this.drawHeart(cv, cx, cy, u * pump, this.angle, Math.trunc(58 * (1 - k / bands)));
        cv.restore();
      }
    }
    plain.setColor(Color.argb(Math.trunc(70 + 60 * b), 255, 196, 70));
    oval.set(cx - u * 0.42, floor - u * 0.06, cx + u * 0.42, floor + u * 0.06);
    cv.drawOval(oval, plain);
    plain.setColor(Color.argb(Math.trunc(Math.min(255, 140 + 80 * b)), 255, 240, 200));
    oval.set(cx - u * 0.16, floor - u * 0.025, cx + u * 0.16, floor + u * 0.025);
    cv.drawOval(oval, plain);

    // back halves of the rings and the pearls, behind the heart
    const r1 = u * 1.62, r2 = u * 1.38;
    this.ringHalf(cv, cx, cy + u * 0.08, -14, r1, r1 * 0.30, this.comet, false);
    this.ringHalf(cv, cx, cy + u * 0.02, 11, r2, r2 * 0.34, -this.comet * 1.3 + 140, false);
    const n = Math.ceil(this.shown);
    for (let i = 0; i < n; i++) this.pearl(cv, i, cx, cy, u, false);

    // fast turns leave golden ghosts behind
    if (this.spd > 200) {
      const gh = Math.min(1, (this.spd - 200) / 500);
      this.drawHeart(cv, cx, cy, u * pump, this.angle - this.spd * 0.020, 70 * gh);
      this.drawHeart(cv, cx, cy, u * pump, this.angle - this.spd * 0.040, 36 * gh);
    }
    this.drawSolidHeart(cv, cx, cy, u * pump, this.angle);
    // the light inside flares with each beat, brightest when the heart faces you
    const face = Math.abs(Math.cos(this.angle * Math.PI / 180));
    const fl = Math.min(1, (0.35 + 0.65 * b) * (0.4 + 0.6 * face));
    cv.save();
    cv.translate(cx + u * 0.04, cy - u * 0.02);
    const cs = u * (0.30 + 0.22 * b);
    cv.scale(cs, cs);
    this.core.setAlpha(Math.trunc(255 * fl));
    cv.drawCircle(0, 0, 1, this.core);
    cv.restore();
    plain.setColor(Color.argb(Math.trunc(230 * fl), 255, 255, 255));
    this.spark(cv, cx + u * 0.04, cy - u * 0.02, u * (0.05 + 0.06 * b) * (0.5 + 0.5 * face));

    this.ringHalf(cv, cx, cy + u * 0.08, -14, r1, r1 * 0.30, this.comet, true);
    this.ringHalf(cv, cx, cy + u * 0.02, 11, r2, r2 * 0.34, -this.comet * 1.3 + 140, true);
    for (let i = 0; i < n; i++) this.pearl(cv, i, cx, cy, u, true);

    // golden dust and confetti
    for (let i = 0; i < this.parts.length; i++) {
      const p = this.parts[i];
      const f = p.life / p.max;
      plain.setColor(((p.color & 0x00FFFFFF) | (Math.trunc(255 * Math.min(1, f * 1.6)) << 24)) >>> 0);
      if (p.grav > 0 && p.max > 2) {
        cv.drawRect(p.x - p.size, p.y - p.size * 0.5, p.x + p.size, p.y + p.size * 0.5, plain);
      } else {
        this.spark(cv, p.x, p.y, p.size * (0.6 + f));
      }
    }
    // the green tick in a gold ring when every doubt has an answer
    if (this.badge > 0.02) {
      const bb = Math.min(1, this.badge) * (1 + 0.15 * Math.sin(Math.min(1, this.badge) * 3.14159));
      const r = u * 0.26;
      cv.save();
      cv.translate(cx + u * 0.95, cy - u * 0.82);
      cv.scale(bb, bb);
      plain.setColor(0x5522C55E);
      cv.drawCircle(0, 0, r * 1.5, plain);
      plain.setColor(0xFFFFD875);
      cv.drawCircle(0, 0, r * 1.1, plain);
      plain.setColor(0xFF16A34A);
      cv.drawCircle(0, 0, r, plain);
      line.setColor(0xFFFFFFFF);
      line.setStrokeWidth(r * 0.22);
      cv.drawLine(-r * 0.45, 0, -r * 0.1, r * 0.36, line);
      cv.drawLine(-r * 0.1, r * 0.36, r * 0.5, -r * 0.34, line);
      cv.restore();
    }
  }

  /** A four-point sparkle. */
  spark(cv, x, y, r) {
    const s = this.star;
    s.reset();
    s.moveTo(x, y - r * 1.6);
    s.quadTo(x, y, x + r * 1.6, y);
    s.quadTo(x, y, x, y + r * 1.6);
    s.quadTo(x, y, x - r * 1.6, y);
    s.quadTo(x, y, x, y - r * 1.6);
    s.close();
    cv.drawPath(s, this.plain);
  }
}
;
