/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Exam cases (7.81): faculty and PGs mark in-patients with good clinical signs as exam cases, and the PGs give them
 * to MBBS students and PGs for the daily case presentation to the faculty. A case leaves the list when the patient
 * leaves hospital.
 */
class ExamCases {
  constructor() {}

  static TABLE = "exam_cases";
  static ALLOTS = "exam_allots";
  static COLOR = 0xFFC2410C;
  static HERO = [0xFFF97316, 0xFFC2410C, 0xFF7C2D12];
  static KINDS = ["Long case", "Short case", "Spotter"];
  static SYSTEMS = ["CVS", "RS", "Abdomen", "CNS", "Endocrine", "Renal", "Haematology", "Rheumatology", "Infection", "Toxicology", "Other"];
  static SYSTEM_COLORS = [0xFFDC2626, 0xFF0284C7, 0xFF16A34A, 0xFF7C3AED, 0xFFCA8A04, 0xFF0891B2, 0xFFBE123C, 0xFF9333EA, 0xFF0F766E, 0xFF65A30D, 0xFF475569];
  static LEVELS = ["MBBS", "PG"];

  static systemColor(s) {
    const i = ExamCases.SYSTEMS.indexOf(s);
    return ExamCases.SYSTEM_COLORS[i < 0 ? ExamCases.SYSTEMS.length - 1 : i];
  }

  /** Faculty (any rank), the HOD, the registrar, the admin and the PGs mark cases and give them out; everyone else only sees the list. */
  static canMark(c) {
    if (!Cloud.active(c)) return true;
    const r = Cloud.role(c);
    return Cloud.isManager(r) || "professor".equals(r) || "faculty".equals(r) || "pg".equals(r);
  }

  static myName(c, db) {
    return Chat.myName(c, db);
  }

  /** The exam case entry of this patient, if marked. */
  static forPatient(db, patientId) {
    return db.row("SELECT * FROM " + ExamCases.TABLE + " WHERE patient_id=? AND active='1' ORDER BY id DESC LIMIT 1", String(patientId));
  }

  /** Every exam case whose patient is still in hospital, with the patient's details, newest first. */
  static current(db) {
    const TABLE = ExamCases.TABLE, ALLOTS = ExamCases.ALLOTS;
    return db.rows("SELECT e.*, p.name, p.age, p.sex, p.ip_no, p.bed, p.location, p.home_unit, p.diagnosis, p.admit_date, "
        + "(SELECT COUNT(*) FROM " + ALLOTS + " a WHERE a.case_id=e.id) AS given, "
        + "(SELECT MAX(a.date) FROM " + ALLOTS + " a WHERE a.case_id=e.id) AS last_given "
        + "FROM " + TABLE + " e JOIN patients p ON p.id=e.patient_id WHERE e.active='1' AND p.status=? ORDER BY e.time DESC, e.id DESC", Db.IN);
  }

  static count(db) {
    return db.num("SELECT COUNT(*) FROM " + ExamCases.TABLE + " e JOIN patients p ON p.id=e.patient_id WHERE e.active='1' AND p.status=?", Db.IN);
  }

  /** The day's presentations: who presents which case. */
  static allotted(db, day) {
    return db.rows("SELECT a.*, e.kind, e.system, p.name, p.age, p.sex, p.bed, p.location, p.home_unit, p.diagnosis FROM " + ExamCases.ALLOTS + " a "
        + "JOIN " + ExamCases.TABLE + " e ON e.id=a.case_id JOIN patients p ON p.id=a.patient_id WHERE a.date=? ORDER BY a.level, a.time, a.id", day);
  }

  static mark(c, db, patientId, kind, system, points) {
    const old = ExamCases.forPatient(db, patientId);
    const cv = new ContentValues();
    cv.put("kind", kind);
    cv.put("system", system);
    cv.put("points", points);
    if (old != null) {
      const id = Long.parseLong(old.get("id"));
      db.update(ExamCases.TABLE, cv, id);
      return id;
    }
    cv.put("patient_id", patientId);
    cv.put("marked_by", ExamCases.myName(c, db));
    cv.put("marked_role", Cloud.active(c) ? Cloud.roleLabel(Cloud.role(c)) : "");
    cv.put("time", Chat.now());
    cv.put("active", "1");
    return db.insert(ExamCases.TABLE, cv);
  }

  static unmark(c, db, id) {
    const cv = new ContentValues();
    cv.put("active", "");
    cv.put("removed_by", ExamCases.myName(c, db));
    db.update(ExamCases.TABLE, cv, Long.parseLong(id));
  }

  /** Status of a given case (7.82): '' = given (same unit, or allowed), WAIT = waiting for the case's unit, NO = not allowed. */
  static WAIT = "wait";
  static NO = "no";

  /** The units the case belongs to: the ward or special ward it lies in, and its admitting unit. */
  static owners(r) {
    const o = [];
    for (const u of [Ui.nz(r.get("location")), Ui.nz(r.get("home_unit"))]) if (!u.isEmpty() && !o.contains(u)) o.add(u);
    return o;
  }

  /** "M3" or "IMCU / M5": whose permission is needed. */
  static ownerLabel(r) {
    const sb = new StringBuilder();
    for (const u of ExamCases.owners(r)) sb.append(sb.isEmpty() ? "" : " / ").append(Db.shortName(u));
    return sb.toString();
  }

  /** The student's unit from the Students list, or null. */
  static unitOfStudent(db, name) {
    const s = db.row("SELECT unit FROM staff WHERE name=? AND unit<>'' LIMIT 1", name);
    return s == null ? null : s.get("unit");
  }

  /** A case goes to a student of its own unit (or ward) freely; to another unit's student only with permission. */
  static needsPermission(r, studentUnit) {
    return studentUnit == null || studentUnit.isEmpty() || !ExamCases.owners(r).contains(studentUnit);
  }

  /** Who may allow a case to go to another unit: that unit's or special ward's PGs and Assistant Professors (and its Professors), the HOD, the registrar and the admin. */
  static canPermit(c, db, r) {
    if (!Cloud.active(c)) return true;
    if (Cloud.isAdmin(c) || Chat.isHod(c, db)) return true;
    const me = Cloud.myStaff(c);
    if (me <= 0) return false;
    const s = db.row("SELECT unit, role FROM staff WHERE id=?", String(me));
    if (s == null) return false;
    const role = Ui.nz(s.get("role"));
    if (!(role.equals("Postgraduate") || role.endsWith("Professor"))) return false;
    return ExamCases.owners(r).contains(Ui.nz(s.get("unit")));
  }

  /** Cases waiting for this person's permission. */
  static waitingForMe(c, db) {
    const out = [];
    for (const a of db.rows("SELECT a.*, e.kind, e.system, p.name, p.age, p.sex, p.bed, p.location, p.home_unit, p.diagnosis FROM " + ExamCases.ALLOTS + " a "
        + "JOIN " + ExamCases.TABLE + " e ON e.id=a.case_id JOIN patients p ON p.id=a.patient_id WHERE a.status=? AND p.status=? ORDER BY a.date, a.id", ExamCases.WAIT, Db.IN))
      if (ExamCases.canPermit(c, db, a)) out.add(a);
    return out;
  }

  static permit(c, db, allotId, allow) {
    const cv = new ContentValues();
    cv.put("status", allow ? "" : ExamCases.NO);
    cv.put("permit_by", ExamCases.myName(c, db));
    cv.put("permit_time", Chat.now());
    db.update(ExamCases.ALLOTS, cv, Long.parseLong(allotId));
  }

  /**
   * Gives the case; to another unit's student it waits for that unit's permission unless the giver may allow it.
   * (Java overloads: give(c, db, ec, day, student, level, faculty) looks up the student's unit.)
   */
  static give(c, db, ec, day, student, level, faculty, studentUnit) {
    if (arguments.length < 8) studentUnit = ExamCases.unitOfStudent(db, student);
    const cv = new ContentValues();
    cv.put("student_unit", Ui.nz(studentUnit));
    if (ExamCases.needsPermission(ec, studentUnit)) {
      if (ExamCases.canPermit(c, db, ec)) {
        cv.put("status", "");
        cv.put("permit_by", ExamCases.myName(c, db));
        cv.put("permit_time", Chat.now());
      } else cv.put("status", ExamCases.WAIT);
    } else cv.put("status", "");
    cv.put("case_id", ec.get("id"));
    cv.put("patient_id", ec.get("patient_id"));
    cv.put("date", day);
    cv.put("student", student);
    cv.put("level", level);
    cv.put("faculty", faculty);
    cv.put("by_name", ExamCases.myName(c, db));
    cv.put("time", Chat.now());
    cv.put("presented", "");
    return db.insert(ExamCases.ALLOTS, cv);
  }

  static setPresented(db, allotId, done) {
    const cv = new ContentValues();
    cv.put("presented", done ? "1" : "");
    db.update(ExamCases.ALLOTS, cv, Long.parseLong(allotId));
  }

  static ungive(db, allotId) {
    db.delete(ExamCases.ALLOTS, Long.parseLong(allotId));
  }

  /** "M3 male ward · M3 unit" or "IMCU · M5 unit". */
  static ward(r) {
    const loc = Ui.nz(r.get("location")), home = Ui.nz(r.get("home_unit"));
    const w = Db.isWardUnit(loc) ? loc + ("F".equals(r.get("sex")) ? " female" : " male") + " ward" : Db.shortName(loc);
    return w + (home.isEmpty() ? "" : "  ·  " + home + " unit");
  }

  static patientLine(r) {
    const age = Ui.nz(r.get("age")).isEmpty() ? "" : r.get("age") + "/" + Ui.nz(r.get("sex"));
    return Ui.nz(r.get("name")) + (age.isEmpty() ? "" : ", " + age) + (Ui.nz(r.get("bed")).isEmpty() ? "" : ", bed " + r.get("bed"));
  }

  /** The day's list for the WhatsApp group. */
  static whatsapp(db, day) {
    const sb = new StringBuilder("🎓 *Case presentations, " + Dates.nice(day) + "*\nDepartment of Medicine, TVMCH\n");
    const a = [];
    for (const r of ExamCases.allotted(db, day)) if (Ui.nz(r.get("status")).isEmpty()) a.add(r);
    if (a.isEmpty()) sb.append("\nNo cases given yet.\n");
    let n = 0;
    for (const r of a) {
      n++;
      sb.append("\n").append(n).append(". *").append(Ui.nz(r.get("student"))).append("* (").append(Ui.nz(r.get("level"))).append(")\n   ")
          .append(Ui.nz(r.get("kind"))).append(" · ").append(Ui.nz(r.get("system"))).append("\n   ")
          .append(ExamCases.patientLine(r)).append("\n   📍 ").append(ExamCases.ward(r));
      if (!Ui.nz(r.get("faculty")).isEmpty()) sb.append("\n   Present to: ").append(r.get("faculty"));
      sb.append("\n");
    }
    return sb.toString();
  }
}
;
/* ---- app/ExamCasesActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Exam cases: every in-patient marked as an exam case, with the ward and unit, filters by ward, system and case type,
 * and the day's case presentations (which MBBS student or PG presents which case, to whom).
 */
class ExamCasesActivity extends Base {
  constructor() { super(); this.wardFilter = ""; this.systemFilter = ""; this.kindFilter = ""; }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Exam cases");
    this.headerColor(ExamCases.COLOR);
  }

  liveRefresh() {
    return true;
  }

  wrap(v) {
    const p = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    p.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 6));
    v.setLayoutParams(p);
    return v;
  }

  render() {
    const all = ExamCases.current(this.db);
    this.subtitle = all.size() + (all.size() == 1 ? " case" : " cases") + " in the wards now";
    const page = Ui.v(this);
    const today = Dates.todayIso();
    const todays = ExamCases.allotted(this.db, today);
    page.addView(this.hero(all, todays));
    const waiting = ExamCases.waitingForMe(this, this.db);
    if (!waiting.isEmpty()) page.addView(this.permitCard(waiting));
    page.addView(this.todayCard(todays, today));

    // filters: ward or unit, system, case type
    const wards = new JMap();
    for (const w of Db.CENSUS_WARDS) wards.put(w, 0);
    wards.put(Db.KDP, 0);
    for (const r of all) {
      const w = Ui.nz(r.get("location"));
      wards.put(w, (wards.containsKey(w) ? wards.get(w) : 0) + 1);
    }
    const wf = Ui.h(this);
    wf.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 2));
    wf.addView(this.filterChip("All wards · " + all.size(), this.wardFilter.isEmpty(), ExamCases.COLOR, "w", ""));
    for (const e of wards.entrySet())
      if (e.getValue() > 0) wf.addView(this.filterChip(Db.shortName(e.getKey()) + " · " + e.getValue(), this.wardFilter.equals(e.getKey()), Ui.unitColor(e.getKey()), "w", e.getKey()));
    page.addView(Ui.hscroll(this, wf));
    const sf = Ui.h(this);
    sf.setPadding(Ui.dp(this, 12), Ui.dp(this, 2), Ui.dp(this, 12), Ui.dp(this, 2));
    sf.addView(this.filterChip("All types", this.kindFilter.isEmpty(), ExamCases.COLOR, "k", ""));
    for (const k of ExamCases.KINDS) sf.addView(this.filterChip(k, this.kindFilter.equals(k), ExamCases.COLOR, "k", k));
    sf.addView(this.filterChip("All systems", this.systemFilter.isEmpty(), Ui.SLATE, "s", ""));
    for (const s of ExamCases.SYSTEMS) {
      let n = 0;
      for (const r of all) if (s === r.get("system")) n++;
      if (n > 0) sf.addView(this.filterChip(s + " · " + n, this.systemFilter.equals(s), ExamCases.systemColor(s), "s", s));
    }
    page.addView(Ui.hscroll(this, sf));

    const shown = [];
    for (const r of all) {
      if (!this.wardFilter.isEmpty() && !this.wardFilter.equals(r.get("location"))) continue;
      if (!this.systemFilter.isEmpty() && !this.systemFilter.equals(r.get("system"))) continue;
      if (!this.kindFilter.isEmpty() && !this.kindFilter.equals(r.get("kind"))) continue;
      shown.add(r);
    }
    page.addView(Ui.heading(this, "Exam cases" + (this.wardFilter.isEmpty() ? "" : " in " + PgConnect.name(this.wardFilter)) + "  ·  " + shown.size(), ExamCases.COLOR));
    if (shown.isEmpty()) {
      const t = Ui.tv(this, all.isEmpty() ? "No exam cases yet.\nOpen any in-patient and tap 🎓 Mark as exam case."
          : "No exam cases match these filters.", 14, Ui.MUTED, false);
      t.setGravity(Gravity.CENTER);
      t.setPadding(Ui.dp(this, 20), Ui.dp(this, 24), Ui.dp(this, 20), Ui.dp(this, 24));
      page.addView(t);
    }
    for (const r of shown) page.addView(this.caseCard(r));
    this.setPage(page);
  }

  filterChip(label, on, color, which, value) {
    const c = Ui.chip(this, label, on, color);
    c.setOnClickListener({
      onClick: (v) => {
        if (which.equals("w")) this.wardFilter = value;
        else if (which.equals("s")) this.systemFilter = value;
        else this.kindFilter = value;
        this.render();
      }
    });
    return c;
  }

  hero(all, todays) {
    const h = Ui.v(this);
    h.setBackground(Glass.hero(this, ExamCases.HERO, 24));
    h.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const tag = Ui.tv(this, "🎓 CASE PRESENTATIONS", 11, Color.WHITE, true);
    tag.setLetterSpacing(0.12);
    tag.setBackground(Ui.round(this, 0x33FFFFFF, 12));
    tag.setPadding(Ui.dp(this, 10), Ui.dp(this, 3), Ui.dp(this, 10), Ui.dp(this, 3));
    const tr = Ui.h(this);
    tr.addView(tag);
    h.addView(tr);
    const title = Ui.tv(this, "Exam cases", 26, Color.WHITE, true);
    h.addView(title);
    Ui.margins(title, 0, 8, 0, 0);
    h.addView(Ui.tv(this, "Patients with good signs, marked by faculty and PGs, to give to MBBS students and PGs for presentation.", 13, 0xE6FFFFFF, false));
    let lc = 0, sc = 0, wardsWith = 0;
    const ws = new JSet();
    for (const r of all) {
      if ("Long case".equals(r.get("kind"))) lc++;
      else if ("Short case".equals(r.get("kind"))) sc++;
      ws.add(Ui.nz(r.get("location")));
    }
    wardsWith = ws.size();
    const stats = Ui.h(this);
    stats.addView(this.heroStat(String(all.size()), "cases"), Ui.weight(1));
    stats.addView(this.heroStat(lc + " / " + sc, "long / short"), Ui.weight(1));
    stats.addView(this.heroStat(String(wardsWith), "wards"), Ui.weight(1));
    stats.addView(this.heroStat(String(todays.size()), "today"), Ui.weight(1));
    h.addView(stats);
    Ui.margins(stats, 0, 12, 0, 0);
    return this.wrap(h);
  }

  heroStat(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    l.setBackground(Glass.frost(this, 14));
    l.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    const n = Ui.tv(this, v, 18, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 11, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    const p = Ui.lp(0, LinearLayout.LayoutParams.WRAP_CONTENT);
    p.weight = 1;
    p.setMargins(Ui.dp(this, 3), 0, Ui.dp(this, 3), 0);
    l.setLayoutParams(p);
    return l;
  }

  /** Today's presentations: student, case, ward, presented tick, and the WhatsApp list. */
  todayCard(todays, day) {
    const card = Ui.card(this);
    const bg = Ui.round(this, 0xFFFFF7ED, 18);
    bg.setStroke(Ui.dp(this, 1), 0xFFFED7AA);
    card.setBackground(bg);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.tv(this, "📋 Today's presentations", 16, 0xFF7C2D12, true), Ui.weight(1));
    top.addView(Ui.softPill(this, todays.size() + " given", ExamCases.COLOR));
    card.addView(top);
    if (todays.isEmpty()) {
      card.addView(Ui.muted(this, ExamCases.canMark(this) ? "Tap Give to a student on any case below." : "No cases given for today yet."));
    }
    for (const a of todays) {
      const done = "1".equals(a.get("presented"));
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 2));
      const lv = Ui.tv(this, Ui.nz(a.get("level")), 11, Color.WHITE, true);
      lv.setGravity(Gravity.CENTER);
      lv.setBackground(Ui.round(this, "PG".equals(a.get("level")) ? 0xFF7C3AED : 0xFF0284C7, 10));
      lv.setPadding(Ui.dp(this, 6), Ui.dp(this, 2), Ui.dp(this, 6), Ui.dp(this, 2));
      row.addView(lv);
      const mid = Ui.v(this);
      mid.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 6), 0);
      mid.addView(Ui.tv(this, Ui.nz(a.get("student")) + "  ·  " + Ui.nz(a.get("kind")), 14, Ui.TEXT, true));
      mid.addView(Ui.muted(this, ExamCases.patientLine(a) + "  ·  " + ExamCases.ward(a)
          + (Ui.nz(a.get("faculty")).isEmpty() ? "" : "\nPresent to " + a.get("faculty"))));
      row.addView(mid, Ui.weight(1));
      const st = Ui.nz(a.get("status"));
      if (!st.isEmpty()) {
        // given to another unit's student: waiting for that unit, or not allowed
        const no = ExamCases.NO.equals(st);
        const sp = Ui.tv(this, no ? "✗ Not allowed" : "⏳ Waiting", 12, no ? Ui.RED : 0xFFB45309, true);
        sp.setBackground(Ui.round(this, no ? Ui.alpha(Ui.RED, 0x22) : 0x22F59E0B, 12));
        sp.setPadding(Ui.dp(this, 9), Ui.dp(this, 4), Ui.dp(this, 9), Ui.dp(this, 4));
        mid.addView(Ui.tv(this, no ? "Not allowed by " + Ui.nz(a.get("permit_by")) + " (" + ExamCases.ownerLabel(a) + ")"
            : "Waiting for permission from " + ExamCases.ownerLabel(a) + " PGs or Assistant Professor", 12, no ? Ui.RED : 0xFFB45309, true));
        if (ExamCases.canMark(this)) row.setOnLongClickListener(this.takeBack(a));
        row.addView(sp);
        card.addView(row);
        continue;
      }
      if (!Ui.nz(a.get("permit_by")).isEmpty() && !ExamCases.owners(a).contains(Ui.nz(a.get("student_unit"))))
        mid.addView(Ui.tv(this, "✓ Allowed by " + a.get("permit_by"), 12, Ui.GREEN, false));
      const tick = Ui.tv(this, done ? "✓ Presented" : "○ Pending", 12, done ? Ui.GREEN : 0xFFB45309, true);
      tick.setBackground(Ui.round(this, done ? Ui.alpha(Ui.GREEN, 0x22) : 0x22F59E0B, 12));
      tick.setPadding(Ui.dp(this, 9), Ui.dp(this, 4), Ui.dp(this, 9), Ui.dp(this, 4));
      if (ExamCases.canMark(this)) {
        const now = done;
        tick.setOnClickListener({
          onClick: (v) => {
            ExamCases.setPresented(this.db, a.get("id"), !now);
            this.render();
          }
        });
        row.setOnLongClickListener(this.takeBack(a));
      }
      row.addView(tick);
      card.addView(row);
    }
    if (!todays.isEmpty()) {
      const wa = Ui.button(this, "Share today's list on WhatsApp", Chat.GREEN, {
        onClick: (v) => { this.whatsappText(ExamCases.whatsapp(this.db, day)); }
      });
      card.addView(wa);
      Ui.margins(wa, 0, 10, 0, 0);
    }
    return this.wrap(card);
  }

  takeBack(a) {
    return {
      onLongClick: (v) => {
        new AlertDialog.Builder(this).setTitle("Take this case back from " + a.get("student") + "?")
          .setPositiveButton("Take back", {
            onClick: (d, w) => {
              ExamCases.ungive(this.db, a.get("id"));
              this.render();
            }
          }).setNegativeButton("Cancel", null).show();
        return true;
      }
    };
  }

  /** Cases from this person's unit or ward given to another unit's students, waiting for permission. */
  permitCard(waiting) {
    const card = Ui.card(this);
    const bg = Ui.round(this, 0xFFFFFBEB, 18);
    bg.setStroke(Ui.dp(this, 2), 0xFFF59E0B);
    card.setBackground(bg);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.tv(this, "🔐 Waiting for your permission", 16, 0xFF92400E, true), Ui.weight(1));
    top.addView(Ui.softPill(this, String(waiting.size()), 0xFFB45309));
    card.addView(top);
    card.addView(Ui.muted(this, "Your unit's cases given to students of another unit."));
    for (const a of waiting) {
      const box = Ui.v(this);
      box.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 2));
      const su = Ui.nz(a.get("student_unit"));
      box.addView(Ui.tv(this, Ui.nz(a.get("student")) + " (" + Ui.nz(a.get("level")) + (su.isEmpty() ? ", unit not known" : ", " + Db.shortName(su)) + ")", 14, Ui.TEXT, true));
      box.addView(Ui.muted(this, Ui.nz(a.get("kind")) + " · " + Ui.nz(a.get("system")) + "  ·  " + ExamCases.patientLine(a) + "  ·  " + ExamCases.ward(a)
          + "\n" + Dates.nice(a.get("date")) + "  ·  asked by " + Ui.nz(a.get("by_name"))));
      const br = Ui.buttonRow(this,
        Ui.button(this, "Allow", Ui.GREEN, {
          onClick: (v) => {
            ExamCases.permit(this, this.db, a.get("id"), true);
            this.render();
          }
        }),
        Ui.outlineButton(this, "Not allow", Ui.RED, {
          onClick: (v) => {
            ExamCases.permit(this, this.db, a.get("id"), false);
            this.render();
          }
        }));
      box.addView(br);
      Ui.margins(br, 0, 6, 0, 0);
      card.addView(box);
    }
    return this.wrap(card);
  }

  caseCard(r) {
    const sc = ExamCases.systemColor(r.get("system"));
    const wc = Ui.unitColor(r.get("location"));
    const card = Ui.card(this);
    const bg = Ui.round(this, Color.WHITE, 18);
    bg.setStroke(Ui.dp(this, 1), Ui.alpha(sc, 0x55));
    card.setBackground(bg);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const badge = Ui.tv(this, Db.shortName(r.get("location")), 13, Color.WHITE, true);
    badge.setGravity(Gravity.CENTER);
    badge.setBackground(Ui.gradient(this, [Ui.mix(wc, Color.WHITE, 0.15), Ui.mix(wc, Color.BLACK, 0.25)], 22));
    top.addView(badge, Ui.lp(Ui.dp(this, 44), Ui.dp(this, 44)));
    const mid = Ui.v(this);
    mid.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 6), 0);
    mid.addView(Ui.tv(this, ExamCases.patientLine(r), 16, Ui.TEXT, true));
    mid.addView(Ui.tv(this, "📍 " + ExamCases.ward(r), 13, Ui.mix(wc, Color.BLACK, 0.2), true));
    top.addView(mid, Ui.weight(1));
    card.addView(top);
    const chips = Ui.h(this);
    const k = Ui.softPill(this, "🎓 " + Ui.nz(r.get("kind")), ExamCases.COLOR);
    chips.addView(k);
    const s = Ui.softPill(this, Ui.nz(r.get("system")), sc);
    chips.addView(s);
    Ui.margins(s, 6, 0, 0, 0);
    const given = Integer.parseInt(Ui.nz(r.get("given")).isEmpty() ? "0" : r.get("given"));
    if (given > 0) {
      const g = Ui.softPill(this, "Given " + given + "×", Ui.SLATE);
      chips.addView(g);
      Ui.margins(g, 6, 0, 0, 0);
    }
    card.addView(chips);
    Ui.margins(chips, 0, 10, 0, 4);
    if (!Ui.nz(r.get("diagnosis")).isEmpty()) card.addView(Ui.tv(this, "Diagnosis: " + r.get("diagnosis"), 13, Ui.TEXT, false));
    if (!Ui.nz(r.get("points")).isEmpty()) {
      const pt = Ui.tv(this, "✨ " + r.get("points"), 14, 0xFF7C2D12, false);
      pt.setBackground(Ui.round(this, 0xFFFFF7ED, 10));
      pt.setPadding(Ui.dp(this, 10), Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 6));
      card.addView(pt);
      Ui.margins(pt, 0, 6, 0, 0);
    }
    const last = Ui.nz(r.get("last_given"));
    card.addView(Ui.muted(this, "Marked by " + Ui.nz(r.get("marked_by")) + (Ui.nz(r.get("marked_role")).isEmpty() ? "" : " (" + r.get("marked_role") + ")")
        + "  ·  " + Chat.when(r.get("time")) + (last.isEmpty() ? "" : "  ·  last given " + Dates.nice(last))));
    const btns = [];
    if (ExamCases.canMark(this)) btns.add(Ui.button(this, "Give to a student", ExamCases.COLOR, {
      onClick: (v) => { this.giveDialog(r); }
    }));
    btns.add(Ui.outlineButton(this, "Open patient", ExamCases.COLOR, this.opener(PatientActivity, "id", r.get("patient_id"))));
    const br = Ui.buttonRow(this, btns);
    card.addView(br);
    Ui.margins(br, 0, 10, 0, 0);
    return card;
  }

  /** Names of the MBBS students and PGs, for the student box. */
  students() {
    const out = [];
    for (const s of this.db.rows("SELECT name FROM staff WHERE (role='Postgraduate' OR role LIKE 'MBBS%') AND " + Approvals.APPROVED_SQL + " ORDER BY name"))
      out.add(s.get("name"));
    return out;
  }

  giveDialog(r) {
    const f = new Form(this);
    f.heading(ExamCases.patientLine(r) + "  ·  " + Db.shortName(r.get("location")));
    f.suggest("student", "Student *", "", this.students());
    f.segment("level", "Student is", ExamCases.LEVELS, "MBBS");
    const unitNames = new Array(Db.CENSUS_WARDS.length).fill(null);
    for (let i = 0; i < unitNames.length; i++) unitNames[i] = Db.shortName(Db.CENSUS_WARDS[i]);
    f.choice("unit", "Student's unit (taken from the Students list when there)", unitNames, Db.CENSUS_WARDS, "", null);
    f.heading("Same unit: given at once. Another unit's student: waits for " + ExamCases.ownerLabel(r) + " PGs or Assistant Professor to allow.");
    f.date("date", "Presentation day", Dates.todayIso());
    f.text("faculty", "Present to (faculty, optional)", "", Form.TEXT);
    Ui.formDialog(this, "Give for presentation", f, "Give case", {
      run: () => {
        const st = f.get("student").trim();
        if (st.isEmpty()) {
          Ui.toast(this, "Enter the student's name");
          return false;
        }
        const s = this.db.row("SELECT role, unit FROM staff WHERE name=?", st);
        let level = f.get("level"), unit = f.get("unit");
        if (s != null) level = "Postgraduate".equals(s.get("role")) ? "PG" : "MBBS";
        if (s != null && !Ui.nz(s.get("unit")).isEmpty()) unit = s.get("unit");
        if (unit.isEmpty()) {
          Ui.toast(this, "Choose the student's unit");
          return false;
        }
        const id = ExamCases.give(this, this.db, r, f.get("date"), st, level, f.get("faculty").trim(), unit);
        const g = this.db.row("SELECT status FROM " + ExamCases.ALLOTS + " WHERE id=?", String(id));
        if (g != null && ExamCases.WAIT.equals(g.get("status")))
          Ui.toast(this, "Sent to " + ExamCases.ownerLabel(r) + " for permission");
        this.render();
        return true;
      }
    });
  }

  whatsappText(text) {
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, text);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    this.startActivity(Intent.createChooser(i, "Share the list"));
  }

  /** The mark / edit dialog, used from the patient page. */
  static markDialog(a, db, patientId, done) {
    const old = ExamCases.forPatient(db, patientId);
    const f = new Form(a);
    f.segment("kind", "Case type", ExamCases.KINDS, old == null ? "Long case" : old.get("kind"));
    f.choice("system", "System", ExamCases.SYSTEMS, ExamCases.SYSTEMS, old == null ? "" : old.get("system"), null);
    f.multi("points", "Signs and teaching points (optional)", old == null ? "" : Ui.nz(old.get("points")));
    Ui.formDialog(a, old == null ? "🎓 Mark as exam case" : "🎓 Edit exam case", f, old == null ? "Mark" : "Save", {
      run: () => {
        if (f.get("system").isEmpty()) {
          Ui.toast(a, "Choose the system");
          return false;
        }
        ExamCases.mark(a, db, patientId, f.get("kind"), f.get("system"), f.get("points").trim());
        done.run();
        return true;
      }
    });
  }
}
;
