'use strict';
/** One faculty member: photo, service details and the document folder. */
class FacultyProfileActivity extends Base {
  constructor() {
    super();
    this.id = 0;
    this.s = null;
    // What the pending picker or camera result is for; kept across process death.
    this.pendingType = null;
    this.pendingCapture = null;
    this.pendingReplace = -1;
  }

  static REQ_PICK_DOC = 41;
  static REQ_CAPTURE_DOC = 42;
  static REQ_PICK_PHOTO = 43;
  static REQ_CAPTURE_PHOTO = 44;

  // interface Saved { void saved(long id); }  → an object { saved: (id) => … }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    if (b != null) {
      this.pendingType = b.getString("pendingType");
      this.pendingCapture = b.getString("pendingCapture");
      this.pendingReplace = b.getLong("pendingReplace", -1);
    }
  }

  onSaveInstanceState(b) {
    super.onSaveInstanceState(b);
    b.putString("pendingType", this.pendingType);
    b.putString("pendingCapture", this.pendingCapture);
    b.putLong("pendingReplace", this.pendingReplace);
  }

  render() {
    this.s = this.db.row("SELECT * FROM staff WHERE id=?", String(this.id));
    const s = this.s;
    if (s == null || !Cloud.canSeeFaculty(this)) { this.finish(); return; }
    const color = Store.roleColor(s.get("role"));
    this.headerColor(color);
    this.setTitle(s.get("name"));
    this.subtitle = s.get("role");
    if (Store.locked(this.db)) {
      this.headerAction(null, null);
      this.setPage(FacultyActivity.lockPage(this));
      return;
    }
    this.headerAction("Edit", {
      onClick: (v) => { this.edit(); }
    });
    const page = Ui.v(this);

    // Hero with photo
    const hero = Ui.card(this);
    hero.setGravity(Gravity.CENTER_HORIZONTAL);
    hero.setBackground(Glass.hero(this, [color, Ui.mix(color, 0xFF0EA5E9, 0.45)], 20));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 22), Ui.dp(this, 18), Ui.dp(this, 18));
    const ph = new FrameLayout(this);
    const av = Store.avatar(this, s, 104, Ui.mix(color, 0xFFFFFFFF, 0.25));
    av.setLayoutParams(new FrameLayout.LayoutParams(Ui.dp(this, 104), Ui.dp(this, 104)));
    ph.addView(av);
    const cam = new ImageView(this);
    cam.setImageResource(R.drawable.ic_camera);
    cam.setColorFilter(color);
    cam.setBackground(Ui.round(this, Color.WHITE, 17));
    const p = Ui.dp(this, 7);
    cam.setPadding(p, p, p, p);
    const cp = new FrameLayout.LayoutParams(Ui.dp(this, 34), Ui.dp(this, 34), Gravity.END | Gravity.BOTTOM);
    ph.addView(cam, cp);
    ph.setOnClickListener({
      onClick: (v) => { this.photoOptions(); }
    });
    hero.addView(ph, Ui.lp(Ui.dp(this, 108), Ui.dp(this, 108)));
    const name = Ui.tv(this, s.get("name"), 21, Color.WHITE, true);
    name.setGravity(Gravity.CENTER);
    hero.addView(name);
    Ui.margins(name, 0, 10, 0, 0);
    const line = s.get("role") + "  ·  " + Db.unitName(s.get("unit"));
    const rl = Ui.tv(this, line, 14, 0xE6FFFFFF, false);
    rl.setGravity(Gravity.CENTER);
    hero.addView(rl);
    if (!s.get("qualification").isEmpty()) {
      const q = Ui.tv(this, s.get("qualification"), 13, 0xCCFFFFFF, false);
      q.setGravity(Gravity.CENTER);
      hero.addView(q);
    }
    const acts = [];
    if (!s.get("phone").isEmpty()) acts.add(this.heroButton("Call", {
      onClick: (v) => { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + s.get("phone")))); }
    }));
    if (WhatsApp.usable(s.get("phone"))) acts.add(this.heroButton("WhatsApp", {
      onClick: (v) => { WhatsApp.chat(this, s.get("phone"), null); }
    }));
    if (!s.get("email").isEmpty()) acts.add(this.heroButton("Email", {
      onClick: (v) => {
        try { this.startActivity(new Intent(Intent.ACTION_SENDTO, Uri.parse("mailto:" + s.get("email")))); }
        catch (e) { Ui.toast(this, "No email app found"); }
      }
    }));
    acts.add(this.heroButton(s.get("photo").isEmpty() ? "Add photo" : "Photo", {
      onClick: (v) => { this.photoOptions(); }
    }));
    const ar = Ui.h(this);
    ar.setGravity(Gravity.CENTER_HORIZONTAL);
    for (const a of acts) ar.addView(a);
    hero.addView(ar);
    Ui.margins(ar, 0, 14, 0, 0);
    page.addView(hero);

    // Details
    page.addView(Ui.heading(this, "Service details", color));
    const d = Ui.card(this);
    d.addView(Ui.kv(this, "Employee / GPF / CPS no.", s.get("emp_id")));
    d.addView(Ui.kv(this, "Qualification", s.get("qualification")));
    d.addView(Ui.kv(this, "Medical council reg. no.", s.get("reg_no")));
    d.addView(Ui.kv(this, "Date of birth", s.get("dob").isEmpty() ? "" : Dates.nice(s.get("dob"))));
    d.addView(Ui.kv(this, "Joined department", s.get("doj").isEmpty() ? "" : Dates.nice(s.get("doj"))));
    d.addView(Ui.kv(this, "Phone", s.get("phone")));
    d.addView(Ui.kv(this, "Email", s.get("email")));
    d.addView(Ui.kv(this, "Address", s.get("address")));
    const ed = Ui.outlineButton(this, "Edit details", color, {
      onClick: (v) => { this.edit(); }
    });
    d.addView(ed);
    Ui.margins(ed, 0, 10, 0, 0);
    page.addView(d);

    // Documents
    if (!Cloud.canSeeDocs(this, this.id)) {
      page.addView(Ui.heading(this, "Documents", color));
      const pv = Ui.card(this);
      pv.addView(Ui.iconBadge(this, R.drawable.ic_lock, Ui.SLATE, 44));
      pv.addView(Ui.body(this, "Documents are private. Only the admin and " + s.get("name") + " can see or upload them."));
      page.addView(pv);
      this.setPage(page);
      return;
    }
    const docs = this.db.docs(this.id);
    let have = 0;
    for (let i = 0; i < FacultyActivity.REQUIRED_DOCS; i++) if (FacultyProfileActivity.count(docs, Db.DOC_TYPES[i]) > 0) have++;
    page.addView(Ui.heading(this, "Documents  ·  " + have + " of " + FacultyActivity.REQUIRED_DOCS, color));
    const hint = Ui.muted(this, (Cloud.active(this) ? "Upload a PDF or photo of each certificate and order, or scan it with the camera. Only the HOD and Professors can see these files." : "Upload a PDF or photo of each certificate and order, or scan it with the camera. Files stay on this phone and go into backups."));
    hint.setPadding(Ui.dp(this, 18), 0, Ui.dp(this, 18), Ui.dp(this, 4));
    page.addView(hint);
    const card = Ui.card(this);
    card.setPadding(Ui.dp(this, 14), Ui.dp(this, 6), Ui.dp(this, 14), Ui.dp(this, 6));
    for (let i = 0; i < Db.DOC_TYPES.length; i++) {
      const type = Db.DOC_TYPES[i];
      const mine = [];
      for (const x of docs) if (type.equals(x.get("type"))) mine.add(x);
      if (i > 0) card.addView(Ui.divider(this));
      if (mine.isEmpty()) {
        card.addView(this.docRow(type, null, false, color));
      } else if (!Db.multiDoc(type)) {
        card.addView(this.docRow(type, mine.get(0), false, color));
      } else {
        for (let k = 0; k < mine.size(); k++) card.addView(this.docRow(type, mine.get(k), k > 0, color));
        const more = Ui.tv(this, "+ Add another " + type.toLowerCase(), 13, color, true);
        more.setPadding(Ui.dp(this, 52), Ui.dp(this, 2), 0, Ui.dp(this, 10));
        more.setOnClickListener({
          onClick: (v) => { this.uploadOptions(type, -1); }
        });
        card.addView(more);
      }
    }
    page.addView(card);
    this.setPage(page);
  }

  static count(docs, type) {
    let n = 0;
    for (const d of docs) if (type.equals(d.get("type"))) n++;
    return n;
  }

  heroButton(label, l) {
    const t = Ui.tv(this, label, 13, Color.WHITE, true);
    t.setBackground(Ui.round(this, 0x33FFFFFF, 16));
    t.setPadding(Ui.dp(this, 16), Ui.dp(this, 7), Ui.dp(this, 16), Ui.dp(this, 7));
    Ui.ripple(t, 0x44FFFFFF);
    t.setOnClickListener(l);
    const lp = Ui.lp(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 4), 0, Ui.dp(this, 4), 0);
    t.setLayoutParams(lp);
    return t;
  }

  docRow(type, doc, repeat, color) {
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 10));
    const ok = doc != null && Store.exists(this, doc.get("file"));
    const badge = Ui.iconBadge(this, ok ? R.drawable.ic_verified : R.drawable.ic_doc, ok ? Ui.GREEN : 0xFF94A3B8, 40);
    if (repeat) badge.setVisibility(View.INVISIBLE);
    row.addView(badge);
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    let title = type;
    if (doc != null && Db.multiDoc(type) && !doc.get("title").isEmpty() && !doc.get("title").equals(type)) title = doc.get("title");
    const tt = Ui.tv(this, title, 15, Ui.TEXT, true);
    tt.setMaxLines(2);
    t.addView(tt);
    let sub;
    if (doc == null) sub = "Not uploaded";
    else if (!ok) sub = "File missing, upload again";
    else sub = Store.kindLabel(doc.get("file")) + "  ·  " + Store.sizeLabel(Store.size(this, doc.get("file"))) + "  ·  " + Dates.nice(doc.get("added"));
    if (doc != null && Db.multiDoc(type) && !title.equals(type)) sub = type + "  ·  " + sub;
    t.addView(Ui.tv(this, sub, 12, doc == null ? 0xFF94A3B8 : ok ? Ui.MUTED : Ui.RED, false));
    row.addView(t, Ui.weight(1));
    const act = doc == null || !ok ? Ui.softPill(this, "Upload", color) : Ui.softPill(this, "View", Ui.GREEN);
    row.addView(act);
    Ui.ripple(row, Ui.alpha(color, 0x1A));
    const l = {
      onClick: (v) => {
        if (doc == null) this.uploadOptions(type, -1);
        else if (!Store.exists(this, doc.get("file"))) this.uploadOptions(type, Long.parseLong(doc.get("id")));
        else this.open(ViewerActivity, "file", doc.get("file"), "title", this.s.get("name") + " · " + type);
      }
    };
    row.setOnClickListener(l);
    act.setOnClickListener(l);
    if (doc != null) {
      row.setOnLongClickListener({
        onLongClick: (v) => { this.docOptions(type, doc); return true; }
      });
      const more = Ui.tv(this, "⋮", 22, Ui.MUTED, true);
      more.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 2), 0);
      more.setOnClickListener({
        onClick: (v) => { this.docOptions(type, doc); }
      });
      row.addView(more);
    }
    return row;
  }

  docOptions(type, doc) {
    const docId = Long.parseLong(doc.get("id"));
    const ok = Store.exists(this, doc.get("file"));
    const items = [];
    if (ok) { items.add("View"); items.add("Share"); items.add("Open with another app"); }
    items.add("Replace");
    if (Db.multiDoc(type)) items.add("Rename");
    items.add("Remove");
    new AlertDialog.Builder(this).setTitle(type).setItems(items.slice(), {
      onClick: (di, w) => {
        const it = items.get(w);
        const f = doc.get("file");
        if (it.equals("View")) this.open(ViewerActivity, "file", f, "title", this.s.get("name") + " · " + type);
        else if (it.equals("Share")) Store.share(this, f, this.s.get("name") + " - " + type);
        else if (it.equals("Open with another app")) Store.openWith(this, f);
        else if (it.equals("Replace")) this.uploadOptions(type, docId);
        else if (it.equals("Rename")) this.rename(doc);
        else if (it.equals("Remove")) {
          Ui.confirm(this, "Remove " + type.toLowerCase() + "?", "The file will be deleted from this phone.", "Remove", {
            run: () => { this.db.deleteDoc(docId); this.render(); }
          });
        }
      }
    }).show();
  }

  rename(doc) {
    const f = new Form(this);
    f.text("title", "Title", doc.get("title"), Form.PLAIN);
    Ui.formDialog(this, "Rename", f, "Save", {
      run: () => {
        const cv = new ContentValues();
        cv.put("title", f.get("title").isEmpty() ? doc.get("type") : f.get("title"));
        this.db.update("docs", cv, Long.parseLong(doc.get("id")));
        this.render();
        return true;
      }
    });
  }

  uploadOptions(type, replaceId) {
    new AlertDialog.Builder(this).setTitle((replaceId >= 0 ? "Replace " : "Upload ") + type.toLowerCase())
      .setItems(["Choose a PDF or image", "Scan with camera"], {
        onClick: (di, w) => {
          this.pendingType = type;
          this.pendingReplace = replaceId;
          if (w === 0) {
            Store.pick(this, ["application/pdf", "image/*"], FacultyProfileActivity.REQ_PICK_DOC);
          } else {
            this.pendingCapture = this.dir() + "/" + Store.safeName(type) + "_" + System.currentTimeMillis() + ".jpg";
            Store.capture(this, this.pendingCapture, FacultyProfileActivity.REQ_CAPTURE_DOC);
          }
        }
      }).show();
  }

  photoOptions() {
    const items = [];
    items.add("Choose from gallery");
    items.add("Take a photo");
    if (!this.s.get("photo").isEmpty()) { items.add("View photo"); items.add("Remove photo"); }
    new AlertDialog.Builder(this).setTitle("Profile photo").setItems(items.slice(), {
      onClick: (di, w) => {
        const it = items.get(w);
        if (it.startsWith("Choose")) Store.pick(this, ["image/*"], FacultyProfileActivity.REQ_PICK_PHOTO);
        else if (it.startsWith("Take")) {
          this.pendingCapture = this.dir() + "/capture_" + System.currentTimeMillis() + ".jpg";
          Store.capture(this, this.pendingCapture, FacultyProfileActivity.REQ_CAPTURE_PHOTO);
        } else if (it.startsWith("View")) Ui.showImage(this, this.db.file(this.s.get("photo")));
        else this.setPhoto(null);
      }
    }).show();
  }

  dir() {
    return "faculty/" + this.id;
  }

  setPhoto(rel) {
    const cur = this.db.row("SELECT photo FROM staff WHERE id=?", String(this.id));
    if (cur != null) this.db.forgetFile(cur.get("photo"));
    const cv = new ContentValues();
    cv.put("photo", rel == null ? "" : rel);
    this.db.update("staff", cv, this.id);
  }

  /** Records an uploaded file, replacing the earlier one if asked. */
  saveDoc(type, rel, title, replaceId) {
    const cv = new ContentValues();
    cv.put("staff_id", this.id);
    cv.put("type", type);
    cv.put("title", title);
    cv.put("file", rel);
    cv.put("mime", DocProvider.mimeOf(rel));
    cv.put("added", Dates.todayIso());
    const old = replaceId >= 0 ? this.db.row("SELECT * FROM docs WHERE id=?", String(replaceId)) : null;
    if (old != null) {
      if (!old.get("file").equals(rel)) this.db.forgetFile(old.get("file"));
      if (Db.multiDoc(type) && !old.get("title").isEmpty()) cv.put("title", old.get("title"));
      this.db.update("docs", cv, replaceId);
    } else {
      this.db.insert("docs", cv);
    }
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    const P = FacultyProfileActivity;
    try {
      if (req === P.REQ_CAPTURE_DOC || req === P.REQ_CAPTURE_PHOTO) {
        const f = this.pendingCapture == null ? null : this.db.file(this.pendingCapture);
        if (res !== RESULT_OK || f == null || !f.exists() || f.length() === 0) {
          if (f != null) f.delete();
          return;
        }
        if (req === P.REQ_CAPTURE_PHOTO) {
          const rel = Store.savePhoto(this, null, f, this.id);
          f.delete();
          this.setPhoto(rel);
        } else {
          if (!Store.shrink(f, 2400)) throw new Error("The camera did not return a picture");
          this.saveDoc(this.pendingType, this.pendingCapture, this.pendingType, this.pendingReplace);
          Ui.toast(this, this.pendingType + " saved");
        }
        this.pendingCapture = null;
        return;
      }
      if (res !== RESULT_OK || data == null || data.getData() == null) return;
      const uri = data.getData();
      if (req === P.REQ_PICK_PHOTO) {
        this.setPhoto(Store.savePhoto(this, uri, null, this.id));
      } else if (req === P.REQ_PICK_DOC && this.pendingType != null) {
        const name = Store.displayName(this, uri);
        const rel = Store.importUri(this, uri, this.dir(), this.pendingType);
        let title = this.pendingType;
        if (Db.multiDoc(this.pendingType) && !name.isEmpty()) title = name.replaceAllRx("\\.[A-Za-z0-9]{1,5}$", "");
        this.saveDoc(this.pendingType, rel, title, this.pendingReplace);
        Ui.toast(this, this.pendingType + " saved");
      }
    } catch (e) {
      Ui.toast(this, "Could not save: " + e.getMessage());
    }
  }

  edit() {
    FacultyProfileActivity.editDialog(this, this.s, this.s.get("role"), {
      saved: (x) => { this.render(); }
    });
  }

  /** Add (s == null) or edit a faculty member, with every service detail. */
  static editDialog(a, s, role, done) {
    const db = Db.get(a);
    const f = new Form(a);
    f.text("name", "Name *", s == null ? "Dr. " : s.get("name"), Form.TEXT);
    f.choice("role", "Designation", Db.FACULTY_ROLES, Db.FACULTY_ROLES, s == null ? role : s.get("role"), null);
    f.choice("unit", "Unit", StaffActivity.UNIT_LABELS, StaffActivity.UNIT_VALUES, s == null ? "M1" : s.get("unit"), null);
    f.text("qualification", "Qualification", s == null ? "MBBS, MD (General Medicine)" : s.get("qualification"), Form.PLAIN);
    f.text("emp_id", "Employee / GPF / CPS no.", s == null ? "" : s.get("emp_id"), Form.PLAIN);
    f.text("reg_no", "Medical council registration no.", s == null ? "" : s.get("reg_no"), Form.PLAIN);
    f.text("phone", "Phone", s == null ? "" : s.get("phone"), Form.PHONE);
    f.text("email", "Email", s == null ? "" : s.get("email"),
      InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
    f.optionalDate("dob", "Date of birth", s == null ? "" : s.get("dob"));
    f.optionalDate("doj", "Date of joining the department", s == null ? "" : s.get("doj"));
    f.multi("address", "Address", s == null ? "" : s.get("address"));
    const waiting = s != null && !Ui.nz(s.get("approval")).isEmpty();
    if (waiting) StaffActivity.approvalBlock(a, f, s);
    else if (s == null && !Approvals.canApprove(a, role))
      f.view.addView(Ui.muted(a, "New faculty entries wait for approval by the HOD."), 0);
    if (s != null) {
      const del = Ui.outlineButton(a, "Remove from faculty", Ui.RED, null);
      f.view.addView(del);
      Ui.margins(del, 0, 16, 0, 0);
      del.setOnClickListener({
        onClick: (v) => {
          Ui.confirm(a, "Remove " + s.get("name") + "?", "Their photo, all uploaded documents, attendance and leave records will be deleted from this phone.", "Remove", {
            run: () => {
              db.deleteStaff(Long.parseLong(s.get("id")));
              a.finish();
            }
          });
        }
      });
    }
    Ui.formDialog(a, s == null ? "Add faculty member" : "Edit details", f, "Save", {
      run: () => {
        const name = f.get("name");
        if (name.isEmpty() || name.equals("Dr.")) {
          Ui.toast(a, "Enter a name");
          return false;
        }
        const cv = new ContentValues();
        cv.put("name", name);
        for (const k of ["role", "unit", "qualification", "emp_id", "reg_no", "phone", "email", "dob", "doj", "address"])
          cv.put(k, f.get(k));
        let sid;
        if (s == null) {
          sid = db.insert("staff", cv);
          if (Approvals.PENDING.equals(cv.getAsString("approval"))) Ui.toast(a, "Saved. Waiting for approval by the HOD");
        } else {
          sid = Long.parseLong(s.get("id"));
          Approvals.stamp(a, cv, s);
          db.update("staff", cv, sid);
          if (waiting && "1" === f.get("approve_now") && Approvals.canApprove(a, f.get("role"))) Approvals.approve(db, a, sid);
        }
        done.saved(sid);
        return true;
      }
    });
  }
}
;
