'use strict';
/**
 * The 7:30 AM handover. During the duty (7:30 AM to 7:30 AM) the DAP and the call-duty PGs list sick patients,
 * pending tests and plans; after 7:30 AM the next team sees that list first, and marks each patient as seen.
 */
class HandoverActivity extends Base {
  static COLOR = 0xFF0F766E;
  static SICK = "Sick patient";
  static TEST = "Pending test";
  static PLAN = "Plan";
  static KINDS = ["Sick patient", "Pending test", "Plan"];

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Handover");
    this.subtitle = "At 7:30 AM: sick patients, pending tests and plans for the next team";
    this.headerColor(HandoverActivity.COLOR);
    this.headerAction("+ Add", {
      onClick: (v) => { this.addDialog(null, this.getIntent().getStringExtra("patient")); }
    });
    if (this.getIntent().getStringExtra("patient") != null && b == null) this.addDialog(null, this.getIntent().getStringExtra("patient"));
  }

  static kindColor(k) {
    return HandoverActivity.SICK.equals(k) ? Ui.RED : HandoverActivity.TEST.equals(k) ? Ui.AMBER : Ui.SKY;
  }

  static of(db, day) {
    return db.rows("SELECT * FROM handovers WHERE day=? ORDER BY CASE kind WHEN '" + HandoverActivity.SICK + "' THEN 0 WHEN '" + HandoverActivity.TEST + "' THEN 1 ELSE 2 END, ward, bed, id", day.toString());
  }

  /** Home card after 7:30 AM: last night's handover, until every patient on it has been seen. */
  static homeCard(a, db) {
    const COLOR = HandoverActivity.COLOR;
    const prev = Dates.admitDay().minusDays(1);
    const n = db.num("SELECT COUNT(*) FROM handovers WHERE day=?", prev.toString());
    if (n == 0) return null;
    const unseen = db.num("SELECT COUNT(*) FROM handovers WHERE day=? AND seen_by=''", prev.toString());
    if (unseen == 0) return null;
    const sick = db.num("SELECT COUNT(*) FROM handovers WHERE day=? AND kind=?", prev.toString(), HandoverActivity.SICK);
    const card = a.entryCard("HANDOVER · 7:30 AM", COLOR, "🔁 From last night's team · " + n + (n == 1 ? " patient" : " patients"),
      (sick > 0 ? sick + " sick  ·  " : "") + unseen + " not seen yet. Tap to see them first.", null, a.opener(HandoverActivity));
    const g = Ui.round(a, Ui.mix(COLOR, Color.WHITE, 0.92), 18);
    g.setStroke(Ui.dp(a, 2), COLOR);
    card.setBackground(g);
    return card;
  }

  render() {
    const COLOR = HandoverActivity.COLOR;
    const page = Ui.v(this);
    const day = Dates.admitDay(), prev = day.minusDays(1);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(COLOR), 20));
    hero.addView(Ui.tv(this, "Handover at 7:30 AM", 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, "The outgoing DAP and call-duty PGs list the patients the next team must see first.", 13, 0xD9FFFFFF, false));
    const last = HandoverActivity.of(this.db, prev), now = HandoverActivity.of(this.db, day);
    let unseen = 0;
    for (const r of last) if (Ui.nz(r.get("seen_by")).isEmpty()) unseen++;
    const stats = Ui.statRow(this, this.whiteStat(String(last.size()), "From last night"), this.whiteStat(String(unseen), "Not seen yet"),
      this.whiteStat(String(now.size()), "Tonight's list"));
    hero.addView(stats);
    Ui.margins(stats, 0, 10, 0, 0);
    page.addView(hero);

    page.addView(Ui.heading(this, "From last night's team  ·  " + Dates.shortFmt(prev) + " 7:30 AM to " + Dates.shortFmt(day) + " 7:30 AM", COLOR));
    if (last.isEmpty()) page.addView(this.emptyNote("Nothing was handed over this morning."));
    for (const r of last) page.addView(this.row(r, true));

    page.addView(Ui.heading(this, "Your team's handover  ·  for " + Dates.shortFmt(day.plusDays(1)) + " 7:30 AM", Ui.PRIMARY));
    const act = Ui.v(this);
    act.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 12), 0);
    const add = Ui.button(this, "+ Add a patient", Ui.PRIMARY, {
      onClick: (v) => { this.addDialog(null, null); }
    });
    const sick = Ui.outlineButton(this, "Add tonight's sick list", Ui.RED, {
      onClick: (v) => {
        const n = HandoverActivity.importSick(this.db, CallDutyActivity.myName(this), day);
        Ui.toast(this, n == 0 ? "No new sick cases on the call duty list" : n + " added from the sick list");
        this.render();
      }
    });
    act.addView(Ui.buttonRow(this, add, sick));
    const smart = Ui.outlineButton(this, "Draft handover from the wards", COLOR, {
      onClick: (v) => { this.draftDialog(day); }
    });
    act.addView(smart);
    Ui.margins(smart, 0, 8, 0, 0);
    if (!now.isEmpty()) {
      const share = Ui.outlineButton(this, "Share handover on WhatsApp", Ui.GREEN, {
        onClick: (v) => { ReportActivity.shareText(this, HandoverActivity.text(this.db, day)); }
      });
      act.addView(share);
      Ui.margins(share, 0, 8, 0, 0);
    }
    page.addView(act);
    if (now.isEmpty()) page.addView(this.emptyNote("Add the sick patients, pending tests and plans before 7:30 AM."));
    for (const r of now) page.addView(this.row(r, false));
    this.setPage(page);
  }

  whiteStat(v, l) {
    const s = Ui.v(this);
    s.setGravity(Gravity.CENTER);
    s.addView(Ui.tv(this, v, 20, Color.WHITE, true));
    s.addView(Ui.tv(this, l, 11, 0xD9FFFFFF, false));
    return s;
  }

  row(r, incoming) {
    const COLOR = HandoverActivity.COLOR;
    const card = Ui.card(this);
    const top = Ui.h(this);
    top.addView(Ui.softPill(this, r.get("kind"), HandoverActivity.kindColor(r.get("kind"))));
    const sp = new View(this);
    top.addView(sp, new LinearLayoutParams(0, 1, 1));
    top.addView(Ui.muted(this, Db.shortName(r.get("ward")) + (Ui.nz(r.get("bed")).isEmpty() ? "" : " · bed " + r.get("bed"))));
    card.addView(top);
    const name = Ui.tv(this, Ui.nz(r.get("patient")), 16, Ui.TEXT, true);
    card.addView(name);
    Ui.margins(name, 0, 6, 0, 0);
    if (!Ui.nz(r.get("note")).isEmpty()) card.addView(Ui.body(this, r.get("note")));
    card.addView(Ui.muted(this, "By " + Ui.nz(r.get("by_name")) + " · " + Ui.nz(r.get("time"))));
    if (incoming) {
      if (Ui.nz(r.get("seen_by")).isEmpty()) {
        const seen = Ui.button(this, "✓ Seen", COLOR, {
          onClick: (v) => {
            const cv = new ContentValues();
            cv.put("seen_by", CallDutyActivity.myName(this).isEmpty() ? "Next team" : CallDutyActivity.myName(this));
            cv.put("seen_time", Dates.todayIso() + " " + Dates.now());
            this.db.update("handovers", cv, Long.parseLong(r.get("id")));
            this.render();
          }
        });
        card.addView(seen);
        Ui.margins(seen, 0, 8, 0, 0);
      } else {
        card.addView(Ui.tv(this, "✓ Seen by " + r.get("seen_by") + " · " + Ui.nz(r.get("seen_time")), 12, Ui.GREEN, true));
      }
    }
    Ui.ripple(card, Ui.alpha(COLOR, 0x22));
    card.setOnClickListener({
      onClick: (v) => {
        if (Ui.toInt(r.get("patient_id"), 0) > 0 && this.db.row("SELECT id FROM patients WHERE id=?", r.get("patient_id")) != null)
          this.open(PatientActivity, "id", r.get("patient_id"));
        else this.addDialog(r, null);
      }
    });
    if (!incoming) card.setOnLongClickListener({
      onLongClick: (v) => { this.addDialog(r, null); return true; }
    });
    return card;
  }

  addDialog(r, patientId) {
    const db = this.db;
    const all = PatientPick.inpatients(db, null);
    const f = new Form(this);
    let pre = r == null ? "" : Ui.nz(r.get("patient"));
    if (patientId != null) {
      const p = db.row("SELECT * FROM patients WHERE id=?", patientId);
      if (p != null) pre = PatientPick.label(p);
    }
    f.suggest("patient", "Patient (type the name or IP number)", pre, all.keySet());
    f.choice("kind", "What the next team must know", HandoverActivity.KINDS, HandoverActivity.KINDS, r == null ? HandoverActivity.SICK : r.get("kind"), null);
    f.multi("note", "Details (e.g. BP 80/50 on noradrenaline; CT brain report pending; plan to extubate)", r == null ? "" : r.get("note"));
    Ui.formDialog(this, r == null ? "Add to the handover" : "Edit handover", f, r == null ? "Add" : "Save", {
      run: () => {
        if (!f.require("patient", "Pick the patient")) return false;
        const p = PatientPick.find(all, f.get("patient"));
        const cv = new ContentValues();
        if (p != null) {
          cv.put("patient_id", p.get("id"));
          cv.put("patient", Ui.nz(p.get("name")) + (Ui.nz(p.get("age")).isEmpty() ? "" : ", " + p.get("age") + " " + Ui.nz(p.get("sex")))
            + (Ui.nz(p.get("ip_no")).isEmpty() ? "" : " · IP " + p.get("ip_no")));
          cv.put("ward", p.get("location"));
          cv.put("bed", Ui.nz(p.get("bed")));
        } else {
          cv.put("patient_id", 0);
          cv.put("patient", f.get("patient").trim());
        }
        cv.put("kind", f.get("kind"));
        cv.put("note", f.get("note").trim());
        if (r == null) {
          cv.put("day", Dates.admitDay().toString());
          cv.put("by_name", CallDutyActivity.myName(this));
          cv.put("time", Dates.now());
          db.insert("handovers", cv);
        } else db.update("handovers", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  /** Preview of the draft built from the wards for the outgoing admitting unit (plus IMCU and CCB): tick the lines to keep, then save. */
  draftDialog(day) {
    const lines = SmartHandover.draft(this.db, this.db.todaysUnit(), LocalDateTime.of(Dates.today(), Dates.time()), day);
    if (lines.isEmpty()) {
      Ui.toast(this, "Nothing new to hand over from the wards");
      return;
    }
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 16), Ui.dp(this, 8), Ui.dp(this, 16), Ui.dp(this, 8));
    box.addView(Ui.muted(this, "Draft for " + this.db.todaysUnit() + ", IMCU and CCB: decision support from NEWS, ventilator, ward, labs and pending tasks. Untick what you do not want. Type the plan lines yourself."));
    let kind = null;
    for (const l of lines) {
      if (l.kind !== kind) {
        kind = l.kind;
        const h = Ui.tv(this, kind, 14, HandoverActivity.kindColor(kind), true);
        box.addView(h);
        Ui.margins(h, 0, 10, 0, 2);
      }
      const cb = new CheckBox(this);
      cb.setText(l.preview());
      cb.setTextSize(14);
      cb.setTextColor(Ui.TEXT);
      cb.setChecked(l.on);
      cb.setOnCheckedChangeListener({
        onCheckedChanged: (b, on) => { l.on = on; }
      });
      box.addView(cb);
    }
    const sv = new ScrollView(this);
    sv.addView(box);
    new AlertDialog.Builder(this).setTitle("Draft handover (" + lines.size() + ")").setView(sv)
      .setPositiveButton("Add ticked", {
        onClick: (d, w) => {
          const n = SmartHandover.save(this.db, lines, CallDutyActivity.myName(this), day);
          Ui.toast(this, n + (n === 1 ? " line added" : " lines added") + " to tonight's handover");
          this.render();
        }
      }).setNegativeButton("Cancel", null).show();
  }

  /** Copies the call duty sick list of this duty into the handover (patients already on it are skipped). */
  static importSick(db, by, day) {
    let n = 0;
    for (const s of db.rows("SELECT * FROM duty_sick WHERE date=?", day.toString())) {
      const pid = Ui.nz(s.get("patient_id"));
      if (Ui.toInt(pid, 0) > 0 && db.num("SELECT COUNT(*) FROM handovers WHERE day=? AND patient_id=?", day.toString(), pid) > 0) continue;
      if (Ui.toInt(pid, 0) <= 0 && db.num("SELECT COUNT(*) FROM handovers WHERE day=? AND patient=?", day.toString(), Ui.nz(s.get("patient"))) > 0) continue;
      const cv = new ContentValues();
      cv.put("day", day.toString());
      cv.put("ward", Ui.nz(s.get("ward")));
      cv.put("patient_id", Ui.toInt(pid, 0));
      cv.put("patient", Ui.nz(s.get("patient")) + (Ui.nz(s.get("ip_no")).isEmpty() ? "" : " · IP " + s.get("ip_no")));
      cv.put("bed", Ui.nz(s.get("bed")));
      cv.put("kind", HandoverActivity.SICK);
      cv.put("note", Ui.nz(s.get("issue")) + (Ui.nz(s.get("status")).isEmpty() ? "" : " (" + s.get("status") + ")"));
      cv.put("by_name", by);
      cv.put("time", Dates.now());
      db.insert("handovers", cv);
      n++;
    }
    return n;
  }

  static text(db, day) {
    let s = "*Handover " + Dates.shortFmt(day) + " → " + Dates.shortFmt(day.plusDays(1)) + " 7:30 AM*\n";
    let kind = null;
    let i = 0;
    for (const r of HandoverActivity.of(db, day)) {
      if (!r.get("kind").equals(kind)) {
        kind = r.get("kind");
        s += "\n*" + kind + "*\n";
        i = 0;
      }
      s += (++i) + ". " + r.get("patient") + " (" + Db.shortName(r.get("ward"))
        + (Ui.nz(r.get("bed")).isEmpty() ? "" : " bed " + r.get("bed")) + ")";
      if (!Ui.nz(r.get("note")).isEmpty()) s += ": " + r.get("note");
      s += '\n';
    }
    return s;
  }
}
;
