/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * ICD-11 (WHO, International Classification of Diseases 11th revision, Mortality and Morbidity Statistics) codes for the
 * final diagnosis (7.86): a scrolling list by chapter with search by words, abbreviations or code. The list is in
 * res/raw/icd11.txt ("code TAB title TAB chapter"; "#n TAB chapter name" lines first), read once, offline.
 * ICD-11 is (c) World Health Organization, used under its ICD-11 licence (CC BY-ND 3.0 IGO).
 */
class Icd11 {
  static COLOR = 0xFF1D4ED8;

  // Java statics "codes" and "chapters" are _codes / _chapters here (chapters(c) is a method)
  static _codes = null;
  static _chapters = null;

  /** Chapters a physician uses most, shown first. */
  static MEDICINE_FIRST = ["Diseases of the circulatory system", "Diseases of the respiratory system", "Endocrine, nutritional or metabolic diseases",
            "Certain infectious or parasitic diseases", "Diseases of the nervous system", "Diseases of the digestive system", "Diseases of the genitourinary system",
            "Diseases of the blood or blood-forming organs", "Injury, poisoning or certain other consequences of external causes"];

  /** Abbreviations used on the wards, searched as their words. */
  static SHORT = [["dm", "diabetes mellitus"], ["t2dm", "type 2 diabetes"], ["t1dm", "type 1 diabetes"], ["htn", "hypertension"],
            ["mi", "myocardial infarction"], ["stemi", "myocardial infarction"], ["nstemi", "myocardial infarction"], ["cad", "coronary"], ["ihd", "ischaemic heart"],
            ["chf", "heart failure"], ["hf", "heart failure"], ["af", "atrial fibrillation"], ["cva", "stroke"], ["ich", "intracerebral haemorrhage"],
            ["sah", "subarachnoid"], ["ckd", "chronic kidney disease"], ["aki", "acute kidney"], ["esrd", "chronic kidney disease"], ["uti", "urinary tract infection"],
            ["copd", "chronic obstructive pulmonary"], ["ba", "asthma"], ["tb", "tuberculosis"], ["ptb", "tuberculosis of the respiratory"], ["cap", "pneumonia"],
            ["ild", "interstitial lung"], ["pe", "pulmonary embolism"], ["dvt", "deep vein thrombosis"], ["dka", "ketoacidosis"], ["hhs", "hyperosmolar"],
            ["cld", "cirrhosis"], ["dcld", "cirrhosis"], ["ugib", "gastrointestinal haemorrhage"], ["gbs", "guillain"], ["aidp", "guillain"], ["sle", "lupus"],
            ["ra", "rheumatoid arthritis"], ["hiv", "human immunodeficiency virus"], ["op", "organophosphorus"], ["opc", "organophosphorus"],
            ["ida", "iron deficiency anaemia"], ["anemia", "anaemia"], ["hemorrhage", "haemorrhage"], ["ischemic", "ischaemic"], ["edema", "oedema"],
            ["leukemia", "leukaemia"], ["hepatic", "liver"], ["renal", "kidney"], ["seizure", "epilep"], ["fever", "fever"]];

  static load(c) {
    if (Icd11._codes != null) return;
    const out = [];
    const ch = [];
    try {
      const r = new BufferedReader(new InputStreamReader(c.getResources().openRawResource(R.raw.icd11), "UTF-8"));
      let line;
      while ((line = r.readLine()) != null) {
        const f = line.jsplit("\t");
        if (line.startsWith("#") && f.length == 2) ch.add(f[1]);
        else if (f.length == 3) out.add(new Icd11.Code(f[0], f[1], Integer.parseInt(f[2])));
      }
      r.close();
    } catch (e) {
    }
    Icd11._chapters = ch;
    Icd11._codes = out;
  }

  static chapters(c) {
    Icd11.load(c);
    return Icd11._chapters;
  }

  static size(c) {
    Icd11.load(c);
    return Icd11._codes.length;
  }

  static byCode(c, code) {
    Icd11.load(c);
    for (const k of Icd11._codes) if (k.code.equalsIgnoreCase(code)) return k;
    return null;
  }

  /** Every word must be found (abbreviations become their words); a code typed alone matches codes that start with it. Chapter -1 = all. */
  static search(c, q, chapter) {
    Icd11.load(c);
    const codes = Icd11._codes;
    const ql = q.trim().toLowerCase();
    const out = [];
    if (ql.isEmpty()) {
      for (const k of codes) if (chapter < 0 || k.chapter == chapter) out.add(k);
      return out;
    }
    const words = [];
    for (const w of ql.jsplit("[\\s,]+")) {
      if (w.isEmpty()) continue;
      let alt = null;
      for (const s of Icd11.SHORT) if (s[0].equals(w)) alt = s[1];
      words.add(alt == null ? [w] : [w, alt]);
    }
    const starts = [];
    for (const k of codes) {
      if (chapter >= 0 && k.chapter != chapter) continue;
      if (words.length == 1 && k.code.toLowerCase().startsWith(ql)) {
        starts.add(k);
        continue;
      }
      let all = true;
      for (const w of words) {
        let one = false;
        for (const x of w) if (k.lower.contains(x)) one = true;
        if (!one) { all = false; break; }
      }
      if (all) out.add(k);
    }
    // the main codes (5A11) before their subdivisions (5A11.0), each in code order
    const subs = [];
    for (const k of out) if (k.code.indexOf('.') < 0) starts.add(k); else subs.add(k);
    starts.addAll(subs);
    return starts;
  }

  /** Adds a line to a diagnosis field, unless it is there already. */
  static add(field, k) {
    const f = Ui.nz(field).trim();
    if (f.contains("ICD-11 " + k.code + ")")) return f;
    return f.isEmpty() ? k.line() : f + "\n" + k.line();
  }

  /** "Choose ICD-11 diagnosis" button under a diagnosis field. */
  static attach(a, form, key) {
    const b = Ui.button(a, "Choose ICD-11 diagnosis (WHO, latest)", Icd11.COLOR, {
      onClick: (v) => { Icd11.pick(a, form, key); }
    });
    form.view.addView(b);
    Ui.margins(b, 0, 6, 0, 0);
    return b;
  }

  /** The scrolling picker: search box, chapter chips and the code list; tap a code to add it. */
  static pick(a, form, key) {
    Icd11.load(a);
    const chapters = Icd11._chapters;
    const box = Ui.v(a);
    const p = Ui.dp(a, 12);
    box.setPadding(p, Ui.dp(a, 4), p, 0);
    const q = new EditText(a);
    q.setHint("Search: words, abbreviation (DKA, CKD, MI) or code (5A11)");
    q.setSingleLine(true);
    q.setTextSize(15);
    box.addView(q);
    // chapters: all, then the physician's chapters first, then the rest
    const order = [];
    order.add(-1);
    for (const m of Icd11.MEDICINE_FIRST) if (chapters.indexOf(m) >= 0) order.add(chapters.indexOf(m));
    for (let i = 0; i < chapters.length; i++) if (!order.contains(i)) order.add(i);
    const chapter = [-1];
    const chips = Ui.h(a);
    const count = Ui.muted(a, "");
    const list = new ListView(a);
    const ad = new Icd11.Adapter(a);
    list.setAdapter(ad);
    const refresh = {
      run: () => {
        ad.items = Icd11.search(a, q.getText().toString(), chapter[0]);
        ad.notifyDataSetChanged();
        count.setText(ad.items.length + " codes" + (chapter[0] < 0 ? "" : " in " + chapters.get(chapter[0])) + "  \u00B7  tap to add, scroll for more");
        chips.removeAllViews();
        for (const ci of order) {
          const label = ci < 0 ? "All chapters" : Icd11.shortChapter(chapters.get(ci));
          const c = Ui.chip(a, label, ci == chapter[0], Icd11.COLOR);
          c.setOnClickListener({
            onClick: (v) => {
              chapter[0] = ci;
              refresh.run();
              list.setSelection(0);
            }
          });
          chips.addView(c);
        }
      }
    };
    box.addView(Ui.hscroll(a, chips));
    box.addView(count);
    box.addView(list, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(a, 380)));
    const src = Ui.muted(a, "ICD-11 MMS \u00A9 World Health Organization");
    src.setTextSize(10);
    box.addView(src);
    refresh.run();
    q.addTextChangedListener({
      beforeTextChanged: (s, x, y, z) => {},
      onTextChanged: (s, x, y, z) => {},
      afterTextChanged: (e) => {
        refresh.run();
        list.setSelection(0);
      }
    });
    const d = new AlertDialog.Builder(a).setTitle("Final diagnosis \u00B7 ICD-11").setView(box).setPositiveButton("Done", null).create();
    list.setOnItemClickListener({
      onItemClick: (parent, v, pos, id) => {
        const k = ad.items.get(pos);
        form.set(key, Icd11.add(form.get(key), k));
        Ui.toast(a, "Added: " + k.code + " " + k.title);
      }
    });
    d.show();
    return d;
  }

  static shortChapter(c) {
    return c.split("Diseases of the ").join("").split("Certain ").join("").split(", not elsewhere classified").join("").split("Injury, poisoning or certain other consequences of external causes").join("Injury and poisoning");
  }
}

Icd11.Code = class {
  constructor(code, title, chapter) {
    this.code = code;
    this.title = title;
    this.chapter = chapter;
    this.lower = (code + " " + title).toLowerCase();
  }

  /** "Type 2 diabetes mellitus (ICD-11 5A11)" */
  line() {
    return this.title + " (ICD-11 " + this.code + ")";
  }
};

Icd11.Adapter = class extends BaseAdapter {
  constructor(c) { super(); this.c = c; this.items = []; }

  getCount() { return this.items.length; }

  getItem(i) { return this.items[i]; }

  getItemId(i) { return i; }

  getView(i, v, parent) {
    const c = this.c;
    let row, code, title;
    if (v == null) {
      row = Ui.h(c);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(c, 8), 0, Ui.dp(c, 8));
      code = Ui.tv(c, "", 13, Icd11.COLOR, true);
      code.setMinWidth(Ui.dp(c, 64));
      title = Ui.tv(c, "", 14, Ui.TEXT, false);
      row.addView(code);
      row.addView(title, Ui.weight(1));
    } else row = v;
    code = row.getChildAt(0);
    title = row.getChildAt(1);
    const k = this.items[i];
    code.setText(k.code);
    title.setText(k.title);
    return row;
  }
};
;
