/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One X-ray or CT study of a patient: the films (camera or gallery) and the report (photo, PDF or typed impression). */
class ImagingActivity extends Base {
  constructor() { super(); this.pid = 0; this.id = -1; this.form = null; this.pendingCamera = null; this.pendingPart = null; this.clinical = false; }

  static REQ_CAMERA = 71;
  static REQ_PICK = 72;

  onCreate(b) {
    super.onCreate(b);
    this.pid = Long.parseLong(this.getIntent().getStringExtra("patient"));
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    this.clinical = "1" === this.getIntent().getStringExtra("clinical");
    if (b != null) {
      this.id = b.getLong("id", this.id);
      this.pendingCamera = b.getString("camera");
      this.pendingPart = b.getString("part");
    }
    const p = this.db.row("SELECT name FROM patients WHERE id=?", String(this.pid));
    if (this.clinical) this.setTitle(this.id >= 0 ? "Clinical photos" : "Add clinical photos");
    else this.setTitle(this.id >= 0 ? "X-ray / CT" : "Add X-ray / CT");
    this.subtitle = p == null ? "" : p.get("name");
    this.headerColor(this.clinical ? Imaging.CLINICAL_COLOR : Imaging.COLOR);
    this.headerAction("Save", { onClick: (v) => { this.save(true); } });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putLong("id", this.id);
    if (this.pendingCamera != null) out.putString("camera", this.pendingCamera);
    if (this.pendingPart != null) out.putString("part", this.pendingPart);
  }

  liveRefresh() {
    return false;
  }

  canChange() {
    const p = this.db.row("SELECT * FROM patients WHERE id=?", String(this.pid));
    return p != null && CaseSheet.canEdit(this, this.db, p);
  }

  render() {
    const db = this.db;
    const v = ImagingActivity.v;
    const r = this.id >= 0 ? db.row("SELECT * FROM " + Imaging.TABLE + " WHERE id=?", String(this.id)) : null;
    const edit = this.canChange();
    const page = Ui.v(this);
    const form0 = this.form;
    const keepKind = form0 != null ? form0.get("kind") : null, keepDate = form0 != null ? form0.get("date") : null,
      keepOther = form0 != null ? form0.get("other") : null, keepImp = form0 != null ? form0.get("impression") : null;
    this.form = new Form(this);
    if (this.clinical) {
      this.form.suggest("other", "Finding (e.g. rash, pedal oedema, clubbing, ulcer)", keepOther != null ? keepOther : v(r, "other", ""), ImagingActivity.FINDINGS);
      this.form.date("date", "Date", keepDate != null ? keepDate : v(r, "date", Dates.todayIso()));
      this.form.multi("impression", "Notes (site, size, description; optional)", keepImp != null ? keepImp : v(r, "impression", Ui.nz(this.getIntent().getStringExtra("impression"))));
      const fc = Ui.card(this);
      fc.addView(this.form.view);
      page.addView(fc);
      page.addView(this.part(Imaging.FILM, "📸 Photos", "Take the photo with the camera or pick it from the gallery. Several photos can be added. "
        + "Ask the patient's consent; avoid the face unless the finding is on it.", edit));
      this.footer(page, r, edit);
      return;
    }
    this.form.choice("kind", "Study", Imaging.KINDS, Imaging.KINDS, keepKind != null ? keepKind : v(r, "kind", Imaging.KINDS[0]), {
      changed: (val) => { this.form.show("other", "Other" === val); }
    });
    this.form.text("other", "Which study (e.g. USG abdomen, MRI brain, CT KUB)", keepOther != null ? keepOther : v(r, "other", ""), Form.PLAIN);
    this.form.show("other", "Other" === this.form.get("kind"));
    this.form.date("date", "Date of the study", keepDate != null ? keepDate : v(r, "date", Dates.todayIso()));
    this.form.multi("impression", "Report impression (type the radiologist's impression, optional)", keepImp != null ? keepImp : v(r, "impression", Ui.nz(this.getIntent().getStringExtra("impression"))));
    const fc = Ui.card(this);
    fc.addView(this.form.view);
    page.addView(fc);

    page.addView(this.part(Imaging.FILM, "🎞 Films", "Photograph the film against a light box or window, or the screen. Several films can be added.", edit));
    page.addView(this.part(Imaging.REPORT, "📄 Report", "Photograph the printed report, or pick the report PDF.", edit));
    this.footer(page, r, edit);
  }

  footer(page, r, edit) {
    const db = this.db;
    const clinical = this.clinical;
    if (r != null) page.addView(Ui.muted(this, "  Added by " + Ui.nz(r.get("by_name")) + "  ·  " + Chat.when(r.get("time"))));
    if (!edit) page.addView(Ui.muted(this, clinical ? "  View only: the patient's unit can add or change these photos." : "  View only: the patient's unit can add or change imaging."));
    else if (this.id >= 0) {
      const del = Ui.outlineButton(this, clinical ? "Delete these photos" : "Delete this study", Ui.RED, {
        onClick: (x) => {
          Ui.confirm(this, clinical ? "Delete these photos?" : "Delete this study?", clinical ? "The photos are removed for everyone." : "The films and the report are removed for everyone.", "Delete", {
            run: () => {
              Imaging.delete(db, this.id);
              this.finish();
            }
          });
        }
      });
      const w = Ui.v(this);
      w.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), 0);
      w.addView(del);
      page.addView(w);
    }
    this.setPage(page);
    this.attachShared();
  }

  /** 10.3: photos or a PDF shared from WhatsApp (moved into imaging/ by ShareInActivity) are added once, as a new study. */
  attachShared() {
    const shared = this.getIntent().getStringExtra("shared");
    if (shared == null || shared.isEmpty()) return;
    this.getIntent().removeExtra("shared");
    let part = this.getIntent().getStringExtra("part");
    if (part == null) part = Imaging.FILM;
    if (!this.save(false)) return;
    for (const rel of shared.split("|")) {
      if (rel.isEmpty() || !this.db.file(rel).exists()) continue;
      if (Store.isImage(rel)) Store.shrink(this.db.file(rel), 2400);
      else if (Imaging.REPORT !== part) continue;
      Imaging.addFile(this.db, this.id, part, rel);
    }
    Ui.toast(this, "Added. Check the details and tap Save");
    this.render();
  }

  part(part, title, hint, edit) {
    const db = this.db;
    const c = Ui.card(this);
    const fs = this.id >= 0 ? Imaging.files(db, String(this.id), part) : [];
    c.addView(Ui.title(this, title + (fs.isEmpty() ? "" : "  ·  " + fs.size())));
    if (fs.isEmpty()) c.addView(Ui.muted(this, hint));
    const row = Ui.h(this);
    for (const f of fs) {
      const t = Imaging.thumb(this, db, f.get("file"), 96, Imaging.REPORT === part);
      t.setOnClickListener({ onClick: (v) => { Imaging.open(this, db, f.get("file")); } });
      if (edit) t.setOnLongClickListener({
        onLongClick: (v) => {
          Ui.confirm(this, "Remove this picture?", "", "Remove", {
            run: () => {
              Imaging.removeFile(db, f.get("id"));
              this.render();
            }
          });
          return true;
        }
      });
      row.addView(t);
      Ui.margins(t, 0, 0, 8, 0);
    }
    if (!fs.isEmpty()) {
      const hs = new HorizontalScrollView(this);
      hs.addView(row);
      c.addView(hs);
      Ui.margins(hs, 0, 8, 0, 4);
      if (edit) c.addView(Ui.muted(this, "Tap to view large  ·  long-press to remove"));
    }
    if (edit) {
      const mimes = Imaging.REPORT === part ? ["image/*", "application/pdf"] : ["image/*"];
      c.addView(Ui.buttonRow(this,
        Ui.button(this, "Camera", Imaging.COLOR, {
          onClick: (v) => {
            if (!this.save(false)) return;
            this.pendingPart = part;
            this.pendingCamera = Imaging.DIR + "/" + part + "_" + this.id + "_" + System.currentTimeMillis() + ".jpg";
            if (!Store.capture(this, this.pendingCamera, ImagingActivity.REQ_CAMERA)) this.pendingCamera = null;
          }
        }),
        Ui.outlineButton(this, Imaging.REPORT === part ? "Gallery / PDF" : "Gallery", Imaging.COLOR, {
          onClick: (v) => {
            if (!this.save(false)) return;
            this.pendingPart = part;
            Store.pick(this, mimes, ImagingActivity.REQ_PICK);
          }
        })));
    }
    return c;
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    const db = this.db;
    if (res !== RESULT_OK || this.id < 0 || this.pendingPart == null) return;
    try {
      if (req === ImagingActivity.REQ_CAMERA && this.pendingCamera != null) {
        const f = db.file(this.pendingCamera);
        if (!f.exists() || f.length() === 0) return;
        Store.shrink(f, 2400);
        Imaging.addFile(db, this.id, this.pendingPart, this.pendingCamera);
        this.pendingCamera = null;
      } else if (req === ImagingActivity.REQ_PICK && data != null && data.getData() != null) {
        const rel = Store.importUri(this, data.getData(), Imaging.DIR, this.pendingPart + "_" + this.id);
        const pdf = rel.toLowerCase().endsWith(".pdf");
        if (!Store.isImage(rel) && !(pdf && Imaging.REPORT === this.pendingPart)) {
          db.file(rel).delete();
          Ui.toast(this, Imaging.REPORT === this.pendingPart ? "Pick a photo or a PDF" : "Pick a photo (JPG or PNG)");
          return;
        }
        if (Store.isImage(rel)) Store.shrink(db.file(rel), 2400);
        Imaging.addFile(db, this.id, this.pendingPart, rel);
      }
      this.render();
    } catch (e) {
      Ui.toast(this, "Could not add the picture: " + e.getMessage());
    }
  }

  /** For tests: attach a file already in filesDir. */
  attach(part, rel) {
    this.save(false);
    Imaging.addFile(this.db, this.id, part, rel);
    this.render();
  }

  /** Saves the study (creating it the first time). close: finish the screen afterwards. */
  save(close) {
    const form = this.form;
    if (form == null) return false;
    if (!this.canChange()) {
      if (close) this.finish();
      return false;
    }
    if (!this.clinical && "Other" === form.get("kind") && form.get("other").trim().isEmpty()) {
      Ui.toast(this, "Write which study it is");
      return false;
    }
    const cv = new ContentValues();
    if (this.clinical) {
      cv.put("kind", Imaging.CLINICAL);
      cv.put("other", form.get("other").trim());
    } else {
      cv.put("kind", form.get("kind"));
      cv.put("other", "Other" === form.get("kind") ? form.get("other").trim() : "");
    }
    cv.put("date", form.get("date"));
    cv.put("impression", form.get("impression").trim());
    if (this.id < 0) {
      cv.put("patient_id", this.pid);
      cv.put("by_name", Chat.myName(this, this.db));
      cv.put("time", Chat.now());
      this.id = this.db.insert(Imaging.TABLE, cv);
    } else this.db.update(Imaging.TABLE, cv, this.id);
    if (close) {
      Ui.toast(this, "Saved");
      this.finish();
    }
    return true;
  }

  static v(r, k, def) {
    return r == null || Ui.nz(r.get(k)).isEmpty() ? def : r.get(k);
  }
}

ImagingActivity.FINDINGS = ["Rash", "Pedal oedema", "Clubbing", "Pallor", "Icterus", "Cyanosis", "Lymph node", "Goitre", "Ulcer", "Bed sore",
  "Bite site", "Cellulitis", "Petechiae / purpura", "Joint swelling", "Wasting", "Fundus", "Skin lesion", "Wound", "Other"];
