/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Recognises what a document holds and turns it into records: the morning duty roster, staff lists,
 * patient (admission) lists, CMCHIS lists and call duty sick case lists. Anything else can go to the information board.
 */
class Importer {
  static ROSTER = "roster";
  static STAFF = "staff";
  static PATIENTS = "patients";
  static CMCHIS = "cmchis";
  static SICK = "sick";

  // column name → field
  static COLS = [
    ["name", "name|patient name|name of the patient|patient|staff name|name of staff|doctor|doctor name|name of the doctor|faculty"],
    ["ip_no", "ip|ip no|ip no.|ip number|ipno|i.p. no|i.p.no|ip/op no|inpatient no|ip num|mrd no|uhid"],
    ["age", "age|age \\(yrs\\)|age in years|age \\(years\\)"],
    ["sex", "sex|gender|m/f"],
    ["age_sex", "age/sex|age / sex|age & sex|age and sex|a/s"],
    ["diagnosis", "diagnosis|dx|provisional diagnosis|final diagnosis|disease|complaints|clinical diagnosis"],
    ["unit", "unit|ward|unit/ward|ward/unit|dept unit|medical unit|location"],
    ["date", "date|doa|date of admission|admission date|admitted on|date of adm|adm date|from|date put up"],
    ["bed", "bed|bed no|bed no.|bed number"],
    ["phone", "phone|mobile|mobile no|mobile number|contact|contact no|cell|phone no|ph no|ph.no"],
    ["role", "designation|role|post|cadre|rank|position"],
    ["address", "address|place|village|town"],
    ["cmchis_no", "cmchis|cmchis no|cmchis id|card no|card number|pre-auth no|preauth no|pre auth no|urn|cmchis card no"],
    ["package", "package|procedure|package code|package name|procedure code"],
    ["amount", "amount|amount \\(rs\\)|amount rs|rs|cost|claim amount|approved amount"],
    ["status", "status|approval|approval status|approved/not approved|condition"],
    ["issue", "issue|issues|problem|problems|plan|remarks|comments|notes|clinical status|current status"],
  ];

  static fieldOf(header) {
    let h = header.toLowerCase().replaceAllRx("[*:#]", "").replaceAllRx("\\s+", " ").trim();
    h = h.replaceAllRx("\\.$", "");
    for (const c of Importer.COLS) if (h.matches("(" + c[1] + ")")) return c[0];
    // looser: header contains the word
    if (h.contains("diagnos")) return "diagnosis";
    if (h.contains("mobile") || h.contains("phone")) return "phone";
    if (h.contains("designation")) return "role";
    if (h.contains("cmchis") || h.contains("pre-auth") || h.contains("preauth")) return "cmchis_no";
    if (h.contains("ip no") || h.equals("ip") || h.startsWith("ip ")) return "ip_no";
    if (h.contains("patient") && h.contains("name")) return "name";
    if (h.contains("admission") && h.contains("date")) return "date";
    return null;
  }

  /** Looks at the extracted text and tables and reports what can be added. */
  static analyze(db, r) {
    const out = [];
    const text = r.text.toString();
    const rp = Roster.parse(text);
    const low = text.toLowerCase();
    if (rp.count >= 5 && (low.contains("dap") || low.contains("imcu") || low.contains("triage"))) {
      const f = new Importer.Finding();
      f.kind = Importer.ROSTER;
      f.roster = rp;
      f.title = "Daily duty roster";
      f.detail = rp.count + " duty entries" + (rp.date == null ? "" : " for " + Dates.nice(rp.date)) + (rp.unit == null ? "" : ", " + Db.unitName(rp.unit) + " admission day");
      f.fresh = 1;
      out.add(f);
    }
    if (low.contains("sick case list")) {
      const f = Importer.sickFromShare(db, text);
      if (f != null) out.add(f);
    }
    for (const t of r.tables) {
      const f = Importer.table(db, t);
      if (f != null) out.add(f);
    }
    return out;
  }

  /** Reads a table: finds the header row, maps its columns, and decides what kind of list it is. */
  static table(db, t) {
    let hdr = -1;
    let fields = null;
    for (let i = 0; i < Math.min(8, t.size()); i++) {
      const row = t.get(i);
      const f = new Array(row.size()).fill(null);
      let known = 0;
      for (let c = 0; c < row.size(); c++) {
        f[c] = Importer.fieldOf(row.get(c));
        if (f[c] != null) known++;
      }
      if (known >= 2 && Importer.contains(f, "name")) { hdr = i; fields = f; break; }
    }
    if (hdr < 0) return null;
    const fd = new Importer.Finding();
    fd.header.addAll(t.get(hdr));
    const hasIp = Importer.contains(fields, "ip_no"), hasDx = Importer.contains(fields, "diagnosis"), hasRole = Importer.contains(fields, "role"),
      hasCm = Importer.contains(fields, "cmchis_no") || Importer.contains(fields, "package"), hasIssue = Importer.contains(fields, "issue"),
      hasAge = Importer.contains(fields, "age") || Importer.contains(fields, "age_sex") || Importer.contains(fields, "sex");
    const headLow = Extract.join(t.get(hdr), " ").toLowerCase();
    if (hasCm || headLow.contains("cmchis")) fd.kind = Importer.CMCHIS;
    else if (hasRole && !hasIp && !hasDx) fd.kind = Importer.STAFF;
    else if (hasIssue && !hasAge && Importer.contains(fields, "unit")) fd.kind = Importer.SICK;
    else if (hasIp || hasDx || hasAge) fd.kind = Importer.PATIENTS;
    else if (Importer.contains(fields, "phone")) fd.kind = Importer.STAFF;
    else return null;

    for (let i = hdr + 1; i < t.size(); i++) {
      const row = t.get(i);
      const m = new JMap();
      for (let c = 0; c < Math.min(row.size(), fields.length); c++) {
        if (fields[c] == null) continue;
        const v = row.get(c).trim();
        if (!v.isEmpty() && !m.containsKey(fields[c])) m.put(fields[c], v);
      }
      const name = Ui.nz(m.get("name")).trim();
      if (name.isEmpty() || name.matches("[\\d.\\s]+") || Importer.fieldOf(name) != null) continue;
      if (m.containsKey("age_sex")) Importer.splitAgeSex(m);
      if (m.containsKey("unit")) {
        const u = Importer.unitCode(m.get("unit"));
        if (u == null) m.remove("unit"); else m.put("unit", u);
      }
      if (!m.containsKey("unit")) fd.needsUnit = true;
      if (m.containsKey("date")) {
        const d = Importer.parseDate(m.get("date"));
        if (d == null) m.remove("date"); else m.put("date", d);
      }
      if (m.containsKey("phone")) m.put("phone", m.get("phone").replaceAllRx("[^+\\d]", ""));
      fd.rows.add(m);
    }
    if (fd.rows.isEmpty()) return null;
    for (const m of fd.rows) if (!Importer.exists(db, fd.kind, m)) fd.fresh++;
    const n = fd.rows.size();
    switch (fd.kind) {
      case Importer.STAFF: fd.title = "Staff list"; fd.detail = n + " people" + Importer.already(n, fd.fresh); break;
      case Importer.PATIENTS: fd.title = "Patient list"; fd.detail = n + " patients" + Importer.already(n, fd.fresh); break;
      case Importer.CMCHIS: fd.title = "CMCHIS list"; fd.detail = n + " patients" + Importer.already(n, fd.fresh); break;
      default: fd.title = "Sick case list"; fd.detail = n + " patients" + Importer.already(n, fd.fresh); break;
    }
    return fd;
  }

  static already(n, fresh) {
    return n == fresh ? "" : ", " + (n - fresh) + " already in the app";
  }

  /** The sick case list as the app shares it on WhatsApp ("*Sick case list · call duty …*"). */
  static sickFromShare(db, text) {
    const f = new Importer.Finding();
    f.kind = Importer.SICK;
    let ward = null;
    const item = Pattern.compile("^[•*-]\\s*(.+?)(?:, bed ([^,–-]+))?(?:, IP ([^–-]+))?\\s+[–-]\\s+([A-Za-z ]+?)(?::\\s*(.*))?$");
    for (const line of text.jsplit("\n")) {
      const l = line.trim();
      if (l.startsWith("*") && l.endsWith("*") && !l.toLowerCase().contains("sick case")) {
        ward = Importer.unitCode(l.split("*").join(""));
        continue;
      }
      const m = item.matcher(l);
      if (!m.find() || ward == null) continue;
      const r = new JMap();
      r.put("name", m.group(1).trim());
      if (m.group(2) != null) r.put("bed", m.group(2).trim());
      if (m.group(3) != null) r.put("ip_no", m.group(3).trim());
      r.put("status", m.group(4).trim());
      if (m.group(5) != null) r.put("issue", m.group(5).trim());
      r.put("unit", ward);
      f.rows.add(r);
    }
    if (f.rows.isEmpty()) return null;
    f.header.add("Patient");
    f.title = "Sick case list";
    f.fresh = f.rows.size();
    f.detail = f.rows.size() + " patients";
    return f;
  }

  static exists(db, kind, m) {
    const name = Ui.nz(m.get("name")).trim();
    switch (kind) {
      case Importer.STAFF: return db.num("SELECT COUNT(*) FROM staff WHERE lower(trim(name))=lower(?)", name) > 0;
      case Importer.PATIENTS:
        if (!Ui.nz(m.get("ip_no")).isEmpty()) return db.num("SELECT COUNT(*) FROM patients WHERE ip_no=?", m.get("ip_no")) > 0;
        return db.num("SELECT COUNT(*) FROM patients WHERE lower(name)=lower(?) AND status='IN'", name) > 0;
      case Importer.CMCHIS: return db.num("SELECT COUNT(*) FROM cmchis_cases WHERE lower(patient)=lower(?) AND (ip_no=? OR ?='')", name, Ui.nz(m.get("ip_no")), Ui.nz(m.get("ip_no"))) > 0;
      default: return false;
    }
  }

  // ---------- adding ----------

  /** Adds the rows that are not in the app yet. Returns how many were added. */
  static apply(db, f, defaultUnit, dutyDate) {
    let added = 0;
    if (f.kind.equals(Importer.ROSTER)) {
      const date = f.roster.date != null ? f.roster.date : dutyDate;
      const cv = new ContentValues();
      cv.put("date", date);
      cv.put("unit", f.roster.unit != null ? f.roster.unit : defaultUnit);
      for (const k of Roster.keys()) cv.put(k, f.roster.fields.containsKey(k) ? f.roster.fields.get(k) : "");
      const same = db.row("SELECT id FROM duty_roster WHERE date=? ORDER BY id DESC LIMIT 1", date);
      if (same != null) db.update("duty_roster", cv, Long.parseLong(same.get("id")));
      else db.insert("duty_roster", cv);
      const dap = f.roster.fields.containsKey("dap") ? f.roster.fields.get("dap").jsplit("\n")[0] : "";
      if (!dap.isEmpty()) {
        const d = db.row("SELECT id FROM dap WHERE date=? ORDER BY id DESC LIMIT 1", date);
        const dv = new ContentValues();
        dv.put("dap_name", Roster.name(dap));
        if (d == null) {
          dv.put("date", date);
          dv.put("unit", cv.getAsString("unit"));
          db.insert("dap", dv);
        } else db.update("dap", dv, Long.parseLong(d.get("id")));
      }
      return 1;
    }
    for (const m of f.rows) {
      if (Importer.exists(db, f.kind, m)) continue;
      const unit = m.containsKey("unit") ? m.get("unit") : defaultUnit;
      const name = m.get("name").trim();
      switch (f.kind) {
        case Importer.STAFF: {
          const cv = new ContentValues();
          cv.put("name", name);
          cv.put("role", Importer.role(Ui.nz(m.get("role"))));
          cv.put("unit", unit);
          cv.put("phone", Ui.nz(m.get("phone")));
          db.insert("staff", cv);
          break;
        }
        case Importer.PATIENTS: {
          const cv = new ContentValues();
          cv.put("name", name);
          cv.put("ip_no", Ui.nz(m.get("ip_no")));
          const age = Ui.nz(m.get("age")).replaceAllRx("[^0-9]", "");
          if (!age.isEmpty()) cv.put("age", Integer.parseInt(age.length > 3 ? age.substring(0, 3) : age));
          cv.put("sex", Importer.sex(Ui.nz(m.get("sex"))));
          cv.put("diagnosis", Ui.nz(m.get("diagnosis")));
          cv.put("phone", Ui.nz(m.get("phone")));
          cv.put("address", Ui.nz(m.get("address")));
          cv.put("bed", Ui.nz(m.get("bed")));
          const date = m.containsKey("date") ? m.get("date") : Dates.todayIso();
          const parent = Db.isWardUnit(unit) ? unit : db.todaysUnit();
          db.admit(cv, unit, parent, date, "");
          break;
        }
        case Importer.CMCHIS: {
          const cv = new ContentValues();
          cv.put("unit", Db.isWardUnit(unit) || Db.IMCU.equals(unit) ? unit : defaultUnit);
          cv.put("patient", name);
          cv.put("date", m.containsKey("date") ? m.get("date") : Dates.todayIso());
          const as = (Ui.nz(m.get("age")) + (m.containsKey("sex") ? " / " + m.get("sex") : "")).trim();
          cv.put("age_sex", as.startsWith("/") ? as.substring(1).trim() : as);
          cv.put("ip_no", Ui.nz(m.get("ip_no")));
          cv.put("cmchis_no", Ui.nz(m.get("cmchis_no")));
          cv.put("diagnosis", Ui.nz(m.get("diagnosis")));
          cv.put("package", Ui.nz(m.get("package")));
          let amt = 0;
          try { amt = Double.parseDouble(Ui.nz(m.get("amount")).replaceAllRx("[^0-9.]", "")); } catch (ignored) {}
          cv.put("amount", amt);
          cv.put("status", Importer.approval(Ui.nz(m.get("status"))));
          cv.put("remarks", Ui.nz(m.get("issue")));
          const p = db.row("SELECT id FROM patients WHERE lower(name)=lower(?) ORDER BY id DESC LIMIT 1", name);
          if (p != null) cv.put("patient_id", p.get("id"));
          db.insert("cmchis_cases", cv);
          break;
        }
        default: {
          const cv = new ContentValues();
          cv.put("date", dutyDate);
          cv.put("ward", unit);
          cv.put("patient", name);
          cv.put("bed", Ui.nz(m.get("bed")));
          cv.put("ip_no", Ui.nz(m.get("ip_no")));
          cv.put("issue", Ui.nz(m.get("issue")) + (m.containsKey("diagnosis") ? (m.containsKey("issue") ? " · " : "") + m.get("diagnosis") : ""));
          cv.put("status", Importer.sickStatus(Ui.nz(m.get("status"))));
          cv.put("by_name", "Imported");
          cv.put("updated", Alerts.now());
          db.insert("duty_sick", cv);
        }
      }
      added++;
    }
    return added;
  }

  // ---------- value clean-up ----------

  static unitCode(s) {
    const l = s.toLowerCase().replaceAllRx("[^a-z0-9 ]", " ").replaceAllRx("\\s+", " ").trim();
    if (l.isEmpty()) return null;
    if (l.contains("imcu") || l.contains("icu")) return Db.IMCU;
    if (l.contains("fever")) return Db.FEVER;
    if (l.contains("ccb") || l.contains("critical care")) return Db.CCB;
    if (l.contains("geriatric") || l.contains("geri")) return Db.GERI;
    if (l.contains("rheum")) return Db.RHEUM;
    if (l.contains("kandiyaperi") || l.equals("kdp")) return Db.KDP;
    const m = Pattern.compile("^(?:m|mu|unit|medical unit|med|medicine)?\\s*([1-7])\\b").matcher(l);
    if (m.find()) return "M" + m.group(1);
    const roman = ["i", "ii", "iii", "iv", "v", "vi", "vii"];
    const core = l.replaceFirstRx("^(m|unit|medical unit)\\s*", "").trim();
    for (let i = 0; i < 7; i++) if (core.equals(roman[i])) return "M" + (i + 1);
    for (let i = 0; i < 7; i++) if (l.startsWith(Roster.ORDINALS[i])) return "M" + (i + 1);
    return null;
  }

  static role(s) {
    const l = s.toLowerCase();
    if (l.contains("assoc")) return "Associate Professor";
    if (l.contains("asst") || l.contains("assistant") || l.equals("ap")) return "Assistant Professor";
    if (l.contains("prof") || l.contains("hod") || l.contains("chief")) return "Professor";
    const pgWord = l.contains("pg") || l.contains("post") || l.contains("md ") || l.contains("resident");
    if (l.contains("mbbs") || l.contains("ug") || !pgWord) {
      if (l.contains("prefinal") || l.contains("pre-final") || l.contains("pre final")) return "MBBS Prefinal year";
      if (l.contains("final")) return "MBBS Final year";
      if (l.contains("mbbs")) return "MBBS 2nd year";
    }
    if (l.contains("pg") || l.contains("post") || l.contains("resident") || l.contains("md ")) return "Postgraduate";
    if (l.contains("crri") || l.contains("crmi") || l.contains("intern") || l.contains("hs")) return "CRMI";
    if (l.contains("nurse") || l.contains("sister")) return "Staff Nurse";
    return "Other";
  }

  static sex(s) {
    const l = s.trim().toLowerCase();
    if (l.startsWith("f") || l.startsWith("w")) return "F";
    if (l.startsWith("m")) return "M";
    if (l.startsWith("t")) return "T";
    return "M";
  }

  static splitAgeSex(m) {
    const x = Pattern.compile("(\\d{1,3})\\s*(?:y|yr|yrs|years)?\\s*[/,\\s-]*\\s*([MmFfTt])?").matcher(m.get("age_sex"));
    if (x.find()) {
      if (!m.containsKey("age")) m.put("age", x.group(1));
      if (x.group(2) != null && !m.containsKey("sex")) m.put("sex", x.group(2));
    }
  }

  static approval(s) {
    return CmchisStages.of(s);
  }

  static sickStatus(s) {
    for (const k of CallDutyActivity.STATUS) if (k.equalsIgnoreCase(s.trim())) return k;
    const l = s.toLowerCase();
    if (l.contains("critical") || l.contains("serious")) return "Critical";
    if (l.contains("improv")) return "Improving";
    if (l.contains("stable")) return "Stable";
    return "Sick";
  }

  static parseDate(s) {
    s = s.trim();
    if (s.matches("\\d{4}-\\d{2}-\\d{2}.*")) return s.substring(0, 10);
    if (s.matches("\\d{5}(\\.\\d+)?")) return Extract.serialDate(s);
    const m = Pattern.compile("(\\d{1,2})[/.-](\\d{1,2})[/.-](\\d{2,4})").matcher(s);
    if (m.find()) {
      try {
        const y = Integer.parseInt(m.group(3));
        return LocalDate.of(y < 100 ? 2000 + y : y, Integer.parseInt(m.group(2)), Integer.parseInt(m.group(1))).toString();
      } catch (ignored) {}
    }
    return null;
  }

  static contains(a, v) {
    for (const s of a) if (v.equals(s)) return true;
    return false;
  }
}

/** One thing found in the document. */
Importer.Finding = class {
  constructor() {
    this.kind = null; this.title = null; this.detail = null;
    this.header = [];
    this.rows = [];            // field → value
    this.roster = null;        // Roster.Parsed
    this.fresh = 0;            // rows not already in the app
    this.needsUnit = false;    // some rows have no unit / ward column
  }
};
;
