'use strict';
/** Kandiyaperi Hospital: the peripheral hospital's daily outpatients and its inpatients. */
class KdpActivity extends Base {
  constructor() {
    super();
    this.day = null;
    this.newM = null; this.newF = null; this.review = null; this.doctor = null; this.notes = null;
  }

  onCreate(b) {
    super.onCreate(b);
    this.day = Dates.today();
    this.setTitle("Kandiyaperi Hospital");
    this.subtitle = "Peripheral hospital attached to TVMCH";
    this.headerColor(Ui.unitColor(Db.KDP));
    this.headerAction("+ Admit", this.opener(FormActivity, "kind", "patient", "unit", Db.KDP));
  }

  liveRefresh() {
    return false;
  }

  render() {
    const db = this.db;
    const color = Ui.unitColor(Db.KDP);
    const page = Ui.v(this);
    const m0 = Dates.monthStart(Dates.today()).toString(), m1 = Dates.todayIso();

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(color), 20));
    const m = db.census(Db.KDP, "M"), f = db.census(Db.KDP, "F");
    const opMonth = db.num("SELECT SUM(new_m + new_f + review) FROM kdp_op WHERE date BETWEEN ? AND ?", m0, m1);
    hero.addView(Ui.statRow(this, this.ws(String(m + f), "Inpatients"), this.ws(String(m), "Male"), this.ws(String(f), "Female"),
        this.ws(String(opMonth), "OP this month")));
    const head = db.unitHead(Db.KDP);
    if (!head.isEmpty()) hero.addView(Ui.tv(this, "In-charge: " + head, 12, 0xD9FFFFFF, false));
    page.addView(hero);

    // Outpatient entry
    page.addView(Ui.heading(this, "Outpatients", color));
    const op = db.row("SELECT * FROM kdp_op WHERE date=?", this.day.toString());
    const card = Ui.card(this);
    const nav = Ui.h(this);
    nav.addView(Ui.outlineButton(this, "‹", color, {
      onClick: (v) => { this.day = this.day.minusDays(1); this.render(); }
    }));
    const d = Ui.tv(this, Dates.longFmt(this.day), 15, Ui.TEXT, true);
    d.setGravity(Gravity.CENTER);
    nav.addView(d, Ui.weight(1));
    const next = Ui.outlineButton(this, "›", color, {
      onClick: (v) => { this.day = this.day.plusDays(1); this.render(); }
    });
    if (!this.day.isBefore(Dates.today())) next.setVisibility(View.INVISIBLE);
    nav.addView(next);
    card.addView(nav);
    const nums = Ui.h(this);
    this.newM = this.numField(nums, "New male", op == null ? "" : op.get("new_m"));
    this.newF = this.numField(nums, "New female", op == null ? "" : op.get("new_f"));
    this.review = this.numField(nums, "Review", op == null ? "" : op.get("review"));
    card.addView(nums);
    Ui.margins(nums, 0, 8, 0, 0);
    this.doctor = new EditText(this);
    this.doctor.setHint("Doctor(s) on OP duty");
    this.doctor.setText(op == null ? "" : op.get("doctor"));
    card.addView(this.doctor);
    this.notes = new EditText(this);
    this.notes.setHint("Notes (referrals to TVMCH, issues)");
    this.notes.setText(op == null ? "" : op.get("notes"));
    card.addView(this.notes);
    const save = Ui.button(this, op == null ? "Save OP for this day" : "Update OP", color, {
      onClick: (v) => { this.saveOp(); }
    });
    card.addView(save);
    Ui.margins(save, 0, 8, 0, 0);
    page.addView(card);

    const days = db.rows("SELECT * FROM kdp_op ORDER BY date DESC LIMIT 10");
    if (!days.isEmpty()) {
      const hist = Ui.card(this);
      hist.addView(Ui.tv(this, "Recent OP days", 14, color, true));
      for (const r of days) {
        const total = Ui.toInt(r.get("new_m"), 0) + Ui.toInt(r.get("new_f"), 0) + Ui.toInt(r.get("review"), 0);
        const row = Ui.kv(this, Dates.nice(r.get("date")), total + " (new M " + r.get("new_m") + ", F " + r.get("new_f") + ", review " + r.get("review") + ")");
        Ui.ripple(row, Ui.alpha(color, 0x1A));
        row.setOnClickListener({
          onClick: (v) => {
            const x = Dates.parse(r.get("date"));
            if (x != null) { this.day = x; this.render(); }
          }
        });
        hist.addView(row);
      }
      page.addView(hist);
    }

    // Inpatients
    page.addView(Ui.heading(this, Dates.month(Dates.today()) + " inpatients", color));
    const st = Ui.card(this);
    st.addView(Ui.statRow(this,
        Ui.stat(this, String(db.events(Db.ADMIT, m0, m1, "to_loc", Db.KDP)), "Admitted", color),
        Ui.stat(this, String(db.events(Db.DISCHARGE, m0, m1, "from_loc", Db.KDP)), "Discharged", Ui.GREEN),
        Ui.stat(this, String(db.transfers(m0, m1, Db.KDP, null)), "Sent to TVMCH", Ui.ORANGE),
        Ui.stat(this, String(db.events(Db.DEATH, m0, m1, "from_loc", Db.KDP)), "Deaths", Ui.SLATE)));
    page.addView(st);
    const ips = db.rows("SELECT * FROM patients WHERE status='IN' AND location='KDP' ORDER BY sex, CAST(bed AS INTEGER), admit_date DESC");
    page.addView(Ui.section(this, "In ward now  ·  " + ips.size()));
    if (ips.isEmpty()) page.addView(this.emptyNote("No inpatients. Use “+ Admit” to add one."));
    for (const p of ips) page.addView(this.patientRow(p));
    const recent = db.rows("SELECT * FROM patients WHERE status<>'IN' AND id IN (SELECT patient_id FROM events WHERE type IN ('DISCHARGE','DEATH') AND from_loc='KDP') ORDER BY outcome_date DESC LIMIT 15");
    if (!recent.isEmpty()) {
      page.addView(Ui.section(this, "Recently discharged or died"));
      for (const p of recent) page.addView(this.patientRow(p));
    }
    this.setPage(page);
  }

  numField(row, label, val) {
    const b = Ui.v(this);
    b.addView(Ui.tv(this, label, 12, Ui.MUTED, true));
    const e = new EditText(this);
    e.setInputType(Form.NUMBER);
    e.setText(val);
    e.setHint("0");
    b.addView(e);
    const p = Ui.weight(1);
    if (row.getChildCount() > 0) p.leftMargin = Ui.dp(this, 10);
    row.addView(b, p);
    return e;
  }

  saveOp() {
    const cv = new ContentValues();
    cv.put("date", this.day.toString());
    cv.put("new_m", Ui.toInt(this.newM.getText().toString(), 0));
    cv.put("new_f", Ui.toInt(this.newF.getText().toString(), 0));
    cv.put("review", Ui.toInt(this.review.getText().toString(), 0));
    cv.put("doctor", this.doctor.getText().toString().trim());
    cv.put("notes", this.notes.getText().toString().trim());
    this.db.upsertBy("kdp_op", cv, "date=?", this.day.toString());
    Ui.toast(this, "OP saved for " + Dates.nice(this.day));
    this.render();
  }

  ws(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    const n = Ui.tv(this, v, 24, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 11, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    return l;
  }
}
;
