/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Library: the department's PDF e-books on wooden shelves, each with its front page. Tapping a book opens it in the browser's
 * own PDF reader (an uploaded book downloads first, once) or, for a Google Drive book, in Google Drive; members add books by
 * uploading a PDF (up to 45 MB) or, for a bigger book, with its Google Drive link.
 */
class LibraryActivity extends Base {
  static REQ_PDF = 61;
  static WOOD = 0xFF8B5E34;
  static WOOD_DARK = 0xFF5C3A1E;
  static WOOD_LIGHT = 0xFFB98552;

  constructor() {
    super();
    this.query = "";
    this.shelf = null;
    this.list = null;
    this.visible = false;
  }

  onCreate(b) {
    super.onCreate(b);
    if (b != null) {
      this.query = Ui.nz(b.getString("query", ""));
      this.shelf = b.getString("shelf");
    }
    this.setTitle("Library");
    this.subtitle = "The department's PDF e-books";
    this.headerColor(LibraryActivity.WOOD);
    this.headerAction("+ Add book", { onClick: (v) => { this.addBook(); } });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putString("query", this.query);
    if (this.shelf != null) out.putString("shelf", this.shelf);
  }

  onResume() {
    this.visible = true;
    LibraryService.screen = this;
    super.onResume();
  }

  onPause() {
    this.visible = false;
    super.onPause();
  }

  onDestroy() {
    if (LibraryService.screen === this) LibraryService.screen = null;
    super.onDestroy();
  }

  render() {
    const db = this.db;
    Library.tidy(db);
    const W = LibraryActivity;
    const page = Ui.v(this);
    const hero = Ui.card(this);
    hero.setBackground(Ui.gradient(this, [W.WOOD_LIGHT, W.WOOD, W.WOOD_DARK], 20));
    const n = Library.count(db);
    const shelves = Library.shelves(db).size();
    hero.addView(Ui.tv(this, "📚  " + n + (n === 1 ? " book" : " books") + (n === 0 ? "" : " on " + shelves + (shelves === 1 ? " shelf" : " shelves")), 19, 0xFFFFFFFF, true));
    hero.addView(Ui.tv(this, "Tap a book to open it in your PDF reader. Anyone can add a book: a PDF up to 45 MB uploads here; "
      + "a bigger book goes in as its Google Drive link and opens in Google Drive.", 13, 0xEFFFFFFF, false));
    const add = Ui.button(this, "Add a book", W.WOOD_DARK, { onClick: (v) => { this.addBook(); } });
    hero.addView(add);
    Ui.margins(add, 0, 12, 0, 0);
    page.addView(hero);

    const search = new EditText(this);
    search.setHint("Search title, author or shelf");
    search.setSingleLine(true);
    search.setText(this.query);
    search.setBackground(Glass.panel(this, 14));
    search.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
    search.addTextChangedListener({
      beforeTextChanged: () => {}, onTextChanged: () => {},
      afterTextChanged: (e) => { this.query = e.toString().trim(); this.fillList(); }
    });
    page.addView(search);
    Ui.margins(search, 12, 6, 12, 4);
    this.list = Ui.v(this);
    page.addView(this.list);
    this.fillList();

    const here = Library.phoneBytes(db);
    if (here > 0) {
      const foot = Ui.card(this);
      foot.addView(Ui.muted(this, "Downloaded books in this browser: " + Store.sizeLabel(here)));
      const free = Ui.outlineButton(this, "Free up space", W.WOOD, { onClick: (v) => {
        Ui.confirm(this, "Free up space?", "The downloaded copies are removed from this browser. The books stay in the Library and download again when opened.",
          "Remove copies", { run: () => {
            for (const b of Library.find(db, "")) if (!LibraryService.busy(b.get("id"))) Library.removeFromPhone(db, b);
            this.render();
          } });
      } });
      foot.addView(free);
      Ui.margins(free, 0, 8, 0, 0);
      page.addView(foot);
    }
    this.setPage(page);
  }

  fillList() {
    if (this.list == null) return;
    const db = this.db;
    const W = LibraryActivity;
    this.list.removeAllViews();
    if (this.query !== "") {
      const found = Library.find(db, this.query);
      this.list.addView(Ui.heading(this, found.length + (found.length === 1 ? " book found" : " books found"), W.WOOD));
      if (found.length === 0) this.list.addView(this.emptyNote("No book matches."));
      else this.list.addView(this.grid(found));
      return;
    }
    const all = Library.shelves(db);
    if (all.isEmpty()) {
      this.list.addView(this.emptyNote("The shelves are empty. Tap Add a book to put the first one here."));
      return;
    }
    if (this.shelf != null && all.containsKey(this.shelf)) {
      const back = Ui.chip(this, "‹ All shelves", false, W.WOOD);
      back.setOnClickListener({ onClick: (v) => { this.shelf = null; this.render(); } });
      this.list.addView(back);
      Ui.margins(back, 14, 8, 0, 0);
      this.list.addView(Ui.heading(this, this.shelf + " · " + all.get(this.shelf).length, W.WOOD));
      this.list.addView(this.grid(all.get(this.shelf)));
      return;
    }
    this.shelf = null;
    for (const [name, books] of all) this.list.addView(this.shelfView(name, books));
  }

  plank(hDp) {
    const W = LibraryActivity;
    const v = new View(this);
    const wood = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, [W.WOOD_LIGHT, W.WOOD, W.WOOD_DARK]);
    wood.setCornerRadius(Ui.dp(this, 3));
    v.setBackground(wood);
    v.setElevation(Ui.dp(this, 3));
    return v;
  }

  /** One wooden shelf: its name, its books standing in a row (scroll sideways), and the plank under them. */
  shelfView(name, books) {
    const box = Ui.v(this);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.setPadding(Ui.dp(this, 16), Ui.dp(this, 14), Ui.dp(this, 16), Ui.dp(this, 4));
    const t = Ui.tv(this, name, 16, Ui.TEXT, true);
    top.addView(t, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
    const all = Ui.tv(this, books.length + (books.length === 1 ? " book  ›" : " books  ›"), 13, LibraryActivity.WOOD, true);
    all.setPadding(Ui.dp(this, 8), Ui.dp(this, 4), 0, Ui.dp(this, 4));
    all.setOnClickListener({ onClick: (v) => { this.shelf = name; this.render(); } });
    top.addView(all);
    box.addView(top);
    const row = Ui.h(this);
    row.setGravity(Gravity.BOTTOM);
    row.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), 0);
    for (const b of books) {
      const bv = this.bookView(b);
      row.addView(bv, new LinearLayout.LayoutParams(Ui.dp(this, 108), ViewGroup.LayoutParams.WRAP_CONTENT));
      Ui.margins(bv, 6, 0, 6, 0);
    }
    box.addView(Ui.hscroll(this, row));
    const plank = this.plank();
    box.addView(plank, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, Ui.dp(this, 12)));
    Ui.margins(plank, 10, 2, 10, 4);
    return box;
  }

  /** Books three to a row (a shelf opened in full, or search results). */
  grid(books) {
    const g = Ui.v(this);
    g.setPadding(Ui.dp(this, 8), Ui.dp(this, 4), Ui.dp(this, 8), 0);
    let row = null;
    for (let i = 0; i < books.length; i++) {
      if (i % 3 === 0) {
        row = Ui.h(this);
        row.setGravity(Gravity.BOTTOM);
        g.addView(row);
      }
      const cell = new FrameLayout(this);
      cell.addView(this.bookView(books[i]), new FrameLayout.LayoutParams(Ui.dp(this, 108), ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.CENTER_HORIZONTAL));
      row.addView(cell, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
      if (i % 3 === 2 || i === books.length - 1) {
        for (let k = i % 3; k < 2; k++) row.addView(new View(this), new LinearLayout.LayoutParams(0, 1, 1));
        const plank = this.plank();
        g.addView(plank, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, Ui.dp(this, 10)));
        Ui.margins(plank, 2, 2, 2, 14);
      }
    }
    return g;
  }

  /** A book: its front page with a soft shadow, a tick when it is here, the title and author under it. */
  bookView(b) {
    const db = this.db;
    const v = Ui.v(this);
    v.setGravity(Gravity.CENTER_HORIZONTAL);
    const cover = new FrameLayout(this);
    const img = new ImageView(this);
    img.setScaleType(ImageView.ScaleType.CENTER_CROP);
    let bm = null;
    const rel = Ui.nz(b.get("cover"));
    if (rel !== "" && db.file(rel).exists()) bm = Ui.loadScaled(db.file(rel), 360);
    if (bm == null) bm = Library.plainCover(this, b.get("title"), b.get("author"), 240, 340);
    img.setImageBitmap(bm);
    cover.addView(img, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
    cover.setBackground(Ui.round(this, 0xFFFFFFFF, 4));
    cover.setClipToOutline(true);
    cover.setElevation(Ui.dp(this, 6));
    const id = b.get("id");
    if (LibraryService.busy(id)) {
      const p = Ui.tv(this, "Downloading…", 12, 0xFFFFFFFF, true);
      p.setGravity(Gravity.CENTER);
      p.setBackgroundColor(0x99000000);
      cover.addView(p, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, Ui.dp(this, 30), Gravity.BOTTOM));
    } else if (Library.onPhone(db, b)) {
      const ok = Ui.tv(this, "✓", 12, 0xFFFFFFFF, true);
      ok.setGravity(Gravity.CENTER);
      ok.setBackground(Ui.round(this, Ui.GREEN, 11));
      const lp = new FrameLayout.LayoutParams(Ui.dp(this, 22), Ui.dp(this, 22), Gravity.TOP | Gravity.END);
      lp.setMargins(0, Ui.dp(this, 5), Ui.dp(this, 5), 0);
      cover.addView(ok, lp);
    }
    v.addView(cover, new LinearLayout.LayoutParams(Ui.dp(this, 100), Ui.dp(this, 142)));
    Ui.margins(cover, 0, 6, 0, 0);
    const t = Ui.tv(this, b.get("title"), 12, Ui.TEXT, true);
    t.setMaxLines(2);
    t.setEllipsize(TextUtils.TruncateAt.END);
    t.setGravity(Gravity.CENTER_HORIZONTAL);
    v.addView(t);
    Ui.margins(t, 0, 8, 0, 0);
    const sub = Ui.nz(b.get("author")) !== "" ? b.get("author") : Library.isDrive(b) ? "Google Drive" : LibraryActivity.sizeOf(b);
    const a = Ui.tv(this, sub, 11, 0xFF78716C, false);
    a.setSingleLine(true);
    a.setEllipsize(TextUtils.TruncateAt.END);
    a.setGravity(Gravity.CENTER_HORIZONTAL);
    v.addView(a);
    v.setPadding(0, 0, 0, Ui.dp(this, 8));
    v.setOnClickListener({ onClick: (x) => { this.open(b); } });
    v.setOnLongClickListener({ onLongClick: (x) => { this.actions(b); return true; } });
    return v;
  }

  static sizeOf(b) {
    const s = Ui.toLong(b.get("size"), 0);
    return s > 0 ? Store.sizeLabel(s) : "PDF";
  }

  // ---------- opening ----------

  /** Opens the book: a Drive book in Google Drive, an uploaded one in the browser's PDF reader (downloading it first). */
  open(b) {
    if (Library.isDrive(b)) {
      this.openDrive(b);
      return;
    }
    if (Library.onPhone(this.db, b)) {
      Store.openWith(this, Library.localRel(b));
      return;
    }
    const id = b.get("id");
    if (LibraryService.busy(id)) {
      LibraryService.openWhenReady = id;
      Ui.toast(this, "Still downloading. It opens when ready.");
      return;
    }
    if (!Cloud.active(this)) {
      Ui.toast(this, "This book is not in this browser");
      return;
    }
    LibraryService.openWhenReady = id;
    LibraryService.start(this, id);
    Ui.toast(this, "Downloading " + b.get("title") + "…");
    this.render();
  }

  openDrive(b) {
    try {
      this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(Library.driveView(Library.driveId(b.get("link"))))));
    } catch (e) {
      Ui.toast(this, "Could not open the link");
    }
  }

  /** Called when a book has downloaded (err null) or failed. */
  downloaded(id, err) {
    const b = Library.book(this.db, id);
    const wanted = String(id) === String(LibraryService.openWhenReady);
    if (wanted) LibraryService.openWhenReady = "";
    this.render();
    if (b == null) return;
    if (err != null) {
      new AlertDialog.Builder(this).setTitle("Could not download").setMessage(b.get("title") + "\n\n" + err).setPositiveButton("OK", null).show();
      return;
    }
    if (wanted) Store.openWith(this, Library.localRel(b));
  }

  actions(b) {
    const db = this.db;
    const labels = [];
    const runs = [];
    const here = Library.onPhone(db, b);
    labels.push(Library.isDrive(b) ? "Open in Google Drive" : "Open in my PDF reader");
    runs.push(() => this.open(b));
    if (here) {
      labels.push("Share the PDF");
      runs.push(() => Store.share(this, Library.localRel(b), b.get("title")));
    }
    if (Library.isDrive(b)) {
      labels.push("Copy the Drive link");
      runs.push(() => {
        try { navigator.clipboard.writeText(b.get("link")); Ui.toast(this, "Link copied"); } catch (e) { Ui.toast(this, b.get("link")); }
      });
    }
    if (here && !LibraryService.busy(b.get("id"))) {
      labels.push("Remove from this browser (" + Store.sizeLabel(db.file(Library.localRel(b)).length()) + ")");
      runs.push(() => { Library.removeFromPhone(db, b); this.render(); });
    }
    if (Library.canEdit(this, b)) {
      labels.push("Edit title, author or shelf");
      runs.push(() => this.edit(b));
      labels.push("Delete for everyone");
      runs.push(() => {
        Ui.confirm(this, "Delete this book?", b.get("title") + " will be removed from the Library for everyone.", "Delete", {
          run: () => { Library.delete(db, b); this.render(); }
        });
      });
    } else if (Conduct.canReport(this, b.get("added_by"))) {
      labels.push("🚩 Report this book");
      runs.push(() => Conduct.report(this, Library.TABLE, b.get("id"), b.get("added_by"), b.get("by_name"), b.get("title"), b.get("cover")));
    }
    const info = (Library.isDrive(b) ? "Google Drive" : "Uploaded") + (Ui.toLong(b.get("size"), 0) > 0 ? " · " + LibraryActivity.sizeOf(b) : "")
      + (Ui.toInt(b.get("pages"), 0) > 0 ? " · " + b.get("pages") + " pages" : "") + "\nShelf: " + Library.shelfOf(b)
      + (Ui.nz(b.get("by_name")) === "" ? "" : "\nAdded by " + b.get("by_name")) + (Ui.nz(b.get("added_on")).length >= 10 ? " on " + Dates.nice(b.get("added_on").substring(0, 10)) : "");
    new AlertDialog.Builder(this).setTitle(b.get("title")).setMessage(info).setItems(labels, (d, i) => runs[i]()).show();
  }

  edit(b) {
    const f = new Form(this);
    f.text("title", "Title *", b.get("title"), Form.PLAIN);
    f.text("author", "Author / edition", b.get("author"), Form.PLAIN);
    f.suggest("shelf", "Shelf", Library.shelfOf(b), Library.shelfNames(this.db));
    if (Library.isDrive(b)) f.text("link", "Google Drive link *", b.get("link"), Form.PLAIN);
    Ui.formDialog(this, "Edit book", f, "Save", { run: () => {
      if (!f.require("title", "Enter the title")) return false;
      if (Library.isDrive(b) && Library.driveId(f.get("link")) === "") {
        Ui.toast(this, "Paste the Google Drive link of the PDF");
        return false;
      }
      const cv = new ContentValues();
      cv.put("title", f.get("title").trim());
      cv.put("author", f.get("author").trim());
      cv.put("shelf", f.get("shelf").trim() === "" ? "Others" : f.get("shelf").trim());
      if (Library.isDrive(b)) cv.put("link", f.get("link").trim());
      this.db.update(Library.TABLE, cv, Long.parseLong(b.get("id")));
      this.render();
      return true;
    } });
  }

  // ---------- adding ----------

  addBook() {
    new AlertDialog.Builder(this).setTitle("Add a book")
      .setItems(["Upload a PDF (up to 45 MB)", "Bigger book: paste its Google Drive link"], (d, i) => {
        if (i === 0) Store.pick(this, ["application/pdf"], LibraryActivity.REQ_PDF);
        else this.driveForm("", "");
      }).show();
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req !== LibraryActivity.REQ_PDF || res !== RESULT_OK || data == null || data.getData() == null) return;
    const uri = data.getData();
    const name = Store.displayName(this, uri);
    const mime = Ui.nz(this.getContentResolver().getType(uri));
    if (!name.toLowerCase().endsWith(".pdf") && mime !== "application/pdf") {
      Ui.toast(this, "Choose a PDF file");
      return;
    }
    const size = uri.bytes ? uri.bytes.length : (uri.file ? uri.file.size : -1);
    if (size > Library.MAX_BYTES) {
      new AlertDialog.Builder(this).setTitle("This PDF is " + Store.sizeLabel(size))
        .setMessage("Books over 45 MB go into the Library as a Google Drive link:\n\n1. Upload the PDF to Google Drive.\n2. Share it as \"Anyone with the link\" and copy the link.\n3. Tap Add with Drive link and paste it.")
        .setPositiveButton("Add with Drive link", (d, i) => { this.driveForm(Library.titleOf(name), ""); })
        .setNegativeButton("Cancel", null).show();
      return;
    }
    if (uri.bytes && !new TextDecoder("latin1").decode(uri.bytes.subarray(0, 1024)).includes("%PDF")) {
      Ui.toast(this, "This file is not a PDF");
      return;
    }
    try {
      const rel = Store.importUri(this, uri, Library.DIR, "b");
      this.details(rel, Library.titleOf(name));
    } catch (e) {
      Ui.toast(this, "Could not read the file: " + e.message);
    }
  }

  /** Title, author and shelf of an uploaded PDF, then it goes on the shelf (and up to the department's storage). */
  details(rel, title) {
    const db = this.db;
    const f = new Form(this);
    f.text("title", "Title *", title, Form.PLAIN);
    f.text("author", "Author / edition", "", Form.PLAIN);
    f.suggest("shelf", "Shelf", this.shelf != null ? this.shelf : "", Library.shelfNames(db));
    Ui.formDialog(this, "Put on the shelf", f, "Add", { run: () => {
      if (!f.require("title", "Enter the title")) return false;
      const id = Library.add(this, db, Library.FILE, f.get("title"), f.get("author"), f.get("shelf"), rel, "", db.file(rel).length(), 0, "");
      if (id < 0) {
        db.file(rel).delete();
        return true;
      }
      Ui.toast(this, Cloud.active(this) ? "Added. It is shared with the department in the background." : "Added");
      this.render();
      return true;
    } });
  }

  /** A bigger book by its Google Drive link (its front page is added by the first phone that opens it). */
  driveForm(title, link) {
    const f = new Form(this);
    f.text("link", "Google Drive link *", link, Form.PLAIN);
    f.text("title", "Title *", title, Form.PLAIN);
    f.text("author", "Author / edition", "", Form.PLAIN);
    f.suggest("shelf", "Shelf", this.shelf != null ? this.shelf : "", Library.shelfNames(this.db));
    Ui.formDialog(this, "Add a book from Google Drive", f, "Add", { run: () => {
      if (Library.driveId(f.get("link")) === "") {
        Ui.toast(this, "Paste the Google Drive link of the PDF (Share › Copy link)");
        return false;
      }
      if (!f.require("title", "Enter the title")) return false;
      const id = Library.add(this, this.db, Library.DRIVE, f.get("title"), f.get("author"), f.get("shelf"), "", f.get("link"), 0, 0, "");
      if (id < 0) return true;
      Ui.toast(this, "Added. Make sure the Drive file is shared as \"Anyone with the link\".");
      this.render();
      return true;
    } });
  }
}
;
/* ---- app/LibraryService.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Library downloads on the website: an uploaded book is fetched from the department's storage into this browser, then the
 * browser's own PDF reader opens it. (A Google Drive book opens in Google Drive instead, so nothing big comes in here.)
 */
class LibraryService {
  /** id -> {bytes done, bytes in all} for downloads running. */
  static progress = new JMap();
  static errors = new JMap();
  /** The Library on screen: it is told when a download finishes. */
  static screen = null;
  static openWhenReady = "";

  static busy(id) {
    return LibraryService.progress.containsKey(String(id));
  }

  static progressOf(id) {
    const p = LibraryService.progress.get(String(id));
    return p == null ? null : [p[0], p[1]];
  }

  static start(c, id) {
    id = String(id);
    LibraryService.errors.remove(id);
    if (LibraryService.busy(id)) return;
    const db = Db.get(c);
    const b = Library.book(db, id);
    LibraryService.progress.put(id, [0, b == null ? 0 : Ui.toLong(b.get("size"), 0)]);
    (async () => {
      let err = null;
      try {
        if (b == null) throw new IOException("This book was removed");
        if (Library.isDrive(b)) throw new IOException("A Google Drive book opens in Google Drive");
        await Sync.fetchFile(c, db, b.get("file"));
      } catch (e) {
        err = (e && e.message) || String(e);
      }
      LibraryService.progress.remove(id);
      if (err != null) LibraryService.errors.put(id, err);
      const a = LibraryService.screen;
      if (a != null && !a.isFinishing() && a.visible) a.downloaded(id, err);
      else if (err != null) Ui.toast(c, "Book not downloaded: " + err);
    })();
  }

  static sizes(done, total) {
    return total > 0 ? Store.sizeLabel(done) + " of " + Store.sizeLabel(total) + " (" + Math.floor(done * 100 / total) + "%)" : Store.sizeLabel(done);
  }

  static looksLikePdf(f) {
    return true;
  }
}
;
/* ---- app/Live.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Instant alerts (9.99), browser side. While the TVMCHMED tab is open it listens on the Supabase Realtime lobby channel
 * (the same one the Android intercom uses): when any phone uploads something that notifies, it sends a bare "sync" signal
 * and this tab syncs at once and shows the notification. After this tab uploads, it sends the signal too. The signal has
 * no patient or message data. A closed browser tab does not listen (the Android app keeps a line open instead).
 */
class Live {
  static EVENT = "sync";
  static LOBBY = "tvm:lobby";
  static NOTIFY = new Set(["chat_messages", "alerts", "crit_alerts", "pgc_msgs", "signoffs", "pg_leaves", "faculty_leaves", "handovers", "issues",
    "memos", "swaps", "doubts", "doubt_answers", "notices", "staff", "harrison", "callover", "opinions", "duty_roster", "dap", "charts", "labs", "kudos", "fame", "mysteries", "code_blues", "teach_points", "patients", "tasks"]);
  static SEND_GAP_MS = 15000;
  static SYNC_GAP_MS = 6000;
  static ws = null;
  static ctx = null;
  static beat = null;
  static ref = 1;
  static lastSend = 0;
  static lastSync = 0;
  static pending = false;
  static backoff = 2000;

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences("live", Context.MODE_PRIVATE);
  }

  static enabled(c) {
    return Live.prefs(c).getBoolean("on", true) && Notify.on(c);
  }

  static possible(c) {
    return Cloud.active(c) && Cloud.url(c).startsWith("https://") && typeof WebSocket !== 'undefined';
  }

  static me(c) {
    let id = Live.prefs(c).getString("me", "");
    if (id === "") {
      id = Math.random().toString(16).slice(2) + Date.now().toString(16);
      Live.prefs(c).edit().putString("me", id).apply();
    }
    return id;
  }

  static start(c) {
    Live.ctx = c.getApplicationContext ? c.getApplicationContext() : c;
    if (Live.ws != null || !Live.enabled(c) || !Live.possible(c)) return;
    Live.open();
  }

  static stop() {
    const w = Live.ws;
    Live.ws = null;
    if (Live.beat) clearInterval(Live.beat);
    Live.beat = null;
    if (w) try { w.onclose = null; w.close(); } catch (e) { /* closed already */ }
  }

  static async open() {
    const c = Live.ctx;
    let token = "";
    try {
      token = await Cloud.tokenA(c);
    } catch (e) {
      return;
    }
    const w = new WebSocket(Realtime.urlFor(Cloud.url(c), Cloud.key(c)));
    Live.ws = w;
    const self = Live.me(c);
    w.onopen = () => {
      Live.backoff = 2000;
      const join = { topic: "realtime:" + Live.LOBBY, event: "phx_join", ref: String(Live.ref++), join_ref: "1",
        payload: { config: { broadcast: { ack: false, self: false }, presence: { key: "" }, postgres_changes: [], private: true }, access_token: token } };
      w.send(JSON.stringify(join));
      Live.beat = setInterval(() => {
        try { w.send(JSON.stringify({ topic: "phoenix", event: "heartbeat", payload: {}, ref: String(Live.ref++) })); } catch (e) { /* reconnects */ }
      }, 25000);
      Live.syncSoon(c);   // catch up on anything sent while the line was down
    };
    w.onmessage = (m) => {
      try {
        const j = JSON.parse(m.data);
        if (j.event === "broadcast" && j.payload && j.payload.event === Live.EVENT && (j.payload.payload || {}).from !== self) Live.syncSoon(c);
      } catch (e) { /* not ours */ }
    };
    w.onclose = () => {
      if (Live.beat) clearInterval(Live.beat);
      Live.beat = null;
      if (Live.ws !== w) return;
      Live.ws = null;
      setTimeout(() => { if (Live.ws == null && Live.enabled(c) && Live.possible(c)) Live.open(); }, Live.backoff);
      Live.backoff = Math.min(60000, Live.backoff * 2);
    };
  }

  static syncSoon(c) {
    const now = Date.now();
    if (now - Live.lastSync < Live.SYNC_GAP_MS) {
      if (Live.pending) return;
      Live.pending = true;
      setTimeout(() => { Live.pending = false; Live.syncSoon(c); }, Live.SYNC_GAP_MS);
      return;
    }
    Live.lastSync = now;
    Sync.now(c, {
      done: (error) => {
        if (error != null) return;
        try {
          Background.check(c);
        } catch (e) {
          // the 15-minute check tries again
        }
      }
    });
  }

  /** After an upload: tells the other phones to sync now (at most every 15 s). */
  static announce(c, tables) {
    let any = false;
    for (const t of tables) if (Live.NOTIFY.has(t)) any = true;
    if (!any || !Live.possible(c)) return;
    const now = Date.now();
    if (now - Live.lastSend < Live.SEND_GAP_MS) return;
    Live.lastSend = now;
    (async () => {
      try {
        const token = await Cloud.tokenA(c);
        const u = Cloud.url(c).replace(/\/$/, "") + "/realtime/v1/api/broadcast";
        await fetch(u, {
          method: "POST",
          headers: { "Content-Type": "application/json", apikey: Cloud.key(c), Authorization: "Bearer " + token },
          body: JSON.stringify({ messages: [{ topic: Live.LOBBY, event: Live.EVENT, payload: { from: Live.me(c) }, private: true }] })
        });
      } catch (e) {
        // the other phones still get it at their next check
      }
    })();
  }
}
;
/* ---- app/LiveCensusActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Live census: every ward of the department on one screen, with the numbers changing as patients are admitted,
 * moved, discharged or die on any phone. Today's movement counts from 7:30 AM (the admission day). A number that
 * just changed pulses and shows its change for two minutes.
 */
class LiveCensusActivity extends Base {
  static COLOR = 0xFF0E7490;
  static REFRESH_MS = 15000;
  static CHANGE_SHOWN_MS = 120000;

  /** The last value seen of each number, and when and by how much it last changed (kept while the app runs). */
  static last = new JMap();
  static delta = new JMap();
  static changedAt = new JMap();

  static TABLE_HEAD = ["Ward", "Now", "Male", "Female", "Admitted", "Moved in", "Moved out", "Discharged", "Died", "Usual"];

  constructor() {
    super();
    this.handler = new Handler(Looper.getMainLooper());
    this.refresher = {
      run: () => {
        Sync.kick(this);
        this.render();
        this.handler.postDelayed(this.refresher, LiveCensusActivity.REFRESH_MS);
      }
    };
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Live census");
    this.headerColor(LiveCensusActivity.COLOR);
  }

  onResume() {
    super.onResume();
    this.handler.removeCallbacks(this.refresher);
    this.handler.postDelayed(this.refresher, LiveCensusActivity.REFRESH_MS);
  }

  onPause() {
    super.onPause();
    this.handler.removeCallbacks(this.refresher);
  }

  /** The admission day's start (7:30 AM) as a condition on events.date / events.time. */
  static since(day) {
    return "(date>'" + day + "' OR (date='" + day + "' AND IFNULL(time,'')>='07:30'))";
  }

  n(sql, ...args) {
    if (args.length === 1 && Array.isArray(args[0])) args = args[0];
    return this.db.num(sql, ...args);
  }

  /** Records a number and returns its change since it was last different (0 when unchanged for 2 minutes). */
  track(key, value) {
    const L = LiveCensusActivity;
    const now = System.currentTimeMillis();
    const old = L.last.get(key);
    if (old != null && old !== value) {
      L.delta.put(key, value - old);
      L.changedAt.put(key, now);
    }
    L.last.put(key, value);
    const at = L.changedAt.get(key);
    return at != null && now - at < L.CHANGE_SHOWN_MS ? L.delta.get(key) : 0;
  }

  render() {
    const day = Dates.admitDay().toString();
    const sinceSql = LiveCensusActivity.since(day);
    this.subtitle = "All wards at once  ·  updated " + Dates.time().toString().substring(0, 5);
    const page = Ui.v(this);

    // ---- hero: the whole department ----
    const total = this.db.totalInpatients();
    const male = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location<>'KDP' AND sex='M'");
    const female = total - male;
    const vent = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND vent='1'");
    const adm = this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND " + sinceSql);
    const trf = this.n("SELECT COUNT(*) FROM events WHERE type='TRANSFER' AND " + sinceSql);
    const dis = this.n("SELECT COUNT(*) FROM events WHERE type='DISCHARGE' AND " + sinceSql);
    const died = this.n("SELECT COUNT(*) FROM events WHERE type='DEATH' AND " + sinceSql);

    const hero = Ui.v(this);
    hero.setBackground(Glass.hero(this, Ui.HERO, 24));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(this.liveDot());
    const live = Ui.tv(this, "  LIVE", 12, Color.WHITE, true);
    live.setLetterSpacing(0.15);
    top.addView(live);
    const sp = new View(this);
    top.addView(sp, new LinearLayoutParams(0, 1, 1));
    const au = this.db.admittingUnits(Dates.dow(Dates.admitDay()));
    const today = Ui.tv(this, "Admitting today: " + (au.isEmpty() ? "-" : TextUtils.join(", ", au)), 12, Color.WHITE, true);
    today.setBackground(Ui.round(this, 0x33FFFFFF, 14));
    today.setPadding(Ui.dp(this, 10), Ui.dp(this, 3), Ui.dp(this, 10), Ui.dp(this, 3));
    top.addView(today);
    hero.addView(top);

    const big = Ui.h(this);
    big.setGravity(Gravity.BOTTOM);
    const tn = Ui.tv(this, String(total), 54, Color.WHITE, true);
    big.addView(tn);
    const tl = Ui.v(this);
    tl.setPadding(Ui.dp(this, 12), 0, 0, Ui.dp(this, 12));
    tl.addView(Ui.tv(this, "inpatients now", 15, Color.WHITE, true));
    tl.addView(Ui.tv(this, "at TVMCH, all medicine wards", 12, 0xCCFFFFFF, false));
    big.addView(tl, Ui.weight(1));
    const dt = this.track("total", total);
    if (dt !== 0) {
      big.addView(this.changeBadge(dt, true));
      LiveCensusActivity.pulse(tn);
    }
    hero.addView(big);
    hero.addView(this.sexBar(male, female, true));
    const mf = Ui.h(this);
    mf.addView(Ui.tv(this, "♂ Male " + male, 12, Color.WHITE, true), Ui.weight(1));
    const fv = Ui.tv(this, "Female " + female + " ♀", 12, Color.WHITE, true);
    fv.setGravity(Gravity.END);
    mf.addView(fv, Ui.weight(1));
    hero.addView(mf);

    // today's movement, on frosted chips
    const moves = Ui.h(this);
    moves.addView(this.heroStat("adm", adm, "Admitted"), Ui.weight(1));
    moves.addView(this.heroStat("trf", trf, "Moved"), Ui.weight(1));
    moves.addView(this.heroStat("dis", dis, "Discharged"), Ui.weight(1));
    moves.addView(this.heroStat("died", died, "Died"), Ui.weight(1));
    moves.addView(this.heroStat("vent", vent, "Ventilator"), Ui.weight(1));
    hero.addView(moves);
    Ui.margins(moves, 0, 12, 0, 0);
    hero.addView(Ui.tv(this, "Movement since 7:30 AM  ·  refreshes by itself every 15 seconds", 11, 0xB3FFFFFF, false));
    const hp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    hp.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 4));
    page.addView(hero, hp);
    const tv = Ui.v(this);
    tv.setPadding(Ui.dp(this, 12), Ui.dp(this, 2), Ui.dp(this, 12), 0);
    tv.addView(Ui.outlineButton(this, "📺  Show on the duty room TV (wall screen)", LiveCensusActivity.COLOR, this.opener(WallActivity)));
    page.addView(tv);

    // ---- the census table: every ward, every number ----
    page.addView(Ui.heading(this, "Census table  ·  all wards now", LiveCensusActivity.COLOR));
    page.addView(this.table(sinceSql));

    // ---- where everyone is: one bar, a segment per ward ----
    page.addView(Ui.heading(this, "Where the patients are", LiveCensusActivity.COLOR));
    const sc = Ui.card(this);
    const wards = ArrayList(Db.CENSUS_WARDS);
    const counts = new Array(wards.size()).fill(0);
    const colors = new Array(wards.size()).fill(0);
    for (let i = 0; i < wards.size(); i++) {
      counts[i] = this.db.census(wards.get(i), null);
      colors[i] = Ui.unitColor(wards.get(i));
    }
    sc.addView(new LiveCensusActivity.ShareBar(this, counts, colors), Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 22)));
    const legend = new LiveCensusActivity.FlowRow(this);
    for (let i = 0; i < wards.size(); i++) {
      if (counts[i] === 0) continue;
      legend.addView(this.legendItem(Db.shortName(wards.get(i)) + " " + counts[i], colors[i]));
    }
    sc.addView(legend);
    Ui.margins(legend, 0, 8, 0, 0);
    page.addView(sc);

    // ---- the wards ----
    page.addView(Ui.heading(this, "Medical units  ·  " + this.sum(Db.WARD_UNITS) + " in their own wards", Ui.PRIMARY));
    page.addView(this.grid(Db.WARD_UNITS, sinceSql));
    const special = [];
    for (const w of Db.CENSUS_WARDS) if (!Db.isWardUnit(w)) special.add(w);
    const sp2 = special;
    page.addView(Ui.heading(this, "Special wards  ·  " + this.sum(sp2) + " inpatients", Ui.RED));
    page.addView(this.grid(sp2, sinceSql));

    // ---- each unit's responsibility, wherever its patients are ----
    page.addView(Ui.heading(this, "Each unit's patients, wherever they are", Ui.PURPLE));
    page.addView(this.unitTable());

    // ---- Kandiyaperi ----
    page.addView(Ui.heading(this, "Peripheral hospital", Ui.unitColor(Db.KDP)));
    page.addView(this.grid([Db.KDP], sinceSql));
    this.setPage(page);
  }

  /** One row per ward (units, special wards, Kandiyaperi) and a total row; today's columns count from 7:30 AM. */
  table(sinceSql) {
    const TABLE_HEAD = LiveCensusActivity.TABLE_HEAD;
    const card = Ui.card(this);
    card.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    const t = new TableLayout(this);
    t.addView(this.tableRow(TABLE_HEAD, LiveCensusActivity.COLOR, true, 0));
    const wards = ArrayList(Db.CENSUS_WARDS);
    wards.add(Db.KDP);
    const tot = new Array(TABLE_HEAD.length - 1).fill(0);
    let i = 0;
    for (const w of wards) {
      const unit = Db.isWardUnit(w);
      const v = [
          this.db.census(w, null), this.db.census(w, "M"), this.db.census(w, "F"),
          unit ? this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND from_loc=? AND " + sinceSql, w)
              : this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND to_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='TRANSFER' AND to_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='TRANSFER' AND from_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='DISCHARGE' AND from_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='DEATH' AND from_loc=? AND " + sinceSql, w),
          Db.CCB.equals(w) ? 12 : Db.IMCU.equals(w) ? Db.TOX_BEDS + Db.NONTOX_BEDS : this.db.capacity(w)];
      const cells = new Array(TABLE_HEAD.length).fill(null);
      cells[0] = unit ? w + " unit" : Db.shortName(w);
      for (let k = 0; k < v.length; k++) {
        cells[k + 1] = String(v[k]);
        if (!Db.KDP.equals(w)) tot[k] += v[k];
      }
      const row = this.tableRow(cells, Ui.unitColor(w), false, i++);
      row.setOnClickListener(Db.KDP.equals(w) ? this.opener(KdpActivity) : this.opener(UnitActivity, "code", w));
      t.addView(row);
    }
    // the department's admissions are each counted once, under the admitting unit
    tot[3] = this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND IFNULL(to_loc,'')<>'KDP' AND " + sinceSql);
    const cells = new Array(TABLE_HEAD.length).fill(null);
    cells[0] = "TVMCH total";
    for (let k = 0; k < tot.length; k++) cells[k + 1] = String(tot[k]);
    t.addView(this.tableRow(cells, Ui.PRIMARY, true, 0));
    card.addView(Ui.hscroll(this, t));
    card.addView(this.pad(Ui.muted(this, "Admitted: by the unit for M1 to M7, into the ward for special wards; the total counts each admission once. Moved in / out, discharged and died: since 7:30 AM. Tap a row to open the ward. Kandiyaperi is left out of the TVMCH total.")));
    return card;
  }

  pad(v) {
    v.setPadding(Ui.dp(this, 14), Ui.dp(this, 6), Ui.dp(this, 14), 0);
    return v;
  }

  tableRow(cells, color, head, index) {
    const row = new TableRow(this);
    row.setBackgroundColor(head ? Ui.mix(color, Color.WHITE, 0.88) : index % 2 === 1 ? 0xFFF8FAFC : Color.WHITE);
    for (let k = 0; k < cells.length; k++) {
      let c;
      if (k === 0 && !head) {
        c = Ui.tv(this, cells[k], 13, Color.WHITE, true);
        c.setBackground(Ui.round(this, color, 10));
        c.setPadding(Ui.dp(this, 8), Ui.dp(this, 3), Ui.dp(this, 8), Ui.dp(this, 3));
      } else {
        const zero = !head && "0".equals(cells[k]);
        const col = head ? Ui.mix(color, Color.BLACK, 0.35) : zero ? 0xFFCBD5E1
            : k === 1 ? Ui.TEXT : k === 4 || k === 5 ? Ui.ORANGE : k === 7 ? Ui.GREEN : k === 8 ? Ui.RED : Ui.SLATE;
        c = Ui.tv(this, cells[k], k === 1 && !head ? 15 : 13, col, head || k === 1);
        c.setGravity(k === 0 ? Gravity.START : Gravity.CENTER);
        c.setPadding(Ui.dp(this, 8), Ui.dp(this, 7), Ui.dp(this, 8), Ui.dp(this, 7));
      }
      const lp = new TableRow.LayoutParams(WRAP_CONTENT, WRAP_CONTENT);
      lp.gravity = Gravity.CENTER_VERTICAL;
      lp.setMargins(k === 0 ? Ui.dp(this, 10) : 0, Ui.dp(this, 2), 0, Ui.dp(this, 2));
      row.addView(c, lp);
    }
    return row;
  }

  sum(wards) {
    let s = 0;
    for (const w of wards) s += this.db.census(w, null);
    return s;
  }

  // ---------- pieces ----------

  liveDot() {
    const dot = new View(this);
    dot.setBackground(Ui.round(this, 0xFF4ADE80, 6));
    dot.setLayoutParams(Ui.lp(Ui.dp(this, 10), Ui.dp(this, 10)));
    const a = new AlphaAnimation(1, 0.25);
    a.setDuration(800);
    a.setRepeatMode(Animation.REVERSE);
    a.setRepeatCount(Animation.INFINITE);
    dot.startAnimation(a);
    return dot;
  }

  static pulse(v) {
    const s = new ScaleAnimation(1, 1.18, 1, 1.18, Animation.RELATIVE_TO_SELF, 0.5, Animation.RELATIVE_TO_SELF, 0.5);
    s.setDuration(450);
    s.setRepeatMode(Animation.REVERSE);
    s.setRepeatCount(3);
    v.startAnimation(s);
  }

  /** ▲2 / ▼1: how a number just changed. */
  changeBadge(d, onDark) {
    const t = Ui.tv(this, (d > 0 ? "▲" : "▼") + Math.abs(d), 12, onDark ? Ui.TEXT : Color.WHITE, true);
    t.setBackground(Ui.round(this, onDark ? Color.WHITE : (d > 0 ? Ui.ORANGE : Ui.GREEN), 10));
    t.setPadding(Ui.dp(this, 7), Ui.dp(this, 1), Ui.dp(this, 7), Ui.dp(this, 1));
    return t;
  }

  heroStat(key, value, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    l.setBackground(Glass.frost(this, 14));
    l.setPadding(Ui.dp(this, 2), Ui.dp(this, 6), Ui.dp(this, 2), Ui.dp(this, 6));
    const nv = Ui.tv(this, String(value), 20, Color.WHITE, true);
    nv.setGravity(Gravity.CENTER);
    l.addView(nv);
    const lv = Ui.tv(this, label, 10, 0xD9FFFFFF, false);
    lv.setGravity(Gravity.CENTER);
    lv.setSingleLine(true);
    l.addView(lv);
    if (this.track(key, value) !== 0) LiveCensusActivity.pulse(nv);
    const wrap = Ui.v(this);
    wrap.setPadding(Ui.dp(this, 3), 0, Ui.dp(this, 3), 0);
    wrap.addView(l);
    return wrap;
  }

  /** Blue / pink proportion bar of male and female patients. */
  sexBar(m, f, onDark) {
    const track = Ui.h(this);
    track.setBackground(Ui.round(this, onDark ? 0x33FFFFFF : Ui.LINE, 5));
    const all = m + f;
    const a = new View(this), b = new View(this);
    a.setBackground(Ui.round(this, 0xFF60A5FA, 5));
    b.setBackground(Ui.round(this, 0xFFF472B6, 5));
    if (all > 0) {
      track.addView(a, new LinearLayout.LayoutParams(0, Ui.dp(this, 8), m));
      track.addView(b, new LinearLayout.LayoutParams(0, Ui.dp(this, 8), f));
    } else {
      track.addView(new View(this), new LinearLayout.LayoutParams(0, Ui.dp(this, 8), 1));
    }
    const p = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 8));
    p.setMargins(0, Ui.dp(this, 6), 0, Ui.dp(this, 4));
    track.setLayoutParams(p);
    return track;
  }

  legendItem(s, color) {
    const l = Ui.h(this);
    l.setGravity(Gravity.CENTER_VERTICAL);
    const sw = new View(this);
    sw.setBackground(Ui.round(this, color, 3));
    l.addView(sw, Ui.lp(Ui.dp(this, 10), Ui.dp(this, 10)));
    const t = Ui.tv(this, " " + s, 12, Ui.TEXT, false);
    l.addView(t);
    l.setPadding(0, Ui.dp(this, 2), Ui.dp(this, 12), Ui.dp(this, 2));
    return l;
  }

  grid(wards, sinceSql) {
    const g = Ui.v(this);
    g.setPadding(Ui.dp(this, 7), 0, Ui.dp(this, 7), 0);
    let row = null;
    for (let i = 0; i < wards.length; i++) {
      if (i % 2 === 0) {
        row = Ui.h(this);
        row.setGravity(Gravity.TOP);
        g.addView(row);
      }
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5));
      row.addView(this.wardCard(wards[i], sinceSql), p);
    }
    if (wards.length % 2 === 1) {
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5));
      row.addView(new View(this), p);
    }
    return g;
  }

  /** Green under 85 % of the usual load, amber to 100 %, red above. */
  static loadColor(value, cap) {
    if (cap <= 0) return Ui.TEAL;
    const f = value / cap;
    return f < 0.85 ? Ui.GREEN : f <= 1 ? Ui.AMBER : Ui.RED;
  }

  wardCard(code, sinceSql) {
    const color = Ui.unitColor(code);
    const unit = Db.isWardUnit(code);
    const total = this.db.census(code, null), m = this.db.census(code, "M"), f = this.db.census(code, "F");
    const cap = Db.CCB.equals(code) ? 12 : Db.IMCU.equals(code) ? Db.TOX_BEDS + Db.NONTOX_BEDS : this.db.capacity(code);
    const inN = unit ? this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND from_loc=? AND " + sinceSql, code)
        : this.n("SELECT COUNT(*) FROM events WHERE type IN ('ADMIT','TRANSFER') AND to_loc=? AND " + sinceSql, code);
    const out = this.n("SELECT COUNT(*) FROM events WHERE type IN ('TRANSFER','DISCHARGE','DEATH') AND from_loc=? AND " + sinceSql, code);

    const card = Ui.v(this);
    card.setBackground(Ui.round(this, Color.WHITE, 20));
    card.setElevation(Ui.dp(this, 2));
    // coloured band with the ward's name
    const band = Ui.h(this);
    band.setGravity(Gravity.CENTER_VERTICAL);
    band.setBackground(Ui.gradient(this, Ui.shades(color), 20));
    band.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 8));
    const name = Ui.tv(this, unit ? code + " unit" : Db.shortName(code), 14, Color.WHITE, true);
    name.setSingleLine(true);
    band.addView(name, Ui.weight(1));
    const d = this.track("w:" + code, total);
    if (d !== 0) band.addView(this.changeBadge(d, true));
    card.addView(band);

    const body = Ui.v(this);
    body.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 12));
    const r = Ui.h(this);
    r.setGravity(Gravity.CENTER_VERTICAL);
    const ring = new LiveCensusActivity.Ring(this, total, cap, LiveCensusActivity.loadColor(total, cap));
    r.addView(ring, Ui.lp(Ui.dp(this, 70), Ui.dp(this, 70)));
    if (d !== 0) LiveCensusActivity.pulse(ring);
    const side = Ui.v(this);
    side.setPadding(Ui.dp(this, 10), 0, 0, 0);
    side.addView(Ui.tv(this, "♂ " + m + "   ♀ " + f, 13, Ui.TEXT, true));
    side.addView(Ui.tv(this, cap > 0 ? (Db.CCB.equals(code) || Db.IMCU.equals(code) ? Math.max(0, cap - total) + " beds free" : "usual ~" + cap) : "", 11, Ui.MUTED, false));
    const io = Ui.h(this);
    io.addView(Ui.softPill(this, "+" + inN, Ui.ORANGE));
    const o = Ui.softPill(this, "−" + out, Ui.GREEN);
    io.addView(o);
    Ui.margins(o, 6, 0, 0, 0);
    side.addView(io);
    Ui.margins(io, 0, 4, 0, 0);
    r.addView(side, Ui.weight(1));
    body.addView(r);
    body.addView(this.sexBar(m, f, false));

    // the extra line each ward needs
    let extra;
    let ec = Ui.MUTED;
    if (unit) {
      const away = this.db.awayFrom(code);
      extra = away > 0 ? away + " more in special wards" : "Admits " + Dates.DAYS[Ui.toInt(this.db.unit(code).get("admit_day"), 0)];
      if (away > 0) ec = Ui.RED;
    } else if (Db.IMCU.equals(code)) {
      const v = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location='IMCU' AND vent='1'");
      extra = v + " on ventilator";
      if (v > 0) ec = Ui.RED;
    } else if (Db.FEVER.equals(code)) {
      const dg = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location='FEVER' AND dengue='1'");
      extra = dg + " dengue positive";
    } else if (Db.KDP.equals(code)) {
      extra = "Kandiyaperi OP & IP";
    } else {
      extra = "Under the admitting units";
    }
    const tasks = Tasks.inWard(this.db, code);
    if (tasks > 0) {
      extra += "  ·  ⏳ " + tasks;
    }
    body.addView(Ui.tv(this, extra, 11, ec, (ec | 0) !== (Ui.MUTED | 0)));
    card.addView(body);
    Ui.ripple(card, Ui.alpha(color, 0x22));
    card.setOnClickListener(Db.KDP.equals(code) ? this.opener(KdpActivity) : this.opener(UnitActivity, "code", code));
    return card;
  }

  /** M1..M7: own ward plus each special ward, as one stacked bar per unit. */
  unitTable() {
    const card = Ui.card(this);
    const locs = ArrayList(Db.CENSUS_WARDS);
    for (const u of Db.WARD_UNITS) {
      const cs = [];
      const cols = [];
      let all = 0;
      // own ward first, then the special wards holding its patients
      const own = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location=?", u);
      cs.add(own);
      cols.add(Ui.unitColor(u));
      all += own;
      for (const w of locs) {
        if (Db.isWardUnit(w)) continue;
        const c = this.db.awayFrom(u, w);
        if (c === 0) continue;
        cs.add(c);
        cols.add(Ui.unitColor(w));
        all += c;
      }
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
      const name = Ui.pill(this, u, Ui.unitColor(u));
      row.addView(name, Ui.lp(Ui.dp(this, 46), LinearLayout.LayoutParams.WRAP_CONTENT));
      const a = new Array(cs.size()).fill(0), b = new Array(cols.size()).fill(0);
      for (let i = 0; i < a.length; i++) { a[i] = cs.get(i); b[i] = cols.get(i); }
      const bp = new LinearLayout.LayoutParams(0, Ui.dp(this, 16), 1);
      bp.setMargins(Ui.dp(this, 10), 0, Ui.dp(this, 10), 0);
      row.addView(new LiveCensusActivity.ShareBar(this, a, b), bp);
      const tv = Ui.tv(this, String(all), 16, Ui.TEXT, true);
      tv.setGravity(Gravity.END);
      row.addView(tv, Ui.lp(Ui.dp(this, 36), LinearLayout.LayoutParams.WRAP_CONTENT));
      if (this.track("u:" + u, all) !== 0) LiveCensusActivity.pulse(tv);
      row.setOnClickListener(this.opener(UnitActivity, "code", u));
      card.addView(row);
    }
    card.addView(Ui.muted(this, "Each bar: the unit's own ward first, then its patients in triage, step-down, IMCU, CCB, fever, ID and other wards (colours as above)."));
    return card;
  }
}

// ---------- drawn views ----------

/** Occupancy ring: the arc fills with the census against the usual load; the number sits in the middle. */
LiveCensusActivity.Ring = class extends View {
  constructor(c, value, cap, color) {
    super(c);
    this.val = value;
    this.capN = cap;
    this.col = color;
    this.paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.rect = new RectF();
  }

  onDraw(cv) {
    const p = this.paint, r = this.rect, value = this.val, cap = this.capN, color = this.col;
    const w = this.getWidth(), h = this.getHeight(), s = Math.min(w, h), stroke = s * 0.11;
    r.set((w - s) / 2 + stroke, (h - s) / 2 + stroke, (w + s) / 2 - stroke, (h + s) / 2 - stroke);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(stroke);
    p.setStrokeCap(Paint.Cap.ROUND);
    p.setColor(Ui.mix(color, Color.WHITE, 0.82));
    cv.drawArc(r, 0, 360, false, p);
    const frac = cap > 0 ? Math.min(1, value / cap) : value > 0 ? 1 : 0;
    p.setColor(color);
    if (frac > 0) cv.drawArc(r, -90, Math.max(4, 360 * frac), false, p);
    p.setStyle(Paint.Style.FILL);
    p.setColor(Ui.TEXT);
    p.setTypeface(Typeface.DEFAULT_BOLD);
    p.setTextAlign(Paint.Align.CENTER);
    p.setTextSize(s * (value >= 100 ? 0.26 : 0.32));
    cv.drawText(String(value), w / 2, h / 2 + p.getTextSize() * 0.22, p);
    if (cap > 0) {
      p.setTypeface(Typeface.DEFAULT);
      p.setColor(Ui.MUTED);
      p.setTextSize(s * 0.13);
      cv.drawText(Math.round(100 * value / cap) + "%", w / 2, h / 2 + s * 0.24, p);
    }
  }
};

/** A rounded bar split into coloured segments in proportion to the counts. */
LiveCensusActivity.ShareBar = class extends View {
  constructor(c, counts, colors) {
    super(c);
    this.cnts = counts;
    this.cols = colors;
    this.paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.rect = new RectF();
  }

  onDraw(cv) {
    const p = this.paint, r = this.rect, counts = this.cnts, colors = this.cols;
    const w = this.getWidth(), h = this.getHeight(), rad = h / 2;
    let all = 0;
    for (const v of counts) all += v;
    p.setColor(Ui.LINE);
    r.set(0, 0, w, h);
    cv.drawRoundRect(r, rad, rad, p);
    if (all === 0) return;
    cv.save();
    const clip = new Path();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    let x = 0;
    const gap = Math.max(1, h * 0.08);
    for (let i = 0; i < counts.length; i++) {
      if (counts[i] === 0) continue;
      const seg = w * counts[i] / all;
      p.setColor(colors[i]);
      cv.drawRect(x, 0, x + seg - (x + seg < w - 1 ? gap : 0), h, p);
      x += seg;
    }
    cv.restore();
  }
};

/** Lays its children left to right, wrapping to a new line when the row is full (for the legend). */
LiveCensusActivity.FlowRow = class extends FlowLayout {
  constructor(c) {
    super(c, 0, 0);
  }
};
