/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The app lock screen: PIN keypad (and fingerprint where set up). With no PIN yet it asks for a new one twice.
 * Extra "change" = true sets a new PIN from Settings (back allowed); otherwise Back only leaves the app.
 */
class LockActivity extends Base {
  constructor() {
    super();
    this.change = false; this.setting = false;
    this.first = null;
    this.pin = new StringBuilder();
    this.dots = null; this.note = null;
    this.bioAsked = false;
  }

  onCreate(b) {
    super.onCreate(b);
    this.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
    this.change = this.getIntent().getBooleanExtra("change", false);
    this.setTitle("TVMCHMED");
    this.headerColor(Ui.PRIMARY);
  }

  showBack() { return this.change; }

  liveRefresh() { return false; }

  onBackPressed() {
    if (this.change) super.onBackPressed();
    else this.moveTaskToBack(true);
  }

  render() {
    if (!this.change && !Lock.needed(this)) { this.finish(); return; }
    this.setting = this.change || !Lock.hasPin(this);
    this.subtitle = this.setting ? (this.first == null ? "Set an app PIN" : "Enter the PIN again") : "Locked";
    const page = Ui.v(this);
    const c = Ui.card(this);
    c.setBackground(Glass.hero(this, Ui.HERO, 22));
    c.setGravity(Gravity.CENTER_HORIZONTAL);
    const logo = new ImageView(this);
    logo.setImageResource(R.drawable.dept_logo);
    logo.setBackground(Ui.round(this, Color.WHITE, 18));
    logo.setClipToOutline(true);
    c.addView(logo, Ui.lp(Ui.dp(this, 64), Ui.dp(this, 64)));
    const head = this.setting ? (this.first == null ? "Choose a PIN of 4 to 8 digits" : "Type the same PIN again") : "Enter your PIN";
    const h = Ui.tv(this, head, 17, Color.WHITE, true);
    h.setGravity(Gravity.CENTER);
    h.setPadding(0, Ui.dp(this, 10), 0, 0);
    c.addView(h);
    if (this.setting && this.first == null) {
      const w = Ui.tv(this, "If this phone is lost, no one can open the department's records without this PIN. "
        + "It stays on this phone only.", 13, 0xE6FFFFFF, false);
      w.setGravity(Gravity.CENTER);
      c.addView(w);
    }
    this.dots = Ui.tv(this, "", 26, Color.WHITE, true);
    this.dots.setGravity(Gravity.CENTER);
    this.dots.setPadding(0, Ui.dp(this, 12), 0, Ui.dp(this, 4));
    c.addView(this.dots);
    this.note = Ui.tv(this, "", 13, 0xFFFDE68A, true);
    this.note.setGravity(Gravity.CENTER);
    c.addView(this.note);
    page.addView(c);
    page.addView(this.keypad());
    if (!this.setting) {
      const links = Ui.v(this);
      links.setPadding(Ui.dp(this, 16), Ui.dp(this, 6), Ui.dp(this, 16), 0);
      if (Lock.bio(this)) {
        links.addView(Ui.button(this, "Use fingerprint", Ui.TEAL, {
          onClick: (v) => { this.fingerprint(); }
        }));
      }
      const forgot = Ui.tv(this, "Forgot PIN?", 14, Ui.PRIMARY, true);
      forgot.setGravity(Gravity.CENTER);
      forgot.setPadding(0, Ui.dp(this, 14), 0, Ui.dp(this, 6));
      forgot.setOnClickListener({
        onClick: (v) => { this.forgot(); }
      });
      links.addView(forgot);
      page.addView(links);
    }
    page.addView(Copyright.footer(this, Ui.MUTED));
    this.setPage(page);
    this.showDots();
    if (!this.setting && !this.bioAsked && Lock.bio(this)) {
      this.bioAsked = true;
      this.fingerprint();
    }
  }

  keypad() {
    const pad = Ui.v(this);
    pad.setPadding(Ui.dp(this, 28), Ui.dp(this, 10), Ui.dp(this, 28), 0);
    const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "⌫", "0", "OK"];
    for (let r = 0; r < 4; r++) {
      const row = Ui.h(this);
      for (let k = 0; k < 3; k++) {
        const key = keys[r * 3 + k];
        const ok = key.equals("OK");
        const t = Ui.tv(this, key, ok ? 18 : 24, ok ? Color.WHITE : Ui.TEXT, true);
        t.setGravity(Gravity.CENTER);
        t.setBackground(Ui.round(this, ok ? Ui.PRIMARY : 0xF2FFFFFF, 18));
        t.setElevation(Ui.dp(this, 2));
        Ui.ripple(t, 0x331D4E89);
        t.setOnClickListener({
          onClick: (v) => { this.key(key); }
        });
        const lp = new LinearLayout.LayoutParams(0, Ui.dp(this, 60), 1);
        lp.setMargins(Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6));
        row.addView(t, lp);
      }
      pad.addView(row);
    }
    return pad;
  }

  showDots() {
    const s = new StringBuilder();
    for (let i = 0; i < this.pin.length(); i++) s.append("● ");
    if (this.pin.length() == 0) s.append("○ ○ ○ ○");
    this.dots.setText(s.toString().trim());
  }

  key(k) {
    if (k.equals("⌫")) {
      if (this.pin.length() > 0) this.pin.setLength(this.pin.length() - 1);
    } else if (k.equals("OK")) {
      this.submit();
      return;
    } else if (this.pin.length() < Lock.MAX_LEN) {
      this.pin.append(k);
      this.note.setText("");
    }
    this.showDots();
  }

  submit() {
    const p = this.pin.toString();
    this.pin.setLength(0);
    if (this.setting) {
      if (this.first == null) {
        if (!Lock.validPin(p)) { this.warn("Use 4 to 8 digits."); return; }
        this.first = p;
        this.render();
      } else if (!this.first.equals(p)) {
        this.first = null;
        this.render();
        this.warn("The two PINs did not match. Choose again.");
      } else {
        Lock.setPin(this, p);
        Lock.unlock();
        Ui.toast(this, "App PIN set");
        this.offerFingerprint();
      }
      return;
    }
    if (Lock.check(this, p)) { this.done(); return; }
    const left = Lock.triesLeft(this);
    if (left <= 0) {
      this.leave("Too many wrong PINs. Signed out of this phone: sign in again with your email and password, then choose a new PIN.");
      return;
    }
    this.warn("Wrong PIN. " + left + (left == 1 ? " try" : " tries") + " left before this phone is signed out.");
  }

  warn(s) {
    this.showDots();
    this.note.setText(s);
  }

  done() {
    Lock.unlock();
    this.finish();
  }

  /** After a new PIN: fingerprint too, if the phone has one. */
  offerFingerprint() {
    if (!Lock.bioAvailable(this) || Lock.bio(this)) { this.finish(); return; }
    new AlertDialog.Builder(this).setTitle("Use fingerprint too?")
      .setMessage("Open the app with your fingerprint, and use the PIN when it does not work.")
      .setPositiveButton("Yes", {
        onClick: (d, w) => { Lock.setBio(this, true); this.finish(); }
      })
      .setNegativeButton("PIN only", {
        onClick: (d, w) => { this.finish(); }
      })
      .setCancelable(false).show();
  }

  forgot() {
    Ui.confirm(this, "Forgot PIN?", "This phone will be signed out. Sign in again with your email and password, then choose a new PIN. "
      + "Records already shared online are safe.", "Sign out", {
      run: () => { this.leave("Signed out. Sign in again, then choose a new PIN."); }
    });
  }

  leave(msg) {
    Cloud.signOut(this);
    Lock.clear(this);
    Ui.toast(this, msg);
    Cloud.openLogin(this);
    this.finish();
  }

  /** Web: browsers have no fingerprint prompt for pages (Lock.bio is always false there); the PIN is used. */
  fingerprint() {
    if (Build.VERSION.SDK_INT < 28 || !Lock.bio(this)) return;
    this.note.setText("Fingerprint is not available now. Use your PIN.");
  }
}
;
/* ---- app/Logbook.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The PG procedure logbook: what counts, and who signs. */
class Logbook {
  static COLOR = 0xFF4338CA;
  static PENDING = "Pending";
  static SIGNED = "Signed";
  static RETURNED = "Returned";
  static PROCEDURES = ["Central venous line", "Lumbar puncture", "Endotracheal intubation", "Pleural tap", "Intercostal drain",
      "Ascitic tap", "Bone marrow aspiration", "Arterial blood gas", "Arterial line", "Mechanical ventilation", "Non-invasive ventilation",
      "CPR / ACLS", "DC cardioversion / defibrillation", "Temporary pacemaker", "Pericardiocentesis", "Knee joint aspiration",
      "Liver biopsy", "Renal biopsy", "Haemodialysis catheter", "Plasmapheresis (PLEX)", "Ryle's tube", "Urinary catheter",
      "Upper GI endoscopy", "ECHO (bedside)", "USG-guided procedure", "Other"];
  static ROLES = ["Performed under supervision", "Performed independently", "Assisted", "Observed"];

  /** Faculty sign the logbook: the Assistant / Associate Professors, Professors, HOD, Medical Registrar and admin. */
  static canSign(c) {
    return SessionAttendance.canRun(c);
  }

  /** The PG's own staff entry when this phone belongs to a PG, else -1. */
  static myPg(c, db) {
    const id = Cloud.myStaff(c);
    if (id <= 0) return -1;
    const s = db.row("SELECT role FROM staff WHERE id=?", String(id));
    return s != null && ("Postgraduate".equals(s.get("role")) || "CRMI".equals(s.get("role"))) ? id : -1;
  }

  /** Entries waiting for this faculty member's signature: those naming them as supervisor, or any when no one is named. */
  static waitingToSign(c, db) {
    if (!Logbook.canSign(c)) return 0;
    const me = CallDutyActivity.myName(c);
    let n = 0;
    for (const r of db.rows("SELECT supervisor FROM logbook WHERE status=?", Logbook.PENDING)) {
      const sup = Ui.nz(r.get("supervisor"));
      if (sup.isEmpty() || me.isEmpty() || Chat.sameName(sup, me)) n++;
    }
    return n;
  }

  // ---------------------------------------------------------------- competency progress

  /**
   * DEPARTMENT TARGETS (not an NMC or university requirement): the minimum number of SIGNED entries a PG should reach in each year of the MD course,
   * by procedure. The admin or HOD can adjust any of them in the app (stored as settings rows logbook_target_<code> = "year1,year2,year3").
   * Columns: procedure (as in PROCEDURES), year 1, year 2, year 3. A target of 0 means no yearly target.
   */
  static TARGETS = [
      ["Central venous line", 2, 3, 3], ["Lumbar puncture", 2, 3, 3], ["Endotracheal intubation", 3, 4, 4], ["Pleural tap", 3, 3, 3],
      ["Intercostal drain", 1, 2, 2], ["Ascitic tap", 3, 3, 3], ["Bone marrow aspiration", 1, 2, 2], ["Arterial blood gas", 10, 10, 10],
      ["Arterial line", 0, 1, 1], ["Mechanical ventilation", 2, 3, 3], ["Non-invasive ventilation", 3, 4, 4], ["CPR / ACLS", 2, 2, 2],
      ["DC cardioversion / defibrillation", 1, 2, 2], ["Temporary pacemaker", 0, 1, 1], ["Pericardiocentesis", 0, 1, 1], ["Knee joint aspiration", 1, 1, 1],
      ["Liver biopsy", 0, 1, 1], ["Renal biopsy", 0, 1, 1], ["Haemodialysis catheter", 1, 2, 2], ["Plasmapheresis (PLEX)", 0, 1, 1],
      ["Ryle's tube", 5, 5, 5], ["Urinary catheter", 5, 5, 5], ["Upper GI endoscopy", 3, 5, 5], ["ECHO (bedside)", 5, 10, 10], ["USG-guided procedure", 3, 5, 5],
  ];

  /** A short stable code for a procedure: "Pleural tap" → "pleural_tap". */
  static code(procedure) {
    return Ui.nz(procedure).toLowerCase().replaceAllRx("[^a-z0-9]+", "_").replaceAllRx("^_+|_+$", "");
  }

  static targetKey(procedure) { return "logbook_target_" + Logbook.code(procedure); }

  /** The default targets [year1, year2, year3] from the table, or null when the procedure has none. */
  static defaultTargets(procedure) {
    for (const t of Logbook.TARGETS) if (t[0] === procedure) return [t[1], t[2], t[3]];
    return null;
  }

  /** The targets in force: the admin's override from settings when set ("2,3,3"), else the table. Null for a procedure with no target row. */
  static targets(db, procedure) {
    const d = Logbook.defaultTargets(procedure);
    if (d == null) return null;
    const v = db == null ? "" : db.setting(Logbook.targetKey(procedure), "");
    if (v != null && v.trim().matches("\\d{1,3}\\s*,\\s*\\d{1,3}\\s*,\\s*\\d{1,3}")) {
      const p = v.trim().jsplit("\\s*,\\s*");
      return [Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2])];
    }
    return d;
  }

  /** Only the admin and the HOD change department targets (everyone, on a phone not signed in to the cloud). */
  static canEditTargets(c) {
    const r = Cloud.role(c);
    return !Cloud.active(c) || "admin".equals(r) || "hod".equals(r);
  }

  /** The academic year (from 1 July) that today is in. */
  static yearStart(today) {
    return LocalDate.of(today.getMonthValue() >= 7 ? today.getYear() : today.getYear() - 1, 7, 1);
  }

  /** A PG's signed count against the targets. Counts SIGNED entries only; "this year" counts entries dated from 1 July. */
  static progress(db, staffId, year, today, cumulative) {
    const pr = new Logbook.Progress();
    pr.year = Math.max(1, Math.min(3, year));
    pr.cumulative = cumulative;
    const from = cumulative ? "" : Logbook.yearStart(today).toString();
    const signed = new JMap();
    for (const r of db.rows("SELECT procedure AS p, COUNT(*) AS n FROM logbook WHERE staff_id=? AND status=? AND date>=? GROUP BY procedure",
        String(staffId), Logbook.SIGNED, from)) signed.put(Ui.nz(r.get("p")), Ui.toInt(r.get("n"), 0));
    let sum = 0;
    for (const t of Logbook.TARGETS) {
      const proc = t[0];
      const tg = Logbook.targets(db, proc);
      let target = 0;
      for (let y = cumulative ? 1 : pr.year; y <= pr.year; y++) target += tg[y - 1];
      const row = new Logbook.Row();
      row.procedure = proc;
      row.target = target;
      const n = signed.get(proc);
      row.signed = n == null ? 0 : n;
      pr.rows.push(row);
      if (target > 0) {
        sum += Math.min(row.signed, target);
        pr.targetTotal += target;
      }
    }
    pr.signedCounted = sum;
    pr.pct = pr.targetTotal === 0 ? 100 : Math.round(sum * 100 / pr.targetTotal);
    pr.pending = db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status=?", String(staffId), Logbook.PENDING);
    pr.returned = db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status=?", String(staffId), Logbook.RETURNED);
    pr.unsigned = db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status<>?", String(staffId), Logbook.SIGNED);
    const frac = Math.max(0, Math.min(1, ChronoUnit.DAYS.between(Logbook.yearStart(today), today) / 365.0));
    pr.expected = cumulative ? (pr.year - 1 + frac) / pr.year : frac;
    pr.onTrack = pr.pct >= Math.round(pr.expected * 80);   // behind = under 80% of the pace the calendar asks for
    return pr;
  }

  /** Every approved PG with their progress, behind first then lowest percent. */
  static league(db, today, cumulative) {
    const out = [];
    for (const s of db.rows("SELECT id, name, unit, batch FROM staff WHERE role='Postgraduate' AND " + Approvals.APPROVED_SQL + " ORDER BY name")) {
      const r = new Logbook.PgRow();
      r.id = Long.parseLong(s.get("id"));
      r.name = Ui.nz(s.get("name"));
      r.unit = Ui.nz(s.get("unit"));
      r.year = Math.max(1, CaseSheet.pgYear(s.get("batch"), today));
      r.progress = Logbook.progress(db, r.id, r.year, today, cumulative);
      out.push(r);
    }
    out.sort((a, b) => {
      if (a.progress.onTrack !== b.progress.onTrack) return a.progress.onTrack ? 1 : -1;
      return a.progress.pct - b.progress.pct;
    });
    return out;
  }

  /** PDF / Word of one PG's progress, in the same form as the logbook PDF. */
  static progressDoc(db, s, pr) {
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "PG LOGBOOK: COMPETENCY PROGRESS";
    f.footer = s.get("name") + "  •  " + f.dept + ", " + f.college;
    f.fileBase = "LogbookProgress_" + Ui.nz(s.get("name")).replaceAllRx("[^A-Za-z0-9]+", "_");
    const h = f.block(null, 0, 0.4, 0.3, 0.3);
    h.row(16, new FormDoc.Cell("PG: " + s.get("name")).b(), new FormDoc.Cell("Unit: " + Ui.nz(s.get("unit"))).b(), new FormDoc.Cell("PG year: " + pr.year).b());
    h.row(16, new FormDoc.Cell(pr.cumulative ? "Since joining" : "Academic year from " + Logbook.yearStart(LocalDate.now())), new FormDoc.Cell("Overall: " + pr.pct + "%").b(),
        new FormDoc.Cell("Unsigned entries: " + pr.unsigned + " (" + pr.pending + " waiting, " + pr.returned + " returned)"));
    const t = f.block("SIGNED PROCEDURES AGAINST DEPARTMENT TARGETS", FormDoc.NAVY, 0.4, 0.15, 0.15, 0.15, 0.15);
    t.row(14, new FormDoc.Cell("Procedure").b(), new FormDoc.Cell("Signed").b(), new FormDoc.Cell("Target").b(), new FormDoc.Cell("Done").b(), new FormDoc.Cell("Status").b());
    for (const r of pr.rows) {
      if (r.target <= 0 && r.signed === 0) continue;
      t.row(14, new FormDoc.Cell(r.procedure), new FormDoc.Cell(String(r.signed)), new FormDoc.Cell(r.target > 0 ? String(r.target) : "-"),
          new FormDoc.Cell(r.target > 0 ? Math.min(100, idiv(r.signed * 100, r.target)) + "%" : "-"), new FormDoc.Cell(r.target <= 0 ? "" : r.done() ? "Met" : "Short by " + (r.target - r.signed)));
    }
    const n = f.block(null, 0, 1);
    n.row(14, new FormDoc.Cell("Targets are department targets set by the HOD, not a university or NMC requirement. Only entries signed by faculty are counted.").size(9));
    return f;
  }

  /** Home card for the signed-in PG: in the first week of each month when behind the department targets, else null. */
  static homeCard(a, db) {
    const id = Logbook.myPg(a, db);
    if (id <= 0) return null;
    const s = db.row("SELECT * FROM staff WHERE id=?", String(id));
    if (s == null || !"Postgraduate".equals(s.get("role"))) return null;
    const today = LocalDate.now();
    if (today.getDayOfMonth() > 7) return null;
    const pr = Logbook.progress(db, id, Math.max(1, CaseSheet.pgYear(s.get("batch"), today)), today, false);
    if (pr.onTrack) return null;
    const card = a.entryCard("LOGBOOK · MONTHLY CHECK", Logbook.COLOR, "📒 Logbook: " + pr.pct + "% of this year's target",
        "You are behind the department pace" + (pr.unsigned > 0 ? "  ·  " + pr.unsigned + " entries not signed yet" : "") + ". Tap to see which procedures are short.",
        null, a.opener(LogbookActivity, "progress", "1"));
    const g = Ui.round(a, Ui.mix(Logbook.COLOR, Color.WHITE, 0.92), 18);
    g.setStroke(Ui.dp(a, 2), Logbook.COLOR);
    card.setBackground(g);
    return card;
  }
}

Logbook.Row = class {
  constructor() { this.procedure = null; this.signed = 0; this.target = 0; }
  done() { return this.signed >= this.target; }
};

Logbook.Progress = class {
  constructor() {
    this.year = 0;                 // PG year 1..3 used for the targets
    this.cumulative = false;       // targets of years 1..year and all signed entries, instead of this academic year
    this.rows = [];
    this.signedCounted = 0; this.targetTotal = 0; this.pct = 0; this.unsigned = 0; this.pending = 0; this.returned = 0;
    this.expected = 0;             // share of the target a PG should have reached by today, 0..1
    this.onTrack = true;
  }
};

/** One line of the league table. */
Logbook.PgRow = class {
  constructor() { this.id = 0; this.name = null; this.unit = null; this.year = 0; this.progress = null; }
};
;
/* ---- app/LogbookActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * PG logbook: PGs log the procedures they do (central line, LP, intubation, pleural tap…); faculty sign each entry
 * or return it with a remark. Each PG's logbook can be saved as a PDF.
 */
class LogbookActivity extends Base {
  constructor() {
    super();
    this.toSign = false;
    this.pg = -1;
    this.progress = false; this.cumulative = false;
    this.viewPg = -1;      // progress: the PG opened from the league table
    this.fUnit = "";
    this.fYear = 0;
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("PG logbook");
    this.subtitle = "Procedures logged by PGs, signed by faculty";
    this.headerColor(Logbook.COLOR);
    this.pg = Logbook.myPg(this, this.db);
    this.toSign = this.pg <= 0 && Logbook.canSign(this) && Logbook.waitingToSign(this, this.db) > 0;
    this.progress = this.getIntent().getStringExtra("progress") != null;
    if (this.progress) this.toSign = false;
    if (b != null) {
      this.progress = b.getBoolean("progress", this.progress);
      this.cumulative = b.getBoolean("cumulative", false);
      this.viewPg = b.getLong("viewPg", -1);
      this.pg = b.getLong("pg", this.pg);
      this.toSign = b.getBoolean("toSign", this.toSign);
    }
    if (this.pg <= 0) {
      const first = this.db.row("SELECT id FROM staff WHERE role='Postgraduate' AND " + Approvals.APPROVED_SQL + " ORDER BY name LIMIT 1");
      if (first != null) this.pg = Long.parseLong(first.get("id"));
    }
    this.headerAction("+ Log", {
      onClick: (v) => { this.entryDialog(null); }
    });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putLong("pg", this.pg);
    out.putBoolean("toSign", this.toSign);
    out.putBoolean("progress", this.progress);
    out.putBoolean("cumulative", this.cumulative);
    out.putLong("viewPg", this.viewPg);
  }

  render() {
    const page = Ui.v(this);
    const sign = Logbook.canSign(this);
    if (sign || Logbook.myPg(this, this.db) > 0) {
      const tabs = Ui.h(this);
      tabs.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), 0);
      if (sign) {
        const a = Ui.chip(this, "To sign · " + Logbook.waitingToSign(this, this.db), this.toSign && !this.progress, Ui.AMBER);
        a.setOnClickListener({
          onClick: (v) => { this.toSign = true; this.progress = false; this.render(); }
        });
        tabs.addView(a);
      }
      const b = Ui.chip(this, sign ? "PG logbooks" : "My logbook", !this.toSign && !this.progress, Logbook.COLOR);
      b.setOnClickListener({
        onClick: (v) => { this.toSign = false; this.progress = false; this.render(); }
      });
      tabs.addView(b);
      const c = Ui.chip(this, "Progress", this.progress, Ui.GREEN);
      c.setOnClickListener({
        onClick: (v) => { this.progress = true; this.toSign = false; this.render(); }
      });
      tabs.addView(c);
      if (sign) Ui.margins(b, 8, 0, 0, 0);
      page.addView(tabs);
      // 10.17: the monthly work record that fills itself (user's pick 201)
      page.addView(this.entryCard("📄", MyMonth.COLOR, "My month (fills itself)", MyMonth.line(this, this.db), "PDF", {
        onClick: (v) => { MyMonth.offer(this, this.db); }
      }));
    }
    if (this.progress) this.renderProgress(page);
    else if (this.toSign && sign) this.renderToSign(page);
    else this.renderPg(page);
    this.setPage(page);
  }

  renderToSign(page) {
    const db = this.db;
    const me = CallDutyActivity.myName(this);
    let n = 0;
    page.addView(Ui.heading(this, "Waiting for your signature", Ui.AMBER));
    for (const r of db.rows("SELECT * FROM logbook WHERE status=? ORDER BY date, id", Logbook.PENDING)) {
      const sup = Ui.nz(r.get("supervisor"));
      if (!sup.isEmpty() && !me.isEmpty() && !Chat.sameName(sup, me)) continue;
      page.addView(this.entryRow(r, true));
      n++;
    }
    if (n == 0) page.addView(this.emptyNote("Nothing to sign."));
    const others = db.rows("SELECT * FROM logbook WHERE status=? AND supervisor<>'' ORDER BY date, id", Logbook.PENDING);
    let k = 0;
    for (const r of others) if (me.isEmpty() || !Chat.sameName(r.get("supervisor"), me)) k++;
    if (k > 0) page.addView(Ui.muted(this, "      " + k + " more " + (k == 1 ? "entry is" : "entries are") + " waiting for other faculty."));
  }

  renderPg(page) {
    const db = this.db;
    const pg = this.pg;
    const s = pg > 0 ? db.row("SELECT * FROM staff WHERE id=?", String(pg)) : null;
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Logbook.COLOR), 20));
    hero.addView(Ui.tv(this, s == null ? "No PG chosen" : s.get("name"), 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, s == null ? "Add PGs in Students" : Ui.nz(s.get("role")) + (Ui.nz(s.get("unit")).isEmpty() ? "" : " · " + s.get("unit"))
      + (Ui.nz(s.get("batch")).isEmpty() ? "" : " · " + s.get("batch")), 13, 0xD9FFFFFF, false));
    const total = pg > 0 ? db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=?", String(pg)) : 0;
    const signed = pg > 0 ? db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status=?", String(pg), Logbook.SIGNED) : 0;
    const stats = Ui.statRow(this, this.white(String(total), "Logged"), this.white(String(signed), "Signed"),
      this.white(String(pg > 0 ? db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status=?", String(pg), Logbook.PENDING) : 0), "Waiting"));
    hero.addView(stats);
    Ui.margins(stats, 0, 8, 0, 0);
    const btns = Ui.h(this);
    const change = Ui.outlineButton(this, "Choose PG", Logbook.COLOR, {
      onClick: (v) => { this.choosePg(); }
    });
    btns.addView(change, Ui.weight(1));
    if (total > 0) {
      const pdf = Ui.outlineButton(this, "Save as PDF", Logbook.COLOR, {
        onClick: (v) => { this.pdf(); }
      });
      btns.addView(pdf, Ui.weight(1));
      Ui.margins(pdf, 8, 0, 0, 0);
    }
    hero.addView(btns);
    Ui.margins(btns, 0, 10, 0, 0);
    page.addView(hero);
    if (pg <= 0) return;

    // procedures done so far, signed count first
    const count = new JMap();
    for (const r of db.rows("SELECT procedure, status FROM logbook WHERE staff_id=? ORDER BY procedure", String(pg))) {
      let c = count.get(r.get("procedure"));
      if (c == null) { c = [0, 0]; count.put(r.get("procedure"), c); }
      c[0]++;
      if (Logbook.SIGNED.equals(r.get("status"))) c[1]++;
    }
    if (!count.isEmpty()) {
      page.addView(Ui.heading(this, "Procedures  ·  " + count.size() + " kinds", Logbook.COLOR));
      const card = Ui.card(this);
      for (const e of count.entrySet()) {
        const r = Ui.h(this);
        r.setGravity(Gravity.CENTER_VERTICAL);
        r.addView(Ui.tv(this, e.getKey(), 14, Ui.TEXT, false), Ui.weight(1));
        r.addView(Ui.tv(this, e.getValue()[0] + "  (" + e.getValue()[1] + " signed)", 13, e.getValue()[1] == e.getValue()[0] ? Ui.GREEN : Ui.AMBER, true));
        card.addView(r);
        Ui.margins(r, 0, 3, 0, 3);
      }
      page.addView(card);
    }
    const rows = db.rows("SELECT * FROM logbook WHERE staff_id=? ORDER BY date DESC, id DESC", String(pg));
    page.addView(Ui.heading(this, "Entries  ·  " + rows.size(), Logbook.COLOR));
    if (rows.isEmpty()) page.addView(this.emptyNote("No procedures logged yet. Tap + Log."));
    for (const r of rows) page.addView(this.entryRow(r, false));
  }

  // ---------- competency progress ----------

  renderProgress(page) {
    const db = this.db;
    const mine = Logbook.myPg(this, db);
    const sign = Logbook.canSign(this);
    const today = Dates.today();
    const modes = Ui.h(this);
    modes.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    const y = Ui.chip(this, "This academic year", !this.cumulative, Logbook.COLOR);
    y.setOnClickListener({
      onClick: (v) => { this.cumulative = false; this.render(); }
    });
    const all = Ui.chip(this, "Since joining", this.cumulative, Logbook.COLOR);
    all.setOnClickListener({
      onClick: (v) => { this.cumulative = true; this.render(); }
    });
    modes.addView(y);
    modes.addView(all);
    page.addView(modes);
    if (!sign) {
      if (mine <= 0) {
        page.addView(this.emptyNote("Progress is shown to PGs for their own logbook, and to faculty for all PGs."));
        return;
      }
      this.progressDetail(page, mine, false);
      return;
    }
    if (this.viewPg > 0) {
      this.progressDetail(page, this.viewPg, true);
      return;
    }
    // league table with unit and year filters
    const all0 = Logbook.league(db, today, this.cumulative);
    const units = new TreeSet();
    for (const r of all0) if (!r.unit.isEmpty()) units.add(r.unit);
    const f1 = Ui.h(this);
    f1.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    f1.addView(this.unitChip("All units", ""));
    for (const u of units) f1.addView(this.unitChip(Db.shortName(u), u));
    page.addView(Ui.hscroll(this, f1));
    const f2 = Ui.h(this);
    f2.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), 0);
    f2.addView(this.yearChip("All years", 0));
    f2.addView(this.yearChip("1st year", 1));
    f2.addView(this.yearChip("2nd year", 2));
    f2.addView(this.yearChip("3rd year", 3));
    page.addView(f2);
    let behind = 0, ok = 0;
    const shown = [];
    for (const r of all0) {
      if (!this.fUnit.isEmpty() && !this.fUnit.equals(r.unit)) continue;
      if (this.fYear > 0 && this.fYear !== r.year) continue;
      shown.add(r);
      if (r.progress.onTrack) ok++;
      else behind++;
    }
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Logbook.COLOR), 20));
    hero.addView(Ui.tv(this, "PG competency league", 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, "Signed procedures against department targets (set by the HOD). Behind means under 80% of the pace the calendar asks for.", 12, 0xD9FFFFFF, false));
    const st = Ui.statRow(this, this.white(String(behind), "Behind"), this.white(String(ok), "On track"), this.white(String(shown.length), "PGs"));
    hero.addView(st);
    Ui.margins(st, 0, 8, 0, 0);
    if (Logbook.canEditTargets(this)) {
      const t = Ui.outlineButton(this, "Department targets", Color.WHITE, {
        onClick: (v) => { this.targetsDialog(); }
      });
      hero.addView(t);
      Ui.margins(t, 0, 10, 0, 0);
    }
    page.addView(hero);
    if (shown.isEmpty()) page.addView(this.emptyNote("No PGs match. Add PGs in Students."));
    for (const r of shown) {
      const p = r.progress;
      const card = this.entryCard(p.onTrack ? "On track" : "Behind", p.onTrack ? Ui.GREEN : Ui.RED, r.name,
          r.year + (r.year === 1 ? "st" : r.year === 2 ? "nd" : "rd") + " year" + (r.unit.isEmpty() ? "" : "  ·  " + r.unit) + "  ·  " + p.signedCounted + " of " + p.targetTotal
              + " signed" + (p.unsigned > 0 ? "  ·  " + p.unsigned + " unsigned" : ""), p.pct + "%", {
            onClick: (v) => { this.viewPg = r.id; this.render(); }
          });
      card.addView(Ui.bar(this, p.pct, 100, p.onTrack ? Ui.GREEN : Ui.AMBER));
      page.addView(card);
    }
  }

  unitChip(label, unit) {
    const c = Ui.chip(this, label, this.fUnit.equals(unit), Logbook.COLOR);
    c.setOnClickListener({
      onClick: (v) => { this.fUnit = unit; this.render(); }
    });
    return c;
  }

  yearChip(label, year) {
    const c = Ui.chip(this, label, this.fYear === year, Logbook.COLOR);
    c.setOnClickListener({
      onClick: (v) => { this.fYear = year; this.render(); }
    });
    return c;
  }

  progressDetail(page, staffId, fromLeague) {
    const db = this.db;
    const s = db.row("SELECT * FROM staff WHERE id=?", String(staffId));
    if (s == null) {
      page.addView(this.emptyNote("PG not found."));
      return;
    }
    const year = Math.max(1, CaseSheet.pgYear(s.get("batch"), Dates.today()));
    const p = Logbook.progress(db, staffId, year, Dates.today(), this.cumulative);
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Logbook.COLOR), 20));
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(this.ring(p.pct), new LinearLayout.LayoutParams(Ui.dp(this, 84), Ui.dp(this, 84)));
    const who = Ui.v(this);
    who.addView(Ui.tv(this, Ui.nz(s.get("name")), 20, Color.WHITE, true));
    who.addView(Ui.tv(this, "PG year " + p.year + (Ui.nz(s.get("unit")).isEmpty() ? "" : "  ·  " + s.get("unit")) + "  ·  " + (this.cumulative ? "since joining" : "this academic year"), 13, 0xD9FFFFFF, false));
    who.addView(Ui.tv(this, p.onTrack ? "On track" : "Behind the pace for this time of year", 13, Color.WHITE, true));
    top.addView(who, Ui.weight(1));
    Ui.margins(who, 12, 0, 0, 0);
    hero.addView(top);
    const stats = Ui.statRow(this, this.white(p.pct + "%", "Overall"), this.white(String(p.unsigned), "Unsigned entries"),
        this.white(p.pending + " / " + p.returned, "Waiting / returned"));
    hero.addView(stats);
    Ui.margins(stats, 0, 10, 0, 0);
    const btns = Ui.h(this);
    if (fromLeague) {
      btns.addView(Ui.outlineButton(this, "All PGs", Logbook.COLOR, {
        onClick: (v) => { this.viewPg = -1; this.render(); }
      }), Ui.weight(1));
    }
    const pdf = Ui.outlineButton(this, "PDF", Logbook.COLOR, {
      onClick: (v) => { this.progressFile(s, p, true); }
    });
    const word = Ui.outlineButton(this, "Word", Logbook.COLOR, {
      onClick: (v) => { this.progressFile(s, p, false); }
    });
    btns.addView(pdf, Ui.weight(1));
    btns.addView(word, Ui.weight(1));
    Ui.margins(pdf, 8, 0, 0, 0);
    Ui.margins(word, 8, 0, 0, 0);
    hero.addView(btns);
    Ui.margins(btns, 0, 10, 0, 0);
    page.addView(hero);
    page.addView(Ui.heading(this, "Procedures: signed against target", Logbook.COLOR));
    const card = Ui.card(this);
    for (const r of p.rows) {
      if (r.target <= 0 && r.signed === 0) continue;
      const line = Ui.h(this);
      line.setGravity(Gravity.CENTER_VERTICAL);
      line.addView(Ui.tv(this, r.procedure, 14, Ui.TEXT, false), Ui.weight(1));
      line.addView(Ui.tv(this, r.target > 0 ? r.signed + " / " + r.target : r.signed + " signed", 13, r.target <= 0 || r.done() ? Ui.GREEN : Ui.AMBER, true));
      card.addView(line);
      if (r.target > 0) card.addView(Ui.bar(this, r.signed, r.target, r.done() ? Ui.GREEN : Logbook.COLOR));
      else Ui.margins(line, 0, 3, 0, 3);
    }
    page.addView(card);
    const note = Ui.muted(this, "Targets are department targets (the HOD can change them), not a university or NMC requirement. Only entries signed by faculty are counted.");
    note.setTextSize(12);
    page.addView(note);
    Ui.margins(note, 18, 4, 18, 12);
    if (Logbook.canEditTargets(this)) {
      const t = Ui.outlineButton(this, "Department targets", Logbook.COLOR, {
        onClick: (v) => { this.targetsDialog(); }
      });
      page.addView(t);
      Ui.margins(t, 12, 0, 12, 12);
    }
  }

  /** A ring showing a percentage. */
  ring(pct) {
    return new LogbookActivity.Ring(this, pct);
  }

  /** Admin / HOD: pick a procedure and change its yearly targets. */
  targetsDialog() {
    if (!Logbook.canEditTargets(this)) return;
    const n = Logbook.TARGETS.length;
    const names = new Array(n).fill(null);
    for (let i = 0; i < n; i++) {
      const t = Logbook.targets(this.db, Logbook.TARGETS[i][0]);
      names[i] = Logbook.TARGETS[i][0] + "   (" + t[0] + " / " + t[1] + " / " + t[2] + ")";
    }
    new AlertDialog.Builder(this).setTitle("Yearly targets: year 1 / 2 / 3").setItems(names, {
      onClick: (d, w) => { this.targetForm(Logbook.TARGETS[w][0]); }
    }).setNegativeButton("Close", null).show();
  }

  targetForm(proc) {
    const cur = Logbook.targets(this.db, proc), def = Logbook.defaultTargets(proc);
    const f = new Form(this);
    f.view.addView(Ui.muted(this, "Minimum signed entries per year of the MD course. Department targets: 0 means no target. Default: " + def[0] + " / " + def[1] + " / " + def[2] + "."));
    f.text("y1", "1st year", String(cur[0]), Form.NUMBER);
    f.text("y2", "2nd year", String(cur[1]), Form.NUMBER);
    f.text("y3", "3rd year", String(cur[2]), Form.NUMBER);
    Ui.formDialog(this, proc, f, "Save", {
      run: () => {
        const a = Ui.toInt(f.get("y1").trim(), -1), b = Ui.toInt(f.get("y2").trim(), -1), c = Ui.toInt(f.get("y3").trim(), -1);
        if (a < 0 || b < 0 || c < 0 || a > 999 || b > 999 || c > 999) {
          Ui.toast(this, "Enter whole numbers from 0 to 999");
          return false;
        }
        const d = Logbook.defaultTargets(proc);
        this.db.setSetting(Logbook.targetKey(proc), a === d[0] && b === d[1] && c === d[2] ? "" : a + "," + b + "," + c);
        this.render();
        return true;
      }
    });
  }

  progressFile(s, p, pdf) {
    let rel;
    try {
      const f = Logbook.progressDoc(this.db, s, p);
      rel = pdf ? f.pdf(this) : f.docx(this);
    } catch (e) {
      Ui.toast(this, "Could not make the file: " + e.getMessage());
      return;
    }
    Store.share(this, rel, "Logbook progress " + s.get("name"));
  }

  white(v, l) {
    const s = Ui.v(this);
    s.setGravity(Gravity.CENTER);
    s.addView(Ui.tv(this, v, 20, Color.WHITE, true));
    s.addView(Ui.tv(this, l, 11, 0xD9FFFFFF, false));
    return s;
  }

  static statusColor(st) {
    return Logbook.SIGNED.equals(st) ? Ui.GREEN : Logbook.RETURNED.equals(st) ? Ui.RED : Ui.AMBER;
  }

  entryRow(r, showPg) {
    const sub = (showPg ? Ui.nz(r.get("pg")) + "  ·  " : "") + Dates.nice(r.get("date")) + "  ·  " + Ui.nz(r.get("role"))
      + (Ui.nz(r.get("patient")).isEmpty() ? "" : "\n" + r.get("patient") + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : " · IP " + r.get("ip_no")))
      + (Ui.nz(r.get("ward")).isEmpty() ? "" : " · " + Db.shortName(r.get("ward")))
      + (Ui.nz(r.get("notes")).isEmpty() ? "" : "\n" + r.get("notes"))
      + (Logbook.SIGNED.equals(r.get("status")) ? "\n✓ Signed by " + r.get("signed_by") + " · " + Ui.nz(r.get("signed_time"))
        : Ui.nz(r.get("supervisor")).isEmpty() ? "" : "\nSupervisor: " + r.get("supervisor"))
      + (Ui.nz(r.get("remarks")).isEmpty() ? "" : "\nRemark: " + r.get("remarks"));
    const card = this.entryCard(r.get("status"), LogbookActivity.statusColor(r.get("status")), Ui.nz(r.get("procedure")), sub, null, {
      onClick: (v) => { this.tap(r); }
    });
    const likes = Kudos.bar(this, this.db, "logbook", r.get("id"), "logbook entry (" + Ui.nz(r.get("procedure")) + ")", Ui.nz(r.get("staff_id")), Ui.nz(r.get("pg")));
    if (likes != null) card.addView(likes);
    return card;
  }

  tap(r) {
    const mine = Ui.toInt(r.get("staff_id"), -2) == Logbook.myPg(this, this.db);
    const sign = Logbook.canSign(this) && !Logbook.SIGNED.equals(r.get("status"));
    if (sign) this.signDialog(r);
    else if (mine && !Logbook.SIGNED.equals(r.get("status"))) this.entryDialog(r);
    else if (!Cloud.active(this)) this.entryDialog(r);
  }

  choosePg() {
    const pgs = this.db.rows("SELECT id, name, unit FROM staff WHERE role IN ('Postgraduate','CRMI') AND " + Approvals.APPROVED_SQL + " ORDER BY role DESC, name");
    if (pgs.isEmpty()) {
      Ui.toast(this, "Add PGs in Students first");
      return;
    }
    const names = new Array(pgs.size()).fill(null);
    for (let i = 0; i < names.length; i++) names[i] = pgs.get(i).get("name") + (Ui.nz(pgs.get(i).get("unit")).isEmpty() ? "" : "  (" + pgs.get(i).get("unit") + ")");
    new AlertDialog.Builder(this).setTitle("Whose logbook?").setItems(names, {
      onClick: (d, w) => {
        this.pg = Long.parseLong(pgs.get(w).get("id"));
        this.toSign = false;
        this.render();
      }
    }).show();
  }

  entryDialog(r) {
    const db = this.db;
    const mine = Logbook.myPg(this, db);
    const f = new Form(this);
    const pgs = db.rows("SELECT id, name FROM staff WHERE role IN ('Postgraduate','CRMI') AND " + Approvals.APPROVED_SQL + " ORDER BY name");
    if (mine <= 0 || (r != null && Ui.toInt(r.get("staff_id"), 0) != mine)) {
      if (pgs.isEmpty()) {
        Ui.toast(this, "Add PGs in Students first");
        return;
      }
      const l = new Array(pgs.size()).fill(null), v = new Array(pgs.size()).fill(null);
      for (let i = 0; i < l.length; i++) { l[i] = pgs.get(i).get("name"); v[i] = pgs.get(i).get("id"); }
      f.choice("pg", "PG", l, v, r != null ? r.get("staff_id") : this.pg > 0 ? String(this.pg) : v[0], null);
    }
    f.date("date", "Date", r == null ? Dates.todayIso() : r.get("date"));
    f.choice("procedure", "Procedure", Logbook.PROCEDURES, Logbook.PROCEDURES, r == null ? Logbook.PROCEDURES[0] : r.get("procedure"), null);
    f.text("other", "If other, which procedure", r == null || Logbook.PROCEDURES.contains(r.get("procedure")) ? "" : r.get("procedure"), Form.PLAIN);
    f.choice("role", "Your part", Logbook.ROLES, Logbook.ROLES, r == null ? Logbook.ROLES[0] : r.get("role"), null);
    const all = PatientPick.inpatients(db, null);
    f.suggest("patient", "Patient (name or IP number)", r == null ? "" : r.get("patient"), all.keySet());
    f.suggest("supervisor", "Supervising faculty (signs this entry)", r == null ? "" : r.get("supervisor"),
      db.staffNames("AND role IN ('Assistant Professor','Associate Professor','Professor')"));
    f.multi("notes", "Indication, findings, complications", r == null ? "" : r.get("notes"));
    Ui.formDialog(this, r == null ? "Log a procedure" : "Edit entry", f, "Save", {
      run: () => {
        const who = f.has("pg") ? Long.parseLong(f.get("pg")) : mine;
        const proc = f.get("procedure").equals("Other") && !f.get("other").trim().isEmpty() ? f.get("other").trim() : f.get("procedure");
        const cv = new ContentValues();
        cv.put("staff_id", who);
        const s = db.row("SELECT name FROM staff WHERE id=?", String(who));
        cv.put("pg", s == null ? "" : s.get("name"));
        cv.put("date", f.get("date"));
        cv.put("procedure", proc);
        cv.put("role", f.get("role"));
        const p = PatientPick.find(all, f.get("patient"));
        cv.put("patient", p == null ? f.get("patient").trim() : Ui.nz(p.get("name")));
        cv.put("ip_no", p == null ? (r == null ? "" : Ui.nz(r.get("ip_no"))) : Ui.nz(p.get("ip_no")));
        cv.put("ward", p == null ? (r == null ? "" : Ui.nz(r.get("ward"))) : Ui.nz(p.get("location")));
        cv.put("supervisor", f.get("supervisor").trim());
        cv.put("notes", f.get("notes").trim());
        cv.put("status", Logbook.PENDING);
        cv.put("remarks", "");
        cv.put("time", Dates.todayIso() + " " + Dates.now());
        if (r == null) db.insert("logbook", cv);
        else db.update("logbook", cv, Long.parseLong(r.get("id")));
        this.pg = who;
        this.toSign = false;
        this.render();
        return true;
      }
    });
  }

  signDialog(r) {
    const f = new Form(this);
    const dec = ["Sign", "Return to the PG"];
    f.segment("decision", "Decision", dec, dec[0], dec[0]);
    f.multi("remarks", "Remark (optional; say what to correct when returning)", Ui.nz(r.get("remarks")));
    Ui.formDialog(this, r.get("procedure") + " · " + r.get("pg"), f, "Save", {
      run: () => {
        const rem = f.get("remarks").trim();
        if (f.get("decision").equals(dec[0])) this.save(r, Logbook.SIGNED, rem);
        else this.save(r, Logbook.RETURNED, rem.isEmpty() ? "Please correct and resubmit" : rem);
        return true;
      }
    });
  }

  save(r, status, remarks) {
    const cv = new ContentValues();
    cv.put("status", status);
    cv.put("remarks", remarks);
    cv.put("signed_by", Logbook.SIGNED.equals(status) ? CallDutyActivity.myName(this) : "");
    cv.put("signed_time", Logbook.SIGNED.equals(status) ? Dates.todayIso() + " " + Dates.now() : "");
    this.db.update("logbook", cv, Long.parseLong(r.get("id")));
    this.render();
  }

  pdf() {
    const db = this.db;
    const s = db.row("SELECT * FROM staff WHERE id=?", String(this.pg));
    if (s == null) return;
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "PG PROCEDURE LOGBOOK";
    f.footer = s.get("name") + "  •  " + f.dept + ", " + f.college;
    f.fileBase = "Logbook_" + s.get("name").replaceAllRx("[^A-Za-z0-9]+", "_");
    const h = f.block(null, 0, 0.5, 0.25, 0.25);
    h.row(16, new FormDoc.Cell("PG: " + s.get("name")).b(), new FormDoc.Cell("Unit: " + Ui.nz(s.get("unit"))).b(), new FormDoc.Cell("Batch: " + Ui.nz(s.get("batch"))).b());
    const t = f.block("PROCEDURES", FormDoc.NAVY, 0.05, 0.11, 0.2, 0.17, 0.2, 0.27);
    t.row(14, new FormDoc.Cell("No").b(), new FormDoc.Cell("Date").b(), new FormDoc.Cell("Procedure").b(), new FormDoc.Cell("Part").b(),
      new FormDoc.Cell("Patient / IP").b(), new FormDoc.Cell("Signed by").b());
    let i = 0;
    for (const r of db.rows("SELECT * FROM logbook WHERE staff_id=? ORDER BY date, id", String(this.pg))) {
      t.row(14, new FormDoc.Cell(String(++i)), new FormDoc.Cell(Dates.nice(r.get("date"))), new FormDoc.Cell(r.get("procedure")),
        new FormDoc.Cell(r.get("role")), new FormDoc.Cell(Ui.nz(r.get("patient")) + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : " / " + r.get("ip_no"))),
        new FormDoc.Cell(Logbook.SIGNED.equals(r.get("status")) ? r.get("signed_by") + "\n" + Ui.nz(r.get("signed_time")) : r.get("status")));
    }
    try {
      const rel = f.pdf(this);
      Store.share(this, rel, "Logbook " + s.get("name"));
    } catch (e) {
      Ui.toast(this, "Could not make the PDF: " + e.getMessage());
    }
  }
}

/** A ring showing a percentage. */
LogbookActivity.Ring = class extends View {
  constructor(c, pct) {
    super(c);
    this.pct = pct;
    this.paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.w = Ui.dp(c, 9);
  }

  onDraw(c) {
    const paint = this.paint, w = this.w, pct = this.pct;
    const size = Math.min(this.getWidth(), this.getHeight()), pad = w / 2 + 2;
    const box = new RectF(pad, pad, size - pad, size - pad);
    paint.setStyle(Paint.Style.STROKE);
    paint.setStrokeWidth(w);
    paint.setColor(0x44FFFFFF);
    c.drawArc(box, 0, 360, false, paint);
    paint.setColor(Color.WHITE);
    paint.setStrokeCap(Paint.Cap.ROUND);
    c.drawArc(box, -90, 360 * Math.max(0, Math.min(100, pct)) / 100, false, paint);
    paint.setStyle(Paint.Style.FILL);
    paint.setTextAlign(Paint.Align.CENTER);
    paint.setTextSize(size / 4.2);
    paint.setFakeBoldText(true);
    c.drawText(pct + "%", size / 2, size / 2 + paint.getTextSize() / 3, paint);
  }
};
;
