/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Daily MCQ: faculty post a case-based question each day; students (and anyone) answer once on their own phone.
 * Every answer is recorded, so the faculty see how many answered and how many were right, option by option.
 * The explanation opens after answering.
 */
class Mcq {
  constructor() {}

  static LETTERS = ["A", "B", "C", "D", "E"];
  static SUBJECTS = ["General medicine", "Cardiology", "Neurology", "Nephrology", "Pulmonology", "Gastroenterology & hepatology",
      "Endocrinology & metabolism", "Infectious diseases", "Haematology", "Rheumatology", "Toxicology", "Critical care", "ECG & imaging", "Pharmacology"];
  static LEVELS = ["All", "MBBS", "PG"];
  /** Card gradient: deep indigo to violet to pink. */
  static GRADIENT = [0xFF312E81, 0xFF6D28D9, 0xFFDB2777];

  /** Only faculty (and the admin, HOD) post questions; a phone without shared login belongs to its user. */
  static canPost(c) {
    return SessionAttendance.canRun(c);
  }

  static options(q) {
    const out = [];
    for (const l of Mcq.LETTERS) {
      const o = Ui.nz(q.get("opt_" + l.toLowerCase()));
      if (!o.isEmpty()) out.add(o);
    }
    return out;
  }

  // ---------- which question ----------

  /** Today's question for the home card: the first one not yet answered, else the latest of today, else the latest. */
  static featured(c, db) {
    const me = SessionAttendance.me(c, db);
    const t = Dates.todayIso();
    const today = db.rows("SELECT * FROM mcqs WHERE date=? ORDER BY id", t);
    for (const q of today) if (me == null || Mcq.mine(db, q.get("id"), me) == null) return q;
    if (!today.isEmpty()) return today.get(today.size() - 1);
    return db.row("SELECT * FROM mcqs WHERE date<=? ORDER BY date DESC, id DESC LIMIT 1", t);
  }

  // ---------- answers ----------

  static mine(db, mcqId, me) {
    if (me == null) return null;
    return db.row("SELECT * FROM mcq_answers WHERE mcq_id=? AND (staff_id=? OR name=?) ORDER BY time LIMIT 1", mcqId, me.get("id"), me.get("name"));
  }

  /** Records an answer (first answer counts). Returns whether it was right, or null if already answered. */
  static answer(db, c, q, me, letter) {
    if (Mcq.mine(db, q.get("id"), me) != null) return null;
    const right = letter.equals(q.get("answer"));
    const cv = new ContentValues();
    cv.put("mcq_id", q.get("id"));
    cv.put("staff_id", me.get("id"));
    cv.put("name", me.get("name"));
    cv.put("role", me.get("role"));
    cv.put("choice", letter);
    cv.put("correct", right ? "1" : "0");
    cv.put("time", LocalDateTime.now().withNano(0).toString());
    db.insert("mcq_answers", cv);
    return right;
  }

  static answered(db, mcqId) {
    return db.num("SELECT COUNT(*) FROM mcq_answers WHERE mcq_id=?", mcqId);
  }

  static correct(db, mcqId) {
    return db.num("SELECT COUNT(*) FROM mcq_answers WHERE mcq_id=? AND correct='1'", mcqId);
  }

  static picked(db, mcqId, letter) {
    return db.num("SELECT COUNT(*) FROM mcq_answers WHERE mcq_id=? AND choice=?", mcqId, letter);
  }

  static percent(part, whole) {
    return whole === 0 ? 0 : Math.round(part * 100 / whole);
  }

  /** Days in a row (ending today or yesterday) on which this person answered at least one MCQ. */
  static streak(db, me) {
    if (me == null) return 0;
    const days = db.rows("SELECT DISTINCT substr(time,1,10) AS d FROM mcq_answers WHERE staff_id=? OR name=? ORDER BY d DESC",
        me.get("id"), me.get("name"));
    let expect = Dates.today();
    let n = 0;
    for (let i = 0; i < days.size(); i++) {
      const d = Dates.parse(days.get(i).get("d"));
      if (d == null) continue;
      if (i === 0 && d.equals(expect.minusDays(1))) expect = d;
      if (!d.equals(expect)) break;
      n++;
      expect = expect.minusDays(1);
    }
    return n;
  }

  /** This month's top scorers: name, role, right, answered. */
  static leaders(db, month, limit) {
    const m0 = Dates.monthStart(month).toString(), m1 = Dates.monthStart(month).plusMonths(1).toString();
    return db.rows("SELECT name, role, SUM(correct='1') AS ok, COUNT(*) AS n FROM mcq_answers WHERE time>=? AND time<? "
        + "GROUP BY name ORDER BY ok DESC, n ASC, MIN(time) LIMIT " + limit, m0, m1);
  }

  // ---------- the home card ----------

  /** A modern glass card for the home page: today's case, streak, a ring of how many got it right, one tap to answer. */
  static homeCard(a, db) {
    const q = Mcq.featured(a, db);
    const poster = Mcq.canPost(a);
    if (q == null && !poster) return null;
    const me = SessionAttendance.me(a, db);
    const card = Ui.v(a);
    card.setBackground(Glass.hero(a, Mcq.GRADIENT, 24));
    card.setPadding(Ui.dp(a, 18), Ui.dp(a, 16), Ui.dp(a, 18), Ui.dp(a, 16));
    card.setElevation(Ui.dp(a, 6));
    Glass.softShadow(card, 0xFF6D28D9);
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(a, 12), Ui.dp(a, 12), Ui.dp(a, 12), Ui.dp(a, 4));
    card.setLayoutParams(lp);

    const top = Ui.h(a);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const tag = Ui.tv(a, "✦  DAILY MCQ", 11, Color.WHITE, true);
    tag.setLetterSpacing(0.12);
    tag.setBackground(Glass.frost(a, 14));
    tag.setPadding(Ui.dp(a, 10), Ui.dp(a, 4), Ui.dp(a, 10), Ui.dp(a, 4));
    top.addView(tag);
    const sp = new View(a);
    top.addView(sp, new LinearLayoutParams(0, 1, 1));
    const st = Mcq.streak(db, me);
    if (st > 0) {
      const s = Ui.tv(a, "🔥 " + st + "-day streak", 12, Color.WHITE, true);
      s.setBackground(Ui.round(a, 0x33000000, 14));
      s.setPadding(Ui.dp(a, 10), Ui.dp(a, 4), Ui.dp(a, 10), Ui.dp(a, 4));
      top.addView(s);
    }
    card.addView(top);

    if (q == null) {
      const t = Ui.tv(a, "Start the department's daily question", 19, Color.WHITE, true);
      card.addView(t);
      Ui.margins(t, 0, 12, 0, 0);
      card.addView(Ui.tv(a, "Post a case-based MCQ. Students answer on their phones and you see how many got it right.", 13, 0xD9FFFFFF, false));
      const go = Mcq.cta(a, "Post today's MCQ  →");
      go.setOnClickListener(a.opener(McqEditActivity));
      card.addView(go);
      Ui.margins(go, 0, 14, 0, 0);
      return card;
    }

    const isToday = Dates.todayIso().equals(q.get("date"));
    const sub = Ui.tv(a, Ui.nz(q.get("subject")) + "  ·  " + (isToday ? "Today" : Dates.nice(q.get("date")))
        + ("All".equals(Ui.nz(q.get("level"))) || Ui.nz(q.get("level")).isEmpty() ? "" : "  ·  " + q.get("level")), 12, 0xCCFFFFFF, true);
    card.addView(sub);
    Ui.margins(sub, 0, 12, 0, 0);
    const preview = Ui.nz(q.get("scenario")).isEmpty() ? q.get("question") : q.get("scenario");
    const body = Ui.tv(a, preview, 16, Color.WHITE, true);
    body.setMaxLines(3);
    body.setEllipsize(TextUtils.TruncateAt.END);
    body.setLineSpacing(0, 1.1);
    card.addView(body);
    Ui.margins(body, 0, 4, 0, 0);

    const n = Mcq.answered(db, q.get("id")), ok = Mcq.correct(db, q.get("id"));
    const bottom = Ui.h(a);
    bottom.setGravity(Gravity.CENTER_VERTICAL);
    const ring = new Mcq.Ring(a, Mcq.percent(ok, n), n > 0);
    bottom.addView(ring, Ui.lp(Ui.dp(a, 54), Ui.dp(a, 54)));
    const stats = Ui.v(a);
    stats.setPadding(Ui.dp(a, 12), 0, 0, 0);
    stats.addView(Ui.tv(a, n === 0 ? "Be the first to answer" : n + " answered", 14, Color.WHITE, true));
    stats.addView(Ui.tv(a, n === 0 ? "Answer to unlock the explanation" : Mcq.percent(ok, n) + "% got it right", 12, 0xCCFFFFFF, false));
    bottom.addView(stats, Ui.weight(1));
    const mine = Mcq.mine(db, q.get("id"), me);
    const go = Mcq.cta(a, mine == null ? "Answer  →" : "1".equals(mine.get("correct")) ? "✓ Correct" : "✗ Review");
    if (mine != null) go.setTextColor("1".equals(mine.get("correct")) ? Ui.GREEN : Ui.RED);
    bottom.addView(go);
    card.addView(bottom);
    Ui.margins(bottom, 0, 14, 0, 0);

    const open = a.opener(McqQuestionActivity, "id", q.get("id"));
    go.setOnClickListener(open);
    card.setOnClickListener(open);
    Ui.ripple(card, 0x33FFFFFF);
    return card;
  }

  static cta(c, s) {
    const t = Ui.tv(c, s, 14, 0xFF4C1D95, true);
    t.setBackground(Ui.round(c, Color.WHITE, 20));
    t.setPadding(Ui.dp(c, 16), Ui.dp(c, 9), Ui.dp(c, 16), Ui.dp(c, 9));
    t.setGravity(Gravity.CENTER);
    return t;
  }
}

/** A small progress ring with the percentage in the middle. */
Mcq.Ring = class extends View {
  constructor(c, pct, has) {
    super(c);
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.r = new RectF();
    this.pct = pct;
    this.has = has;
  }

  onDraw(cv) {
    const w = this.getWidth(), h = this.getHeight(), s = Math.min(w, h), stroke = s * 0.11;
    const p = this.p, r = this.r;
    r.set((w - s) / 2 + stroke, (h - s) / 2 + stroke, (w + s) / 2 - stroke, (h + s) / 2 - stroke);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(stroke);
    p.setStrokeCap(Paint.Cap.ROUND);
    p.setColor(0x40FFFFFF);
    cv.drawArc(r, 0, 360, false, p);
    if (this.has && this.pct > 0) {
      p.setColor(0xFF6EE7B7);
      cv.drawArc(r, -90, 360 * this.pct / 100, false, p);
    }
    p.setStyle(Paint.Style.FILL);
    p.setColor(Color.WHITE);
    p.setTextAlign(Paint.Align.CENTER);
    p.setFakeBoldText(true);
    p.setTextSize(s * 0.26);
    cv.drawText(this.has ? this.pct + "%" : "–", w / 2, h / 2 - (p.descent() + p.ascent()) / 2, p);
  }
};
;
/* ---- app/McqActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Daily MCQ, Daily ECG and Daily Image: today's questions, every earlier question with results, and this month's top scorers;
 * and the ECGs and images that faculty and students post for discussion.
 */
class McqActivity extends Base {
  constructor() {
    super();
    this.tab = "today";
    this.section = McqActivity.MCQ;
  }

  static MCQ = "MCQ";

  onCreate(b) {
    super.onCreate(b);
    if (this.getIntent().getStringExtra("section") != null) this.section = this.getIntent().getStringExtra("section");
    this.setTitle("Daily MCQ, ECG & Image");
    this.subtitle = "Learn something new every day";
    this.headerAction("+ Post", {
      onClick: (v) => {
        if (!this.section.equals(McqActivity.MCQ)) this.open(SpotEditActivity, "kind", this.section);
        else if (Mcq.canPost(this)) this.open(McqEditActivity);
        else Ui.toast(this, "Only faculty post MCQs. Anyone can post an ECG or an image.");
      }
    });
  }

  /** MCQ / ECG / Image switch at the top of the screen. */
  sections() {
    const keys = [McqActivity.MCQ, Spots.ECG, Spots.IMAGE];
    const labels = ["✦  MCQ", "♥  ECG", "◉  Image"];
    const cols = [0xFF6D28D9, Spots.ECG_COLOR, Spots.IMAGE_COLOR];
    const bar = Ui.h(this);
    bar.setBackground(Ui.round(this, 0x14000000, 22));
    bar.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    bar.setLayoutParams(lp);
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const on = k.equals(this.section);
      const t = Ui.tv(this, labels[i], 14, on ? Color.WHITE : cols[i], true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 9), 0, Ui.dp(this, 9));
      if (on) t.setBackground(Ui.round(this, cols[i], 18));
      t.setOnClickListener({ onClick: (v) => { this.section = k; this.tab = "today"; this.render(); } });
      bar.addView(t, Ui.weight(1));
    }
    return bar;
  }

  render() {
    this.headerColors = this.section.equals(McqActivity.MCQ) ? Mcq.GRADIENT : Spots.gradient(this.section);
    if (!this.section.equals(McqActivity.MCQ)) {
      this.spots();
      return;
    }
    const page = Ui.v(this);
    page.addView(this.sections());
    const home = Mcq.homeCard(this, this.db);
    if (home != null) page.addView(home);
    page.addView(this.myStats());

    const keys = ["today", "all", "top"];
    const labels = ["Today", "All questions", "Top scorers"];
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.tab), 0xFF6D28D9);
      c.setOnClickListener({ onClick: (v) => { this.tab = k; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    if (this.tab.equals("top")) this.top(page);
    else {
      const qs = this.tab.equals("today")
          ? this.db.rows("SELECT * FROM mcqs WHERE date=? ORDER BY id", Dates.todayIso())
          : this.db.rows("SELECT * FROM mcqs WHERE date<=? ORDER BY date DESC, id DESC LIMIT 200", Dates.todayIso());
      if (qs.isEmpty()) page.addView(this.emptyNote(this.tab.equals("today")
          ? (Mcq.canPost(this) ? "No MCQ for today yet. Tap + Post to add one." : "Today's MCQ has not been posted yet.")
          : "No MCQs yet."));
      const me = SessionAttendance.me(this, this.db);
      for (const q of qs) page.addView(this.row(q, me));
      if (Mcq.canPost(this)) {
        const later = this.db.rows("SELECT * FROM mcqs WHERE date>? ORDER BY date, id", Dates.todayIso());
        if (!later.isEmpty()) {
          page.addView(Ui.heading(this, "Scheduled (" + later.size() + ")", Ui.SLATE));
          for (const q of later) page.addView(this.row(q, me));
        }
      }
    }
    this.setPage(page);
  }

  /** Daily ECG or Daily Image: a hero with the upload button, then today's or every post with its discussion count. */
  spots() {
    const kind = this.section;
    const col = Spots.color(kind);
    const page = Ui.v(this);
    page.addView(this.sections());
    const hero = Ui.v(this);
    hero.setBackground(Glass.hero(this, Spots.gradient(kind), 22));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 4));
    hero.setLayoutParams(lp);
    hero.addView(Ui.tv(this, Spots.name(kind), 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, Spots.ECG.equals(kind)
        ? "Faculty and students upload an interesting ECG with a short history. Everyone writes their reading; the answer opens when you tap Show."
        : "Upload an X-ray, CT, MRI, USG, fundus, smear or clinical photo with a short history. Everyone discusses it; the answer opens when you tap Show.",
        13, 0xE6FFFFFF, false));
    const up = Mcq.cta(this, Spots.ECG.equals(kind) ? "+  Upload an ECG" : "+  Upload an image");
    up.setTextColor(col);
    up.setOnClickListener(this.opener(SpotEditActivity, "kind", kind));
    hero.addView(up);
    Ui.margins(up, 0, 14, 0, 0);
    page.addView(hero);

    const keys = ["today", "all"];
    const labels = ["Today", Spots.ECG.equals(kind) ? "All ECGs" : "All images"];
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.tab) || (i === 0 && !this.tab.equals("all")), col);
      c.setOnClickListener({ onClick: (v) => { this.tab = k; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));
    const l = this.tab.equals("all") ? Spots.all(this.db, kind) : Spots.today(this.db, kind);
    if (l.isEmpty()) page.addView(this.emptyNote(this.tab.equals("all") ? "Nothing posted yet." : "Nothing posted today yet. Tap Upload to share one."));
    for (const s of l) {
      const n = Spots.count(this.db, s.get("id"));
      let sub = Ui.nz(s.get("question"));
      if (sub.length > 120) sub = sub.substring(0, 120) + "…";
      sub += (sub.isEmpty() ? "" : "\n") + "By " + Ui.nz(s.get("name")) + "  ·  " + (n === 0 ? "No comments yet" : n + (n === 1 ? " comment" : " comments"))
          + (Ui.nz(s.get("answer")).isEmpty() ? "" : "  ·  answer inside");
      page.addView(this.entryCard(Ui.nz(s.get("type")), col, Spots.label(s), sub, Dates.nice(s.get("date")),
          this.opener(SpotActivity, "id", s.get("id"))));
    }
    this.setPage(page);
  }

  /** The person's own record: answered, accuracy, streak. */
  myStats() {
    const me = SessionAttendance.me(this, this.db);
    const c = Ui.card(this);
    if (me == null) {
      c.addView(Ui.muted(this, "Answer a question to start your score and streak."));
      return c;
    }
    const n = this.db.num("SELECT COUNT(*) FROM mcq_answers WHERE staff_id=? OR name=?", me.get("id"), me.get("name"));
    const ok = this.db.num("SELECT COUNT(*) FROM mcq_answers WHERE (staff_id=? OR name=?) AND correct='1'", me.get("id"), me.get("name"));
    c.addView(Ui.statRow(this, Ui.stat(this, String(n), "Answered", Ui.PRIMARY),
        Ui.stat(this, Mcq.percent(ok, n) + "%", "Accuracy", Ui.GREEN),
        Ui.stat(this, "🔥 " + Mcq.streak(this.db, me), "Day streak", Ui.ORANGE)));
    return c;
  }

  row(q, me) {
    const n = Mcq.answered(this.db, q.get("id")), ok = Mcq.correct(this.db, q.get("id"));
    const mine = Mcq.mine(this.db, q.get("id"), me);
    const status = mine == null ? "Not answered" : "1".equals(mine.get("correct")) ? "✓ You got it right" : "✗ You answered " + mine.get("choice");
    const sub = n + " answered" + (n > 0 ? " · " + Mcq.percent(ok, n) + "% right" : "") + "  ·  " + status;
    const future = q.get("date").compareTo(Dates.todayIso()) > 0;
    const body = Ui.nz(q.get("question"));
    return this.entryCard(Ui.nz(q.get("subject")), mine == null ? 0xFF6D28D9 : "1".equals(mine.get("correct")) ? Ui.GREEN : Ui.RED,
        body.length > 140 ? body.substring(0, 140) + "…" : body, sub, (future ? "Shows " : "") + Dates.nice(q.get("date")),
        this.opener(McqQuestionActivity, "id", q.get("id")));
  }

  top(page) {
    const l = Mcq.leaders(this.db, Dates.today(), 20);
    page.addView(Ui.heading(this, "Top scorers · " + Dates.month(Dates.today()), 0xFF6D28D9));
    if (l.isEmpty()) {
      page.addView(this.emptyNote("No answers this month yet."));
      return;
    }
    const c = Ui.card(this);
    const medals = ["🥇", "🥈", "🥉"];
    for (let i = 0; i < l.size(); i++) {
      const r = l.get(i);
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 7), 0, Ui.dp(this, 7));
      const rank = Ui.tv(this, i < 3 ? medals[i] : String(i + 1), i < 3 ? 20 : 14, Ui.MUTED, true);
      rank.setGravity(Gravity.CENTER);
      row.addView(rank, Ui.lp(Ui.dp(this, 36), LinearLayout.LayoutParams.WRAP_CONTENT));
      const who = Ui.v(this);
      who.addView(Ui.tv(this, r.get("name"), 15, Ui.TEXT, true));
      who.addView(Ui.muted(this, "Postgraduate".equals(r.get("role")) ? "PG" : Ui.nz(r.get("role"))));
      row.addView(who, Ui.weight(1));
      const ok = Ui.toInt(r.get("ok"), 0), n = Ui.toInt(r.get("n"), 0);
      const sc = Ui.tv(this, ok + " / " + n, 15, i === 0 ? Color.WHITE : 0xFF6D28D9, true);
      sc.setBackground(i === 0 ? Ui.round(this, 0xFF6D28D9, 14) : Ui.round(this, Ui.alpha(0xFF6D28D9, 0x1A), 14));
      sc.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
      row.addView(sc);
      c.addView(row);
    }
    page.addView(c);
  }
}
;
