/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Faculty: post a daily MCQ (case scenario, question, up to five options, the answer, explanation), or edit one. */
class McqEditActivity extends Base {
  constructor() {
    super();
    this.form = null;
    this.id = -1;
    this.scan = null;
    this.pasteBtn = null; this.waitNote = null;
  }

  static REQ_SCAN = 8701;   // 8701 live, 8702 camera, 8703 gallery / file

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    this.setTitle(this.id >= 0 ? "Edit MCQ" : "Post a daily MCQ");
    this.headerColor(0xFF6D28D9);
    this.headerAction("Save", { onClick: (v) => { this.save(); } });
    this.scan = new PageScan(this, "mcqscan", "Daily MCQ from a book", McqScan.prompt(), McqScan.MARK, QuizScan.MAX_PAGES, McqEditActivity.REQ_SCAN, {
      read: (text) => { this.useText(text); }
    });
    this.scan.restore(b);
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    this.scan.save(out);
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    this.scan.result(req, res, data);
  }

  onResume() {
    super.onResume();
    this.paintWait();
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.form != null) return;
    if (!Mcq.canPost(this)) {
      const page = Ui.v(this);
      page.addView(this.emptyNote("Only faculty can post MCQs."));
      this.setPage(page);
      return;
    }
    const v = McqEditActivity.v;
    const q = this.id >= 0 ? this.db.row("SELECT * FROM mcqs WHERE id=?", String(this.id)) : null;
    const form = this.form = new Form(this);
    form.heading("Question");
    form.date("date", "Show on (date)", v(q, "date", Dates.todayIso()));
    form.choice("subject", "Subject", Mcq.SUBJECTS, Mcq.SUBJECTS, v(q, "subject", Mcq.SUBJECTS[0]), null);
    form.choice("level", "For", ["Everyone", "MBBS students", "PGs"], Mcq.LEVELS, v(q, "level", "All"), null);
    form.multi("scenario", "Case scenario", v(q, "scenario", ""));
    form.multi("question", "Question *", v(q, "question", ""));
    form.heading("Options");
    for (const l of Mcq.LETTERS) form.text("opt_" + l.toLowerCase(), l + (l.compareTo("C") < 0 ? " *" : " (optional)"),
        v(q, "opt_" + l.toLowerCase(), ""), Form.PLAIN);
    form.choice("answer", "Correct answer", Mcq.LETTERS, Mcq.LETTERS, v(q, "answer", "A"), null);
    form.heading("Explanation (shown after answering)");
    form.multi("explanation", "Explanation / teaching points", v(q, "explanation", ""));
    form.text("refs", "Reference (book, guideline, page)", v(q, "refs", ""), Form.PLAIN);

    const page = Ui.v(this);
    page.addView(this.scanCard());
    const card = Ui.card(this);
    card.addView(form.view);
    page.addView(card);
    const btns = Ui.v(this);
    btns.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    btns.addView(Ui.button(this, this.id >= 0 ? "Save changes" : "Post MCQ", 0xFF6D28D9, { onClick: (v2) => { this.save(); } }));
    if (this.id >= 0) {
      const del = Ui.outlineButton(this, "Delete MCQ", Ui.RED, {
        onClick: (v2) => {
          Ui.confirm(this, "Delete this MCQ?", "The question and everyone's answers will be removed.", "Delete", {
            run: () => {
              for (const r of this.db.rows("SELECT id FROM mcq_answers WHERE mcq_id=?", String(this.id)))
                this.db.delete("mcq_answers", Long.parseLong(r.get("id")));
              this.db.delete("mcqs", this.id);
              this.finish();
            }
          });
        }
      });
      btns.addView(del);
      Ui.margins(del, 0, 10, 0, 0);
    }
    page.addView(btns);
    this.setPage(page);
  }

  // ---------- from a photo or PDF of a book (8.70) ----------

  scanCard() {
    const card = Ui.card(this);
    card.addView(Ui.title(this, "📷  Fill from a book or question paper"));
    const hint = Ui.muted(this, "Point the camera at the MCQ, snap it, or pick a photo or PDF. The case, question, options, answer and "
        + "explanation fill in by themselves; check them before posting.");
    card.addView(hint);
    Ui.margins(hint, 0, 4, 0, 6);
    card.addView(Ui.buttonRow(this, Ui.button(this, "📹  Live scan", 0xFF6D28D9, { onClick: (v) => { this.scan.live(); } }),
        Ui.button(this, "📷  Camera", 0xFF6D28D9, { onClick: (v) => { this.scan.camera(true); } })));
    const gal = Ui.outlineButton(this, "🖼  Gallery or file (photo / PDF)", 0xFF6D28D9, { onClick: (v) => { this.scan.pick(true); } });
    card.addView(gal);
    Ui.margins(gal, 0, 8, 0, 0);
    this.pasteBtn = Ui.outlineButton(this, "", 0xFF6D28D9, { onClick: (v) => { this.scan.paste(); } });
    card.addView(this.pasteBtn);
    Ui.margins(this.pasteBtn, 0, 8, 0, 0);
    this.waitNote = Ui.tv(this, "", 13, 0xFF6D28D9, true);
    card.addView(this.waitNote);
    Ui.margins(this.waitNote, 0, 6, 0, 0);
    this.paintWait();
    return card;
  }

  paintWait() {
    if (this.pasteBtn == null) return;
    const app = this.scan.waiting();
    this.pasteBtn.setText(app.isEmpty() ? "Paste copied MCQ text" : "Paste " + app + "'s answer");
    this.waitNote.setText(app.isEmpty() ? "" : "Waiting for " + app + ": copy its answer there, come back and tap Paste.");
    this.waitNote.setVisibility(app.isEmpty() ? View.GONE : View.VISIBLE);
  }

  /** The questions read: one fills the form; with several, choose one, and the rest can wait for the next days. */
  useText(text) {
    this.paintWait();
    const items = QuizScan.parse(text);
    if (items.isEmpty()) {
      new AlertDialog.Builder(this).setTitle("No MCQ found")
        .setMessage("Try a clearer picture, straight from above in good light, with the whole question and its options.").setPositiveButton("OK", null).show();
      return;
    }
    if (items.length === 1) {
      this.fill(items[0]);
      return;
    }
    const labels = new Array(items.length).fill(null);
    for (let k = 0; k < items.length; k++) labels[k] = McqScan.label(k, items[k]);
    new AlertDialog.Builder(this).setTitle(items.length + " questions found: which one for this MCQ?")
      .setItems(labels, {
        onClick: (d, w) => {
          this.fill(items[w]);
          const rest = ArrayList(items);
          rest.removeAt(w);
          if (this.id >= 0) return;
          new AlertDialog.Builder(this).setTitle("The other " + rest.length + (rest.length === 1 ? " question" : " questions"))
            .setMessage("Save them as the daily MCQs for the next days (one a day, on days without an MCQ)? You can edit or delete them later.")
            .setPositiveButton("Save for the next days", {
              onClick: (d2, k) => {
                const n = this.scheduleRest(rest);
                Ui.toast(this, n + (n === 1 ? " MCQ" : " MCQs") + " saved for the coming days");
              }
            }).setNegativeButton("No", null).show();
        }
      }).show();
  }

  fill(i) {
    const f = McqScan.fields(i);
    for (const e of f.entrySet()) if (!e.getKey().equals("answer") || i.answer >= 0) this.form.set(e.getKey(), e.getValue());
    const msg = i.answer < 0 ? "Filled in. No answer was found: choose the correct answer." : i.aiAnswer
      ? "Filled in. The answer was given by the AI, not the book: check it." : "Filled in from the page. Check it, then Post.";
    new AlertDialog.Builder(this).setTitle("MCQ read").setMessage(msg).setPositiveButton("OK", null).show();
  }

  /** The other questions, one a day after this MCQ's date, on days with no MCQ yet. Only questions with an answer are kept. */
  scheduleRest(rest) {
    let day = Dates.parse(this.form.get("date"));
    if (day == null) day = Dates.today();
    const by = Approvals.me(this).isEmpty() ? Reminders.myName(this, this.db) : Approvals.me(this);
    let n = 0;
    for (const i of rest) {
      if (i.answer < 0 || i.options.length < 2) continue;
      do day = day.plusDays(1); while (this.db.num("SELECT COUNT(*) FROM mcqs WHERE date=?", day.toString()) > 0);
      const f = McqScan.fields(i);
      const cv = new ContentValues();
      for (const e of f.entrySet()) cv.put(e.getKey(), e.getValue());
      cv.put("date", day.toString());
      cv.put("level", this.form.get("level"));
      cv.put("refs", this.form.get("refs"));
      cv.put("posted_by", by);
      cv.put("posted_on", Dates.todayIso() + " " + Dates.now());
      this.db.insert("mcqs", cv);
      n++;
    }
    return n;
  }

  static v(r, k, def) {
    return r == null || Ui.nz(r.get(k)).isEmpty() ? def : r.get(k);
  }

  save() {
    const form = this.form;
    if (form == null) return;
    if (!form.require("question", "Enter the question")) return;
    if (!form.require("opt_a", "Enter option A") || !form.require("opt_b", "Enter option B")) return;
    const ans = form.get("answer");
    if (form.get("opt_" + ans.toLowerCase()).isEmpty()) {
      Ui.toast(this, "The correct answer (" + ans + ") has no option text");
      return;
    }
    const cv = new ContentValues();
    for (const k of ["date", "subject", "level", "scenario", "question", "opt_a", "opt_b", "opt_c", "opt_d", "opt_e", "answer", "explanation", "refs"])
      cv.put(k, form.get(k));
    if (this.id < 0) {
      cv.put("posted_by", Approvals.me(this).isEmpty() ? Reminders.myName(this, this.db) : Approvals.me(this));
      cv.put("posted_on", Dates.todayIso() + " " + Dates.now());
      this.id = this.db.insert("mcqs", cv);
      Ui.toast(this, "MCQ posted");
      this.finish();
      this.open(McqQuestionActivity, "id", String(this.id));
      return;
    }
    this.db.update("mcqs", cv, this.id);
    Ui.toast(this, "Saved");
    this.finish();
  }
}
;
/* ---- app/McqMaker.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * AI MCQ maker (8.30): a learning board topic, or any text the teacher types or pastes, becomes ready live-quiz questions with
 * four options, the right answer and a one-line reason. The reply uses QuizScan's shape, so the same checking screens are used.
 */
class McqMaker {
  static MARK = "Write multiple-choice questions for a live quiz";
  static LEVELS = ["MBBS final year", "PG (MD General Medicine)", "Mixed"];
  static COUNTS = ["5", "10", "15", "20"];

  static system() {
    return McqMaker.MARK + " in the Department of General Medicine, Tirunelveli Medical College Hospital, India. You are an experienced "
        + "examiner who writes clinical, case-based questions in the style of NEET-PG and university exams.\n"
        + "Rules: every question has exactly four options and one clearly right answer; the wrong options are plausible; no 'all of "
        + "the above' or 'none of the above'; prefer short case scenarios and applied knowledge over recall; follow standard Indian "
        + "and international guidelines and textbooks (Harrison, API, ICMR, WHO). Keep each question under 60 words.\n"
        + "Reply in exactly this shape, with a blank line between questions and nothing else:\n"
        + "Q: the question\nA) option\nB) option\nC) option\nD) option\nAnswer: the letter\nWhy: one line on why it is right\n"
        + "No introduction, no numbering other than this, no markdown.";
  }

  static user(topic, text, count, level) {
    const u = new StringBuilder();
    u.append("Write ").append(count).append(" questions for ").append(level).append(" students");
    if (!Ui.nz(topic).trim().isEmpty()) u.append(" on the topic: ").append(topic.trim());
    u.append(".\n");
    if (!Ui.nz(text).trim().isEmpty()) u.append("Base them on these notes (and standard knowledge where the notes are short):\n<notes>\n").append(text.trim()).append("\n</notes>");
    return u.toString();
  }

  /** A learning board topic as notes for the AI: its name, subject and numbered points. */
  static topicText(n) {
    const b = new StringBuilder();
    if (!Ui.nz(n.get("subject")).isEmpty()) b.append("Subject: ").append(n.get("subject")).append("\n");
    let k = 1;
    const pts = TopicNotes.points(n);
    for (const p of pts) b.append(k++).append(". ").append(p).append("\n");
    return b.toString();
  }
}
;
