/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One daily MCQ: read the case, tap an answer, then see the explanation and how the department did. */
class McqQuestionActivity extends Base {
  constructor() {
    super();
    this.qid = null;
  }

  onCreate(b) {
    super.onCreate(b);
    this.qid = this.getIntent().getStringExtra("id");
    this.setTitle("Daily MCQ");
    this.headerColors = Mcq.GRADIENT;
    if (Mcq.canPost(this)) this.headerAction("Edit", this.opener(McqEditActivity, "id", Ui.nz(this.qid)));
  }

  render() {
    const db = this.db, qid = this.qid;
    const q = db.row("SELECT * FROM mcqs WHERE id=?", Ui.nz(qid));
    const page = Ui.v(this);
    if (q == null) {
      page.addView(this.emptyNote("This MCQ was removed."));
      this.setPage(page);
      return;
    }
    this.subtitle = Ui.nz(q.get("subject")) + " · " + Dates.nice(q.get("date"));
    const faculty = Mcq.canPost(this);
    const me = SessionAttendance.me(this, db);
    const mine = Mcq.mine(db, qid, me);
    const reveal = mine != null || faculty;
    const n = Mcq.answered(db, qid), ok = Mcq.correct(db, qid);

    // the case
    const hero = Ui.v(this);
    hero.setBackground(Glass.hero(this, Mcq.GRADIENT, 22));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 18));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 4));
    hero.setLayoutParams(lp);
    const tags = Ui.h(this);
    tags.addView(this.frostTag(Ui.nz(q.get("subject"))));
    if (!Ui.nz(q.get("level")).isEmpty() && !"All".equals(q.get("level"))) {
      const lv = this.frostTag(q.get("level"));
      tags.addView(lv);
      Ui.margins(lv, 6, 0, 0, 0);
    }
    hero.addView(tags);
    if (!Ui.nz(q.get("scenario")).isEmpty()) {
      const cs = Ui.tv(this, "CASE", 11, 0xB3FFFFFF, true);
      cs.setLetterSpacing(0.15);
      hero.addView(cs);
      Ui.margins(cs, 0, 14, 0, 0);
      const sc = Ui.tv(this, q.get("scenario"), 15, Color.WHITE, false);
      sc.setLineSpacing(0, 1.15);
      hero.addView(sc);
    }
    const qq = Ui.tv(this, q.get("question"), 17, Color.WHITE, true);
    qq.setLineSpacing(0, 1.1);
    hero.addView(qq);
    Ui.margins(qq, 0, 14, 0, 0);
    page.addView(hero);

    // result banner
    if (mine != null) {
      const right = "1".equals(mine.get("correct"));
      const res = Ui.card(this);
      res.setBackground(Ui.round(this, Ui.alpha(right ? Ui.GREEN : Ui.RED, 0x1F), 18));
      res.addView(Ui.tv(this, right ? "🎉  Correct!" : "Not quite. The answer is " + q.get("answer") + ".", 17, right ? Ui.GREEN : Ui.RED, true));
      res.addView(Ui.muted(this, "You answered " + mine.get("choice") + ".  " + Mcq.percent(ok, n) + "% of " + n + " got it right."
          + (Mcq.streak(db, me) > 1 ? "  🔥 " + Mcq.streak(db, me) + "-day streak" : "")));
      page.addView(res);
    } else if (faculty) {
      page.addView(this.note("You are viewing as faculty: the answer is shown. Students see it after answering."));
    } else {
      page.addView(this.note("Tap an option. Your first answer counts."));
    }

    // options
    const opts = Ui.v(this);
    opts.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), 0);
    for (let i = 0; i < Mcq.LETTERS.length; i++) {
      const l = Mcq.LETTERS[i];
      const text = Ui.nz(q.get("opt_" + l.toLowerCase()));
      if (text.isEmpty()) continue;
      const isAns = l.equals(q.get("answer"));
      const isMine = mine != null && l.equals(mine.get("choice"));
      const pct = Mcq.percent(Mcq.picked(db, qid, l), n);
      const row = this.option(l, text, reveal, isAns, isMine, pct, n > 0 && reveal);
      if (!reveal) {
        row.setOnClickListener({ onClick: (v) => { this.choose(q, l); } });
      }
      opts.addView(row);
    }
    page.addView(opts);

    // explanation
    if (reveal) {
      page.addView(Ui.heading(this, "Explanation", 0xFF6D28D9));
      const ex = Ui.card(this);
      const e = Ui.nz(q.get("explanation"));
      ex.addView(e.isEmpty() ? Ui.muted(this, "The explanation will be added by the faculty.") : Ui.body(this, e));
      if (!Ui.nz(q.get("refs")).isEmpty()) {
        const r = Ui.muted(this, "📖  " + q.get("refs"));
        ex.addView(r);
        Ui.margins(r, 0, 10, 0, 0);
      }
      if (faculty) {
        const ed = Ui.outlineButton(this, e.isEmpty() ? "Add explanation" : "Edit explanation", 0xFF6D28D9, { onClick: (v) => { this.editExplanation(q); } });
        ex.addView(ed);
        Ui.margins(ed, 0, 12, 0, 0);
      }
      page.addView(ex);
    } else {
      const lock = Ui.card(this);
      lock.addView(Ui.muted(this, "🔒  The explanation opens after you answer."));
      page.addView(lock);
    }

    // how the department did (faculty see each response)
    if (reveal) {
      page.addView(Ui.heading(this, "Responses", Ui.SLATE));
      const st = Ui.card(this);
      st.addView(Ui.statRow(this, Ui.stat(this, String(n), "Answered", Ui.PRIMARY),
          Ui.stat(this, String(ok), "Correct", Ui.GREEN),
          Ui.stat(this, String(n - ok), "Wrong", Ui.RED),
          Ui.stat(this, Mcq.percent(ok, n) + "%", "Accuracy", 0xFF6D28D9)));
      page.addView(st);
      if (faculty) {
        const all = db.rows("SELECT * FROM mcq_answers WHERE mcq_id=? ORDER BY correct DESC, time", qid);
        if (!all.isEmpty()) {
          const who = Ui.card(this);
          for (const a of all) {
            const t = Ui.nz(a.get("time"));
            who.addView(Ui.kv(this, ("1".equals(a.get("correct")) ? "✓  " : "✗  ") + a.get("name") + "  ·  " + McqQuestionActivity.role(a.get("role")),
                a.get("choice") + (t.length >= 16 ? "  " + Dates.nice(t.substring(0, 10)).substring(0, 5) + " " + t.substring(11, 16) : "")));
          }
          page.addView(who);
        }
      }
    }

    const more = Ui.v(this);
    more.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), 0);
    more.addView(Ui.outlineButton(this, "All MCQs and top scorers", 0xFF6D28D9, this.opener(McqActivity)));
    if (faculty) {
      const sh = Ui.outlineButton(this, "Share question to WhatsApp", Ui.GREEN, { onClick: (v) => { McqQuestionActivity.share(this, q); } });
      more.addView(sh);
      Ui.margins(sh, 0, 8, 0, 0);
    }
    page.addView(more);
    this.setPage(page);
  }

  static role(r) {
    return "Postgraduate".equals(r) ? "PG" : Ui.nz(r);
  }

  frostTag(s) {
    const t = Ui.tv(this, s, 11, Color.WHITE, true);
    t.setBackground(Glass.frost(this, 12));
    t.setPadding(Ui.dp(this, 10), Ui.dp(this, 3), Ui.dp(this, 10), Ui.dp(this, 3));
    return t;
  }

  note(s) {
    const t = Ui.muted(this, s);
    t.setPadding(Ui.dp(this, 18), Ui.dp(this, 12), Ui.dp(this, 18), Ui.dp(this, 2));
    return t;
  }

  /** An option: letter bubble and text; after answering, a bar shows how many picked it. */
  option(letter, text, reveal, isAns, isMine, pct, showPct) {
    const accent = reveal && isAns ? Ui.GREEN : reveal && isMine ? Ui.RED : 0xFF6D28D9;
    const box = new FrameLayout(this);
    box.setBackground(reveal && (isAns || isMine) ? Ui.outline(this, Ui.alpha(accent, 0x14), Ui.alpha(accent, 0xAA), 16)
        : Ui.outline(this, Ui.CARD, Ui.LINE, 16));
    const blp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    blp.topMargin = Ui.dp(this, 8);
    box.setLayoutParams(blp);
    if (showPct && pct > 0) {
      const bar = new View(this);
      bar.setBackground(Ui.round(this, Ui.alpha(accent, 0x1A), 16));
      box.addView(bar, new FrameLayout.LayoutParams(0, FrameLayout.LayoutParams.MATCH_PARENT));
      const b2 = bar;
      const p2 = pct;
      box.addOnLayoutChangeListener({
        onLayoutChange: (v, l, t, r, bo, ol, ot, or, ob) => {
          const w = Math.trunc((r - l) * p2 / 100);
          if (b2.getLayoutParams().width !== w) {
            b2.getLayoutParams().width = w;
            // requestLayout is a no-op in the browser runtime: re-apply the params so the new width shows
            b2.post({ run: () => { b2.requestLayout(); b2.setLayoutParams(b2.getLayoutParams()); } });
          }
        }
      });
    }
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
    const bub = Ui.tv(this, reveal && isAns ? "✓" : reveal && isMine ? "✗" : letter, 15, reveal && (isAns || isMine) ? Color.WHITE : accent, true);
    bub.setGravity(Gravity.CENTER);
    bub.setBackground(reveal && (isAns || isMine) ? Ui.round(this, accent, 18) : Ui.round(this, Ui.alpha(accent, 0x1F), 18));
    row.addView(bub, Ui.lp(Ui.dp(this, 34), Ui.dp(this, 34)));
    const t = Ui.tv(this, text, 15, Ui.TEXT, reveal && isAns);
    t.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    row.addView(t, Ui.weight(1));
    if (showPct) row.addView(Ui.tv(this, pct + "%", 13, Ui.MUTED, true));
    box.addView(row);
    Ui.ripple(box, Ui.alpha(accent, 0x22));
    return box;
  }

  /** Records the answer; asks who is answering first if this phone does not know. */
  choose(q, letter) {
    const me = SessionAttendance.me(this, this.db);
    if (me == null) {
      const f = new Form(this);
      f.suggest("name", "Your name (as in the student / faculty list)", "", this.db.staffNames(""));
      Ui.formDialog(this, "Who is answering?", f, "Continue", {
        run: () => {
          const who = this.db.row("SELECT * FROM staff WHERE name=? AND " + Approvals.APPROVED_SQL + " LIMIT 1", f.get("name"));
          if (who == null) {
            Ui.toast(this, "Choose your name from the list");
            return false;
          }
          Reminders.prefs(this).edit().putString("name", who.get("name")).apply();
          this.choose(q, letter);
          return true;
        }
      });
      return;
    }
    Mcq.answer(this.db, this, q, me, letter);
    this.render();
  }

  editExplanation(q) {
    const f = new Form(this);
    f.multi("explanation", "Explanation / teaching points", Ui.nz(q.get("explanation")));
    f.text("refs", "Reference", Ui.nz(q.get("refs")), Form.PLAIN);
    Ui.formDialog(this, "Explanation", f, "Save", {
      run: () => {
        const cv = new ContentValues();
        cv.put("explanation", f.get("explanation"));
        cv.put("refs", f.get("refs"));
        this.db.update("mcqs", cv, Long.parseLong(this.qid));
        this.render();
        return true;
      }
    });
  }

  /** Shares the question and options (not the answer), e.g. to the WhatsApp group. */
  static share(a, q) {
    const sb = new StringBuilder("🩺 Daily MCQ · " + Ui.nz(q.get("subject")) + "\n\n");
    if (!Ui.nz(q.get("scenario")).isEmpty()) sb.append(q.get("scenario")).append("\n\n");
    sb.append(q.get("question")).append("\n");
    for (const l of Mcq.LETTERS) {
      const o = Ui.nz(q.get("opt_" + l.toLowerCase()));
      if (!o.isEmpty()) sb.append(l).append(". ").append(o).append("\n");
    }
    sb.append("\nAnswer in the TVMCHMED app.");
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, sb.toString());
    a.startActivity(Intent.createChooser(i, "Share MCQ"));
  }
}
;
