/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The monthly department report for the HOD: admissions, deaths, CMCHIS claims and academics in one PDF or Word file. */
class MonthlyReport {
  static c(t) {
    return new FormDoc.Cell(t);
  }

  static h(t) {
    return new FormDoc.Cell(t).b().fill(0xFFE3F2FD);
  }

  static pct(deaths, out) {
    return out === 0 ? '-' : jfmt('%.1f%%', deaths * 100.0 / out);
  }

  static money(v) {
    // String.format(Locale.ENGLISH, "%,.0f", v): western digit grouping
    return v === 0 ? '-' : '₹' + Math.round(Number(v)).toLocaleString('en-US');
  }

  /** Asks which month, makes the PDF or Word file and offers to share or open it. */
  static choose(a, pdf) {
    const now = YearMonth.from(Dates.today());
    const ms = [now, now.minusMonths(1), now.minusMonths(2), now.minusMonths(3)];
    const names = new Array(ms.length).fill(null);
    for (let i = 0; i < ms.length; i++) names[i] = Dates.month(ms[i].atDay(1)) + (i === 0 ? ' (so far)' : '');
    new AlertDialog.Builder(a).setTitle('Monthly report for')
        .setItems(names, {
          onClick: (d, w) => { MonthlyReport.make(a, ms[w], pdf); }
        }).show();
  }

  static make(a, m, pdf) {
    let rel;
    try {
      const f = MonthlyReport.build(a.db, m);
      rel = pdf ? f.pdf(a) : f.docx(a);
    } catch (e) {
      Ui.toast(a, 'Could not make the report: ' + e.getMessage());
      return;
    }
    const subject = 'Monthly report ' + Dates.month(m.atDay(1));
    new AlertDialog.Builder(a).setTitle((pdf ? 'PDF' : 'Word') + ' report ready')
        .setItems(['Share (WhatsApp, email…)', 'Open'], {
          onClick: (d, w) => {
            if (w === 0) Store.share(a, rel, subject);
            else Store.openWith(a, rel);
          }
        }).setNegativeButton('Close', null).show();
  }

  static build(db, m) {
    const c = MonthlyReport.c, h = MonthlyReport.h, pct = MonthlyReport.pct, money = MonthlyReport.money;
    const a = m.atDay(1).toString(), b = m.atEndOfMonth().toString();
    const f = new FormDoc();
    f.college = db.setting('college', 'Tirunelveli Medical College Hospital');
    f.address = db.setting('address', 'Tirunelveli – 627 011, Tamil Nadu');
    f.dept = db.setting('dept', 'Department of General Medicine');
    f.title = 'MONTHLY DEPARTMENT REPORT · ' + Dates.month(m.atDay(1)).toUpperCase();
    f.footer = Dates.month(m.atDay(1)) + '  •  ' + f.dept + ', ' + f.college;
    f.fileBase = 'Monthly_report_' + m;

    const adm = db.events(Db.ADMIT, a, b, null, null), dis = db.events(Db.DISCHARGE, a, b, null, null), died = db.events(Db.DEATH, a, b, null, null);
    const s = f.block('SUMMARY', FormDoc.NAVY, 0.25, 0.25, 0.25, 0.25);
    s.row(16, h('Admissions'), h('Discharges'), h('Deaths'), h('Mortality'));
    s.row(16, c(String(adm)).b().center(), c(String(dis)).b().center(), c(String(died)).b().center(), c(pct(died, died + dis)).b().center());
    s.row(16, h('Transfers to IMCU'), h('Transfers to CCB'), h('Inpatients now'), h('Head of Department'));
    s.row(16, c(String(db.transfers(a, b, null, Db.IMCU))).center(), c(String(db.transfers(a, b, null, Db.CCB))).center(),
        c(String(db.totalInpatients())).center(), c(db.setting('hod', '')).center());

    const u = f.block('UNIT AND WARD MOVEMENT', 0xFF0F766E, 0.22, 0.13, 0.13, 0.13, 0.13, 0.13, 0.13);
    u.row(14, h('Ward'), h('Admitted'), h('In'), h('Out'), h('Discharged'), h('Deaths'), h('Mortality'));
    const wards = Array.from(Db.WARD_UNITS).concat(Array.from(Db.SPECIAL));
    for (const w of wards) {
      const ad = db.events(Db.ADMIT, a, b, Db.isWardUnit(w) ? 'from_loc' : 'to_loc', w), inn = db.transfers(a, b, null, w), out = db.transfers(a, b, w, null);
      const ds = db.events(Db.DISCHARGE, a, b, 'from_loc', w), dd = db.events(Db.DEATH, a, b, 'from_loc', w);
      if (ad + inn + out + ds + dd === 0) continue;
      u.row(14, c(Db.unitName(w)).b(), c(String(ad)).center(), c(String(inn)).center(), c(String(out)).center(),
          c(String(ds)).center(), c(String(dd)).center(), c(pct(dd, dd + ds)).center());
    }

    const deaths = db.rows('SELECT e.date, e.from_loc, p.name, p.age, p.sex, p.ip_no, p.home_unit, p.outcome_note, p.diagnosis FROM events e '
        + 'JOIN patients p ON p.id = e.patient_id WHERE e.type=? AND e.date BETWEEN ? AND ? ORDER BY e.date', Db.DEATH, a, b);
    const d = f.block('DEATHS  ·  ' + deaths.size(), 0xFF475569, 0.05, 0.12, 0.25, 0.12, 0.46);
    d.row(14, h('No'), h('Date'), h('Name, age, IP'), h('Unit / place'), h('Cause of death'));
    if (deaths.isEmpty()) d.row(14, c('Nil').span(5));
    let i = 0;
    for (const r of deaths) {
      const cause = Ui.nz(r.get('outcome_note')).isEmpty() ? Ui.nz(r.get('diagnosis')) : r.get('outcome_note');
      d.row(14, c(String(++i)), c(Dates.nice(r.get('date'))), c(Ui.nz(r.get('name')) + ', ' + Ui.nz(r.get('age')) + ' ' + Ui.nz(r.get('sex'))
          + (Ui.nz(r.get('ip_no')).isEmpty() ? '' : '\nIP ' + r.get('ip_no'))), c(Ui.nz(r.get('home_unit')) + ' / ' + Db.shortName(r.get('from_loc'))), c(cause.split('\n').join(' ')));
    }

    const cm = f.block('CMCHIS CLAIMS', 0xFFBE185D, 0.2, 0.12, 0.12, 0.12, 0.12, 0.16, 0.16);
    cm.row(14, h('Unit'), h('Cases'), h('Approved'), h('Awaiting'), h('Rejected'), h('Approved amount'), h('Credited'));
    let ct = 0, ca = 0, cw = 0, cr = 0;
    let am = 0, cred = 0;
    const cu = Array.from(Db.WARD_UNITS).concat([Db.IMCU]);
    for (const w of cu) {
      const n = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ?', w, a, b);
      if (n === 0) continue;
      const ap = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND ' + CmchisStages.APPROVED_SQL, w, a, b);
      const aw = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND ' + CmchisStages.AWAITING_SQL, w, a, b);
      const rj = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND status=?', w, a, b, CmchisStages.REJECTED);
      const amt = db.dbl('SELECT COALESCE(SUM(amount),0) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND ' + CmchisStages.APPROVED_SQL, w, a, b);
      const cr1 = db.dbl('SELECT COALESCE(SUM(credited),0) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ?', w, a, b);
      cm.row(14, c(Db.unitName(w)).b(), c(String(n)).center(), c(String(ap)).center(), c(String(aw)).center(), c(String(rj)).center(),
          c(money(amt)).center(), c(money(cr1)).center());
      ct += n; ca += ap; cw += aw; cr += rj; am += amt; cred += cr1;
    }
    if (ct === 0) cm.row(14, c('No CMCHIS cases this month').span(7));
    else cm.row(14, c('Total').b(), c(String(ct)).b().center(), c(String(ca)).b().center(), c(String(cw)).b().center(),
        c(String(cr)).b().center(), c(money(am)).b().center(), c(money(cred)).b().center());

    const ac = f.block('ACADEMICS', 0xFF7C3AED, 0.28, 0.12, 0.6);
    ac.row(14, h('Activity'), h('Number'), h('Topics'));
    for (const k of db.rows("SELECT kind, COUNT(*) AS n, GROUP_CONCAT(topic, '; ') AS topics FROM academics WHERE date BETWEEN ? AND ? GROUP BY kind ORDER BY kind", a, b))
      ac.row(14, c(Ui.nz(k.get('kind'))).b(), c(k.get('n')).center(), c(Ui.nz(k.get('topics'))));
    for (const k of db.rows("SELECT kind, COUNT(*) AS n, GROUP_CONCAT(topic, '; ') AS topics FROM classes WHERE date BETWEEN ? AND ? GROUP BY kind ORDER BY kind", a, b))
      ac.row(14, c(('PG'.equals(k.get('kind')) ? 'PG' : 'MBBS') + ' classes').b(), c(k.get('n')).center(), c(Ui.nz(k.get('topics'))));
    ac.row(14, c('Daily MCQs posted').b(), c(String(db.num('SELECT COUNT(*) FROM mcqs WHERE date BETWEEN ? AND ?', a, b))).center(),
        c(db.num('SELECT COUNT(*) FROM mcq_answers a JOIN mcqs q ON q.id = a.mcq_id WHERE q.date BETWEEN ? AND ?', a, b) + ' answers'));
    ac.row(14, c('Session check-ins').b(), c(String(db.num('SELECT COUNT(*) FROM acad_attendance t JOIN academics s ON s.id = t.academic_id WHERE s.date BETWEEN ? AND ?', a, b))).center(),
        c('Physicon / journal club attendance taken in the app'));
    ac.row(14, c('PG logbook procedures signed').b(), c(String(db.num('SELECT COUNT(*) FROM logbook WHERE status=? AND date BETWEEN ? AND ?', Logbook.SIGNED, a, b))).center(),
        c(db.num('SELECT COUNT(DISTINCT staff_id) FROM logbook WHERE date BETWEEN ? AND ?', a, b) + ' PGs logged procedures'));

    const o = f.block('OTHER SERVICES', 0xFF0369A1, 0.5, 0.5);
    o.row(14, c('Call overs answered for other departments').b(), c(String(db.num('SELECT COUNT(*) FROM callover WHERE date BETWEEN ? AND ?', a, b))));
    o.row(14, c('OG block cases seen (obstetric physician)').b(), c(String(db.num('SELECT COUNT(*) FROM og_cases WHERE date BETWEEN ? AND ?', a, b))));
    o.row(14, c('Kandiyaperi OP / IP').b(), c(db.num('SELECT COALESCE(SUM(COALESCE(new_m,0)+COALESCE(new_f,0)+COALESCE(review,0)),0) FROM kdp_op WHERE date BETWEEN ? AND ?', a, b) + ' OP  ·  ' + db.events(Db.ADMIT, a, b, 'to_loc', Db.KDP) + ' IP'));
    o.row(14, c('Achievements recorded').b(), c(String(db.num('SELECT COUNT(*) FROM achievements WHERE date BETWEEN ? AND ?', a, b))));
    return f;
  }
}
;
/* ---- app/MorningBrief.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The 7:30 AM ward-round brief (8.30): for one unit (or all), what happened since yesterday's 7:30 AM and who to see first. Built
 * on the phone from the records (new admissions, NEWS2, the deterioration watch, abnormal labs of the last 24 hours, last night's
 * handover, overdue tasks); an AI can turn it into a short spoken-style summary with the names left out.
 */
class MorningBrief {
  static COLOR = 0xFFEA580C;
  static HERO = [0xFF9A3412, 0xFFEA580C, 0xFFF59E0B];
  static $clinit() {
    MorningBrief.START = Dates.CHANGEOVER;
  }

  /** Yesterday's 7:30 AM (the start of the duty that just ended). */
  static windowStart(now) {
    const d = now.toLocalTime().isBefore(MorningBrief.START) ? now.toLocalDate().minusDays(1) : now.toLocalDate();
    return LocalDateTime.of(d.minusDays(1), MorningBrief.START);
  }

  /** The member's own unit from their staff entry, or "" (all units). */
  static myUnit(c, db) {
    const u = Cloud.unitOf(db, Cloud.myStaff(c));
    return u == null ? "" : u;
  }

  static inUnit(p, unit) {
    return unit.isEmpty() || unit.equals(p.get("home_unit")) || unit.equals(p.get("location"));
  }

  static build(db, unit, now) {
    const b = new MorningBrief.Brief();
    b.unit = Ui.nz(unit);
    b.from = MorningBrief.windowStart(now);
    b.to = now;
    const fromDay = b.from.toLocalDate().toString();
    for (const e of db.rows("SELECT e.*, p.home_unit, p.location FROM events e JOIN patients p ON p.id=e.patient_id WHERE e.date>=?", fromDay)) {
      const t = Watch.at(e.get("date"), e.get("time"));
      if (t == null || t.isBefore(b.from) || !MorningBrief.inUnit(e, b.unit)) continue;
      const type = Ui.nz(e.get("type"));
      if (type.equals(Db.DISCHARGE)) b.discharged++;
      else if (type.equals(Db.DEATH)) b.died++;
    }
    for (const p of db.rows("SELECT * FROM patients WHERE status='IN' ORDER BY id")) {
      if (!MorningBrief.inUnit(p, b.unit)) continue;
      b.inpatients++;
      const pid = Long.parseLong(p.get("id"));
      const it = new MorningBrief.Item();
      it.p = p;
      const adm = db.row("SELECT date, time, to_loc FROM events WHERE patient_id=? AND type=? ORDER BY id DESC LIMIT 1", p.get("id"), Db.ADMIT);
      const at = adm == null ? null : Watch.at(adm.get("date"), adm.get("time"));
      if (at != null && !at.isBefore(b.from)) {
        b.admitted++;
        it.score += 2;
        it.why.add("New admission " + (at.toLocalDate().equals(now.toLocalDate()) ? "today" : "yesterday") + " " + at.toLocalTime());
      }
      const ew = Ews.latest(db, pid, now);
      if (ew != null && ew.flagged()) {
        if (ew.red()) b.red++;
        else b.amber++;
        it.score += ew.red() ? 5 : 3;
        it.why.add(ew.label());
      }
      for (const f of Watch.check(db, pid, now, true)) {
        it.score += f.red ? 3 : 2;
        it.why.add(f.text);
      }
      const abn = [];
      for (const l of db.rows("SELECT * FROM labs WHERE patient_id=? AND date>=? ORDER BY date DESC, time DESC LIMIT 2", p.get("id"), fromDay)) {
        const t = Watch.at(l.get("date"), l.get("time"));
        if (t == null || t.isBefore(now.minusHours(24))) continue;
        for (const q of Labs.PARAMS) {
          const v = Labs.num(l.get(q.key));
          if (v == null || !Labs.abnormal(q, v)) continue;
          const s = q.name + " " + Labs.fmt(v) + (v < q.lo ? "↓" : "↑");
          if (!abn.contains(s)) abn.add(s);
        }
      }
      if (!abn.isEmpty()) {
        it.score += Math.min(3, abn.size());
        it.why.add("Labs: " + TextUtils.join(", ", abn));
      }
      for (const h of db.rows("SELECT * FROM handovers WHERE patient_id=? AND day>=? ORDER BY id DESC LIMIT 2", p.get("id"), fromDay)) {
        it.score += 2;
        it.why.add("Handover: " + Ui.nz(h.get("kind")) + (Ui.nz(h.get("note")).isEmpty() ? "" : " – " + h.get("note")));
      }
      const due = db.num("SELECT COUNT(*) FROM tasks WHERE patient_id=? AND done='' AND due<>'' AND due<=?", p.get("id"), now.toLocalDate().toString());
      if (due > 0) {
        it.score += 1;
        it.why.add(due + (due === 1 ? " task due" : " tasks due"));
      }
      if (it.score > 0) b.first.add(it);
    }
    Collections.sort(b.first, {
      compare: (x, y) => y.score - x.score
    });
    return b;
  }

  static where(p) {
    return Db.shortName(p.get("location")) + (Ui.nz(p.get("bed")).isEmpty() ? "" : " bed " + p.get("bed"));
  }

  static title(b) {
    return "Morning brief · " + (b.unit.isEmpty() ? "All units" : Db.unitName(b.unit)) + " · " + Dates.nice(b.to.toLocalDate().toString());
  }

  static counts(b) {
    return b.inpatients + " in-patients  ·  " + b.admitted + " admitted  ·  " + b.discharged + " discharged" + (b.died > 0 ? "  ·  " + b.died + " died" : "")
        + (b.red + b.amber > 0 ? "  ·  NEWS raised " + (b.red + b.amber) : "");
  }

  /** The brief for WhatsApp (names included: it goes to the team's own group). */
  static text(b) {
    const s = new StringBuilder("*🌅 ").append(MorningBrief.title(b)).append("*\n").append(MorningBrief.counts(b)).append("\n");
    if (b.first.isEmpty()) s.append("\nA quiet night: nobody flagged to see first.");
    else s.append("\n*See first:*\n");
    let k = 1;
    for (const it of b.first) {
      s.append(k++).append(". ").append(Ui.nz(it.p.get("name"))).append(", ").append(MorningBrief.where(it.p)).append(" – ")
          .append(TextUtils.join("; ", it.why)).append("\n");
      if (k > 15) break;
    }
    return s.toString().trim();
  }

  static AI_MARK = "You are the senior resident giving the 7:30 AM ward-round brief";

  static aiSystem() {
    return MorningBrief.AI_MARK + " in the Department of General Medicine at Tirunelveli Medical College Hospital. From the list below write a short "
        + "brief that a consultant can read in one minute: one line on the night (numbers), then the patients to see first in order of "
        + "urgency, one line each with the reason and the one thing to do or check now. Use only the facts given; do not add values or "
        + "diagnoses. Patients are named only by their code (P1, P2): keep the codes. Plain lines, no markdown, no asterisks.";
  }

  /** The brief with names, IP numbers and beds left out: P-codes, age, sex, diagnosis and reasons only. */
  static aiUser(b) {
    const s = new StringBuilder(MorningBrief.title(b)).append("\n").append(MorningBrief.counts(b)).append("\n\n");
    let k = 1;
    for (const it of b.first) {
      s.append("P").append(k++).append(" | ").append(Ui.nz(it.p.get("age"))).append(Ui.nz(it.p.get("sex"))).append(" | ")
          .append(Ui.nz(it.p.get("diagnosis"))).append(" | ").append(TextUtils.join("; ", it.why)).append("\n");
      if (k > 15) break;
    }
    return s.toString();
  }

  /** P-codes in the AI's brief turned back into names and beds on this phone. */
  static decode(b, text) {
    let t = Ui.nz(text);
    for (let k = Math.min(15, b.first.size()); k >= 1; k--) {
      const p = b.first.get(k - 1).p;
      const rep = Ui.nz(p.get("name")) + " (" + MorningBrief.where(p) + ")";
      t = t.replaceAllRx("\\bP" + k + "\\b", () => rep);   // the name taken literally (Matcher.quoteReplacement)
    }
    return t;
  }

  /** Home card from 7:30 AM to 1 PM. */
  static homeCard(a, db) {
    const now = Dates.time();
    if (now.isBefore(MorningBrief.START) || now.getHour() >= 13) return null;
    const b = MorningBrief.build(db, MorningBrief.myUnit(a, db), LocalDateTime.of(Dates.today(), now));
    if (b.inpatients === 0) return null;
    const card = Ui.card(a);
    card.setBackground(Glass.hero(a, MorningBrief.HERO, 20));
    card.addView(Ui.tv(a, "🌅  Morning brief" + (b.unit.isEmpty() ? "" : " · " + Db.unitName(b.unit)), 18, Color.WHITE, true));
    card.addView(Ui.tv(a, MorningBrief.counts(b), 12, 0xE6FFFFFF, false));
    const first = Ui.tv(a, b.first.isEmpty() ? "A quiet night: nobody flagged to see first." : b.first.size() + (b.first.size() === 1 ? " patient" : " patients") + " to see first"
        + (b.first.isEmpty() ? "" : ": " + Ui.nz(b.first.get(0).p.get("name")) + " (" + b.first.get(0).why.get(0) + ")" + (b.first.size() > 1 ? "…" : "")), 14, Color.WHITE, true);
    card.addView(first);
    Ui.margins(first, 0, 8, 0, 0);
    card.setOnClickListener(a.opener(MorningBriefActivity));
    Ui.ripple(card, 0x33FFFFFF);
    return card;
  }
}
MorningBrief.Item = class {
  constructor() {
    this.p = null;
    this.score = 0;
    this.why = [];
  }
};
MorningBrief.Brief = class {
  constructor() {
    this.unit = "";
    this.from = null; this.to = null;
    this.inpatients = 0; this.admitted = 0; this.discharged = 0; this.died = 0; this.red = 0; this.amber = 0;
    this.first = [];
  }
};
;
/* ---- app/MorningBriefActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The 7:30 AM ward-round brief for a unit: the night in numbers, who to see first and why, an AI summary, WhatsApp. */
class MorningBriefActivity extends Base {
  constructor() { super(); this.unit = null; }

  static WAIT = "brief_wait";

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Morning brief");
    this.subtitle = "Since yesterday 7:30 AM";
    this.headerColors = MorningBrief.HERO;
    this.unit = b != null ? b.getString("unit", null) : null;
    if (this.unit == null) this.unit = MorningBrief.myUnit(this, this.db);
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putString("unit", this.unit);
  }

  aiKey(b) {
    return "brief_ai_" + b.to.toLocalDate() + "_" + (b.unit.isEmpty() ? "all" : b.unit);
  }

  render() {
    const WAIT = MorningBriefActivity.WAIT;
    const b = MorningBrief.build(this.db, this.unit, LocalDateTime.of(Dates.today(), Dates.time()));
    const page = Ui.v(this);

    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
    const units = [""].concat(Db.UNITS);
    for (const u of units) {
      const c = Ui.chip(this, u.isEmpty() ? "All" : Db.shortName(u), u.equals(this.unit), MorningBrief.COLOR);
      c.setOnClickListener({
        onClick: (v) => {
          this.unit = u;
          this.render();
        }
      });
      chips.addView(c);
      Ui.margins(c, 0, 0, 6, 0);
    }
    const hs = new HorizontalScrollView(this);
    hs.setHorizontalScrollBarEnabled(false);
    hs.addView(chips);
    page.addView(hs);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, MorningBrief.HERO, 20));
    hero.addView(Ui.tv(this, "🌅  " + (b.unit.isEmpty() ? "All units" : Db.unitName(b.unit)), 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, MorningBrief.counts(b), 13, 0xE6FFFFFF, false));
    hero.addView(Ui.tv(this, "From " + Dates.nice(b.from.toLocalDate().toString()) + " 7:30 AM to now", 12, 0xCCFFFFFF, false));
    page.addView(hero);

    // the AI's one-minute version
    const key = this.aiKey(b);
    const ai = Ai.prefs(this).getString(key, "");
    const ac = Ui.card(this);
    ac.addView(Ui.title(this, "✨  One-minute brief"));
    if (!ai.isEmpty()) {
      const t = Ui.tv(this, ai, 14, Ui.TEXT, false);
      t.setTextIsSelectable(true);
      ac.addView(t);
      Ui.margins(t, 0, 6, 0, 0);
      ac.addView(Ui.muted(this, "Written by " + Ai.prefs(this).getString(key + "_by", "AI") + " from the list below (names were left out). Check it."));
    } else {
      ac.addView(Ui.muted(this, "An AI writes the list below as a short brief for the consultant. Names, IP numbers and beds are not sent."));
    }
    const app = AiRun.waiting(this, WAIT);
    const ab = Ui.buttonRow(this, Ui.button(this, ai.isEmpty() ? "✨ Write it" : "✨ Write again", Ui.PURPLE, {
      onClick: (v) => {
        if (b.first.isEmpty()) {
          Ui.toast(this, "Nobody is flagged: nothing for the AI to write");
          return;
        }
        AiRun.ask(this, "Morning brief", MorningBrief.aiSystem(), MorningBrief.aiUser(b), 4000, WAIT, null, {
          got: (text, who) => { this.keepAi(b, text, who); }
        });
      }
    }));
    if (!app.isEmpty()) ab.addView(Ui.outlineButton(this, "Paste " + app + "'s answer", Ui.PURPLE, {
      onClick: (v) => {
        const t = AiRun.paste(this, WAIT, MorningBrief.AI_MARK);
        if (t != null) this.keepAi(b, t, app + " (AI)");
      }
    }));
    ac.addView(ab);
    Ui.margins(ab, 0, 8, 0, 0);
    page.addView(ac);

    page.addView(Ui.heading(this, b.first.isEmpty() ? "Nobody flagged" : "See first  ·  " + b.first.size(), MorningBrief.COLOR));
    let k = 1;
    for (const it of b.first) {
      const why = new StringBuilder();
      for (const w of it.why) why.append(why.length() === 0 ? "" : "\n").append("• ").append(w);
      page.addView(this.entryCard((k++) + "", it.score >= 5 ? Ui.RED : MorningBrief.COLOR, Ui.nz(it.p.get("name")) + "  ·  " + Ui.nz(it.p.get("age")) + Ui.nz(it.p.get("sex")),
          MorningBrief.where(it.p) + "  ·  " + Ui.nz(it.p.get("diagnosis")) + "\n" + why, Ui.nz(it.p.get("home_unit")),
          this.opener(PatientActivity, "id", it.p.get("id")), 20));
    }
    if (b.first.isEmpty()) page.addView(this.emptyNote("No new admission, raised NEWS, worsening trend, abnormal lab or handover item since yesterday 7:30 AM."));

    const sh = Ui.v(this);
    sh.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), 0);
    sh.addView(Ui.button(this, "Share on WhatsApp", Ui.GREEN, {
      onClick: (v) => {
        const ai2 = Ai.prefs(this).getString(key, "");
        ReportActivity.shareText(this, MorningBrief.text(b) + (ai2.isEmpty() ? "" : "\n\n*Brief:*\n" + ai2));
      }
    }));
    page.addView(sh);
    this.setPage(page);
  }

  keepAi(b, text, who) {
    if (text == null) return;
    Ai.prefs(this).edit().putString(this.aiKey(b), MorningBrief.decode(b, Ai.clean(text))).putString(this.aiKey(b) + "_by", who).apply();
    this.render();
  }
}
;
/* ---- app/MyMonth.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * My month (10.17, user's pick 201): a PG's monthly work record that fills itself from what they already entered: the case sheets they
 * wrote, progress notes, procedures in the logbook, academics attended, presentations, exam cases presented and faculty likes. A PDF or
 * Word file to submit, with places for the unit Assistant Professor's and the HOD's signatures. No patient names, only IP numbers.
 */
class MyMonth {
  static COLOR = 0xFF4338CA;
  static HEAD = 0xFF312E81;

  static within(d, d0, d1) {
    if (Ui.nz(d).length < 10) return false;
    const x = d.substring(0, 10);
    return x.compareTo(d0) >= 0 && x.compareTo(d1) <= 0;
  }

  static same(name, me) {
    return !me.isEmpty() && Wrapped.names(name, me);
  }

  /** Everything this person did between d0 and d1 (inclusive, ISO dates). */
  static collect(db, staffId, name, d0, d1) {
    const out = new MyMonth.Data();
    const me = Wrapped.norm(name);
    const sid = Ui.nz(staffId);
    for (const r of db.rows("SELECT c.data, p.admit_date, p.ip_no, p.age, p.sex, p.diagnosis, p.home_unit FROM case_sheets c LEFT JOIN patients p ON p.id=c.id "
      + "WHERE substr(IFNULL(c.updated,''),1,10)>=? ORDER BY p.admit_date", d0)) {
      let o;
      try {
        o = new JSONObject(Ui.nz(r.get("data")));
      } catch (e) {
        continue;
      }
      if (MyMonth.same(CaseSheet.s(o, "wb_name"), me) && MyMonth.within(r.get("admit_date"), d0, d1)) {
        const fdx = CaseSheet.s(o, "final_dx");
        if (!fdx.isEmpty()) out.finalDx++;
        out.cases.add([Dates.nice(r.get("admit_date")), Ui.nz(r.get("ip_no")), Ui.nz(r.get("age")) + " " + Ui.nz(r.get("sex")),
          fdx.isEmpty() ? Ui.nz(r.get("diagnosis")) : fdx, Db.shortName(Ui.nz(r.get("home_unit")))]);
      }
      const a = o.optJSONArray(CaseSheet.PROGRESS);
      if (a == null) continue;
      for (let i = 0; i < a.length(); i++) {
        const n = a.optJSONObject(i);
        if (n != null && MyMonth.within(CaseSheet.s(n, "date"), d0, d1) && MyMonth.same(CaseSheet.s(n, "by"), me)) out.notes++;
      }
    }
    for (const r of db.rows("SELECT * FROM logbook WHERE date BETWEEN ? AND ? ORDER BY date, id", d0, d1)) {
      if (!(sid.length > 0 && sid === r.get("staff_id") || MyMonth.same(r.get("pg"), me))) continue;
      out.procs.add([Dates.nice(r.get("date")), Ui.nz(r.get("procedure")), Ui.nz(r.get("role")), Ui.nz(r.get("supervisor")), Ui.nz(r.get("status"))]);
    }
    for (const r of db.rows("SELECT t.staff_id, t.name, t.time, a.date, a.kind, a.topic FROM acad_attendance t LEFT JOIN academics a ON a.id=t.academic_id "
      + "WHERE IFNULL(t.status,'Present') IN ('Present','') ORDER BY t.time")) {
      const day = Ui.nz(r.get("date")).isEmpty() ? Ui.nz(r.get("time")) : r.get("date");
      if (!MyMonth.within(day, d0, d1)) continue;
      if (!(sid.length > 0 && sid === r.get("staff_id") || MyMonth.same(r.get("name"), me))) continue;
      const k = Array.from(Db.ACAD_KINDS).indexOf(Ui.nz(r.get("kind")));
      out.acads.add([Dates.nice(day.substring(0, 10)), k >= 0 ? Db.ACAD_LABELS[k] : Ui.nz(r.get("kind")), Ui.nz(r.get("topic"))]);
    }
    for (const r of db.rows("SELECT date, title, kind, presenter FROM acad_files WHERE date BETWEEN ? AND ? ORDER BY date", d0, d1))
      if (MyMonth.same(r.get("presenter"), me)) out.pres.add([Dates.nice(r.get("date")), Ui.nz(r.get("kind")), Ui.nz(r.get("title"))]);
    // exam cases presented, by the student's name
    for (const r of db.rows("SELECT a.date, a.student, a.faculty, e.kind, e.system FROM exam_allots a LEFT JOIN exam_cases e ON e.id=a.case_id "
      + "WHERE a.date BETWEEN ? AND ? AND a.presented='1' ORDER BY a.date", d0, d1))
      if (MyMonth.same(r.get("student"), me)) out.exams.add([Dates.nice(r.get("date")), (Ui.nz(r.get("kind")) + " " + Ui.nz(r.get("system"))).trim(), Ui.nz(r.get("faculty"))]);
    for (const r of db.rows("SELECT to_staff, to_name FROM " + Kudos.TABLE + " WHERE substr(time,1,10) BETWEEN ? AND ?", d0, d1))
      if (sid.length > 0 && sid === r.get("to_staff") || MyMonth.same(r.get("to_name"), me)) out.likes++;
    return out;
  }

  static c(t) { return new FormDoc.Cell(t).size(8.5); }
  static h(t) { return new FormDoc.Cell(t).b().size(8.5).fill(0xFFE0E7FF).color(MyMonth.HEAD); }

  static build(db, staffId, name, unit, ym) {
    const c = MyMonth.c, h = MyMonth.h, HEAD = MyMonth.HEAD;
    const d0 = ym.atDay(1).toString(), d1 = ym.atEndOfMonth().toString();
    const d = MyMonth.collect(db, staffId, name, d0, d1);
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College");
    f.address = "Tirunelveli";
    f.dept = db.setting("dept", "Department of General Medicine");
    const month = Dates.month(ym.atDay(1));
    f.title = "PG MONTHLY WORK RECORD  —  " + month.toUpperCase();
    f.footer = "Filled from the entries in TVMCHMED  •  " + f.dept + ", " + f.college;
    f.fileBase = "My_month_" + Ui.nz(name).replaceAllRx("[^A-Za-z0-9]+", "_") + "_" + ym;
    const a = f.block("POSTGRADUATE", HEAD, 0.2, 0.3, 0.2, 0.3);
    a.row(16, h("Name"), c(name).b(), h("Unit"), c(Db.unitName(unit)));
    a.row(16, h("Month"), c(month), h("PG year"), c(MyMonth.pgYear(db, staffId)));
    const s = f.block("SUMMARY", HEAD, 0.25, 0.25, 0.25, 0.25);
    s.row(16, h("Cases clerked"), c(String(d.cases.size())), h("Final diagnosis written"), c(String(d.finalDx)));
    s.row(16, h("Progress notes"), c(String(d.notes)), h("Procedures"), c(String(d.procs.size())));
    s.row(16, h("Academics attended"), c(String(d.acads.size())), h("Presentations"), c(String(d.pres.size())));
    s.row(16, h("Exam cases presented"), c(String(d.exams.size())), h("Faculty likes"), c(String(d.likes)));

    const cb = f.block("CASES CLERKED (case sheets written)", HEAD, 0.06, 0.14, 0.14, 0.12, 0.44, 0.1);
    cb.row(15, h("No."), h("Admitted"), h("IP number"), h("Age / sex"), h("Diagnosis"), h("Unit"));
    if (d.cases.isEmpty()) cb.row(15, c("None this month").span(6));
    for (let i = 0; i < d.cases.size(); i++) {
      const x = d.cases.get(i);
      cb.row(15, c(String(i + 1)), c(x[0]), c(x[1]), c(x[2]), c(x[3]), c(x[4]));
    }
    const pb = f.block("PROCEDURES (logbook)", HEAD, 0.06, 0.14, 0.28, 0.22, 0.18, 0.12);
    pb.row(15, h("No."), h("Date"), h("Procedure"), h("Role"), h("Supervisor"), h("Status"));
    if (d.procs.isEmpty()) pb.row(15, c("None this month").span(6));
    for (let i = 0; i < d.procs.size(); i++) {
      const x = d.procs.get(i);
      pb.row(15, c(String(i + 1)), c(x[0]), c(x[1]), c(x[2]), c(x[3]), c(x[4]));
    }
    const ab = f.block("ACADEMICS ATTENDED", HEAD, 0.06, 0.16, 0.26, 0.52);
    ab.row(15, h("No."), h("Date"), h("Activity"), h("Topic"));
    if (d.acads.isEmpty()) ab.row(15, c("None marked this month").span(4));
    for (let i = 0; i < d.acads.size(); i++) {
      const x = d.acads.get(i);
      ab.row(15, c(String(i + 1)), c(x[0]), c(x[1]), c(x[2]));
    }
    if (!d.pres.isEmpty() || !d.exams.isEmpty()) {
      const xb = f.block("PRESENTATIONS AND EXAM CASES", HEAD, 0.06, 0.16, 0.26, 0.52);
      xb.row(15, h("No."), h("Date"), h("Kind"), h("Title / presented to"));
      let i = 0;
      for (const x of d.pres) xb.row(15, c(String(++i)), c(x[0]), c(x[1].isEmpty() ? "Presentation" : x[1]), c(x[2]));
      for (const x of d.exams) xb.row(15, c(String(++i)), c(x[0]), c("Exam case " + x[1]), c(x[2]));
    }
    const sg = f.block("SIGNATURES", HEAD, 0.34, 0.33, 0.33);
    sg.row(15, h("Postgraduate"), h("Unit Assistant Professor"), h("Head of the Department"));
    sg.row(46, c("").bottom(), c("").bottom(), c("").bottom());
    sg.keep = true;
    return f;
  }

  static pgYear(db, staffId) {
    const s = db.row("SELECT batch FROM staff WHERE id=?", Ui.nz(staffId));
    const y = s == null ? 0 : CaseSheet.pgYear(Ui.nz(s.get("batch")), Dates.today());
    return y <= 0 ? "—" : y === 1 ? "1st year" : y === 2 ? "2nd year" : "3rd year (final)";
  }

  /** From the logbook: the person (a PG themselves, or any PG for faculty), the month and PDF or Word, then shares the file. */
  static offer(a, db) {
    const mine = Logbook.myPg(a, db);
    const pgs = mine > 0 ? db.rows("SELECT id, name, unit FROM staff WHERE id=?", String(mine))
      : Logbook.canSign(a) ? db.rows("SELECT id, name, unit FROM staff WHERE role IN ('Postgraduate','CRMI') AND " + Approvals.APPROVED_SQL + " ORDER BY name") : [];
    if (pgs.isEmpty()) {
      Ui.toast(a, "Only for PGs and CRMIs (and faculty, for their PGs). Link your account to your name in Students first.");
      return;
    }
    const f = new Form(a);
    f.view.addView(Ui.muted(a, "Filled from what is already in the app: case sheets you wrote, progress notes, logbook procedures, "
      + "academics attended, presentations and exam cases. Patient names are left out."));
    const ids = new Array(pgs.size()).fill(null), names = new Array(pgs.size()).fill(null);
    for (let i = 0; i < pgs.size(); i++) { ids[i] = pgs.get(i).get("id"); names[i] = Ui.nz(pgs.get(i).get("name")); }
    f.choice("pg", "PG / CRMI", names, ids, ids[0], null);
    if (pgs.size() === 1) f.show("pg", false);
    const now = YearMonth.from(Dates.today());
    const mv = new Array(4).fill(null), ml = new Array(4).fill(null);
    for (let i = 0; i < 4; i++) { mv[i] = now.minusMonths(i).toString(); ml[i] = Dates.month(now.minusMonths(i).atDay(1)); }
    f.choice("month", "Month", ml, mv, Dates.today().getDayOfMonth() <= 5 ? mv[1] : mv[0], null);
    f.segment("fmt", "File", ["PDF", "Word"], "PDF");
    Ui.formDialog(a, "📄 My month", f, "Make it", {
      run: () => {
        let who = null;
        for (const p of pgs) if (p.get("id") === f.get("pg")) who = p;
        if (who == null) who = pgs.get(0);
        try {
          const doc = MyMonth.build(db, who.get("id"), Ui.nz(who.get("name")), Ui.nz(who.get("unit")), YearMonth.parse(f.get("month")));
          const rel = "Word" === f.get("fmt") ? doc.docx(a) : doc.pdf(a);
          Store.share(a, rel, "Monthly work record");
        } catch (e) {
          Ui.toast(a, "Could not make it: " + e.getMessage());
        }
        return true;
      }
    });
  }

  /** One line for the logbook screen: this month so far. */
  static line(c, db) {
    const mine = Logbook.myPg(c, db);
    if (mine <= 0) return "Fills itself from your entries: cases, notes, procedures, academics";
    const s = db.row("SELECT name FROM staff WHERE id=?", String(mine));
    const ym = YearMonth.from(Dates.today());
    const d = MyMonth.collect(db, String(mine), s == null ? "" : Ui.nz(s.get("name")), ym.atDay(1).toString(), ym.atEndOfMonth().toString());
    return "This month so far: " + d.cases.size() + " cases, " + d.notes + " notes, " + d.procs.size() + " procedures, " + d.acads.size() + " academics";
  }
}

MyMonth.Data = class {
  constructor() {
    this.cases = []; this.procs = []; this.acads = []; this.pres = []; this.exams = [];
    this.notes = 0; this.likes = 0; this.finalDx = 0;
  }

  total() {
    return this.cases.size() + this.procs.size() + this.acads.size() + this.pres.size() + this.exams.size() + this.notes;
  }
};
;
/* ---- app/Mystery.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Mystery Case (10.0): faculty set a de-identified case for a day. One clue opens every 3 hours (9 AM history, 12 PM
 * examination, 3 PM investigations, 6 PM imaging or the key test); a right guess scores 40, 30, 20 or 10 points by the clue it
 * came at. The answer, the teaching points and who solved it open at 9 PM.
 */
class Mystery {
  static TABLE = "mysteries";
  static GUESSES = "mystery_guesses";
  static COLOR = 0xFF0F766E;
  static GRADIENT = [0xFF042F2E, 0xFF0F766E, 0xFF14B8A6];
  static CLUE_HOURS = [9, 12, 15, 18];
  static REVEAL_HOUR = 21;
  static POINTS = [40, 30, 20, 10];
  static CLUE_NAMES = ["History", "Examination", "Investigations", "Imaging / key test"];

  static canSet(c) {
    return SessionAttendance.canRun(c);
  }

  static forDay(db, iso) {
    return db.row("SELECT * FROM " + Mystery.TABLE + " WHERE day=? ORDER BY id DESC LIMIT 1", iso);
  }

  static today(db) {
    return Mystery.forDay(db, Dates.todayIso());
  }

  /** Clues open now for a mystery of that day: all for a past day, none for a coming one. */
  static cluesOpen(m, now) {
    const cmp = Ui.nz(m.get("day")).compareTo(now.toLocalDate().toString());
    if (cmp < 0) return 4;
    if (cmp > 0) return 0;
    let n = 0;
    for (const h of Mystery.CLUE_HOURS) if (!now.toLocalTime().isBefore(LocalTime.of(h, 0))) n++;
    return n;
  }

  static revealed(m, now) {
    const cmp = Ui.nz(m.get("day")).compareTo(now.toLocalDate().toString());
    return cmp < 0 || cmp === 0 && now.getHour() >= Mystery.REVEAL_HOUR;
  }

  static clue(m, i) {
    return Ui.nz(m.get("clue" + (i + 1))).trim();
  }

  static opensAt(i) {
    const h = Mystery.CLUE_HOURS[i];
    return (h > 12 ? h - 12 : h) + (h >= 12 ? " PM" : " AM");
  }

  static norm(s) {
    return (" " + Ui.nz(s).toLowerCase().replace(/[^a-z0-9]+/g, " ") + " ").replace(/\s+/g, " ");
  }

  /** The answer and the other accepted answers (commas or semicolons). */
  static accepted(m) {
    const out = [];
    for (const s of (Ui.nz(m.get("answer")) + "," + Ui.nz(m.get("accept"))).split(/[,;\n]/)) {
      const n = Mystery.norm(s).trim();
      if (n.length >= 3 && !out.contains(n)) out.add(n);
    }
    return out;
  }

  /** Right when the guess holds an accepted answer, or is a good part of one (5 letters or more). */
  static right(m, guess) {
    const g = Mystery.norm(guess);
    const gt = g.trim();
    if (gt.isEmpty()) return false;
    for (const a of Mystery.accepted(m)) {
      if (g.contains(" " + a + " ")) return true;
      if (gt.length >= 5 && (" " + a + " ").contains(" " + gt + " ")) return true;
    }
    return false;
  }

  static myGuesses(c, db, m) {
    const me = SessionAttendance.me(c, db);
    const name = me == null ? Reminders.myName(c, db) : me.get("name");
    const sid = me == null ? "-" : me.get("id");
    return db.rows("SELECT * FROM " + Mystery.GUESSES + " WHERE mystery_id=? AND (staff_id=? OR name=?) ORDER BY time, id", m.get("id"), sid, name);
  }

  static mySolve(c, db, m) {
    for (const g of Mystery.myGuesses(c, db, m)) if ("1" === g.get("correct")) return g;
    return null;
  }

  /** One guess per clue. Returns the saved guess row's points (0 when wrong), or -1 when not allowed now. */
  static guess(c, db, m, text) {
    const now = LocalDateTime.of(Dates.today(), Dates.time());
    const open = Mystery.cluesOpen(m, now);
    if (open === 0 || Mystery.revealed(m, now) || Mystery.mySolve(c, db, m) != null) return -1;
    for (const g of Mystery.myGuesses(c, db, m)) if (Ui.toInt(g.get("clue"), 0) === open) return -1;
    const ok = Mystery.right(m, text);
    const pts = ok ? Mystery.POINTS[open - 1] : 0;
    const me = SessionAttendance.me(c, db);
    const cv = new ContentValues();
    cv.put("mystery_id", m.get("id"));
    cv.put("staff_id", me == null ? "" : me.get("id"));
    cv.put("name", me == null ? Reminders.myName(c, db) : me.get("name"));
    cv.put("unit", me == null ? "" : Ui.nz(me.get("unit")));
    cv.put("guess", text.trim());
    cv.put("clue", open);
    cv.put("correct", ok ? "1" : "0");
    cv.put("points", pts);
    cv.put("time", now.withNano(0).toString());
    db.insert(Mystery.GUESSES, cv);
    Sync.kick(c);
    return pts;
  }

  /** Who solved it: earliest clue first, then the earliest time. */
  static solvers(db, m) {
    return db.rows("SELECT * FROM " + Mystery.GUESSES + " WHERE mystery_id=? AND correct='1' ORDER BY points DESC, time, id", m.get("id"));
  }

  static players(db, m) {
    return db.num("SELECT COUNT(DISTINCT name) FROM " + Mystery.GUESSES + " WHERE mystery_id=?", m.get("id"));
  }

  static save(c, db, old, f) {
    const cv = new ContentValues();
    for (const k of ["day", "title", "clue1", "clue2", "clue3", "clue4", "answer", "accept", "teaching"]) cv.put(k, Ui.nz(f.get(k)).trim());
    let id;
    if (old != null) {
      id = Long.parseLong(old.get("id"));
      db.update(Mystery.TABLE, cv, id);
    } else {
      const me = SessionAttendance.me(c, db);
      cv.put("by_name", me == null ? Reminders.myName(c, db) : me.get("name"));
      cv.put("by_staff", me == null ? "" : me.get("id"));
      cv.put("created", LocalDateTime.now().withNano(0).toString());
      id = db.insert(Mystery.TABLE, cv);
    }
    Sync.kick(c);
    return id;
  }

  /** The next day from today that has no mystery yet. */
  static nextFreeDay(db) {
    let d = Dates.today();
    for (let i = 0; i < 60; i++, d = d.plusDays(1)) if (Mystery.forDay(db, d.toString()) == null) return d.toString();
    return d.toString();
  }

  static coming(db) {
    return db.rows("SELECT * FROM " + Mystery.TABLE + " WHERE day>? ORDER BY day", Dates.todayIso());
  }

  static past(db) {
    return db.rows("SELECT * FROM " + Mystery.TABLE + " WHERE day<? ORDER BY day DESC LIMIT 30", Dates.todayIso());
  }

  // ---------- AI: write a mystery case on a topic ----------

  static MARK = "Write a 'mystery case'";

  static system() {
    return Mystery.MARK + " for postgraduate students of General Medicine in Tamil Nadu, India. A real-looking but invented patient, no names. "
        + "Give exactly these labelled lines, nothing else:\nTITLE: (one line teaser, e.g. Fever and confusion in a 45-year-old farmer)\n"
        + "CLUE 1: (history, 3 to 5 sentences, do not give the diagnosis away)\nCLUE 2: (examination findings)\n"
        + "CLUE 3: (investigations with values)\nCLUE 4: (imaging or the key test that clinches it)\n"
        + "ANSWER: (the diagnosis, short)\nALSO ACCEPT: (other names or spellings, comma separated)\n"
        + "TEACHING: (3 to 5 take-home points on one line each, starting with -)";
  }

  static user(topic) {
    return topic.trim().isEmpty() ? "Choose a common but tricky diagnosis seen in Indian medical wards." : "Topic or diagnosis: " + topic.trim();
  }

  /** The AI's labelled lines as form values (keys as in the table). */
  static parse(text) {
    const out = new LinkedHashMap();
    const keys = [["TITLE", "title"], ["CLUE 1", "clue1"], ["CLUE 2", "clue2"], ["CLUE 3", "clue3"], ["CLUE 4", "clue4"],
      ["ANSWER", "answer"], ["ALSO ACCEPT", "accept"], ["TEACHING", "teaching"]];
    let cur = null;
    let b = "";
    for (const raw of Ui.nz(text).replace(/\r/g, "").split("\n")) {
      const line = raw.replace(/^[*#\s]+/, "").split("**").join("");
      let found = null, rest = null;
      for (const k of keys) {
        if (line.toUpperCase().startsWith(k[0] + ":")) {
          found = k[1];
          rest = line.substring(k[0].length + 1).trim();
          break;
        }
      }
      if (found != null) {
        if (cur != null) out.put(cur, b.trim());
        cur = found;
        b = rest;
      } else if (cur != null) {
        b += (b.length === 0 ? "" : "\n") + raw.trim();
      }
    }
    if (cur != null) out.put(cur, b.trim());
    return out;
  }

  static homeLine(c, db) {
    const m = Mystery.today(db);
    if (m == null) return "No mystery today";
    const now = LocalDateTime.of(Dates.today(), Dates.time());
    if (Mystery.revealed(m, now)) return "Answer is out · " + Mystery.solvers(db, m).size() + " solved";
    if (Mystery.mySolve(c, db, m) != null) return "You solved it · answer at 9 PM";
    const open = Mystery.cluesOpen(m, now);
    return open === 0 ? "First clue at 9 AM" : "Clue " + open + " of 4 open · guess now for " + Mystery.POINTS[open - 1];
  }
}
;
