/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Obstetric physician: each month one Assistant Professor is the obstetric physician, with a senior PG of that
 * Assistant Professor's unit. They see the critical cases in the OG block, 9 AM to 2 PM daily.
 */
class ObstetricActivity extends Base {
  constructor() { super(); this.month = null; }

  static COLOR = 0xFFBE185D;
  static STATUS = ["Seen", "Follow-up", "Shifted to medicine / IMCU", "Settled"];

  onCreate(b) {
    super.onCreate(b);
    this.month = YearMonth.from(Dates.today());
    this.setTitle("Obstetric physician");
    this.subtitle = "Critical cases in the OG block · 9 AM to 2 PM daily";
    this.headerColor(ObstetricActivity.COLOR);
    this.headerAction("+ Case", {
      onClick: (v) => { this.caseDialog(null); }
    });
  }

  static onNow() {
    const t = Dates.time();
    return !t.isBefore(LocalTime.of(9, 0)) && t.isBefore(LocalTime.of(14, 0));
  }

  static duty(db, m) {
    return db.row("SELECT * FROM ob_duty WHERE month=? ORDER BY id DESC LIMIT 1", m.toString());
  }

  render() {
    const COLOR = ObstetricActivity.COLOR;
    const page = Ui.v(this);
    const d = ObstetricActivity.duty(this.db, this.month);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(COLOR), 20));
    const nav = Ui.h(this);
    nav.setGravity(Gravity.CENTER_VERTICAL);
    const prev = Ui.tv(this, "‹", 24, Color.WHITE, true);
    prev.setPadding(Ui.dp(this, 6), 0, Ui.dp(this, 14), 0);
    prev.setOnClickListener({
      onClick: (v) => { this.month = this.month.minusMonths(1); this.render(); }
    });
    nav.addView(prev);
    nav.addView(Ui.tv(this, Dates.month(this.month.atDay(1)), 15, 0xD9FFFFFF, true), Ui.weight(1));
    const nxt = Ui.tv(this, "›", 24, Color.WHITE, true);
    nxt.setPadding(Ui.dp(this, 14), 0, Ui.dp(this, 6), 0);
    nxt.setOnClickListener({
      onClick: (v) => { this.month = this.month.plusMonths(1); this.render(); }
    });
    nav.addView(nxt);
    hero.addView(nav);
    const ap = d == null ? "" : Ui.nz(d.get("ap")), pg = d == null ? "" : Ui.nz(d.get("pg")), unit = d == null ? "" : Ui.nz(d.get("unit"));
    hero.addView(Ui.tv(this, ap.isEmpty() ? "Not set yet" : ap, 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, "Assistant Professor, obstetric physician" + (unit.isEmpty() ? "" : " · " + unit + " unit"), 12, 0xD9FFFFFF, false));
    hero.addView(Ui.tv(this, "Senior PG: " + (pg.isEmpty() ? "not set" : pg), 14, Color.WHITE, true));
    const thisMonth = this.month.equals(YearMonth.from(Dates.today()));
    hero.addView(Ui.tv(this, thisMonth && ObstetricActivity.onNow() ? "● On duty now (9 AM to 2 PM)" : "Duty 9 AM to 2 PM daily", 12, Color.WHITE, false));
    if (SessionAttendance.canRun(this)) {
      const set = Ui.outlineButton(this, d == null ? "+ Set this month's obstetric physician" : "Change", COLOR, {
        onClick: (v) => { this.dutyDialog(); }
      });
      hero.addView(set);
      Ui.margins(set, 0, 10, 0, 0);
    }
    page.addView(hero);

    const m0 = this.month.atDay(1).toString(), m1 = this.month.atEndOfMonth().toString();
    const open = this.db.rows("SELECT * FROM og_cases WHERE status IN ('Seen','Follow-up') AND date BETWEEN ? AND ? ORDER BY date DESC, time DESC", m0, m1);
    page.addView(Ui.heading(this, "Being followed  ·  " + open.size(), COLOR));
    if (open.isEmpty()) page.addView(this.emptyNote("No OG block cases on follow-up"));
    for (const r of open) page.addView(this.caseRow(r));
    const all = this.db.rows("SELECT * FROM og_cases WHERE status NOT IN ('Seen','Follow-up') AND date BETWEEN ? AND ? ORDER BY date DESC, time DESC", m0, m1);
    page.addView(Ui.heading(this, "Done this month  ·  " + all.size(), Ui.SLATE));
    for (const r of all) page.addView(this.caseRow(r));
    this.setPage(page);
  }

  caseRow(r) {
    const COLOR = ObstetricActivity.COLOR;
    const card = Ui.card(this);
    card.addView(Ui.tv(this, Ui.nz(r.get("patient")) + (Ui.nz(r.get("age_sex")).isEmpty() ? "" : "  ·  " + r.get("age_sex")), 15, Ui.TEXT, true));
    card.addView(Ui.muted(this, Dates.nice(r.get("date")) + " " + Ui.nz(r.get("time")) + (Ui.nz(r.get("ward")).isEmpty() ? "" : "  ·  " + r.get("ward"))
        + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : "  ·  IP " + r.get("ip_no"))));
    if (!Ui.nz(r.get("problem")).isEmpty()) card.addView(Ui.body(this, r.get("problem")));
    if (!Ui.nz(r.get("advice")).isEmpty()) card.addView(Ui.tv(this, "Advice: " + r.get("advice"), 13, Ui.TEXT, false));
    card.addView(Ui.tv(this, Ui.nz(r.get("status")) + (Ui.nz(r.get("seen_by")).isEmpty() ? "" : "  ·  seen by " + r.get("seen_by")), 12, COLOR, true));
    Ui.ripple(card, Ui.alpha(COLOR, 0x22));
    card.setOnClickListener({
      onClick: (v) => { this.caseDialog(r); }
    });
    return card;
  }

  caseDialog(r) {
    const f = new Form(this);
    const d = ObstetricActivity.duty(this.db, YearMonth.from(Dates.today()));
    f.date("date", "Date", r == null ? Dates.todayIso() : r.get("date"));
    f.time("time", "Time", r == null ? Dates.now() : r.get("time"));
    f.text("patient", "Patient name *", r == null ? "" : r.get("patient"), Form.TEXT);
    f.text("age_sex", "Age / G P L (e.g. 24 F, G2P1L1, 34 weeks)", r == null ? "" : r.get("age_sex"), Form.TEXT);
    f.text("ip_no", "IP number", r == null ? "" : r.get("ip_no"), Form.TEXT);
    f.text("ward", "OG ward / bed", r == null ? "" : r.get("ward"), Form.TEXT);
    f.multi("problem", "Medical problem (e.g. eclampsia, PPH with shock, heart disease, sepsis)", r == null ? "" : r.get("problem"));
    f.multi("advice", "Opinion / advice", r == null ? "" : r.get("advice"));
    const by = d == null ? "" : Ui.nz(d.get("ap"));
    f.suggest("seen_by", "Seen by", r == null ? by : r.get("seen_by"), this.db.staffNames("AND role IN ('Assistant Professor','Associate Professor','Professor','Postgraduate')"));
    f.choice("status", "Status", ObstetricActivity.STATUS, ObstetricActivity.STATUS, r == null ? ObstetricActivity.STATUS[0] : r.get("status"), null);
    Ui.formDialog(this, r == null ? "OG block case" : "Edit OG block case", f, "Save", {
      run: () => {
        if (!f.require("patient", "Enter the patient's name")) return false;
        const cv = new ContentValues();
        for (const k of ["date", "time", "patient", "age_sex", "ip_no", "ward", "problem", "advice", "seen_by", "status"]) cv.put(k, f.get(k));
        cv.put("by_name", CallDutyActivity.myName(this));
        if (r == null) this.db.insert("og_cases", cv);
        else this.db.update("og_cases", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  dutyDialog() {
    const d = ObstetricActivity.duty(this.db, this.month);
    const f = new Form(this);
    f.suggest("ap", "Assistant Professor (obstetric physician)", d == null ? "" : d.get("ap"), this.db.staffNames("AND role IN ('Assistant Professor','Associate Professor')"));
    f.suggest("pg", "Senior PG (from the same unit)", d == null ? "" : d.get("pg"), this.db.staffNames("AND role='Postgraduate'"));
    Ui.formDialog(this, "Obstetric physician, " + Dates.month(this.month.atDay(1)), f, "Save", {
      run: () => {
        const cv = new ContentValues();
        cv.put("month", this.month.toString());
        cv.put("ap", f.get("ap").trim());
        cv.put("pg", f.get("pg").trim());
        const s = this.db.row("SELECT unit FROM staff WHERE name=? LIMIT 1", f.get("ap").trim());
        cv.put("unit", s == null ? "" : Ui.nz(s.get("unit")));
        cv.put("by_name", CallDutyActivity.myName(this));
        if (d == null) this.db.insert("ob_duty", cv);
        else this.db.update("ob_duty", cv, Long.parseLong(d.get("id")));
        this.render();
        return true;
      }
    });
  }
}
;
