/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Opinions medicine asks of other departments for its own patients (the other half of call over). */
class Opinions {
  constructor() {}

  static DEPTS = ["Cardiology", "Nephrology", "Neurology", "Medical gastroenterology", "Pulmonology / TB & chest", "Endocrinology",
      "General surgery", "Surgical gastroenterology", "Orthopaedics", "Obstetrics & gynaecology", "Urology", "Neurosurgery", "Cardiothoracic surgery",
      "Vascular surgery", "Plastic surgery", "ENT", "Ophthalmology", "Dermatology", "Psychiatry", "Anaesthesia / pain", "Radiology",
      "Haematology", "Medical oncology", "Rheumatology", "Paediatrics", "Dental", "Physical medicine", "Other"];
  static STATUS = ["Requested", "Seen", "Follow-up", "Transferred out", "Cancelled"];
  static URGENCY = ["Routine", "Urgent", "Emergency"];
  static OPEN_SQL = "status IN ('Requested','Follow-up')";

  static color(status) {
    if ("Requested".equals(status)) return Ui.ORANGE;
    if ("Follow-up".equals(status)) return Ui.AMBER;
    if ("Cancelled".equals(status)) return Ui.SLATE;
    if ("Transferred out".equals(status)) return Ui.PURPLE;
    return Ui.GREEN;
  }

  static shortDept(d) {
    return Ui.nz(d).split("Medical gastroenterology").join("MGE").split("Surgical gastroenterology").join("SGE")
        .split("Obstetrics & gynaecology").join("OG").split("Cardiothoracic surgery").join("CTS").split("Pulmonology / TB & chest").join("Pulmonology");
  }

  /** A list card for one request. */
  static card(a, db, r, showPatient, after) {
    const st = r.get("status");
    const sub = [];
    if (showPatient) {
      const id = (Ui.nz(r.get("age_sex")).isEmpty() ? "" : r.get("age_sex") + "  ·  ") + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : "IP " + r.get("ip_no") + "  ·  ")
          + (Ui.nz(r.get("ward")).isEmpty() ? "" : r.get("ward"));
      if (!id.trim().isEmpty()) sub.add(id.replaceAllRx("  ·  $", ""));
    }
    if (!Ui.nz(r.get("reason")).isEmpty()) sub.add("Why: " + r.get("reason"));
    if (!Ui.nz(r.get("seen_by")).isEmpty() || !Ui.nz(r.get("advice")).isEmpty())
      sub.add("Opinion" + (Ui.nz(r.get("seen_by")).isEmpty() ? "" : " (" + r.get("seen_by") + (Ui.nz(r.get("seen_date")).isEmpty() ? "" : ", " + Dates.nice(r.get("seen_date"))) + ")")
          + (Ui.nz(r.get("advice")).isEmpty() ? "" : ": " + r.get("advice")));
    else if (!Ui.nz(r.get("asked_by")).isEmpty()) sub.add("Asked by " + r.get("asked_by"));
    const urgent = "Routine".equals(r.get("urgency")) || Ui.nz(r.get("urgency")).isEmpty() ? "" : "  ·  " + r.get("urgency");
    const title = showPatient ? r.get("patient") + "  →  " + Opinions.shortDept(r.get("dept")) : Opinions.shortDept(r.get("dept"));
    const card = a.entryCard(Db.shortName(r.get("unit")) + "  ·  " + st + urgent, "Urgent".equals(r.get("urgency")) || "Emergency".equals(r.get("urgency")) ? Ui.RED : Opinions.color(st),
        title, TextUtils.join("\n", sub), Dates.nice(r.get("date")) + (Ui.nz(r.get("time")).isEmpty() ? "" : " " + r.get("time")),
        {
          onClick: (v) => { Opinions.dialog(a, db, r, null, after); }
        });
    if (Opinions.OPEN_SQL.contains("'" + st + "'")) {
      const seen = Ui.outlineButton(a, "Record their opinion", Ui.TEAL, {
        onClick: (v) => { Opinions.opinionDialog(a, db, r, after); }
      });
      card.addView(seen);
      Ui.margins(seen, 0, 8, 0, 0);
    }
    return card;
  }

  /** New request (r == null; patient may be given) or edit of an existing one. */
  static dialog(a, db, r, patient, after) {
    const f = new Form(a);
    const unit = r != null ? r.get("unit") : patient != null ? (Ui.nz(patient.get("home_unit")).isEmpty() ? patient.get("location") : patient.get("home_unit")) : db.todaysUnit();
    if (r != null || patient == null) {
      const names = [];
      for (const p of db.rows("SELECT name FROM patients WHERE status='IN' ORDER BY admit_date DESC LIMIT 400")) names.add(p.get("name"));
      f.suggest("patient", "Patient name *", r == null ? "" : r.get("patient"), names.slice());
      f.choice("unit", "Our unit", Db.shortNames(VipActivity.UNITS), VipActivity.UNITS, unit, null);
    }
    f.choice("dept", "Opinion from", Opinions.DEPTS, Opinions.DEPTS, r == null ? "Cardiology" : r.get("dept"), null);
    f.text("reason", "Reason / question for them *", r == null ? "" : r.get("reason"), Form.PLAIN);
    f.segment("urgency", "Urgency", Opinions.URGENCY, r == null ? "Routine" : r.get("urgency"));
    f.date("date", "Asked on", r == null ? Dates.todayIso() : r.get("date"));
    f.text("asked_by", "Asked by (PG / AP)", r == null ? CallDutyActivity.myName(a) : r.get("asked_by"), Form.PLAIN);
    if (r != null) {
      f.choice("status", "Status", Opinions.STATUS, Opinions.STATUS, r.get("status"), null);
      f.text("seen_by", "Seen by (their doctor)", r.get("seen_by"), Form.PLAIN);
      f.multi("advice", "Their opinion / advice", r.get("advice"));
      const del = Ui.outlineButton(a, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(a, "Delete request?", r.get("patient") + " → " + r.get("dept"), "Delete", {
            run: () => { db.delete("opinions", Long.parseLong(r.get("id"))); after.run(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(a, r == null ? "Ask another department" : "Edit opinion request", f, "Save", {
      run: () => {
        if (patient == null && !f.require("patient", "Enter the patient's name")) return false;
        if (!f.require("reason", "Write why the opinion is needed")) return false;
        const cv = new ContentValues();
        for (const k of ["dept", "reason", "urgency", "date", "asked_by"]) cv.put(k, f.get(k).trim());
        let p = patient;
        if (patient == null) {
          cv.put("patient", f.get("patient").trim());
          cv.put("unit", f.get("unit"));
          p = db.row("SELECT * FROM patients WHERE name=? AND status='IN' ORDER BY admit_date DESC LIMIT 1", f.get("patient").trim());
          // a new request for a patient found in the wards goes under that patient's own unit
          if (r == null && p != null) cv.put("unit", Ui.nz(p.get("home_unit")).isEmpty() ? p.get("location") : p.get("home_unit"));
        } else {
          cv.put("patient", patient.get("name"));
          cv.put("unit", Ui.nz(patient.get("home_unit")).isEmpty() ? patient.get("location") : patient.get("home_unit"));
        }
        if (p != null && (r == null || !p.get("id").equals(r.get("patient_id")))) {
          cv.put("patient_id", p.get("id"));
          cv.put("ip_no", p.get("ip_no"));
          cv.put("age_sex", (p.get("age").isEmpty() ? "" : p.get("age") + " / ") + Ui.nz(p.get("sex")));
          cv.put("ward", Db.shortName(p.get("location")) + (p.get("bed").isEmpty() ? "" : " · bed " + p.get("bed")));
        }
        if (r == null) {
          cv.put("time", Dates.now());
          cv.put("status", "Requested");
          db.insert("opinions", cv);
        } else {
          cv.put("status", f.get("status"));
          cv.put("seen_by", f.get("seen_by").trim());
          cv.put("advice", f.get("advice").trim());
          if (!"Requested".equals(f.get("status")) && Ui.nz(r.get("seen_date")).isEmpty()) cv.put("seen_date", Dates.todayIso());
          db.update("opinions", cv, Long.parseLong(r.get("id")));
        }
        CallDutyActivity.rememberName(a, f.get("asked_by"));
        after.run();
        return true;
      }
    });
  }

  /** Quick entry once the other department has seen the patient. */
  static opinionDialog(a, db, r, after) {
    const f = new Form(a);
    f.text("seen_by", "Seen by (their doctor)", r.get("seen_by"), Form.PLAIN);
    f.multi("advice", "Their opinion / advice *", r.get("advice"));
    f.segment("status", "Outcome", ["Seen", "Follow-up", "Transferred out"], "Follow-up".equals(r.get("status")) ? "Follow-up" : "Seen");
    Ui.formDialog(a, Opinions.shortDept(r.get("dept")) + " · " + r.get("patient"), f, "Save", {
      run: () => {
        if (!f.require("advice", "Write their opinion")) return false;
        const cv = new ContentValues();
        cv.put("seen_by", f.get("seen_by").trim());
        cv.put("advice", f.get("advice").trim());
        cv.put("status", f.get("status"));
        cv.put("seen_date", Dates.todayIso());
        db.update("opinions", cv, Long.parseLong(r.get("id")));
        after.run();
        return true;
      }
    });
  }
}
;
