/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Outbreak early warning: clusters this week, a map of where the cases come from, and the places with the most cases. */
class OutbreakActivity extends Base {
  static PERIODS = [7, 30, 90];

  constructor() {
    super();
    this.days = 30;
    this.only = "";
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Outbreak early warning");
    this.subtitle = "Epidemic-prone admissions by village and town";
    this.headerColor(Outbreak.COLOR);
  }

  render() {
    const db = this.db;
    const cls = Outbreak.clusters(db);
    const rise = Outbreak.rising(db);
    Outbreak.mark(this, cls, "home");
    Outbreak.mark(this, cls, "bg");
    const page = Ui.v(this);
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Outbreak.COLOR), 20));
    hero.addView(Ui.tv(this, cls.isEmpty() && rise.isEmpty() ? "🦠 No clusters this week" : "🦠 " + (cls.size() + rise.size())
      + ((cls.size() + rise.size()) === 1 ? " warning this week" : " warnings this week"), 18, 0xFFFFFFFF, true));
    hero.addView(Ui.tv(this, "Dengue, scrub typhus, leptospirosis, cholera, diarrhoea, malaria, chikungunya, typhoid, hepatitis A/E, influenza and "
      + "encephalitis admissions are grouped by the village or town in the address. A few from one place within a week is a cluster.",
      12, 0xE6FFFFFF, false));
    if (!cls.isEmpty() || !rise.isEmpty()) {
      const text = Outbreak.shareText(db, cls, rise);
      const share = Ui.button(this, "Share with public health (no names)", 0x33FFFFFF, {
        onClick: (v) => {
          const i = new Intent(Intent.ACTION_SEND);
          i.setType("text/plain");
          i.putExtra(Intent.EXTRA_TEXT, text);
          try {
            this.startActivity(Intent.createChooser(i, "Share the outbreak alert"));
          } catch (e) {
            Ui.toast(this, "No app to share with");
          }
        }
      });
      share.setTextColor(0xFFFFFFFF);
      share.setBackground(Ui.outline(this, 0x2EFFFFFF, 0x99FFFFFF, 12));
      hero.addView(share);
      Ui.margins(share, 0, 10, 0, 0);
    }
    page.addView(hero);

    if (!cls.isEmpty()) page.addView(Ui.heading(this, "Clusters this week", Outbreak.COLOR));
    for (const cl of cls) {
      const pl = Places.byName(cl.place);
      const b = new StringBuilder();
      for (const c of cl.cases)
        b.append(b.length() === 0 ? "" : "\n").append(Dates.nice(c.date)).append("  ·  ").append(Ui.nz(c.patient.get("name"))).append(", ")
          .append(Ui.nz(c.patient.get("age"))).append(Ui.nz(c.patient.get("sex"))).append("  ·  ").append(Db.shortName(Ui.nz(c.patient.get("home_unit"))));
      page.addView(this.entryCard(cl.disease.label.toUpperCase(), cl.disease.color, cl.cases.size() + " from " + cl.place
        + (pl == null ? "" : "  ·  " + pl.taluk + " taluk"), b.toString(), Dates.nice(cl.last()),
        this.opener(PatientActivity, "id", cl.cases.get(0).patient.get("id")), 12));
    }
    for (const r of rise) {
      const d = Outbreak.disease(r[0]);
      page.addView(this.entryCard("RISING", d.color, d.label + " rising across the district", r[1] + " admissions this week; about " + r[2]
        + " a week in the 4 weeks before.", null, null));
    }

    // period and disease filters
    const chips = Ui.h(this);
    for (const p of OutbreakActivity.PERIODS) {
      const ch = Ui.chip(this, p + " days", p === this.days, Outbreak.COLOR);
      ch.setOnClickListener({ onClick: (v) => { this.days = p; this.render(); } });
      chips.addView(ch);
    }
    page.addView(Ui.heading(this, "Where the cases come from", Outbreak.COLOR));
    page.addView(chips);
    Ui.margins(chips, 14, 0, 14, 6);
    const all = Outbreak.cases(db, Dates.today().minusDays(this.days - 1).toString());
    const perDisease = new JMap();
    for (const d of Outbreak.DISEASES) perDisease.put(d.key, 0);
    for (const c of all) perDisease.put(c.disease.key, perDisease.get(c.disease.key) + 1);
    const dchips = Ui.h(this);
    const any = Ui.chip(this, "All " + all.size(), this.only.isEmpty(), Outbreak.COLOR);
    any.setOnClickListener({ onClick: (v) => { this.only = ""; this.render(); } });
    dchips.addView(any);
    for (const d of Outbreak.DISEASES) {
      if (perDisease.get(d.key) === 0) continue;
      const ch = Ui.chip(this, d.label + " " + perDisease.get(d.key), d.key === this.only, d.color);
      ch.setOnClickListener({ onClick: (v) => { this.only = d.key; this.render(); } });
      dchips.addView(ch);
    }
    const hs = new HorizontalScrollView(this);
    hs.setHorizontalScrollBarEnabled(false);
    hs.addView(dchips);
    page.addView(hs);
    Ui.margins(hs, 14, 0, 14, 8);
    const shown = [];
    for (const c of all) if (this.only.isEmpty() || c.disease.key === this.only) shown.add(c);

    const mapCard = Ui.card(this);
    const map = new OutbreakActivity.MapView(this, shown);
    mapCard.addView(map, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 380)));
    mapCard.addView(Ui.muted(this, "Approximate positions. Places not on the map are listed below."));
    page.addView(mapCard);

    // places with the most cases
    const byPlace = new JMap();
    for (const c of shown) {
      const k = c.place.isEmpty() ? "(no address)" : c.place;
      if (!byPlace.containsKey(k)) byPlace.put(k, []);
      byPlace.get(k).add(c);
    }
    const rows = ArrayList(byPlace.entrySet());
    Collections.sort(rows, { compare: (a, b) => b.getValue().size() - a.getValue().size() });
    const tc = Ui.card(this);
    if (rows.isEmpty()) tc.addView(Ui.muted(this, "No epidemic-prone admissions in the last " + this.days + " days."));
    for (let i = 0; i < Math.min(20, rows.size()); i++) {
      const n = new JMap();
      for (const c of rows.get(i).getValue()) n.put(c.disease.label, n.containsKey(c.disease.label) ? n.get(c.disease.label) + 1 : 1);
      const bits = [];
      for (const e of n.entrySet()) bits.add(e.getKey() + " " + e.getValue());
      const pl = Places.byName(rows.get(i).getKey());
      tc.addView(Ui.kv(this, rows.get(i).getKey() + (pl == null ? "" : "  (" + pl.taluk + ")"), TextUtils.join(", ", bits)));
    }
    page.addView(tc);
    const note = Ui.muted(this, "From this department's admissions only, by the address written at admission. Diagnoses may be provisional.");
    Ui.margins(note, 16, 8, 16, 0);
    page.addView(note);
    this.setPage(page);
  }
}

/** The places around Tirunelveli with a bubble for the cases from each (sized by the number, coloured by the commonest disease). */
OutbreakActivity.MapView = class extends View {
  static LAT_MIN = 8.05;
  static LAT_MAX = 9.62;
  static LON_MIN = 77.18;
  static LON_MAX = 78.28;

  constructor(c, cases) {
    super(c);
    this.cases = cases;
    this.pDot = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.pText = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.pFill = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.pRing = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.pBg = new Paint();
    this.pSea = new Paint();
    this.pDot.setColor(0xFFCBD5E1);
    this.pText.setColor(0xFF475569);
    this.pText.setTextSize(Ui.dp(c, 9));
    this.pRing.setStyle(Paint.Style.STROKE);
    this.pRing.setStrokeWidth(Ui.dp(c, 1.5));
    this.pRing.setColor(0xFFFFFFFF);
    this.pBg.setColor(0xFFF1F5EE);
    this.pSea.setColor(0xFFDBEAFE);
  }

  x(lon) {
    const M = OutbreakActivity.MapView;
    return (lon - M.LON_MIN) / (M.LON_MAX - M.LON_MIN) * this.getWidth();
  }

  y(lat) {
    const M = OutbreakActivity.MapView;
    return (M.LAT_MAX - lat) / (M.LAT_MAX - M.LAT_MIN) * this.getHeight();
  }

  onDraw(cv) {
    const text = this.pText;
    const w = this.getWidth(), h = this.getHeight();
    cv.drawRect(0, 0, w, h, this.pBg);
    // the Gulf of Mannar and the sea south of the cape, roughly
    const s = new Path();
    s.moveTo(this.x(78.28), this.y(9.62));
    s.lineTo(this.x(78.20), this.y(9.25));
    s.lineTo(this.x(78.16), this.y(8.80));
    s.lineTo(this.x(78.12), this.y(8.45));
    s.lineTo(this.x(77.90), this.y(8.26));
    s.lineTo(this.x(77.70), this.y(8.15));
    s.lineTo(this.x(77.55), this.y(8.07));
    s.lineTo(this.x(77.18), this.y(8.05));
    s.lineTo(this.x(78.28), this.y(8.05));
    s.close();
    cv.drawPath(s, this.pSea);
    text.setColor(0xFF93C5FD);
    text.setTextSize(Ui.dp(this.getContext(), 10));
    cv.drawText("Gulf of Mannar", this.x(78.02), this.y(8.20), text);
    text.setColor(0xFF64748B);
    text.setTextSize(Ui.dp(this.getContext(), 9));

    const at = new JMap();
    for (const c of this.cases) {
      if (Places.byName(c.place) == null) continue;
      if (!at.containsKey(c.place)) at.put(c.place, []);
      at.get(c.place).add(c);
    }
    const r0 = Ui.dp(this.getContext(), 2.5);
    for (const p of Places.ALL) {
      cv.drawCircle(this.x(p.lon), this.y(p.lat), r0, this.pDot);
      if (p.big || at.containsKey(p.name)) cv.drawText(p.name, this.x(p.lon) + r0 * 2, this.y(p.lat) + r0, text);
    }
    for (const e of at.entrySet()) {
      const p = Places.byName(e.getKey());
      const n = e.getValue().size();
      const cnt = new JMap();
      let top = e.getValue().get(0).disease;
      for (const c of e.getValue()) {
        const k = (cnt.containsKey(c.disease.key) ? cnt.get(c.disease.key) : 0) + 1;
        cnt.put(c.disease.key, k);
        if (k > cnt.get(top.key)) top = c.disease;
      }
      const r = Ui.dp(this.getContext(), 6) + Ui.dp(this.getContext(), 4) * Math.sqrt(n);
      this.pFill.setColor(Ui.alpha(top.color, 0xB0));
      cv.drawCircle(this.x(p.lon), this.y(p.lat), r, this.pFill);
      cv.drawCircle(this.x(p.lon), this.y(p.lat), r, this.pRing);
      const num = new Paint(Paint.ANTI_ALIAS_FLAG);
      num.setColor(0xFFFFFFFF);
      num.setFakeBoldText(true);
      num.setTextSize(Ui.dp(this.getContext(), 10));
      num.setTextAlign(Paint.Align.CENTER);
      cv.drawText(String(n), this.x(p.lon), this.y(p.lat) + Ui.dp(this.getContext(), 3.5), num);
    }
  }
};
;
/* ---- app/PageJudge.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Live scan (8.70): decides from small grey camera frames (about 90 x 120, four a second) when the phone is held still over a
 * page that is in focus, so the page can be taken without pressing the shutter. After a page is taken it waits until the view
 * changes (the page is turned), so the same page is not taken twice. Plain Java so it can be tested and ported.
 */
class PageJudge {
  static NO_PAGE = 0; static MOVING = 1; static BLURRY = 2; static HOLD = 3; static SHOOT = 4; static SAME_PAGE = 5;

  /** Frames in a row that must be still and sharp (about one second). */
  static NEED = 4;
  /** Mean grey change between frames above which the phone is moving. */
  static MOVE = 7.0;
  /** Mean grey difference from the last page taken above which this is a new page. */
  static NEW_PAGE = 14.0;
  /** Lowest edge strength for a readable page. */
  static MIN_SHARP = 3.0;

  constructor() { this.prev = null; this.lastShot = null; this.steady = 0; this.armed = true; this.peak = 0; }

  /** Brightness edges: the mean of |4p - the four neighbours|, every second pixel (inside a box when one is given). */
  static sharpness(g, w, h, x0, y0, x1, y1) {
    if (x0 === undefined) { x0 = 1; y0 = 1; x1 = w - 1; y1 = h - 1; }
    let sum = 0;
    let n = 0;
    x0 = Math.max(1, x0);
    y0 = Math.max(1, y0);
    x1 = Math.min(w - 1, x1);
    y1 = Math.min(h - 1, y1);
    for (let y = y0; y < y1; y += 2)
      for (let x = x0; x < x1; x += 2) {
        const i = y * w + x;
        sum += Math.abs(4 * g[i] - g[i - 1] - g[i + 1] - g[i - w] - g[i + w]);
        n++;
      }
    return n === 0 ? 0 : sum / n;
  }

  static diff(a, b) {
    if (a == null || b == null || a.length !== b.length) return 255;
    let sum = 0;
    for (let i = 0; i < a.length; i++) sum += Math.abs(a[i] - b[i]);
    return sum / a.length;
  }

  /** The bright paper: its box when it covers a quarter of the view or more and has some contrast (writing), else null. */
  static paper(g, w, h) {
    const hist = new Array(256).fill(0);
    for (const v of g) hist[Math.max(0, Math.min(255, v))]++;
    const p10 = PageJudge.pct(hist, g.length, 0.10), p90 = PageJudge.pct(hist, g.length, 0.90);
    if (p90 < 110 || p90 - p10 < 40) return null;
    const t = idiv(p10 + p90, 2);
    const rows = new Array(h).fill(0), cols = new Array(w).fill(0);
    let bright = 0;
    for (let y = 0; y < h; y++)
      for (let x = 0; x < w; x++)
        if (g[y * w + x] >= t) {
          rows[y]++;
          cols[x]++;
          bright++;
        }
    if (bright < idiv(g.length, 4)) return null;
    const top = PageJudge.first(rows, idiv(w * 3, 10), true), bottom = PageJudge.first(rows, idiv(w * 3, 10), false);
    const left = PageJudge.first(cols, idiv(h * 3, 10), true), right = PageJudge.first(cols, idiv(h * 3, 10), false);
    if (top < 0 || left < 0 || bottom <= top || right <= left) return null;
    const area = (right - left + 1) * (bottom - top + 1) / (w * h);
    if (area < 0.25) return null;
    return [left / w, top / h, (right + 1) / w, (bottom + 1) / h];
  }

  static pct(hist, n, p) {
    const want = toInt(n * p);
    let got = 0;
    for (let v = 0; v < 256; v++) {
      got += hist[v];
      if (got > want) return v;
    }
    return 255;
  }

  static first(counts, min, fromStart) {
    if (fromStart) {
      for (let i = 0; i < counts.length; i++) if (counts[i] >= min) return i;
    } else {
      for (let i = counts.length - 1; i >= 0; i--) if (counts[i] >= min) return i;
    }
    return -1;
  }

  /** One frame (grey 0..255, row by row). */
  feed(g, w, h) {
    const f = new PageJudge.Frame();
    f.motion = this.prev == null ? 255 : PageJudge.diff(g, this.prev);
    this.prev = g.slice();
    f.box = PageJudge.paper(g, w, h);
    if (f.box == null) f.sharp = PageJudge.sharpness(g, w, h);
    else {
      // inside the paper, a tenth in from each side
      const bw = f.box[2] - f.box[0], bh = f.box[3] - f.box[1];
      f.sharp = PageJudge.sharpness(g, w, h, Math.round((f.box[0] + bw * 0.1) * w), Math.round((f.box[1] + bh * 0.1) * h),
          Math.round((f.box[2] - bw * 0.1) * w), Math.round((f.box[3] - bh * 0.1) * h));
    }
    if (this.lastShot != null) {
      f.change = PageJudge.diff(g, this.lastShot);
      if (f.change > PageJudge.NEW_PAGE) this.armed = true;
    }
    this.peak = Math.max(this.peak * 0.97, f.sharp);
    if (f.box == null) {
      this.steady = 0;
      f.state = PageJudge.NO_PAGE;
    } else if (!this.armed) {
      this.steady = 0;
      f.state = PageJudge.SAME_PAGE;
    } else if (f.motion > PageJudge.MOVE) {
      this.steady = 0;
      f.state = PageJudge.MOVING;
    } else if (f.sharp < PageJudge.MIN_SHARP || f.sharp < this.peak * 0.55) {
      this.steady = 0;
      f.state = PageJudge.BLURRY;
    } else if (++this.steady >= PageJudge.NEED) {
      this.steady = 0;
      f.state = PageJudge.SHOOT;
    } else f.state = PageJudge.HOLD;
    f.progress = f.state === PageJudge.HOLD ? this.steady / PageJudge.NEED : f.state === PageJudge.SHOOT ? 1 : 0;
    return f;
  }

  /** A page was taken from this view (by itself or with the shutter): wait for the next page. */
  taken(g) {
    this.lastShot = g == null ? this.prev : g.slice();
    this.armed = false;
    this.steady = 0;
  }

  /** A page was removed: the view in front may be taken again. */
  unlock() {
    this.lastShot = null;
    this.armed = true;
    this.steady = 0;
  }

  static say(state, pages) {
    switch (state) {
      case PageJudge.NO_PAGE: return pages === 0 ? "Point the camera at the page" : "Turn to the next page";
      case PageJudge.MOVING: return "Hold still…";
      case PageJudge.BLURRY: return "Focusing… hold a little higher";
      case PageJudge.HOLD: return "Hold still…";
      case PageJudge.SHOOT: return "Taking the page";
      case PageJudge.SAME_PAGE: return "Page " + pages + " taken ✓  Turn to the next page";
      default: return "";
    }
  }

  /** ARGB pixels to grey (the green-heavy luma). */
  static grey(argb) {
    const g = new Array(argb.length).fill(0);
    for (let i = 0; i < argb.length; i++) {
      const p = argb[i];
      g[i] = (((p >> 16) & 0xFF) * 77 + ((p >> 8) & 0xFF) * 150 + (p & 0xFF) * 29) >> 8;
    }
    return g;
  }
}

PageJudge.Frame = class {
  constructor() {
    this.state = 0;
    /** 0..1 while holding still. */
    this.progress = 0;
    this.sharp = 0; this.motion = 0; this.change = 0;
    /** The paper's box in the frame, as fractions (left, top, right, bottom); null when no page is seen. */
    this.box = null;
  }
};
;
/* ---- app/PageScan.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Pages to text with an AI (8.70), for any screen: live scan, camera, gallery or a PDF file, then Gemini with the user's key or a
 * free AI chat app (copy its answer, come back, Paste). The screen passes the prompt and gets the text back in Done. Request codes
 * are reqBase (live), reqBase + 1 (camera) and reqBase + 2 (gallery / file); the screen hands them to result().
 */
class PageScan {
  // interface Done { void read(String text); }

  constructor(a, prefix, title, prompt, mark, max, reqBase, done) {
    this.a = a;
    this.db = Db.get(a);
    this.prefix = prefix;
    this.title = title;
    this.prompt = prompt;
    this.mark = mark;
    this.max = max;
    this.reqBase = reqBase;
    this.done = done;
    this.waitKey = prefix + "_wait";
    this.pages = [];
    this.cameraRel = null;
  }

  save(out) {
    out.putString(this.prefix + "_camera", this.cameraRel);
    out.putStringArrayList(this.prefix + "_pages", this.pages);
  }

  restore(b) {
    if (b == null) return;
    this.cameraRel = b.getString(this.prefix + "_camera");
    const p = b.getStringArrayList(this.prefix + "_pages");
    if (p != null) {
      this.pages.clear();
      this.pages.addAll(p);
    }
  }

  // ---------- getting the pages ----------

  live() {
    this.clean();
    LiveScanActivity.start(this.a, this.prefix, this.max, this.title, this.reqBase);
  }

  camera(fresh) {
    if (fresh) this.clean();
    this.cameraRel = Imaging.DIR + "/" + this.prefix + "_" + System.currentTimeMillis() + ".jpg";
    if (!Store.capture(this.a, this.cameraRel, this.reqBase + 1)) this.cameraRel = null;
  }

  pick(fresh) {
    if (fresh) this.clean();
    Store.pick(this.a, ["image/*", "application/pdf"], this.reqBase + 2);
  }

  /** True when the result was one of ours. */
  result(req, res, data) {
    if (req < this.reqBase || req > this.reqBase + 2) return false;
    if (req === this.reqBase) {
      if (res === RESULT_OK) {
        this.pages.addAll(LiveScanActivity.pagesOf(data));
        if (!this.pages.isEmpty()) this.read();
      }
      return true;
    }
    if (res !== RESULT_OK) {
      if (!this.pages.isEmpty()) this.more();
      return true;
    }
    try {
      let rel = null;
      if (req === this.reqBase + 1 && this.cameraRel != null) {
        rel = this.cameraRel;
        this.cameraRel = null;
      } else if (req === this.reqBase + 2 && data != null && data.getData() != null) rel = Store.importUri(this.a, data.getData(), Imaging.DIR, this.prefix);
      if (rel == null) return true;
      const f = this.db.file(rel);
      if (PageScan.isPdf(f)) {
        if (f.length() > 15 * 1024 * 1024) {
          f.delete();
          Ui.toast(this.a, "That PDF is too big (over 15 MB). Pick the pages as photos instead.");
          return true;
        }
      } else {
        const jpg = f.exists() ? LabScan.jpeg(f) : null;
        if (jpg == null) {
          f.delete();
          Ui.toast(this.a, "Pick a photo (JPG or PNG) or a PDF");
          return true;
        }
        const out = new FileOutputStream(f);
        try { out.write(jpg); } finally { out.close(); }
      }
      this.pages.push(rel);
      this.more();
    } catch (e) {
      Ui.toast(this.a, "Could not use the file: " + (e && e.getMessage ? e.getMessage() : e));
    }
    return true;
  }

  static isPdf(f) {
    const b = VFS.readSync(f.rel());
    return b != null && b.length >= 4 && b[0] === 0x25 && b[1] === 0x50 && b[2] === 0x44 && b[3] === 0x46;
  }

  static bytes(f) {
    return VFS.readSync(f.rel());
  }

  /** After each page: another one, or read what there is. */
  more() {
    const n = this.pages.length;
    const b = new AlertDialog.Builder(this.a).setTitle(n + (n === 1 ? " page" : " pages") + " ready")
      .setMessage(n < this.max ? "Add another page, or read now." : "That is the most read at once. Read now.")
      .setPositiveButton("Read now", { onClick: (d, w) => { this.read(); } })
      .setNegativeButton("Cancel", { onClick: (d, w) => { this.clean(); } });
    if (n < this.max) b.setNeutralButton("Another page", {
      onClick: (d, w) => {
        new AlertDialog.Builder(this.a).setTitle("Another page")
          .setItems(["📷  Camera", "🖼  Gallery or PDF file"], {
            onClick: (d2, k) => {
              if (k === 0) this.camera(false);
              else this.pick(false);
            }
          }).setNegativeButton("Cancel", { onClick: (d2, k) => { this.more(); } }).show();
      }
    });
    b.setCancelable(false).show();
  }

  // ---------- reading them ----------

  /** Gemini reads the pages with the user's key (the test fake first); without one they go to a free AI chat app. */
  read() {
    if (this.pages.isEmpty()) return;
    if (AiRun.fake != null) {
      const text = AiRun.fake.answer(this.prompt, "[pages]");
      this.clean();
      this.done.read(text);
      return;
    }
    if (Ai.geminiKey(this.a).isEmpty()) {
      this.chooseApp();
      return;
    }
    const files = [];
    for (const rel of this.pages) {
      const f = this.db.file(rel);
      const b = PageScan.isPdf(f) ? PageScan.bytes(f) : LabScan.jpeg(f);
      if (b != null) files.push(b);
    }
    if (files.isEmpty()) {
      Ui.toast(this.a, "Could not open the pages");
      return;
    }
    const wait = new AlertDialog.Builder(this.a).setTitle("Gemini is reading…").setMessage("Only the pages are sent. Keep the app open.")
      .setCancelable(false).show();
    new Thread({
      run: () => {
        let got = null, err = null;
        try {
          got = Ai.visionPages(this.a, files, this.prompt, null, false);
        } catch (e) {
          if (e instanceof Ai.Failure) err = e.getMessage();
          else err = "Could not read it: " + (e && e.getMessage ? e.getMessage() : e);
        }
        const res = got, error = err;
        this.a.runOnUiThread({
          run: () => {
            if (this.a.isFinishing()) return;
            try { wait.dismiss(); } catch (ignored) { }
            this.clean();
            if (error != null || res == null || res.trim().isEmpty()) {
              new AlertDialog.Builder(this.a).setTitle("Not read").setMessage(error == null ? "The AI sent nothing back. Try clearer pages." : error)
                .setPositiveButton("OK", null).show();
              return;
            }
            this.done.read(res);
          }
        });
      }
    }).start();
  }

  chooseApp() {
    const apps = DischargeActivity.CHAT_APPS;
    const items = [];
    for (const x of apps) items.push("Free: " + x[0] + " app");
    items.push("Read inside the app: add a free Gemini key");
    new AlertDialog.Builder(this.a).setTitle("Which AI app reads it?")
      .setItems(items, {
        onClick: (d, w) => {
          if (w < apps.length) this.toApp(apps[w]);
          else {
            this.clean();
            this.a.startActivity(new Intent(this.a, SettingsActivity));
          }
        }
      }).setNegativeButton("Cancel", { onClick: (d, w) => { this.clean(); } }).show();
  }

  toApp(app) {
    const cm = this.a.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Request for AI", this.prompt));
    const uris = [];
    let pdf = false, img = false;
    for (const rel of this.pages) {
      uris.push(DocProvider.uri(rel));
      if (PageScan.isPdf(this.db.file(rel))) pdf = true;
      else img = true;
    }
    const i = new Intent(uris.length === 1 ? Intent.ACTION_SEND : Intent.ACTION_SEND_MULTIPLE);
    i.setType(pdf && img ? "*/*" : pdf ? "application/pdf" : "image/jpeg");
    if (uris.length === 1) i.putExtra(Intent.EXTRA_STREAM, uris[0]);
    else i.putExtra(Intent.EXTRA_STREAM, uris);
    i.putExtra(Intent.EXTRA_TEXT, this.prompt);
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK);
    Ai.prefs(this.a).edit().putString(this.waitKey, app[0]).apply();
    i.setPackage(app[1]);
    try {
      this.a.startActivity(i);
      Ui.toast(this.a, "In " + app[0] + " send the pages with the request (it is copied too), copy the answer, then come back and tap Paste");
    } catch (noApp) {
      try {
        i.setPackage(null);
        this.a.startActivity(Intent.createChooser(i, "Send the pages to " + app[0]).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
      } catch (e) {
        Ai.prefs(this.a).edit().remove(this.waitKey).apply();
        Ui.toast(this.a, app[0] + " is not installed on this phone");
      }
    }
    if (this.a instanceof Base) this.a.render();
  }

  /** The free app being waited on, or "". */
  waiting() {
    return AiRun.waiting(this.a, this.waitKey);
  }

  /** The answer copied from the free app (or any copied text). */
  paste() {
    const text = AiRun.paste(this.a, this.waitKey, this.mark);
    if (text != null) this.done.read(text);
  }

  /** The page files are deleted once read (they may show a patient's details). */
  clean() {
    this.pages.clear();
    try {
      const fs = this.db.file(Imaging.DIR).listFiles();
      if (fs != null) for (const f of fs) if (f.getName().startsWith(this.prefix + "_")) f.delete();
    } catch (ignored) {
    }
  }
}
;
/* ---- app/PatientActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
class PatientActivity extends Base {
  constructor() {
    super();
    this.id = 0;
    this.p = null;
  }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    // 10.35: the clean patient page of the user's picture
    this.clean = true;
    this.pageBg = PatientDesign.PAGE;
  }

  /** Exam case: mark this patient for case presentations, or see and edit the mark. */
  examRow() {
    const db = this.db, id = this.id;
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    const ec = ExamCases.forPatient(db, id);
    const can = ExamCases.canMark(this);
    const again = { run: () => { this.render(); } };
    if (ec == null) {
      if (!can) return box;
      const r = again;
      box.addView(Ui.outlineButton(this, "🎓 Mark as exam case", ExamCases.COLOR, {
        onClick: (v) => { ExamCasesActivity.markDialog(this, db, id, r); }
      }));
      return box;
    }
    const card = Ui.v(this);
    card.setBackground(Ui.round(this, 0xFFFFF7ED, 16));
    card.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
    card.addView(Ui.tv(this, "🎓 Exam case  ·  " + Ui.nz(ec.get("kind")) + "  ·  " + Ui.nz(ec.get("system")), 15, 0xFF7C2D12, true));
    if (!Ui.nz(ec.get("points")).isEmpty()) card.addView(Ui.tv(this, ec.get("points"), 13, Ui.TEXT, false));
    card.addView(Ui.muted(this, "Marked by " + Ui.nz(ec.get("marked_by"))));
    const b = [];
    b.add(Ui.button(this, "Exam cases", ExamCases.COLOR, this.opener(ExamCasesActivity)));
    if (can) {
      const r = again;
      b.add(Ui.outlineButton(this, "Edit", ExamCases.COLOR, {
        onClick: (v) => { ExamCasesActivity.markDialog(this, db, id, r); }
      }));
      b.add(Ui.outlineButton(this, "Remove", Ui.RED, {
        onClick: (v) => {
          ExamCases.unmark(this, db, ec.get("id"));
          this.render();
        }
      }));
    }
    const row = Ui.buttonRow(this, b);
    card.addView(row);
    Ui.margins(row, 0, 8, 0, 0);
    box.addView(card);
    return box;
  }

  render() {
    const db = this.db, id = this.id;
    this.p = db.row("SELECT * FROM patients WHERE id=?", String(id));
    const p = this.p;
    if (p == null) {
      this.finish();
      return;
    }
    const loc = p.get("location"), home = p.get("home_unit");
    const inn = Db.IN.equals(p.get("status"));
    const color = Db.DIED.equals(p.get("status")) ? Ui.SLATE : Ui.unitColor(loc);
    const unitName = Db.isWardUnit(home) ? home + " unit" : Db.unitName(home);
    this.setTitle(unitName + " · Medicine");
    this.subtitle = null;
    this.headerColor(PatientDesign.INK);
    this.headerAction("Edit", this.opener(FormActivity, "kind", "patient", "id", String(id)));
    const page = Ui.v(this);

    let state;
    if (Db.DIED.equals(p.get("status"))) state = "Died on " + Dates.nice(p.get("outcome_date"));
    else if (Db.DISCHARGED.equals(p.get("status"))) state = "Discharged on " + Dates.nice(p.get("outcome_date"));
    else state = "Now in " + Base.where(p);
    const cs = CaseSheet.load(db, id);
    let filled = 0;
    for (const s of CaseSheet.SECTIONS) if (CaseSheet.filled(cs, s)) filled++;
    const wb = CaseSheet.writtenBy(cs);
    const note = (filled === 0 ? "Case sheet not started" : "Case sheet: " + filled + " of " + CaseSheet.SECTIONS.length + " sections filled")
        + (wb.isEmpty() ? "" : " · written by " + wb);
    page.addView(PatientDesign.heroFor(this, db, p, state, note, ["Admitted", "Bed", "CMCHIS"],
        [PatientDesign.shortDate(p.get("admit_date")), Ui.nz(p.get("bed")), "1".equals(p.get("cmchis")) ? "Yes" : "No"], [
          PatientDesign.action(this, R.drawable.ic_doc, "Case sheet", false, this.opener(CaseSheetActivity, "id", String(id))),
          PatientDesign.action(this, R.drawable.ic_event, "Timeline", false, this.opener(TimelineActivity, "id", String(id))),
          PatientDesign.action(this, R.drawable.ic_menu, "Summary", false, this.opener(DischargeActivity, "id", String(id), "kind", DischargeActivity.CASE)),
          PatientDesign.action(this, R.drawable.ic_approve, "Discharge", true, this.opener(DischargeActivity, "id", String(id)))]));

    const quickCard = FormActivity.quickCard(this, p);
    if (quickCard != null) page.addView(quickCard);
    if (inn) page.addView(ProtocolActivity.patientCard(this, db, id));
    page.addView(CodeBlueActivity.patientCard(this, db, id, inn));

    // bedside charts: the ones the diagnosis calls for are filled; tap any to open
    let onCharts = 0;
    for (const k of Charts.KINDS) onCharts += Charts.count(db, id, k.code);
    if (Db.IN.equals(p.get("status")) || onCharts > 0) {
      page.addView(PatientDesign.heading(this, "Bedside charts", Charts.KINDS.length + " charts"));
      const flow = new Bands.Flow(this);
      flow.setPadding(Ui.dp(this, 16), Ui.dp(this, 2), Ui.dp(this, 16), Ui.dp(this, 4));
      let darkDone = false;
      for (const k of Charts.KINDS) {
        const n = Charts.count(db, id, k.code);
        const start = n === 0 && Charts.suggested(p, k.code) && !darkDone;
        if (start) darkDone = true;
        const label = start ? "Start " + k.name.toLowerCase() : k.name + (n > 0 ? " · " + n : "");
        // the chart to start comes first, as in the picture
        if (start) flow.addView(PatientDesign.chartPill(this, label, k.color, true, this.opener(ChartActivity, "id", String(id), "kind", k.code)), 0);
        else flow.addView(PatientDesign.chartPill(this, label, k.color, false, this.opener(ChartActivity, "id", String(id), "kind", k.code)));
      }
      page.addView(flow);
      const news = Ews.patientLine(this, this.db, id);
      if (news != null) page.addView(news);
    }
    const claim = CmchisClaims.patientCard(this, db, p);
    if (claim != null) page.addView(claim);
    const readmit = Readmit.card(this, db, p);
    if (readmit != null) page.addView(readmit);
    const crit = CriticalLabs.patientCard(this, db, id);
    if (crit != null) page.addView(crit);
    if (inn) {
      const watch = Watch.patientCard(this, db, id);
      if (watch != null) page.addView(watch);
      page.addView(Countdown.section(this, db, id));
    }
    // pending tasks and results, then the investigations
    if (inn || Tasks.pending(db, id) > 0) page.addView(Tasks.section(this, db, id));
    if (inn || Results.waitingFor(db, id) > 0) page.addView(Results.section(this, db, id));
    page.addView(Labs.section(this, db, id));
    if (inn || !Antibiogram.forPatient(db, id).isEmpty()) page.addView(CultureActivity.patientCard(this, db, id));
    page.addView(Imaging.section(this, db, id));
    page.addView(Imaging.clinicalSection(this, db, id));
    // bedside tools
    if (inn) page.addView(EcgActivity.patientCard(this, db, id));
    if (inn) {
      const kd = KidneyDoseActivity.patientCard(this, db, id, p);
      if (kd != null) page.addView(kd);
    }
    page.addView(ScoresActivity.patientCard(this, db, id));
    page.addView(AbgActivity.patientCard(this, db, id));
    if (inn) {
      const gl = Guidelines.section(this, db, id, p);
      if (gl != null) page.addView(gl);
      const hw = Ui.v(this);
      hw.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
      const onList = db.num("SELECT COUNT(*) FROM handovers WHERE day=? AND patient_id=?", Dates.admitDay().toString(), String(id));
      hw.addView(Ui.outlineButton(this, onList > 0 ? "✓ On tonight's handover (open)" : "Add to the 7:30 AM handover", HandoverActivity.COLOR,
          onList > 0 ? this.opener(HandoverActivity) : this.opener(HandoverActivity, "patient", String(id))));
      page.addView(hw);
    }
    // teaching
    const tps = TeachPoints.section(this, db, p);
    if (tps != null) page.addView(tps);
    const rare = RareCase.patientCard(this, db, p);
    if (rare != null) page.addView(rare);
    if (inn) page.addView(this.examRow());
    page.addView(CasePresentationActivity.patientButton(this, db, id));
    page.addView(CaseReportActivity.patientButton(this, db, p));
    // patient and family
    if (inn || !Counsel.forPatient(db, id).isEmpty()) page.addView(Counsel.section(this, db, p));
    page.addView(PillCardActivity.patientButton(this, db, id));
    page.addView(TamilCard.patientButton(this, db, id));
    if (Dama.show(db, p)) page.addView(Dama.section(this, db, id));
    if (Db.DIED.equals(p.get("status"))) page.addView(MccdActivity.patientCard(this, db, id));

    const ops = db.rows("SELECT * FROM opinions WHERE patient_id=? ORDER BY date DESC, id DESC", String(id));
    if (inn || !ops.isEmpty()) {
      page.addView(PatientDesign.heading(this, "Opinions", ops.isEmpty() ? "None requested" : ops.size() + " asked"));
      for (const o of ops) page.addView(Opinions.card(this, db, o, false, { run: () => { this.render(); } }));
      if (inn) {
        const ask = Ui.outlineButton(this, "+ Ask another department", Ui.TEAL, {
          onClick: (v) => {
            Opinions.dialog(this, db, null, p, { run: () => { this.render(); } });
          }
        });
        page.addView(ask);
        Ui.margins(ask, 14, 4, 14, 4);
      }
    }

    if (inn) {
      page.addView(PatientDesign.heading(this, "Move or close", "From " + Base.where(p)));
      const ask = UnitMoves.open(db, id);
      if (ask != null) page.addView(UnitMoves.banner(this, db, ask, { run: () => { this.render(); } }));
      const act = Ui.card(this);
      const quick = [];
      // the department's flow: TAEI -> CCB / triage, triage -> step-down / fever / IMCU, step-down -> unit ward
      const next = [];
      if (Db.fixedFlow(loc)) next.addAll(Db.nextWards(loc, home));
      else if (Db.isWardUnit(loc)) Collections.addAll(next, Db.IMCU, Db.FEVER, Db.CCB, Db.GERI, Db.RHEUM);
      else {
        next.add(Db.STEPDOWN);
        if (Db.isWardUnit(home)) next.add(home);
      }
      // convict cases go to that month's convict ward (one of M1 to M7) the day after admission
      const convictWard = db.rotationUnit();
      if ("1".equals(p.get("convict")) && !convictWard.equals(loc)) {
        quick.add(Ui.button(this, "To convict ward (" + convictWard + ")", Ui.unitColor(convictWard), {
          onClick: (v) => { this.transfer(convictWard); }
        }));
        next.removeObj(convictWard);
      }
      for (const s of next) {
        if (s.equals(loc)) continue;
        const label = Db.isWardUnit(s) ? "To " + s + " ward" : "To " + Db.shortName(s);
        quick.add(Ui.button(this, label, Ui.unitColor(s), {
          onClick: (v) => { this.transfer(s); }
        }));
      }
      if (!quick.isEmpty()) act.addView(Ui.buttonRow(this, quick));
      const other = Ui.outlineButton(this, "Transfer to another ward…", Ui.PRIMARY, {
        onClick: (v) => { this.transfer(null); }
      });
      act.addView(other);
      Ui.margins(other, 0, quick.isEmpty() ? 0 : 8, 0, 0);
      if (ask == null) {
        const hand = Ui.outlineButton(this, "Hand over to another unit…", UnitMoves.COLOR, {
          onClick: (v) => { this.handOver(null); }
        });
        act.addView(hand);
        Ui.margins(hand, 0, 8, 0, 0);
      }
      const row = Ui.buttonRow(this,
          Ui.button(this, "Discharge", Ui.GREEN, {
            onClick: (v) => { this.discharge(); }
          }),
          Ui.button(this, "Record death", Ui.SLATE, {
            onClick: (v) => { this.death(); }
          }));
      act.addView(row);
      Ui.margins(row, 0, 8, 0, 0);
      page.addView(act);
    }

    page.addView(PatientDesign.heading(this, "Details", null));
    const det = Ui.card(this);
    det.addView(Ui.kv(this, "Parent unit", Db.unitName(home)));
    det.addView(Ui.kv(this, "Admitted on", Dates.nice(p.get("admit_date"))));
    det.addView(Ui.kv(this, "Diagnosis", p.get("diagnosis")));
    if (!Ui.nz(p.get("category")).isEmpty()) det.addView(Ui.kv(this, "Admission group", p.get("category") + " (also in its own admission list)"));
    det.addView(Ui.kv(this, "Bed", p.get("bed")));
    if (inn && Db.IMCU.equals(p.get("location"))) {
      const w = Db.imcuWing(p);
      det.addView(Ui.kv(this, "IMCU wing", w.isEmpty() ? "Not set" : w.equals(Db.TOX) ? "Toxicology" + (Ui.nz(p.get("tox_kind")).isEmpty() ? "" : " · " + p.get("tox_kind")) : "Non-toxicology"));
      det.addView(Ui.kv(this, "Ventilator", "1".equals(p.get("vent")) ? "Yes" : "No"));
      const iw = Ui.outlineButton(this, "IMCU wing, bed, ventilator…", Ui.unitColor(Db.IMCU), {
        onClick: (v) => { UnitActivity.imcuDialog(this, p, { run: () => { this.render(); } }); }
      });
      det.addView(iw);
      Ui.margins(iw, 0, 8, 0, 0);
    }
    if (Db.isDengue(p) || (inn && Db.FEVER.equals(p.get("location")))) {
      const pos = Db.isDengue(p);
      const test = Ui.nz(p.get("dengue_test"));
      det.addView(Ui.kv(this, "Dengue", pos ? "Positive" + (test.isEmpty() ? "" : " (" + test + ")") + (Ui.nz(p.get("dengue_date")).isEmpty() ? "" : " · " + Dates.nice(p.get("dengue_date"))) : "Not marked"));
      if (pos) det.addView(Ui.kv(this, "Severity", Ui.nz(p.get("dengue_grade")).isEmpty() ? "Not set" : p.get("dengue_grade")));
      if (!Ui.nz(p.get("platelet")).isEmpty()) det.addView(Ui.kv(this, "Platelet count", p.get("platelet")));
      if (inn) {
        const dg = Ui.outlineButton(this, pos ? "Update dengue details…" : "Mark dengue positive…", Ui.RED, {
          onClick: (v) => { UnitActivity.dengueDialog(this, p, { run: () => { this.render(); } }); }
        });
        det.addView(dg);
        Ui.margins(dg, 0, 8, 0, 0);
      }
    }
    det.addView(Ui.kv(this, "PIN number (TN HMIS)", Ui.nz(p.get("pin_no"))));
    det.addView(Ui.kv(this, "Phone", p.get("phone")));
    det.addView(Ui.kv(this, "Address", p.get("address")));
    det.addView(Ui.kv(this, "CMCHIS", "1".equals(p.get("cmchis")) ? "Yes" + (p.get("cmchis_no").isEmpty() ? "" : " (" + p.get("cmchis_no") + ")") : "No"));
    if (!Ui.nz(p.get("cmchis_pkg")).isEmpty()) det.addView(Ui.kv(this, "CMCHIS package", p.get("cmchis_pkg")));
    if (!inn) det.addView(Ui.kv(this, Db.DIED.equals(p.get("status")) ? "Cause / notes" : "Discharge notes", p.get("outcome_note")));
    if (!p.get("phone").isEmpty()) {
      const call = Ui.outlineButton(this, "Call " + p.get("phone"), Ui.GREEN, {
        onClick: (v) => { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + p.get("phone")))); }
      });
      det.addView(call);
      Ui.margins(call, 0, 8, 0, 0);
      if (WhatsApp.usable(p.get("phone"))) {
        const wa = Ui.outlineButton(this, "💬 WhatsApp " + p.get("phone"), WhatsApp.GREEN, { onClick: (v) => { WhatsApp.chat(this, p.get("phone"), null); } });
        det.addView(wa);
        Ui.margins(wa, 0, 8, 0, 0);
      }
    }
    page.addView(det);

    const ev = db.rows("SELECT * FROM events WHERE patient_id=?" + Db.EVENT_ORDER, String(id));
    page.addView(PatientDesign.heading(this, "Timeline", ev.size() === 1 ? "1 event" : ev.size() + " events"));
    const tl = Ui.card(this);
    for (const e of ev) {
      const row = Ui.h(this);
      row.setGravity(Gravity.TOP);
      row.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
      const dot = new View(this);
      dot.setBackground(Ui.round(this, PatientActivity.eventColor(e), 6));
      const dp = Ui.lp(Ui.dp(this, 12), Ui.dp(this, 12));
      dp.topMargin = Ui.dp(this, 4);
      row.addView(dot, dp);
      const t = Ui.v(this);
      t.setPadding(Ui.dp(this, 12), 0, 0, 0);
      t.addView(Ui.tv(this, Db.eventLabel(e), 15, Ui.TEXT, true));
      const when = Dates.nice(e.get("date")) + (e.get("time").isEmpty() ? "" : "  " + e.get("time"));
      t.addView(Ui.muted(this, when + (e.get("note").isEmpty() ? "" : "  ·  " + e.get("note"))));
      row.addView(t, Ui.weight(1));
      tl.addView(row);
    }
    page.addView(tl);

    const more = Ui.card(this);
    more.addView(Ui.buttonRow(this,
        Ui.outlineButton(this, "Edit details", Ui.PRIMARY, this.opener(FormActivity, "kind", "patient", "id", String(id))),
        Ui.outlineButton(this, "Undo last step", Ui.ORANGE, {
          onClick: (v) => { this.undo(); }
        })));
    const del = Ui.outlineButton(this, "Delete this record", Ui.RED, {
      onClick: (v) => {
        Ui.confirm(this, "Delete record?", "This removes " + p.get("name") + " and their whole timeline from all counts.", "Delete", {
          run: () => {
            const sid = String(id);
            const snap = this.stepSnap().rowsWhere(db, "plex", "patient_id=?", sid).rowsWhere(db, "dama", "patient_id=?", sid).rowsWhere(db, "signoffs", "patient_id=?", sid);
            db.deletePatient(id);
            Undo.offer(this, "Deleted " + Ui.nz(p.get("name")) + " (X-ray and photos cannot come back)", snap);
            this.finish();
          }
        });
      }
    });
    more.addView(del);
    Ui.margins(del, 0, 8, 0, 0);
    page.addView(more);
    if (Base.wide(this)) {
      // tablet: the patient on the left, the timeline beside it
      const two = Ui.h(this);
      two.setGravity(Gravity.TOP);
      two.addView(page, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 3));
      const side = Ui.v(this);
      side.addView(Ui.heading(this, "Timeline", PatientTimeline.COLOR));
      const tc = Ui.card(this);
      tc.addView(PatientTimeline.view(this, PatientTimeline.build(db, id), null, 40));
      side.addView(tc);
      two.addView(side, new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 2));
      this.maxWidthDp = 1400;
      this.setPage(two);
    } else {
      this.setPage(page);
    }
    if (PatientActivity.damaDischarge === id) {
      PatientActivity.damaDischarge = 0;
      if (inn) this.discharge(Dama.DISCHARGE_TYPE);
    }
  }

  static eventColor(e) {
    const t = e.get("type");
    if (Db.ADMIT.equals(t)) return Ui.PRIMARY;
    if (Db.DISCHARGE.equals(t)) return Ui.GREEN;
    if (Db.DEATH.equals(t)) return Ui.SLATE;
    return Ui.unitColor(e.get("to_loc"));
  }

  when(f) {
    f.date("date", "Date", Dates.todayIso());
    f.time("time", "Time", Dates.now());
    return f;
  }

  /** Transfer to a fixed ward, or (to == null) let the user pick any ward. */
  transfer(to) {
    const db = this.db, p = this.p, id = this.id;
    const f = new Form(this);
    const from = p.get("location");
    if (to == null) {
      const opts = [];
      for (const l of Db.nextWards(from, p.get("home_unit"))) if (!l.equals(from)) opts.add(l);
      if ("1".equals(p.get("convict")) && !opts.contains(db.rotationUnit()) && !db.rotationUnit().equals(from)) opts.add(0, db.rotationUnit());
      const vals = ArrayList(opts);
      const labels = new Array(vals.length).fill(null);
      for (let i = 0; i < vals.length; i++) labels[i] = Db.unitName(vals[i]);
      f.choice("to", "Transfer to", labels, vals, vals[0], null);
    }
    this.when(f);
    f.text("bed", "New bed number", "", Form.TEXT);
    f.multi("note", "Reason / notes", "");
    const fixed = to;
    Ui.formDialog(this, to == null ? "Transfer " + p.get("name") : "Transfer to " + Db.unitName(to), f, "Transfer", {
      run: () => {
        const dest = fixed != null ? fixed : f.get("to");
        const home = Ui.nz(p.get("home_unit"));
        if (Db.isWardUnit(dest) && !dest.equals(home) && !(dest.equals(db.rotationUnit()) && "1".equals(p.get("convict")))) {
          // another unit's ward: that unit has to accept the case first
          Ui.toast(this, dest + " unit has to accept this case first");
          this.handOver(dest);
          return true;
        }
        const snap = this.stepSnap();
        db.addEvent(id, f.get("date"), f.get("time"), Db.TRANSFER, from, dest, f.get("note"));
        const cv = new ContentValues();
        cv.put("bed", f.get("bed"));
        db.update("patients", cv, id);
        this.render();
        Undo.offer(this, "Transferred to " + Db.shortName(dest), snap);
        return true;
      }
    });
  }

  handOver(to) {
    UnitMoves.requestDialog(this, this.db, this.p, to, { run: () => { this.render(); } });
  }

  discharge(preset) {
    const db = this.db, p = this.p, id = this.id;
    const f = this.when(new Form(this));
    // a case taken from another department goes back to it after treatment, or medicine discharges it
    const dept = Ui.nz(p.get("from_dept")).trim();
    const types = [];
    if (!dept.isEmpty()) types.add(Db.BACK_TO + dept);
    Collections.addAll(types, ...Db.DISCHARGE_TYPES);
    if (dept.isEmpty() && "OTHER_DEPT".equals(p.get("source"))) types.add(1, Db.BACK_TO + "the department it came from");
    const tv = ArrayList(types);
    f.choice("type", "Type of discharge", tv, tv, preset != null && types.contains(preset) ? preset : tv[0], null);
    const cs = CaseSheet.load(db, id);
    const fin = CaseSheet.s(cs, "final_dx");
    f.multi("dx", "Final diagnosis (needed to discharge)", fin.isEmpty() ? CaseSheet.withNewDiagnoses(Ui.nz(p.get("diagnosis")), cs) : fin);
    Icd11.attach(this, f, "dx");
    Diagnoses.attach(this, f, "dx");
    f.multi("note", "Advice / notes", "");
    Ui.formDialog(this, "Discharge " + p.get("name"), f, "Discharge", {
      run: () => {
        if (!f.require("dx", "Enter the final diagnosis before discharge")) return false;
        const snap = this.stepSnap();
        const dx = f.get("dx").trim();
        if (!dx.equals(CaseSheet.s(cs, "final_dx")) && CaseSheet.canEdit(this, db, p)) {
          try { cs.put("final_dx", dx); } catch (ignored) { }
          CaseSheet.save(db, id, cs);
        }
        const note = f.get("type") + ". Final diagnosis: " + dx + (f.get("note").isEmpty() ? "" : ". " + f.get("note"));
        db.addEvent(id, f.get("date"), f.get("time"), Db.DISCHARGE, p.get("location"), "", note);
        if (Dama.DISCHARGE_TYPE.equals(f.get("type")) && Dama.forPatient(db, id) == null)
          Ui.toast(this, "Discharged. Fill the DAMA form below for the signatures.");
        this.render();
        Undo.offer(this, "Discharged " + Ui.nz(p.get("name")), snap);
        return true;
      }
    });
  }

  /** IMCU and critical care by ward; otherwise triage on the day of admission, else the ward. */
  static defaultDeathPlace(p) {
    const loc = Ui.nz(p.get("location"));
    if (Db.IMCU.equals(loc)) return "IMCU";
    if (Db.CCB.equals(loc)) return "Critical care block";
    if (Db.TRIAGE.equals(loc)) return "Triage";
    const adm = Dates.parse(p.get("admit_date"));
    return adm != null && !adm.isBefore(Dates.admitDay()) ? "Triage" : "Ward";
  }

  death() {
    const db = this.db, p = this.p, id = this.id;
    const f = this.when(new Form(this));
    f.choice("place", "Place of death (for the census)", Db.DEATH_PLACES, Db.DEATH_PLACES, PatientActivity.defaultDeathPlace(p), null);
    f.multi("note", "Cause of death (type, or choose from the list)", "");
    Diagnoses.attach(this, f, "note");
    Ui.formDialog(this, "Record death of " + p.get("name"), f, "Save", {
      run: () => {
        if (!f.require("note", "Enter the cause of death")) return false;
        const snap = this.stepSnap();
        db.addEvent(id, f.get("date"), f.get("time"), Db.DEATH, p.get("location"), "", f.get("note"));
        const dp = new ContentValues();
        dp.put("death_place", f.get("place"));
        db.update("patients", dp, id);
        this.render();
        Undo.offer(this, "Death recorded", snap);
        return true;
      }
    });
  }

  /** The patient, the timeline and the case sheet as they are now, for the 10-second Undo bar (10.4). */
  stepSnap() {
    const db = this.db, id = this.id;
    return new Undo.Snap().rowsWhere(db, "events", "patient_id=?", String(id)).row(db, "patients", id).row(db, "case_sheets", id).patient(id);
  }

  undo() {
    const db = this.db, id = this.id;
    const last = db.row("SELECT * FROM events WHERE patient_id=? AND type<>?" + Db.EVENT_ORDER_DESC + " LIMIT 1", String(id), Db.ADMIT);
    if (last == null) {
      Ui.toast(this, "Nothing to undo; only the admission is recorded.");
      return;
    }
    Ui.confirm(this, "Undo last step?", "Remove: " + Db.eventLabel(last) + " on " + Dates.nice(last.get("date")), "Undo", {
      run: () => {
        db.undoLast(id);
        this.render();
      }
    });
  }
}
/** Set by the DAMA form's "Discharge as DAMA": the patient screen opens the discharge with that type chosen. */
PatientActivity.damaDischarge = 0;
;
