/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Picking an inpatient by typing: "Name · ward bed · IP no." suggestions, turned back into the patient's row. */
class PatientPick {
  static label(p) {
    const bed = Ui.nz(p.get("bed")).isEmpty() ? "" : " bed " + p.get("bed");
    const ip = Ui.nz(p.get("ip_no")).isEmpty() ? "" : " · IP " + p.get("ip_no");
    return Ui.nz(p.get("name")) + " · " + Db.shortName(p.get("location")) + bed + ip;
  }

  /** Inpatients now, optionally in one ward, keyed by their label. */
  static inpatients(db, ward) {
    const out = new JMap();
    const rows = ward == null ? db.rows("SELECT * FROM patients WHERE status='IN' ORDER BY location, bed, name")
      : db.rows("SELECT * FROM patients WHERE status='IN' AND location=? ORDER BY bed, name", ward);
    for (const p of rows) out.put(PatientPick.label(p), p);
    return out;
  }

  /** The patient a typed or picked label points to, or null. */
  static find(all, typed) {
    const t = Ui.nz(typed).trim();
    if (t.isEmpty()) return null;
    if (all.containsKey(t)) return all.get(t);
    for (const e of all.entrySet())
      if (Ui.nz(e.getValue().get("name")).equalsIgnoreCase(t) || Ui.nz(e.getValue().get("ip_no")).equalsIgnoreCase(t)) return e.getValue();
    return null;
  }
}
;
