'use strict';
/**
 * People (9.00): everyone's own photo beside their name, so faces are easy to put to names, and each unit's or special
 * ward's team board at the top of its census page. Photos live under people/, which every approved member can download.
 */
class People {
  static REQ_PICK = 9301;
  static REQ_CAMERA = 9302;
  static pendingStaff = 0;
  static pendingCapture = null;

  /** Team board order, with the heading each group gets. */
  static GROUPS = [
    ["HOD", "Head of the Department"],
    ["Professor", "Unit chief / Professor"],
    ["Associate Professor", "Associate Professor"],
    ["Assistant Professor", "Assistant Professors"],
    ["Postgraduate", "Postgraduates"],
    ["CRMI", "CRMIs"],
    ["MBBS", "MBBS students"]];
  static GROUP_COLORS = [0xFFB91C1C, 0xFF1D4ED8, 0xFF7C3AED, 0xFF0F766E, 0xFFDB2777, 0xFFEA580C, 0xFF16A34A];

  /** This phone's own photo can be changed; the admin, HOD and Registrar can set anyone's; everyone when not sharing records. */
  static canSet(c, staffId) {
    if (staffId <= 0) return false;
    return !Cloud.active(c) || Number(Cloud.myStaff(c)) === Number(staffId) || Cloud.isAdmin(c);
  }

  /** Gallery, camera, view or remove. */
  static choose(a, staffId) {
    const s = a.db.row("SELECT * FROM staff WHERE id=?", String(staffId));
    if (s == null) {
      Ui.toast(a, "Your account is not linked to the Students / Faculty list yet. The admin links it in Members.");
      return;
    }
    const has = !Ui.nz(s.get("photo")).isEmpty();
    const items = [];
    items.add("Choose from gallery");
    items.add("Take a photo");
    if (has) { items.add("View photo"); items.add("Remove photo"); }
    new AlertDialog.Builder(a).setTitle(Number(Cloud.myStaff(a)) === Number(staffId) ? "Your photo" : "Photo · " + s.get("name"))
      .setItems(items, {
        onClick: (d, w) => {
          const it = items.get(w);
          People.pendingStaff = staffId;
          if (it.startsWith("Choose")) Store.pick(a, ["image/*"], People.REQ_PICK);
          else if (it.startsWith("Take")) {
            People.pendingCapture = "people/capture_" + System.currentTimeMillis() + ".jpg";
            Store.capture(a, People.pendingCapture, People.REQ_CAMERA);
          } else if (it.startsWith("View")) Ui.showImage(a, a.db.file(s.get("photo")));
          else People.set(a, staffId, null);
        }
      }).show();
  }

  /** Base passes every activity result here first; true when it was a photo for People. */
  static onResult(a, req, res, data) {
    if (req !== People.REQ_PICK && req !== People.REQ_CAMERA) return false;
    try {
      if (req === People.REQ_CAMERA) {
        const f = People.pendingCapture == null ? null : a.db.file(People.pendingCapture);
        if (res === RESULT_OK && f != null && f.exists() && f.length() > 0) People.set(a, People.pendingStaff, Store.savePhoto(a, null, f, People.pendingStaff));
        if (f != null) f.delete();
        People.pendingCapture = null;
      } else if (res === RESULT_OK && data != null && data.getData() != null) {
        People.set(a, People.pendingStaff, Store.savePhoto(a, data.getData(), null, People.pendingStaff));
      }
    } catch (e) {
      Ui.toast(a, "Could not use that photo: " + e.getMessage());
    }
    return true;
  }

  static set(a, staffId, rel) {
    const cur = a.db.row("SELECT photo FROM staff WHERE id=?", String(staffId));
    if (cur == null) return;
    a.db.forgetFile(cur.get("photo"));
    const cv = new ContentValues();
    cv.put("photo", rel == null ? "" : rel);
    a.db.update("staff", cv, staffId);
    Ui.toast(a, rel == null ? "Photo removed" : "Photo saved. Everyone in the department will see it beside your name.");
    a.render();
  }

  /** A round photo (or initials) that opens the photo choices when it is this person's own (or the admin's to set). */
  static avatar(a, s, sizeDp, color) {
    const av = Store.avatar(a, s, sizeDp, color);
    const id = Ui.toLong(Ui.nz(s.get("id")), 0);
    const has = !Ui.nz(s.get("photo")).isEmpty() && a.db.file(s.get("photo")).exists();
    if (People.canSet(a, id)) {
      av.setOnClickListener({
        onClick: (v) => { People.choose(a, id); }
      });
      av.setContentDescription("Photo of " + Ui.nz(s.get("name")) + ": tap to change");
    } else if (has) {
      av.setOnClickListener({
        onClick: (v) => { Ui.showImage(a, a.db.file(s.get("photo"))); }
      });
    }
    return av;
  }

  /** The signed-in person's own photo with a small "+" when there is none yet; null when not linked to a staff entry. */
  static mine(a, sizeDp, color) {
    const sid = Cloud.myStaff(a);
    const s = sid > 0 ? a.db.row("SELECT * FROM staff WHERE id=?", String(sid)) : null;
    if (s == null) return null;
    const fl = new FrameLayout(a);
    fl.addView(People.avatar(a, s, sizeDp, color));
    if (Ui.nz(s.get("photo")).isEmpty()) {
      const plus = Ui.tv(a, "+", 13, Color.WHITE, true);
      plus.setGravity(Gravity.CENTER);
      plus.setBackground(Ui.round(a, Ui.GREEN, 9));
      const lp = new FrameLayoutParams(Ui.dp(a, 18), Ui.dp(a, 18), Gravity.BOTTOM | Gravity.END);
      fl.addView(plus, lp);
    }
    return fl;
  }

  // ---------- team board ----------

  static group(role) {
    const r = Ui.nz(role);
    if (r.startsWith("MBBS")) return 6;
    for (let i = 0; i < People.GROUPS.length; i++) if (People.GROUPS[i][0] === r) return i;
    return -1;
  }

  /** The members of a unit or special ward, in board order (PGs final year first). */
  static team(db, code) {
    const all = db.rows("SELECT * FROM staff WHERE unit=? AND " + Approvals.APPROVED_SQL + " ORDER BY name", code);
    const out = [];
    for (let g = 0; g < People.GROUPS.length; g++) {
      const inG = [];
      for (const s of all) if (People.group(s.get("role")) === g) inG.add(s);
      if (g === 4) inG.sort((x, y) => CaseSheet.pgYear(y.get("batch"), Dates.today()) - CaseSheet.pgYear(x.get("batch"), Dates.today()));
      out.addAll(inG);
    }
    return out;
  }

  /** 10.33: the dark board of the user's picture: navy glass, gold headings and neon rings around each person. */
  static NIGHT = 0xFF0B1442;
  static GOLD = 0xFFF5C451;
  static NEON = [0xFFA855F7, 0xFF3B82F6, 0xFF22C55E, 0xFFD946EF, 0xFF06B6D4, 0xFFF97316, 0xFFEC4899];
  static GROUP_ICONS = ["👑", "🎓", "🎓", "🎓", "🎓", "🩺", "🎓"];

  /** The colourful team board shown first on a unit's or special ward's page. */
  static board(a, db, code) {
    let teamOf = code;
    let note = null;
    // the ID ward is run each month by one unit in turn
    if (Db.IDW.equals(code)) {
      teamOf = db.rotationUnit();
      note = "In charge this month: " + Db.unitName(teamOf);
    }
    let people = new ArrayList();
    // 10.27: MBBS students have their own card under the board, by year (Posting.unitCard)
    for (const s of People.team(db, teamOf)) if (People.group(s.get("role")) !== 6) people.add(s);
    Away.mirror(a, db);
    let th = People.theme(code);
    let card = Ui.card(a);
    // 9.20: every unit and special ward keeps its own colour theme, now as the band and the glow on a navy board
    card.setBackground(new People.Night(a, th.c));
    card.setElevation(0);
    card.setPadding(Ui.dp(a, 12), Ui.dp(a, 16), Ui.dp(a, 12), Ui.dp(a, 16));

    // the unit's name in gold with its admission day, as in the picture
    let top = Ui.h(a);
    top.setGravity(Gravity.CENTER_VERTICAL);
    let tl = Ui.v(a);
    let title = Honours.goldText(a, Db.isWardUnit(code) ? Db.shortName(code) + " Unit" : Db.unitName(code), 30, true);
    title.setTypeface(Typeface.create(Typeface.SERIF, Typeface.BOLD));
    tl.addView(title);
    let day = Ui.toInt(db.unit(code).get("admit_day"), 0);
    let adm = Ui.tv(a, day === 0 ? "Admits every day" : "Admits every " + Dates.DAYS[day], 16, 0xFFF3D27A, false);
    adm.setTypeface(Typeface.create(Typeface.SERIF, Typeface.BOLD_ITALIC));
    tl.addView(adm);
    top.addView(tl, Ui.weight(1));
    let tr = Ui.v(a);
    tr.setGravity(Gravity.CENTER_HORIZONTAL);
    let ecg = new View(a);
    ecg.setBackground(new PgLeaveActivity.HeartEcg());
    tr.addView(ecg, Ui.lp(Ui.dp(a, 120), Ui.dp(a, 26)));
    let motto = Ui.tv(a, "LEARN  •  HEAL  •  SERVE", 10, 0xFFE9D9A6, true);
    motto.setLetterSpacing(0.12);
    tr.addView(motto);
    top.addView(tr);
    card.addView(top);
    Ui.margins(top, 6, 0, 0, 10);

    // the team band: theme gradient with waves, a gold ring with the team icon
    let band = new FrameLayout(a);
    band.setBackground(new People.Wave(a, th.c));
    let motif = Ui.tv(a, th.motif, 40, Color.WHITE, false);
    motif.setAlpha(0.35);
    band.addView(motif, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.END | Gravity.CENTER_VERTICAL));
    let head = Ui.h(a);
    head.setGravity(Gravity.CENTER_VERTICAL);
    head.setPadding(Ui.dp(a, 10), Ui.dp(a, 10), Ui.dp(a, 60), Ui.dp(a, 10));
    let ring = new FrameLayout(a);
    let rd = Ui.round(a, People.NIGHT, 26);
    rd.setStroke(Ui.dp(a, 2), People.GOLD);
    ring.setBackground(rd);
    let ic = new ImageView(a);
    ic.setImageResource(R.drawable.ic_people);
    ic.setColorFilter(People.GOLD);
    ring.addView(ic, new FrameLayout.LayoutParams(Ui.dp(a, 26), Ui.dp(a, 26), Gravity.CENTER));
    head.addView(ring, Ui.lp(Ui.dp(a, 52), Ui.dp(a, 52)));
    let tt = Ui.v(a);
    tt.setPadding(Ui.dp(a, 12), 0, 0, 0);
    tt.addView(Ui.tv(a, "Team board", 20, Color.WHITE, true));
    tt.addView(Ui.tv(a, th.name + " theme  ·  " + people.size() + (people.size() === 1 ? " member" : " members"), 13, 0xF2FFFFFF, false));
    head.addView(tt, Ui.weight(1));
    band.addView(head);
    card.addView(band, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    let inner = Ui.v(a);
    inner.setPadding(Ui.dp(a, 6), Ui.dp(a, 4), Ui.dp(a, 6), 0);
    card.addView(inner);
    let outer = card;
    card = inner;
    if (note !== null) {
      let nt = Ui.tv(a, note, 13, People.GOLD, true);
      card.addView(nt);
      Ui.margins(nt, 0, 8, 0, 0);
    }
    let chief = db.unitHead(teamOf);
    let chiefListed = false;
    for (const s of people) if (s.get("name").equalsIgnoreCase(chief)) chiefListed = true;
    if (!chief.isEmpty() && !chiefListed) {
      let ch = Ui.tv(a, (Db.isWardUnit(teamOf) ? "Unit chief: " : "In charge: ") + chief, 14, Color.WHITE, true);
      card.addView(ch);
      Ui.margins(ch, 0, 8, 0, 0);
    }
    let away = People.awayCard(a, db, people);
    if (away !== null) {
      card.addView(away);
      Ui.margins(away, 0, 10, 0, 0);
    }
    if (people.isEmpty()) {
      let e = Ui.tv(a, "No team members listed for " + Db.unitName(teamOf) + " yet. Add them in Faculty or Students with the unit set to "
          + Db.shortName(teamOf) + ", and they appear here with their photos.", 13, 0xCCFFFFFF, false);
      card.addView(e);
      Ui.margins(e, 0, 10, 0, 0);
      return outer;
    }
    let last = -1, n = 0;
    let flow = null;
    for (const s of people) {
      let g = People.group(s.get("role"));
      if (g !== last) {
        last = g;
        let gl = People.groupHeading(a, People.GROUP_ICONS[g], People.GROUPS[g][1]);
        card.addView(gl);
        Ui.margins(gl, 0, 14, 0, 6);
        flow = new Bands.Flow(a);
        card.addView(flow, Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT));
      }
      flow.addView(People.chip(a, s, People.NEON[n++ % People.NEON.length]));
    }
    let foot = Ui.h(a);
    foot.setGravity(Gravity.CENTER_VERTICAL);
    let hint = Ui.tv(a, "📷  Tap your own picture to add your photo.", 12, 0xB3FFFFFF, false);
    foot.addView(hint, Ui.weight(1));
    let good = Ui.tv(a, "Good Doctors Build\na Healthy Tomorrow ♥", 14, 0xFFF3D27A, false);
    good.setTypeface(Typeface.create(Typeface.SERIF, Typeface.BOLD_ITALIC));
    good.setGravity(Gravity.END);
    foot.addView(good);
    card.addView(foot);
    Ui.margins(foot, 0, 14, 0, 0);
    return outer;
  }

  /** A gold heading with its icon and a thin gold line running to the right. */
  static groupHeading(a, icon, s) {
    let r = Ui.h(a);
    r.setGravity(Gravity.CENTER_VERTICAL);
    let t = Ui.tv(a, icon + "  " + s.toUpperCase(), 13, People.GOLD, true);
    t.setLetterSpacing(0.06);
    r.addView(t);
    let dot = Ui.tv(a, "◆", 7, People.GOLD, false);
    dot.setPadding(Ui.dp(a, 10), 0, Ui.dp(a, 2), 0);
    r.addView(dot);
    let line = new View(a);
    line.setBackground(Ui.gradient(a, [0xCCF5C451, 0x00F5C451], 1));
    r.addView(line, new LinearLayoutParams(0, Ui.dp(a, 1), 1));
    return r;
  }

  /**
   * 9.72: "Who's in today" on the board: the faculty away today (leave, week off or on duty elsewhere) with the day they
   * are back, who of the faculty is in, and leave coming within a week, so the professor, the other APs and the PGs know.
   */
  static awayCard(a, db, people) {
    const today = Dates.today();
    const out = [], inn = [], soon = [];
    for (const s of people) {
      const g = People.group(s.get("role"));
      if (g < 0 || g > 3) continue;   // the faculty: HOD, Professor, Associate and Assistant Professors
      const k = Away.on(db, s.get("id"), today.toString());
      if (!k.isEmpty()) {
        out.push(Away.icon(k) + "  " + s.get("name") + "  ·  " + (k.equals("On duty") ? "on duty elsewhere" : k.equals("Week off") ? "week off" : "on leave")
          + ", back " + Away.day(Away.backOn(db, s.get("id"), today)));
        continue;
      }
      inn.push(s.get("name"));
      const d = Away.soon(db, s.get("id"), today);
      if (d != null) soon.push(s.get("name") + " from " + Away.day(d));
    }
    if (out.length === 0 && soon.length === 0) return null;
    const c = Ui.v(a);
    c.setPadding(Ui.dp(a, 12), Ui.dp(a, 10), Ui.dp(a, 12), Ui.dp(a, 10));
    const edge = out.length === 0 ? Away.DUTY : Away.LEAVE;
    c.setBackground(Ui.outline(a, Ui.mix(edge, Color.WHITE, 0.9), edge, 16));
    if (out.length > 0) {
      c.addView(Ui.tv(a, "🌴  Away today", 15, Ui.mix(Away.LEAVE, Color.BLACK, 0.45), true));
      for (const l of out) c.addView(Ui.tv(a, l, 14, Ui.TEXT, true));
      const t = inn.length > 0 ? Ui.tv(a, "✅  In today: " + TextUtils.join(", ", inn), 13, Ui.mix(Ui.GREEN, Color.BLACK, 0.2), true)
        : Ui.tv(a, "⚠️  No faculty of this unit in today: call the professor or the HOD for decisions", 13, Ui.RED, true);
      c.addView(t);
      Ui.margins(t, 0, 6, 0, 0);
    }
    if (soon.length > 0) {
      const t = Ui.tv(a, "🗓️  Leave coming: " + TextUtils.join("; ", soon), 13, Ui.mix(Away.DUTY, Color.BLACK, 0.3), true);
      c.addView(t);
      if (out.length > 0) Ui.margins(t, 0, 6, 0, 0);
    }
    return c;
  }

  /** A unit's board theme: a name, three colours for the band, and a motif. */
  static theme(code) {
    const keys = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.CCB, Db.FEVER, Db.TRIAGE, Db.STEPDOWN, Db.IDW, Db.GERI, Db.RHEUM, Db.KDP];
    const themes = [
      ["Ocean", "🌊", 0xFF1D4ED8, 0xFF0EA5E9, 0xFF22D3EE],
      ["Forest", "🌿", 0xFF047857, 0xFF10B981, 0xFF84CC16],
      ["Sunset", "🌅", 0xFFEA580C, 0xFFF43F5E, 0xFFFBBF24],
      ["Royal", "👑", 0xFF6D28D9, 0xFF8B5CF6, 0xFFEC4899],
      ["Rose", "🌸", 0xFFBE185D, 0xFFF472B6, 0xFFFB7185],
      ["Marigold", "🌼", 0xFFC2410C, 0xFFF59E0B, 0xFFFDE047],
      ["Aurora", "✨", 0xFF0F766E, 0xFF06B6D4, 0xFFA78BFA],
      ["Crimson", "❤️", 0xFFB91C1C, 0xFFEF4444, 0xFFF97316],
      ["Midnight", "🛡️", 0xFF1E3A8A, 0xFF3B82F6, 0xFF14B8A6],
      ["Coral", "🌡️", 0xFFE11D48, 0xFFFB923C, 0xFFFACC15],
      ["Lagoon", "🚑", 0xFF0369A1, 0xFF2DD4BF, 0xFFA3E635],
      ["Lilac", "🪜", 0xFF7E22CE, 0xFFC084FC, 0xFF60A5FA],
      ["Jade", "🧪", 0xFF15803D, 0xFF22C55E, 0xFF0EA5E9],
      ["Copper", "🌳", 0xFF92400E, 0xFFD97706, 0xFFF59E0B],
      ["Berry", "🦋", 0xFF9D174D, 0xFFDB2777, 0xFF8B5CF6],
      ["Meadow", "🏡", 0xFF3F6212, 0xFF65A30D, 0xFF0D9488]];
    const i = keys.indexOf(code);
    if (i >= 0) { const t = themes[i]; return {name: t[0], motif: t[1], c: [t[2], t[3], t[4]]}; }
    const c = Ui.unitColor(code);
    return {name: "Classic", motif: "⭐", c: [c, Ui.mix(c, 0xFFDB2777, 0.35), Ui.mix(c, Color.WHITE, 0.3)]};
  }

  /** One person on the board: a dark glass pill with a neon ring, the photo, the name, and their year or role. */
  static chip(a, s, color) {
    let c = Ui.h(a);
    c.setGravity(Gravity.CENTER_VERTICAL);
    // 9.72: someone away today: a sunny dashed card, a faded photo with a 🌴 / ✈️ badge and the day they are back
    let away = Away.on(a.db, s.get("id"), Dates.todayIso());
    let d = new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,
        [Ui.mix(color, People.NIGHT, 0.72), 0xFF121C4E, 0xFF0E1640]);
    d.setCornerRadius(Ui.dp(a, 30));
    if (away.isEmpty()) d.setStroke(Ui.dp(a, 2), Ui.mix(color, Color.WHITE, 0.15));
    else d.setStroke(Ui.dp(a, 2), Away.LEAVE, Ui.dp(a, 5), Ui.dp(a, 3));
    c.setBackground(d);
    c.setElevation(Ui.dp(a, 3));
    c.setPadding(Ui.dp(a, 4), Ui.dp(a, 4), Ui.dp(a, 16), Ui.dp(a, 4));
    let f = new FrameLayout(a);
    let ring = Ui.round(a, 0x00000000, 24);
    ring.setStroke(Ui.dp(a, 2), 0xE6FFFFFF);
    f.setBackground(ring);
    f.setPadding(Ui.dp(a, 3), Ui.dp(a, 3), Ui.dp(a, 3), Ui.dp(a, 3));
    let av = People.avatar(a, s, 40, Ui.mix(color, Color.WHITE, 0.1));
    if (!away.isEmpty()) av.setAlpha(0.45);
    f.addView(av);
    if (!away.isEmpty()) {
      let badge = Ui.tv(a, Away.icon(away), 15, Ui.TEXT, false);
      f.addView(badge, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.END | Gravity.BOTTOM));
    }
    c.addView(f, Ui.lp(Ui.dp(a, 48), Ui.dp(a, 48)));
    let t = Ui.v(a);
    t.setPadding(Ui.dp(a, 10), 0, 0, 0);
    t.addView(Ui.tv(a, "👤  " + s.get("name"), 14, Color.WHITE, true));
    let y = "Postgraduate".equals(s.get("role")) ? CaseSheet.pgYear(s.get("batch"), Dates.today()) : 0;
    let sub = y > 0 ? (y === 3 ? "Final year" : y === 2 ? "2nd year" : "1st year") : Ui.nz(s.get("role")).startsWith("MBBS") ? s.get("role").split("MBBS ").join("") : "";
    if (!sub.isEmpty()) {
      let st = Ui.tv(a, sub, 11, Ui.mix(color, Color.WHITE, 0.55), true);
      st.setPadding(Ui.dp(a, 22), 0, 0, 0);
      t.addView(st);
    }
    if (!away.isEmpty()) t.addView(Ui.tv(a, (away.equals("On duty") ? "On duty elsewhere" : away.equals("Week off") ? "Week off" : "On leave") + " · back "
        + Away.day(Away.backOn(a.db, s.get("id"), Dates.today())), 11, 0xFFFCD34D, true));
    c.addView(t);
    return c;
  }
}

/** The navy board: deep blue gradient, the theme's glow along the edge and its waves in the lower right corner. */
People.Night = class extends Drawable {
  constructor(ctx, c) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.c = c;
    this.dp = Ui.dp(ctx, 1);
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, c = this.c, dp = this.dp;
    const rad = 22 * dp, w = b.width(), h = b.height();
    const r = new RectF(b.left + dp, b.top + dp, b.right - dp, b.bottom - dp);
    p.setStyle(Paint.Style.FILL);
    p.setShader(new LinearGradient(b.left, b.top, b.right, b.bottom, [0xFF0A1440, People.NIGHT, 0xFF160F4A], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);
    // waves in the lower right, in the theme's colours
    cv.save();
    const clip = new Path();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    for (let k = 0; k < 3; k++) {
      const wv = new Path();
      const base = b.bottom - h * (0.05 + 0.045 * k), x0 = b.left + w * (0.45 + 0.08 * k), amp = 10 * dp * (1 + k * 0.3);
      wv.moveTo(x0, b.bottom);
      wv.lineTo(x0, base);
      for (let i = 0; i <= 24; i++) {
        const x = x0 + (b.right - x0) * i / 24;
        wv.lineTo(x, base - amp * Math.sin(i / 24 * Math.PI * 2.2 + k) - (x - x0) * 0.06 * (k + 1));
      }
      wv.lineTo(b.right, b.bottom);
      wv.close();
      p.setShader(new LinearGradient(x0, base - 40 * dp, b.right, b.bottom, [Ui.alpha(c[k % c.length], 0x00), Ui.alpha(c[k % c.length], 0x55)], null, Shader.TileMode.CLAMP));
      cv.drawPath(wv, p);
    }
    cv.restore();
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(2 * dp);
    p.setShader(new LinearGradient(b.left, b.top, b.right, b.bottom, [Ui.alpha(c[1], 0xCC), Ui.alpha(c[0], 0x66), Ui.alpha(People.GOLD, 0xAA)], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);
    p.setShader(null);
  }

  setAlpha(a) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** The team band: the theme's gradient with two soft white waves and a light rim. */
People.Wave = class extends Drawable {
  constructor(ctx, c) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.c = c;
    this.dp = Ui.dp(ctx, 1);
  }

  draw(cv) {
    const b = this.getBounds(), p = this.p, c = this.c, dp = this.dp;
    const rad = b.height() / 2, w = b.width(), h = b.height();
    const r = new RectF(b.left, b.top, b.right, b.bottom);
    p.setStyle(Paint.Style.FILL);
    p.setShader(new LinearGradient(b.left, 0, b.right, 0, [Ui.mix(c[0], People.NIGHT, 0.35), c[0], c[1], c[2]], null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, rad, rad, p);
    cv.save();
    const clip = new Path();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    p.setShader(null);
    for (let k = 0; k < 2; k++) {
      const wv = new Path();
      const base = b.top + h * (0.62 + 0.16 * k), x0 = b.left + w * 0.4;
      wv.moveTo(x0, b.bottom);
      wv.lineTo(x0, base);
      for (let i = 0; i <= 20; i++) {
        const x = x0 + (b.right - x0) * i / 20;
        wv.lineTo(x, base - h * 0.12 * Math.sin(i / 20 * Math.PI * 3 + k * 1.3));
      }
      wv.lineTo(b.right, b.bottom);
      wv.close();
      p.setColor(k === 0 ? 0x2EFFFFFF : 0x40FFFFFF);
      cv.drawPath(wv, p);
    }
    cv.restore();
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(1.5 * dp);
    p.setColor(0x66FFFFFF);
    cv.drawRoundRect(new RectF(b.left + dp, b.top + dp, b.right - dp, b.bottom - dp), rad, rad, p);
  }

  setAlpha(a) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};
;
