'use strict';
/**
 * PG Connect, one conversation between this phone's ward and another ward (or the all-wards room).
 * WhatsApp look; end-to-end encrypted; no screenshots, no copy, no forward.
 */
class PgChatActivity extends Base {
  constructor() {
    super();
    this.with = null;
    this.mine = null;
    this.root = null;
    this.kinds = null;
    this.top = null;
    this.list = null;
    this.input = null;
    this.patient = null;
    this.kind = 0;
    this.jumpBottom = true;
    this.handler = new Handler(Looper.getMainLooper());
    this.fast = {
      run: () => {
        Sync.kick(this);
        this.handler.postDelayed(this.fast, 5000);
      }
    };
  }

  onCreate(b) {
    super.onCreate(b);
    if (!PgConnect.canUse(this, this.db)) {
      Ui.toast(this, "PG Connect is only for postgraduates and the admin");
      this.finish();
      return;
    }
    PgConnect.noteAdmin(this, this.db);
    this.getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE, WindowManager.LayoutParams.FLAG_SECURE);
    this.with = Ui.nz(this.getIntent().getStringExtra("with"));
    if (this.with.isEmpty()) this.with = PgConnect.ALL;
    this.headerColor(PgConnect.DARK);
    E2e.ensureKey(this, this.db);
  }

  onResume() {
    super.onResume();
    this.handler.removeCallbacks(this.fast);
    this.handler.postDelayed(this.fast, 5000);
  }

  onPause() {
    super.onPause();
    this.handler.removeCallbacks(this.fast);
  }

  liveRefresh() {
    return true;
  }

  render() {
    if (this.isFinishing()) return;
    this.mine = PgConnect.myWard(this, this.db);
    if (this.root == null) {
      this.root = Ui.v(this);
      this.root.setBackgroundColor(Chat.WALL);
      this.top = new FrameLayout(this);
      this.root.addView(this.top, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
      this.list = new ScrollView(this);
      this.list.setFillViewport(true);
      this.root.addView(this.list, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
      this.root.addView(this.composer());
      this.setContentView(this.root);
    }
    this.top.removeAllViews();
    this.top.addView(this.header());
    const bottom = this.jumpBottom || !this.list.canScrollVertically(1);
    this.jumpBottom = false;
    const oldY = this.list.getScrollY();
    this.list.removeAllViews();
    this.list.addView(this.messages());
    this.list.post({
      run: () => {
        if (bottom) this.list.fullScroll(View.FOCUS_DOWN);
        else this.list.scrollTo(0, oldY);
      }
    });
    PgConnect.markRead(this, this.mine, this.with);
  }

  header() {
    this.getWindow().setStatusBarColor(PgConnect.DARK);
    const h = Ui.h(this);
    h.setGravity(Gravity.CENTER_VERTICAL);
    h.setBackgroundColor(PgConnect.DARK);
    h.setPadding(Ui.dp(this, 4), Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8));
    h.setElevation(Ui.dp(this, 4));
    const back = new ImageView(this);
    back.setImageResource(R.drawable.ic_back);
    back.setColorFilter(Color.WHITE);
    const p = Ui.dp(this, 8);
    back.setPadding(p, p, p, p);
    Ui.ripple(back, 0x44FFFFFF);
    back.setOnClickListener({ onClick: (v) => { this.finish(); } });
    h.addView(back, Ui.lp(Ui.dp(this, 40), Ui.dp(this, 40)));
    h.addView(PgConnectActivity.badge(this, this.with, 40));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 6), 0);
    const tt = Ui.tv(this, PgConnect.ALL.equals(this.with) ? "All wards" : PgConnect.shortName(this.mine) + "  ⇄  " + PgConnect.name(this.with), 17, Color.WHITE, true);
    tt.setSingleLine(true);
    tt.setEllipsize(TextUtils.TruncateAt.END);
    t.addView(tt);
    const st = Ui.tv(this, "🔒 end-to-end encrypted  ·  you write as " + PgConnect.shortName(this.mine), 12, 0xD9FFFFFF, false);
    st.setSingleLine(true);
    t.addView(st);
    h.addView(t, Ui.weight(1));
    return h;
  }

  messages() {
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8));
    const note = Ui.tv(this, "🔒 Messages and patient details are end-to-end encrypted. Only the PGs and the admin can open them; "
        + "the server never sees them.\n🚫 Screenshots, copying and forwarding are blocked.\n🗑 Messages are deleted automatically after one month.", 12, 0xFF54656F, false);
    note.setGravity(Gravity.CENTER);
    note.setBackground(Ui.round(this, 0xFFFFF5C4, 10));
    note.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 8));
    box.addView(note);
    Ui.margins(note, 20, 4, 20, 8);
    const ms = PgConnect.conversation(this.db, this.mine, this.with);
    if (ms.isEmpty()) {
      const t = Ui.tv(this, PgConnect.ALL.equals(this.with) ? "Write to every ward at once 👋" : "Start the conversation with " + PgConnect.name(this.with) + " 👋", 13, 0xFF54656F, false);
      t.setGravity(Gravity.CENTER);
      box.addView(t);
      Ui.margins(t, 24, 16, 24, 0);
      return box;
    }
    let day = null;
    let prev = "";
    for (const m of ms) {
      const t = Chat.parse(m.get("time"));
      const d = t == null ? null : t.toLocalDate();
      if (d != null && !d.equals(day)) {
        day = d;
        const sep = Ui.tv(this, d.equals(Dates.today()) ? "Today" : d.equals(Dates.today().minusDays(1)) ? "Yesterday" : Dates.longFmt(d), 12, 0xFF54656F, true);
        sep.setBackground(Ui.round(this, 0xFFE1F3FB, 8));
        sep.setPadding(Ui.dp(this, 10), Ui.dp(this, 4), Ui.dp(this, 10), Ui.dp(this, 4));
        const c = Ui.h(this);
        c.setGravity(Gravity.CENTER);
        c.addView(sep);
        box.addView(c);
        Ui.margins(c, 0, 8, 0, 6);
        prev = "";
      }
      const who = Ui.nz(m.get("sender_id")) + "|" + Ui.nz(m.get("from_ward"));
      box.addView(this.bubble(m, !who.equals(prev)));
      prev = who;
    }
    return box;
  }

  bubble(m, first) {
    const db = this.db;
    const mine = this.mine, wth = this.with;
    const own = PgConnect.me(this).equals(m.get("sender_id")) && mine.equals(m.get("from_ward"));
    const deleted = "1" === m.get("deleted");
    const k = PgConnect.kindIndex(m.get("kind"));
    const kc = PgConnect.KIND_COLORS[k];
    const row = Ui.h(this);
    row.setGravity(own ? Gravity.END : Gravity.START);
    const b = Ui.v(this);
    b.setPadding(Ui.dp(this, 9), Ui.dp(this, 6), Ui.dp(this, 9), Ui.dp(this, 5));
    const fill = own ? Chat.BUBBLE_ME : Color.WHITE;
    b.setBackground(k === 4 && !deleted ? Ui.outline(this, fill, Ui.RED, 12) : Ui.round(this, fill, 12));
    b.setElevation(Ui.dp(this, 1));
    if (!own && first) {
      const from = PgConnect.ALL.equals(wth) || !mine.equals(m.get("to_ward")) ? PgConnect.shortName(m.get("from_ward")) + "  ·  " : "";
      const role = Ui.nz(m.get("by_role"));
      b.addView(Ui.tv(this, from + Ui.nz(m.get("by_name")) + (role.isEmpty() ? "" : "  (" + role + ")"), 13, Ui.mix(PgConnect.color(m.get("from_ward")), Color.BLACK, 0.15), true));
    }
    if (deleted) {
      const t = Ui.tv(this, "🚫 This message was deleted", 14, Ui.MUTED, false);
      t.setTypeface(t.getTypeface(), Typeface.ITALIC);
      b.addView(t);
    } else {
      if (k > 0) {
        const chip = Ui.tv(this, PgConnect.EMOJI[k] + " " + PgConnect.KINDS[k].toUpperCase(), 11, kc, true);
        chip.setBackground(Ui.round(this, Ui.alpha(kc, 0x1F), 8));
        chip.setPadding(Ui.dp(this, 7), Ui.dp(this, 2), Ui.dp(this, 7), Ui.dp(this, 2));
        const cr = Ui.h(this);
        cr.addView(chip);
        b.addView(cr);
        Ui.margins(cr, 0, 2, 0, 3);
      }
      const pt = Ui.nz(m.get("patient"));
      if (!pt.isEmpty()) {
        const pv = Ui.tv(this, "🛏 " + pt, 14, 0xFF111B21, true);
        pv.setBackground(Ui.round(this, 0x0F000000, 6));
        pv.setPadding(Ui.dp(this, 6), Ui.dp(this, 3), Ui.dp(this, 6), Ui.dp(this, 3));
        b.addView(pv);
        Ui.margins(pv, 0, 0, 0, 3);
      }
      const t = Ui.tv(this, Ui.nz(m.get("text")), 15, 0xFF111B21, false);
      t.setTextIsSelectable(false);
      b.addView(t);
      if (k > 0) {
        const ack = Ui.nz(m.get("ack_by"));
        if (!ack.isEmpty()) {
          b.addView(Ui.tv(this, "✓ Taken up by " + ack + "  ·  " + Chat.clock(m.get("ack_time")), 12, PgConnect.GREEN, true));
        } else if (mine.equals(m.get("to_ward"))) {
          const take = Ui.button(this, "✓ Take up", PgConnect.GREEN, {
            onClick: (v) => {
              PgConnect.acknowledge(this, db, m.get("id"));
              this.render();
            }
          });
          b.addView(take);
          Ui.margins(take, 0, 6, 0, 2);
        } else {
          b.addView(Ui.tv(this, "⏳ Waiting to be taken up", 12, 0xFFB45309, true));
        }
      }
    }
    const foot = Ui.h(this);
    foot.setGravity(Gravity.END | Gravity.CENTER_VERTICAL);
    foot.addView(Ui.tv(this, Chat.clock(m.get("time")), 11, 0xFF667781, false));
    if (own && !deleted) {
      const up = !Cloud.active(this) || db.num("SELECT COUNT(*) FROM outbox WHERE tbl=? AND pk=?", PgConnect.TABLE, m.get("id")) > 0;
      const tick = Ui.tv(this, up ? "✓" : "✓✓", 12, up ? 0xFF667781 : Chat.TICK_BLUE, true);
      foot.addView(tick);
      Ui.margins(tick, 4, 0, 0, 0);
    }
    b.addView(foot, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    if (!own && !deleted && Conduct.canReport(this, m.get("sender_id"))) {
      b.setOnLongClickListener({
        onLongClick: (v) => {
          Conduct.report(this, PgConnect.TABLE, m.get("id"), m.get("sender_id"), m.get("by_name"), m.get("text"), null);
          return true;
        }
      });
    }
    if (own && !deleted) {
      b.setOnLongClickListener({
        onLongClick: (v) => {
          new AlertDialog.Builder(this).setTitle("Delete this message for everyone?")
              .setPositiveButton("Delete", {
                onClick: (d, w) => {
                  PgConnect.deleteForAll(db, m.get("id"));
                  this.render();
                }
              }).setNegativeButton("Cancel", null).show();
          return true;
        }
      });
    }
    const max = toInt(this.getResources().getDisplayMetrics().widthPixels * 0.8);
    b.setMinimumWidth(Ui.dp(this, 90));
    const lp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    row.addView(b, lp);
    b.measure(View.MeasureSpec.makeMeasureSpec(max, View.MeasureSpec.AT_MOST), View.MeasureSpec.UNSPECIFIED);
    if (b.getMeasuredWidth() >= max) lp.width = max;
    // web: the bubble is laid out later, so cap its width the way the phone's measure pass does
    b.setMaxWidth(max);
    row.setPadding(own ? Ui.dp(this, 48) : 0, Ui.dp(this, first ? 6 : 2), own ? 0 : Ui.dp(this, 48), 0);
    return row;
  }

  composer() {
    const wrap = Ui.v(this);
    wrap.setBackgroundColor(0xFFF0F2F5);
    this.kinds = Ui.h(this);
    this.kinds.setPadding(Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6), 0);
    this.drawKinds();
    wrap.addView(Ui.hscroll(this, this.kinds));
    this.patient = new EditText(this);
    this.patient.setHint("🛏 Patient (optional): name, age/sex, IP no, bed");
    this.patient.setTextSize(14);
    this.patient.setSingleLine(true);
    this.patient.setBackground(Ui.round(this, Color.WHITE, 18));
    this.patient.setPadding(Ui.dp(this, 14), Ui.dp(this, 8), Ui.dp(this, 14), Ui.dp(this, 8));
    wrap.addView(this.patient, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    Ui.margins(this.patient, 6, 6, 6, 0);
    const bar = Ui.h(this);
    bar.setGravity(Gravity.BOTTOM);
    bar.setPadding(Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6), Ui.dp(this, 6));
    this.input = new EditText(this);
    this.input.setHint("Message");
    this.input.setTextSize(16);
    this.input.setMaxLines(5);
    this.input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
    this.input.setBackground(Ui.round(this, Color.WHITE, 22));
    this.input.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10));
    bar.addView(this.input, Ui.weight(1));
    const send = new ImageView(this);
    send.setImageResource(R.drawable.ic_send);
    send.setColorFilter(Color.WHITE);
    const p = Ui.dp(this, 11);
    send.setPadding(p, p, p, p);
    send.setBackground(Ui.round(this, PgConnect.GREEN, 23));
    Ui.ripple(send, 0x33000000);
    send.setOnClickListener({ onClick: (v) => { this.sendNow(); } });
    bar.addView(send, Ui.lp(Ui.dp(this, 46), Ui.dp(this, 46)));
    Ui.margins(send, 6, 0, 0, 0);
    wrap.addView(bar);
    return wrap;
  }

  drawKinds() {
    this.kinds.removeAllViews();
    for (let i = 0; i < PgConnect.KINDS.length; i++) {
      const n = i;
      const c = Ui.chip(this, PgConnect.EMOJI[i] + " " + PgConnect.KINDS[i], this.kind === i, PgConnect.KIND_COLORS[i]);
      c.setOnClickListener({ onClick: (v) => { this.kind = n; this.drawKinds(); } });
      this.kinds.addView(c);
      Ui.margins(c, 0, 0, 6, 0);
    }
  }

  sendNow() {
    const text = this.input.getText().toString().trim();
    if (text.isEmpty()) return;
    if (!PgConnect.ALL.equals(this.with) && this.with.equals(this.mine)) {
      Ui.toast(this, "Choose another ward to write to");
      return;
    }
    PgConnect.send(this, this.db, this.mine, this.with, PgConnect.KINDS[this.kind], this.patient.getText().toString().trim(), text);
    this.input.setText("");
    this.patient.setText("");
    this.kind = 0;
    this.drawKinds();
    this.jumpBottom = true;
    this.render();
    Sync.kick(this);
  }

  /** For tests. */
  typeAndSend(k, pt, text) {
    this.kind = k;
    this.patient.setText(pt);
    this.input.setText(text);
    this.sendNow();
  }
}
;
/* ---- app/PgConnect.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * PG Connect: WhatsApp-style messages between the medical units and the special wards (M1 to M7, triage, step-down,
 * IMCU, fever, CCB, ID ward, geriatric, rheumatology and Kandiyaperi), both ways, plus one room for all wards.
 * Only the postgraduates and the admin can use it (user's rule, 7.79): messages are end-to-end encrypted (E2e) for
 * their phones alone, and the screens block screenshots.
 */
class PgConnect {
  constructor() {}

  static TABLE = "pgc_msgs";
  /** Messages are deleted one month after they were sent (9.00), on every phone and on the server. */
  static KEEP_DAYS = 30;

  static cutoff() {
    return Chat.stamp(LocalDateTime.now().minusDays(PgConnect.KEEP_DAYS));
  }

  /** Removes this phone's PG Connect messages older than a month (without telling the server: it deletes its own). */
  static purgeOld(c) {
    const db = Db.get(c);
    const old = db.rows("SELECT id FROM " + PgConnect.TABLE + " WHERE time<?", PgConnect.cutoff());
    if (old.isEmpty()) return 0;
    const w = db.getWritableDatabase();
    w.beginTransaction();
    try {
      w.execSQL("INSERT INTO sync_mute VALUES (1)");
      for (const m of old) {
        w.delete(PgConnect.TABLE, "id=?", [m.get("id")]);
        w.delete("outbox", "tbl=? AND pk=?", [PgConnect.TABLE, m.get("id")]);
      }
      w.execSQL("DELETE FROM sync_mute");
      w.setTransactionSuccessful();
    } finally {
      w.endTransaction();
    }
    return old.size();
  }
  static ALL = "ALL";
  static KINDS = ["Message", "Opinion request", "Transfer / bed", "Result / update", "Urgent"];
  static EMOJI = ["💬", "🩺", "🛏", "🧪", "🚨"];
  static KIND_COLORS = [0xFF0F8A5F, 0xFF2563EB, 0xFF7C3AED, 0xFF0891B2, 0xFFDC2626];
  /** Settings row naming the admin's staff entry, so the PGs' phones lock messages for the admin too (only the admin may write admin_ settings). */
  static ADMIN_KEY = "admin_pgc_staff";

  static $clinit() {
    PgConnect.GREEN = Chat.GREEN;
    PgConnect.DARK = Chat.DARK;
  }

  /** Every ward that can talk: the units, the special wards (not TAEI, another department's) and Kandiyaperi. */
  static wards() {
    const out = [];
    for (const w of Db.CENSUS_WARDS) if (!Db.TAEI.equals(w)) out.add(w);
    out.add(Db.KDP);
    return out.slice();
  }

  static name(ward) {
    if (PgConnect.ALL.equals(ward)) return "All wards";
    return Db.isWardUnit(ward) ? ward + " unit" : Db.unitName(ward);
  }

  static shortName(ward) {
    return PgConnect.ALL.equals(ward) ? "All" : Db.shortName(ward);
  }

  static color(ward) {
    return PgConnect.ALL.equals(ward) ? PgConnect.GREEN : Ui.unitColor(ward);
  }

  static kindIndex(k) {
    const i = PgConnect.KINDS.indexOf(k);
    return i < 0 ? 0 : i;
  }

  /** The postgraduates and the admin; everyone while the phone is not shared online. */
  static canUse(c, db) {
    if (!Cloud.active(c) || Cloud.isOwner(c) || "pg" === Cloud.role(c)) return true;
    const sid = Cloud.myStaff(c);
    return sid > 0 && db.num("SELECT COUNT(*) FROM staff WHERE id=? AND role='Postgraduate'", String(sid)) > 0;
  }

  /** The admin's phone records which staff entry is the admin's. */
  static noteAdmin(c, db) {
    const sid = Cloud.myStaff(c);
    if (Cloud.isOwner(c) && sid > 0 && !String(sid).equals(db.setting(PgConnect.ADMIN_KEY, ""))) db.setSetting(PgConnect.ADMIN_KEY, String(sid));
  }

  /** Who can open a message: every postgraduate's staff entry and the admin's, as ",id,id,". */
  static audience(db) {
    const sb = new StringBuilder(",");
    for (const r of db.rows("SELECT id FROM staff WHERE role='Postgraduate'")) sb.append(r.get("id")).append(',');
    const admin = db.setting(PgConnect.ADMIN_KEY, "");
    if (!admin.isEmpty()) sb.append(admin).append(',');
    return sb.toString();
  }

  static prefs(c) {
    return c.getSharedPreferences("pgc", Context.MODE_PRIVATE);
  }

  /** The ward this phone writes from: chosen once, else the person's unit in the staff list, else today's admitting unit. */
  static myWard(c, db) {
    const w = PgConnect.prefs(c).getString("ward", "");
    if (!w.isEmpty()) return w;
    const sid = Cloud.myStaff(c);
    const s = sid > 0 ? db.row("SELECT unit FROM staff WHERE id=?", String(sid)) : null;
    const u = s == null ? "" : Ui.nz(s.get("unit"));
    if (PgConnect.wards().contains(u)) return u;
    return db.todaysUnit();
  }

  static setMyWard(c, ward) {
    PgConnect.prefs(c).edit().putString("ward", ward).apply();
  }

  static me(c) {
    const id = Chat.me(c);
    return id > 0 ? String(id) : "me";
  }

  /** The conversation between two wards (both ways), or the all-wards room, oldest first. */
  static conversation(db, mine, other) {
    if (PgConnect.ALL.equals(other)) return db.rows("SELECT * FROM " + PgConnect.TABLE + " WHERE to_ward=? ORDER BY time, id", PgConnect.ALL);
    return db.rows("SELECT * FROM " + PgConnect.TABLE + " WHERE (from_ward=? AND to_ward=?) OR (from_ward=? AND to_ward=?) ORDER BY time, id", mine, other, other, mine);
  }

  static last(db, mine, other) {
    if (PgConnect.ALL.equals(other)) return db.row("SELECT * FROM " + PgConnect.TABLE + " WHERE to_ward=? ORDER BY time DESC, id DESC LIMIT 1", PgConnect.ALL);
    return db.row("SELECT * FROM " + PgConnect.TABLE + " WHERE (from_ward=? AND to_ward=?) OR (from_ward=? AND to_ward=?) ORDER BY time DESC, id DESC LIMIT 1", mine, other, other, mine);
  }

  static seenKey(mine, other) {
    return "seen_" + mine + "_" + other;
  }

  static unread(c, db, mine, other) {
    const seen = PgConnect.prefs(c).getString(PgConnect.seenKey(mine, other), "");
    if (PgConnect.ALL.equals(other))
      return db.num("SELECT COUNT(*) FROM " + PgConnect.TABLE + " WHERE to_ward=? AND from_ward<>? AND time>? AND IFNULL(deleted,'')=''", PgConnect.ALL, mine, seen);
    return db.num("SELECT COUNT(*) FROM " + PgConnect.TABLE + " WHERE from_ward=? AND to_ward=? AND time>? AND IFNULL(deleted,'')=''", other, mine, seen);
  }

  static markRead(c, mine, other) {
    PgConnect.prefs(c).edit().putString(PgConnect.seenKey(mine, other), Chat.now()).apply();
  }

  static unreadAll(c, db) {
    const mine = PgConnect.myWard(c, db);
    let n = PgConnect.unread(c, db, mine, PgConnect.ALL);
    for (const w of PgConnect.wards()) if (!w.equals(mine)) n += PgConnect.unread(c, db, mine, w);
    return n;
  }

  /** Requests sent to this ward that nobody here has taken up yet. */
  static waiting(db, mine) {
    return db.rows("SELECT * FROM " + PgConnect.TABLE + " WHERE to_ward=? AND kind<>'Message' AND IFNULL(ack_by,'')='' AND IFNULL(deleted,'')='' "
        + "ORDER BY CASE WHEN kind='Urgent' THEN 0 ELSE 1 END, time DESC", mine);
  }

  static send(c, db, from, to, kind, patient, text) {
    const cv = new ContentValues();
    cv.put("from_ward", from);
    cv.put("to_ward", to);
    cv.put("kind", kind);
    cv.put("patient", patient);
    cv.put("text", text);
    cv.put("sender_id", PgConnect.me(c));
    cv.put("by_name", Chat.myName(c, db));
    cv.put("by_role", Cloud.active(c) ? Cloud.roleLabel(Cloud.role(c)) : "");
    cv.put("time", Chat.now());
    cv.put("members", "*");
    return db.insert(PgConnect.TABLE, cv);
  }

  static acknowledge(c, db, id) {
    const cv = new ContentValues();
    cv.put("ack_by", Chat.myName(c, db) + " (" + PgConnect.myWard(c, db) + ")");
    cv.put("ack_time", Chat.now());
    db.update(PgConnect.TABLE, cv, Long.parseLong(id));
  }

  static deleteForAll(db, id) {
    const cv = new ContentValues();
    cv.put("deleted", "1");
    cv.put("text", "");
    cv.put("patient", "");
    db.update(PgConnect.TABLE, cv, Long.parseLong(id));
  }

  /** For the background notification: new messages to this phone's ward (or all wards) since the last check. */
  static newSince(c, db, since) {
    const mine = PgConnect.myWard(c, db);
    return db.num("SELECT COUNT(*) FROM " + PgConnect.TABLE + " WHERE (to_ward=? OR to_ward=?) AND from_ward<>? AND sender_id<>? AND time>? AND IFNULL(deleted,'')=''",
        mine, PgConnect.ALL, mine, PgConnect.me(c), since);
  }
}
;
