/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * PG Connect, the chats list: one chat for each ward the user's ward talks to (units and special wards, both ways),
 * the all-wards room, and the requests waiting for this ward. WhatsApp look; screenshots are blocked.
 */
class PgConnectActivity extends Base {

  onCreate(b) {
    super.onCreate(b);
    if (!PgConnect.canUse(this, this.db)) {
      Ui.toast(this, "PG Connect is only for postgraduates and the admin");
      this.finish();
      return;
    }
    PgConnect.noteAdmin(this, this.db);
    this.getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE, WindowManager.LayoutParams.FLAG_SECURE);
    this.setTitle("PG Connect");
    this.headerColor(PgConnect.DARK);
    E2e.ensureKey(this, this.db);
  }

  /** A round ward badge: the ward's colour with its short name. */
  static badge(a, ward, sizeDp) {
    const s = PgConnect.shortName(ward);
    const t = Ui.tv(a, s.length > 4 ? s.substring(0, 3) : s, s.length > 3 ? sizeDp * 0.26 : sizeDp * 0.34, Color.WHITE, true);
    t.setGravity(Gravity.CENTER);
    const c = PgConnect.color(ward);
    const g = new GradientDrawable(GradientDrawable.Orientation.TL_BR, [Ui.mix(c, Color.WHITE, 0.15), Ui.mix(c, Color.BLACK, 0.3)]);
    g.setShape(GradientDrawable.OVAL);
    t.setBackground(g);
    t.setLayoutParams(Ui.lp(Ui.dp(a, sizeDp), Ui.dp(a, sizeDp)));
    if (PgConnect.ALL.equals(ward)) t.setText("ALL");
    return t;
  }

  render() {
    if (this.isFinishing()) return;
    const db = this.db;
    const mine = PgConnect.myWard(this, db);
    this.subtitle = "🔒 End-to-end encrypted  ·  " + PgConnect.name(mine);
    const page = Ui.v(this);
    page.setBackgroundColor(Color.WHITE);

    // who am I writing as
    const me = Ui.h(this);
    me.setGravity(Gravity.CENTER_VERTICAL);
    me.setBackground(Ui.gradient(this, [PgConnect.DARK, PgConnect.GREEN], 18));
    me.setPadding(Ui.dp(this, 14), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
    me.addView(PgConnectActivity.badge(this, mine, 46));
    const mt = Ui.v(this);
    mt.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    mt.addView(Ui.tv(this, "You write from " + PgConnect.name(mine), 15, Color.WHITE, true));
    mt.addView(Ui.tv(this, Chat.myName(this, db) + "  ·  tap to change ward", 12, 0xD9FFFFFF, false));
    me.addView(mt, Ui.weight(1));
    me.addView(Ui.tv(this, "▾", 20, Color.WHITE, true));
    me.setOnClickListener({ onClick: (v) => { this.pickWard(); } });
    const mp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    mp.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 4));
    page.addView(me, mp);
    const lock = Ui.tv(this, "🔒 Messages and patient details are locked on the sender's phone and opened only on the PGs' and the admin's phones. "
        + "The server never sees them. 🚫 Screenshots are blocked. 🗑 Messages are deleted automatically after one month.", 12, 0xFF54656F, false);
    lock.setBackground(Ui.round(this, 0xFFFFF5C4, 10));
    lock.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 8));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 4));
    page.addView(lock, lp);

    // requests waiting for this ward
    const wait = PgConnect.waiting(db, mine);
    if (!wait.isEmpty()) {
      page.addView(Ui.heading(this, "Waiting for " + PgConnect.shortName(mine) + "  ·  " + wait.size(), Ui.RED));
      for (const m of wait) page.addView(this.waitingRow(m));
    }

    // quick strip of every ward
    const strip = Ui.h(this);
    strip.setPadding(Ui.dp(this, 10), Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 4));
    const all = [];
    all.add(PgConnect.ALL);
    for (const w of PgConnect.wards()) if (!w.equals(mine)) all.add(w);
    for (const w of all) {
      const cell = Ui.v(this);
      cell.setGravity(Gravity.CENTER_HORIZONTAL);
      cell.setPadding(Ui.dp(this, 5), 0, Ui.dp(this, 5), 0);
      const f = new FrameLayout(this);
      const ring = new View(this);
      const rg = new GradientDrawable();
      rg.setShape(GradientDrawable.OVAL);
      const un = PgConnect.unread(this, db, mine, w);
      rg.setStroke(Ui.dp(this, 3), un > 0 ? PgConnect.GREEN : 0xFFD1D7DB);
      ring.setBackground(rg);
      f.addView(ring, new FrameLayout.LayoutParams(Ui.dp(this, 60), Ui.dp(this, 60)));
      const bd = PgConnectActivity.badge(this, w, 50);
      const bp = new FrameLayout.LayoutParams(Ui.dp(this, 50), Ui.dp(this, 50));
      bp.gravity = Gravity.CENTER;
      f.addView(bd, bp);
      cell.addView(f, Ui.lp(Ui.dp(this, 60), Ui.dp(this, 60)));
      const nm = Ui.tv(this, PgConnect.shortName(w), 11, Ui.TEXT, un > 0);
      nm.setGravity(Gravity.CENTER);
      cell.addView(nm);
      cell.setOnClickListener(this.opener(PgChatActivity, "with", w));
      strip.addView(cell);
    }
    page.addView(Ui.hscroll(this, strip));

    // the chats, newest first
    const rows = [];
    for (const w of all) {
      const last = PgConnect.last(db, mine, w);
      rows.add([w, last == null ? "" : Ui.nz(last.get("time"))]);
    }
    Collections.sort(rows, {
      compare: (a, b) => b[1].compareTo(a[1])
    });
    page.addView(Ui.heading(this, "Chats", PgConnect.GREEN));
    for (const r of rows) page.addView(this.chatRow(mine, r[0]));
    this.setPage(page);
  }

  chatRow(mine, w) {
    const db = this.db;
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(Ui.dp(this, 14), Ui.dp(this, 9), Ui.dp(this, 14), Ui.dp(this, 9));
    row.addView(PgConnectActivity.badge(this, w, 50));
    const mid = Ui.v(this);
    mid.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    const l1 = Ui.h(this);
    const nm = Ui.tv(this, PgConnect.ALL.equals(w) ? "All wards" : PgConnect.shortName(mine) + "  ⇄  " + PgConnect.name(w), 16, 0xFF111B21, true);
    nm.setSingleLine(true);
    l1.addView(nm, Ui.weight(1));
    const last = PgConnect.last(db, mine, w);
    const un = PgConnect.unread(this, db, mine, w);
    if (last != null) l1.addView(Ui.tv(this, Chat.clock(last.get("time")), 12, un > 0 ? PgConnect.GREEN : 0xFF667781, un > 0));
    mid.addView(l1);
    const l2 = Ui.h(this);
    l2.setGravity(Gravity.CENTER_VERTICAL);
    let pv;
    if (last == null) pv = PgConnect.ALL.equals(w) ? "Messages to every ward" : "No messages yet";
    else if ("1" === last.get("deleted")) pv = "🚫 This message was deleted";
    else {
      const k = PgConnect.kindIndex(last.get("kind"));
      const who = PgConnect.me(this).equals(last.get("sender_id")) ? "You" : Ui.nz(last.get("by_name"));
      pv = (k > 0 ? PgConnect.EMOJI[k] + " " : "") + who + ": " + Ui.nz(last.get("text"));
    }
    const p = Ui.tv(this, pv, 14, 0xFF667781, false);
    p.setSingleLine(true);
    p.setEllipsize(TextUtils.TruncateAt.END);
    l2.addView(p, Ui.weight(1));
    if (un > 0) {
      const b = Ui.tv(this, String(un), 12, Color.WHITE, true);
      b.setGravity(Gravity.CENTER);
      b.setBackground(Ui.round(this, PgConnect.GREEN, 11));
      b.setPadding(Ui.dp(this, 7), Ui.dp(this, 1), Ui.dp(this, 7), Ui.dp(this, 1));
      l2.addView(b);
    }
    mid.addView(l2);
    row.addView(mid, Ui.weight(1));
    Ui.ripple(row, 0x14000000);
    row.setOnClickListener(this.opener(PgChatActivity, "with", w));
    return row;
  }

  waitingRow(m) {
    const k = PgConnect.kindIndex(m.get("kind"));
    const card = Ui.card(this);
    const bg = Ui.round(this, Color.WHITE, 16);
    bg.setStroke(Ui.dp(this, 2), Ui.alpha(PgConnect.KIND_COLORS[k], 0x99));
    card.setBackground(bg);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(PgConnectActivity.badge(this, m.get("from_ward"), 34));
    const t = Ui.tv(this, "  " + PgConnect.EMOJI[k] + " " + m.get("kind") + " from " + PgConnect.shortName(m.get("from_ward")), 14, PgConnect.KIND_COLORS[k], true);
    top.addView(t, Ui.weight(1));
    top.addView(Ui.tv(this, Chat.clock(m.get("time")), 12, 0xFF667781, false));
    card.addView(top);
    if (!Ui.nz(m.get("patient")).isEmpty()) card.addView(Ui.tv(this, "🛏 " + m.get("patient"), 13, Ui.TEXT, true));
    const tx = Ui.tv(this, Ui.nz(m.get("text")), 14, Ui.TEXT, false);
    tx.setMaxLines(3);
    tx.setEllipsize(TextUtils.TruncateAt.END);
    card.addView(tx);
    card.addView(Ui.muted(this, "By " + Ui.nz(m.get("by_name"))));
    const r = Ui.h(this);
    const take = Ui.button(this, "✓ Take up", PgConnect.GREEN, {
      onClick: (v) => {
        PgConnect.acknowledge(this, this.db, m.get("id"));
        this.render();
      }
    });
    r.addView(take, Ui.weight(1));
    const open = Ui.outlineButton(this, "Open chat", PgConnect.GREEN, this.opener(PgChatActivity, "with", m.get("from_ward")));
    r.addView(open, Ui.weight(1));
    Ui.margins(open, 8, 0, 0, 0);
    card.addView(r);
    Ui.margins(r, 0, 8, 0, 0);
    return card;
  }

  pickWard() {
    const ws = PgConnect.wards();
    const names = new Array(ws.length).fill(null);
    for (let i = 0; i < ws.length; i++) names[i] = PgConnect.name(ws[i]);
    new AlertDialog.Builder(this).setTitle("Which ward are you writing from?").setItems(names, {
      onClick: (d, w) => {
        PgConnect.setMyWard(this, ws[w]);
        this.render();
      }
    }).setNegativeButton("Cancel", null).show();
  }
}
;
