'use strict';
/** Apply for (or edit) a PG's leave: dates, reason and the doing-duty PG; the signed letter is uploaded at the end (10.23). */
class PgLeaveFormActivity extends Base {
  constructor() {
    super();
    this.id = -1;
    this.r = null;
    this.form = null;
    this.letter = "";
    this.pendingScan = null;
    this.letterBox = null;
    this.built = false;
  }

  static REQ_PICK = 51;
  static REQ_SCAN = 52;
  static SPANS = ['One day', 'More than one day'];

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) {
      this.id = Long.parseLong(s);
      this.r = this.db.row("SELECT * FROM pg_leaves WHERE id=?", s);
      if (this.r != null) this.letter = Ui.nz(this.r.get("letter"));
    }
    // 10.45: what the PG leave page's Apply card already filled in (a new application only)
    const gx = (k) => Ui.nz(this.getIntent().getStringExtra(k));
    this.preType = this.r == null ? gx("pre_type") : ""; this.preFrom = this.r == null ? gx("pre_from") : ""; this.preTo = this.r == null ? gx("pre_to") : "";
    this.preReason = this.r == null ? gx("pre_reason") : ""; this.preDoc = this.r == null ? gx("pre_doc") : ""; this.preDocName = this.r == null ? gx("pre_doc_name") : ""; this.preDuty = this.r == null ? gx("pre_duty") : "";
    if (b != null) {
      this.letter = Ui.nz(b.getString("letter", this.letter));
      this.pendingScan = b.getString("pendingScan");
    }
    this.setTitle(this.r == null ? "Apply for PG leave" : "PG leave");
    this.subtitle = "In the app: Asst. Professor → Unit chief → Nodal officer · then HOD in person";
    this.headerColor(Ui.PURPLE);
    this.headerAction("Save", {
      onClick: (v) => { this.save(); }
    });
  }

  /** The approval steps, with Approve / Not approve for whoever's turn it is. */
  drawApprovals(ap) {
    ap.removeAllViews();
    for (let i = 0; i < PgLeaveActivity.APP_STEPS; i++) ap.addView(PgLeaveActivity.approvalRow(this, this.r, i, {
      run: () => { this.drawApprovals(ap); }
    }));
    const done = "Approved" === PgLeaveActivity.overall(this.r);
    const note = Ui.muted(this, done ? PgLeaveActivity.NEXT
      : "Any one Assistant Professor approves, then the unit chief, then the leave nodal officer. Each approval is printed on the form as \"Approved in the app on .. at ..\". Then download the form, sign it with the doing-duty PG, get the HOD's signature in person, submit it in the medicine office and upload the signed letter. Changing the dates resets the approvals.");
    note.setPadding(0, Ui.dp(this, 10), 0, 0);
    ap.addView(note);
  }

  onSaveInstanceState(b) {
    super.onSaveInstanceState(b);
    b.putString("letter", this.letter);
    b.putString("pendingScan", this.pendingScan);
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.built) { this.drawLetter(); return; }
    this.built = true;
    const r = this.r;
    const pgs = this.db.rows("SELECT id, name, unit FROM staff WHERE role='Postgraduate' AND " + Approvals.APPROVED_SQL + " ORDER BY name");
    const page = Ui.v(this);
    if (pgs.isEmpty()) {
      page.addView(this.emptyNote("Add the PGs to the staff list first (Menu → Students → PG)."));
      this.setPage(page);
      return;
    }
    const ids = new Array(pgs.size()).fill(null), names = new Array(pgs.size()).fill(null);
    for (let i = 0; i < pgs.size(); i++) {
      ids[i] = pgs.get(i).get("id");
      names[i] = pgs.get(i).get("name") + "  (" + Db.shortName(pgs.get(i).get("unit")) + ")";
    }
    const mine = Cloud.myStaff(this) > 0 ? String(Cloud.myStaff(this)) : ids[0];
    const card = Ui.card(this);
    this.form = new Form(this);
    const form = this.form;
    form.choice("staff_id", "PG", names, ids, r == null ? mine : r.get("staff_id"), null);
    const SPANS = PgLeaveFormActivity.SPANS;
    form.segment("span", "Leave for", SPANS, r == null ? (this.preTo.isEmpty() || this.preTo.equals(this.preFrom) ? SPANS[0] : SPANS[1]) : LeaveForm.oneDay(r) ? SPANS[0] : SPANS[1], null, {
      changed: (v) => {
        const one = SPANS[0].equals(v);
        form.show("on_date", one);
        form.show("from_date", !one);
        form.show("to_date", !one);
      }
    });
    form.date("on_date", "Date of leave", r == null ? (this.preFrom.isEmpty() ? Dates.todayIso() : this.preFrom) : r.get("from_date"));
    form.date("from_date", "Leave from", r == null ? (this.preFrom.isEmpty() ? Dates.todayIso() : this.preFrom) : r.get("from_date"));
    form.date("to_date", "Leave to", r == null ? (this.preTo.isEmpty() || this.preTo.equals(this.preFrom) ? Dates.today().plusDays(1).toString() : this.preTo) : r.get("to_date"));
    form.choice("leave_type", "Type of leave", LeaveForm.TYPES, LeaveForm.TYPES, r == null && !this.preType.isEmpty() ? this.preType : r == null || Ui.nz(r.get("leave_type")).isEmpty() ? LeaveForm.TYPES[0]
      : LeaveRules.pgKind(r.get("leave_type")) === LeaveRules.ACADEMIC ? LeaveRules.ACADEMIC : r.get("leave_type"), null);
    form.multi("reason", "Reason for leave (on account of) *", r == null ? this.preReason : r.get("reason"));
    form.date("resume_date", "Resuming duty on", r == null ? (this.preTo.isEmpty() ? Dates.today().plusDays(1) : Dates.parse(this.preTo).plusDays(1)).toString() : LeaveForm.resume(r));
    const others = [];
    others.add("");
    for (const p of pgs) others.add(p.get("name"));
    const on = others.slice(), ol = others.slice();
    ol[0] = "Not decided";
    form.choice("duty_pg", "Doing-duty PG (attends my duties)", ol, on, r == null ? this.preDuty : Ui.nz(r.get("duty_pg")), null);
    card.addView(form.view);
    const rule = Ui.muted(this, "📋  " + LeaveRules.pgRule());
    card.addView(rule);
    Ui.margins(rule, 0, 10, 0, 0);
    page.addView(card);

    if (r != null) {
      page.addView(Ui.heading(this, LeaveForm.name(r), Ui.PURPLE));
      const fm = Ui.card(this);
      fm.addView(Ui.muted(this, "Approved" === PgLeaveActivity.overall(r) ? "Download the form, sign it with the doing-duty PG, get the HOD's signature in person and submit it in the medicine office."
        : (LeaveForm.oneDay(r) ? "The one day leave application" : "The leave application for more than one day") + ", filled in from this entry, with the approvals given so far."));
      fm.addView(Ui.buttonRow(this,
        Ui.outlineButton(this, "Download PDF", Ui.PURPLE, {
          onClick: (v) => { LeaveForm.make(this, r, true); }
        }),
        Ui.outlineButton(this, "Download Word", Ui.PURPLE, {
          onClick: (v) => { LeaveForm.make(this, r, false); }
        })));
      page.addView(fm);
      page.addView(Ui.heading(this, "Approvals", Ui.PURPLE));
      const ap = Ui.card(this);
      this.drawApprovals(ap);
      page.addView(ap);
      // 10.23: last step, the letter signed by the PG, the doing-duty PG and the HOD, as submitted in the medicine office
      page.addView(Ui.heading(this, "Signed letter", Ui.PURPLE));
      this.letterBox = Ui.card(this);
      page.addView(this.letterBox);
      this.drawLetter();
      const del = Ui.outlineButton(this, "Withdraw this application", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Withdraw leave application?", "It will be deleted with its letter.", "Withdraw", {
            run: () => {
              this.db.forgetFile(this.letter);
              this.db.delete("pg_leaves", this.id);
              this.finish();
            }
          });
        }
      });
      page.addView(del);
      Ui.margins(del, 14, 14, 14, 0);
    }
    const save = Ui.button(this, r == null ? "Submit for approval" : "Save changes", Ui.PURPLE, {
      onClick: (v) => { this.save(); }
    });
    page.addView(save);
    Ui.margins(save, 14, 14, 14, 0);
    this.setPage(page);
  }

  drawLetter() {
    if (this.letterBox == null) return;
    this.letterBox.removeAllViews();
    const has = !this.letter.isEmpty() && this.db.file(this.letter).exists();
    if (has) {
      const row = Ui.h(this);
      row.addView(Ui.iconBadge(this, R.drawable.ic_verified, Ui.GREEN, 40));
      const t = Ui.v(this);
      t.setPadding(Ui.dp(this, 12), 0, 0, 0);
      t.addView(Ui.tv(this, "Letter attached", 15, Ui.TEXT, true));
      t.addView(Ui.muted(this, Store.kindLabel(this.letter) + "  ·  " + Store.sizeLabel(this.db.file(this.letter).length())));
      row.addView(t, Ui.weight(1));
      const v = Ui.softPill(this, "View", Ui.GREEN);
      v.setOnClickListener(this.opener(ViewerActivity, "file", this.letter, "title", "Leave letter"));
      row.addView(v);
      this.letterBox.addView(row);
    } else {
      this.letterBox.addView(Ui.muted(this, "After the HOD signs and the letter is submitted in the medicine office, upload the signed letter here: a PDF, a photo, or scan it with the camera."));
    }
    this.letterBox.addView(Ui.buttonRow(this,
      Ui.outlineButton(this, has ? "Replace with file" : "Choose PDF / photo", Ui.PURPLE, {
        onClick: (v) => { Store.pick(this, ["application/pdf", "image/*"], PgLeaveFormActivity.REQ_PICK); }
      }),
      Ui.outlineButton(this, "Scan with camera", Ui.PURPLE, {
        onClick: (v) => {
          this.pendingScan = "leaves/letter_" + System.currentTimeMillis() + ".jpg";
          Store.capture(this, this.pendingScan, PgLeaveFormActivity.REQ_SCAN);
        }
      })));
  }

  setLetter(rel) {
    if (!this.letter.isEmpty() && !this.letter.equals(rel) && (this.r == null || !this.letter.equals(this.r.get("letter")))) this.db.forgetFile(this.letter);
    this.letter = rel;
    // an existing application keeps the uploaded letter at once
    if (this.r != null) {
      const cv = new ContentValues();
      cv.put("letter", this.letter);
      this.db.update("pg_leaves", cv, this.id);
      this.r.put("letter", this.letter);
      Ui.toast(this, "Signed letter uploaded");
    }
    this.drawLetter();
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    try {
      if (req === PgLeaveFormActivity.REQ_SCAN) {
        const f = this.pendingScan == null ? null : this.db.file(this.pendingScan);
        if (res !== RESULT_OK || f == null || !f.exists() || f.length() === 0) { if (f != null) f.delete(); return; }
        if (!Store.shrink(f, 2400)) throw new Error("The camera did not return a picture");
        this.setLetter(this.pendingScan);
        this.pendingScan = null;
      } else if (req === PgLeaveFormActivity.REQ_PICK && res === RESULT_OK && data != null && data.getData() != null) {
        this.setLetter(Store.importUri(this, data.getData(), "leaves", "letter"));
      }
    } catch (e) {
      Ui.toast(this, "Could not attach: " + e.getMessage());
    }
  }

  save() {
    const form = this.form, r = this.r;
    if (form == null) return;
    const one = PgLeaveFormActivity.SPANS[0].equals(form.get("span"));
    const a = Dates.parse(form.get(one ? "on_date" : "from_date")), b = one ? a : Dates.parse(form.get("to_date"));
    if (a == null || b == null || b.isBefore(a)) { Ui.toast(this, "“Leave to” must be on or after “Leave from”"); return; }
    if (!one && !b.isAfter(a)) { Ui.toast(this, "For a single day choose “One day”, or set “Leave to” after “Leave from”"); return; }
    if (!form.require("reason", "Enter the reason")) return;
    if (Ui.nz(form.get("duty_pg")).isEmpty()) { Ui.toast(this, "Choose the doing-duty PG"); return; }
    const limit = LeaveRules.pgCheck(this.db, r == null ? -1 : this.id, form.get("staff_id"), form.get("leave_type"), a, ChronoUnit.DAYS.between(a, b) + 1);
    if (limit != null) { Ui.toast(this, limit); return; }
    const cv = new ContentValues();
    cv.put("staff_id", form.get("staff_id"));
    cv.put("from_date", a.toString());
    cv.put("to_date", b.toString());
    cv.put("days", ChronoUnit.DAYS.between(a, b) + 1);
    cv.put("reason", form.get("reason"));
    cv.put("leave_type", form.get("leave_type"));
    cv.put("duty_pg", form.get("duty_pg"));
    const back = Dates.parse(form.get("resume_date"));
    // left at the day after the old "Leave to": follow the new dates
    const oldTo = r == null ? Dates.today() : Dates.parse(r.get("to_date"));
    const followed = back != null && oldTo != null && back.equals(oldTo.plusDays(1));
    cv.put("resume_date", back == null || !back.isAfter(b) || followed ? b.plusDays(1).toString() : back.toString());
    cv.put("letter", this.letter);
    const datesChanged = r == null || !a.toString().equals(r.get("from_date")) || !b.toString().equals(r.get("to_date"))
      || !form.get("staff_id").equals(r.get("staff_id"));
    if (datesChanged) {
      for (let i = 0; i < PgLeaveActivity.LEVELS.length; i++) {
        const k = PgLeaveActivity.LEVELS[i];
        // 10.21: the Assistant Professor, the unit chief and the nodal officer approve in the app; the HOD signs in person
        cv.put(k + "_status", i < PgLeaveActivity.APP_STEPS ? "Pending" : "");
        cv.put(k + "_by", "");
        cv.put(k + "_date", "");
        if (i < PgLeaveActivity.APP_STEPS) cv.put(k + "_time", "");
      }
    }
    if (r == null) {
      cv.put("applied", Dates.todayIso());
      const nid = this.db.insert("pg_leaves", cv);
      if (!this.preDoc.isEmpty() && nid > 0) Attach.add(this, this.db, "pg_leaves", String(nid), this.preDoc, this.preDocName);
      Ui.toast(this, "Sent for approval");
    } else {
      if (!this.letter.equals(Ui.nz(r.get("letter")))) this.db.forgetFile(r.get("letter"));
      this.db.update("pg_leaves", cv, this.id);
      Ui.toast(this, "Saved");
    }
    this.finish();
  }
}
;
