/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Phone directory: HOD and admin, Professors, Associate and Assistant Professors, PGs, CRMIs, MBBS students and workers.
 * Faculty and students come from the staff list; the HOD's number from settings; admin, workers and other numbers from contacts.
 */
class PhoneDirectoryActivity extends Base {
  constructor() { super(); this.group = "All"; this.query = ""; this.list = null; }

  static COLOR = 0xFF2563EB;
  static CATS = ["ADMIN", "WORKER", "OTHER"];
  static CAT_LABELS = ["HOD office & admin", "Worker", "Other useful number"];
  static WORKER_ROLES = ["Nursing superintendent", "Staff nurse", "MNA / FNA (attender)", "Sanitary worker", "Lab technician",
    "ECG technician", "Data entry operator", "Ward clerk", "Office assistant", "Security", "Ambulance / driver", "Other"];

  /** The groups, in the order they are shown. */
  static HOD = "HOD & admin";
  static PROF = "Professors";
  static ASSOC = "Associate Professors";
  static ASST = "Assistant Professors";
  static PG = "PGs";
  static CRMI = "CRMIs";
  static MBBS = "MBBS students";
  static WORKERS = "Workers";
  static OTHER = "Other numbers";
  static GROUPS = ["HOD & admin", "Professors", "Associate Professors", "Assistant Professors", "PGs", "CRMIs", "MBBS students", "Workers", "Other numbers"];
  static GROUP_COLORS = [0xFF0B2E5C, 0xFF7C3AED, 0xFF9333EA, 0xFF2563EB, 0xFF0D9488, 0xFF059669, 0xFFD97706, 0xFFEA580C, 0xFF64748B];

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Phone directory");
    this.subtitle = "Faculty, students and workers";
    this.headerColor(PhoneDirectoryActivity.COLOR);
    if (PhoneDirectoryActivity.canEdit(this)) this.headerAction("+ Add", {
      onClick: (v) => { this.contactDialog(null); }
    });
  }

  /** Faculty and the HOD, the admin add and correct numbers; everyone can look them up. */
  static canEdit(c) {
    return SessionAttendance.canRun(c);
  }

  // ---------- gathering ----------

  static entries(db) {
    const P = PhoneDirectoryActivity;
    const out = [];
    const hod = db.setting("hod", "");
    if (!hod.isEmpty()) {
      const e = new P.Entry();
      e.name = hod;
      e.post = "Head of the Department";
      e.group = P.HOD;
      e.src = "hod";
      e.phone = db.setting("hod_phone", "");
      if (e.phone.isEmpty()) {
        const s = db.row("SELECT phone FROM staff WHERE name=? AND phone<>'' LIMIT 1", hod);
        if (s != null) e.phone = s.get("phone");
      }
      out.add(e);
    }
    P.addContacts(db, out, "ADMIN", P.HOD);
    const staffGroups = [["Professor", P.PROF], ["Associate Professor", P.ASSOC], ["Assistant Professor", P.ASST], ["Postgraduate", P.PG], ["CRMI", P.CRMI]];
    for (const g of staffGroups) {
      for (const s of db.rows("SELECT * FROM staff WHERE role=? AND " + Approvals.APPROVED_SQL + " ORDER BY name", g[0])) {
        if (g[0].equals("Professor") && s.get("name").equals(hod)) continue;
        out.add(P.fromStaff(s, g[1], P.unitPost(s)));
      }
    }
    for (const s of db.rows("SELECT * FROM staff WHERE role LIKE 'MBBS%' AND " + Approvals.APPROVED_SQL + " ORDER BY role, name")) {
      const post = s.get("role").split("MBBS ").join("") + (Ui.nz(s.get("batch")).isEmpty() ? "" : " · " + s.get("batch"));
      out.add(P.fromStaff(s, P.MBBS, post));
    }
    for (const s of db.rows("SELECT * FROM staff WHERE role IN ('Staff Nurse','Other') AND " + Approvals.APPROVED_SQL + " ORDER BY name"))
      out.add(P.fromStaff(s, P.WORKERS, s.get("role") + (P.unitPost(s).isEmpty() ? "" : " · " + P.unitPost(s))));
    P.addContacts(db, out, "WORKER", P.WORKERS);
    P.addContacts(db, out, "OTHER", P.OTHER);
    return out;
  }

  static unitPost(s) {
    const u = Ui.nz(s.get("unit"));
    return u.isEmpty() || u.equals("DEPT") ? "" : Db.unitName(u);
  }

  static fromStaff(s, group, post) {
    const e = new PhoneDirectoryActivity.Entry();
    e.name = s.get("name");
    e.phone = Ui.nz(s.get("phone"));
    e.post = post;
    e.group = group;
    e.src = "staff";
    e.id = s.get("id");
    return e;
  }

  static addContacts(db, out, cat, group) {
    for (const r of db.rows("SELECT * FROM contacts WHERE category=? ORDER BY designation, name", cat)) {
      const e = new PhoneDirectoryActivity.Entry();
      e.name = r.get("name");
      const post = [];
      if (!Ui.nz(r.get("designation")).isEmpty()) post.add(r.get("designation"));
      if (!Ui.nz(r.get("place")).isEmpty()) post.add(r.get("place"));
      e.post = TextUtils.join(" · ", post);
      e.phone = Ui.nz(r.get("phone"));
      if (!Ui.nz(r.get("phone2")).isEmpty()) e.phone += (e.phone.isEmpty() ? "" : ", ") + r.get("phone2");
      e.group = group;
      e.src = "contact";
      e.id = r.get("id");
      out.add(e);
    }
  }

  static matches(e, q) {
    if (q.isEmpty()) return true;
    const s = q.toLowerCase();
    const digits = q.replaceAllRx("\\D", "");
    return e.name.toLowerCase().contains(s) || e.post.toLowerCase().contains(s)
      || (!digits.isEmpty() && e.phone.replaceAllRx("\\D", "").contains(digits));
  }

  /** The first number in a field, digits only, for calling. */
  static dialable(phone) {
    const first = Ui.nz(phone).jsplit("[,/;]")[0];
    return first.replaceAllRx("[^+\\d]", "");
  }

  /** A 10-digit Indian mobile becomes 91XXXXXXXXXX for WhatsApp. */
  static whatsapp(phone) {
    let d = PhoneDirectoryActivity.dialable(phone).split("+").join("");
    if (d.length === 11 && d.startsWith("0")) d = d.substring(1);
    return d.length === 10 ? "91" + d : d;
  }

  // ---------- screen ----------

  render() {
    const P = PhoneDirectoryActivity;
    const page = Ui.v(this);
    const all = P.entries(this.db);

    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 2));
    const opts = [];
    opts.add("All");
    for (const g of P.GROUPS) opts.add(g);
    for (const g of opts) {
      let n = 0;
      for (const e of all) if (g.equals("All") || g.equals(e.group)) n++;
      if (n === 0 && !g.equals("All") && !g.equals(P.WORKERS)) continue;
      const c = Ui.chip(this, g + "  " + n, g.equals(this.group), g.equals("All") ? P.COLOR : P.colorOf(g));
      c.setOnClickListener({
        onClick: (v) => { this.group = g; this.render(); }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    const search = new EditText(this);
    search.setHint("Search name, post, unit or number");
    search.setSingleLine(true);
    search.setText(this.query);
    search.setBackground(Glass.panel(this, 14));
    search.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
    search.addTextChangedListener({
      beforeTextChanged: (s, a, b, c) => {},
      onTextChanged: (s, a, b, c) => {},
      afterTextChanged: (e) => { this.query = e.toString().trim(); this.fillList(); }
    });
    page.addView(search);
    Ui.margins(search, 12, 6, 12, 2);

    this.list = Ui.v(this);
    page.addView(this.list);
    this.fillList();
    this.setPage(page);
  }

  static colorOf(g) {
    const P = PhoneDirectoryActivity;
    for (let i = 0; i < P.GROUPS.length; i++) if (P.GROUPS[i].equals(g)) return P.GROUP_COLORS[i];
    return P.COLOR;
  }

  fillList() {
    const P = PhoneDirectoryActivity;
    this.list.removeAllViews();
    const all = P.entries(this.db);
    let shown = 0;
    for (const g of P.GROUPS) {
      if (!this.group.equals("All") && !this.group.equals(g)) continue;
      const inn = [];
      for (const e of all) if (e.group.equals(g) && P.matches(e, this.query)) inn.add(e);
      if (inn.isEmpty() && !(g.equals(P.WORKERS) && this.group.equals(P.WORKERS))) continue;
      this.list.addView(Ui.heading(this, g + "  (" + inn.size() + ")", P.colorOf(g)));
      const card = Ui.card(this);
      for (let i = 0; i < inn.size(); i++) {
        if (i > 0) card.addView(Ui.divider(this));
        card.addView(this.row(inn.get(i)));
      }
      if (inn.isEmpty()) card.addView(Ui.muted(this, P.canEdit(this) ? "No workers yet. Tap “+ Add” to add nurses, attenders, technicians and others." : "No workers added yet."));
      this.list.addView(card);
      shown += inn.size();
    }
    if (shown === 0 && !this.query.isEmpty()) this.list.addView(this.emptyNote("No one matches “" + this.query + "”."));
  }

  row(e) {
    const P = PhoneDirectoryActivity;
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 7), 0, Ui.dp(this, 7));
    const av = Ui.tv(this, P.initials(e.name), 14, Color.WHITE, true);
    av.setGravity(Gravity.CENTER);
    av.setBackground(Ui.round(this, P.colorOf(e.group), 19));
    row.addView(av, new LinearLayout.LayoutParams(Ui.dp(this, 38), Ui.dp(this, 38)));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 6), 0);
    t.addView(Ui.tv(this, e.name, 15, Ui.TEXT, true));
    if (!e.post.isEmpty()) t.addView(Ui.muted(this, e.post));
    const ph = Ui.tv(this, e.phone.isEmpty() ? "No number yet" : e.phone, 14, e.phone.isEmpty() ? 0xFF94A3B8 : P.COLOR, !e.phone.isEmpty());
    t.addView(ph);
    row.addView(t, Ui.weight(1));
    if (!e.phone.isEmpty()) {
      const call = Ui.softPill(this, "Call", Ui.GREEN);
      call.setOnClickListener({
        onClick: (v) => {
          try { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + P.dialable(e.phone)))); } catch (ignored) {}
        }
      });
      row.addView(call);
      const wa = Ui.softPill(this, "WhatsApp", 0xFF16A34A);
      wa.setOnClickListener({
        onClick: (v) => {
          try { this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse("https://wa.me/" + P.whatsapp(e.phone)))); } catch (ignored) {}
        }
      });
      row.addView(wa);
      Ui.margins(wa, 6, 0, 0, 0);
    }
    Ui.ripple(row, Ui.alpha(P.colorOf(e.group), 0x1A));
    row.setOnClickListener({
      onClick: (v) => { this.detail(e); }
    });
    return row;
  }

  static initials(name) {
    const sb = new StringBuilder();
    for (const p of Ui.nz(name).replaceAllRx("(?i)\\b(prof|dr|mr|mrs|ms|thiru|tmt)\\.?\\s*", " ").trim().jsplit("[\\s.]+"))
      if (!p.isEmpty() && Character.isLetter(p.charAt(0)) && sb.length() < 2) sb.append(Character.toUpperCase(p.charAt(0)));
    return sb.length() === 0 ? "?" : sb.toString();
  }

  detail(e) {
    const v = Ui.v(this);
    v.setPadding(Ui.dp(this, 20), Ui.dp(this, 8), Ui.dp(this, 20), 0);
    v.addView(Ui.kv(this, "Post", e.post.isEmpty() ? e.group : e.post));
    v.addView(Ui.kv(this, "Phone", e.phone));
    if ("contact" === e.src) {
      const r = this.db.row("SELECT notes FROM contacts WHERE id=?", e.id);
      if (r != null && !r.get("notes").isEmpty()) v.addView(Ui.kv(this, "Notes", r.get("notes")));
    }
    const b = new AlertDialog.Builder(this).setTitle(e.name).setView(v);
    if (!e.phone.isEmpty()) b.setNeutralButton("Share", {
      onClick: (d, w) => {
        const i = new Intent(Intent.ACTION_SEND);
        i.setType("text/plain");
        i.putExtra(Intent.EXTRA_TEXT, e.name + (e.post.isEmpty() ? "" : ", " + e.post) + "\n" + e.phone);
        this.startActivity(Intent.createChooser(i, "Share number"));
      }
    });
    if (PhoneDirectoryActivity.canEdit(this)) b.setPositiveButton("Edit", {
      onClick: (d, w) => { this.edit(e); }
    });
    b.setNegativeButton("Close", null).show();
  }

  edit(e) {
    if ("contact" === e.src) {
      this.contactDialog(this.db.row("SELECT * FROM contacts WHERE id=?", e.id));
      return;
    }
    const f = new Form(this);
    f.text("phone", "Mobile number", e.phone, Form.PHONE);
    Ui.formDialog(this, e.name, f, "Save", {
      run: () => {
        const p = f.get("phone").trim();
        if ("hod" === e.src) this.db.setSetting("hod_phone", p);
        else {
          const cv = new ContentValues();
          cv.put("phone", p);
          this.db.update("staff", cv, Long.parseLong(e.id));
        }
        this.fillList();
        return true;
      }
    });
  }

  contactDialog(r) {
    const P = PhoneDirectoryActivity;
    const f = new Form(this);
    f.choice("category", "Group", P.CAT_LABELS, P.CATS, r == null ? "WORKER" : r.get("category"), null);
    f.text("name", "Name *", r == null ? "" : r.get("name"), Form.PLAIN);
    f.suggest("designation", "Designation (e.g. Staff nurse, Office superintendent)", r == null ? "" : r.get("designation"), P.WORKER_ROLES);
    f.text("place", "Ward / unit / place", r == null ? "" : r.get("place"), Form.PLAIN);
    f.text("phone", "Mobile number *", r == null ? "" : r.get("phone"), Form.PHONE);
    f.text("phone2", "Second number", r == null ? "" : r.get("phone2"), Form.PHONE);
    f.text("notes", "Notes", r == null ? "" : r.get("notes"), Form.PLAIN);
    if (r != null) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete number?", r.get("name"), "Delete", {
            run: () => { this.db.delete("contacts", Long.parseLong(r.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "Add a number" : "Edit number", f, "Save", {
      run: () => {
        if (!f.require("name", "Enter the name")) return false;
        if (P.dialable(f.get("phone")).split("+").join("").length < 6) {
          Ui.toast(this, "Enter the mobile number");
          return false;
        }
        const cv = new ContentValues();
        for (const k of ["category", "name", "designation", "place", "phone", "phone2", "notes"]) cv.put(k, f.get(k).trim());
        if (r == null) {
          cv.put("added_by", Reminders.myName(this, this.db));
          cv.put("added_on", Alerts.now());
          this.db.insert("contacts", cv);
        } else this.db.update("contacts", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }
}

/** One person in the directory. */
PhoneDirectoryActivity.Entry = class {
  constructor() { this.name = null; this.post = ""; this.phone = ""; this.group = null; this.src = ""; this.id = ""; }
};
;
