/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The host's screen for a live quiz, for the projector or a big TV: the game PIN while students join, each question
 * with its countdown and answer tiles, how many chose each answer, the leaderboard, and the podium at the end.
 * The server keeps the game; this screen asks it for the latest every second.
 */
class QuizHostActivity extends Base {
  constructor() {
    super();
    this.setId = -1;
    this.game = -1;
    this.setTitleText = "";   // Java field "setTitle" (a method of the same name exists)
    this.view = null;
    this.error = null;
    this.busy = false;
    /** The question already moved to the answers, so the reveal is asked for only once. */
    this.revealed = -1;
    this.pending = null;
    this.body = null;
    this.h = new Handler(Looper.getMainLooper());
    this.poll = {
      run: () => {
        this.step(null);
        this.h.postDelayed(this.poll, 1000);
      }
    };
  }

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.setId = Long.parseLong(s);
    if (b != null) this.game = b.getLong("game", -1);
    const r = this.db.row("SELECT * FROM quiz_sets WHERE id=?", String(this.setId));
    if (r != null) this.setTitleText = Ui.nz(r.get("title"));
    this.setTitle(this.setTitleText.isEmpty() ? "Live quiz" : this.setTitleText);
    this.subtitle = "Host · show this screen on the projector";
    this.headerColors = Quiz.GRADIENT;
    this.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
    this.headerAction("End", { onClick: (v) => { this.confirmEnd(); } });
  }

  onSaveInstanceState(b) {
    super.onSaveInstanceState(b);
    b.putLong("game", this.game);
  }

  liveRefresh() {
    return false;
  }

  onResume() {
    super.onResume();
    this.h.removeCallbacks(this.poll);
    this.h.post(this.poll);
  }

  onPause() {
    super.onPause();
    this.h.removeCallbacks(this.poll);
  }

  onBackPressed() {
    if (this.view != null && !"ended".equals(this.view.optString("state"))) this.confirmEnd();
    else super.onBackPressed();
  }

  confirmEnd() {
    if (this.view == null || "ended".equals(this.view.optString("state"))) {
      this.finish();
      return;
    }
    Ui.confirm(this, "End the quiz?", "Students see the final results.", "End quiz", { run: () => { this.step("end"); } });
  }

  render() {
    if (this.body == null) {
      this.body = Ui.v(this);
      this.setPage(this.body);
    }
    this.draw();
  }

  /** Asks the server for the latest (or moves the quiz on with an action), off the main thread. */
  step(action) {
    if (action != null) this.pending = action;
    if (this.busy) return;
    this.busy = true;
    const act = this.pending;
    this.pending = null;
    new Thread({
      run: () => {
        let v = null;
        let err = null;
        try {
          if (this.game < 0) {
            const r = this.db.row("SELECT * FROM quiz_sets WHERE id=?", String(this.setId));
            if (r == null) throw new Error("Quiz not found");
            const g = Quiz.rpc(this, "quiz_create",
                new JSONObject().put("p_title", this.setTitleText).put("p_questions", Quiz.questions(r)));
            this.game = g.getLong("id");
          }
          const args = new JSONObject().put("p_game", this.game);
          v = act == null ? Quiz.rpc(this, "quiz_host_view", args)
              : Quiz.rpc(this, "quiz_control", args.put("p_action", act));
        } catch (e) {
          err = e.getMessage();
        } finally {
          const fv = v;
          const fe = err;
          this.runOnUiThread({
            run: () => {
              this.busy = false;
              if (this.isFinishing()) return;
              if (fv != null) {
                this.view = fv;
                this.error = null;
              } else if (fe != null) this.error = fe;
              this.autoReveal();
              this.draw();
            }
          });
        }
      }
    }).start();
  }

  /** Shows the answers when time is up or everyone has answered. */
  autoReveal() {
    const view = this.view;
    if (view == null || !"question".equals(view.optString("state"))) return;
    const q = view.optInt("q_index");
    const players = view.optInt("players"), answered = view.optInt("answered");
    if (this.revealed !== q && (view.optDouble("left", 1) <= 0 || (players > 0 && answered >= players))) {
      this.revealed = q;
      this.step("reveal");
    }
  }

  draw() {
    const body = this.body;
    if (body == null) return;
    body.removeAllViews();
    body.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 28));
    if (this.view == null) {
      body.addView(this.emptyNote(this.error != null ? "Could not start the quiz: " + this.error + "\nCheck the internet; it tries again every second." : "Starting the quiz…"));
      return;
    }
    if (this.error != null) {
      const e = Ui.tv(this, "⚠ " + this.error, 12, Ui.RED, false);
      body.addView(e);
    }
    const st = this.view.optString("state");
    if (st.equals("lobby")) this.lobby();
    else if (st.equals("question")) this.question(false);
    else if (st.equals("reveal")) this.question(true);
    else if (st.equals("board")) this.board();
    else this.podium();
  }

  big(s, sp, color) {
    const t = Ui.tv(this, s, sp, color, true);
    t.setGravity(Gravity.CENTER);
    return t;
  }

  lobby() {
    const view = this.view, body = this.body;
    const card = Ui.card(this);
    card.setBackground(Glass.hero(this, Quiz.GRADIENT, 20));
    card.setGravity(Gravity.CENTER_HORIZONTAL);
    const link = Quiz.joinLink(this.db);
    card.addView(this.big("Join at " + (link.isEmpty() ? "the TVMCHMED app › Live quiz" : link + "  or the TVMCHMED app"), 15, 0xE6FFFFFF));
    card.addView(this.big("Game PIN", 14, 0xCCFFFFFF));
    const pin = this.big(view.optString("pin").replaceAllRx("(\\d{3})(\\d{3})", "$1 $2"), 56, Color.WHITE);
    pin.setLetterSpacing(0.08);
    card.addView(pin);
    body.addView(card);
    const n = view.optInt("players");
    body.addView(this.big("👥  " + n + (n === 1 ? " player" : " players"), 20, Quiz.PURPLE));
    const names = view.optJSONArray("names");
    const sb = new StringBuilder();
    for (let i = 0; names != null && i < names.length(); i++) sb.append(i === 0 ? "" : "   ·   ").append(names.optString(i));
    if (!sb.isEmpty()) {
      const t = this.big(sb.toString(), 15, Ui.TEXT);
      t.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 12));
      body.addView(t);
    } else body.addView(this.emptyNote("Waiting for students to join…"));
    const total = view.optInt("total");
    body.addView(Ui.button(this, "Start  ▶   (" + total + (total === 1 ? " question)" : " questions)"), Quiz.COLORS[3], { onClick: (v) => { this.step("next"); } }));
  }

  question(reveal) {
    const view = this.view, body = this.body;
    const q = view.optJSONObject("question");
    if (q == null) return;
    const qi = view.optInt("q_index"), total = view.optInt("total");
    const players = view.optInt("players"), answered = view.optInt("answered");
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.softPill(this, "Question " + (qi + 1) + " of " + total, Quiz.PURPLE));
    top.addView(new View(this), Ui.weight(1));
    top.addView(Ui.tv(this, answered + " / " + players + " answered  ", 14, Ui.TEXT, true));
    if (!reveal) top.addView(Quiz.timer(this, view.optDouble("left")), Ui.lp(Ui.dp(this, 56), Ui.dp(this, 56)));
    body.addView(top);
    const qt = Quiz.questionCard(this, q.optString("q"), 22);
    body.addView(qt);
    Ui.margins(qt, 0, 10, 0, 10);
    const o = q.optJSONArray("options");
    const counts = view.optJSONArray("counts");
    const right = q.optInt("answer");
    const tiles = new Array(o == null ? 0 : o.length()).fill(null);
    for (let k = 0; k < tiles.length; k++) {
      const cnt = counts == null ? 0 : counts.optInt(k);
      const text = o.optString(k) + (reveal ? (k === right ? "   ✓" : "") + "\n" + cnt + (cnt === 1 ? " answer" : " answers") : "");
      tiles[k] = Quiz.tile(this, k, text, 18, reveal && k !== right);
    }
    body.addView(Quiz.grid(this, tiles));
    if (reveal) {
      const ok = view.optInt("correct_count");
      body.addView(this.big(ok + " of " + players + " got it right", 18, Quiz.COLORS[3]));
      body.addView(Ui.button(this, "Leaderboard  ▸", Quiz.PURPLE, { onClick: (v) => { this.step("board"); } }));
    } else {
      const skip = Ui.outlineButton(this, "Show answers now  ▸", Quiz.PURPLE, {
        onClick: (v) => {
          this.revealed = this.view.optInt("q_index");
          this.step("reveal");
        }
      });
      body.addView(skip);
      Ui.margins(skip, 0, 12, 0, 0);
    }
  }

  board() {
    const view = this.view, body = this.body;
    const qi = view.optInt("q_index"), total = view.optInt("total");
    body.addView(this.big("🏆  Leaderboard", 26, Quiz.PURPLE));
    body.addView(this.big("after question " + (qi + 1) + " of " + total, 13, Ui.MUTED));
    const b = view.optJSONArray("board");
    for (let i = 0; b != null && i < Math.min(5, b.length()); i++) body.addView(this.rankRow(i, b.optJSONObject(i)));
    const last = qi + 1 >= total;
    const next = Ui.button(this, last ? "Final results  🏁" : "Next question  ▶", last ? Quiz.COLORS[0] : Quiz.COLORS[3], { onClick: (v) => { this.step("next"); } });
    body.addView(next);
    Ui.margins(next, 0, 14, 0, 0);
  }

  rankRow(i, p) {
    const r = Ui.h(this);
    r.setGravity(Gravity.CENTER_VERTICAL);
    r.setBackground(Ui.round(this, i === 0 ? 0xFFFFF4D6 : Color.WHITE, 12));
    r.setPadding(Ui.dp(this, 14), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
    r.addView(Ui.tv(this, (i + 1) + "", 20, Quiz.PURPLE, true), Ui.lp(Ui.dp(this, 36), LinearLayout.LayoutParams.WRAP_CONTENT));
    r.addView(Ui.tv(this, p.optString("name"), 18, Ui.TEXT, true), Ui.weight(1));
    r.addView(Ui.tv(this, String(p.optInt("score")), 18, Ui.TEXT, true));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(0, Ui.dp(this, 6), 0, 0);
    r.setLayoutParams(lp);
    return r;
  }

  podium() {
    const view = this.view, body = this.body;
    this.h.removeCallbacks(this.poll);
    body.addView(this.big("🏁  Final results", 26, Quiz.PURPLE));
    body.addView(this.big(view.optString("title"), 14, Ui.MUTED));
    const b = view.optJSONArray("board");
    const medal = ["🥇", "🥈", "🥉"];
    const pod = Ui.h(this);
    pod.setGravity(Gravity.BOTTOM);
    const order = [1, 0, 2];
    const height = [120, 160, 96];
    for (let k = 0; k < 3; k++) {
      const i = order[k];
      const col = Ui.v(this);
      col.setGravity(Gravity.CENTER_HORIZONTAL | Gravity.BOTTOM);
      const p = b != null && i < b.length() ? b.optJSONObject(i) : null;
      col.addView(this.big(p == null ? "" : p.optString("name"), 15, Ui.TEXT));
      col.addView(this.big(p == null ? "" : p.optInt("score") + " pts", 12, Ui.MUTED));
      const block = this.big(medal[i], 34, Color.WHITE);
      block.setBackground(Ui.round(this, i === 0 ? Quiz.PURPLE : Ui.mix(Quiz.PURPLE, Color.WHITE, 0.3), 10));
      col.addView(block, Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, height[i])));
      const lp = Ui.weight(1);
      lp.setMargins(Ui.dp(this, 4), Ui.dp(this, 16), Ui.dp(this, 4), Ui.dp(this, 8));
      pod.addView(col, lp);
    }
    body.addView(pod);
    for (let i = 3; b != null && i < Math.min(10, b.length()); i++) body.addView(this.rankRow(i, b.optJSONObject(i)));
    const share = Ui.button(this, "Share results", Quiz.PURPLE, { onClick: (v) => { this.share(b); } });
    body.addView(share);
    Ui.margins(share, 0, 14, 0, 0);
    const close = Ui.outlineButton(this, "Close", Quiz.PURPLE, { onClick: (v) => { this.finish(); } });
    body.addView(close);
    Ui.margins(close, 0, 8, 0, 0);
  }

  share(b) {
    const sb = new StringBuilder("🏁 " + this.view.optString("title") + " · live quiz results (" + Dates.nice(Dates.todayIso()) + ")\n");
    for (let i = 0; b != null && i < b.length(); i++) {
      const p = b.optJSONObject(i);
      sb.append(i + 1).append(". ").append(p.optString("name")).append(" · ").append(p.optInt("score")).append('\n');
    }
    const s = new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT, sb.toString());
    this.startActivity(Intent.createChooser(s, "Share results"));
  }
}
;
