/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Enter or edit the day's duty roster: unit faculty, DAP, OP, triage, IMCU, CCB and fever ward duties. */
class RosterFormActivity extends Base {
  constructor() { super(); this.r = null; this.form = null; this.built = false; }

  onCreate(b) {
    super.onCreate(b);
    let date = Ui.nz(this.getIntent().getStringExtra("date"));
    if (date.isEmpty()) date = Dates.todayIso();
    this.r = this.db.row("SELECT * FROM duty_roster WHERE date=? ORDER BY id DESC LIMIT 1", date);
    this.getIntent().putExtra("date", date);
    this.setTitle(this.r == null ? "Daily duty roster" : "Edit duty roster");
    this.subtitle = "Faculty, DAP, PGs and CRRIs on duty";
    this.headerAction("Save", {
      onClick: (v) => { this.save(); }
    });
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.built) return;
    this.built = true;
    const date = this.getIntent().getStringExtra("date");
    const page = Ui.v(this);

    const tools = Ui.card(this);
    tools.addView(Ui.muted(this, "Fill it in below, or paste the morning roster message from WhatsApp and the app will sort the names into place."));
    const row = Ui.buttonRow(this,
      Ui.outlineButton(this, "Paste WhatsApp message", Ui.TEAL, {
        onClick: (v) => { this.pasteDialog(); }
      }),
      Ui.outlineButton(this, "Copy last week's", Ui.PRIMARY, {
        onClick: (v) => { this.copyLastWeek(); }
      }));
    tools.addView(row);
    Ui.margins(row, 0, 10, 0, 0);
    page.addView(tools);

    const card = Ui.card(this);
    this.form = new Form(this);
    this.form.date("date", "Date", this.r == null ? date : this.r.get("date"));
    const unit = this.r == null ? this.firstAdmitting(date) : this.r.get("unit");
    this.form.choice("unit", "Admitting unit", Db.shortNames(Db.WARD_UNITS), Db.WARD_UNITS, unit, null);
    for (let g = 0; g < Roster.FIELDS.length; g++) {
      this.form.heading(Roster.GROUPS[g]);
      for (const f of Roster.FIELDS[g]) {
        let v = this.r == null ? "" : this.r.get(f[0]);
        if (this.r == null && f[0].equals("chief")) v = this.staffLines(unit, "('Professor')");
        if (this.r == null && f[0].equals("aps")) v = this.staffLines(unit, "('Assistant Professor','Associate Professor')");
        const e = this.form.multi(f[0], f[1], v);
        e.setMinLines(1);
        e.setHint("Dr. Name  98765 43210 (one per line)");
        e.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE | InputType.TYPE_TEXT_FLAG_CAP_WORDS);
      }
    }
    this.form.heading("Other");
    this.form.multi("notes", "Notes", this.r == null ? "" : this.r.get("notes"));
    card.addView(this.form.view);
    page.addView(card);

    const save = Ui.button(this, "Save roster", Ui.PRIMARY, {
      onClick: (v) => { this.save(); }
    });
    page.addView(save);
    Ui.margins(save, 14, 14, 14, 0);
    if (this.r != null) {
      const del = Ui.outlineButton(this, "Delete this roster", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete roster?", "The duty roster for " + Dates.nice(this.r.get("date")) + " will be removed.", "Delete", {
            run: () => {
              this.db.delete("duty_roster", Long.parseLong(this.r.get("id")));
              this.finish();
            }
          });
        }
      });
      page.addView(del);
      Ui.margins(del, 14, 10, 14, 0);
    }
    this.setPage(page);
  }

  firstAdmitting(iso) {
    const d = Dates.parse(iso);
    const au = this.db.admittingUnits(Dates.dow(d == null ? Dates.today() : d));
    return au.isEmpty() ? "M1" : au.get(0);
  }

  /** The unit's faculty from the staff list, one "name phone" per line. */
  staffLines(unit, roles) {
    const s = new StringBuilder();
    for (const m of this.db.rows("SELECT name, phone FROM staff WHERE unit=? AND role IN " + roles + " AND " + Approvals.APPROVED_SQL + " ORDER BY name", unit)) {
      if (s.length() > 0) s.append('\n');
      s.append(m.get("name")).append(Ui.nz(m.get("phone")).isEmpty() ? "" : " " + m.get("phone"));
    }
    return s.toString();
  }

  pasteDialog() {
    const f = new Form(this);
    let clip = "";
    try {
      const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
      const cd = cm == null ? null : cm.getPrimaryClip();
      if (cd != null && cd.getItemCount() > 0 && cd.getItemAt(0).getText() != null) clip = cd.getItemAt(0).getText().toString();
    } catch (e) {}
    if (!clip.toLowerCase().contains("dap") && !clip.toLowerCase().contains("imcu")) clip = "";
    const e = f.multi("text", "Roster message", clip);
    e.setMinLines(6);
    e.setHint("Copy the morning roster message in WhatsApp (long-press → Copy) and paste it here");
    Ui.formDialog(this, "Paste WhatsApp roster", f, "Fill in", {
      run: () => {
        const p = Roster.parse(f.get("text"));
        if (p.count === 0) {
          Ui.toast(this, "No duty names found in that message");
          return false;
        }
        if (p.date != null) this.form.set("date", p.date);
        if (p.unit != null) this.form.set("unit", p.unit);
        for (const k of Roster.keys()) this.form.set(k, p.fields.containsKey(k) ? p.fields.get(k) : "");
        Ui.toast(this, p.count + " duty entries filled in. Check them, then Save.");
        return true;
      }
    });
  }

  copyLastWeek() {
    const last = this.db.row("SELECT * FROM duty_roster WHERE unit=? AND date<? ORDER BY date DESC LIMIT 1", this.form.get("unit"), this.form.get("date"));
    if (last == null) {
      Ui.toast(this, "No earlier roster for " + Db.shortName(this.form.get("unit")));
      return;
    }
    for (const k of Roster.keys()) this.form.set(k, last.get(k));
    Ui.toast(this, "Copied from " + Dates.nice(last.get("date")) + ". Change what's different today.");
  }

  save() {
    if (this.form == null) return;
    const date = this.form.get("date");
    const cv = new ContentValues();
    cv.put("date", date);
    cv.put("unit", this.form.get("unit"));
    for (const k of Roster.keys()) cv.put(k, this.form.get(k));
    cv.put("notes", this.form.get("notes"));
    const same = this.db.row("SELECT id FROM duty_roster WHERE date=? ORDER BY id DESC LIMIT 1", date);
    if (this.r != null) this.db.update("duty_roster", cv, Long.parseLong(this.r.get("id")));
    else if (same != null) this.db.update("duty_roster", cv, Long.parseLong(same.get("id")));
    else this.db.insert("duty_roster", cv);
    // the roster's DAP is also the day's DAP on the home page and in the DAP register
    const dap = this.form.get("dap").jsplit("\n")[0];
    if (!dap.trim().isEmpty()) {
      const name = Roster.name(dap);
      const d = this.db.row("SELECT id, dap_name FROM dap WHERE date=? ORDER BY id DESC LIMIT 1", date);
      const dv = new ContentValues();
      dv.put("dap_name", name);
      if (d == null) {
        dv.put("date", date);
        dv.put("unit", this.form.get("unit"));
        this.db.insert("dap", dv);
      } else if (!name.equals(d.get("dap_name"))) this.db.update("dap", dv, Long.parseLong(d.get("id")));
    }
    Ui.toast(this, "Roster saved");
    this.finish();
  }
}
;
