/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Post a Daily ECG or Daily Image (camera or gallery), with history, question and the poster's interpretation; or edit one. */
class SpotEditActivity extends Base {
  constructor() {
    super();
    this.form = null;
    this.id = -1;
    this.kind = Spots.ECG;
    this.image = "";
    this.pendingCamera = null;
    this.preview = null;
  }
  static REQ_CAMERA = 61;
  static REQ_PICK = 62;

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    const r = this.id >= 0 ? this.db.row("SELECT * FROM spots WHERE id=?", String(this.id)) : null;
    if (r != null) {
      this.kind = r.get("kind");
      this.image = Ui.nz(r.get("image"));
    } else if (this.getIntent().getStringExtra("kind") != null) this.kind = this.getIntent().getStringExtra("kind");
    if (b != null) {
      this.image = b.getString("image", this.image);
      this.pendingCamera = b.getString("camera");
    }
    this.setTitle(this.id >= 0 ? "Edit post" : Spots.ECG === this.kind ? "Post an ECG" : "Post an image");
    this.subtitle = "Everyone in the department can discuss it";
    this.headerColors = Spots.gradient(this.kind);
    this.headerAction("Save", { onClick: (v) => { this.save(); } });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putString("image", this.image);
    if (this.pendingCamera != null) out.putString("camera", this.pendingCamera);
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.form != null) {
      this.showPreview();
      return;
    }
    const r = this.id >= 0 ? this.db.row("SELECT * FROM spots WHERE id=?", String(this.id)) : null;
    const col = Spots.color(this.kind);
    const page = Ui.v(this);

    const pic = Ui.card(this);
    pic.addView(Ui.title(this, Spots.ECG === this.kind ? "The ECG" : "The image"));
    pic.addView(Ui.muted(this, Spots.ECG === this.kind
      ? "Photograph the ECG flat, in good light, with all 12 leads in the frame. Cover the patient's name and IP number."
      : "Take a clear photo of the film or screen, or pick a saved image. Cover the patient's name and IP number."));
    this.preview = Ui.v(this);
    pic.addView(this.preview);
    pic.addView(Ui.buttonRow(this,
      Ui.button(this, "Camera", col, {
        onClick: (v) => {
          this.pendingCamera = "spots/" + this.kind.toLowerCase() + "_" + System.currentTimeMillis() + ".jpg";
          if (!Store.capture(this, this.pendingCamera, SpotEditActivity.REQ_CAMERA)) this.pendingCamera = null;
        }
      }),
      Ui.outlineButton(this, "Gallery / file", col, {
        onClick: (v) => { Store.pick(this, ["image/*"], SpotEditActivity.REQ_PICK); }
      })));
    page.addView(pic);

    this.form = new Form(this);
    this.form.date("date", "Show on (date)", SpotEditActivity.v(r, "date", Dates.todayIso()));
    const types = Spots.types(this.kind);
    this.form.choice("type", Spots.ECG === this.kind ? "Type" : "Imaging", types, types, SpotEditActivity.v(r, "type", types[0]), null);
    this.form.text("title", "Title (optional, e.g. Broad complex tachycardia)", SpotEditActivity.v(r, "title", ""), Form.PLAIN);
    this.form.multi("history", "Clinical history (age, sex, complaints, vitals)", SpotEditActivity.v(r, "history", ""));
    this.form.multi("question", "Question for everyone", SpotEditActivity.v(r, "question", Spots.ECG === this.kind ? "What is your interpretation of this ECG?" : "Describe the findings. What is your diagnosis?"));
    this.form.heading("Your interpretation (hidden until someone taps Show)");
    this.form.multi("answer", "Interpretation / answer and teaching points (can be added later)", SpotEditActivity.v(r, "answer", ""));
    const c = Ui.card(this);
    c.addView(this.form.view);
    page.addView(c);

    const btns = Ui.v(this);
    btns.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    btns.addView(Ui.button(this, this.id >= 0 ? "Save changes" : "Post for discussion", col, { onClick: (v) => { this.save(); } }));
    if (this.id >= 0) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete this post?", "The picture and the whole discussion will be removed for everyone.", "Delete", {
            run: () => {
              Spots.delete(this.db, this.id);
              this.setResult(1 /* RESULT_FIRST_USER */);
              this.finish();
            }
          });
        }
      });
      btns.addView(del);
      Ui.margins(del, 0, 10, 0, 0);
    }
    page.addView(btns);
    this.setPage(page);
    this.showPreview();
  }

  showPreview() {
    if (this.preview == null) return;
    this.preview.removeAllViews();
    const f = this.image.isEmpty() ? null : this.db.file(this.image);
    if (f == null || !f.exists()) {
      const none = Ui.tv(this, Spots.ECG === this.kind ? "No ECG added yet" : "No image added yet", 14, Ui.MUTED, true);
      none.setGravity(Gravity.CENTER);
      none.setBackground(Ui.round(this, Ui.alpha(Spots.color(this.kind), 0x14), 16));
      none.setPadding(0, Ui.dp(this, 36), 0, Ui.dp(this, 36));
      this.preview.addView(none);
      Ui.margins(none, 0, 10, 0, 10);
      return;
    }
    const iv = new ImageView(this);
    iv.setImageBitmap(Ui.loadScaled(f, 1200));
    iv.setAdjustViewBounds(true);
    iv.setMaxHeight(Ui.dp(this, 320));
    this.preview.addView(iv);
    Ui.margins(iv, 0, 10, 0, 10);
  }

  static v(r, k, def) {
    return r == null || Ui.nz(r.get(k)).isEmpty() ? def : r.get(k);
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (res !== RESULT_OK) return;
    try {
      if (req === SpotEditActivity.REQ_CAMERA && this.pendingCamera != null) {
        const f = this.db.file(this.pendingCamera);
        if (!f.exists() || f.length() === 0) return;
        Store.shrink(f, 2400);
        this.image = this.pendingCamera;
        this.pendingCamera = null;
      } else if (req === SpotEditActivity.REQ_PICK && data != null && data.getData() != null) {
        const uri = data.getData();
        const rel = Store.importUri(this, uri, "spots", this.kind.toLowerCase());
        if (!Store.isImage(rel)) {
          this.db.file(rel).delete();
          Ui.toast(this, "Pick a photo or image (JPG or PNG)");
          return;
        }
        this.image = rel;
      }
      this.showPreview();
    } catch (e) {
      Ui.toast(this, "Could not add the picture: " + e.getMessage());
    }
  }

  /** For tests: use a file already in filesDir. */
  setImage(rel) {
    this.image = rel;
    this.showPreview();
  }

  save() {
    if (this.form == null) return;
    if (this.image.isEmpty() || !this.db.file(this.image).exists()) {
      Ui.toast(this, Spots.ECG === this.kind ? "Add the ECG photo first" : "Add the image first");
      return;
    }
    const cv = new ContentValues();
    for (const k of ["date", "type", "title", "history", "question", "answer"]) cv.put(k, this.form.get(k));
    cv.put("image", this.image);
    if (this.id < 0) {
      cv.put("kind", this.kind);
      cv.put("staff_id", Spots.myId(this));
      cv.put("name", Spots.myName(this));
      cv.put("role", Spots.myRole(this));
      cv.put("time", Dates.todayIso() + " " + Dates.now());
      this.id = this.db.insert("spots", cv);
      Ui.toast(this, "Posted for discussion");
      this.finish();
      this.open(SpotActivity, "id", String(this.id));
      return;
    }
    this.db.update("spots", cv, this.id);
    Ui.toast(this, "Saved");
    this.finish();
  }
}
;
