/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Daily ECG and Daily Image, beside the Daily MCQ: anyone (faculty or student) uploads an ECG or an image
 * (X-ray, CT, MRI, USG, fundus, clinical photo, smear) with a short history and question, and everyone discusses it.
 * The poster's interpretation stays hidden until a person taps Show.
 */
class Spots {
  constructor() {}

  static ECG = "ECG";
  static IMAGE = "IMAGE";
  static KINDS = ["ECG", "IMAGE"];
  static IMAGE_TYPES = ["Chest X-ray", "X-ray (other)", "CT", "MRI", "Ultrasound", "Echo", "Fundus", "Clinical photo", "Peripheral smear", "Other"];
  static ECG_TYPES = ["12-lead ECG", "Rhythm strip", "Monitor tracing"];
  static ECG_COLOR = 0xFFE11D48;
  static IMAGE_COLOR = 0xFF0891B2;
  static ECG_GRADIENT = [0xFF881337, 0xFFE11D48, 0xFFFB7185];
  static IMAGE_GRADIENT = [0xFF164E63, 0xFF0891B2, 0xFF22D3EE];

  static name(kind) {
    return Spots.ECG === kind ? "Daily ECG" : "Daily Image";
  }

  static color(kind) {
    return Spots.ECG === kind ? Spots.ECG_COLOR : Spots.IMAGE_COLOR;
  }

  static gradient(kind) {
    return Spots.ECG === kind ? Spots.ECG_GRADIENT : Spots.IMAGE_GRADIENT;
  }

  static types(kind) {
    return Spots.ECG === kind ? Spots.ECG_TYPES : Spots.IMAGE_TYPES;
  }

  /** Every member posts and discusses; a phone without shared login belongs to its user. */
  static canEdit(c, s) {
    return SessionAttendance.canRun(c) || Spots.mine(c, s.get("name"));
  }

  static mine(c, name) {
    return !Ui.nz(name).isEmpty() && Ui.nz(name) === Spots.myName(c);
  }

  static myName(c) {
    const me = SessionAttendance.me(c, Db.get(c));
    if (me != null) return me.get("name");
    const n = Approvals.me(c);
    return n.isEmpty() ? Reminders.myName(c, Db.get(c)) : n;
  }

  /** The person's role in words: their staff role, else their sign-in role. */
  static myRole(c) {
    const me = SessionAttendance.me(c, Db.get(c));
    if (me != null && !Ui.nz(me.get("role")).isEmpty()) return me.get("role");
    return Cloud.active(c) ? Cloud.roleLabel(Cloud.role(c)) : "";
  }

  static myId(c) {
    const me = SessionAttendance.me(c, Db.get(c));
    return me == null ? "" : me.get("id");
  }

  static isFaculty(role) {
    const r = Ui.nz(role);
    return Db.isFaculty(r) || r.startsWith("Admin") || r.startsWith("Professor") || r === "Assistant Professor";
  }

  static today(db, kind) {
    return db.rows("SELECT * FROM spots WHERE kind=? AND date=? ORDER BY id DESC", kind, Dates.todayIso());
  }

  static all(db, kind) {
    return db.rows("SELECT * FROM spots WHERE kind=? AND date<=? ORDER BY date DESC, id DESC LIMIT 200", kind, Dates.todayIso());
  }

  static comments(db, spotId) {
    return db.rows("SELECT * FROM spot_comments WHERE spot_id=? ORDER BY time, id", spotId);
  }

  static count(db, spotId) {
    return db.num("SELECT COUNT(*) FROM spot_comments WHERE spot_id=?", spotId);
  }

  static comment(c, db, spotId, text) {
    const cv = new ContentValues();
    cv.put("spot_id", spotId);
    cv.put("staff_id", Spots.myId(c));
    cv.put("name", Spots.myName(c));
    cv.put("role", Spots.myRole(c));
    cv.put("text", text.trim());
    cv.put("time", Dates.todayIso() + " " + Dates.now());
    return db.insert("spot_comments", cv);
  }

  static delete(db, id) {
    for (const r of db.rows("SELECT id FROM spot_comments WHERE spot_id=?", String(id)))
      db.delete("spot_comments", Long.parseLong(r.get("id")));
    db.delete("spots", id);
  }

  static label(s) {
    const t = Ui.nz(s.get("title"));
    return t.isEmpty() ? Ui.nz(s.get("type")) : t;
  }

  // ---------- the two home cards under the Daily MCQ ----------

  /** Daily ECG and Daily Image side by side: today's post (or a prompt to post one) and how many have discussed it. */
  static homeRow(a, db) {
    const row = Ui.h(a);
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(a, 12), Ui.dp(a, 6), Ui.dp(a, 12), Ui.dp(a, 4));
    row.setLayoutParams(lp);
    for (let i = 0; i < Spots.KINDS.length; i++) {
      const card = Spots.homeCard(a, db, Spots.KINDS[i]);
      const w = Ui.weight(1);
      w.setMargins(i === 0 ? 0 : Ui.dp(a, 5), 0, i === 0 ? Ui.dp(a, 5) : 0, 0);
      row.addView(card, w);
    }
    return row;
  }

  static homeCard(a, db, kind) {
    const t = Spots.today(db, kind);
    const s = t.isEmpty() ? null : t.get(0);
    const card = Ui.v(a);
    card.setBackground(Glass.hero(a, Spots.gradient(kind), 20));
    card.setPadding(Ui.dp(a, 14), Ui.dp(a, 12), Ui.dp(a, 14), Ui.dp(a, 12));
    card.setElevation(Ui.dp(a, 4));
    Glass.softShadow(card, Spots.color(kind));
    const tag = Ui.tv(a, Spots.ECG === kind ? "♥  DAILY ECG" : "◉  DAILY IMAGE", 10, Color.WHITE, true);
    tag.setLetterSpacing(0.1);
    card.addView(tag);
    const title = Ui.tv(a, s == null ? (Spots.ECG === kind ? "Post today's ECG" : "Post today's image") : Spots.label(s), 15, Color.WHITE, true);
    title.setMaxLines(2);
    title.setEllipsize(TextUtils.TruncateAt.END);
    card.addView(title);
    Ui.margins(title, 0, 6, 0, 0);
    const n = s == null ? 0 : Spots.count(db, s.get("id"));
    const sub = Ui.tv(a, s == null ? "Upload one for everyone to discuss" : n === 0 ? "Be the first to comment" : n + (n === 1 ? " comment" : " comments"),
      12, 0xD9FFFFFF, false);
    card.addView(sub);
    Ui.margins(sub, 0, 4, 0, 0);
    const open = s == null ? a.opener(SpotEditActivity, "kind", kind)
      : a.opener(SpotActivity, "id", s.get("id"));
    card.setOnClickListener(open);
    Ui.ripple(card, 0x33FFFFFF);
    card.setGravity(Gravity.TOP);
    return card;
  }
}
;
/* ---- app/StaffActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Students: postgraduates, CRMIs and MBBS students (2nd year, prefinal, final), grouped by unit or clinical posting. */
class StaffActivity extends Base {
  constructor() { super(); this.cat = 0; this.query = ""; this.list = null; }

  static UNIT_LABELS = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", "IMCU", "Fever ward", "Critical Care Block", "Geriatric ward", "Rheumatology ward", "Kandiyaperi", "Department"];

  /** The five subsections and the role each one is stored under. */
  static CATS = ["PG", "CRMI", "MBBS 2nd year", "Prefinal", "Final year"];
  static CAT_COLORS = [0xFF6366F1, 0xFF14B8A6, 0xFFF97316, 0xFFEC4899, 0xFF22C55E];
  static PG_YEAR_LABELS = ["1st year", "2nd year", "3rd year (final)"];
  static PG_YEAR_VALUES = ["1", "2", "3"];

  static $clinit() {
    StaffActivity.UNIT_VALUES = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.FEVER, Db.CCB, Db.GERI, Db.RHEUM, Db.KDP, Db.DEPT];
    StaffActivity.CAT_ROLES = ["Postgraduate", "CRMI", Db.MBBS_ROLES[0], Db.MBBS_ROLES[1], Db.MBBS_ROLES[2]];
  }

  onCreate(b) {
    super.onCreate(b);
    if (b != null) this.cat = b.getInt("cat", 0);
    else this.cat = Math.max(0, Math.min(StaffActivity.CATS.length - 1, this.getIntent().getIntExtra("cat", 0)));
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putInt("cat", this.cat);
  }

  render() {
    const S = StaffActivity;
    this.setTitle("Students");
    const total = this.db.num("SELECT COUNT(*) FROM staff WHERE (role IN ('Postgraduate','CRMI') OR role LIKE 'MBBS%') AND " + Approvals.APPROVED_SQL);
    const waiting = this.db.num("SELECT COUNT(*) FROM staff WHERE (role IN ('Postgraduate','CRMI') OR role LIKE 'MBBS%') AND approval=?", Approvals.PENDING);
    this.subtitle = total + " students · PG, CRMI and MBBS" + (waiting > 0 ? " · " + waiting + " awaiting approval" : "");
    this.headerColor(S.CAT_COLORS[this.cat]);
    const may = Approvals.mayChange(this, S.CAT_ROLES[this.cat]);
    if (may) this.headerAction("+ Add", {
      onClick: (v) => { S.studentDialog(this, null, S.CAT_ROLES[this.cat], "M1", this.refresh()); }
    });
    const page = Ui.v(this);

    // subsections
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
    for (let i = 0; i < S.CATS.length; i++) {
      const idx = i;
      const n = this.db.num("SELECT COUNT(*) FROM staff WHERE role=?", S.CAT_ROLES[i]);
      const c = Ui.chip(this, S.CATS[i] + "  " + n, i === this.cat, S.CAT_COLORS[i]);
      c.setOnClickListener({
        onClick: (v) => { this.cat = idx; this.query = ""; this.render(); }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    // summary + actions
    const mbbs = this.cat >= 2;
    const head = Ui.card(this);
    const hr = Ui.h(this);
    hr.setGravity(Gravity.CENTER_VERTICAL);
    hr.addView(Ui.iconBadge(this, mbbs ? R.drawable.ic_school : R.drawable.ic_group, S.CAT_COLORS[this.cat], 48));
    const ht = Ui.v(this);
    ht.setPadding(Ui.dp(this, 12), 0, 0, 0);
    ht.addView(Ui.tv(this, S.CAT_ROLES[this.cat].equals("Postgraduate") ? "Postgraduates (MD General Medicine)" : S.CAT_ROLES[this.cat].equals("CRMI") ? "CRMIs (interns)" : S.CAT_ROLES[this.cat], 16, Ui.TEXT, true));
    ht.addView(Ui.muted(this, mbbs ? "Grouped by clinical posting. Tap a name to edit." : "Grouped by unit. Tap a name to edit."));
    hr.addView(ht, Ui.weight(1));
    head.addView(hr);
    const btns = Ui.h(this);
    const add = Ui.button(this, "+ Add " + (mbbs ? "student" : S.CATS[this.cat]), S.CAT_COLORS[this.cat], {
      onClick: (v) => { S.studentDialog(this, null, S.CAT_ROLES[this.cat], "M1", this.refresh()); }
    });
    btns.addView(add, Ui.weight(1));
    const paste = Ui.outlineButton(this, "Paste a list", S.CAT_COLORS[this.cat], {
      onClick: (v) => { this.pasteDialog(); }
    });
    btns.addView(paste, Ui.weight(1));
    Ui.margins(paste, 8, 0, 0, 0);
    if (may) {
      head.addView(btns);
      Ui.margins(btns, 0, 12, 0, 0);
    } else {
      const note = Ui.muted(this, Approvals.FACULTY_ONLY_NOTE);
      head.addView(note);
      Ui.margins(note, 0, 10, 0, 0);
    }
    page.addView(head);
    const mine = Approvals.waitingForMe(this, this.db);
    if (mine > 0) {
      const go = Ui.button(this, mine + " new " + (mine === 1 ? "entry" : "entries") + " awaiting your approval", Ui.AMBER, this.opener(ApprovalActivity));
      page.addView(go);
      Ui.margins(go, 12, 4, 12, 4);
    }

    const search = new EditText(this);
    search.setHint("Search name, roll / reg no or phone");
    search.setSingleLine(true);
    search.setText(this.query);
    search.setBackground(Glass.panel(this, 14));
    search.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
    search.addTextChangedListener({
      beforeTextChanged: (s, a, b, c) => {},
      onTextChanged: (s, a, b, c) => {},
      afterTextChanged: (e) => { this.query = e.toString().trim(); this.fillList(); }
    });
    page.addView(search);
    Ui.margins(search, 12, 6, 12, 2);

    this.list = Ui.v(this);
    page.addView(this.list);
    this.fillList();
    this.setPage(page);
  }

  fillList() {
    const S = StaffActivity;
    this.list.removeAllViews();
    const q = "%" + this.query + "%";
    let shown = 0;
    for (const code of S.UNIT_VALUES) {
      const rows = this.db.rows("SELECT * FROM staff WHERE role=? AND unit=? AND (name LIKE ? OR reg_no LIKE ? OR phone LIKE ?) ORDER BY reg_no, name",
        S.CAT_ROLES[this.cat], code, q, q, q);
      if (rows.isEmpty()) continue;
      this.list.addView(Ui.section(this, (Db.DEPT.equals(code) ? (this.cat >= 2 ? "Not posted yet" : "Department") : Db.unitName(code)) + "  ·  " + rows.size()));
      const card = Ui.card(this);
      for (const s of rows) card.addView(this.row(s));
      this.list.addView(card);
      shown += rows.size();
    }
    // anyone saved under a unit this screen does not list
    const other = this.db.rows("SELECT * FROM staff WHERE role=? AND unit NOT IN ('M1','M2','M3','M4','M5','M6','M7','IMCU','FEVER','CCB','GERI','RHEUM','KDP','DEPT') AND (name LIKE ? OR reg_no LIKE ? OR phone LIKE ?) ORDER BY name",
      S.CAT_ROLES[this.cat], q, q, q);
    if (!other.isEmpty()) {
      this.list.addView(Ui.section(this, "Other  ·  " + other.size()));
      const card = Ui.card(this);
      for (const s of other) card.addView(this.row(s));
      this.list.addView(card);
      shown += other.size();
    }
    if (shown === 0) this.list.addView(this.emptyNote(this.query.isEmpty() ? "No " + S.CATS[this.cat] + " students added yet. Use + Add, or Paste a list." : "No match."));
  }

  row(s) {
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    row.addView(People.avatar(this, s, 40, StaffActivity.CAT_COLORS[this.cat]));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 10), 0, 0, 0);
    t.addView(Ui.tv(this, s.get("name"), 15, Ui.TEXT, true));
    const bits = [];
    if (!Ui.nz(s.get("reg_no")).isEmpty()) bits.add(s.get("reg_no"));
    const y = "Postgraduate" === s.get("role") ? CaseSheet.pgYear(s.get("batch"), Dates.today()) : 0;
    if (y > 0) bits.add(StaffActivity.PG_YEAR_LABELS[y - 1]);
    else if (!Ui.nz(s.get("batch")).isEmpty()) bits.add(s.get("batch"));
    if (!Ui.nz(s.get("phone")).isEmpty()) bits.add(s.get("phone"));
    if (!bits.isEmpty()) t.addView(Ui.muted(this, TextUtils.join("  ·  ", bits)));
    row.addView(t, Ui.weight(1));
    const ap = Approvals.pill(this, s);
    if (ap != null) {
      row.addView(ap);
      Ui.margins(ap, 0, 0, 6, 0);
    }
    if (!Ui.nz(s.get("phone")).isEmpty()) {
      const call = Ui.softPill(this, "Call", Ui.GREEN);
      call.setOnClickListener({
        onClick: (v) => { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + s.get("phone")))); }
      });
      row.addView(call);
      if (WhatsApp.usable(s.get("phone"))) {
        const wa = WhatsApp.pill(this, s.get("phone"));
        row.addView(wa);
        Ui.margins(wa, 6, 0, 0, 0);
      }
    }
    Ui.ripple(row, Ui.alpha(StaffActivity.CAT_COLORS[this.cat], 0x1A));
    row.setOnClickListener({
      onClick: (v) => { StaffActivity.studentDialog(this, s, s.get("role"), s.get("unit"), this.refresh()); }
    });
    return row;
  }

  refresh() {
    return {
      run: () => { this.render(); }
    };
  }

  /** Add (s == null) or edit one student. */
  static studentDialog(a, s, role, unit, done) {
    const S = StaffActivity;
    const db = Db.get(a);
    if (!Approvals.mayChange(a, role)) {
      Ui.toast(a, Approvals.FACULTY_ONLY_NOTE);
      return;
    }
    const f = new Form(a);
    const pg = role.equals("Postgraduate") || role.equals("CRMI");
    f.text("name", "Name *", s == null ? (pg ? "Dr. " : "") : s.get("name"), Form.TEXT);
    f.choice("role", "Section", S.CATS, S.CAT_ROLES, role, {
      changed: (r) => {
        f.show("pg_year", r.equals("Postgraduate"));
        f.show("batch", !r.equals("Postgraduate"));
      }
    });
    f.choice("unit", pg ? "Unit" : "Clinical posting", S.UNIT_LABELS, S.UNIT_VALUES, s == null ? unit : s.get("unit"), null);
    f.text("reg_no", "Roll no / Reg no", s == null ? "" : Ui.nz(s.get("reg_no")), Form.TEXT);
    const batch0 = s == null ? "" : Ui.nz(s.get("batch"));
    const y0 = CaseSheet.pgYear(batch0, Dates.today());
    f.choice("pg_year", "PG year", S.PG_YEAR_LABELS, S.PG_YEAR_VALUES, y0 > 0 ? String(y0) : "", null);
    f.text("batch", "Batch / academic year (e.g. 2023 batch)", batch0, Form.TEXT);
    f.show("pg_year", role.equals("Postgraduate"));
    f.show("batch", !role.equals("Postgraduate"));
    f.text("phone", "Phone", s == null ? "" : Ui.nz(s.get("phone")), Form.PHONE);
    const waiting = s != null && !Ui.nz(s.get("approval")).isEmpty();
    if (waiting) S.approvalBlock(a, f, s);
    else if (s == null && !Approvals.canApprove(a, role))
      f.view.addView(Ui.muted(a, "New entries wait for approval by " + Approvals.approverLabel(role) + " before they appear in attendance and duty lists."), 0);
    if (s != null) {
      const del = Ui.outlineButton(a, "Remove", Ui.RED, null);
      f.view.addView(del);
      Ui.margins(del, 0, 16, 0, 0);
      del.setOnClickListener({
        onClick: (v) => {
          Ui.confirm(a, "Remove " + s.get("name") + "?", "They will be removed from the students list, with their attendance and leave records.", "Remove", {
            run: () => {
              db.deleteStaff(Long.parseLong(s.get("id")));
              done.run();
            }
          });
        }
      });
    }
    Ui.formDialog(a, s == null ? "Add student" : "Edit student", f, "Save", {
      run: () => {
        const name = f.get("name");
        if (name.isEmpty() || name.equals("Dr.")) {
          Ui.toast(a, "Enter a name");
          return false;
        }
        if (!Approvals.mayChange(a, f.get("role"))) {
          Ui.toast(a, Approvals.FACULTY_ONLY_NOTE);
          return false;
        }
        const cv = new ContentValues();
        cv.put("name", name);
        cv.put("role", f.get("role"));
        cv.put("unit", f.get("unit"));
        cv.put("reg_no", f.get("reg_no"));
        cv.put("batch", f.get("role").equals("Postgraduate") ? S.pgBatch(f.get("pg_year"), batch0) : f.get("batch"));
        cv.put("phone", f.get("phone"));
        if (s == null) {
          db.insert("staff", cv);
          if (Approvals.PENDING.equals(cv.getAsString("approval")))
            Ui.toast(a, "Saved. Waiting for approval by " + Approvals.approverLabel(cv.getAsString("role")));
        } else {
          Approvals.stamp(a, cv, s);
          db.update("staff", cv, Long.parseLong(s.get("id")));
          if (waiting && "1" === f.get("approve_now") && Approvals.canApprove(a, f.get("role")))
            Approvals.approve(db, a, Long.parseLong(s.get("id")));
        }
        done.run();
        return true;
      }
    });
  }

  /** The batch (year of joining) for a PG now in the given year; it moves up each July (CaseSheet.pgYear). Unchanged if the year is unchanged. */
  static pgBatch(year, old) {
    if (year == null || year.isEmpty()) return old;
    const y = Integer.parseInt(year);
    const t = Dates.today();
    if (CaseSheet.pgYear(old, t) === y) return old;
    const joined = t.getYear() - y + (t.getMonthValue() >= 7 ? 1 : 0);
    return joined + " batch";
  }

  /** In an edit form: who added a waiting entry, why it was not approved, and (for approvers) an approve tick. */
  static approvalBlock(a, f, s) {
    const rejected = Approvals.REJECTED.equals(s.get("approval"));
    const who = Ui.nz(s.get("added_by")).isEmpty() ? "" : " Added by " + s.get("added_by") + (Ui.nz(s.get("added_on")).isEmpty() ? "" : " on " + Dates.nice(s.get("added_on").jsplit(" ")[0])) + ".";
    const msg = rejected ? "Not approved" + (Ui.nz(s.get("approved_by")).isEmpty() ? "" : " by " + s.get("approved_by"))
      + (Ui.nz(s.get("approval_note")).isEmpty() ? "." : ": " + s.get("approval_note")) + " Correct and save to send it again."
      : "Waiting for approval by " + Approvals.approverLabel(s.get("role")) + "." + who;
    const t = Ui.tv(a, msg, 13, rejected ? Ui.RED : Ui.AMBER, true);
    f.view.addView(t, 0);
    if (Approvals.canApprove(a, s.get("role"))) f.check("approve_now", "Approve this entry", !rejected);
  }

  /** Adds many students at once: one per line, as "name", "roll no, name" or "roll no  name". */
  pasteDialog() {
    const S = StaffActivity;
    const f = new Form(this);
    f.multi("lines", "One student per line (roll no first is optional)", "");
    f.choice("unit", this.cat >= 2 ? "Clinical posting for all of them" : "Unit for all of them", S.UNIT_LABELS, S.UNIT_VALUES, this.cat >= 2 ? Db.DEPT : "M1", null);
    f.text("batch", "Batch / academic year (optional)", "", Form.TEXT);
    Ui.formDialog(this, "Paste " + S.CATS[this.cat] + " list", f, "Add", {
      run: () => {
        let added = 0, skipped = 0;
        for (const p of S.parseList(f.get("lines"))) {
          if (this.db.num("SELECT COUNT(*) FROM staff WHERE role=? AND lower(trim(name))=lower(?)", S.CAT_ROLES[this.cat], p[1]) > 0) {
            skipped++;
            continue;
          }
          const cv = new ContentValues();
          cv.put("name", p[1]);
          cv.put("reg_no", p[0]);
          cv.put("role", S.CAT_ROLES[this.cat]);
          cv.put("unit", f.get("unit"));
          cv.put("batch", f.get("batch"));
          cv.put("phone", "");
          this.db.insert("staff", cv);
          added++;
        }
        if (added === 0 && skipped === 0) {
          Ui.toast(this, "Paste at least one name");
          return false;
        }
        Ui.toast(this, added + " added" + (skipped > 0 ? ", " + skipped + " already on the list" : ""));
        this.render();
        return true;
      }
    });
  }

  /** {roll no, name} for each non-empty line; a leading serial number like "1." is dropped. */
  static parseList(text) {
    const out = [];
    for (const raw of text.jsplit("\\r?\\n")) {
      const line = raw.trim().replaceAllRx("^\\d{1,3}[.)]\\s+", "");
      if (line.isEmpty()) continue;
      let roll = "", name = line;
      const parts = line.jsplit("\\s*[,\\t|]\\s*");
      if (parts.length >= 2 && parts[0].matches(".*\\d.*") && !parts[1].isEmpty()) {
        roll = parts[0];
        name = line.substring(line.indexOf(parts[1], parts[0].length));
      } else if (parts.length >= 2 && parts[parts.length - 1].matches("[A-Za-z]*\\d[\\w/-]*")) {
        roll = parts[parts.length - 1];
        name = line.substring(0, line.lastIndexOf(roll)).replaceAllRx("[\\s,\\t|]+$", "");
      } else {
        const m = Pattern.compile("^([A-Za-z]{0,4}\\d[\\w/-]*)\\s+(.+)$").matcher(line);
        if (m.find()) {
          roll = m.group(1);
          name = m.group(2);
        }
      }
      name = name.replaceAllRx("\\s+", " ").trim();
      if (!name.isEmpty()) out.add([roll, name]);
    }
    return out;
  }

  /** Add or edit a unit team member (faculty, PG, CRMI, nurse), used from each unit's team card. */
  static editDialog(a, s, unit, done) {
    const S = StaffActivity;
    const db = Db.get(a);
    if (s != null && !Approvals.mayChange(a, s.get("role"))) {
      Ui.toast(a, Approvals.FACULTY_ONLY_NOTE);
      return;
    }
    const f = new Form(a);
    f.text("name", "Name *", s == null ? "Dr. " : s.get("name"), Form.TEXT);
    f.choice("role", "Designation", Db.ROLES, Db.ROLES, s == null ? "Assistant Professor" : s.get("role"), null);
    f.choice("unit", "Unit", S.UNIT_LABELS, S.UNIT_VALUES, s == null ? unit : s.get("unit"), null);
    f.text("phone", "Phone", s == null ? "" : s.get("phone"), Form.PHONE);
    if (s != null) {
      const del = Ui.outlineButton(a, "Remove from team", Ui.RED, null);
      f.view.addView(del);
      Ui.margins(del, 0, 16, 0, 0);
      del.setOnClickListener({
        onClick: (v) => {
          Ui.confirm(a, "Remove " + s.get("name") + "?", "They will be removed from the staff list, with their photo, documents, attendance and leave records.", "Remove", {
            run: () => {
              db.deleteStaff(Long.parseLong(s.get("id")));
              done.run();
            }
          });
        }
      });
    }
    Ui.formDialog(a, s == null ? "Add staff member" : "Edit staff member", f, "Save", {
      run: () => {
        const name = f.get("name");
        if (name.isEmpty() || name.equals("Dr.")) {
          Ui.toast(a, "Enter a name");
          return false;
        }
        const cv = new ContentValues();
        cv.put("name", name);
        cv.put("role", f.get("role"));
        cv.put("unit", f.get("unit"));
        cv.put("phone", f.get("phone"));
        if (!Approvals.mayChange(a, f.get("role"))) {
          Ui.toast(a, Approvals.FACULTY_ONLY_NOTE);
          return false;
        }
        if (s == null) db.insert("staff", cv);
        else db.update("staff", cv, Long.parseLong(s.get("id")));
        done.run();
        return true;
      }
    });
  }
}
;
