/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Writes a discharge summary as a Word (.docx) or PDF file under files/exports/, made on the phone. */
class SummaryExport {
  static DIR = 'exports';

  /** Turns a discharge summary layout into the case summary: no discharge date, stamped with when it was made. */
  static asCaseSummary(d) {
    d.title = 'CASE SUMMARY';
    d.patientCopy = false;
    d.footer = 'Case summary';
    d.details.remove('Date of discharge');
    d.details.put('Summary as on', Dates.nice(Dates.today()) + ' ' + Dates.now());
    d.fileBase = d.fileBase.split('Discharge_summary_').join('Case_summary_');
  }

  // ---------- medicines to take at home ----------

  static DRUG = Pattern.compile(
      '(?i)^(tab|tablet|cap|capsule|syp|syr|syrup|inj|injection|oint|inh|inhaler|neb|drops?|susp|gel|cream|sachet)\\b\\.?\\s+.+');
  static FREQ = Pattern.compile(
      '(?i)(?<![\\w-])(OD|BD|BID|TDS|TID|QID|HS|SOS|STAT|PRN|(?:[0-9½]+(?:/2)?-){2}[0-9½]+(?:/2)?)(?![\\w-])');
  static DAYS = Pattern.compile(
      '(?i)(?:(?:\\bx\\s*|\\bfor\\s+)(\\d+\\s*(?:days?|d|weeks?|wks?|months?|mo)\\b)|\\b(?:for\\s+)?(life\\s*long|long\\s*term)\\b)');

  /** The medicine in this line, or null when the line isn't a prescription (diet, activity, warning signs…). */
  static med(line) {
    const l = Ui.nz(line).trim().replaceAllRx('^[•\\-*]\\s*', '').replaceAllRx('^\\d+[.)]\\s+', '');
    if (!SummaryExport.DRUG.matcher(l).matches()) return null;
    const f = SummaryExport.FREQ.matcher(l);
    if (!f.find()) return null;
    const m = new SummaryExport.Med();
    const code = f.group(1).toUpperCase();
    let rest = (l.substring(0, f.start()) + ' ' + l.substring(f.end())).trim();
    const dm = SummaryExport.DAYS.matcher(rest);
    if (dm.find()) {
      m.days = (dm.group(1) != null ? dm.group(1) : dm.group(2)).replaceAllRx('(?i)\\bd\\b', 'days').replaceAllRx('(?i)wks?', 'weeks').replaceAllRx('(?i)\\bmo\\b', 'months')
          .replaceAllRx('(?i)life\\s*long', 'Lifelong').replaceAllRx('(?i)long\\s*term', 'Long term').replaceAllRx('\\s+', ' ');
      rest = (rest.substring(0, dm.start()) + ' ' + rest.substring(dm.end())).trim();
    }
    m.name = rest.replaceAllRx('(?i)\\b(PO|per oral|orally)\\b', '').replaceAllRx('\\s+', ' ').replaceAllRx('[,;\\s]+$', '').trim();
    switch (code) {
      case 'OD': m.slots = ['1', '–', '–']; break;
      case 'BD': case 'BID': m.slots = ['1', '–', '1']; break;
      case 'TDS': case 'TID': m.slots = ['1', '1', '1']; break;
      case 'HS': m.slots = ['–', '–', '1']; break;
      case 'QID': m.when = '4 times a day'; break;
      case 'SOS': case 'PRN': m.when = 'Only when needed'; break;
      case 'STAT': m.when = 'Once'; break;
      default: {
        const p = code.jsplit('-');
        if (p.length === 3) {
          m.slots = new Array(3).fill(null);
          for (let i = 0; i < 3; i++) m.slots[i] = p[i].equals('0') ? '–' : p[i].split('1/2').join('½');
        } else m.when = code;
      }
    }
    return m;
  }

  static isAdvice(heading) {
    return heading.toLowerCase().startsWith('advice') || heading.toLowerCase().startsWith('medicines on discharge');
  }

  static isFollowUp(heading) {
    return heading.toLowerCase().split('-').join('').startsWith('follow');
  }

  static build(db, p, sections, o) {
    const d = new SummaryExport.Doc();
    d.dept = db.setting('dept', 'Department of General Medicine');
    d.college = db.setting('college', 'Tirunelveli Medical College Hospital');
    const age = Ui.nz(p.get('age'));
    d.details.put('Name', p.get('name'));
    d.details.put('Age / Sex', (age.isEmpty() ? '' : age + ' years / ') + Base.sexLabel(p.get('sex')));
    d.details.put('IP number', Ui.nz(p.get('ip_no')));
    d.details.put('Unit', Db.unitName(p.get('home_unit')));
    d.details.put('Ward / bed', Base.where(p) + (Ui.nz(p.get('bed')).isEmpty() ? '' : ', bed ' + p.get('bed')));
    d.details.put('Date of admission', Dates.nice(p.get('admit_date')));
    let dod = CaseSheet.s(o, 'dis_date');
    if (dod.isEmpty() && !Ui.nz(p.get('outcome_date')).isEmpty()) dod = p.get('outcome_date');
    d.details.put(Db.DIED.equals(p.get('status')) ? 'Date of death' : 'Date of discharge', dod.isEmpty() ? '' : Dates.nice(dod));
    if ('1'.equals(p.get('cmchis'))) d.details.put('CMCHIS', Ui.nz(p.get('cmchis_no')).isEmpty() ? 'Yes' : p.get('cmchis_no'));
    if (!Ui.nz(p.get('phone')).isEmpty()) d.details.put('Phone', p.get('phone'));
    d.sections = sections;
    const u = db.row('SELECT head FROM units WHERE code=?', Ui.nz(p.get('home_unit')));
    d.unitChief = u == null ? '' : Ui.nz(u.get('head'));
    d.hod = db.setting('hod', '');
    d.fileBase = 'Discharge_summary_' + Store.safeName(p.get('name')) + (Ui.nz(p.get('ip_no')).isEmpty() ? '' : '_IP' + Store.safeName(p.get('ip_no')));
    return d;
  }

  static logoPng(c, px) {
    try {
      const bm = ShimE.logo();   // BitmapFactory.decodeResource(c.getResources(), R.drawable.dept_logo), ready now
      if (bm == null || !bm.getWidth()) return null;
      const s = Bitmap.createScaledBitmap(bm, px, Math.max(1, idiv(px * bm.getHeight(), bm.getWidth())), true);
      const out = new ByteArrayOutputStream();
      s.compress(Bitmap.CompressFormat.PNG, 100, out);
      return out.toByteArray();
    } catch (t) {
      return null;
    }
  }

  // ---------- Word ----------

  /** Writes files/exports/{fileBase}.docx and returns its path under files/. */
  static docx(c, d) {
    const rel = SummaryExport.DIR + '/' + d.fileBase + '.docx';
    const f = new File(c.getFilesDir(), rel);
    f.getParentFile().mkdirs();
    const logo = SummaryExport.logoPng(c, 240);
    const z = new ZipOutputStream(new FileOutputStream(f));
    try {
      SummaryExport.put(z, '[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          + '<Default Extension="xml" ContentType="application/xml"/>'
          + '<Default Extension="png" ContentType="image/png"/>'
          + '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
          + '</Types>');
      SummaryExport.put(z, '_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
          + '</Relationships>');
      SummaryExport.put(z, 'word/_rels/document.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          + (logo == null ? '' : '<Relationship Id="rIdLogo" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/logo.png"/>')
          + '</Relationships>');
      if (logo != null) {
        z.putNextEntry(new ZipEntry('word/media/logo.png'));
        z.write(logo);
        z.closeEntry();
      }
      SummaryExport.put(z, 'word/document.xml', SummaryExport.documentXml(d, logo != null));
    } finally {
      z.close();
    }
    return rel;
  }

  static put(z, name, s) {
    z.putNextEntry(new ZipEntry(name));
    z.write(jbytes(s));
    z.closeEntry();
  }

  static esc(s) {
    return Ui.nz(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
  }

  static run(text, bold, halfPts, color) {
    return '<w:r><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:cs="Calibri"/>' + (bold ? '<w:b/>' : '')
        + (color == null ? '' : '<w:color w:val="' + color + '"/>') + '<w:sz w:val="' + halfPts + '"/></w:rPr>'
        + '<w:t xml:space="preserve">' + SummaryExport.esc(text) + '</w:t></w:r>';
  }

  static para(align, after, runs) {
    return '<w:p><w:pPr><w:spacing w:before="0" w:after="' + after + '"/>' + (align == null ? '' : '<w:jc w:val="' + align + '"/>')
        + '</w:pPr>' + runs + '</w:p>';
  }

  static documentXml(d, logo) {
    const run = SummaryExport.run, para = SummaryExport.para;
    const b = new StringBuilder('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
        + ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"'
        + ' xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"'
        + ' xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"'
        + ' xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>');
    if (logo) {
      const emu = 762000;   // 0.83 inch
      b.append('<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:after="60"/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0">')
          .append('<wp:extent cx="').append(emu).append('" cy="').append(emu).append('"/><wp:docPr id="1" name="Logo"/>')
          .append('<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic>')
          .append('<pic:nvPicPr><pic:cNvPr id="1" name="logo.png"/><pic:cNvPicPr/></pic:nvPicPr>')
          .append('<pic:blipFill><a:blip r:embed="rIdLogo"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>')
          .append('<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="').append(emu).append('" cy="').append(emu).append('"/></a:xfrm>')
          .append('<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>');
    }
    b.append(para('center', 0, run(d.dept.toUpperCase(), true, 28, '1D4E89')));
    b.append(para('center', 120, run(d.college, false, 22, '334155')));
    b.append('<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="12" w:space="1" w:color="14A3A0"/></w:pBdr><w:spacing w:after="160"/></w:pPr></w:p>');
    b.append(para('center', 160, run(d.title, true, 30, '0B2E5C')));

    // patient details: two pairs per row
    b.append('<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/><w:tblBorders>')
        .append('<w:top w:val="single" w:sz="4" w:color="CBD5E1"/><w:left w:val="single" w:sz="4" w:color="CBD5E1"/>')
        .append('<w:bottom w:val="single" w:sz="4" w:color="CBD5E1"/><w:right w:val="single" w:sz="4" w:color="CBD5E1"/>')
        .append('<w:insideH w:val="single" w:sz="4" w:color="CBD5E1"/><w:insideV w:val="single" w:sz="4" w:color="CBD5E1"/>')
        .append('</w:tblBorders><w:tblCellMar><w:left w:w="100" w:type="dxa"/><w:right w:w="100" w:type="dxa"/></w:tblCellMar></w:tblPr>')
        .append('<w:tblGrid><w:gridCol w:w="1800"/><w:gridCol w:w="2800"/><w:gridCol w:w="1800"/><w:gridCol w:w="2800"/></w:tblGrid>');
    const det = ArrayList(d.details.entrySet());
    for (let i = 0; i < det.size(); i += 2) {
      b.append('<w:tr>');
      for (let k = i; k < i + 2; k++) {
        const key = k < det.size() ? det.get(k).getKey() : '', val = k < det.size() ? det.get(k).getValue() : '';
        b.append('<w:tc><w:tcPr><w:shd w:val="clear" w:color="auto" w:fill="EEF3FA"/></w:tcPr>')
            .append(para(null, 0, run(key, true, 20, '334155'))).append('</w:tc>');
        b.append('<w:tc>').append(para(null, 0, run(val, false, 20, null))).append('</w:tc>');
      }
      b.append('</w:tr>');
    }
    b.append('</w:tbl>');

    for (const e of d.sections.entrySet()) {
      if (Ui.nz(e.getValue()).trim().isEmpty()) continue;
      b.append('<w:p><w:pPr><w:spacing w:before="220" w:after="60"/><w:pBdr><w:bottom w:val="single" w:sz="4" w:space="1" w:color="CBD5E1"/></w:pBdr></w:pPr>')
          .append(run(e.getKey().toUpperCase(), true, 22, '1D4E89')).append('</w:p>');
      const meds = [];
      if (d.patientCopy && SummaryExport.isAdvice(e.getKey()))
        for (const line of e.getValue().trim().jsplit('\n')) { const m = SummaryExport.med(line); if (m != null) meds.add(m); }
      if (!meds.isEmpty()) b.append(SummaryExport.medTableXml(meds));
      if (d.patientCopy && SummaryExport.isFollowUp(e.getKey())) {
        for (const line of e.getValue().trim().jsplit('\n'))
          if (!line.trim().isEmpty())
            b.append('<w:p><w:pPr><w:shd w:val="clear" w:color="auto" w:fill="E6F6F5"/><w:pBdr><w:left w:val="single" w:sz="24" w:space="6" w:color="14A3A0"/></w:pBdr>'
                + '<w:spacing w:after="0"/><w:ind w:left="160"/></w:pPr>').append(run(line.trim().replaceAllRx('^•\\s*', ''), true, 22, '0B2E5C')).append('</w:p>');
        continue;
      }
      for (const line of e.getValue().trim().jsplit('\n')) {
        const l = line.trim();
        if (l.isEmpty() || !meds.isEmpty() && SummaryExport.med(l) != null) continue;
        const colon = l.indexOf(': ');
        const labelled = !l.startsWith('•') && colon > 0 && colon < 28;
        if (l.startsWith('•'))
          b.append('<w:p><w:pPr><w:spacing w:after="40"/><w:ind w:left="360" w:hanging="240"/></w:pPr>').append(run(l, false, 22, null)).append('</w:p>');
        else if (labelled)
          b.append(para('both', 60, run(l.substring(0, colon + 1) + ' ', true, 22, null) + run(l.substring(colon + 2), false, 22, null)));
        else b.append(para('both', 60, run(l, false, 22, null)));
      }
    }

    // signatures
    b.append(para(null, 0, ''));
    b.append(para(null, 0, ''));
    b.append('<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/></w:tblPr><w:tblGrid><w:gridCol w:w="4600"/><w:gridCol w:w="4600"/></w:tblGrid><w:tr>');
    b.append('<w:tc>').append(para(null, 0, run('Signature of unit chief', true, 20, null)))
        .append(para(null, 0, run(d.unitChief, false, 20, '334155'))).append('</w:tc>');
    b.append('<w:tc>').append(para('right', 0, run('Professor & Head of the Department', true, 20, null)))
        .append(para('right', 0, run(d.hod, false, 20, '334155'))).append('</w:tc>');
    b.append('</w:tr></w:tbl>');
    b.append('<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="850" w:right="1000" w:bottom="850" w:left="1000" w:header="400" w:footer="400" w:gutter="0"/></w:sectPr>');
    b.append('</w:body></w:document>');
    return b.toString();
  }

  static cellXml(text, head, align, w) {
    return '<w:tc><w:tcPr><w:tcW w:w="' + w + '" w:type="dxa"/>' + (head ? '<w:shd w:val="clear" w:color="auto" w:fill="1D4E89"/>' : '')
        + '<w:vAlign w:val="center"/></w:tcPr>' + SummaryExport.para(align, 0, SummaryExport.run(text, head, head ? 19 : 21, head ? 'FFFFFF' : null)) + '</w:tc>';
  }

  /** Medicines to take at home as a table the patient can follow. */
  static medTableXml(meds) {
    const run = SummaryExport.run, para = SummaryExport.para, cellXml = SummaryExport.cellXml;
    const b = new StringBuilder();
    b.append(para(null, 60, run('Medicines to take at home', true, 21, '0F172A')));
    b.append('<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/><w:tblBorders>')
        .append('<w:top w:val="single" w:sz="4" w:color="CBD5E1"/><w:left w:val="single" w:sz="4" w:color="CBD5E1"/>')
        .append('<w:bottom w:val="single" w:sz="4" w:color="CBD5E1"/><w:right w:val="single" w:sz="4" w:color="CBD5E1"/>')
        .append('<w:insideH w:val="single" w:sz="4" w:color="CBD5E1"/><w:insideV w:val="single" w:sz="4" w:color="CBD5E1"/>')
        .append('</w:tblBorders><w:tblCellMar><w:top w:w="50" w:type="dxa"/><w:left w:w="100" w:type="dxa"/><w:bottom w:w="50" w:type="dxa"/><w:right w:w="100" w:type="dxa"/></w:tblCellMar></w:tblPr>')
        .append('<w:tblGrid><w:gridCol w:w="4300"/><w:gridCol w:w="1100"/><w:gridCol w:w="1200"/><w:gridCol w:w="1100"/><w:gridCol w:w="1300"/></w:tblGrid>');
    b.append('<w:tr><w:trPr><w:tblHeader/></w:trPr>').append(cellXml('Medicine and dose', true, null, 4300)).append(cellXml('Morning', true, 'center', 1100))
        .append(cellXml('Afternoon', true, 'center', 1200)).append(cellXml('Night', true, 'center', 1100)).append(cellXml('How long', true, 'center', 1300)).append('</w:tr>');
    let i = 0;
    for (const m of meds) {
      const fill = i++ % 2 === 1 ? '<w:shd w:val="clear" w:color="auto" w:fill="F5F8FC"/>' : '';
      b.append('<w:tr>').append(cellXml(m.name, false, null, 4300).split('<w:vAlign').join(fill + '<w:vAlign'));
      if (m.slots != null) for (let k = 0; k < 3; k++)
        b.append(cellXml(m.slots[k], false, 'center', k === 1 ? 1200 : 1100).split('<w:vAlign').join(fill + '<w:vAlign'));
      else b.append('<w:tc><w:tcPr><w:tcW w:w="3400" w:type="dxa"/><w:gridSpan w:val="3"/>' + fill + '<w:vAlign w:val="center"/></w:tcPr>')
          .append(para('center', 0, run(m.when, false, 21, null))).append('</w:tc>');
      b.append(cellXml(m.days, false, 'center', 1300).split('<w:vAlign').join(fill + '<w:vAlign')).append('</w:tr>');
    }
    b.append('</w:tbl>');
    b.append(para(null, 80, run('1 = one dose at that time,  – = no dose.', false, 17, '64748B')));
    return b.toString();
  }

  // ---------- PDF ----------

  static W = 595;
  static H = 842;
  static M = 42;

  /* interface Pages { Canvas start(int number); void end(); }: where the pages are drawn, a PDF on the phone or bitmaps for a preview. */

  /** Writes files/exports/{fileBase}.pdf (A4) and returns its path under files/. */
  static pdf(c, d) {
    const W = SummaryExport.W, H = SummaryExport.H;
    const rel = SummaryExport.DIR + '/' + d.fileBase + '.pdf';
    const f = new File(c.getFilesDir(), rel);
    f.getParentFile().mkdirs();
    const pdf = new PdfDocument();
    try {
      let page = null;
      SummaryExport.draw(c, d, {
        start: (number) => {
          page = pdf.startPage(new PdfDocument.PageInfo.Builder(W, H, number).create());
          return page.getCanvas();
        },
        end: () => {
          pdf.finishPage(page);
        }
      });
      const out = new FileOutputStream(f);
      try {
        pdf.writeTo(out);
      } finally {
        out.close();
      }
    } finally {
      pdf.close();
    }
    return rel;
  }

  /** Lays out the summary on A4 pages (595 x 842 points). Returns the number of pages. */
  static draw(c, d, pages) {
    const W = SummaryExport.W, M = SummaryExport.M, text = SummaryExport.text;
    const pg = new SummaryExport.Pager(pages, d);
    const cv = pg.canvas;

    // letterhead
    let logo = null;
    try {
      logo = ShimE.logo();   // BitmapFactory.decodeResource(c.getResources(), R.drawable.dept_logo), ready now
    } catch (ignored) {
    }
    const top = M;
    if (logo != null) cv.drawBitmap(logo, null, new RectF(M, top, M + 58, top + 58), new Paint(Paint.FILTER_BITMAP_FLAG));
    const head = text(15, true, 0xFF1D4E89);
    const sub = text(11, false, 0xFF334155);
    const cx = (W + (logo != null ? 58 : 0)) / 2;
    head.setTextAlign(Paint.Align.CENTER);
    sub.setTextAlign(Paint.Align.CENTER);
    cv.drawText(d.dept.toUpperCase(), cx, top + 24, head);
    cv.drawText(d.college, cx, top + 42, sub);
    const rule = new Paint();
    rule.setColor(0xFF14A3A0);
    rule.setStrokeWidth(1.6);
    cv.drawLine(M, top + 66, W - M, top + 66, rule);
    const title = text(14, true, 0xFF0B2E5C);
    title.setTextAlign(Paint.Align.CENTER);
    cv.drawText(d.title, W / 2, top + 90, title);
    pg.y = top + 104;

    // details grid
    const key = text(9.5, true, 0xFF334155), val = text(9.5, false, 0xFF0F172A);
    const box = new Paint();
    box.setStyle(Paint.Style.STROKE);
    box.setColor(0xFFCBD5E1);
    box.setStrokeWidth(0.7);
    const fill = new Paint();
    fill.setColor(0xFFEEF3FA);
    const det = ArrayList(d.details.entrySet());
    const colW = (W - 2 * M) / 2, kw = 92, rowH = 18;
    for (let i = 0; i < det.size(); i += 2) {
      for (let k = i; k < i + 2 && k < det.size(); k++) {
        const x = M + (k - i) * colW;
        cv.drawRect(x, pg.y, x + kw, pg.y + rowH, fill);
        cv.drawRect(x, pg.y, x + colW, pg.y + rowH, box);
        cv.drawLine(x + kw, pg.y, x + kw, pg.y + rowH, box);
        cv.drawText(det.get(k).getKey(), x + 5, pg.y + 12.5, key);
        const v = nz(det.get(k).getValue());
        const n = val.breakText(v, true, colW - kw - 10, null);
        cv.drawText(n < v.length ? v.substring(0, Math.max(0, n - 1)) + '…' : v, x + kw + 5, pg.y + 12.5, val);
      }
      pg.y += rowH;
    }
    pg.y += 8;

    const secHead = text(11, true, 0xFF1D4E89);
    const body = text(10.5, false, 0xFF0F172A);
    const bodyBold = text(10.5, true, 0xFF0F172A);
    const thin = new Paint();
    thin.setColor(0xFFCBD5E1);
    thin.setStrokeWidth(0.7);
    const lh = 14.5;
    for (const e of d.sections.entrySet()) {
      if (Ui.nz(e.getValue()).trim().isEmpty()) continue;
      pg.need(lh * 3 + 12);
      pg.y += 12;
      pg.canvas.drawText(e.getKey().toUpperCase(), M, pg.y, secHead);
      pg.canvas.drawLine(M, pg.y + 4, W - M, pg.y + 4, thin);
      pg.y += lh + 2;
      const meds = [];
      if (d.patientCopy && SummaryExport.isAdvice(e.getKey()))
        for (const line of e.getValue().trim().jsplit('\n')) { const m = SummaryExport.med(line); if (m != null) meds.add(m); }
      if (!meds.isEmpty()) SummaryExport.drawMeds(pg, meds);
      if (d.patientCopy && SummaryExport.isFollowUp(e.getKey())) {
        SummaryExport.drawBox(pg, e.getValue().trim().replace(/^•\s*/gm, ''));
        continue;
      }
      for (const line of e.getValue().trim().jsplit('\n')) {
        let l = line.trim();
        if (l.isEmpty() || !meds.isEmpty() && SummaryExport.med(l) != null) continue;
        const bullet = l.startsWith('•');
        const indent = bullet ? 12 : 0;
        let label = null;
        const colon = l.indexOf(': ');
        if (!bullet && colon > 0 && colon < 28) {
          label = l.substring(0, colon + 1);
          l = l.substring(colon + 2);
        }
        if (bullet) l = l.substring(1).trim();
        const firstOffset = label == null ? 0 : bodyBold.measureText(label + ' ');
        const lines = SummaryExport.wrap(l, body, W - 2 * M - indent, firstOffset);
        for (let i = 0; i < lines.size(); i++) {
          pg.need(lh);
          if (i === 0 && bullet) pg.canvas.drawText('•', M + 2, pg.y, body);
          if (i === 0 && label != null) pg.canvas.drawText(label, M, pg.y, bodyBold);
          pg.canvas.drawText(lines.get(i), M + indent + (i === 0 ? firstOffset : 0), pg.y, body);
          pg.y += lh;
        }
        pg.y += 2;
      }
    }

    // signatures
    pg.need(80);
    pg.y += 50;
    const sig = text(10, true, 0xFF0F172A), sigName = text(10, false, 0xFF334155);
    pg.canvas.drawText('Signature of unit chief', M, pg.y, sig);
    if (!Ui.nz(d.unitChief).isEmpty()) pg.canvas.drawText(d.unitChief, M, pg.y + 14, sigName);
    sig.setTextAlign(Paint.Align.RIGHT);
    sigName.setTextAlign(Paint.Align.RIGHT);
    pg.canvas.drawText('Professor & Head of the Department', W - M, pg.y, sig);
    if (!Ui.nz(d.hod).isEmpty()) pg.canvas.drawText(d.hod, W - M, pg.y + 14, sigName);
    pg.finishPage();
    return pg.n;
  }

  /** The medicines table on the PDF; long names wrap inside their column and the header repeats on a new page. */
  static drawMeds(pg, meds) {
    const W = SummaryExport.W, H = SummaryExport.H, M = SummaryExport.M, text = SummaryExport.text;
    const cw = [231, 66, 72, 62, 80];      // = W - 2M
    const head = ['Medicine and dose', 'Morning', 'Afternoon', 'Night', 'How long'];
    const label = text(10, true, 0xFF0F172A), hp = text(9, true, 0xFFFFFFFF), cell = text(10, false, 0xFF0F172A), note = text(8.5, false, 0xFF64748B);
    const hf = new Paint(), alt = new Paint(), line = new Paint();
    hf.setColor(0xFF1D4E89);
    alt.setColor(0xFFF5F8FC);
    line.setColor(0xFFCBD5E1);
    line.setStrokeWidth(0.7);
    line.setStyle(Paint.Style.STROKE);
    pg.need(56);
    pg.canvas.drawText('Medicines to take at home', M, pg.y, label);
    pg.y += 6;
    let header = true;
    for (let r = 0; r < meds.size(); r++) {
      const m = meds.get(r);
      const nm = SummaryExport.wrap(m.name, cell, cw[0] - 10, 0);
      const rh = Math.max(20, nm.size() * 12.5 + 8);
      if (pg.y + rh + 20 > H - M - 20) { pg.need(H); header = true; }
      if (header) {
        pg.canvas.drawRect(M, pg.y, W - M, pg.y + 18, hf);
        let x = M;
        for (let k = 0; k < 5; k++) {
          hp.setTextAlign(k === 0 ? Paint.Align.LEFT : Paint.Align.CENTER);
          pg.canvas.drawText(head[k], k === 0 ? x + 6 : x + cw[k] / 2, pg.y + 12.5, hp);
          x += cw[k];
        }
        pg.y += 18;
        header = false;
      }
      if (r % 2 === 1) pg.canvas.drawRect(M, pg.y, W - M, pg.y + rh, alt);
      pg.canvas.drawRect(M, pg.y, W - M, pg.y + rh, line);
      let x = M;
      const base = pg.y + (rh - nm.size() * 12.5) / 2 + 9.5;
      for (let i = 0; i < nm.size(); i++) pg.canvas.drawText(nm.get(i), x + 6, base + i * 12.5, cell);
      x += cw[0];
      cell.setTextAlign(Paint.Align.CENTER);
      const mid = pg.y + rh / 2 + 3.5;
      if (m.slots != null) {
        for (let k = 0; k < 3; k++) {
          pg.canvas.drawLine(x, pg.y, x, pg.y + rh, line);
          pg.canvas.drawText(m.slots[k], x + cw[k + 1] / 2, mid, cell);
          x += cw[k + 1];
        }
      } else {
        pg.canvas.drawLine(x, pg.y, x, pg.y + rh, line);
        const span = cw[1] + cw[2] + cw[3];
        pg.canvas.drawText(m.when, x + span / 2, mid, cell);
        x += span;
      }
      pg.canvas.drawLine(x, pg.y, x, pg.y + rh, line);
      pg.canvas.drawText(m.days, x + cw[4] / 2, mid, cell);
      cell.setTextAlign(Paint.Align.LEFT);
      pg.y += rh;
    }
    pg.y += 11;
    pg.canvas.drawText('1 = one dose at that time,  – = no dose.', M, pg.y, note);
    pg.y += 16;
  }

  /** A shaded box with a teal bar on the left, for the follow-up the patient must not miss. */
  static drawBox(pg, text) {
    const W = SummaryExport.W, M = SummaryExport.M;
    const p = SummaryExport.text(10.5, true, 0xFF0B2E5C), fill = new Paint(), bar = new Paint();
    fill.setColor(0xFFE6F6F5);
    bar.setColor(0xFF14A3A0);
    const lines = [];
    for (const l of text.jsplit('\n')) if (!l.trim().isEmpty()) lines.addAll(SummaryExport.wrap(l.trim(), p, W - 2 * M - 24, 0));
    const h = lines.size() * 14.5 + 12;
    pg.need(h + 4);
    const top = pg.y - 10;
    pg.canvas.drawRoundRect(new RectF(M, top, W - M, top + h), 4, 4, fill);
    pg.canvas.drawRect(M, top, M + 3.5, top + h, bar);
    for (const l of lines) {
      pg.canvas.drawText(l, M + 14, pg.y + 4, p);
      pg.y += 14.5;
    }
    pg.y += 12;
  }

  static text(size, bold, color) {
    const p = new Paint(Paint.ANTI_ALIAS_FLAG);
    p.setTextSize(size);
    p.setColor(color);
    p.setTypeface(Typeface.create(Typeface.SANS_SERIF, bold ? Typeface.BOLD : Typeface.NORMAL));
    return p;
  }

  /** Word wrap to a width; the first line may start after a bold label. */
  static wrap(s, p, width, firstOffset) {
    const out = [];
    const cur = new StringBuilder();
    let avail = width - firstOffset;
    for (let w of s.jsplit(' ')) {
      const t = cur.length() === 0 ? w : cur + ' ' + w;
      if (p.measureText(t) <= avail || cur.length() === 0 && p.measureText(w) <= avail) {
        cur.setLength(0);
        cur.append(t);
        continue;
      }
      if (cur.length() > 0) {
        out.add(cur.toString());
        avail = width;
        cur.setLength(0);
      }
      while (p.measureText(w) > avail) {             // a very long word: hard break
        const n = Math.max(1, p.breakText(w, true, avail, null));
        out.add(w.substring(0, n));
        w = w.substring(n);
        avail = width;
      }
      cur.append(w);
    }
    if (cur.length() > 0 || out.isEmpty()) out.add(cur.toString());
    return out;
  }

  // ---------- saving a copy to Downloads ----------

  /** Copies the file to Downloads/TVMCHMED (Android 10 and later). On the web: the browser downloads it. */
  static toDownloads(c, rel) {
    if (Build.VERSION.SDK_INT < 29) return false;
    const src = new File(c.getFilesDir(), rel);
    const name = src.getName(), mime = mimeOf(name);
    const now = VFS.readSync(src.rel());
    if (now) { downloadBytes(now, name, mime); return true; }
    if (!src.exists()) throw new IOException('Could not create the file in Downloads');
    VFS.read(src.rel()).then(b => { if (b) downloadBytes(b, name, mime); });
    return true;
  }
}

/** Everything that goes on the page: letterhead, patient details, the sections and who signs. */
SummaryExport.Doc = class {
  constructor() {
    this.dept = null; this.college = null; this.title = 'DISCHARGE SUMMARY';
    this.details = new JMap();
    this.sections = new JMap();
    this.unitChief = null; this.hod = null;
    this.fileBase = null; this.footer = 'Discharge summary';
    this.patientCopy = true;   // medicines as a table and a follow-up box; off for the case summary
  }
};

/** One medicine line read as a prescription: name and dose, morning / afternoon / night doses, and for how long. */
SummaryExport.Med = class {
  constructor() {
    this.name = null; this.days = ''; this.when = '';
    this.slots = null;   // morning, afternoon, night: "1", "½" or "–"; null when the timing is not a fixed schedule
  }
};

/** Page handling: footer with name and page number, a new page when the text reaches the bottom. */
SummaryExport.Pager = class {
  constructor(pages, d) {
    this.pages = pages;
    this.d = d;
    this.canvas = null;
    this.y = 0;
    this.n = 0;
    this.next();
  }
  next() {
    this.n++;
    this.canvas = this.pages.start(this.n);
    this.y = SummaryExport.M + 10;
  }
  need(h) {
    if (this.y + h <= SummaryExport.H - SummaryExport.M - 20) return;
    this.finishPage();
    this.next();
  }
  finishPage() {
    const M = SummaryExport.M, H = SummaryExport.H, W = SummaryExport.W;
    const f = SummaryExport.text(8.5, false, 0xFF64748B);
    const d = this.d;
    this.canvas.drawText(d.details.get('Name') + (Ui.nz(d.details.get('IP number')).isEmpty() ? '' : '  ·  IP ' + d.details.get('IP number'))
        + '  ·  ' + d.footer, M, H - M + 8, f);
    f.setTextAlign(Paint.Align.RIGHT);
    this.canvas.drawText('Page ' + this.n, W - M, H - M + 8, f);
    this.pages.end();
  }
};
;
