/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** A medical unit (M1–M7) or a special ward (IMCU, fever ward, Critical Care Block). */
class UnitActivity extends Base {
  constructor() {
    super();
    this.code = null;
    this.wingTab = 0; this.toxFilter = 0; this.nonFilter = 0; this.feverTab = 0; this.dengueFilter = 0;
  }

  static CCB_BEDS = 12;

  onCreate(b) {
    super.onCreate(b);
    this.code = this.getIntent().getStringExtra("code");
    if (this.code == null) this.code = "M1";
    this.setTitle(Db.unitName(this.code));
    this.headerColor(Ui.unitColor(this.code));
  }

  render() {
    const db = this.db, code = this.code;
    if (Db.TAEI.equals(code)) {
      this.taeiPage();
      return;
    }
    const special = Db.isSpecial(code);
    const color = Ui.unitColor(code);
    const u = db.unit(code);
    const day = Ui.toInt(u.get("admit_day"), 0);
    const head = db.unitHead(code);
    this.subtitle = (day === 0 ? "Admits every day" : "Admits every " + Dates.DAYS[day]) + (head.isEmpty() ? "" : "  ·  " + head);
    this.headerAction("+ Admit", this.opener(FormActivity, "kind", "patient", "unit", code));
    const page = Ui.v(this);
    // the unit's or ward's team first, with their photos (9.00)
    page.addView(People.board(this, db, code));
    const mbbs = Posting.unitCard(this, db, code);
    if (mbbs != null) page.addView(mbbs);

    // Census
    const census = Ui.card(this);
    census.setBackground(Glass.hero(this, Ui.shades(color), 20));
    const m = db.census(code, "M"), f = db.census(code, "F");
    let row;
    if (Db.IMCU.equals(code)) {
      const inn = db.rows("SELECT * FROM patients WHERE status='IN' AND location='IMCU'");
      let tox = 0, non = 0, vent = 0;
      for (const p of inn) {
        const w = Db.imcuWing(p);
        if (w.equals(Db.TOX)) tox++;
        if (w.equals(Db.NONTOX)) non++;
        if ("1".equals(p.get("vent"))) vent++;
      }
      row = Ui.statRow(this, this.whiteStat(tox + "/" + Db.TOX_BEDS, "Toxicology"), this.whiteStat(non + "/" + Db.NONTOX_BEDS, "Non-toxicology"),
          this.whiteStat(String(vent), "Ventilator"));
    } else if (Db.FEVER.equals(code)) {
      const dengue = db.num("SELECT COUNT(*) FROM patients WHERE status='IN' AND location='FEVER' AND dengue='1'");
      row = Ui.statRow(this, this.whiteStat(String(m + f), "In ward"), this.whiteStat(String(dengue), "Dengue +"),
          this.whiteStat(String(m), "Male"), this.whiteStat(String(f), "Female"));
    } else if (special) {
      row = Ui.statRow(this, this.whiteStat(String(m + f), Db.CCB.equals(code) ? "of 12 beds" : "In ward"),
          this.whiteStat(String(m), "Male"), this.whiteStat(String(f), "Female"));
    } else {
      row = Ui.statRow(this, this.whiteStat(String(m), "Male ward"), this.whiteStat(String(f), "Female ward"),
          this.whiteStat(String(db.awayFrom(code)), "In special wards"));
    }
    census.addView(row);
    if (Db.IMCU.equals(code)) census.addView(Ui.tv(this, (m + f) + " in IMCU (25 beds)  ·  male " + m + ", female " + f, 12, 0xD9FFFFFF, false));
    else if (!Db.CCB.equals(code)) census.addView(Ui.tv(this, special ? "Typical load ~" + db.capacity(code) : "Typical census: male ~" + u.get("male_cap") + ", female ~" + u.get("female_cap"), 12, 0xD9FFFFFF, false));
    const pend = Tasks.inWard(db, code);
    const bb = Ui.outlineButton(this, "Bed board" + (pend > 0 ? "   ·   ⏳ " + pend + " pending tasks" : ""), Color.WHITE, this.opener(BedBoardActivity, "code", code));
    bb.setBackground(Glass.frost(this, 14));
    census.addView(bb);
    Ui.margins(bb, 0, 10, 0, 0);
    page.addView(census);

    if (Db.CCB.equals(code)) {
      this.ccbDuty(page);
      this.bedBoard(page);
    }
    if (Db.TAEI.equals(code)) page.addView(CallOverActivity.taeiCard(this, db));
    if (Db.IDW.equals(code) || (Db.isWardUnit(code) && code.equals(db.rotationUnit()))) page.addView(UnitActivity.rotationCard(this, db));
    if (Db.IMCU.equals(code)) {
      this.imcuSpecial(page);
      this.imcuWings(page);
    }

    // This month
    const t = Dates.today();
    const m0 = Dates.monthStart(t).toString(), m1 = t.toString();
    page.addView(Ui.heading(this, Dates.month(t) + " so far", color));
    const month = Ui.card(this);
    month.addView(Ui.statRow(this,
        Ui.stat(this, String(db.events(Db.ADMIT, m0, m1, Db.isWardUnit(code) ? "from_loc" : "to_loc", code)), "Admitted", color),
        Ui.stat(this, String(db.transfers(m0, m1, null, code)), "Transfer in", Ui.ORANGE),
        Ui.stat(this, String(db.transfers(m0, m1, code, null)), "Transfer out", Ui.AMBER),
        Ui.stat(this, String(db.events(Db.DISCHARGE, m0, m1, "from_loc", code)), "Discharged", Ui.GREEN),
        Ui.stat(this, String(db.events(Db.DEATH, m0, m1, "from_loc", code)), "Deaths", Ui.SLATE)));
    page.addView(month);

    if (Db.isWardUnit(code)) this.callOverCard(page);
    this.staffCard(page);

    if (Db.IMCU.equals(code)) {
      // the wing lists above replace the male / female lists
    } else if (Db.FEVER.equals(code)) {
      this.feverSections(page);
    } else if (Db.IDW.equals(code)) {
      for (const dz of Db.ID_DISEASES) {
        const rows = db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND id_disease=? ORDER BY admit_date DESC", code, dz);
        if (!rows.isEmpty()) this.list(page, dz, rows);
      }
      const other = db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND IFNULL(id_disease,'') NOT IN ("
          + "'Acute diarrhoeal disease','Acute gastroenteritis','Acute brain stem encephalitis','Rabies','Tetanus','Chicken pox') ORDER BY admit_date DESC", code);
      if (!other.isEmpty()) this.list(page, "Disease not set", other);
      if (db.census(code, null) === 0) page.addView(this.emptyNote("No patients in the ID ward now"));
    } else if (Db.TAEI.equals(code) || Db.TRIAGE.equals(code) || Db.STEPDOWN.equals(code)) {
      // each case belongs to its admitting unit
      for (const wu of Db.WARD_UNITS) {
        const rows = db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND home_unit=? ORDER BY CAST(bed AS INTEGER), admit_date DESC", code, wu);
        if (!rows.isEmpty()) this.list(page, "Under " + wu + " unit", rows);
      }
      const rest = db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND home_unit NOT IN ('M1','M2','M3','M4','M5','M6','M7') ORDER BY admit_date DESC", code);
      if (!rest.isEmpty()) this.list(page, "Admitting unit not set", rest);
      if (db.census(code, null) === 0) page.addView(this.emptyNote("No patients here now"));
    } else if (special) {
      this.list(page, "Male patients", db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND sex='M' ORDER BY CAST(bed AS INTEGER), admit_date DESC", code));
      this.list(page, "Female patients", db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND sex='F' ORDER BY CAST(bed AS INTEGER), admit_date DESC", code));
    } else {
      const gen = " AND IFNULL(category,'') NOT IN ('Hemophilia','Stroke')";
      this.list(page, "Male ward", db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND sex='M'" + gen + " ORDER BY CAST(bed AS INTEGER), admit_date DESC", code));
      this.list(page, "Female ward", db.rows("SELECT * FROM patients WHERE status='IN' AND location=? AND sex='F'" + gen + " ORDER BY CAST(bed AS INTEGER), admit_date DESC", code));
      this.groupList(page, Db.HEMOPHILIA, code);
      this.groupList(page, Db.STROKE, code);
      // convict cases of this unit: admitted on its day, then in its ward while it holds the convict ward
      this.list(page, "Convict cases (admitted by " + code + " or in its ward)", db.rows("SELECT * FROM patients WHERE status='IN' AND convict='1' AND (location=? OR home_unit=? "
          + "OR id IN (SELECT patient_id FROM events WHERE type='ADMIT' AND from_loc=?)) ORDER BY admit_date DESC", code, code, code));
      this.list(page, "Unit's patients in triage, step-down, IMCU, fever, CCB and other wards", db.rows("SELECT * FROM patients WHERE status='IN' AND location IN " + Db.SPECIAL_SQL + " AND home_unit=? ORDER BY admit_date DESC", code));
    }
    this.list(page, "Recently discharged or died", db.rows(
        "SELECT * FROM patients WHERE status<>'IN' AND id IN (SELECT patient_id FROM events WHERE type IN ('DISCHARGE','DEATH') AND from_loc=?) ORDER BY outcome_date DESC, id DESC LIMIT 20", code));
    this.setPage(page);
  }

  /**
   * The TAEI ward is under another department: medicine admits no one there. Medicine gives opinions on call over and
   * receives its patients into the Critical Care Block or the triage ward (commonly) or IMCU (rarely), under the day's unit.
   */
  taeiPage() {
    const db = this.db, code = this.code;
    const color = Ui.unitColor(code);
    this.subtitle = "Another department's ward  ·  medicine call over";
    this.headerAction("+ Receive", this.opener(FormActivity, "kind", "patient", "from_taei", "1"));
    const page = Ui.v(this);
    const today = Dates.admitDay().toString(), now = Dates.todayIso();
    const m0 = Dates.monthStart(Dates.today()).toString();

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(color), 20));
    hero.addView(Ui.statRow(this, this.whiteStat(String(db.fromTaei(today, now).size()), "Received today"),
        this.whiteStat(String(db.fromTaei(m0, now).size()), "This month"),
        this.whiteStat(String(db.num("SELECT COUNT(*) FROM callover WHERE dept=? AND status IN ('Pending','Follow-up')", Db.TAEI_DEPT)), "Opinions open")));
    hero.addView(Ui.tv(this, "Medicine does not admit patients in the TAEI ward. Its patients come to us in the Critical Care Block or the triage ward, rarely IMCU.", 12, 0xD9FFFFFF, false));
    page.addView(hero);

    // receive: one button per receiving ward, the admitting unit is the day's unit
    page.addView(Ui.heading(this, "Receive a patient from TAEI  ·  " + db.todaysUnit() + " unit today", color));
    const rc = Ui.card(this);
    const notes = ["Common", "Common", "Rarely"];
    for (let i = 0; i < Db.FROM_TAEI.length; i++) {
      const w = Db.FROM_TAEI[i];
      const b = i === 0 ? Ui.button(this, "To " + Db.unitName(w) + "  ·  " + notes[i], Ui.unitColor(w), this.opener(FormActivity, "kind", "patient", "from_taei", "1", "to", w))
          : Ui.outlineButton(this, "To " + Db.unitName(w) + "  ·  " + notes[i], Ui.unitColor(w), this.opener(FormActivity, "kind", "patient", "from_taei", "1", "to", w));
      rc.addView(b);
      if (i > 0) Ui.margins(b, 0, 8, 0, 0);
    }
    page.addView(rc);

    page.addView(Ui.heading(this, "Opinions (call over)", color));
    page.addView(CallOverActivity.taeiCard(this, db));

    page.addView(Ui.heading(this, Dates.month(Dates.today()) + ": received from TAEI", color));
    const month = Ui.card(this);
    month.addView(Ui.statRow(this,
        Ui.stat(this, String(db.fromTaeiInto(Db.CCB, m0, now)), "To CCB", Ui.unitColor(Db.CCB)),
        Ui.stat(this, String(db.fromTaeiInto(Db.TRIAGE, m0, now)), "To triage", Ui.unitColor(Db.TRIAGE)),
        Ui.stat(this, String(db.fromTaeiInto(Db.IMCU, m0, now)), "To IMCU", Ui.unitColor(Db.IMCU))));
    page.addView(month);

    // cases put in the TAEI ward by older versions of the app: move them where they really are
    const left = db.rows("SELECT * FROM patients WHERE status='IN' AND location=? ORDER BY admit_date DESC", code);
    if (!left.isEmpty()) {
      this.list(page, "Still shown in TAEI (open each and move to CCB, triage or IMCU)", left);
    }
    this.list(page, "Received from TAEI, last 7 days", db.fromTaei(Dates.today().minusDays(6).toString(), now));
    this.setPage(page);
  }

  whiteStat(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    const n = Ui.tv(this, v, 26, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 12, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    return l;
  }

  /** 12-bed grid for the Critical Care Block: tap a free bed to admit, an occupied bed to open the patient. */
  bedBoard(page) {
    const db = this.db;
    page.addView(Ui.heading(this, "Bed board", Ui.unitColor(Db.CCB)));
    const byBed = new JMap();
    const inn = db.rows("SELECT * FROM patients WHERE status='IN' AND location='CCB' ORDER BY id");
    for (const p of inn) byBed.put(p.get("bed").trim(), p);
    const card = Ui.card(this);
    card.setPadding(Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10));
    let row = null;
    for (let b = 1; b <= UnitActivity.CCB_BEDS; b++) {
      if ((b - 1) % 4 === 0) {
        row = Ui.h(this);
        card.addView(row);
      }
      const p = byBed.get(String(b));
      const bed = Ui.v(this);
      bed.setGravity(Gravity.CENTER);
      bed.setPadding(Ui.dp(this, 4), Ui.dp(this, 8), Ui.dp(this, 4), Ui.dp(this, 8));
      const col = p == null ? Ui.GREEN : ("F".equals(p.get("sex")) ? Ui.PINK : Ui.unitColor(Db.CCB));
      bed.setBackground(p == null ? Ui.outline(this, Ui.alpha(Ui.GREEN, 0x14), Ui.alpha(Ui.GREEN, 0x66), 12) : Ui.round(this, col, 12));
      const bl = Ui.tv(this, "Bed " + b, 12, p == null ? Ui.GREEN : Color.WHITE, true);
      bl.setGravity(Gravity.CENTER);
      bed.addView(bl, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
      const n = Ui.tv(this, p == null ? "Free" : p.get("name"), 11, p == null ? Ui.GREEN : Color.WHITE, false);
      n.setSingleLine(true);
      n.setEllipsize(TextUtils.TruncateAt.END);
      n.setGravity(Gravity.CENTER);
      bed.addView(n, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
      Ui.ripple(bed, 0x33000000);
      const bedNo = b;
      bed.setOnClickListener(p != null ? this.opener(PatientActivity, "id", p.get("id"))
          : this.opener(FormActivity, "kind", "patient", "unit", Db.CCB, "bed", String(bedNo)));
      const lp = Ui.weight(1);
      lp.setMargins(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
      row.addView(bed, lp);
    }
    let unbedded = 0;
    for (const p of inn) {
      const bn = Ui.toInt(p.get("bed"), 0);
      if (bn < 1 || bn > UnitActivity.CCB_BEDS) unbedded++;
    }
    if (unbedded > 0) card.addView(Ui.tv(this, unbedded + " patient(s) without a bed number 1–12; set it under Edit details.", 12, Ui.RED, false));
    page.addView(card);
  }

  callOverCard(page) {
    const db = this.db, code = this.code;
    page.addView(Ui.heading(this, "Call over", Ui.TEAL));
    const pend = db.rows("SELECT * FROM callover WHERE unit=? AND status IN ('Pending','Follow-up') ORDER BY date DESC, id DESC LIMIT 5", code);
    const card = Ui.card(this);
    const today = db.num("SELECT COUNT(*) FROM callover WHERE unit=? AND date=?", code, Dates.todayIso());
    card.addView(Ui.muted(this, today + " call over(s) today  ·  " + pend.size() + " open"));
    for (const c of pend) {
      const r = Ui.h(this);
      r.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
      const tx = Ui.v(this);
      tx.addView(Ui.tv(this, c.get("patient") + "  ·  " + c.get("dept"), 14, Ui.TEXT, true));
      tx.addView(Ui.muted(this, c.get("ward") + "  ·  " + c.get("reason")));
      r.addView(tx, Ui.weight(1));
      r.addView(Ui.softPill(this, c.get("status"), Ui.AMBER));
      Ui.ripple(r, Ui.alpha(Ui.TEAL, 0x1A));
      r.setOnClickListener(this.opener(FormActivity, "kind", "callover", "id", c.get("id")));
      card.addView(r);
    }
    const btns = Ui.buttonRow(this,
        Ui.outlineButton(this, "+ New call over", Ui.TEAL, this.opener(FormActivity, "kind", "callover", "unit", code)),
        Ui.outlineButton(this, "All call overs", Ui.TEAL, this.opener(CallOverActivity, "unit", code)));
    card.addView(btns);
    Ui.margins(btns, 0, 10, 0, 0);
    page.addView(card);
  }

  /** Hemophilia or stroke patients of this unit, kept out of the male / female ward lists. */
  groupList(page, group, code) {
    const rows = this.db.rows("SELECT * FROM patients WHERE status='IN' AND category=? AND (location=? OR (home_unit=? AND location IN " + Db.SPECIAL_SQL + ")) "
        + "ORDER BY admit_date DESC, id DESC", group, code, code);
    page.addView(Ui.section(this, group + "  ·  " + rows.size()));
    if (rows.isEmpty()) page.addView(this.emptyNote("No " + group.toLowerCase() + " patients in the unit"));
    for (const p of rows) page.addView(this.patientRow(p));
  }

  list(page, title, rows) {
    page.addView(Ui.section(this, title + "  ·  " + rows.size()));
    if (rows.isEmpty()) page.addView(this.emptyNote("None"));
    for (const p of rows) page.addView(this.patientRow(p));
  }

  /** The unit running the convict ward and the ID ward this month (M1 to M7 in turn), changeable by the admin. */
  static rotationCard(a, db) {
    const ym = YearMonth.from(Dates.today());
    const now = db.rotationUnit(ym), next = db.rotationUnit(ym.plusMonths(1));
    const card = Ui.card(a);
    card.addView(Ui.tv(a, "Convict ward & ID ward in-charge: " + now + " unit", 15, Ui.unitColor(now), true));
    card.addView(Ui.muted(a, Dates.month(Dates.today()) + "  ·  next month " + next + "  ·  one unit a month in turn, M1 to M7"));
    card.addView(Ui.muted(a, "Convict cases are admitted by the day's admitting unit and moved to the " + now + " ward the next day."));
    if (Cloud.isAdmin(a) || !Cloud.active(a)) {
      const ch = Ui.outlineButton(a, "Change this month's unit", Ui.PRIMARY, {
        onClick: (v) => {
          const f = new Form(a);
          f.choice("unit", "Unit in charge this month", Db.WARD_UNITS, Db.WARD_UNITS, db.rotationUnit(), null);
          Ui.formDialog(a, "Convict & ID ward rotation", f, "Save", {
            run: () => {
              db.setSetting(Db.ROTATION_KEY, YearMonth.from(Dates.today()) + ":" + f.get("unit"));
              a.render();
              return true;
            }
          });
        }
      });
      card.addView(ch);
      Ui.margins(ch, 0, 8, 0, 0);
    }
    return card;
  }

  staffCard(page) {
    const db = this.db, code = this.code;
    if (Db.IDW.equals(code)) {
      const u = db.rotationUnit();
      page.addView(Ui.heading(this, "ID ward team this month: " + u, Ui.PRIMARY));
      const card = Ui.card(this);
      card.addView(Ui.body(this, "The " + u + " unit's Professor, Assistant Professors, PGs and CRMIs look after the ID ward this month."));
      for (const s of db.rows("SELECT * FROM staff WHERE unit=? AND " + Db.NOT_STUDENT + " AND role IN ('Professor','Associate Professor','Assistant Professor','Postgraduate','CRMI') ORDER BY CASE role WHEN 'Professor' THEN 0 WHEN 'Associate Professor' THEN 1 WHEN 'Assistant Professor' THEN 2 WHEN 'Postgraduate' THEN 3 ELSE 4 END, id", u))
        card.addView(this.staffRow(s));
      page.addView(card);
      return;
    }
    if (Db.underUnit(code)) {
      // no separate chief or Assistant Professor: the admitting unit's faculty look after their own cases
      const ownTeam = Db.FEVER.equals(code);
      page.addView(Ui.heading(this, ownTeam ? "Ward PGs & CRMIs" : "Who looks after these cases", Ui.PRIMARY));
      const card = Ui.card(this);
      card.addView(Ui.body(this, ownTeam
          ? "The fever ward has its own PGs and CRMIs. There is no separate Professor or Assistant Professor: each case is under the Professor and Assistant Professor of the unit that admitted it."
          : Db.STEPDOWN.equals(code) ? "Cases stay here for a short time and are completely under their admitting unit (Professor, Assistant Professor, PGs and CRMIs). No separate chief or Assistant Professor."
          : Db.TAEI.equals(code) ? "Medicine cases here are seen on call over: the admitting unit's PGs and Assistant Professor 9 AM to 2 PM, the DAP 2 PM to 7:30 AM. From here cases go to the Critical Care Block or the triage ward."
          : "Each case is under its admitting unit's team. From triage, cases go to the step-down ward, fever ward or IMCU."));
      if (ownTeam) {
        for (const s of db.rows("SELECT * FROM staff WHERE unit=? AND " + Db.NOT_STUDENT + " AND role NOT IN ('Professor','Assistant Professor','Associate Professor') ORDER BY role, id", code))
          card.addView(this.staffRow(s));
        const add = Ui.outlineButton(this, "+ Add PG or CRMI", Ui.PRIMARY, {
          onClick: (v) => {
            StaffActivity.editDialog(this, null, code, { run: () => { this.render(); } });
          }
        });
        card.addView(add);
        Ui.margins(add, 0, 12, 0, 0);
      }
      page.addView(card);
      return;
    }
    const special = Db.isSpecial(code);
    page.addView(Ui.heading(this, special ? "In-charge & duty team" : "Unit team", Ui.PRIMARY));
    const card = Ui.card(this);
    for (let r = 0; r < 4; r++) {
      const role = Db.ROLES[r];
      const staff = db.rows("SELECT * FROM staff WHERE unit=? AND role=? AND " + Approvals.APPROVED_SQL + " ORDER BY id", code, role);
      if (special && r > 1) continue;
      const head = Ui.h(this);
      const label = special && r < 2 ? role + " in-charge" : role + (r === 0 ? "" : "s");
      head.addView(Ui.tv(this, label, 14, Ui.PRIMARY, true), Ui.weight(1));
      if (!special) head.addView(Ui.muted(this, staff.size() + " / " + Db.ROLE_STRENGTH[r]));
      card.addView(head);
      if (r > 0) Ui.margins(head, 0, 10, 0, 0);
      for (const s of staff) card.addView(this.staffRow(s));
      if (staff.isEmpty()) card.addView(Ui.muted(this, "Not added yet"));
    }
    const others = db.rows("SELECT * FROM staff WHERE unit=? AND " + Db.NOT_STUDENT + " AND role NOT IN ('Professor','Assistant Professor'" + (special ? "" : ",'Postgraduate','CRMI'") + ") ORDER BY role, id", code);
    if (!others.isEmpty()) {
      const h = Ui.tv(this, special ? "On duty (PGs, CRMIs, nurses)" : "Others", 14, Ui.PRIMARY, true);
      card.addView(h);
      Ui.margins(h, 0, 10, 0, 0);
      for (const s of others) card.addView(this.staffRow(s));
    }
    const add = Ui.outlineButton(this, "+ Add team member", Ui.PRIMARY, {
      onClick: (v) => {
        StaffActivity.editDialog(this, null, code, { run: () => { this.render(); } });
      }
    });
    card.addView(add);
    Ui.margins(add, 0, 12, 0, 0);
    page.addView(card);
  }

  // ---------- Critical Care Block duty ----------

  static CCB_SLOTS = [
    ["prof", "Professor in-charge", "9 AM to 2 PM"], ["ap", "Assistant Professor", "9 AM to 2 PM"],
    ["day_pg", "PG, day shift", "7:30 AM to 7:30 PM"], ["day_crmi", "CRMI, day shift", "7:30 AM to 7:30 PM"],
    ["night_pg", "PG, night shift", "7:30 PM to 7:30 AM"], ["night_crmi", "CRMI, night shift", "7:30 PM to 7:30 AM"]];

  /** Which CCB slots are on duty at this hour. */
  static ccbOnNow(slot) {
    const t = Dates.time();
    if (slot.equals("prof") || slot.equals("ap")) return !t.isBefore(LocalTime.of(9, 0)) && t.isBefore(LocalTime.of(14, 0));
    const day = !t.isBefore(Dates.CHANGEOVER) && t.isBefore(LocalTime.of(19, 30));
    return slot.startsWith("day") === day;
  }

  ccbDuty(page) {
    const db = this.db;
    const iso = Dates.admitDay().toString();
    const r = db.row("SELECT * FROM ccb_duty WHERE date=? ORDER BY id DESC LIMIT 1", iso);
    page.addView(Ui.heading(this, "CCB duty today", Ui.unitColor(Db.CCB)));
    const card = Ui.card(this);
    card.addView(Ui.muted(this, "Faculty 9 AM to 2 PM  ·  PGs and CRMIs in 12-hour shifts: 7:30 AM to 7:30 PM and 7:30 PM to 7:30 AM"));
    for (const s of UnitActivity.CCB_SLOTS) {
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
      const t = Ui.v(this);
      const name = r == null ? "" : Ui.nz(r.get(s[0]));
      t.addView(Ui.tv(this, name.isEmpty() ? "Not set" : name, 14, name.isEmpty() ? Ui.MUTED : Ui.TEXT, true));
      t.addView(Ui.muted(this, s[1] + "  ·  " + s[2]));
      row.addView(t, Ui.weight(1));
      if (UnitActivity.ccbOnNow(s[0])) row.addView(Ui.softPill(this, "On duty now", Ui.GREEN));
      card.addView(row);
    }
    if (SessionAttendance.canRun(this) || Cloud.isAdmin(this)) {
      const edit = Ui.outlineButton(this, r == null ? "+ Set today's CCB duty" : "Edit today's CCB duty", Ui.unitColor(Db.CCB), {
        onClick: (v) => { this.ccbDutyDialog(iso); }
      });
      card.addView(edit);
      Ui.margins(edit, 0, 8, 0, 0);
    }
    page.addView(card);
  }

  ccbDutyDialog(iso) {
    const db = this.db;
    const r = db.row("SELECT * FROM ccb_duty WHERE date=? ORDER BY id DESC LIMIT 1", iso);
    const prev = r != null ? r : db.row("SELECT * FROM ccb_duty WHERE date<? ORDER BY date DESC, id DESC LIMIT 1", iso);
    const f = new Form(this);
    const fac = db.staffNames("AND role IN ('Professor','Associate Professor','Assistant Professor')");
    const juniors = db.staffNames("AND role IN ('Postgraduate','CRMI')");
    for (const s of UnitActivity.CCB_SLOTS) {
      const val = prev == null ? "" : Ui.nz(prev.get(s[0]));
      if (s[0].equals("prof") || s[0].equals("ap")) f.suggest(s[0], s[1] + " (" + s[2] + ")", val, fac);
      else f.suggest(s[0], s[1] + " (" + s[2] + ")", r == null ? "" : val, juniors);
    }
    Ui.formDialog(this, "CCB duty, " + Dates.nice(iso), f, "Save", {
      run: () => {
        const cv = new ContentValues();
        cv.put("date", iso);
        for (const s of UnitActivity.CCB_SLOTS) cv.put(s[0], f.get(s[0]).trim());
        cv.put("by_name", CallDutyActivity.myName(this));
        if (r == null) db.insert("ccb_duty", cv);
        else db.update("ccb_duty", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  staffRow(s) {
    const row = Ui.h(this);
    row.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    const t = Ui.v(this);
    t.addView(Ui.body(this, s.get("name")));
    if (Db.isSpecial(this.code)) t.addView(Ui.muted(this, s.get("role")));
    row.addView(t, Ui.weight(1));
    if (!s.get("phone").isEmpty()) {
      const call = Ui.softPill(this, "Call", Ui.GREEN);
      call.setOnClickListener({
        onClick: (v) => { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + s.get("phone")))); }
      });
      row.addView(call);
      if (WhatsApp.usable(s.get("phone"))) {
        const wa = WhatsApp.pill(this, s.get("phone"));
        row.addView(wa);
        Ui.margins(wa, 6, 0, 0, 0);
      }
    }
    Ui.ripple(row, Ui.alpha(Ui.PRIMARY, 0x1A));
    row.setOnClickListener({
      onClick: (v) => {
        StaffActivity.editDialog(this, s, this.code, { run: () => { this.render(); } });
      }
    });
    return row;
  }

  // ---------- IMCU: toxicology (13 beds) and non-toxicology (12 beds) ----------

  imcuWings(page) {
    const db = this.db;
    const color = Ui.unitColor(Db.IMCU);
    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const labels = ["Toxicology · 13 beds", "Non-toxicology · 12 beds"];
    for (let i = 0; i < 2; i++) {
      const idx = i;
      const t = Ui.tv(this, labels[i], 14, i === this.wingTab ? color : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 9), 0, Ui.dp(this, 9));
      if (i === this.wingTab) t.setBackground(Ui.round(this, 0xFFFFFFFF, 11));
      t.setOnClickListener({
        onClick: (v) => { this.wingTab = idx; this.render(); }
      });
      seg.addView(t, Ui.weight(1));
    }
    page.addView(seg);
    Ui.margins(seg, 12, 14, 12, 4);

    const wing = this.wingTab === 0 ? Db.TOX : Db.NONTOX;
    const beds = this.wingTab === 0 ? Db.TOX_BEDS : Db.NONTOX_BEDS;
    const prefix = this.wingTab === 0 ? "T" : "N";
    const all = db.rows("SELECT * FROM patients WHERE status='IN' AND location='IMCU' ORDER BY admit_date DESC, id DESC");
    const inWing = [], unassigned = [];
    for (const p of all) {
      const w = Db.imcuWing(p);
      if (w.equals(wing)) inWing.add(p);
      else if (w.isEmpty()) unassigned.add(p);
    }

    // bed board
    const byBed = new JMap();
    for (const p of inWing) byBed.put(UnitActivity.bedNo(p.get("bed")), p);
    const card = Ui.card(this);
    card.setPadding(Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10), Ui.dp(this, 10));
    let row = null;
    for (let b = 1; b <= beds; b++) {
      if ((b - 1) % 4 === 0) {
        row = Ui.h(this);
        card.addView(row);
      }
      const p = byBed.get(String(b));
      const vent = p != null && "1".equals(p.get("vent"));
      const bed = Ui.v(this);
      bed.setGravity(Gravity.CENTER);
      bed.setPadding(Ui.dp(this, 4), Ui.dp(this, 7), Ui.dp(this, 4), Ui.dp(this, 7));
      const col = p == null ? Ui.GREEN : vent ? Ui.RED : color;
      bed.setBackground(p == null ? Ui.outline(this, Ui.alpha(Ui.GREEN, 0x14), Ui.alpha(Ui.GREEN, 0x66), 12) : Ui.round(this, col, 12));
      const bl = Ui.tv(this, prefix + b + (vent ? " · Vent" : ""), 12, p == null ? Ui.GREEN : Color.WHITE, true);
      bl.setGravity(Gravity.CENTER);
      bed.addView(bl, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
      const n = Ui.tv(this, p == null ? "Free" : p.get("name"), 11, p == null ? Ui.GREEN : Color.WHITE, false);
      n.setSingleLine(true);
      n.setEllipsize(TextUtils.TruncateAt.END);
      n.setGravity(Gravity.CENTER);
      bed.addView(n, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
      if (p != null && this.wingTab === 0 && !Ui.nz(p.get("tox_kind")).isEmpty()) {
        const k = Ui.tv(this, p.get("tox_kind"), 10, 0xE6FFFFFF, false);
        k.setGravity(Gravity.CENTER);
        bed.addView(k, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
      }
      Ui.ripple(bed, 0x33000000);
      const bedNo = b;
      bed.setOnClickListener(p != null ? this.opener(PatientActivity, "id", p.get("id"))
          : this.opener(FormActivity, "kind", "patient", "unit", Db.IMCU, "bed", prefix + bedNo));
      const lp = Ui.weight(1);
      lp.setMargins(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
      row.addView(bed, lp);
    }
    if (beds % 4 !== 0) for (let i = beds % 4; i < 4; i++) {
      const spacer = new View(this);
      const lp = Ui.weight(1);
      lp.setMargins(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
      row.addView(spacer, lp);
    }
    card.addView(Ui.muted(this, "Tap a free bed to admit. Red beds are on a ventilator."));
    page.addView(card);

    // sub-sections
    const filters = this.wingTab === 0 ? ["All", "Poisoning", "Rat killer", "Snake bite", "Unknown bite", "Ventilator"] : ["All", "Ventilator"];
    const cur = this.wingTab === 0 ? this.toxFilter : this.nonFilter;
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    for (let i = 0; i < filters.length; i++) {
      const idx = i;
      let n = 0;
      for (const p of inWing) if (UnitActivity.matches(p, filters[i])) n++;
      const c = Ui.chip(this, filters[i] + "  " + n, i === cur, filters[i].equals("Ventilator") ? Ui.RED : color);
      c.setOnClickListener({
        onClick: (v) => {
          if (this.wingTab === 0) this.toxFilter = idx; else this.nonFilter = idx;
          this.render();
        }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));
    let shown = 0;
    for (const p of inWing) {
      if (!UnitActivity.matches(p, filters[cur])) continue;
      page.addView(this.patientRow(p));
      page.addView(this.imcuTags(p));
      shown++;
    }
    if (shown === 0) page.addView(this.emptyNote("No patients here."));

    if (!unassigned.isEmpty()) {
      page.addView(Ui.section(this, "In IMCU, wing not set  ·  " + unassigned.size()));
      for (const p of unassigned) {
        page.addView(this.patientRow(p));
        page.addView(this.imcuTags(p));
      }
    }
  }

  /** Three tiles opening the rat killer poisoning, snake bite and PLEX therapy registers. */
  imcuSpecial(page) {
    const db = this.db;
    const row = Ui.h(this);
    const rk = db.num("SELECT COUNT(*) FROM patients WHERE status='IN' AND " + Db.RAT_SQL);
    const sb = db.num("SELECT COUNT(*) FROM patients WHERE status='IN' AND " + Db.SNAKE_SQL);
    const px = db.num("SELECT COUNT(DISTINCT x.patient_id) FROM plex x JOIN patients p ON p.id=x.patient_id WHERE p.status='IN'");
    row.addView(this.specialTile("Rat killer", rk + " in hospital", ImcuSpecialActivity.RK_COLOR, R.drawable.ic_warn, "0"));
    row.addView(this.specialTile("Snake bite", sb + " in hospital", ImcuSpecialActivity.SB_COLOR, R.drawable.ic_snake, "2"));
    row.addView(this.specialTile("PLEX therapy", px + " on PLEX now", ImcuSpecialActivity.PLEX_COLOR, R.drawable.ic_drop, "1"));
    page.addView(row);
    Ui.margins(row, 8, 12, 8, 0);
  }

  specialTile(title, sub, color, glyph, tab) {
    const t = Ui.v(this);
    t.setGravity(Gravity.CENTER_HORIZONTAL);
    t.setPadding(Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 6), Ui.dp(this, 10));
    t.setBackground(Glass.hero(this, Ui.shades(color), 16));
    t.addView(Slab.orb(this, color, glyph, 38));
    const h = Ui.tv(this, title, 13, Color.WHITE, true);
    h.setGravity(Gravity.CENTER);
    h.setSingleLine(true);
    h.setPadding(0, Ui.dp(this, 4), 0, 0);
    t.addView(h, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
    const st = Ui.tv(this, sub, 11, 0xD9FFFFFF, false);
    st.setGravity(Gravity.CENTER);
    st.setSingleLine(true);
    t.addView(st, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
    Slab.pressable(t, 3);
    t.setOnClickListener(this.opener(ImcuSpecialActivity, "tab", tab));
    const lp = Ui.weight(1);
    lp.setMargins(Ui.dp(this, 4), 0, Ui.dp(this, 4), 0);
    t.setLayoutParams(lp);
    return t;
  }

  static bedNo(bed) {
    return Ui.nz(bed).trim().replaceAllRx("[^0-9]", "");
  }

  static matches(p, filter) {
    if (filter.equals("All")) return true;
    if (filter.equals("Ventilator")) return "1".equals(p.get("vent"));
    if (filter.equals("Rat killer")) return Db.isRatKiller(p);
    if (filter.equals("Snake bite")) return Db.isSnakeBite(p);
    return filter.equals(p.get("tox_kind"));
  }

  /** Wing, poisoning / bite type and ventilator under each IMCU patient, with a button to change them. */
  imcuTags(p) {
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(Ui.dp(this, 26), 0, Ui.dp(this, 14), Ui.dp(this, 6));
    const w = Db.imcuWing(p);
    if (!w.isEmpty()) row.addView(Ui.softPill(this, w.equals(Db.TOX) ? "Toxicology" : "Non-toxicology", Ui.unitColor(Db.IMCU)));
    if (w.equals(Db.TOX) && !Ui.nz(p.get("tox_kind")).isEmpty()) UnitActivity.addTag(row, Ui.softPill(this, p.get("tox_kind"), Ui.ORANGE));
    if ("1".equals(p.get("vent"))) UnitActivity.addTag(row, Ui.softPill(this, "Ventilator", Ui.RED));
    const gap = new View(this);
    row.addView(gap, new LinearLayoutParams(0, 1, 1));
    const set = Ui.pill(this, w.isEmpty() ? "Set wing / bed" : "Change", Ui.unitColor(Db.IMCU));
    set.setOnClickListener({
      onClick: (v) => { UnitActivity.imcuDialog(this, p, { run: () => { this.render(); } }); }
    });
    row.addView(set);
    return row;
  }

  static addTag(row, t) {
    row.addView(t);
    Ui.margins(t, 6, 0, 0, 0);
  }

  /** Sets a patient's IMCU wing, bed, poisoning / bite type and ventilator. */
  static imcuDialog(a, p, done) {
    const f = new Form(a);
    const w = Db.imcuWing(p);
    f.choice("wing", "IMCU wing", ["Toxicology (13 beds)", "Non-toxicology (12 beds)"], [Db.TOX, Db.NONTOX],
        w.isEmpty() ? Db.TOX : w, null);
    const beds = new Array(Db.TOX_BEDS + 1).fill(null);
    beds[0] = "";
    for (let i = 1; i <= Db.TOX_BEDS; i++) beds[i] = String(i);
    const bedLabels = beds.slice();
    bedLabels[0] = "Not set";
    f.choice("bed", "Bed number", bedLabels, beds, UnitActivity.bedNo(p.get("bed")), null);
    f.choice("tox_kind", "Toxicology: type", ["Not set", "Poisoning", "Rat killer", "Snake bite", "Unknown bite", "Scorpion sting", "Other bite / sting", "Drowning", "Hanging"],
        ["", "Poisoning", Db.RAT_KILLER, "Snake bite", "Unknown bite", "Scorpion sting", "Other bite / sting", "Drowning", "Hanging"], Ui.nz(p.get("tox_kind")), null);
    f.check("vent", "On ventilator", "1".equals(p.get("vent")));
    Ui.formDialog(a, "IMCU · " + p.get("name"), f, "Save", {
      run: () => {
        const wing = f.get("wing");
        const bed = f.get("bed");
        if (wing.equals(Db.NONTOX) && Ui.toInt(bed, 0) > Db.NONTOX_BEDS) {
          Ui.toast(a, "Non-toxicology has beds 1 to " + Db.NONTOX_BEDS);
          return false;
        }
        const bedCode = bed.isEmpty() ? "" : (wing.equals(Db.TOX) ? "T" : "N") + bed;
        if (!bedCode.isEmpty()) {
          for (const o of a.db.rows("SELECT id, name, bed, imcu_wing FROM patients WHERE status='IN' AND location='IMCU' AND id<>?", p.get("id")))
            if (bedCode.equalsIgnoreCase(Ui.nz(o.get("bed")).trim())) {
              Ui.toast(a, "Bed " + bedCode + " has " + o.get("name"));
              return false;
            }
        }
        const cv = new ContentValues();
        cv.put("imcu_wing", wing);
        cv.put("bed", bedCode);
        if (wing.equals(Db.TOX)) cv.put("tox_kind", f.get("tox_kind"));
        cv.put("vent", f.get("vent"));
        a.db.update("patients", cv, Long.parseLong(p.get("id")));
        run(done);
        return true;
      }
    });
  }

  // ---------- Fever ward: dengue positive cases ----------

  feverSections(page) {
    const db = this.db;
    const color = Ui.unitColor(Db.FEVER);
    const all = db.rows("SELECT * FROM patients WHERE status='IN' AND location='FEVER' ORDER BY CAST(bed AS INTEGER), admit_date DESC, id DESC");
    const dengue = [];
    for (const p of all) if (Db.isDengue(p)) dengue.add(p);

    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const labels = ["All fever cases · " + all.size(), "Dengue positive · " + dengue.size()];
    for (let i = 0; i < 2; i++) {
      const idx = i;
      const t = Ui.tv(this, labels[i], 14, i === this.feverTab ? (i === 1 ? Ui.RED : color) : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 9), 0, Ui.dp(this, 9));
      if (i === this.feverTab) t.setBackground(Ui.round(this, 0xFFFFFFFF, 11));
      t.setOnClickListener({
        onClick: (v) => { this.feverTab = idx; this.render(); }
      });
      seg.addView(t, Ui.weight(1));
    }
    page.addView(seg);
    Ui.margins(seg, 12, 14, 12, 4);

    if (this.feverTab === 0) {
      this.feverList(page, "Male patients", all, "M");
      this.feverList(page, "Female patients", all, "F");
      return;
    }

    // dengue positive: summary, severity filters, list
    let warn = 0, severe = 0, lowPlt = 0;
    for (const p of dengue) {
      if (Db.DENGUE_GRADES[1].equals(p.get("dengue_grade"))) warn++;
      if (Db.DENGUE_GRADES[2].equals(p.get("dengue_grade"))) severe++;
      if (UnitActivity.plateletLow(p.get("platelet"))) lowPlt++;
    }
    const sum = Ui.card(this);
    sum.addView(Ui.statRow(this, Ui.stat(this, String(dengue.size()), "Dengue +", Ui.RED),
        Ui.stat(this, String(warn), "Warning signs", Ui.ORANGE),
        Ui.stat(this, String(severe), "Severe", Ui.RED),
        Ui.stat(this, String(lowPlt), "Platelet < 50k", Ui.AMBER)));
    page.addView(sum);

    const filters = ["All", "Without warning signs", "With warning signs", "Severe dengue", "Platelet < 50k"];
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    for (let i = 0; i < filters.length; i++) {
      const idx = i;
      let n = 0;
      for (const p of dengue) if (UnitActivity.dengueMatches(p, filters[i])) n++;
      const c = Ui.chip(this, filters[i] + "  " + n, i === this.dengueFilter, i === 0 ? color : i === 1 ? Ui.GREEN : i === 2 ? Ui.ORANGE : Ui.RED);
      c.setOnClickListener({
        onClick: (v) => { this.dengueFilter = idx; this.render(); }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));
    let shown = 0;
    for (const p of dengue) {
      if (!UnitActivity.dengueMatches(p, filters[this.dengueFilter])) continue;
      page.addView(this.patientRow(p, this.dengueTags(p), this.dengueButton(p)));
      shown++;
    }
    if (shown === 0) page.addView(this.emptyNote(dengue.isEmpty() ? "No dengue positive cases. Mark a patient from the All fever cases tab." : "No patients here."));
  }

  feverList(page, title, all, sex) {
    let n = 0;
    for (const p of all) if (sex.equals(p.get("sex"))) n++;
    page.addView(Ui.section(this, title + "  ·  " + n));
    if (n === 0) page.addView(this.emptyNote("None"));
    for (const p of all) {
      if (!sex.equals(p.get("sex"))) continue;
      page.addView(this.patientRow(p, this.dengueTags(p), this.dengueButton(p)));
    }
  }

  static plateletLow(plt) {
    const v = UnitActivity.plateletValue(plt);
    return v > 0 && v < 50000;
  }

  /** Platelet count as entered: 45000, 45,000, 45k or 0.45 lakh. */
  static plateletValue(plt) {
    const s = Ui.nz(plt).toLowerCase().split(",").join("").trim();
    try {
      if (s.contains("lakh") || s.contains("lac")) return toInt(Math.round(Double.parseDouble(s.replaceAllRx("[^0-9.]", "")) * 100000));
      if (s.endsWith("k")) return toInt(Math.round(Double.parseDouble(s.replaceAllRx("[^0-9.]", "")) * 1000));
      const d = Double.parseDouble(s.replaceAllRx("[^0-9.]", ""));
      return toInt(Math.round(d < 1000 ? d * 1000 : d));
    } catch (e) {
      return 0;
    }
  }

  /** 38000 → 38k, 120000 → 1.2L; anything unreadable is shown as entered. */
  static plateletShort(plt) {
    const v = UnitActivity.plateletValue(plt);
    if (v <= 0) return Ui.nz(plt);
    if (v >= 100000) return new DecimalFormat("0.##").format(v / 100000.0) + "L";
    return new DecimalFormat("0.#").format(v / 1000.0) + "k";
  }

  static dengueMatches(p, filter) {
    if (filter.equals("All")) return true;
    if (filter.equals("Platelet < 50k")) return UnitActivity.plateletLow(p.get("platelet"));
    return filter.equals(p.get("dengue_grade"));
  }

  /** Dengue status under each fever ward patient, with a button to mark or update it. */
  /** Dengue status inside each fever ward patient's card (10.39), or null when not marked. */
  dengueTags(p) {
    if (!Db.isDengue(p)) return null;
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 6), 0, 0);
    const test = Ui.nz(p.get("dengue_test"));
    row.addView(Ui.softPill(this, "Dengue +" + (test.isEmpty() ? "" : " · " + test), Ui.RED));
    const g = Ui.nz(p.get("dengue_grade"));
    if (!g.isEmpty()) UnitActivity.addTag(row, Ui.softPill(this, g.equals(Db.DENGUE_GRADES[0]) ? "No warning signs" : g.equals(Db.DENGUE_GRADES[1]) ? "Warning signs" : "Severe", g.equals(Db.DENGUE_GRADES[0]) ? Ui.GREEN : g.equals(Db.DENGUE_GRADES[1]) ? Ui.ORANGE : Ui.RED));
    if (!Ui.nz(p.get("platelet")).isEmpty()) UnitActivity.addTag(row, Ui.softPill(this, "Plt " + UnitActivity.plateletShort(p.get("platelet")), UnitActivity.plateletLow(p.get("platelet")) ? Ui.RED : Ui.SLATE));
    return Ui.hscroll(this, row);
  }

  /** "+ Mark dengue" (or "Edit dengue") at the bottom right of each fever ward card. */
  dengueButton(p) {
    const pos = Db.isDengue(p);
    return PatientRowDesign.action(this, pos ? "✎ Edit dengue" : "+  Mark dengue", pos ? Ui.unitColor(Db.FEVER) : 0xFFDC2626, {
      onClick: (v) => { UnitActivity.dengueDialog(this, p, { run: () => { this.render(); } }); }
    });
  }

  /** Marks a fever ward patient dengue positive (or not), with test, severity and latest platelet count. */
  static dengueDialog(a, p, done) {
    const f = new Form(a);
    const pos = Db.isDengue(p);
    f.check("dengue", "Dengue positive", pos || Ui.nz(p.get("dengue")).isEmpty());
    const tl = new Array(Db.DENGUE_TESTS.length + 1).fill(null), tv = new Array(Db.DENGUE_TESTS.length + 1).fill(null);
    tl[0] = "Not set";
    tv[0] = "";
    for (let i = 0; i < Db.DENGUE_TESTS.length; i++) tl[i + 1] = tv[i + 1] = Db.DENGUE_TESTS[i];
    f.choice("dengue_test", "Positive by", tl, tv, Ui.nz(p.get("dengue_test")), null);
    f.date("dengue_date", "Result date", Ui.nz(p.get("dengue_date")).isEmpty() ? Dates.todayIso() : p.get("dengue_date"));
    const gl = new Array(Db.DENGUE_GRADES.length + 1).fill(null), gv = new Array(Db.DENGUE_GRADES.length + 1).fill(null);
    gl[0] = "Not set";
    gv[0] = "";
    for (let i = 0; i < Db.DENGUE_GRADES.length; i++) gl[i + 1] = gv[i + 1] = Db.DENGUE_GRADES[i];
    f.choice("dengue_grade", "Severity (WHO)", gl, gv, Ui.nz(p.get("dengue_grade")), null);
    f.text("platelet", "Latest platelet count (e.g. 45000)", Ui.nz(p.get("platelet")), Form.TEXT);
    Ui.formDialog(a, "Dengue · " + p.get("name"), f, "Save", {
      run: () => {
        const cv = new ContentValues();
        const on = "1".equals(f.get("dengue"));
        cv.put("dengue", on ? "1" : "0");
        cv.put("dengue_test", on ? f.get("dengue_test") : "");
        cv.put("dengue_date", on ? f.get("dengue_date") : "");
        cv.put("dengue_grade", on ? f.get("dengue_grade") : "");
        cv.put("platelet", f.get("platelet"));
        a.db.update("patients", cv, Long.parseLong(p.get("id")));
        run(done);
        return true;
      }
    });
  }
}
;
