'use strict';
/**
 * Handing a case over to another medical unit (7.83). A case belongs to the unit admitting on that day, wherever it lies
 * (triage, IMCU, fever ward, CCB). It can go to another unit, for example when it was that unit's case in an earlier
 * admission, only after the receiving unit's PGs or Assistant Professor (or its Professors, the HOD or the admin) accept.
 */
class UnitMoves {
  constructor() {}

  static TABLE = "unit_moves";
  static WAIT = "wait";
  static OK = "ok";
  static NO = "no";
  static COLOR = 0xFF4F46E5;
  static REASONS = ["Was this unit's case in an earlier admission", "Specialty / unit's own follow-up case", "Other"];

  /** The receiving unit's PGs, Assistant / Associate Professors and Professors, the HOD and the admin may accept. */
  static canAccept(c, db, unit) {
    if (!Cloud.active(c)) return true;
    if (Cloud.isAdmin(c) || Chat.isHod(c, db)) return true;
    const me = Cloud.myStaff(c);
    if (me <= 0) return false;
    const s = db.row("SELECT unit, role FROM staff WHERE id=?", String(me));
    if (s == null) return false;
    const role = Ui.nz(s.get("role"));
    return (role.equals("Postgraduate") || role.endsWith("Professor")) && unit.equals(Ui.nz(s.get("unit")));
  }

  /** The open request for this patient, if any. */
  static open(db, pid) {
    return db.row("SELECT * FROM " + UnitMoves.TABLE + " WHERE patient_id=? AND status=? ORDER BY id DESC LIMIT 1", String(pid), UnitMoves.WAIT);
  }

  /** Requests this person may accept, for patients still in hospital. */
  static waitingForMe(c, db) {
    const out = [];
    for (const r of db.rows("SELECT m.*, p.name, p.age, p.sex, p.location, p.bed FROM " + UnitMoves.TABLE + " m JOIN patients p ON p.id=m.patient_id "
        + "WHERE m.status=? AND p.status=? ORDER BY m.id", UnitMoves.WAIT, Db.IN))
      if (UnitMoves.canAccept(c, db, Ui.nz(r.get("to_unit")))) out.add(r);
    return out;
  }

  /** Asks the receiving unit; when the asker may accept for that unit, the case moves at once. Returns true if it moved. */
  static request(c, db, p, toUnit, reason, prevAdm, note) {
    const cv = new ContentValues();
    cv.put("patient_id", p.get("id"));
    cv.put("from_unit", Ui.nz(p.get("home_unit")));
    cv.put("to_unit", toUnit);
    cv.put("reason", reason);
    cv.put("prev_adm", prevAdm);
    cv.put("note", note);
    cv.put("by_name", Chat.myName(c, db));
    cv.put("time", Chat.now());
    cv.put("status", UnitMoves.WAIT);
    const id = db.insert(UnitMoves.TABLE, cv);
    if (UnitMoves.canAccept(c, db, toUnit)) {
      UnitMoves.decide(c, db, String(id), true);
      return true;
    }
    return false;
  }

  /** Accept (the case moves: into the unit's ward if it was in a unit ward, else only its unit changes) or decline. */
  static decide(c, db, moveId, accept) {
    const m = db.row("SELECT * FROM " + UnitMoves.TABLE + " WHERE id=?", moveId);
    if (m == null) return;
    const cv = new ContentValues();
    cv.put("status", accept ? UnitMoves.OK : UnitMoves.NO);
    cv.put("decided_by", Chat.myName(c, db));
    cv.put("decided_time", Chat.now());
    db.update(UnitMoves.TABLE, cv, Long.parseLong(moveId));
    if (!accept) return;
    const pid = Long.parseLong(m.get("patient_id"));
    const p = db.row("SELECT location, home_unit FROM patients WHERE id=?", String(pid));
    if (p == null) return;
    const loc = Ui.nz(p.get("location")), to = m.get("to_unit");
    const note = "Taken over by " + to + " unit (" + Ui.nz(m.get("reason")) + "), accepted by " + Chat.myName(c, db);
    if (Db.isWardUnit(loc)) db.addEvent(pid, Dates.todayIso(), Dates.now(), Db.TRANSFER, loc, to, note);
    else db.addEvent(pid, Dates.todayIso(), Dates.now(), Db.UNIT_CHANGE, Ui.nz(p.get("home_unit")), to, note);
  }

  static cancel(db, moveId) {
    db.delete(UnitMoves.TABLE, Long.parseLong(moveId));
  }

  /** The request dialog on the patient page. */
  static requestDialog(a, db, p, toUnit, done) {
    const home = Ui.nz(p.get("home_unit"));
    const units = [];
    for (const u of Db.WARD_UNITS) if (!u.equals(home)) units.add(u);
    const vals = units.slice();
    const labels = new Array(vals.length).fill(null);
    for (let i = 0; i < vals.length; i++) labels[i] = vals[i] + " unit";
    const f = new Form(a);
    f.heading("Now under " + (home.isEmpty() ? "no unit" : home + " unit") + ". The receiving unit's PGs or Assistant Professor must accept before the case moves.");
    f.choice("to", "Hand over to", labels, vals, toUnit != null && units.contains(toUnit) ? toUnit : vals[0], null);
    f.choice("reason", "Why", UnitMoves.REASONS, UnitMoves.REASONS, UnitMoves.REASONS[0], null);
    f.text("prev", "Earlier admission (IP number / date / unit)", "", Form.TEXT);
    f.multi("note", "Notes", "");
    Ui.formDialog(a, "Hand over to another unit", f, "Ask", {
      run: () => {
        const to = f.get("to");
        const moved = UnitMoves.request(a, db, p, to, f.get("reason"), f.get("prev").trim(), f.get("note").trim());
        Ui.toast(a, moved ? "Moved to " + to + " unit" : "Sent to " + to + " unit to accept");
        done.run();
        return true;
      }
    });
  }

  /** The banner on the patient page while a request is open. */
  static banner(a, db, m, done) {
    const to = Ui.nz(m.get("to_unit"));
    const card = Ui.card(a);
    const g = Ui.round(a, 0xFFEEF2FF, 18);
    g.setStroke(Ui.dp(a, 2), UnitMoves.COLOR);
    card.setBackground(g);
    card.addView(Ui.tv(a, "⏳ Waiting for " + to + " unit to accept this case", 15, 0xFF3730A3, true));
    card.addView(Ui.muted(a, "From " + Ui.nz(m.get("from_unit")) + " unit  ·  " + Ui.nz(m.get("reason"))
        + (Ui.nz(m.get("prev_adm")).isEmpty() ? "" : "\nEarlier admission: " + m.get("prev_adm"))
        + (Ui.nz(m.get("note")).isEmpty() ? "" : "\n" + m.get("note"))
        + "\nAsked by " + Ui.nz(m.get("by_name")) + "  ·  " + Chat.when(m.get("time"))));
    const b = [];
    if (UnitMoves.canAccept(a, db, to)) {
      b.add(Ui.button(a, "Accept", Ui.GREEN, {
        onClick: (v) => {
          UnitMoves.decide(a, db, m.get("id"), true);
          done.run();
        }
      }));
      b.add(Ui.outlineButton(a, "Not accept", Ui.RED, {
        onClick: (v) => {
          UnitMoves.decide(a, db, m.get("id"), false);
          done.run();
        }
      }));
    } else {
      b.add(Ui.outlineButton(a, "Cancel request", UnitMoves.COLOR, {
        onClick: (v) => {
          UnitMoves.cancel(db, m.get("id"));
          done.run();
        }
      }));
    }
    const br = Ui.buttonRow(a, b);
    card.addView(br);
    Ui.margins(br, 0, 8, 0, 0);
    return card;
  }

  /** Home card: cases other units ask this person's unit to take over. */
  static homeCard(a, db) {
    const w = UnitMoves.waitingForMe(a, db);
    if (w.isEmpty()) return null;
    const r = w.get(0);
    const more = w.size() > 1 ? "  ·  and " + (w.size() - 1) + " more" : "";
    const card = a.entryCard("UNIT HANDOVER · NEEDS YOUR OK", UnitMoves.COLOR, "🔀 " + Ui.nz(r.get("from_unit")) + " asks " + Ui.nz(r.get("to_unit")) + " to take over " + Ui.nz(r.get("name")),
        Ui.nz(r.get("reason")) + more + ". Tap to accept or not.", null, a.opener(PatientActivity, "id", r.get("patient_id")));
    const g = Ui.round(a, Ui.mix(UnitMoves.COLOR, Color.WHITE, 0.92), 18);
    g.setStroke(Ui.dp(a, 2), UnitMoves.COLOR);
    card.setBackground(g);
    return card;
  }
}
;
