/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Shows a stored document inside the app: images directly, PDFs page by page (web: the browser's own PDF viewer in a frame). */
class ViewerActivity extends Base {
  constructor() { super(); this.rel = null; this.pdf = false; }

  onCreate(b) {
    super.onCreate(b);
    this.rel = this.getIntent().getStringExtra("file");
    this.setTitle(Ui.nz(this.getIntent().getStringExtra("title")));
    this.headerColor(Ui.SLATE);
    const f = this.db.file(this.rel);
    this.subtitle = Store.kindLabel(this.rel) + "  ·  " + Store.sizeLabel(f.length());
    this.headerAction("Share", { onClick: (v) => { Store.share(this, this.rel, this.getTitle().toString()); } });
    // Web: no PdfRenderer; a PDF that is stored is shown by the browser's viewer (a frame), see renderPdf()
    this.pdf = this.rel.toLowerCase().endsWith(".pdf") && f.exists();
  }

  onDestroy() {
    super.onDestroy();
  }

  render() {
    if (this.rel.startsWith("faculty/") && (Store.locked(this.db) || !Cloud.canSeeFaculty(this))) {
      this.finish();
      return;
    }
    if (this.pdf) {
      this.renderPdf();
      return;
    }
    const page = Ui.v(this);
    if (Store.isImage(this.rel)) {
      const iv = new ImageView(this);
      iv.setImageBitmap(Ui.loadScaled(this.db.file(this.rel), 2000));
      iv.setAdjustViewBounds(true);
      iv.setOnClickListener({ onClick: (v) => { Store.openWith(this, this.rel); } });
      page.addView(iv, Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
      page.addView(this.openWithButton());
    } else {
      const c = Ui.card(this);
      c.addView(Ui.body(this, "This file can't be shown inside the app."));
      c.addView(this.openWithButton());
      page.addView(c);
    }
    this.setPage(page);
  }

  openWithButton() {
    const b = Ui.outlineButton(this, "Open in another app (zoom, print)", Ui.SLATE, {
      onClick: (v) => { Store.openWith(this, this.rel); }
    });
    const p = Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
    p.setMargins(Ui.dp(this, 14), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
    b.setLayoutParams(p);
    return b;
  }

  /** PDF pages: on the phone a recycling list of rendered pages; in the browser the browser's own PDF viewer in a frame. */
  renderPdf() {
    const wv = new WebView(this);
    wv.setBackgroundColor(0xFFE2E8F0);
    VFS.url(this.rel).then((u) => {
      if (u != null) wv.loadUrl(u);
      else Ui.toast(this, "This file can't be shown inside the app.");
    }, (e) => { Ui.toast(this, "This file can't be shown inside the app."); });
    const root = Ui.v(this);
    root.setBackgroundColor(Ui.BG);
    root.addView(this.header(), Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    root.addView(wv, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
    root.addView(this.openWithButton());
    this.setContentView(root);
  }
}
;
