'use strict';
/** VIP cases, kept up to date by the unit looking after them. */
class VipActivity extends Base {
  constructor() { super(); this.unit = "ALL"; this.showClosed = false; }

  static CONDITIONS = ["Stable", "Improving", "Serious", "Critical", "Discharged", "Expired"];
  static $clinit() {
    VipActivity.UNITS = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.FEVER, Db.CCB, Db.GERI, Db.RHEUM];
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("VIP cases");
    this.subtitle = "Updated by the concerned unit";
    this.headerColor(Ui.AMBER);
    this.headerAction("+ VIP", {
      onClick: (v) => { this.vipDialog(null); }
    });
  }

  /** In the shared database a unit's own faculty and PGs update its VIP cases; the HOD and Professors can update all. */
  canEdit(u) {
    if (!Cloud.active(this)) return true;
    const r = Cloud.role(this);
    if (Cloud.isManager(r) || r.equals("professor")) return true;
    const me = Cloud.myStaff(this);
    if (me <= 0) return false;
    const s = this.db.row("SELECT unit FROM staff WHERE id=?", String(me));
    return s != null && u.equals(s.get("unit"));
  }

  static color(c) {
    if ("Critical".equals(c) || "Expired".equals(c)) return Ui.RED;
    if ("Serious".equals(c)) return Ui.ORANGE;
    if ("Improving".equals(c) || "Discharged".equals(c)) return Ui.GREEN;
    return Ui.TEAL;
  }

  render() {
    const page = Ui.v(this);
    const active = this.db.num("SELECT COUNT(*) FROM vip_cases WHERE active='1'");
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Ui.AMBER), 20));
    hero.addView(Ui.statRow(this,
        this.white(String(active), "VIP inpatients"),
        this.white(String(this.db.num("SELECT COUNT(*) FROM vip_cases WHERE active='1' AND condition IN ('Serious','Critical')")), "Serious / critical"),
        this.white(String(this.db.num("SELECT COUNT(*) FROM vip_cases WHERE active='1' AND last_update LIKE ?", Dates.todayIso() + "%")), "Updated today")));
    page.addView(hero);

    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    const opts = [];
    opts.add("ALL");
    for (const u of VipActivity.UNITS) opts.add(u);
    for (const u of opts) {
      const n = u.equals("ALL") ? active : this.db.num("SELECT COUNT(*) FROM vip_cases WHERE active='1' AND unit=?", u);
      const c = Ui.chip(this, (u.equals("ALL") ? "All" : Db.shortName(u)) + (n > 0 ? "  " + n : ""), u.equals(this.unit), u.equals("ALL") ? Ui.AMBER : Ui.unitColor(u));
      c.setOnClickListener({
        onClick: (v) => { this.unit = u; this.render(); }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    const where = (this.showClosed ? "1=1" : "active='1'") + (this.unit.equals("ALL") ? "" : " AND unit='" + this.unit.split("'").join("") + "'");
    const rows = this.db.rows("SELECT * FROM vip_cases WHERE " + where
        + " ORDER BY active DESC, CASE condition WHEN 'Critical' THEN 0 WHEN 'Serious' THEN 1 ELSE 2 END, last_update DESC LIMIT 200");
    if (rows.isEmpty()) page.addView(this.emptyNote(this.showClosed ? "No VIP cases." : "No VIP inpatients now."));
    for (const r of rows) page.addView(this.vipCard(r));
    const t = Ui.outlineButton(this, this.showClosed ? "Hide discharged / closed" : "Show discharged / closed", Ui.SLATE, {
      onClick: (v) => { this.showClosed = !this.showClosed; this.render(); }
    });
    page.addView(t);
    Ui.margins(t, 14, 12, 14, 0);
    this.setPage(page);
  }

  vipCard(r) {
    const cond = Ui.nz(r.get("condition"));
    let sub = new StringBuilder();
    if (!r.get("vip_info").isEmpty()) sub.append("⭐ ").append(r.get("vip_info")).append('\n');
    const id = (r.get("age_sex").isEmpty() ? "" : r.get("age_sex") + "  ·  ") + (r.get("ip_no").isEmpty() ? "" : "IP " + r.get("ip_no") + "  ·  ")
        + (r.get("ward_bed").isEmpty() ? "" : r.get("ward_bed"));
    if (!id.trim().isEmpty()) sub.append(id.replaceAllRx("  ·  $", "")).append('\n');
    if (!r.get("diagnosis").isEmpty()) sub.append(r.get("diagnosis")).append('\n');
    const upd = Ui.nz(r.get("updates")).trim();
    if (!upd.isEmpty()) {
      const lines = upd.jsplit("\n");
      sub.append("Latest: ").append(lines[lines.length - 1]);
    }
    const card = this.entryCard(cond.isEmpty() ? "Stable" : cond, VipActivity.color(cond), r.get("patient"), sub.toString().trim(),
        Db.shortName(r.get("unit")), {
          onClick: (v) => { this.detail(r); }
        });
    if (!"1".equals(r.get("active"))) card.setAlpha(0.6);
    if (this.canEdit(r.get("unit")) && "1".equals(r.get("active"))) {
      const u = Ui.outlineButton(this, "+ Add update", Ui.AMBER, {
        onClick: (v) => { this.updateDialog(r); }
      });
      card.addView(u);
      Ui.margins(u, 0, 8, 0, 0);
    }
    return card;
  }

  detail(r) {
    const v = Ui.v(this);
    v.setPadding(Ui.dp(this, 20), Ui.dp(this, 8), Ui.dp(this, 20), 0);
    v.addView(Ui.kv(this, "Unit", Db.unitName(r.get("unit"))));
    v.addView(Ui.kv(this, "VIP details", r.get("vip_info")));
    v.addView(Ui.kv(this, "Diagnosis", r.get("diagnosis")));
    v.addView(Ui.kv(this, "Condition", r.get("condition")));
    v.addView(Ui.kv(this, "Ward / bed", r.get("ward_bed")));
    const h = Ui.tv(this, "Updates", 14, Ui.AMBER, true);
    h.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 4));
    v.addView(h);
    const upd = Ui.nz(r.get("updates")).trim();
    v.addView(Ui.body(this, upd.isEmpty() ? "No updates yet." : upd));
    const sv = new ScrollView(this);
    sv.addView(v);
    const b = new AlertDialog.Builder(this).setTitle(r.get("patient")).setView(sv)
        .setNegativeButton("Close", null);
    if (this.canEdit(r.get("unit"))) b.setPositiveButton("Edit", {
      onClick: (d, w) => { this.vipDialog(r); }
    });
    b.show();
  }

  me() {
    const n = Cloud.active(this) ? Cloud.prefs(this).getString("name", "") : "";
    return n.isEmpty() ? CallDutyActivity.myName(this) : n;
  }

  updateDialog(r) {
    const f = new Form(this);
    f.choice("condition", "Condition", VipActivity.CONDITIONS, VipActivity.CONDITIONS, Ui.nz(r.get("condition")).isEmpty() ? "Stable" : r.get("condition"), null);
    f.multi("note", "Update *", "");
    f.text("by", "Updated by", this.me(), Form.PLAIN);
    Ui.formDialog(this, "Update · " + r.get("patient"), f, "Save", {
      run: () => {
        if (!f.require("note", "Write the update")) return false;
        CallDutyActivity.rememberName(this, f.get("by"));
        const stamp = Alerts.now();
        const line = Alerts.show(stamp) + " · " + f.get("condition") + " · " + f.get("note") + (f.get("by").isEmpty() ? "" : " (" + f.get("by") + ")");
        const old = Ui.nz(r.get("updates")).trim();
        const cv = new ContentValues();
        cv.put("updates", old.isEmpty() ? line : old + "\n" + line);
        cv.put("condition", f.get("condition"));
        cv.put("last_update", stamp);
        if (f.get("condition").equals("Discharged") || f.get("condition").equals("Expired")) cv.put("active", "0");
        this.db.update("vip_cases", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  vipDialog(r) {
    const f = new Form(this);
    const u = r != null ? r.get("unit") : this.unit.equals("ALL") ? this.db.todaysUnit() : this.unit;
    f.choice("unit", "Unit", Db.shortNames(VipActivity.UNITS), VipActivity.UNITS, u, null);
    const names = [];
    for (const p of this.db.rows("SELECT name FROM patients WHERE status='IN' ORDER BY admit_date DESC LIMIT 400")) names.add(p.get("name"));
    f.suggest("patient", "Patient name *", r == null ? "" : r.get("patient"), names.slice());
    f.text("vip_info", "Who / reference (e.g. MLA, retired judge, staff relative)", r == null ? "" : r.get("vip_info"), Form.PLAIN);
    f.text("age_sex", "Age / sex", r == null ? "" : r.get("age_sex"), Form.PLAIN);
    f.text("ip_no", "IP number", r == null ? "" : r.get("ip_no"), Form.PLAIN);
    f.text("ward_bed", "Ward / bed", r == null ? "" : r.get("ward_bed"), Form.PLAIN);
    f.text("diagnosis", "Diagnosis", r == null ? "" : r.get("diagnosis"), Form.PLAIN);
    f.choice("condition", "Condition", VipActivity.CONDITIONS, VipActivity.CONDITIONS, r == null || r.get("condition").isEmpty() ? "Stable" : r.get("condition"), null);
    if (r == null) f.multi("note", "First update", "");
    if (r != null) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete VIP case?", r.get("patient"), "Delete", {
            run: () => { this.db.delete("vip_cases", Long.parseLong(r.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "Add VIP case" : "Edit VIP case", f, "Save", {
      run: () => {
        if (!f.require("patient", "Enter the patient's name")) return false;
        if (!this.canEdit(f.get("unit"))) {
          Ui.toast(this, "Only " + Db.shortName(f.get("unit")) + " unit staff, Professors and the HOD can update its VIP cases");
          return false;
        }
        const cv = new ContentValues();
        for (const k of ["unit", "patient", "vip_info", "age_sex", "ip_no", "ward_bed", "diagnosis", "condition"]) cv.put(k, f.get(k));
        // link to the admitted patient and fill what was left blank
        const p = this.db.row("SELECT * FROM patients WHERE status='IN' AND name=? ORDER BY id DESC LIMIT 1", f.get("patient"));
        if (p != null) {
          cv.put("patient_id", p.get("id"));
          if (f.get("ip_no").isEmpty()) cv.put("ip_no", p.get("ip_no"));
          if (f.get("age_sex").isEmpty()) cv.put("age_sex", (p.get("age").isEmpty() ? "" : p.get("age") + " / ") + p.get("sex"));
          if (f.get("diagnosis").isEmpty()) cv.put("diagnosis", p.get("diagnosis"));
          if (f.get("ward_bed").isEmpty()) cv.put("ward_bed", Db.shortName(p.get("location")) + (p.get("bed").isEmpty() ? "" : " · bed " + p.get("bed")));
        }
        const c = f.get("condition");
        cv.put("active", c.equals("Discharged") || c.equals("Expired") ? "0" : "1");
        cv.put("last_update", Alerts.now());
        if (r == null) {
          cv.put("added", Dates.todayIso());
          if (!f.get("note").isEmpty()) cv.put("updates", Alerts.show(Alerts.now()) + " · " + c + " · " + f.get("note") + " (" + this.me() + ")");
          this.db.insert("vip_cases", cv);
        } else this.db.update("vip_cases", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  white(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    const n = Ui.tv(this, v, 22, 0xFFFFFFFF, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 11, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    return l;
  }
}
;
